-- Modelo de referencia de la huella del esquema (eng/huella/regenerar_huella.py).
-- Esquema sin datos de bazar3 del 19/11/2026, que reproduce HuellaEsquema.json
-- con los scripts de modelo_referencia_scripts.txt. Normalizado para que lo
-- carguen MariaDB 10 y MySQL 8 (sin NO_AUTO_CREATE_USER ni uca1400). No editar a mano.
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS=0;
SET SQL_MODE="NO_AUTO_VALUE_ON_ZERO";


DROP TABLE IF EXISTS `bak_20261030_traducciones_764`;
CREATE TABLE `bak_20261030_traducciones_764` (
  `ID_TRAD` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `CLAVE_TRAD` varchar(255) NOT NULL,
  `IDIOMA_TRAD` varchar(20) NOT NULL,
  `TEXTO_TRAD` text NOT NULL,
  `CONTEXTO_TRAD` varchar(500) DEFAULT NULL,
  `ESACTIVO_TRAD` varchar(1) NOT NULL DEFAULT 'S',
  `ESDESCARGADA_TRAD` varchar(1) NOT NULL DEFAULT 'N',
  `INSTANTE_ALTA` datetime NOT NULL DEFAULT current_timestamp(),
  `USUARIO_ALTA` varchar(50) NOT NULL,
  `INSTANTE_MODIF` datetime DEFAULT NULL,
  `USUARIO_MODIF` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`ID_TRAD`),
  UNIQUE KEY `UQ_TRAD_CLAVE_IDIOMA` (`CLAVE_TRAD`,`IDIOMA_TRAD`),
  KEY `IDX_TRAD_DESCARGADA_IDIOMA` (`ESDESCARGADA_TRAD`,`IDIOMA_TRAD`),
  KEY `IDX_TRAD_IDIOMA_ACTIVO` (`IDIOMA_TRAD`,`ESACTIVO_TRAD`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `bak_familias_padre_462`;
CREATE TABLE `bak_familias_padre_462` (
  `CODIGO_FAM_FAM` varchar(20) NOT NULL,
  `CODIGO_PADRE_FAM` varchar(20) DEFAULT NULL,
  `CODIGO_RECUPERADO_FAM` varchar(20) NOT NULL,
  `ESAPLICADO_FAM` varchar(1) NOT NULL DEFAULT 'N',
  PRIMARY KEY (`CODIGO_FAM_FAM`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `bak_fza_articulos_691`;
CREATE TABLE `bak_fza_articulos_691` (
  `CODIGO_ART_ART` varchar(50) NOT NULL,
  `VALOR_REFERENCIA_PRECIO_ART` decimal(19,6) NOT NULL DEFAULT 1.000000,
  `UNIDAD_REFERENCIA_PRECIO_ART` varchar(3) DEFAULT NULL,
  `ESPRECIO_UNIDAD_ART` varchar(1) NOT NULL DEFAULT 'N',
  `ESPRECIO_UNIDAD_TICKET_ART` varchar(1) NOT NULL DEFAULT 'N',
  PRIMARY KEY (`CODIGO_ART_ART`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `bak_fza_articulos_skus_691`;
CREATE TABLE `bak_fza_articulos_skus_691` (
  `CODIGO_UNIDAD_SKU` varchar(50) NOT NULL,
  `VALOR_CONTENIDO_NETO_SKU` decimal(19,6) DEFAULT NULL,
  `UNIDAD_CONTENIDO_NETO_SKU` varchar(3) DEFAULT NULL,
  PRIMARY KEY (`CODIGO_UNIDAD_SKU`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_albaranes`;
CREATE TABLE `fza_albaranes` (
  `NUMERO_ALB` varchar(20) NOT NULL,
  `SERIE_ALB` varchar(20) NOT NULL,
  `FECHA_ALB` date DEFAULT NULL,
  `INSTANTE_MOVIMIENTO_ALB` datetime DEFAULT NULL COMMENT 'Instante efectivo del movimiento de stock',
  `ESCONSOLIDADO_ALB` varchar(1) DEFAULT 'N',
  `ESTADO_ALB` varchar(20) DEFAULT 'ABIERTO' COMMENT 'ABIERTO, FACTURADO, CANCELADO',
  `NUMERO_PED_ALB` varchar(20) DEFAULT NULL COMMENT 'FK lógica a fza_pedidos.NUMERO_PED',
  `SERIE_PED_ALB` varchar(20) DEFAULT NULL COMMENT 'FK lógica a fza_pedidos.SERIE_PED',
  `NUMERO_FAC_ALB` varchar(20) DEFAULT NULL COMMENT 'FK lógica a fza_facturas.NUMERO_FAC (cuando se factura)',
  `SERIE_FAC_ALB` varchar(20) DEFAULT NULL COMMENT 'FK lógica a fza_facturas.SERIE_FAC',
  `CODIGO_EMP_ALB` varchar(8) DEFAULT NULL,
  `CODIGO_ALM_ALB` varchar(10) DEFAULT NULL COMMENT 'Almacen de salida de la mercancia',
  `RAZON_SOCIAL_EMPRESA_ALB` varchar(200) DEFAULT NULL,
  `NIF_EMPRESA_ALB` varchar(50) DEFAULT NULL,
  `MOVIL_EMPRESA_ALB` varchar(40) DEFAULT NULL,
  `EMAIL_EMPRESA_ALB` varchar(200) DEFAULT NULL,
  `DIRECCION1_EMPRESA_ALB` varchar(200) DEFAULT NULL,
  `DIRECCION2_EMPRESA_ALB` varchar(200) DEFAULT NULL,
  `POBLACION_EMPRESA_ALB` varchar(200) DEFAULT NULL,
  `PROVINCIA_EMPRESA_ALB` varchar(200) DEFAULT NULL,
  `CODIGO_PAI_EMPRESA_ALB` varchar(3) DEFAULT '724',
  `NOMBRE_PAI_EMPRESA_ALB` varchar(150) DEFAULT 'España',
  `CODIGO_POSTAL_EMPRESA_ALB` varchar(15) DEFAULT NULL,
  `GRUPO_ZONA_IVA_EMPRESA_ALB` varchar(10) DEFAULT NULL,
  `ESRETENCIONES_EMPRESA_ALB` varchar(1) DEFAULT 'N' COMMENT 'S o N si la empresa aplica retenciones como autónomos',
  `ESREGIMENESPECIALAGRICOLA_EMPRESA_ALB` varchar(1) DEFAULT 'N' COMMENT 'S o N si la empresa tiene REAGP',
  `CODIGO_CLI_ALB` varchar(20) DEFAULT NULL,
  `RAZON_SOCIAL_CLIENTE_ALB` varchar(200) DEFAULT NULL,
  `NIF_CLIENTE_ALB` varchar(50) DEFAULT NULL,
  `MOVIL_CLIENTE_ALB` varchar(40) DEFAULT NULL,
  `EMAIL_CLIENTE_ALB` varchar(200) DEFAULT NULL,
  `DIRECCION1_CLIENTE_ALB` varchar(200) DEFAULT NULL,
  `DIRECCION2_CLIENTE_ALB` varchar(200) DEFAULT NULL,
  `POBLACION_CLIENTE_ALB` varchar(200) DEFAULT NULL,
  `PROVINCIA_CLIENTE_ALB` varchar(200) DEFAULT NULL,
  `CODIGO_POSTAL_CLIENTE_ALB` varchar(15) DEFAULT NULL,
  `CODIGO_PAI_CLIENTE_ALB` varchar(3) DEFAULT '724',
  `NOMBRE_PAI_CLIENTE_ALB` varchar(150) DEFAULT 'España',
  `NOMBRE_CLI_ENVIO_ALB` varchar(200) DEFAULT NULL COMMENT 'Datos de envío (si difieren del cliente fiscal)',
  `MOVIL_CLIENTE_ENVIO_ALB` varchar(40) DEFAULT NULL,
  `DIRECCION1_CLIENTE_ENVIO_ALB` varchar(200) DEFAULT NULL,
  `DIRECCION2_CLIENTE_ENVIO_ALB` varchar(200) DEFAULT NULL,
  `POBLACION_CLIENTE_ENVIO_ALB` varchar(200) DEFAULT NULL,
  `PROVINCIA_CLIENTE_ENVIO_ALB` varchar(200) DEFAULT NULL,
  `CODIGO_POSTAL_CLIENTE_ENVIO_ALB` varchar(15) DEFAULT NULL,
  `CODIGO_PAI_CLIENTE_ENVIO_ALB` varchar(3) DEFAULT '724',
  `NOMBRE_PAI_CLIENTE_ENVIO_ALB` varchar(150) DEFAULT 'España',
  `TRANSPORTISTA_ALB` varchar(200) DEFAULT NULL,
  `CODIGO_IVA_ALB` varchar(20) DEFAULT NULL,
  `ESIVA_RECARGO_CLIENTE_ALB` varchar(1) DEFAULT 'N',
  `ESIVA_EXENTO_CLIENTE_ALB` varchar(1) DEFAULT 'N',
  `ESINTRACOMUNITARIO_CLIENTE_ALB` varchar(1) DEFAULT 'N',
  `ESRETENCIONES_CLIENTE_ALB` varchar(1) DEFAULT 'N' COMMENT 'S o N si el cliente aplica retenciones',
  `ESREGIMENESPECIALAGRICOLA_CLIENTE_ALB` varchar(1) DEFAULT 'N' COMMENT 'S o N si el cliente tiene REAGP',
  `TARIFA_ARTICULO_CLIENTE_ALB` varchar(10) DEFAULT NULL,
  `ESIMP_INCL_TARIFA_CLIENTE_ALB` varchar(1) DEFAULT 'S',
  `PORCENTAJE_IVAN_ALB` decimal(19,6) DEFAULT NULL,
  `TOTAL_IVAN_ALB` decimal(18,6) DEFAULT NULL,
  `PORCENTAJE_IVAR_ALB` decimal(19,6) DEFAULT NULL,
  `TOTAL_IVAR_ALB` decimal(18,6) DEFAULT NULL,
  `PORCENTAJE_IVAS_ALB` decimal(19,6) DEFAULT NULL,
  `TOTAL_IVAS_ALB` decimal(18,6) DEFAULT NULL,
  `PORCENTAJE_IVAE_ALB` decimal(19,6) DEFAULT NULL,
  `TOTAL_IVAE_ALB` decimal(18,6) DEFAULT NULL,
  `TOTAL_BASES_ALB` decimal(18,6) DEFAULT NULL,
  `TOTAL_IMPUESTOS_ALB` decimal(18,6) DEFAULT NULL,
  `PORCENTAJE_RETENCION_ALB` decimal(19,6) DEFAULT 0.000000,
  `TOTAL_RETENCION_ALB` decimal(18,6) DEFAULT 0.000000,
  `TOTAL_LIQUIDO_ALB` decimal(18,6) DEFAULT NULL,
  `FORMA_PAGO_ALB` varchar(200) DEFAULT NULL,
  `CODIGO_VENDEDOR_ALB` varchar(20) DEFAULT NULL COMMENT 'Vendedor del albaran (fza_empleados)',
  `CONTADOR_LINEAS_ALB` varchar(8) DEFAULT NULL,
  `COMENTARIOS_ALB` varchar(1000) DEFAULT '',
  `OBSERVACIONES_ALB` varchar(2000) DEFAULT '',
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  `ESAPLICA_RE_ZONA_IVA_ALB` varchar(1) DEFAULT NULL,
  `PORCENTAJE_REN_ALB` decimal(19,6) DEFAULT NULL,
  `TOTAL_REN_ALB` decimal(19,6) DEFAULT NULL,
  `PORCENTAJE_RER_ALB` decimal(19,6) DEFAULT NULL,
  `TOTAL_RER_ALB` decimal(19,6) DEFAULT NULL,
  `PORCENTAJE_RES_ALB` decimal(19,6) DEFAULT NULL,
  `TOTAL_RES_ALB` decimal(19,6) DEFAULT NULL,
  `PORCENTAJE_REE_ALB` decimal(19,6) DEFAULT NULL,
  `TOTAL_REE_ALB` decimal(19,6) DEFAULT NULL,
  `TOTAL_BASEI_IVAN_ALB` decimal(19,6) DEFAULT NULL,
  `TOTAL_BASEI_IVAR_ALB` decimal(19,6) DEFAULT NULL,
  `TOTAL_BASEI_IVAS_ALB` decimal(19,6) DEFAULT NULL,
  `TOTAL_BASEI_IVAE_ALB` decimal(19,6) DEFAULT NULL,
  `PORCENTAJE_DTO_COMERCIAL_ALB` decimal(19,6) DEFAULT 0.000000,
  `TOTAL_DTO_COMERCIAL_ALB` decimal(19,6) DEFAULT 0.000000,
  `PORCENTAJE_DTO_FINANCIERO_ALB` decimal(19,6) DEFAULT 0.000000,
  `TOTAL_DTO_FINANCIERO_ALB` decimal(19,6) DEFAULT 0.000000,
  PRIMARY KEY (`NUMERO_ALB`,`SERIE_ALB`),
  KEY `IDX_ALB_ALMACEN` (`CODIGO_ALM_ALB`),
  KEY `IDX_ALB_CLIENTE_FECHA` (`CODIGO_CLI_ALB`,`FECHA_ALB`),
  KEY `IDX_ALB_EMPRESA` (`CODIGO_EMP_ALB`),
  KEY `IDX_ALB_EMP_INSTANTE` (`CODIGO_EMP_ALB`,`INSTANTE_ALTA`),
  KEY `IDX_ALB_ESTADO` (`ESTADO_ALB`),
  KEY `IDX_ALB_FACTURA` (`SERIE_FAC_ALB`,`NUMERO_FAC_ALB`),
  KEY `IDX_ALB_PEDIDO` (`SERIE_PED_ALB`,`NUMERO_PED_ALB`),
  KEY `IDX_ALB_VENDEDOR` (`CODIGO_VENDEDOR_ALB`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_albaranes_celdas`;
CREATE TABLE `fza_albaranes_celdas` (
  `SERIE_ALB_ALBCEL` varchar(20) NOT NULL,
  `NUMERO_ALB_ALBCEL` varchar(20) NOT NULL,
  `LINEA_ALBCEL` int(11) NOT NULL,
  `ID_FILA_ALBCEL` int(11) NOT NULL,
