  `ESTADO_ALBC` varchar(20) DEFAULT 'ABIERTO' COMMENT 'ABIERTO, FACTURADO, CANCELADO',
  `NUMERO_PED_ALBC` varchar(20) DEFAULT NULL COMMENT 'FK logica a fza_pedidos_compra',
  `SERIE_PED_ALBC` varchar(20) DEFAULT NULL,
  `NUMERO_FAC_ALBC` varchar(20) DEFAULT NULL COMMENT 'FK logica a fza_facturas_compras',
