  `CODIGO_POSTAL_EMPRESA_ALBC` varchar(15) DEFAULT NULL,
  `CODIGO_PRV_ALBC` varchar(20) DEFAULT NULL COMMENT 'FK logica a fza_proveedores',
  `RAZON_SOCIAL_PRV_ALBC` varchar(200) DEFAULT NULL,
  `NIF_PRV_ALBC` varchar(50) DEFAULT NULL,
  `MOVIL_PRV_ALBC` varchar(40) DEFAULT NULL,
  `EMAIL_PRV_ALBC` varchar(200) DEFAULT NULL,
  `DIRECCION1_PRV_ALBC` varchar(200) DEFAULT NULL,
  `DIRECCION2_PRV_ALBC` varchar(200) DEFAULT NULL,
  `POBLACION_PRV_ALBC` varchar(200) DEFAULT NULL,
  `PROVINCIA_PRV_ALBC` varchar(200) DEFAULT NULL,
  `CODIGO_PAI_PRV_ALBC` varchar(3) DEFAULT '724',
  `NOMBRE_PAI_PRV_ALBC` varchar(150) DEFAULT 'Espana',
  `CODIGO_POSTAL_PRV_ALBC` varchar(15) DEFAULT NULL,
  `REF_PROVEEDOR_ALBC` varchar(50) DEFAULT NULL COMMENT 'Numero de albaran segun el proveedor',
  `CODIGO_ALM_ALBC` varchar(10) DEFAULT NULL COMMENT 'Almacen destino de la entrada de mercancia',
  `TRANSPORTISTA_ALBC` varchar(200) DEFAULT NULL,
  `CODIGO_IVA_ALBC` varchar(20) DEFAULT NULL,
  `ESIVA_RECARGO_COMPRAS_ALBC` varchar(1) DEFAULT 'N',
  `ESIVA_EXENTO_INTRACOMUNITARIO_ALBC` varchar(1) NOT NULL DEFAULT 'N' COMMENT 'S = IVA exento por proveedor intracomunitario',
