  `PORCENTAJE_REN_ALBC` decimal(19,6) DEFAULT NULL,
  `TOTAL_REN_ALBC` decimal(18,6) DEFAULT NULL,
  `PORCENTAJE_IVAR_ALBC` decimal(19,6) DEFAULT NULL,
  `TOTAL_BASEI_IVAR_ALBC` decimal(18,6) DEFAULT NULL,
  `TOTAL_IVAR_ALBC` decimal(18,6) DEFAULT NULL,
  `PORCENTAJE_RER_ALBC` decimal(19,6) DEFAULT NULL,
  `TOTAL_RER_ALBC` decimal(18,6) DEFAULT NULL,
  `PORCENTAJE_IVAS_ALBC` decimal(19,6) DEFAULT NULL,
  `TOTAL_BASEI_IVAS_ALBC` decimal(18,6) DEFAULT NULL,
  `TOTAL_IVAS_ALBC` decimal(18,6) DEFAULT NULL,
  `PORCENTAJE_RES_ALBC` decimal(19,6) DEFAULT NULL,
  `TOTAL_RES_ALBC` decimal(18,6) DEFAULT NULL,
  `PORCENTAJE_IVAE_ALBC` decimal(19,6) DEFAULT NULL,
  `TOTAL_BASEI_IVAE_ALBC` decimal(18,6) DEFAULT NULL,
  `TOTAL_IVAE_ALBC` decimal(18,6) DEFAULT NULL,
  `PORCENTAJE_REE_ALBC` decimal(19,6) DEFAULT NULL,
  `TOTAL_REE_ALBC` decimal(18,6) DEFAULT NULL,
  `TOTAL_BASES_ALBC` decimal(18,6) DEFAULT NULL,
  `TOTAL_IMPUESTOS_ALBC` decimal(18,6) DEFAULT NULL,
  `PORCENTAJE_RETENCION_ALBC` decimal(19,6) DEFAULT NULL,
  `TOTAL_RETENCION_ALBC` decimal(18,6) DEFAULT NULL,
  `TOTAL_BRUTO_ALBC` decimal(18,6) DEFAULT 0.000000,
  `PORCENTAJE_DTO_COMERCIAL_ALBC` decimal(19,6) DEFAULT 0.000000,
  `TOTAL_DTO_COMERCIAL_ALBC` decimal(18,6) DEFAULT 0.000000,
  `PORCENTAJE_DTO_FINANCIERO_ALBC` decimal(19,6) DEFAULT 0.000000,
  `TOTAL_DTO_FINANCIERO_ALBC` decimal(18,6) DEFAULT 0.000000,
  `TOTAL_LIQUIDO_ALBC` decimal(18,6) DEFAULT NULL,
  `FORMA_PAGO_ALBC` varchar(200) DEFAULT NULL,
  `ID_PV_TEMPORADA_ALBC` int(11) DEFAULT NULL COMMENT 'FK logica fza_propiedades_valores.ID_PV_ARTPROP con ID_PROP_PV=TEMPORADA. Procede de ocalbpro.Temporada en la migracion.',
  `CONTADOR_LINEAS_ALBC` varchar(8) DEFAULT NULL,
  `COMENTARIOS_ALBC` varchar(1000) DEFAULT '',
  `OBSERVACIONES_ALBC` varchar(2000) DEFAULT '',
  `ESPIVOTE_HORIZONTAL_ALBC` varchar(1) NOT NULL DEFAULT 'N',
  `CODIGO_TAR_ALBC` varchar(20) DEFAULT NULL,
  `ESDEPOSITO_ALBC` varchar(1) NOT NULL DEFAULT 'N' COMMENT 'S = albaran de compra en deposito (informativo)',
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  `LOTE_REPOSICION_ALBC` varchar(50) DEFAULT NULL,
