  KEY `IDX_ALBC_EMP_INSTANTE` (`CODIGO_EMP_ALBC`,`INSTANTE_ALTA`),
  KEY `IDX_ALBC_ESTADO` (`ESTADO_ALBC`),
  KEY `IDX_ALBC_PEDIDO` (`SERIE_PED_ALBC`,`NUMERO_PED_ALBC`),
  KEY `IDX_ALBC_PROVEEDOR_FECHA` (`CODIGO_PRV_ALBC`,`FECHA_ALBC`),
  KEY `IDX_ALBC_TEMPORADA` (`ID_PV_TEMPORADA_ALBC`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_albaranes_compra_celdas`;
