  `DESCRIPCION_ARTICULO_ALBCLIN` varchar(100) DEFAULT NULL,
  `TIPO_CANTIDAD_ARTICULO_ALBCLIN` varchar(20) DEFAULT 'Uds',
  `CANTIDAD_ALBCLIN` decimal(19,6) DEFAULT 1.000000,
