  `PRECIO_COMPRA_CIVA_ARTICULO_ALBCLIN` decimal(19,6) DEFAULT 0.000000,
  `TOTAL_ALBCLIN` decimal(19,6) DEFAULT 0.000000,
  `CODIGO_ALMACEN_ALBCLIN` varchar(10) DEFAULT NULL,
  `LOTE_ALBCLIN` varchar(50) DEFAULT NULL,
  `FECHA_CADUCIDAD_ALBCLIN` date DEFAULT NULL,
  `DESCRIPCION_VARIACION_ALBCLIN` varchar(200) DEFAULT NULL,
  `ESFACTURADA_ALBCLIN` varchar(1) DEFAULT 'N',
  `NUMERO_FAC_ALBCLIN` varchar(20) DEFAULT NULL,
  `SERIE_FAC_ALBCLIN` varchar(20) DEFAULT NULL,
  `LINEA_FAC_ALBCLIN` varchar(4) DEFAULT NULL,
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  `ATTR1_VALOR_ALBCLIN` varchar(100) NOT NULL DEFAULT '',
  `ATTR1_NOMBRE_ALBCLIN` varchar(100) NOT NULL DEFAULT '',
  `ATTR2_VALOR_ALBCLIN` varchar(100) NOT NULL DEFAULT '',
  `ATTR2_NOMBRE_ALBCLIN` varchar(100) NOT NULL DEFAULT '',
  `ATTR3_VALOR_ALBCLIN` varchar(100) NOT NULL DEFAULT '',
  `ATTR3_NOMBRE_ALBCLIN` varchar(100) NOT NULL DEFAULT '',
  `ATTR4_VALOR_ALBCLIN` varchar(100) NOT NULL DEFAULT '',
  `ATTR4_NOMBRE_ALBCLIN` varchar(100) NOT NULL DEFAULT '',
  `ATTR5_VALOR_ALBCLIN` varchar(100) NOT NULL DEFAULT '',
  `ATTR5_NOMBRE_ALBCLIN` varchar(100) NOT NULL DEFAULT '',
  `NUM_ATRIBUTOS_ALBCLIN` int(11) NOT NULL DEFAULT 0 COMMENT 'Atributos requeridos del articulo',
  `PORCENTAJE_DTO_ALBCLIN` decimal(7,4) DEFAULT 0.0000,
  PRIMARY KEY (`NUMERO_ALBC_ALBCLIN`,`SERIE_ALBC_ALBCLIN`,`LINEA_ALBCLIN`),
  KEY `IDX_ALBCLIN_ARTICULO` (`CODIGO_ART_ALBCLIN`),
  KEY `IDX_ALBCLIN_PEDIDO` (`SERIE_PEDC_ALBCLIN`,`NUMERO_PEDC_ALBCLIN`,`LINEA_PEDC_ALBCLIN`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_albaranes_lineas`;
CREATE TABLE `fza_albaranes_lineas` (
  `NUMERO_ALB_ALBLIN` varchar(20) NOT NULL,
  `SERIE_ALB_ALBLIN` varchar(20) NOT NULL,
  `LINEA_ALBLIN` varchar(4) NOT NULL,
  `NUMERO_PED_ALBLIN` varchar(20) DEFAULT NULL,
  `SERIE_PED_ALBLIN` varchar(20) DEFAULT NULL,
  `LINEA_PED_ALBLIN` varchar(4) DEFAULT NULL COMMENT 'Línea de origen en fza_pedidos_lineas',
  `CODIGO_ART_ALBLIN` varchar(20) DEFAULT NULL,
  `CODIGO_FAM_ALBLIN` varchar(20) DEFAULT NULL,
  `NOMBRE_FAM_ALBLIN` varchar(200) DEFAULT NULL,
  `DESCRIPCION_ARTICULO_ALBLIN` varchar(100) DEFAULT NULL,
  `TIPO_CANTIDAD_ARTICULO_ALBLIN` varchar(20) DEFAULT 'Uds',
  `CANTIDAD_ALBLIN` decimal(19,6) DEFAULT 1.000000,
  `CODIGO_TAR_ALBLIN` varchar(10) DEFAULT NULL,
  `ESIMP_INCL_TARIFA_ALBLIN` varchar(1) DEFAULT 'S',
  `TIPO_IVA_ARTICULO_ALBLIN` varchar(2) DEFAULT 'N',
  `PORCENTAJE_IVA_ALBLIN` decimal(19,6) DEFAULT 0.000000,
  `PRECIO_VENTA_SIVA_ARTICULO_ALBLIN` decimal(19,6) DEFAULT 0.000000,
  `PRECIO_VENTA_CIVA_ARTICULO_ALBLIN` decimal(19,6) DEFAULT 0.000000,
  `TOTAL_ALBLIN` decimal(19,6) DEFAULT 0.000000,
  `CODIGO_ALMACEN_ALBLIN` varchar(10) DEFAULT NULL,
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  `ESFACTURADA_ALBLIN` varchar(1) DEFAULT 'N',
  `NUMERO_FAC_ALBLIN` varchar(20) DEFAULT NULL,
  `SERIE_FAC_ALBLIN` varchar(20) DEFAULT NULL,
  `LINEA_FAC_ALBLIN` varchar(4) DEFAULT NULL,
  `CODIGO_UNIDAD_ALBLIN` varchar(50) DEFAULT NULL,
  `LOTE_ALBLIN` varchar(50) DEFAULT NULL,
  `FECHA_CADUCIDAD_ALBLIN` date DEFAULT NULL,
  `DESCRIPCION_VARIACION_ALBLIN` varchar(200) DEFAULT NULL,
  `ATTR1_VALOR_ALBLIN` varchar(100) NOT NULL DEFAULT '',
  `ATTR1_NOMBRE_ALBLIN` varchar(100) NOT NULL DEFAULT '',
  `ATTR2_VALOR_ALBLIN` varchar(100) NOT NULL DEFAULT '',
  `ATTR2_NOMBRE_ALBLIN` varchar(100) NOT NULL DEFAULT '',
  `ATTR3_VALOR_ALBLIN` varchar(100) NOT NULL DEFAULT '',
  `ATTR3_NOMBRE_ALBLIN` varchar(100) NOT NULL DEFAULT '',
  `ATTR4_VALOR_ALBLIN` varchar(100) NOT NULL DEFAULT '',
  `ATTR4_NOMBRE_ALBLIN` varchar(100) NOT NULL DEFAULT '',
  `ATTR5_VALOR_ALBLIN` varchar(100) NOT NULL DEFAULT '',
  `ATTR5_NOMBRE_ALBLIN` varchar(100) NOT NULL DEFAULT '',
  `NUM_ATRIBUTOS_ALBLIN` int(11) NOT NULL DEFAULT 0 COMMENT 'Atributos requeridos del articulo',
  `ID_AC_PIVOT_ALBLIN` int(11) NOT NULL DEFAULT 0 COMMENT 'Conjunto pivotado en tallas horizontal (0 = sin pivote)',
  `PRECIO_SALIDA_ALBLIN` decimal(19,6) DEFAULT NULL,
  `PORCENTAJE_DTO_ALBLIN` decimal(19,6) DEFAULT 0.000000,
  `PRECIO_DTO_ALBLIN` decimal(19,6) DEFAULT 0.000000,
  PRIMARY KEY (`NUMERO_ALB_ALBLIN`,`SERIE_ALB_ALBLIN`,`LINEA_ALBLIN`),
  KEY `IDX_ALBLIN_ARTICULO` (`CODIGO_ART_ALBLIN`),
  KEY `IDX_ALBLIN_FAC` (`SERIE_FAC_ALBLIN`,`NUMERO_FAC_ALBLIN`),
  KEY `IDX_ALBLIN_PEDIDO` (`SERIE_PED_ALBLIN`,`NUMERO_PED_ALBLIN`,`LINEA_PED_ALBLIN`),
  KEY `IDX_ALBLIN_UNIDAD` (`CODIGO_UNIDAD_ALBLIN`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_almacenes`;
CREATE TABLE `fza_almacenes` (
  `CODIGO_ALM_ALM` varchar(10) NOT NULL,
  `CODIGO_EMP_ALM` varchar(20) NOT NULL,
  `ESACTIVO_ALM` varchar(1) DEFAULT 'S',
  `NOMBRE_ALM_ALM` varchar(100) DEFAULT NULL,
  `CODIGO_PADRE_ALM` varchar(10) DEFAULT NULL,
  `ESFISICO_ALM` varchar(1) DEFAULT 'S',
  `ESWEB_ALM` varchar(1) NOT NULL DEFAULT 'N',
  `TIPO_USO_ALM` varchar(20) DEFAULT 'ESTANDAR',
  `ESCOMPARTIDO_ALM` varchar(1) NOT NULL DEFAULT 'N',
  `DIRECCION_ALM` varchar(200) DEFAULT NULL,
  `POBLACION_ALM` varchar(200) DEFAULT NULL,
  `CODIGO_POSTAL_ALM` varchar(10) DEFAULT NULL,
  `TELEFONO_ALM` varchar(50) DEFAULT NULL,
  `EMAIL_ALM` varchar(100) DEFAULT NULL,
  `CODIGO_CLI_ALM` varchar(20) DEFAULT NULL,
  `DESTINO_ACTUAL_ALM` varchar(10) DEFAULT NULL COMMENT 'Hacia dónde va la mercancía (Pendiente de recibir)',
  `ORIGEN_ACTUAL_ALM` varchar(10) DEFAULT NULL COMMENT 'De dónde viene la mercancía cargada',
  `ORDEN_ALM` int(11) DEFAULT NULL,
  `ORDEN_DISTRIBUCION_ALM` int(11) DEFAULT NULL COMMENT 'Prioridad al distribuir: 1 = primero; NULL = no recibe',
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  `PROVINCIA_ALM` varchar(200) DEFAULT NULL,
  PRIMARY KEY (`CODIGO_ALM_ALM`),
  KEY `IDX_ALMACENES_EMP` (`CODIGO_EMP_ALM`,`ESACTIVO_ALM`),
  KEY `IDX_ALM_EMP_WEB` (`CODIGO_EMP_ALM`,`ESWEB_ALM`,`ESACTIVO_ALM`,`ESFISICO_ALM`,`TIPO_USO_ALM`),
  KEY `IDX_CLIENTE_ALM` (`CODIGO_CLI_ALM`),
  KEY `IDX_EMPRESA_ALM` (`CODIGO_EMP_ALM`),
  KEY `IDX_PADRE_ALM` (`CODIGO_PADRE_ALM`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_almacenes_cajas`;
CREATE TABLE `fza_almacenes_cajas` (
  `CODIGO_ALM_ALMCAJ` varchar(10) NOT NULL,
  `CODIGO_CAJA_ALMCAJ` varchar(10) NOT NULL,
  `DESCRIPCION_ALMCAJ` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`CODIGO_ALM_ALMCAJ`,`CODIGO_CAJA_ALMCAJ`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_almacenes_meteorologia`;
CREATE TABLE `fza_almacenes_meteorologia` (
  `CODIGO_EMP_ALMET` varchar(20) NOT NULL,
  `CODIGO_ALM_ALMET` varchar(20) NOT NULL,
  `FECHA_ALMET` date NOT NULL,
  `CIUDAD_ALMET` varchar(150) NOT NULL,
  `ZONA_HORARIA_ALMET` varchar(80) NOT NULL,
  `VALOR_LATITUD_ALMET` decimal(10,6) NOT NULL,
  `VALOR_LONGITUD_ALMET` decimal(10,6) NOT NULL,
  `VALOR_TEMPERATURA_ALMET` decimal(6,2) DEFAULT NULL,
  `VALOR_MINIMA_ALMET` decimal(6,2) DEFAULT NULL,
  `VALOR_MAXIMA_ALMET` decimal(6,2) DEFAULT NULL,
  `PORCENTAJE_NUBES_ALMET` decimal(5,2) DEFAULT NULL,
  `VALOR_LLUVIA_PREVISTA_ALMET` decimal(10,2) DEFAULT NULL,
  `CODIGO_TIEMPO_ALMET` int(11) DEFAULT NULL,
  `INSTANTE_CONSULTA_UTC_ALMET` datetime NOT NULL,
  `PROVEEDOR_ALMET` varchar(80) NOT NULL,
  `TIPO_DATO_ALMET` varchar(30) NOT NULL DEFAULT 'PREVISION_DIARIA',
  `RESPUESTA_JSON_ALMET` longtext NOT NULL,
  PRIMARY KEY (`CODIGO_EMP_ALMET`,`CODIGO_ALM_ALMET`,`FECHA_ALMET`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_almacenes_observaciones`;
CREATE TABLE `fza_almacenes_observaciones` (
  `CODIGO_EMP_ALOB` varchar(20) NOT NULL,
  `CODIGO_ALM_ALOB` varchar(20) NOT NULL,
  `FECHA_ALOB` date NOT NULL,
  `OBSERVACIONES_ALOB` text NOT NULL,
  `INSTANTE_ALTA` datetime NOT NULL,
  `USUARIO_ALTA` varchar(50) NOT NULL,
  `INSTANTE_MODIF` datetime DEFAULT NULL,
  `USUARIO_MODIF` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`CODIGO_EMP_ALOB`,`CODIGO_ALM_ALOB`,`FECHA_ALOB`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_articulos`;
CREATE TABLE `fza_articulos` (
  `CODIGO_ART_ART` varchar(20) NOT NULL,
  `ESACTIVO_ART` varchar(1) NOT NULL DEFAULT 'S',
  `ESWEB_ART` varchar(1) NOT NULL DEFAULT 'N',
  `TIPO_ART` varchar(10) NOT NULL DEFAULT 'ESTANDAR' COMMENT 'ESTANDAR=Físico (Control Stock), SERVICIO=Intangible (Sin Stock), KIT=Pack',
  `DESCRIPCION_ART` varchar(1000) NOT NULL,
  `CODIGO_FAM_ART` varchar(20) DEFAULT NULL,
  `TIPO_IVA_ART` varchar(2) NOT NULL,
  `ESACTIVO_FIJO_ART` varchar(1) DEFAULT 'N',
  `TIPO_CANTIDAD_ART` varchar(20) NOT NULL DEFAULT 'Uds',
  `ESVARIACION_ART` varchar(1) NOT NULL,
  `ESTRAZABLE_ART` varchar(1) NOT NULL DEFAULT 'N' COMMENT 'S=Pide Lote/Caducidad, N=No pide',
  `TIPO_TRAZABILIDAD_ART` varchar(10) NOT NULL DEFAULT 'NINGUNA',
  `ESCADUCIDAD_ART` varchar(1) NOT NULL DEFAULT 'N',
  `DIAS_AVISO_CADUCIDAD_ART` int(11) DEFAULT NULL,
  `MESES_GARANTIA_ART` int(11) DEFAULT NULL,
  `ORDEN_ART` int(11) DEFAULT NULL,
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  `TIPO_VARIACION_ART` varchar(20) DEFAULT NULL,
  `ESSERVICIO_REPARACION_ART` varchar(1) NOT NULL DEFAULT 'N',
  PRIMARY KEY (`CODIGO_ART_ART`),
  KEY `CODIGO` (`CODIGO_ART_ART`),
  KEY `IDX_ARTICULOS_FAMILIA` (`CODIGO_FAM_ART`),
  KEY `IDX_ARTICULOS_FAMILIA_STAT` (`CODIGO_FAM_ART`,`ESACTIVO_ART`),
  KEY `IDX_ART_ESWEB` (`ESWEB_ART`),
  KEY `TIPO_VARIACION_ART` (`TIPO_VARIACION_ART`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_articulos_atributos_basicos`;
CREATE TABLE `fza_articulos_atributos_basicos` (
  `CODIGO_ART_AAB` varchar(20) NOT NULL COMMENT 'FK lógica fza_articulos.CODIGO_ART_ART',
  `ID_AV_AAB` int(11) NOT NULL COMMENT 'FK lógica fza_atributos_valores.ID_AV',
  `ID_ATB_AAB` int(11) DEFAULT NULL COMMENT 'FK lógica fza_atributos_basicos.ID_ATB. NULL = bloqueo (sin básico).',
  `DESCRIPCION_AAB` varchar(255) DEFAULT NULL,
  `ORDEN_AAB` int(11) DEFAULT NULL COMMENT 'Orden del valor dentro del articulo; en tallas procede de ocarttal.Orden.',
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL DEFAULT 'SISTEMA',
  `USUARIO_MODIF` varchar(100) NOT NULL DEFAULT 'SISTEMA',
  PRIMARY KEY (`CODIGO_ART_AAB`,`ID_AV_AAB`),
  KEY `IDX_AAB_ATB` (`ID_ATB_AAB`),
  KEY `IDX_AAB_VAL` (`ID_AV_AAB`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_articulos_cambios_historico`;
CREATE TABLE `fza_articulos_cambios_historico` (
  `ID_ACH` bigint(20) NOT NULL AUTO_INCREMENT,
  `ID_OPERACION_ACH` char(36) NOT NULL,
  `ORDEN_ACH` int(11) NOT NULL,
  `TIPO_REGISTRO_ACH` varchar(10) NOT NULL,
  `TIPO_OPERACION_ACH` varchar(20) DEFAULT NULL,
  `ID_OPERACION_ORIGEN_ACH` char(36) DEFAULT NULL,
  `ESTADO_ACH` varchar(12) NOT NULL,
  `TIPO_OBJETO_ACH` varchar(10) DEFAULT NULL,
  `CODIGO_ORIGEN_ACH` varchar(100) DEFAULT NULL,
  `CODIGO_DESTINO_ACH` varchar(100) DEFAULT NULL,
  `TABLA_ACH` varchar(64) DEFAULT NULL,
  `ACCION_ACH` varchar(10) DEFAULT NULL,
  `CLAVE_ANTES_ACH` longtext DEFAULT NULL,
  `CLAVE_DESPUES_ACH` longtext DEFAULT NULL,
  `HASH_CLAVE_ANTES_ACH` char(64) DEFAULT NULL,
  `HASH_CLAVE_DESPUES_ACH` char(64) DEFAULT NULL,
  `DATOS_ANTES_ACH` longtext DEFAULT NULL,
  `DATOS_DESPUES_ACH` longtext DEFAULT NULL,
  `HASH_ANTES_ACH` char(64) DEFAULT NULL,
  `HASH_DESPUES_ACH` char(64) DEFAULT NULL,
  `FIRMA_ESQUEMA_ACH` char(64) DEFAULT NULL,
  `VERSION_FORMATO_ACH` smallint(5) unsigned NOT NULL DEFAULT 1,
  `CANTIDAD_FILAS_ACH` int(11) NOT NULL DEFAULT 0,
  `CANTIDAD_UNIDADES_ACH` int(11) NOT NULL DEFAULT 0,
  `DETALLE_ACH` varchar(500) DEFAULT NULL,
  `INSTANTE_ALTA` datetime NOT NULL,
  `USUARIO_ALTA` varchar(50) DEFAULT NULL,
  `INSTANTE_MODIF` datetime DEFAULT NULL,
  `USUARIO_MODIF` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`ID_ACH`),
  UNIQUE KEY `UQ_ACH_OPERACION_ORDEN` (`ID_OPERACION_ACH`,`ORDEN_ACH`),
  UNIQUE KEY `UQ_ACH_OPERACION_ORIGEN` (`ID_OPERACION_ORIGEN_ACH`),
  KEY `IDX_ACH_ESTADO_INSTANTE_ALTA` (`ESTADO_ACH`,`INSTANTE_ALTA`),
  KEY `IDX_ACH_TABLA_HASH_CLAVE_ANTES` (`TABLA_ACH`,`HASH_CLAVE_ANTES_ACH`),
  KEY `IDX_ACH_TABLA_HASH_CLAVE_DESPUES` (`TABLA_ACH`,`HASH_CLAVE_DESPUES_ACH`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_articulos_conjuntos_asign`;
CREATE TABLE `fza_articulos_conjuntos_asign` (
  `CODIGO_ART_ACA` varchar(20) NOT NULL COMMENT 'FK fza_articulos',
  `ID_AC_ACA` int(11) NOT NULL COMMENT 'FK fza_atributos_conjuntos',
  `ID_VA_ACA` varchar(20) NOT NULL COMMENT 'Posición del atributo (CO, TAL...) – denormalizado del conjunto para índice directo',
  `ORDEN_ACA` int(11) NOT NULL DEFAULT 0 COMMENT 'Orden del atributo dentro del SKU para este artículo (0 = usar fza_variaciones_atributos.ORDEN_VA global).',
  `ESGENERACION_AUTO_ACA` char(1) NOT NULL DEFAULT 'S' COMMENT 'S=genera SKUs automáticamente al procesar',
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  PRIMARY KEY (`CODIGO_ART_ACA`,`ID_VA_ACA`),
  KEY `IDX_ACA_CONJUNTO` (`CODIGO_ART_ACA`,`ID_AC_ACA`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_articulos_familias`;
CREATE TABLE `fza_articulos_familias` (
  `CODIGO_FAM_FAM` varchar(20) NOT NULL,
  `CODIGO_PADRE_FAM` varchar(20) DEFAULT NULL,
  `ESACTIVO_FAM` varchar(1) DEFAULT 'S',
  `ORDEN_FAM` int(11) DEFAULT NULL,
  `ESDEFAULT_FAM` varchar(1) DEFAULT NULL,
  `CODIGO_SUBFAMILIA_FAM` varchar(10) DEFAULT NULL,
  `NOMBRE_FAM_FAM` varchar(200) DEFAULT NULL,
  `DESCRIPCION_FAM` varchar(200) DEFAULT NULL,
  `CONTADOR_ART_FAM` int(11) DEFAULT NULL,
  `ESCONTADOR_ART_FAM` varchar(1) DEFAULT NULL,
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  `PAD_ART_FAM` int(11) NOT NULL DEFAULT 5 COMMENT 'Numero de digitos del relleno cuando se autogenera codigo articulo desde familia',
  `TIPO_TRAZABILIDAD_FAM` varchar(20) DEFAULT 'NINGUNA',
  PRIMARY KEY (`CODIGO_FAM_FAM`),
  KEY `IDX_FAM_PADRE` (`CODIGO_PADRE_FAM`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_articulos_fotos`;
CREATE TABLE `fza_articulos_fotos` (
  `CODIGO_ART_FOT` varchar(20) NOT NULL COMMENT 'FK logica fza_articulos.CODIGO_ART_ART',
  `CODIGO_UNIDAD_FOT` varchar(50) NOT NULL DEFAULT '' COMMENT 'FK logica fza_articulos_skus.CODIGO_UNIDAD_SKU. '''' = foto del articulo',
  `ORDEN_FOT` int(10) unsigned NOT NULL DEFAULT 1 COMMENT 'Posición 1-based dentro del artículo o unidad',
  `NOMBRE_FOT_FOT` varchar(255) NOT NULL COMMENT 'Nombre base del fichero (sin sufijo de tamaño ni extension)',
  `EXTENSION_ORIGEN_FOT` varchar(10) NOT NULL DEFAULT 'png' COMMENT 'Extension del fichero real, sin punto (png, jpg, jpeg, ...)',
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  PRIMARY KEY (`CODIGO_ART_FOT`,`CODIGO_UNIDAD_FOT`,`ORDEN_FOT`),
  KEY `IDX_FOT_SKU` (`CODIGO_UNIDAD_FOT`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_articulos_lotes`;
CREATE TABLE `fza_articulos_lotes` (
  `CODIGO_UNIDAD_LOT` varchar(50) NOT NULL,
  `LOTE_LOT` varchar(50) NOT NULL,
  `TIPO_LOT` varchar(1) NOT NULL,
  `FECHA_CADUCIDAD_LOT` date DEFAULT NULL,
  `FECHA_ENTRADA_LOT` date DEFAULT NULL,
  `CODIGO_PRV_LOT` varchar(20) DEFAULT NULL,
  `TIPO_DOC_ORIGEN_LOT` varchar(5) DEFAULT NULL,
  `SERIE_DOC_ORIGEN_LOT` varchar(20) DEFAULT NULL,
  `NUMERO_DOC_ORIGEN_LOT` varchar(20) DEFAULT NULL,
  `ESACTIVO_LOT` varchar(1) NOT NULL DEFAULT 'S',
  `OBSERVACIONES_LOT` varchar(200) DEFAULT NULL,
  `INSTANTE_ALTA` datetime NOT NULL DEFAULT current_timestamp(),
  `USUARIO_ALTA` varchar(50) NOT NULL,
  `INSTANTE_MODIF` datetime DEFAULT NULL,
  `USUARIO_MODIF` varchar(50) DEFAULT NULL,
  `ESREPOSICION_LOT` varchar(1) NOT NULL DEFAULT 'N',
  `CODIGO_EMP_LOT` varchar(10) DEFAULT NULL,
  `ID_PV_TEMPORADA_LOT` int(11) DEFAULT NULL,
  PRIMARY KEY (`CODIGO_UNIDAD_LOT`,`LOTE_LOT`),
  KEY `IDX_LOT_CADUCIDAD` (`FECHA_CADUCIDAD_LOT`),
  KEY `IDX_LOT_LOTE` (`LOTE_LOT`),
  KEY `IDX_LOT_REPOSICION` (`ESREPOSICION_LOT`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_articulos_pdte_recibir`;
CREATE TABLE `fza_articulos_pdte_recibir` (
  `CODIGO_UNIDAD_PDR` varchar(50) NOT NULL,
  `CODIGO_ALM_PDR` varchar(10) NOT NULL,
  `SERIE_DOC_PDR` varchar(12) NOT NULL COMMENT 'Serie del pedido de compra',
  `NUMERO_DOC_PDR` varchar(12) NOT NULL COMMENT 'Numero del pedido de compra',
  `LINEA_PDR` int(11) NOT NULL,
  `CODIGO_ART_PDR` varchar(20) NOT NULL,
  `CODIGO_PRV_PDR` varchar(20) DEFAULT NULL,
  `CODIGO_EMP_PDR` varchar(20) DEFAULT NULL,
  `CANTIDAD_PDR` decimal(19,6) NOT NULL DEFAULT 0.000000,
  `PRECIO_COMPRA_PDR` decimal(19,6) DEFAULT NULL,
  `FECHA_PEDIDO_PDR` date DEFAULT NULL,
  `FECHA_PREVISTA_PDR` date DEFAULT NULL COMMENT 'Fecha estimada de recepcion (opcional)',
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  PRIMARY KEY (`CODIGO_UNIDAD_PDR`,`CODIGO_ALM_PDR`,`SERIE_DOC_PDR`,`NUMERO_DOC_PDR`,`LINEA_PDR`),
  KEY `IDX_PDR_ART` (`CODIGO_ART_PDR`),
  KEY `IDX_PDR_DOC` (`SERIE_DOC_PDR`,`NUMERO_DOC_PDR`),
  KEY `IDX_PDR_SKU_ALM` (`CODIGO_UNIDAD_PDR`,`CODIGO_ALM_PDR`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_articulos_propiedades`;
CREATE TABLE `fza_articulos_propiedades` (
  `CODIGO_ART_ART` varchar(20) NOT NULL,
  `CODIGO_PROP_ARTPROP` varchar(20) NOT NULL COMMENT 'FK a fza_propiedades (ej: MATERIAL, EDAD_MAX)',
  `CODIGO_UNIDAD_ARTPROP` varchar(50) NOT NULL DEFAULT '' COMMENT 'FK logica fza_articulos_skus.CODIGO_UNIDAD_SKU. Vacio=articulo; ART/COLOR=color; ART/COLOR/TALLA=sku.',
  `ID_PV_ARTPROP` int(11) DEFAULT NULL COMMENT 'Si es tipo LISTA, guardas aquí el ID de fza_propiedades_valores',
  `VALOR_LIBRE_ARTPROP` varchar(255) DEFAULT NULL COMMENT 'Si es tipo TEXTO o NUMERO, escribes el dato directamente aquí',
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT current_timestamp(),
  `USUARIO_ALTA` varchar(100) NOT NULL,
  PRIMARY KEY (`CODIGO_ART_ART`,`CODIGO_PROP_ARTPROP`,`CODIGO_UNIDAD_ARTPROP`),
  KEY `IDX_ARTPROP_UNIDAD` (`CODIGO_UNIDAD_ARTPROP`),
  KEY `IDX_VALOR_LISTA` (`ID_PV_ARTPROP`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_articulos_proveedores`;
CREATE TABLE `fza_articulos_proveedores` (
  `CODIGO_PRV_AP` varchar(20) NOT NULL,
  `CODIGO_ART_AP` varchar(20) NOT NULL,
  `REF_PROVEEDOR_AP` varchar(100) DEFAULT NULL,
  `PRECIO_ULT_COMPRA_AP` decimal(19,6) DEFAULT NULL,
  `FECHA_VALIDEZ_AP` datetime DEFAULT NULL,
  `ESPROVEEDORPRINCIPAL_AP` varchar(1) DEFAULT NULL,
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  PRIMARY KEY (`CODIGO_PRV_AP`,`CODIGO_ART_AP`),
  KEY `IDX_AP_ART_PRINC` (`CODIGO_ART_AP`,`ESPROVEEDORPRINCIPAL_AP`),
  KEY `IDX_AP_REF` (`REF_PROVEEDOR_AP`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_articulos_skus`;
CREATE TABLE `fza_articulos_skus` (
  `CODIGO_UNIDAD_SKU` varchar(50) NOT NULL,
  `CODIGO_ART_SKU` varchar(20) NOT NULL,
  `CODIGO_VAR_SKU` varchar(20) NOT NULL,
  `ESACTIVO_SKU` varchar(1) DEFAULT 'S',
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  PRIMARY KEY (`CODIGO_UNIDAD_SKU`),
  KEY `idx_fza_articulos_skus_codart` (`CODIGO_ART_SKU`),
  KEY `IDX_SKU_ART_ACT` (`CODIGO_ART_SKU`,`ESACTIVO_SKU`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_articulos_skus_costes`;
CREATE TABLE `fza_articulos_skus_costes` (
  `CODIGO_UNIDAD_SKU_SKUC` varchar(50) NOT NULL COMMENT 'FK hacia fza_articulos_skus.CODIGO_UNIDAD_SKU',
  `PRECIO_ULT_COMPRA_SKUC` decimal(19,6) DEFAULT NULL,
  `FECHA_ULT_COMPRA_SKUC` date DEFAULT NULL,
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  PRIMARY KEY (`CODIGO_UNIDAD_SKU_SKUC`),
  KEY `IDX_SKUC_FECHA_ULT_COMPRA` (`FECHA_ULT_COMPRA_SKUC`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_articulos_stockactual`;
CREATE TABLE `fza_articulos_stockactual` (
  `CODIGO_ALM_STK` varchar(10) NOT NULL,
  `CODIGO_UNIDAD_STK` varchar(50) NOT NULL,
  `LOTE_STK` varchar(50) NOT NULL DEFAULT '',
  `FECHA_CADUCIDAD_STK` date DEFAULT NULL,
  `CANTIDAD_STK` decimal(19,6) DEFAULT 0.000000,
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `VALOR_TOTAL_STK` decimal(19,6) DEFAULT 0.000000,
  `PRECIO_MEDIO_STK` decimal(19,6) DEFAULT 0.000000,
  `CANTIDAD_PTE_RECIBIR_STK` decimal(19,6) DEFAULT 0.000000,
  `CANTIDAD_PTE_SERVIR_STK` decimal(19,6) DEFAULT 0.000000,
  `CANTIDAD_ENT_COMPRA_STK` decimal(19,6) NOT NULL DEFAULT 0.000000,
  `CANTIDAD_ENT_TRASPASO_STK` decimal(19,6) NOT NULL DEFAULT 0.000000,
  `CANTIDAD_SAL_TRASPASO_STK` decimal(19,6) NOT NULL DEFAULT 0.000000,
  `CANTIDAD_ENT_DEPOSITO_STK` decimal(19,6) NOT NULL DEFAULT 0.000000,
  `CANTIDAD_SAL_DEPOSITO_STK` decimal(19,6) NOT NULL DEFAULT 0.000000,
  `CANTIDAD_SAL_VENTA_STK` decimal(19,6) NOT NULL DEFAULT 0.000000,
  `CANTIDAD_ENT_REGULAR_STK` decimal(19,6) NOT NULL DEFAULT 0.000000,
  `CANTIDAD_SAL_ALBVENTA_STK` decimal(19,6) NOT NULL DEFAULT 0.000000,
  `CANTIDAD_ENT_ALBENTRADA_STK` decimal(19,6) NOT NULL DEFAULT 0.000000,
  PRIMARY KEY (`CODIGO_ALM_STK`,`CODIGO_UNIDAD_STK`,`LOTE_STK`),
  KEY `IDX_STK_UNIDAD` (`CODIGO_UNIDAD_STK`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_articulos_tarifas`;
CREATE TABLE `fza_articulos_tarifas` (
  `CODIGO_ART_ARTTAR` varchar(20) NOT NULL,
  `CODIGO_UNICO_ARTTAR` int(11) NOT NULL AUTO_INCREMENT,
  `CODIGO_UNIDAD_ARTTAR` varchar(50) NOT NULL DEFAULT '' COMMENT 'fza_articulos_skus',
  `CODIGO_TAR_ARTTAR` varchar(10) DEFAULT NULL,
  `ESACTIVO_ARTTAR` varchar(1) DEFAULT 'S',
  `PRECIO_SALIDA_ARTTAR` decimal(19,6) DEFAULT NULL,
  `PRECIO_FINAL_ARTTAR` decimal(19,6) DEFAULT 0.000000,
  `PRECIO_DTO_ARTTAR` decimal(19,6) DEFAULT NULL,
  `PORCENTAJE_DTO_ARTTAR` decimal(19,6) DEFAULT NULL,
  `PORCENTAJE_MARGEN_ARTTAR` decimal(19,6) DEFAULT NULL,
  `VALOR_MULTIPLO_AJUSTE_ARTTAR` decimal(19,6) DEFAULT NULL,
  `VALOR_MENOS_AJUSTE_ARTTAR` decimal(19,6) DEFAULT NULL,
  `FECHA_DESDE_ARTTAR` date DEFAULT NULL,
  `FECHA_HASTA_ARTTAR` date DEFAULT NULL,
  `ESTRAMO_ARTTAR` varchar(1) NOT NULL DEFAULT 'N',
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  `PRECIO_COSTE_ARTTAR` decimal(19,6) DEFAULT NULL,
  `FECHA_ULT_COMPRA_ARTTAR` date DEFAULT NULL,
  `CODIGO_PRV_ARTTAR` varchar(20) DEFAULT NULL,
  PRIMARY KEY (`CODIGO_UNICO_ARTTAR`),
  KEY `IDX_ARTTAR_BUSQ_VIGENTE` (`CODIGO_ART_ARTTAR`,`CODIGO_TAR_ARTTAR`,`ESACTIVO_ARTTAR`,`FECHA_DESDE_ARTTAR`),
  KEY `IDX_ARTTAR_PRV` (`CODIGO_PRV_ARTTAR`),
  KEY `IDX_ARTTAR_VIGENCIA` (`ESACTIVO_ARTTAR`,`FECHA_HASTA_ARTTAR`),
  KEY `IDX_ART_TARIFAS_BUSQUEDA` (`CODIGO_ART_ARTTAR`,`CODIGO_TAR_ARTTAR`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_articulos_vinculos`;
CREATE TABLE `fza_articulos_vinculos` (
  `ID_ARTVIN` int(11) NOT NULL AUTO_INCREMENT,
  `CODIGO_ART_PADRE_ARTVIN` varchar(20) NOT NULL,
  `CODIGO_ART_HIJO_ARTVIN` varchar(20) NOT NULL,
  `CANTIDAD_ARTVIN` decimal(10,2) DEFAULT 1.00,
  `ORDEN_VISUAL_ARTVIN` int(11) DEFAULT 1,
  `ESOBLIGATORIO_ARTVIN` char(1) DEFAULT 'S',
  PRIMARY KEY (`ID_ARTVIN`),
  KEY `IDX_ARTVIN_HIJO` (`CODIGO_ART_HIJO_ARTVIN`),
  KEY `IDX_ARTVIN_PADRE` (`CODIGO_ART_PADRE_ARTVIN`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_atributos_basicos`;
CREATE TABLE `fza_atributos_basicos` (
  `ID_ATB` int(11) NOT NULL AUTO_INCREMENT,
  `ID_VA_ATB` varchar(20) NOT NULL,
  `CODIGO_ATB` varchar(100) NOT NULL COMMENT 'Código corto del atributo básico (XL, AZUL_CIELO, EU42, AD_DEMO-CAMISA_3XL).',
  `NOMBRE_ATB` varchar(100) NOT NULL,
  `DESCRIPCION_ATB` varchar(255) DEFAULT NULL COMMENT 'Descripción larga: AZUL CIELO, Talla XL Hombre, etc.',
  `HEX_ATB` varchar(7) DEFAULT NULL COMMENT 'Color paleta en formato #RRGGBB (sólo para atributos de color)',
  `VALOR_NUM_ATB` decimal(12,4) DEFAULT NULL COMMENT 'Valor numérico básico (47 cm de talla XL, 50 mm de diámetro…)',
  `UNIDAD_ATB` varchar(10) DEFAULT NULL COMMENT 'Unidad de VALOR_NUM_ATB: cm, mm, kg, ml…',
  `ORDEN_ATB` int(11) DEFAULT 0,
  `ESACTIVO_ATB` char(1) DEFAULT 'S',
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL DEFAULT 'SISTEMA',
  `USUARIO_MODIF` varchar(100) NOT NULL DEFAULT 'SISTEMA',
  PRIMARY KEY (`ID_ATB`),
  UNIQUE KEY `ID_VA_ATB` (`ID_VA_ATB`,`CODIGO_ATB`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_atributos_conjuntos`;
CREATE TABLE `fza_atributos_conjuntos` (
  `ID_AC` int(11) NOT NULL AUTO_INCREMENT,
  `NOMBRE_AC` varchar(100) NOT NULL COMMENT 'Nombre descriptivo del set',
  `NOMBRE_CORTO_AC` varchar(12) DEFAULT NULL COMMENT 'Abreviatura del sistema para impresion (CAB, SRA, EUR, LETR, NUM). NULL = fallback al inicio de NOMBRE_AC.',
  `ID_VAR_AC` varchar(20) NOT NULL COMMENT 'FK fza_variaciones (TC, TEMP…)',
  `ID_VA_AC` varchar(20) DEFAULT NULL COMMENT 'Posición/atributo dentro de la variación (CO, TAL, TEMP…) → FK fza_variaciones_atributos',
  `ESACTIVO_AC` varchar(1) DEFAULT 'S',
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  PRIMARY KEY (`ID_AC`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_atributos_conjuntos_det`;
CREATE TABLE `fza_atributos_conjuntos_det` (
  `ID_AC_ACD` int(11) NOT NULL COMMENT 'FK a la cabecera del conjunto',
  `ID_AV_ACD` int(11) NOT NULL COMMENT 'FK al valor individual (fza_atributos_valores)',
  `ORDEN_ACD` int(11) NOT NULL DEFAULT 0 COMMENT 'Orden de visualización dentro de este conjunto específico',
  `ID_ATB_ACD` int(11) DEFAULT NULL COMMENT 'FK → fza_atributos_basicos. Significado del valor dentro de ESTE conjunto (XL=56cm en bañador, XL=34cm en camisa).',
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  PRIMARY KEY (`ID_AC_ACD`,`ID_AV_ACD`),
  KEY `IDX_ACD_ATB` (`ID_ATB_ACD`),
  KEY `IDX_VALOR_ACD` (`ID_AV_ACD`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_atributos_sku`;
CREATE TABLE `fza_atributos_sku` (
  `CODIGO_UNIDAD_SKU_SA` varchar(50) NOT NULL COMMENT 'FK hacia fza_articulos_skus',
  `ID_AV_SA` int(11) NOT NULL COMMENT 'FK hacia fza_atributos_valores',
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  PRIMARY KEY (`CODIGO_UNIDAD_SKU_SA`,`ID_AV_SA`),
  KEY `idx_fza_atributos_sku_idav` (`ID_AV_SA`),
  KEY `idx_fza_atributos_sku_unidad` (`CODIGO_UNIDAD_SKU_SA`),
  KEY `IDX_SA_UNIDAD` (`CODIGO_UNIDAD_SKU_SA`),
  KEY `IDX_VALOR_SA` (`ID_AV_SA`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_atributos_valores`;
CREATE TABLE `fza_atributos_valores` (
  `ID_AV` int(11) NOT NULL AUTO_INCREMENT COMMENT 'Identificador único del valor',
  `ID_VA_AV` varchar(20) NOT NULL COMMENT 'Relación con fza_variaciones_atributos (ej: CO)',
  `AV` varchar(100) NOT NULL COMMENT 'El valor real (ej: Azul, XL, 42)',
  `ORDEN_AV` int(11) NOT NULL DEFAULT 0 COMMENT 'Orden de visualización global (usar saltos de 10: 10, 20, 30...)',
  `DESCRIPCION_AV` varchar(255) DEFAULT NULL,
  `ESACTIVO_AV` varchar(1) DEFAULT 'S',
  `FACTOR_CONVERSION_AV` decimal(19,6) DEFAULT 1.000000 COMMENT 'Multiplicador respecto a la unidad base',
  `UNIDAD_MEDIDA_AV` varchar(10) DEFAULT NULL COMMENT 'L, Kg, m, m2, ud',
  `CODIGO_ART_EXTRA_AV` varchar(20) DEFAULT NULL COMMENT 'Si se rellena, al elegir este valor se genera una linea aparte con un incremento por ejemplo',
  `ID_ATB_AV` int(11) DEFAULT NULL COMMENT 'FK lógica → fza_atributos_basicos.ID_ATB. Asocia este valor concreto (p. ej. "001" del proveedor) con su atributo básico estándar ("AZUL CIELO").',
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  `VALOR_NORMALIZADO_AV` varchar(100) GENERATED ALWAYS AS (ucase(trim(`AV`))) STORED,
  PRIMARY KEY (`ID_AV`),
  UNIQUE KEY `UQ_AV_VALOR` (`ID_VA_AV`,`VALOR_NORMALIZADO_AV`),
  KEY `IDX_AV_ATB` (`ID_ATB_AV`),
  KEY `idx_fza_atributos_valores_idva` (`ID_VA_AV`),
  KEY `IDX_VAR_AV` (`ID_VA_AV`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_atributos_valores_info`;
CREATE TABLE `fza_atributos_valores_info` (
  `ID_AVI` int(11) NOT NULL AUTO_INCREMENT,
  `ID_AV_AVI` int(11) NOT NULL COMMENT 'Relación con fza_atributos_valores (El ID del Rojo o de la XL)',
  `CLAVE_AVI` varchar(50) NOT NULL COMMENT 'El nombre del dato: COD_PROV, MEDIDA_CM, HEX, etc.',
  `VALOR_AVI` varchar(255) NOT NULL COMMENT 'El valor del dato: RED-01, 50-70, #FF0000',
  PRIMARY KEY (`ID_AVI`),
  KEY `IDX_VALOR_INFO` (`ID_AV_AVI`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_bancos`;
CREATE TABLE `fza_bancos` (
  `CODIGO_BAN` varchar(4) NOT NULL COMMENT 'Codigo de entidad NRBE de 4 digitos',
  `NOMBRE_BAN` varchar(100) NOT NULL,
  `BIC_BAN` varchar(11) DEFAULT NULL COMMENT 'BIC/SWIFT de la oficina central (8 u 11)',
  `ESACTIVO_BAN` varchar(1) NOT NULL DEFAULT 'S',
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  PRIMARY KEY (`CODIGO_BAN`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_caja_arqueos`;
CREATE TABLE `fza_caja_arqueos` (
  `CODIGO_ARQ` varchar(30) NOT NULL COMMENT 'ID único del arqueo / cierre Z',
  `CODIGO_EMP_ARQ` varchar(10) NOT NULL,
  `CODIGO_ALM_ARQ` varchar(10) NOT NULL,
  `CODIGO_CAJA_ARQ` varchar(10) NOT NULL COMMENT 'Terminal físico (TPV1, TPV2...)',
  `FECHA_DESDE_ARQ` datetime NOT NULL,
  `FECHA_HASTA_ARQ` datetime NOT NULL,
  `FASE_ARQ` varchar(15) NOT NULL DEFAULT 'ABIERTO' COMMENT 'ABIERTO, CERRADO',
  `CODIGO_EMPLEADO_ARQ` varchar(20) DEFAULT NULL,
  `CANTIDAD_VENTAS_ARQ` int(11) NOT NULL DEFAULT 0,
  `CANTIDAD_OPERACIONES_ARQ` int(11) NOT NULL DEFAULT 0,
  `TOTAL_BRUTO_LINEAS_ARQ` decimal(19,6) NOT NULL DEFAULT 0.000000,
  `TOTAL_DESCUENTOS_LINEAS_ARQ` decimal(19,6) NOT NULL DEFAULT 0.000000,
  `TOTAL_BRUTO_OPERACIONES_ARQ` decimal(19,6) NOT NULL DEFAULT 0.000000,
  `TOTAL_DESCUENTOS_OPERACIONES_ARQ` decimal(19,6) NOT NULL DEFAULT 0.000000,
  `TOTAL_NETO_ARQ` decimal(19,6) NOT NULL DEFAULT 0.000000 COMMENT 'SUM IMPORTE_TOTAL_OPCAJA de VE en el rango (signed)',
  `TOTAL_PRESTAMOS_ARQ` decimal(19,6) NOT NULL DEFAULT 0.000000 COMMENT 'SUM TIPO=DE en el rango (compromiso bruto)',
  `TOTAL_VENTAS_NORMALES_ARQ` decimal(19,6) NOT NULL DEFAULT 0.000000 COMMENT 'VE > 0 sin DE en la misma operación',
  `TOTAL_VENTAS_PRESTAMOS_ARQ` decimal(19,6) NOT NULL DEFAULT 0.000000 COMMENT '= TOTAL_PRESTAMOS_ARQ − TOTAL_COBROS_CLIENTES_ARQ',
  `TOTAL_DEVOLUCIONES_ARQ` decimal(19,6) NOT NULL DEFAULT 0.000000 COMMENT 'ABS de VE < 0 (devoluciones a cliente)',
  `TOTAL_VENTAS_ARQ` decimal(19,6) NOT NULL DEFAULT 0.000000 COMMENT '= VentasNormales + VentasPrestamos − Devoluciones',
  `TOTAL_VENTA_CREDITO_ARQ` decimal(19,6) NOT NULL DEFAULT 0.000000 COMMENT 'Ventas a crédito / albarán (legacy ImpAlbaranCdo)',
  `TOTAL_VALES_RECOGIDOS_ARQ` decimal(19,6) NOT NULL DEFAULT 0.000000,
  `TOTAL_VALES_EMITIDOS_ARQ` decimal(19,6) NOT NULL DEFAULT 0.000000,
  `TOTAL_COBROS_CLIENTES_ARQ` decimal(19,6) NOT NULL DEFAULT 0.000000,
  `TOTAL_PENDIENTE_COBRO_ARQ` decimal(19,6) NOT NULL DEFAULT 0.000000,
  `TOTAL_INGRESOS_CAJA_ARQ` decimal(19,6) NOT NULL DEFAULT 0.000000,
  `TOTAL_EFECTIVO_INGRESOS_ARQ` decimal(19,6) NOT NULL DEFAULT 0.000000,
  `TOTAL_EFECTIVO_ENTRADAS_ARQ` decimal(19,6) NOT NULL DEFAULT 0.000000,
  `TOTAL_EFECTIVO_SALIDAS_ARQ` decimal(19,6) NOT NULL DEFAULT 0.000000,
  `TOTAL_EFECTIVO_ANTERIOR_ARQ` decimal(19,6) NOT NULL DEFAULT 0.000000,
  `TOTAL_EFECTIVO_CAJA_ARQ` decimal(19,6) NOT NULL DEFAULT 0.000000,
  `TOTAL_OTROS_INGRESOS_ARQ` decimal(19,6) NOT NULL DEFAULT 0.000000 COMMENT 'Suma de formas de pago sin cajón (tarjeta, bono, divisa, cripto...)',
  `TOTAL_DEPOSITOS_ARQ` decimal(19,6) NOT NULL DEFAULT 0.000000 COMMENT 'Depósitos (legacy ImpDeposito)',
  `TOTAL_ENCARGOS_ARQ` decimal(19,6) NOT NULL DEFAULT 0.000000 COMMENT 'Encargos (legacy ImpEncargo)',
  `TOTAL_SALDO_RECONTAR_ARQ` decimal(19,6) NOT NULL DEFAULT 0.000000 COMMENT 'Saldo teórico efectivo + otros (lo que debe estar en caja + ext.)',
  `TOTAL_RECUENTO_ARQ` decimal(19,6) NOT NULL DEFAULT 0.000000 COMMENT 'Suma de los importes recontados por el usuario',
  `DIFERENCIA_TOTAL_ARQ` decimal(19,6) NOT NULL DEFAULT 0.000000 COMMENT 'Recuento - Saldo teórico (positivo = sobrante)',
  `EFECTIVO_DEJADO_CAJA_ARQ` decimal(19,6) NOT NULL DEFAULT 0.000000 COMMENT 'Efectivo que se deja en caja como cambio para el día siguiente',
  `DESGLOSE_BILLETES_ARQ` text DEFAULT NULL COMMENT 'Desglose billetes/monedas formato denom:uds;...',
  `IMPORTE_RETIRADA_ARQ` decimal(19,6) NOT NULL DEFAULT 0.000000,
  `CONCEPTO_RETIRADA_ARQ` varchar(100) DEFAULT NULL,
  `OBSERVACIONES_ARQ` varchar(500) DEFAULT NULL,
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  PRIMARY KEY (`CODIGO_ARQ`),
  KEY `IDX_ARQ_CTX_FECHA` (`CODIGO_EMP_ARQ`,`CODIGO_ALM_ARQ`,`CODIGO_CAJA_ARQ`,`FECHA_DESDE_ARQ`),
  KEY `IDX_ARQ_FASE` (`FASE_ARQ`),
  KEY `IDX_ARQ_FECHA` (`FECHA_DESDE_ARQ`,`FECHA_HASTA_ARQ`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_caja_arqueos_recuento`;
CREATE TABLE `fza_caja_arqueos_recuento` (
  `ID_ARQR` int(11) NOT NULL AUTO_INCREMENT COMMENT 'PK autoincremental',
  `CODIGO_ARQ_ARQR` varchar(30) NOT NULL COMMENT 'FK lógica a fza_caja_arqueos.CODIGO_ARQ',
  `CODIGO_FP_CFP_ARQR` varchar(20) NOT NULL COMMENT 'FK lógica a fza_caja_formas_pago.CODIGO_FP_CFP',
  `DESCRIPCION_FP_ARQR` varchar(100) NOT NULL DEFAULT '' COMMENT 'Snapshot de DESCRIPCION_FORMA_PAGO_CFP al momento del arqueo',
  `ESCAJON_ARQR` varchar(1) NOT NULL DEFAULT 'N' COMMENT 'Snapshot de ESABRE_CAJON_FORMA_PAGO_CFP (S/N)',
  `IMPORTE_SISTEMA_ARQR` decimal(19,6) NOT NULL DEFAULT 0.000000 COMMENT 'Importe calculado por el sistema para esta forma de pago',
  `IMPORTE_RECUENTO_ARQR` decimal(19,6) NOT NULL DEFAULT 0.000000 COMMENT 'Importe que el usuario ha contado físicamente',
  `DIFERENCIA_ARQR` decimal(19,6) NOT NULL DEFAULT 0.000000 COMMENT 'Recuento − Sistema (positivo = sobrante)',
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  PRIMARY KEY (`ID_ARQR`),
  UNIQUE KEY `UQ_ARQR_ARQ_FP` (`CODIGO_ARQ_ARQR`,`CODIGO_FP_CFP_ARQR`),
  KEY `IDX_ARQR_ARQUEO` (`CODIGO_ARQ_ARQR`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_caja_formas_pago`;
CREATE TABLE `fza_caja_formas_pago` (
  `CODIGO_FP_CFP` varchar(20) NOT NULL COMMENT 'Código identificativo (EFE, TARJ, etc)',
  `DESCRIPCION_FORMA_PAGO_CFP` varchar(100) NOT NULL COMMENT 'Nombre visual para el ticket',
  `ESREQ_REFERENCIA_FORMA_PAGO_CFP` varchar(1) NOT NULL DEFAULT 'N' COMMENT 'S=Obliga a introducir un número (ej: cod barras bono, nro autorización tarjeta)',
  `ESCRIPTO_FORMA_PAGO_CFP` varchar(1) NOT NULL,
  `RED_BLOCKCHAIN_FORMA_PAGO_CFP` varchar(100) DEFAULT NULL,
  `HASH_BLOCKCHAIN_FORMA_PAGO_CFP` varchar(128) DEFAULT NULL,
  `ESDIVISA_FORMA_PAGO_CFP` varchar(1) NOT NULL,
  `ESDEVUELVE_CAMBIO_FORMA_PAGO_CFP` varchar(1) DEFAULT 'S' COMMENT 'S=Permite dar cambio. N=No permite (el bono debe gastarse entero o se pierde el resto)',
  `ESABRE_CAJON_FORMA_PAGO_CFP` varchar(1) DEFAULT 'N' COMMENT 'S=Lanza la secuencia de apertura de cajón',
  `ESACTIVO_FORMA_PAGO_CFP` varchar(1) DEFAULT 'S',
  `PORCENTAJE_COMISION_FORMA_PAGO_CFP` int(11) DEFAULT NULL,
  `ESCOMISION_INCL_FORMA_PAGO_CFP` varchar(1) DEFAULT NULL,
  `NUM_COD_DIGIT_FORMA_PAGO_CFP` varchar(1) DEFAULT NULL,
  `ORDEN_VISUAL_FORMA_PAGO_CFP` int(11) DEFAULT 99 COMMENT 'Para ordenar los botones en la pantalla F12',
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  PRIMARY KEY (`CODIGO_FP_CFP`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_caja_operaciones`;
CREATE TABLE `fza_caja_operaciones` (
  `ID_OPCAJA` bigint(20) NOT NULL AUTO_INCREMENT,
  `CODIGO_EMP_OPCAJA` varchar(10) NOT NULL,
  `CODIGO_ALM_OPCAJA` varchar(10) NOT NULL,
  `CODIGO_CAJA_OPCAJA` varchar(10) NOT NULL COMMENT 'Terminal físico (TPV1, TPV2...)',
  `NUMERO_OPERACION_OPCAJA` varchar(20) NOT NULL,
  `NUMERO_FAC_OPCAJA` varchar(20) DEFAULT NULL,
  `SERIE_FAC_OPCAJA` varchar(20) DEFAULT NULL,
  `FECHA_OPERACION_OPCAJA` datetime NOT NULL,
  `CODIGO_EMPLEADO_OPCAJA` varchar(20) NOT NULL,
  `TIPO_OPERACION_OPCAJA` varchar(2) NOT NULL COMMENT 'VE, AL, CB, EC, GC, TR, AT',
  `IMPORTE_TOTAL_OPCAJA` decimal(19,6) NOT NULL DEFAULT 0.000000,
  `CODIGO_CLI_OPCAJA` varchar(20) DEFAULT NULL,
  `ESTADO_DEVOLUCION_OPCAJA` char(1) NOT NULL DEFAULT 'N',
  `IMPORTE_DEVUELTO_ACUM_OPCAJA` decimal(19,6) NOT NULL DEFAULT 0.000000,
  `CONCEPTO_GASTO_INGRESO_OPCAJA` varchar(100) DEFAULT NULL,
  `SERIE_REF_ORIGEN_OPCAJA` varchar(20) DEFAULT NULL,
  `NUMERO_REF_ORIGEN_OPCAJA` varchar(20) DEFAULT NULL,
  `MOTIVO_DEVOLUCION_OPCAJA` varchar(50) DEFAULT NULL,
  `CODIGO_EMP_CONTRA_OPCAJA` varchar(20) DEFAULT NULL,
  `CODIGO_ALM_CONTRA_OPCAJA` varchar(10) DEFAULT NULL,
  `ESTRASPASO_OPCAJA` varchar(1) DEFAULT 'N',
  `CODIGO_ARQUEO_OPCAJA` varchar(20) DEFAULT NULL COMMENT 'ID del Cierre Z al que pertenece esta línea',
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  `ID_DEPOSITO_OPCAJA` varchar(20) DEFAULT NULL COMMENT 'FK a fza_depositos_cliente, solo en CB y DE de depósitos',
  `FECHA_OP_DIA_OPCAJA` date DEFAULT NULL,
  PRIMARY KEY (`ID_OPCAJA`),
  KEY `FT_OPCAJA_CONCEPTO` (`CONCEPTO_GASTO_INGRESO_OPCAJA`),
  KEY `IDX_AGRUPACION_OPCAJA` (`CODIGO_EMP_OPCAJA`,`CODIGO_ALM_OPCAJA`,`CODIGO_CAJA_OPCAJA`,`NUMERO_OPERACION_OPCAJA`),
  KEY `IDX_CIERRE_OPCAJA` (`CODIGO_ARQUEO_OPCAJA`),
  KEY `IDX_DEP_OPCAJA` (`ID_DEPOSITO_OPCAJA`),
  KEY `IDX_OPCAJA_CTX_FECHA` (`CODIGO_EMP_OPCAJA`,`CODIGO_ALM_OPCAJA`,`CODIGO_CAJA_OPCAJA`,`FECHA_OPERACION_OPCAJA`),
  KEY `IDX_OPCAJA_DIA_CTX` (`FECHA_OP_DIA_OPCAJA`,`CODIGO_EMP_OPCAJA`,`CODIGO_ALM_OPCAJA`,`CODIGO_CAJA_OPCAJA`),
  KEY `IDX_OPCAJA_EMP_ALM_TIPO_FECHA` (`CODIGO_EMP_OPCAJA`,`CODIGO_ALM_OPCAJA`,`TIPO_OPERACION_OPCAJA`,`FECHA_OPERACION_OPCAJA`),
  KEY `IDX_OPCAJA_EMP_TIPO_INSTANTE` (`CODIGO_EMP_OPCAJA`,`TIPO_OPERACION_OPCAJA`,`INSTANTE_ALTA`),
  KEY `IDX_REF_ORIGEN_OPCAJA` (`SERIE_REF_ORIGEN_OPCAJA`,`NUMERO_REF_ORIGEN_OPCAJA`),
  KEY `IDX_OPCAJA_EMP_FECHA_884` (`CODIGO_EMP_OPCAJA`,`FECHA_OPERACION_OPCAJA`),
  KEY `IDX_OPCAJA_EMP_FACTURA_884` (`CODIGO_EMP_OPCAJA`,`SERIE_FAC_OPCAJA`,`NUMERO_FAC_OPCAJA`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_caja_pagos`;
CREATE TABLE `fza_caja_pagos` (
  `CODIGO_EMP_PAGO` varchar(20) NOT NULL,
  `CODIGO_ALM_PAGO` varchar(10) NOT NULL,
  `CODIGO_CAJA_PAGO` varchar(10) NOT NULL,
  `SERIE_OPERACION_PAGO` varchar(20) NOT NULL,
  `NUMERO_OPERACION_PAGO` varchar(20) NOT NULL,
  `NUMERO_LINEA_PAGO` int(11) NOT NULL DEFAULT 1 COMMENT 'Orden del pago: 1, 2, 3...',
  `CODIGO_FP_CFP` varchar(10) NOT NULL COMMENT 'FK a fza_formas_pago',
  `CODIGO_DIVISA_PAGO` varchar(10) DEFAULT NULL COMMENT 'Código ISO o Ticker: USD, BTC, ETH',
  `RED_BLOCKCHAIN_PAGO` varchar(50) DEFAULT NULL COMMENT 'Ej: Bitcoin, Ethereum, TRC20, ERC20, Lightning',
  `FACTOR_CAMBIO_PAGO` decimal(24,8) NOT NULL DEFAULT 1.00000000 COMMENT 'Valor de conversión respecto a la moneda base',
  `IMPORTE_DIVISA_PAGO` decimal(24,8) NOT NULL DEFAULT 0.00000000 COMMENT 'Cantidad entregada en la divisa o crypto original',
  `IMPORTE_ENTREGADO_PAGO` decimal(19,6) NOT NULL DEFAULT 0.000000,
  `IMPORTE_CAMBIO_PAGO` decimal(19,6) NOT NULL DEFAULT 0.000000 COMMENT 'Solo para efectivo si entrega de más',
  `REFERENCIA_FACPAG` varchar(255) DEFAULT NULL COMMENT 'Hash de Transacción (TxID), Auth Tarjeta o Referencia',
  `OBSERVACIONES_PAGO` varchar(255) DEFAULT NULL,
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `NUMERO_LINEA_ORIGEN_PAGO` int(11) DEFAULT NULL COMMENT 'Línea compensada dentro de la misma operación y serie',
  `TIPO_CORRECCION_PAGO` varchar(1) DEFAULT NULL COMMENT 'N: compensación negativa; P: cobro correcto; NULL: original',
  PRIMARY KEY (`CODIGO_EMP_PAGO`,`CODIGO_ALM_PAGO`,`CODIGO_CAJA_PAGO`,`SERIE_OPERACION_PAGO`,`NUMERO_OPERACION_PAGO`,`NUMERO_LINEA_PAGO`),
  UNIQUE KEY `UQ_PAGO_CORRECCION_ORIGEN` (`CODIGO_EMP_PAGO`,`CODIGO_ALM_PAGO`,`CODIGO_CAJA_PAGO`,`SERIE_OPERACION_PAGO`,`NUMERO_OPERACION_PAGO`,`NUMERO_LINEA_ORIGEN_PAGO`,`TIPO_CORRECCION_PAGO`),
  KEY `FK_PAGO_FORMAP` (`CODIGO_FP_CFP`),
  KEY `IDX_PAGO_OPERACION_884` (`CODIGO_EMP_PAGO`,`CODIGO_ALM_PAGO`,`CODIGO_CAJA_PAGO`,`NUMERO_OPERACION_PAGO`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_caja_subsanaciones`;
CREATE TABLE `fza_caja_subsanaciones` (
  `ID_CJSUB` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `CODIGO_EMP_CJSUB` varchar(20) NOT NULL,
  `CODIGO_ALM_CJSUB` varchar(10) NOT NULL,
  `CODIGO_CAJA_CJSUB` varchar(10) NOT NULL,
  `NUMERO_OPERACION_CJSUB` varchar(20) NOT NULL,
  `SERIE_FAC_CJSUB` varchar(20) NOT NULL,
  `NUMERO_FAC_CJSUB` varchar(20) NOT NULL,
  `MOTIVO_CJSUB` varchar(500) NOT NULL,
  `DATOS_ANTES_CJSUB` longtext NOT NULL,
  `DATOS_DESPUES_CJSUB` longtext NOT NULL,
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT current_timestamp(),
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `INSTANTE_MODIF` timestamp NULL DEFAULT NULL,
  `USUARIO_MODIF` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`ID_CJSUB`),
  KEY `IDX_CJSUB_FACTURA` (`SERIE_FAC_CJSUB`,`NUMERO_FAC_CJSUB`),
  KEY `IDX_CJSUB_OPERACION` (`CODIGO_EMP_CJSUB`,`CODIGO_ALM_CJSUB`,`CODIGO_CAJA_CJSUB`,`NUMERO_OPERACION_CJSUB`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_caja_vales`;
CREATE TABLE `fza_caja_vales` (
  `CODIGO_VL` varchar(50) NOT NULL COMMENT 'Código de barras identificador',
  `CODIGO_PADRE_VL` varchar(50) DEFAULT NULL COMMENT 'Si este vale es el cambio de otro anterior, aquí va el ID del padre',
  `PIN_SEGURIDAD_VL` varchar(10) NOT NULL DEFAULT '' COMMENT 'Código aleatorio tipo CVV para validar el vale',
  `ESTADO_VL` varchar(15) NOT NULL DEFAULT 'PENDIENTE' COMMENT 'PENDIENTE, REDIMIDO, ANULADO, CADUCADO',
  `IMPORTE_NOMINAL_VL` decimal(19,6) NOT NULL DEFAULT 0.000000 COMMENT 'El valor monetario que tiene este vale',
  `FECHA_EMISION_VL` datetime NOT NULL,
  `FECHA_CADUCIDAD_VL` date DEFAULT NULL,
  `CODIGO_EMP_EMI_VL` varchar(20) NOT NULL,
  `CODIGO_ALM_EMI_VL` varchar(10) NOT NULL,
  `CODIGO_CAJA_EMI_VL` varchar(10) NOT NULL,
  `NUMERO_OPERACION_EMI_VL` varchar(20) NOT NULL COMMENT 'ID operación TPV donde se creó',
  `SERIE_FAC_EMI_VL` varchar(20) DEFAULT NULL COMMENT 'Factura de abono o ticket origen',
  `NUMERO_FAC_EMI_VL` varchar(20) DEFAULT NULL,
  `FECHA_REDENCION_VL` datetime DEFAULT NULL,
  `IMPORTE_REDIMIDO_VL` decimal(19,6) DEFAULT 0.000000 COMMENT 'Suele coincidir con el nominal al ser de uso único',
  `CODIGO_EMP_RED_VL` varchar(20) DEFAULT NULL,
  `CODIGO_ALM_RED_VL` varchar(10) DEFAULT NULL,
  `CODIGO_CAJA_RED_VL` varchar(10) DEFAULT NULL,
  `NUMERO_OPERACION_RED_VL` varchar(20) DEFAULT NULL COMMENT 'ID operación TPV donde se gastó',
  `SERIE_FAC_RED_VL` varchar(20) DEFAULT NULL COMMENT 'Factura o ticket que se pagó con esto',
  `NUMERO_FAC_RED_VL` varchar(20) DEFAULT NULL,
  `CODIGO_CLI_VL` varchar(20) DEFAULT NULL,
  `OBSERVACIONES_VL` varchar(200) DEFAULT NULL,
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  PRIMARY KEY (`CODIGO_VL`),
  KEY `IDX_CADUCIDAD_VL` (`FECHA_CADUCIDAD_VL`),
  KEY `IDX_ESTADO_VL` (`ESTADO_VL`),
  KEY `IDX_PADRE_VL` (`CODIGO_PADRE_VL`),
  KEY `IDX_VALES_EMI_OP` (`CODIGO_EMP_EMI_VL`,`CODIGO_ALM_EMI_VL`,`CODIGO_CAJA_EMI_VL`,`NUMERO_OPERACION_EMI_VL`),
  KEY `IDX_VALES_RED_OP` (`CODIGO_EMP_RED_VL`,`CODIGO_ALM_RED_VL`,`CODIGO_CAJA_RED_VL`,`NUMERO_OPERACION_RED_VL`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_clientes`;
CREATE TABLE `fza_clientes` (
  `CODIGO_CLI_CLI` varchar(20) NOT NULL,
  `ESACTIVO_CLI` varchar(1) DEFAULT 'S',
  `ORDEN_CLI` int(11) DEFAULT NULL,
  `RAZON_SOCIAL_CLI` varchar(200) NOT NULL,
  `NIF_CLI` varchar(50) DEFAULT NULL,
  `RESULTADO_VERIFICACION_NIF_CLI` varchar(60) DEFAULT NULL,
  `INSTANTE_VERIFICACION_NIF_CLI` datetime DEFAULT NULL,
  `MOVIL_CLI` varchar(40) DEFAULT NULL,
  `EMAIL_CLI` varchar(200) DEFAULT NULL,
  `DIRECCION1_CLI` varchar(200) DEFAULT NULL,
  `DIRECCION2_CLI` varchar(200) DEFAULT NULL,
  `POBLACION_CLI` varchar(200) DEFAULT NULL,
  `PROVINCIA_CLI` varchar(200) DEFAULT NULL,
  `CODIGO_POSTAL_CLI` varchar(15) DEFAULT NULL,
  `CODIGO_PAI_CLI` varchar(3) DEFAULT '724',
  `NOMBRE_PAI_CLI` varchar(150) DEFAULT 'España',
  `NOMBRE_PERSONA_CLIENTE_CLI` varchar(80) DEFAULT NULL,
  `APELLIDOS_PERSONA_CLIENTE_CLI` varchar(120) DEFAULT NULL,
  `CODIGO_OFICINA_CONTABLE_CLI` varchar(10) DEFAULT NULL,
  `CODIGO_ORGANO_GESTOR_CLI` varchar(10) DEFAULT NULL,
  `CODIGO_UNIDAD_TRAMITADORA_CLI` varchar(10) DEFAULT NULL,
  `OBSERVACIONES_CLI` text DEFAULT NULL,
  `REFERENCIA_CLI` varchar(100) DEFAULT NULL,
  `CONTACTO_CLI` varchar(100) DEFAULT NULL,
  `TELEFONO_CONTACTO_CLI` varchar(100) DEFAULT NULL,
  `TELEFONO_CLI` varchar(40) DEFAULT NULL,
  `IBAN_CLI` varchar(100) DEFAULT NULL,
  `ID_MANDATO_SEPA_CLI` varchar(35) DEFAULT NULL COMMENT 'Identificador del mandato SEPA de adeudo',
  `FECHA_FIRMA_MANDATO_SEPA_CLI` date DEFAULT NULL COMMENT 'Fecha de firma del mandato SEPA de adeudo',
  `ESIVA_RECARGO_CLI` varchar(1) DEFAULT 'N',
  `ESRETENCIONES_CLI` varchar(1) DEFAULT 'S',
  `TOTAL_LIMITE_CREDITO_CLI` decimal(19,6) DEFAULT NULL,
  `ESPERMITE_DEUDA_CLI` varchar(1) DEFAULT NULL,
  `ESVARIOS_CLI` varchar(1) NOT NULL DEFAULT 'N' COMMENT 'S = cliente genérico de Varios: sus préstamos son apartados sin deuda',
  `TOTAL_DEUDA_CLI` decimal(19,6) DEFAULT NULL,
  `ESIVA_EXENTO_CLI` varchar(1) DEFAULT 'N',
  `ESINTRACOMUNITARIO_CLI` varchar(1) DEFAULT 'N',
  `ESREGIMENESPECIALAGRICOLA_CLI` varchar(1) DEFAULT 'N',
  `CODIGO_FP_CLI` varchar(20) DEFAULT NULL,
  `CODIGO_VENDEDOR_CLI` varchar(20) DEFAULT NULL COMMENT 'Vendedor asignado al cliente (fza_empleados)',
  `CODIGO_EMPBAN_CLI` varchar(8) DEFAULT NULL COMMENT 'Cuenta de la empresa (ingreso) por defecto — FK a fza_empresas_bancos',
  `TARIFA_ARTICULO_CLI` varchar(10) DEFAULT NULL,
  `SERIE_CON_CLI` varchar(8) DEFAULT NULL,
  `TEXTO_LEGAL_FACTURA_CLI` varchar(1000) DEFAULT NULL,
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  PRIMARY KEY (`CODIGO_CLI_CLI`),
  KEY `FT_CLI_RAZON` (`RAZON_SOCIAL_CLI`),
  KEY `IDX_CLIENTES_EMAIL` (`EMAIL_CLI`),
  KEY `IDX_CLIENTES_LISTADO` (`CODIGO_CLI_CLI`,`RAZON_SOCIAL_CLI`),
  KEY `IDX_CLI_VENDEDOR` (`CODIGO_VENDEDOR_CLI`),
  KEY `IDX_NIF_CLIENTE` (`EMAIL_CLI`),
  KEY `IDX_POBLACION_CLIENTE` (`NIF_CLI`),
  KEY `IDX_RAZONSOCIAL_CLIENTE` (`RAZON_SOCIAL_CLI`),
  KEY `IDX_REFERENCIA_CLIENTE` (`REFERENCIA_CLI`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_clientes_medidas`;
CREATE TABLE `fza_clientes_medidas` (
  `ID_CLMED` varchar(36) NOT NULL,
  `CODIGO_CLI_CLMED` varchar(20) NOT NULL,
  `FECHA_CLMED` date NOT NULL,
  `PERSONA_CLMED` varchar(100) NOT NULL,
  `ID_ORIGEN_CLMED` varchar(36) DEFAULT NULL,
  `MOTIVO_CLMED` varchar(500) NOT NULL DEFAULT '',
  `OBSERVACIONES_CLMED` text DEFAULT NULL,
  `INSTANTE_ALTA` datetime NOT NULL,
  `USUARIO_ALTA` varchar(50) NOT NULL,
  `INSTANTE_MODIF` datetime DEFAULT NULL,
  `USUARIO_MODIF` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`ID_CLMED`),
  UNIQUE KEY `UQ_CLMED_ORIGEN` (`ID_ORIGEN_CLMED`),
  KEY `IDX_CLMED_CLI_FECHA` (`CODIGO_CLI_CLMED`,`FECHA_CLMED`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_clientes_medidas_magnitudes`;
CREATE TABLE `fza_clientes_medidas_magnitudes` (
  `CODIGO_CMM` varchar(20) NOT NULL,
  `NOMBRE_CMM` varchar(100) NOT NULL,
  `UNIDAD_CMM` varchar(10) NOT NULL DEFAULT 'cm',
  `VALOR_MINIMO_CMM` decimal(10,2) NOT NULL DEFAULT 0.00,
  `VALOR_MAXIMO_CMM` decimal(10,2) NOT NULL DEFAULT 300.00,
  `ORDEN_CMM` int(11) NOT NULL DEFAULT 0,
  `ESACTIVO_CMM` varchar(1) NOT NULL DEFAULT 'S',
  `INSTANTE_ALTA` datetime NOT NULL,
  `USUARIO_ALTA` varchar(50) NOT NULL,
  `INSTANTE_MODIF` datetime DEFAULT NULL,
  `USUARIO_MODIF` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`CODIGO_CMM`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_clientes_medidas_valores`;
CREATE TABLE `fza_clientes_medidas_valores` (
  `ID_CLMED_CMVAL` varchar(36) NOT NULL,
  `CODIGO_CMM_CMVAL` varchar(20) NOT NULL,
  `NOMBRE_CMVAL` varchar(100) NOT NULL,
  `UNIDAD_CMVAL` varchar(10) NOT NULL,
  `VALOR_CMVAL` decimal(10,2) DEFAULT NULL,
  `INSTANTE_ALTA` datetime NOT NULL,
  `USUARIO_ALTA` varchar(50) NOT NULL,
  `INSTANTE_MODIF` datetime DEFAULT NULL,
  `USUARIO_MODIF` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`ID_CLMED_CMVAL`,`CODIGO_CMM_CMVAL`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_codigos_barras`;
CREATE TABLE `fza_codigos_barras` (
  `ID_CB` int(11) NOT NULL AUTO_INCREMENT,
  `CODIGO_BARRAS_CB` varchar(50) NOT NULL,
  `CODIGO_UNIDAD_CB` varchar(50) NOT NULL,
  `LOTE_CB` varchar(50) DEFAULT NULL,
  `TIPO_CODIGO_CB` varchar(20) DEFAULT 'EAN13',
  `ESPRINCIPAL_CB` varchar(1) DEFAULT 'N',
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  PRIMARY KEY (`ID_CB`),
  UNIQUE KEY `UQ_CB_CODIGO_BARRAS_CB` (`CODIGO_BARRAS_CB`),
  KEY `IDX_BARRAS_CB` (`CODIGO_BARRAS_CB`),
  KEY `IDX_CB_UNIDAD_LOTE` (`CODIGO_UNIDAD_CB`,`LOTE_CB`),
  KEY `IDX_UNIDAD_CB` (`CODIGO_UNIDAD_CB`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_compras_plantillas`;
CREATE TABLE `fza_compras_plantillas` (
  `CODIGO_SESPL` varchar(20) NOT NULL,
  `NOMBRE_SESPL` varchar(100) NOT NULL,
  `DESCRIPCION_SESPL` varchar(255) DEFAULT NULL,
  `CODIGO_PRV_SESPL` varchar(20) DEFAULT NULL COMMENT 'Plantilla específica de proveedor; null = global',
  `CODIGO_FAM_SESPL` varchar(20) DEFAULT NULL,
  `TIPO_IVA_SESPL` varchar(2) DEFAULT NULL,
  `PORCENTAJE_MARGEN_SESPL` decimal(7,4) DEFAULT NULL,
  `CODIGO_TAR_SESPL` varchar(20) DEFAULT NULL,
  `CODIGO_VAR_SESPL` varchar(20) DEFAULT NULL,
  `ID_VA_PIVOT_SESPL` varchar(20) DEFAULT NULL,
  `ID_AC_PIVOT_SESPL` int(11) DEFAULT NULL,
  `ID_VA_FILA_SESPL` varchar(20) DEFAULT NULL,
  `ID_AC_FILA_SESPL` int(11) DEFAULT NULL,
  `ESVAR_FIJA_SESPL` char(1) NOT NULL DEFAULT 'N',
  `ESACTIVA_SESPL` char(1) NOT NULL DEFAULT 'S',
  `INSTANTE_ALTA` datetime NOT NULL,
  `USUARIO_ALTA` varchar(50) NOT NULL,
  `INSTANTE_MODIF` datetime DEFAULT NULL,
  `USUARIO_MODIF` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`CODIGO_SESPL`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_compras_plantillas_kits`;
CREATE TABLE `fza_compras_plantillas_kits` (
  `CODIGO_SESPL_SESPLKIT` varchar(20) NOT NULL,
  `CODIGO_SESPLKIT` varchar(20) NOT NULL,
  `NOMBRE_SESPLKIT` varchar(100) NOT NULL,
  `ID_VA_DESTINO_SESPLKIT` varchar(20) NOT NULL,
  `ORDEN_SESPLKIT` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`CODIGO_SESPL_SESPLKIT`,`CODIGO_SESPLKIT`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_compras_plantillas_kits_det`;
CREATE TABLE `fza_compras_plantillas_kits_det` (
  `CODIGO_SESPL_SESPLKITD` varchar(20) NOT NULL,
  `CODIGO_SESPLKIT_SESPLKITD` varchar(20) NOT NULL,
  `VALOR_DESTINO_SESPLKITD` varchar(50) NOT NULL,
  `CANTIDAD_SESPLKITD` decimal(19,6) NOT NULL DEFAULT 0.000000,
  `ORDEN_SESPLKITD` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`CODIGO_SESPL_SESPLKITD`,`CODIGO_SESPLKIT_SESPLKITD`,`VALOR_DESTINO_SESPLKITD`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_compras_plantillas_props`;
CREATE TABLE `fza_compras_plantillas_props` (
  `CODIGO_SESPL_SESPLPROP` varchar(20) NOT NULL,
  `CODIGO_PROP_SESPLPROP` varchar(20) NOT NULL,
  `ESFIJO_SESPLPROP` char(1) NOT NULL DEFAULT 'N',
  `ID_PV_DEFECTO_SESPLPROP` int(11) DEFAULT NULL,
  `VALOR_DEFECTO_SESPLPROP` varchar(255) DEFAULT NULL,
  `ORDEN_SESPLPROP` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`CODIGO_SESPL_SESPLPROP`,`CODIGO_PROP_SESPLPROP`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_compras_sesiones`;
CREATE TABLE `fza_compras_sesiones` (
  `SERIE_SES` varchar(12) NOT NULL,
  `NUMERO_SES` varchar(12) NOT NULL,
  `FECHA_SES` date NOT NULL,
  `FECHA_TOPE_RECEPCION_SES` date DEFAULT NULL COMMENT 'Fecha limite prevista para recibir la mercancia',
  `ESTADO_SES` varchar(10) NOT NULL DEFAULT 'BORRADOR' COMMENT 'BORRADOR | CERRADA | ANULADA',
  `CODIGO_EMP_SES` varchar(20) NOT NULL,
  `CODIGO_PRV_SES` varchar(20) NOT NULL,
  `REF_PRV_SES` varchar(100) DEFAULT NULL COMMENT 'Referencia del proveedor (PO ext.)',
  `FORMA_PAGO_SES` varchar(200) DEFAULT NULL COMMENT 'Codigo de forma de pago (fza_formas_pago)',
  `CODIGO_FAM_SES` varchar(20) DEFAULT NULL COMMENT 'Familia objetivo de los artículos a crear',
  `CODIGO_ALM_SES` varchar(10) DEFAULT NULL COMMENT 'Almacén destino si se materializa albarán',
  `MONEDA_SES` varchar(5) NOT NULL DEFAULT 'EUR',
  `TIPO_IVA_SES` varchar(2) NOT NULL DEFAULT 'N',
  `CODIGO_IVA_SES` varchar(20) DEFAULT NULL,
  `ESVARIOS_TIPOS_IVA_SES` varchar(1) NOT NULL DEFAULT 'N',
  `PORCENTAJE_MARGEN_SES` decimal(7,4) DEFAULT NULL COMMENT '% margen comercial por defecto',
  `CODIGO_TAR_SES` varchar(20) DEFAULT NULL COMMENT 'Tarifa de salida sugerida',
  `ESPRECIOS_SIN_IVA_SES` char(1) NOT NULL DEFAULT 'S',
  `ESREDONDEO_VENTA_SES` char(1) NOT NULL DEFAULT 'N',
  `MULTIPLO_REDONDEO_SES` decimal(19,6) NOT NULL DEFAULT 0.000000,
  `AJUSTE_FINAL_SES` decimal(19,6) NOT NULL DEFAULT 0.000000,
  `CODIGO_VAR_SES` varchar(20) DEFAULT NULL COMMENT 'FK fza_variaciones — TC, TEMP, etc. (defecto)',
  `ID_VA_PIVOT_SES` varchar(20) DEFAULT NULL COMMENT 'Atributo cuyos valores pivotan a columnas (defecto)',
  `ID_AC_PIVOT_SES` int(11) DEFAULT NULL COMMENT 'FK fza_atributos_conjuntos para el eje pivot (defecto)',
  `ID_VA_FILA_SES` varchar(20) DEFAULT NULL COMMENT 'Atributo cuyos valores generan filas (defecto)',
  `ID_AC_FILA_SES` int(11) DEFAULT NULL COMMENT 'FK fza_atributos_conjuntos para el eje fila (defecto)',
  `ESVAR_FIJA_SES` char(1) NOT NULL DEFAULT 'N' COMMENT 'S=todas las líneas obligadas a usar la var por defecto. N=cada línea decide.',
  `PREFIJO_EAN_SES` varchar(7) DEFAULT NULL COMMENT 'Prefijo EAN13 (ej 841xxxx) — null = usa global',
  `INSTANTE_MATERIALIZA_SES` datetime DEFAULT NULL,
  `USUARIO_MATERIALIZA_SES` varchar(50) DEFAULT NULL,
  `ESGENERA_PEDIDO_SES` char(1) NOT NULL DEFAULT 'N',
  `ESGENERA_ALBARAN_SES` char(1) NOT NULL DEFAULT 'N',
  `ESFORMATO_DISTRIBUIDO_SES` varchar(1) NOT NULL DEFAULT 'N',
  `ESCOPIAR_DESCRIPCION_FAM_SES` varchar(1) NOT NULL DEFAULT 'S',
  `SERIE_PEDC_SES` varchar(12) DEFAULT NULL COMMENT 'FK al pedido de compra generado',
  `NUMERO_PEDC_SES` varchar(12) DEFAULT NULL,
  `SERIE_ALBC_SES` varchar(12) DEFAULT NULL COMMENT 'FK al albarán de compra generado',
  `NUMERO_ALBC_SES` varchar(12) DEFAULT NULL,
  `MENSAJE_ERROR_SES` varchar(2000) DEFAULT NULL,
  `CONTADOR_LINEAS_SES` int(11) NOT NULL DEFAULT 0,
  `COMENTARIOS_SES` varchar(1000) DEFAULT NULL,
  `INSTANTE_ALTA` datetime NOT NULL,
  `USUARIO_ALTA` varchar(50) NOT NULL,
  `INSTANTE_MODIF` datetime DEFAULT NULL,
  `USUARIO_MODIF` varchar(50) DEFAULT NULL,
  `ESPRECIO_POR_SKU_SES` char(1) NOT NULL DEFAULT 'N',
  `ID_PV_TEMPORADA_SES` int(11) DEFAULT NULL COMMENT 'FK logica fza_propiedades_valores.ID_PV_ARTPROP con ID_PROP_PV=TEMPORADA. Una unica temporada por sesion; se propaga a cada articulo creado en fza_articulos_propiedades.',
  `ESIVA_RECARGO_COMPRAS_SES` varchar(1) DEFAULT 'N',
  `ESIVA_EXENTO_INTRACOMUNITARIO_SES` varchar(1) NOT NULL DEFAULT 'N' COMMENT 'S = IVA exento por proveedor intracomunitario',
  `PORCENTAJE_IVAN_SES` decimal(19,6) DEFAULT NULL,
  `TOTAL_BASEI_IVAN_SES` decimal(18,6) DEFAULT NULL,
  `TOTAL_IVAN_SES` decimal(18,6) DEFAULT NULL,
  `PORCENTAJE_REN_SES` decimal(19,6) DEFAULT NULL,
  `TOTAL_REN_SES` decimal(18,6) DEFAULT NULL,
  `PORCENTAJE_IVAR_SES` decimal(19,6) DEFAULT NULL,
  `TOTAL_BASEI_IVAR_SES` decimal(18,6) DEFAULT NULL,
  `TOTAL_IVAR_SES` decimal(18,6) DEFAULT NULL,
  `PORCENTAJE_RER_SES` decimal(19,6) DEFAULT NULL,
  `TOTAL_RER_SES` decimal(18,6) DEFAULT NULL,
  `PORCENTAJE_IVAS_SES` decimal(19,6) DEFAULT NULL,
  `TOTAL_BASEI_IVAS_SES` decimal(18,6) DEFAULT NULL,
  `TOTAL_IVAS_SES` decimal(18,6) DEFAULT NULL,
  `PORCENTAJE_RES_SES` decimal(19,6) DEFAULT NULL,
  `TOTAL_RES_SES` decimal(18,6) DEFAULT NULL,
  `PORCENTAJE_IVAE_SES` decimal(19,6) DEFAULT NULL,
  `TOTAL_BASEI_IVAE_SES` decimal(18,6) DEFAULT NULL,
  `TOTAL_IVAE_SES` decimal(18,6) DEFAULT NULL,
  `PORCENTAJE_REE_SES` decimal(19,6) DEFAULT NULL,
  `TOTAL_REE_SES` decimal(18,6) DEFAULT NULL,
  `PORCENTAJE_RETENCION_SES` decimal(19,6) DEFAULT NULL,
  `TOTAL_RETENCION_SES` decimal(18,6) DEFAULT NULL,
  `TOTAL_BRUTO_SES` decimal(18,6) DEFAULT NULL,
  `PORCENTAJE_DTO_COMERCIAL_SES` decimal(19,6) DEFAULT 0.000000,
  `TOTAL_DTO_COMERCIAL_SES` decimal(18,6) DEFAULT 0.000000,
  `PORCENTAJE_DTO_FINANCIERO_SES` decimal(19,6) DEFAULT 0.000000,
  `TOTAL_DTO_FINANCIERO_SES` decimal(18,6) DEFAULT 0.000000,
  `TOTAL_BASES_SES` decimal(18,6) DEFAULT NULL,
  `TOTAL_IMPUESTOS_SES` decimal(18,6) DEFAULT NULL,
  `TOTAL_SES` decimal(18,6) DEFAULT NULL,
  `TOTAL_LIQUIDO_SES` decimal(18,6) DEFAULT NULL,
  `ESDESCRIPCION_BLANCO_SES` varchar(1) NOT NULL DEFAULT 'N',
  `ESVARIOS_TIPOS_VARIACION_SES` varchar(1) NOT NULL DEFAULT 'N',
  PRIMARY KEY (`SERIE_SES`,`NUMERO_SES`),
  KEY `IDX_SES_EMP_INSTANTE` (`CODIGO_EMP_SES`,`INSTANTE_ALTA`),
  KEY `IDX_SES_ESTADO` (`ESTADO_SES`),
  KEY `IDX_SES_FAM` (`CODIGO_FAM_SES`),
  KEY `IDX_SES_FECHA_TOPE_RECEPCION` (`FECHA_TOPE_RECEPCION_SES`),
  KEY `IDX_SES_PRV_FECHA` (`CODIGO_PRV_SES`,`FECHA_SES`),
  KEY `IDX_SES_TEMPORADA` (`ID_PV_TEMPORADA_SES`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_compras_sesiones_celdas`;
CREATE TABLE `fza_compras_sesiones_celdas` (
  `SERIE_SES_SESCEL` varchar(12) NOT NULL,
  `NUMERO_SES_SESCEL` varchar(12) NOT NULL,
  `LINEA_SES_SESCEL` int(11) NOT NULL,
  `ID_FILA_SES_SESCEL` int(11) NOT NULL,
  `ID_AV_PIVOT_SESCEL` int(11) NOT NULL COMMENT 'FK fza_atributos_valores del eje pivot (TALLA)',
  `CODIGO_ALM_SESCEL` varchar(10) NOT NULL DEFAULT '',
  `CANTIDAD_SESCEL` decimal(19,6) NOT NULL,
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL DEFAULT '',
  `INSTANTE_MODIF` datetime DEFAULT NULL,
  `USUARIO_MODIF` varchar(50) DEFAULT NULL,
  `LOTE_SESCEL` varchar(50) DEFAULT NULL,
  `CADUCIDAD_SESCEL` date DEFAULT NULL,
  `SERIES_SESCEL` text DEFAULT NULL,
  PRIMARY KEY (`SERIE_SES_SESCEL`,`NUMERO_SES_SESCEL`,`LINEA_SES_SESCEL`,`ID_FILA_SES_SESCEL`,`ID_AV_PIVOT_SESCEL`,`CODIGO_ALM_SESCEL`),
  KEY `IDX_SESCEL_ALM` (`CODIGO_ALM_SESCEL`),
  KEY `IDX_SESCEL_AV_PIVOT` (`ID_AV_PIVOT_SESCEL`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_compras_sesiones_codigos_barras`;
CREATE TABLE `fza_compras_sesiones_codigos_barras` (
  `SERIE_SES_SESCB` varchar(20) NOT NULL,
  `NUMERO_SES_SESCB` varchar(20) NOT NULL,
  `LINEA_SES_SESCB` int(11) NOT NULL,
  `ID_FILA_SES_SESCB` int(11) NOT NULL DEFAULT 0,
  `ID_AV_PIVOT_SESCB` int(11) NOT NULL DEFAULT 0,
  `CODIGO_BARRAS_SESCB` varchar(50) NOT NULL,
  `INSTANTE_ALTA` datetime NOT NULL,
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `INSTANTE_MODIF` datetime DEFAULT NULL,
  `USUARIO_MODIF` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`SERIE_SES_SESCB`,`NUMERO_SES_SESCB`,`LINEA_SES_SESCB`,`ID_FILA_SES_SESCB`,`ID_AV_PIVOT_SESCB`),
  UNIQUE KEY `UQ_SESCB_SES_CODIGO` (`SERIE_SES_SESCB`,`NUMERO_SES_SESCB`,`CODIGO_BARRAS_SESCB`),
  KEY `IDX_SESCB_CODIGO_BARRAS` (`CODIGO_BARRAS_SESCB`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_compras_sesiones_documentos`;
CREATE TABLE `fza_compras_sesiones_documentos` (
  `SERIE_SES_SESDOC` varchar(12) NOT NULL,
  `NUMERO_SES_SESDOC` varchar(12) NOT NULL,
  `TIPO_DOC_SESDOC` varchar(4) NOT NULL COMMENT 'PEDC = pedido de compra, ALBC = albaran de compra',
  `CODIGO_ALM_SESDOC` varchar(10) NOT NULL COMMENT 'Almacen al que aplica este documento',
  `CODIGO_EMP_SESDOC` varchar(20) DEFAULT NULL,
  `SERIE_SESDOC` varchar(12) NOT NULL COMMENT 'Serie del documento generado (fza_pedidos_compra / _albaranes)',
  `NUMERO_SESDOC` varchar(12) NOT NULL COMMENT 'Numero del documento generado',
  `INSTANTE_ALTA` datetime NOT NULL,
  `USUARIO_ALTA` varchar(50) NOT NULL,
  PRIMARY KEY (`SERIE_SES_SESDOC`,`NUMERO_SES_SESDOC`,`TIPO_DOC_SESDOC`,`CODIGO_ALM_SESDOC`),
  KEY `IDX_SESDOC_DOC` (`TIPO_DOC_SESDOC`,`SERIE_SESDOC`,`NUMERO_SESDOC`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_compras_sesiones_fotos`;
CREATE TABLE `fza_compras_sesiones_fotos` (
  `SERIE_SES_CSF` varchar(12) NOT NULL,
  `NUMERO_SES_CSF` varchar(12) NOT NULL,
  `LINEA_CSF` int(11) NOT NULL,
  `CODIGO_UNIDAD_CSF` varchar(50) NOT NULL DEFAULT '',
  `CODIGO_ART_TENTATIVO_CSF` varchar(20) NOT NULL,
  `NOMBRE_FOT_CSF` varchar(255) NOT NULL,
  `EXTENSION_ORIGEN_CSF` varchar(10) NOT NULL DEFAULT 'png',
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  PRIMARY KEY (`SERIE_SES_CSF`,`NUMERO_SES_CSF`,`LINEA_CSF`,`CODIGO_UNIDAD_CSF`),
  KEY `IDX_CSF_LIN` (`SERIE_SES_CSF`,`NUMERO_SES_CSF`,`LINEA_CSF`),
  KEY `IDX_CSF_TENT` (`CODIGO_ART_TENTATIVO_CSF`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_compras_sesiones_kits`;
CREATE TABLE `fza_compras_sesiones_kits` (
  `SERIE_SES_SESKIT` varchar(12) NOT NULL,
  `NUMERO_SES_SESKIT` varchar(12) NOT NULL,
  `CODIGO_SESKIT` varchar(20) NOT NULL COMMENT 'CURVA-STD, MUESTRA, etc.',
  `NOMBRE_SESKIT` varchar(100) NOT NULL,
  `DESCRIPCION_SESKIT` varchar(255) DEFAULT NULL,
  `ID_VA_DESTINO_SESKIT` varchar(20) NOT NULL COMMENT 'Atributo destino del kit, normalmente el pivot (TAL)',
  `CODIGO_PRV_SESKIT` varchar(20) DEFAULT NULL COMMENT 'Si el kit nace de plantilla del proveedor',
  `ORDEN_SESKIT` int(11) NOT NULL DEFAULT 0,
  `INSTANTE_ALTA` datetime NOT NULL,
  `USUARIO_ALTA` varchar(50) NOT NULL,
  `INSTANTE_MODIF` datetime DEFAULT NULL,
  `USUARIO_MODIF` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`SERIE_SES_SESKIT`,`NUMERO_SES_SESKIT`,`CODIGO_SESKIT`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_compras_sesiones_kits_det`;
CREATE TABLE `fza_compras_sesiones_kits_det` (
  `SERIE_SES_SESKITD` varchar(12) NOT NULL,
  `NUMERO_SES_SESKITD` varchar(12) NOT NULL,
  `CODIGO_SESKIT_SESKITD` varchar(20) NOT NULL,
  `VALOR_DESTINO_SESKITD` varchar(50) NOT NULL COMMENT 'Valor del atributo destino: "38", "M", etc.',
  `CANTIDAD_SESKITD` decimal(19,6) NOT NULL DEFAULT 0.000000,
  `ORDEN_SESKITD` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`SERIE_SES_SESKITD`,`NUMERO_SES_SESKITD`,`CODIGO_SESKIT_SESKITD`,`VALOR_DESTINO_SESKITD`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_compras_sesiones_lineas`;
CREATE TABLE `fza_compras_sesiones_lineas` (
  `SERIE_SES_SESLIN` varchar(12) NOT NULL,
  `NUMERO_SES_SESLIN` varchar(12) NOT NULL,
  `LINEA_SESLIN` int(11) NOT NULL,
  `CODIGO_ART_TENTATIVO_SESLIN` varchar(20) NOT NULL COMMENT 'Lo que el usuario teclea; se valida contra fza_articulos',
  `DESCRIPCION_SESLIN` varchar(1000) NOT NULL,
  `CODIGO_FAM_SESLIN` varchar(20) DEFAULT NULL COMMENT 'Override sobre la familia de cabecera; null = hereda',
  `TIPO_LINEA_SESLIN` varchar(10) NOT NULL DEFAULT 'MATRIZ' COMMENT 'MATRIZ | ESCALAR | SERVICIO | KIT',
  `TIPO_ART_SESLIN` varchar(10) NOT NULL DEFAULT 'ESTANDAR' COMMENT 'Derivado de TIPO_LINEA: SERVICIO=>SERVICIO, KIT=>KIT, resto=>ESTANDAR',
  `TIPO_IVA_SESLIN` varchar(2) DEFAULT NULL COMMENT 'Override sobre cabecera',
  `TIPO_CANTIDAD_SESLIN` varchar(20) NOT NULL DEFAULT 'Uds',
  `ESTRAZABLE_SESLIN` char(1) NOT NULL DEFAULT 'N',
  `CODIGO_VAR_SESLIN` varchar(20) DEFAULT NULL COMMENT 'Override sobre cabecera, null = hereda',
  `ID_VA_PIVOT_SESLIN` varchar(20) DEFAULT NULL,
  `ID_AC_PIVOT_SESLIN` int(11) DEFAULT NULL,
  `ID_VA_FILA_SESLIN` varchar(20) DEFAULT NULL,
  `ID_AC_FILA_SESLIN` int(11) DEFAULT NULL,
  `CANTIDAD_ESCALAR_SESLIN` decimal(19,6) DEFAULT NULL,
  `ESDUPLICADO_SESLIN` char(1) NOT NULL DEFAULT 'N',
  `ACCION_DUPLICADO_SESLIN` varchar(10) DEFAULT NULL COMMENT 'REUSAR | RENOMBRAR | NULL',
  `CODIGO_ART_REUSAR_SESLIN` varchar(20) DEFAULT NULL COMMENT 'Si ACCION=REUSAR, código del artículo a reutilizar',
  `PRECIO_COMPRA_SESLIN` decimal(19,6) NOT NULL DEFAULT 0.000000,
  `PORCENTAJE_MARGEN_SESLIN` decimal(7,4) DEFAULT NULL,
  `PRECIO_VENTA_SESLIN` decimal(19,6) DEFAULT NULL COMMENT 'Calculado pero override-able',
  `REF_PRV_SESLIN` varchar(100) DEFAULT NULL,
  `TOTAL_UNIDADES_SESLIN` decimal(19,6) NOT NULL DEFAULT 0.000000 COMMENT 'Suma de celdas (read-only, lo refresca el form)',
  `TOTAL_LINEA_SESLIN` decimal(19,6) NOT NULL DEFAULT 0.000000 COMMENT 'TOTAL_UNIDADES * PRECIO_COMPRA',
  `INSTANTE_ALTA` datetime NOT NULL,
  `USUARIO_ALTA` varchar(50) NOT NULL,
  `INSTANTE_MODIF` datetime DEFAULT NULL,
  `USUARIO_MODIF` varchar(50) DEFAULT NULL,
  `COLOR_TEXTO_SESLIN` varchar(100) DEFAULT NULL COMMENT 'Texto libre del color/atributo no-pivot de la linea (p. ej. AZUL TURQUESA PROV-XYZ). Para la prueba 01 del grid plano.',
  `CODIGO_ATB_COLOR_SESLIN` varchar(100) DEFAULT NULL COMMENT 'CODIGO_ATB del color basico asociado a la linea (ID_VA_ATB=''CO''). NULL = sin mapeo.',
  `PESTANA_TEXTO_SESLIN` varchar(100) DEFAULT NULL COMMENT 'Valor de pestañas de la línea (copa); NULL = sin pestañas',
  `PORCENTAJE_DTO_SESLIN` decimal(7,4) DEFAULT 0.0000,
  PRIMARY KEY (`SERIE_SES_SESLIN`,`NUMERO_SES_SESLIN`,`LINEA_SESLIN`),
  KEY `IDX_SESLIN_ART_TENT` (`CODIGO_ART_TENTATIVO_SESLIN`),
  KEY `IDX_SESLIN_ATB_COLOR` (`CODIGO_ATB_COLOR_SESLIN`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_compras_sesiones_lineas_filas`;
CREATE TABLE `fza_compras_sesiones_lineas_filas` (
  `SERIE_SES_SESFIL` varchar(12) NOT NULL,
  `NUMERO_SES_SESFIL` varchar(12) NOT NULL,
  `LINEA_SES_SESFIL` int(11) NOT NULL,
  `ID_FILA_SESFIL` int(11) NOT NULL COMMENT 'Numerador 1..N dentro de la línea',
  `ORDEN_SESFIL` int(11) NOT NULL DEFAULT 0,
  `ETIQUETA_TEXTO_SESFIL` varchar(100) DEFAULT NULL COMMENT 'Etiqueta libre tecleada por el usuario cuando la sesion usa eje fila libre (ID_AC_FILA_SES IS NULL). Si esta NULL la etiqueta viene de _filas_atr (modo conjunto).',
  `INSTANTE_ALTA` datetime NOT NULL,
  `USUARIO_ALTA` varchar(50) NOT NULL,
  PRIMARY KEY (`SERIE_SES_SESFIL`,`NUMERO_SES_SESFIL`,`LINEA_SES_SESFIL`,`ID_FILA_SESFIL`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_compras_sesiones_lineas_filas_atr`;
CREATE TABLE `fza_compras_sesiones_lineas_filas_atr` (
  `SERIE_SES_SESFILAT` varchar(12) NOT NULL,
  `NUMERO_SES_SESFILAT` varchar(12) NOT NULL,
  `LINEA_SES_SESFILAT` int(11) NOT NULL,
  `ID_FILA_SESFILAT` int(11) NOT NULL,
  `ID_VA_SESFILAT` varchar(20) NOT NULL COMMENT 'Atributo: CO, MAT, TEMP...',
  `ID_AV_SESFILAT` int(11) NOT NULL COMMENT 'FK fza_atributos_valores',
  PRIMARY KEY (`SERIE_SES_SESFILAT`,`NUMERO_SES_SESFILAT`,`LINEA_SES_SESFILAT`,`ID_FILA_SESFILAT`,`ID_VA_SESFILAT`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_compras_sesiones_lineas_props`;
CREATE TABLE `fza_compras_sesiones_lineas_props` (
  `SERIE_SES_SESLPROP` varchar(12) NOT NULL,
  `NUMERO_SES_SESLPROP` varchar(12) NOT NULL,
  `LINEA_SES_SESLPROP` int(11) NOT NULL,
  `CODIGO_PROP_SESLPROP` varchar(20) NOT NULL,
  `ID_PV_SESLPROP` int(11) DEFAULT NULL,
  `VALOR_LIBRE_SESLPROP` varchar(255) DEFAULT NULL,
  `INSTANTE_ALTA` datetime NOT NULL,
  `USUARIO_ALTA` varchar(50) NOT NULL,
  PRIMARY KEY (`SERIE_SES_SESLPROP`,`NUMERO_SES_SESLPROP`,`LINEA_SES_SESLPROP`,`CODIGO_PROP_SESLPROP`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_compras_sesiones_lineas_skus_precios`;
CREATE TABLE `fza_compras_sesiones_lineas_skus_precios` (
  `SERIE_SES_SESLINSKU` varchar(12) NOT NULL,
  `NUMERO_SES_SESLINSKU` varchar(12) NOT NULL,
  `LINEA_SES_SESLINSKU` int(11) NOT NULL,
  `ID_FILA_SES_SESLINSKU` int(11) NOT NULL,
  `ID_AV_PIVOT_SESLINSKU` int(11) NOT NULL,
  `PRECIO_COMPRA_SESLINSKU` decimal(19,6) DEFAULT NULL COMMENT 'Override del precio de coste para este SKU. NULL = hereda de la linea.',
  `PRECIO_VENTA_SESLINSKU` decimal(19,6) DEFAULT NULL COMMENT 'Override del precio de venta para este SKU. NULL = hereda de la linea.',
  `INSTANTE_ALTA` datetime NOT NULL,
  `USUARIO_ALTA` varchar(50) NOT NULL,
  `INSTANTE_MODIF` datetime DEFAULT NULL,
  `USUARIO_MODIF` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`SERIE_SES_SESLINSKU`,`NUMERO_SES_SESLINSKU`,`LINEA_SES_SESLINSKU`,`ID_FILA_SES_SESLINSKU`,`ID_AV_PIVOT_SESLINSKU`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_compras_sesiones_props`;
CREATE TABLE `fza_compras_sesiones_props` (
  `SERIE_SES_SESPROP` varchar(12) NOT NULL,
  `NUMERO_SES_SESPROP` varchar(12) NOT NULL,
  `CODIGO_PROP_SESPROP` varchar(20) NOT NULL COMMENT 'FK fza_propiedades',
  `ESFIJO_SESPROP` char(1) NOT NULL DEFAULT 'N' COMMENT 'S=todas las líneas heredan obligatoriamente',
  `ID_PV_DEFECTO_SESPROP` int(11) DEFAULT NULL COMMENT 'Si tipo LISTA, FK fza_propiedades_valores',
  `VALOR_DEFECTO_SESPROP` varchar(255) DEFAULT NULL COMMENT 'Si tipo TEXTO/NUMERO/BOOL',
  `ORDEN_SESPROP` int(11) NOT NULL DEFAULT 0,
  `INSTANTE_ALTA` datetime NOT NULL,
  `USUARIO_ALTA` varchar(50) NOT NULL,
  PRIMARY KEY (`SERIE_SES_SESPROP`,`NUMERO_SES_SESPROP`,`CODIGO_PROP_SESPROP`),
  KEY `IDX_SESPROP_PROP` (`CODIGO_PROP_SESPROP`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_config_campos`;
CREATE TABLE `fza_config_campos` (
  `TABLA_OBJETIVO_CC` varchar(60) NOT NULL,
  `OBJETIVO_CC` varchar(60) NOT NULL,
  `TITULO_VISUAL_CC` varchar(100) DEFAULT NULL COMMENT 'El texto bonito para el usuario',
  `ANCHO_COLUMNA_CC` int(11) DEFAULT 100 COMMENT 'Ancho en píxeles',
  `ORDEN_VISUAL_CC` int(11) DEFAULT 0 COMMENT 'Para ordenar columnas si quisieras',
  `VISIBLE_CC` varchar(1) DEFAULT 'S',
  PRIMARY KEY (`TABLA_OBJETIVO_CC`,`OBJETIVO_CC`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_contadores`;
CREATE TABLE `fza_contadores` (
  `TIPO_DOC_CON` varchar(2) NOT NULL,
  `EMPRESA_CON` varchar(10) NOT NULL,
  `SERIE_CON` varchar(12) NOT NULL,
  `CON` bigint(20) NOT NULL,
  `NUM_DIGITOS_CON` int(11) NOT NULL DEFAULT 0,
  `ESACTIVO_CON` varchar(1) NOT NULL DEFAULT 'S',
  `DEFAULT_CON` varchar(1) DEFAULT 'N',
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  PRIMARY KEY (`TIPO_DOC_CON`,`EMPRESA_CON`,`SERIE_CON`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_depositos_cliente`;
CREATE TABLE `fza_depositos_cliente` (
  `ID_DEPOSITO_DEP` varchar(20) NOT NULL,
  `CODIGO_EMP_DEP` varchar(20) NOT NULL,
  `CODIGO_CLI_DEP` varchar(20) NOT NULL,
  `CODIGO_ART_DEP` varchar(50) NOT NULL,
  `CODIGO_UNIDAD_DEP` varchar(50) NOT NULL COMMENT 'SKU o Código de Barras único de la talla/color',
  `CODIGO_ALM_DEP` varchar(10) DEFAULT NULL COMMENT 'Almacén de depósito donde está físicamente la prenda',
  `PRECIO_VENTA_DEP` decimal(19,6) NOT NULL DEFAULT 0.000000 COMMENT 'Precio Unidad original de la venta',
  `IMPORTE_ANTICIPO_DEP` decimal(19,6) NOT NULL DEFAULT 0.000000 COMMENT 'Dinero acumulado entregado a cuenta hasta la fecha',
  `ESTADO_DEP` varchar(15) NOT NULL DEFAULT 'PENDIENTE' COMMENT 'Valores: PENDIENTE, CERRADO',
  `ESAPARTADO_DEP` varchar(1) NOT NULL DEFAULT 'N' COMMENT 'S = apartado del cliente de Varios: no suma deuda',
  `NOMBRE_CONTACTO_DEP` varchar(100) DEFAULT NULL COMMENT 'Nombre de quien aparta la prenda',
  `TELEFONO_CONTACTO_DEP` varchar(30) DEFAULT NULL COMMENT 'Teléfono de quien aparta la prenda',
  `FECHA_CREACION_DEP` datetime NOT NULL DEFAULT current_timestamp(),
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  `TIPO_IVA_DEP` char(1) NOT NULL DEFAULT 'N',
  `PORCENTAJE_IVA_DEP` decimal(19,6) NOT NULL DEFAULT 0.000000,
  `ESIMP_INCL_DEP` char(1) NOT NULL DEFAULT 'S',
  `CANTIDAD_PENDIENTE_DEP` decimal(19,6) DEFAULT NULL COMMENT 'Cantidad de artículos comprados',
  `FECHA_ENTREGA_DEP` date DEFAULT NULL,
  `CODIGO_CAJA_DEP` varchar(10) DEFAULT NULL COMMENT 'Caja donde se realizó el depósito',
  `NUMERO_OPERACION_DEP` varchar(20) DEFAULT NULL COMMENT 'Número de operación de caja en la creación',
  `EMPRESA_CANCEL_DEP` varchar(20) DEFAULT NULL COMMENT 'Empresa donde se canceló el depósito',
  `ALMACEN_CANCEL_DEP` varchar(10) DEFAULT NULL COMMENT 'Almacén donde se canceló el depósito',
  `CAJA_CANCEL_DEP` varchar(10) DEFAULT NULL COMMENT 'Caja donde se canceló el depósito',
  `NUMERO_OPERACION_CANCEL_DEP` varchar(20) DEFAULT NULL COMMENT 'Número de operación de la cancelación',
  `LOTE_DEP` varchar(50) DEFAULT NULL,
  `FECHA_CADUCIDAD_DEP` date DEFAULT NULL,
  PRIMARY KEY (`ID_DEPOSITO_DEP`),
  KEY `IDX_DEP_CLIENTE` (`CODIGO_CLI_DEP`,`ESTADO_DEP`),
  KEY `IDX_DEP_OP_ALTA` (`CODIGO_EMP_DEP`,`CODIGO_ALM_DEP`,`CODIGO_CAJA_DEP`,`NUMERO_OPERACION_DEP`),
  KEY `IDX_DEP_OP_CANCEL` (`EMPRESA_CANCEL_DEP`,`ALMACEN_CANCEL_DEP`,`CAJA_CANCEL_DEP`,`NUMERO_OPERACION_CANCEL_DEP`),
  KEY `IDX_DEP_OP_FECHA` (`CODIGO_EMP_DEP`,`CODIGO_ALM_DEP`,`CODIGO_CAJA_DEP`,`FECHA_CREACION_DEP`),
  KEY `IDX_DEP_UNIDAD` (`CODIGO_UNIDAD_DEP`,`ESTADO_DEP`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_devoluciones_compra`;
CREATE TABLE `fza_devoluciones_compra` (
  `NUMERO_DEVC` varchar(20) NOT NULL,
  `SERIE_DEVC` varchar(20) NOT NULL,
  `FECHA_DEVC` date DEFAULT NULL,
  `INSTANTE_MOVIMIENTO_DEVC` datetime DEFAULT NULL COMMENT 'Instante efectivo del movimiento de stock',
  `ESTADO_DEVC` varchar(20) DEFAULT 'ABIERTO' COMMENT 'ABIERTO, FACTURADO, CANCELADO',
  `NUMERO_PED_DEVC` varchar(20) DEFAULT NULL COMMENT 'FK logica a fza_pedidos_compra',
  `SERIE_PED_DEVC` varchar(20) DEFAULT NULL,
  `NUMERO_FAC_DEVC` varchar(20) DEFAULT NULL COMMENT 'FK logica a fza_facturas_compras',
  `SERIE_FAC_DEVC` varchar(20) DEFAULT NULL,
  `CODIGO_EMP_DEVC` varchar(8) DEFAULT NULL,
  `RAZON_SOCIAL_EMPRESA_DEVC` varchar(200) DEFAULT NULL,
  `NIF_EMPRESA_DEVC` varchar(50) DEFAULT NULL,
  `MOVIL_EMPRESA_DEVC` varchar(40) DEFAULT NULL,
  `EMAIL_EMPRESA_DEVC` varchar(200) DEFAULT NULL,
  `DIRECCION1_EMPRESA_DEVC` varchar(200) DEFAULT NULL,
  `DIRECCION2_EMPRESA_DEVC` varchar(200) DEFAULT NULL,
  `POBLACION_EMPRESA_DEVC` varchar(200) DEFAULT NULL,
  `PROVINCIA_EMPRESA_DEVC` varchar(200) DEFAULT NULL,
  `CODIGO_PAI_EMPRESA_DEVC` varchar(3) DEFAULT '724',
  `NOMBRE_PAI_EMPRESA_DEVC` varchar(150) DEFAULT 'Espana',
  `CODIGO_POSTAL_EMPRESA_DEVC` varchar(15) DEFAULT NULL,
  `CODIGO_PRV_DEVC` varchar(20) DEFAULT NULL COMMENT 'FK logica a fza_proveedores',
  `RAZON_SOCIAL_PRV_DEVC` varchar(200) DEFAULT NULL,
  `NIF_PRV_DEVC` varchar(50) DEFAULT NULL,
  `MOVIL_PRV_DEVC` varchar(40) DEFAULT NULL,
  `EMAIL_PRV_DEVC` varchar(200) DEFAULT NULL,
  `DIRECCION1_PRV_DEVC` varchar(200) DEFAULT NULL,
  `DIRECCION2_PRV_DEVC` varchar(200) DEFAULT NULL,
  `POBLACION_PRV_DEVC` varchar(200) DEFAULT NULL,
  `PROVINCIA_PRV_DEVC` varchar(200) DEFAULT NULL,
  `CODIGO_PAI_PRV_DEVC` varchar(3) DEFAULT '724',
  `NOMBRE_PAI_PRV_DEVC` varchar(150) DEFAULT 'Espana',
  `CODIGO_POSTAL_PRV_DEVC` varchar(15) DEFAULT NULL,
  `REF_PROVEEDOR_DEVC` varchar(50) DEFAULT NULL COMMENT 'Numero de devolucion segun el proveedor',
  `CODIGO_ALM_DEVC` varchar(10) DEFAULT NULL COMMENT 'Almacen destino de la entrada de mercancia',
  `TRANSPORTISTA_DEVC` varchar(200) DEFAULT NULL,
  `CODIGO_IVA_DEVC` varchar(20) DEFAULT NULL,
  `ESIVA_RECARGO_COMPRAS_DEVC` varchar(1) DEFAULT 'N',
  `ESIVA_EXENTO_INTRACOMUNITARIO_DEVC` varchar(1) NOT NULL DEFAULT 'N' COMMENT 'S = IVA exento por proveedor intracomunitario',
  `PORCENTAJE_IVAN_DEVC` decimal(19,6) DEFAULT NULL,
  `TOTAL_BASEI_IVAN_DEVC` decimal(18,6) DEFAULT NULL,
  `TOTAL_IVAN_DEVC` decimal(18,6) DEFAULT NULL,
  `PORCENTAJE_REN_DEVC` decimal(19,6) DEFAULT NULL,
  `TOTAL_REN_DEVC` decimal(18,6) DEFAULT NULL,
  `PORCENTAJE_IVAR_DEVC` decimal(19,6) DEFAULT NULL,
  `TOTAL_BASEI_IVAR_DEVC` decimal(18,6) DEFAULT NULL,
  `TOTAL_IVAR_DEVC` decimal(18,6) DEFAULT NULL,
  `PORCENTAJE_RER_DEVC` decimal(19,6) DEFAULT NULL,
  `TOTAL_RER_DEVC` decimal(18,6) DEFAULT NULL,
  `PORCENTAJE_IVAS_DEVC` decimal(19,6) DEFAULT NULL,
  `TOTAL_BASEI_IVAS_DEVC` decimal(18,6) DEFAULT NULL,
  `TOTAL_IVAS_DEVC` decimal(18,6) DEFAULT NULL,
  `PORCENTAJE_RES_DEVC` decimal(19,6) DEFAULT NULL,
  `TOTAL_RES_DEVC` decimal(18,6) DEFAULT NULL,
  `PORCENTAJE_IVAE_DEVC` decimal(19,6) DEFAULT NULL,
  `TOTAL_BASEI_IVAE_DEVC` decimal(18,6) DEFAULT NULL,
  `TOTAL_IVAE_DEVC` decimal(18,6) DEFAULT NULL,
  `PORCENTAJE_REE_DEVC` decimal(19,6) DEFAULT NULL,
  `TOTAL_REE_DEVC` decimal(18,6) DEFAULT NULL,
  `TOTAL_BASES_DEVC` decimal(18,6) DEFAULT NULL,
  `TOTAL_IMPUESTOS_DEVC` decimal(18,6) DEFAULT NULL,
  `PORCENTAJE_RETENCION_DEVC` decimal(19,6) DEFAULT NULL,
  `TOTAL_RETENCION_DEVC` decimal(18,6) DEFAULT NULL,
  `TOTAL_BRUTO_DEVC` decimal(18,6) DEFAULT 0.000000,
  `PORCENTAJE_DTO_COMERCIAL_DEVC` decimal(19,6) DEFAULT 0.000000,
  `TOTAL_DTO_COMERCIAL_DEVC` decimal(18,6) DEFAULT 0.000000,
  `PORCENTAJE_DTO_FINANCIERO_DEVC` decimal(19,6) DEFAULT 0.000000,
  `TOTAL_DTO_FINANCIERO_DEVC` decimal(18,6) DEFAULT 0.000000,
  `TOTAL_LIQUIDO_DEVC` decimal(18,6) DEFAULT NULL,
  `FORMA_PAGO_DEVC` varchar(200) DEFAULT NULL,
  `CONTADOR_LINEAS_DEVC` varchar(8) DEFAULT NULL,
  `COMENTARIOS_DEVC` varchar(1000) DEFAULT '',
  `OBSERVACIONES_DEVC` varchar(2000) DEFAULT '',
  `ESPIVOTE_HORIZONTAL_DEVC` varchar(1) NOT NULL DEFAULT 'N',
  `CODIGO_TAR_DEVC` varchar(20) DEFAULT NULL,
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  PRIMARY KEY (`NUMERO_DEVC`,`SERIE_DEVC`),
  KEY `IDX_DEVC_EMPRESA` (`CODIGO_EMP_DEVC`),
  KEY `IDX_DEVC_EMP_INSTANTE` (`CODIGO_EMP_DEVC`,`INSTANTE_ALTA`),
  KEY `IDX_DEVC_ESTADO` (`ESTADO_DEVC`),
  KEY `IDX_DEVC_PEDIDO` (`SERIE_PED_DEVC`,`NUMERO_PED_DEVC`),
  KEY `IDX_DEVC_PROVEEDOR_FECHA` (`CODIGO_PRV_DEVC`,`FECHA_DEVC`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_devoluciones_compra_celdas`;
CREATE TABLE `fza_devoluciones_compra_celdas` (
  `SERIE_DEVC_DEVCCEL` varchar(20) NOT NULL,
  `NUMERO_DEVC_DEVCCEL` varchar(20) NOT NULL,
  `LINEA_DEVC_DEVCCEL` varchar(4) NOT NULL,
  `ID_FILA_DEVC_DEVCCEL` int(11) NOT NULL DEFAULT 1,
  `ID_AV_PIVOT_DEVCCEL` int(11) NOT NULL COMMENT 'ID del valor de atributo (talla) que pivota',
  `CANTIDAD_DEVCCEL` decimal(19,6) NOT NULL DEFAULT 0.000000,
  `CODIGO_ALM_DEVCCEL` varchar(10) DEFAULT NULL,
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  PRIMARY KEY (`SERIE_DEVC_DEVCCEL`,`NUMERO_DEVC_DEVCCEL`,`LINEA_DEVC_DEVCCEL`,`ID_FILA_DEVC_DEVCCEL`,`ID_AV_PIVOT_DEVCCEL`),
  KEY `IDX_DEVCCEL_LINEA` (`SERIE_DEVC_DEVCCEL`,`NUMERO_DEVC_DEVCCEL`,`LINEA_DEVC_DEVCCEL`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_devoluciones_compra_lineas`;
CREATE TABLE `fza_devoluciones_compra_lineas` (
  `NUMERO_DEVC_DEVCLIN` varchar(20) NOT NULL,
  `SERIE_DEVC_DEVCLIN` varchar(20) NOT NULL,
  `LINEA_DEVCLIN` varchar(4) NOT NULL,
  `NUMERO_PEDC_DEVCLIN` varchar(20) DEFAULT NULL,
  `SERIE_PEDC_DEVCLIN` varchar(20) DEFAULT NULL,
  `LINEA_PEDC_DEVCLIN` varchar(4) DEFAULT NULL COMMENT 'Linea de origen en fza_pedidos_compra_lineas',
  `CODIGO_ART_DEVCLIN` varchar(20) DEFAULT NULL,
  `CODIGO_UNIDAD_DEVCLIN` varchar(50) DEFAULT NULL COMMENT 'SKU del articulo',
  `REF_PRV_DEVCLIN` varchar(100) DEFAULT NULL,
  `ID_AC_PIVOT_DEVCLIN` int(11) DEFAULT NULL COMMENT 'Conjunto de atributos pivot (fza_atributos_conjuntos)',
  `CODIGO_FAM_DEVCLIN` varchar(20) DEFAULT NULL,
  `NOMBRE_FAM_DEVCLIN` varchar(200) DEFAULT NULL,
  `DESCRIPCION_ARTICULO_DEVCLIN` varchar(100) DEFAULT NULL,
  `TIPO_CANTIDAD_ARTICULO_DEVCLIN` varchar(20) DEFAULT 'Uds',
  `CANTIDAD_DEVCLIN` decimal(19,6) DEFAULT 1.000000,
  `TOTAL_UNIDADES_DEVCLIN` decimal(19,6) DEFAULT 0.000000 COMMENT 'SUM(CANTIDAD) de celdas cuando ID_AC_PIVOT esta fijado',
  `TIPO_IVA_ARTICULO_DEVCLIN` varchar(2) DEFAULT 'N',
  `PORCENTAJE_IVA_DEVCLIN` decimal(19,6) DEFAULT 0.000000,
  `PRECIO_COMPRA_SIVA_ARTICULO_DEVCLIN` decimal(19,6) DEFAULT 0.000000,
  `PRECIO_COMPRA_CIVA_ARTICULO_DEVCLIN` decimal(19,6) DEFAULT 0.000000,
  `TOTAL_DEVCLIN` decimal(19,6) DEFAULT 0.000000,
  `CODIGO_ALMACEN_DEVCLIN` varchar(10) DEFAULT NULL,
  `LOTE_DEVCLIN` varchar(50) DEFAULT NULL,
  `FECHA_CADUCIDAD_DEVCLIN` date DEFAULT NULL,
  `DESCRIPCION_VARIACION_DEVCLIN` varchar(200) DEFAULT NULL,
  `ESFACTURADA_DEVCLIN` varchar(1) DEFAULT 'N',
  `NUMERO_FAC_DEVCLIN` varchar(20) DEFAULT NULL,
  `SERIE_FAC_DEVCLIN` varchar(20) DEFAULT NULL,
  `LINEA_FAC_DEVCLIN` varchar(4) DEFAULT NULL,
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  `ATTR1_VALOR_DEVCLIN` varchar(100) NOT NULL DEFAULT '',
  `ATTR1_NOMBRE_DEVCLIN` varchar(100) NOT NULL DEFAULT '',
  `ATTR2_VALOR_DEVCLIN` varchar(100) NOT NULL DEFAULT '',
  `ATTR2_NOMBRE_DEVCLIN` varchar(100) NOT NULL DEFAULT '',
  `ATTR3_VALOR_DEVCLIN` varchar(100) NOT NULL DEFAULT '',
  `ATTR3_NOMBRE_DEVCLIN` varchar(100) NOT NULL DEFAULT '',
  `ATTR4_VALOR_DEVCLIN` varchar(100) NOT NULL DEFAULT '',
  `ATTR4_NOMBRE_DEVCLIN` varchar(100) NOT NULL DEFAULT '',
  `ATTR5_VALOR_DEVCLIN` varchar(100) NOT NULL DEFAULT '',
  `ATTR5_NOMBRE_DEVCLIN` varchar(100) NOT NULL DEFAULT '',
  `NUM_ATRIBUTOS_DEVCLIN` int(11) NOT NULL DEFAULT 0 COMMENT 'Atributos requeridos del articulo',
  PRIMARY KEY (`NUMERO_DEVC_DEVCLIN`,`SERIE_DEVC_DEVCLIN`,`LINEA_DEVCLIN`),
  KEY `IDX_DEVCLIN_ARTICULO` (`CODIGO_ART_DEVCLIN`),
  KEY `IDX_DEVCLIN_PEDIDO` (`SERIE_PEDC_DEVCLIN`,`NUMERO_PEDC_DEVCLIN`,`LINEA_PEDC_DEVCLIN`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_documentos_trabajo`;
CREATE TABLE `fza_documentos_trabajo` (
  `ID_DTR` bigint(20) NOT NULL AUTO_INCREMENT,
  `TITULO_DTR` varchar(200) NOT NULL,
  `TIPO_DTR` varchar(20) NOT NULL DEFAULT 'GENERAL',
  `ESTADO_DTR` varchar(20) NOT NULL DEFAULT 'CREADO',
  `CODIGO_EMP_DTR` varchar(20) DEFAULT NULL,
  `CODIGO_ALM_DTR` varchar(10) DEFAULT NULL,
  `USUARIO_DTR` varchar(100) NOT NULL DEFAULT 'SISTEMA',
  `INSTANTE_DOCUMENTO_DTR` datetime NOT NULL,
  `OBSERVACIONES_DTR` text DEFAULT NULL,
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL DEFAULT 'SISTEMA',
  `USUARIO_MODIF` varchar(100) NOT NULL DEFAULT 'SISTEMA',
  PRIMARY KEY (`ID_DTR`),
  KEY `IDX_DTR_ESTADO` (`ESTADO_DTR`),
  KEY `IDX_DTR_INSTANTE` (`INSTANTE_DOCUMENTO_DTR`),
  KEY `IDX_DTR_USUARIO` (`USUARIO_DTR`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_documentos_trabajo_celdas`;
CREATE TABLE `fza_documentos_trabajo_celdas` (
  `ID_DTR_DTRCEL` bigint(20) NOT NULL,
  `LINEA_DTRCEL` int(11) NOT NULL,
  `ID_FILA_DTRCEL` int(11) NOT NULL,
  `ID_AV_PIVOT_DTRCEL` int(11) NOT NULL COMMENT 'FK logica fza_atributos_valores del eje pivot (TALLA)',
  `CODIGO_ALM_DTRCEL` varchar(10) NOT NULL DEFAULT '',
  `CANTIDAD_DTRCEL` decimal(19,6) NOT NULL,
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL DEFAULT '',
  `INSTANTE_MODIF` datetime DEFAULT NULL,
  `USUARIO_MODIF` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`ID_DTR_DTRCEL`,`LINEA_DTRCEL`,`ID_FILA_DTRCEL`,`ID_AV_PIVOT_DTRCEL`,`CODIGO_ALM_DTRCEL`),
  KEY `IDX_DTRCEL_AV_PIVOT` (`ID_AV_PIVOT_DTRCEL`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_documentos_trabajo_compartidos`;
CREATE TABLE `fza_documentos_trabajo_compartidos` (
  `ID_DTC` bigint(20) NOT NULL AUTO_INCREMENT,
  `ID_DTR_DTC` bigint(20) NOT NULL,
  `USUARIO_DTC` varchar(200) NOT NULL,
  `USUARIO_GRUPO_DTC` varchar(200) NOT NULL DEFAULT '',
  `TIPO_DESTINO_DTC` varchar(20) NOT NULL DEFAULT 'USUARIO',
  `PERMISO_DTC` varchar(20) NOT NULL DEFAULT 'LECTURA',
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL DEFAULT 'SISTEMA',
  `USUARIO_MODIF` varchar(100) NOT NULL DEFAULT 'SISTEMA',
  PRIMARY KEY (`ID_DTC`),
  UNIQUE KEY `UQ_DTC_DTR_TIPO_DESTINO_USUARIO_GRUPO` (`ID_DTR_DTC`,`TIPO_DESTINO_DTC`,`USUARIO_GRUPO_DTC`),
  KEY `IDX_DTC_DTR` (`ID_DTR_DTC`),
  KEY `IDX_DTC_TIPO_DESTINO_USUARIO_GRUPO` (`TIPO_DESTINO_DTC`,`USUARIO_GRUPO_DTC`),
  KEY `IDX_DTC_USUARIO` (`USUARIO_DTC`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_documentos_trabajo_lineas`;
CREATE TABLE `fza_documentos_trabajo_lineas` (
  `ID_DTL` bigint(20) NOT NULL AUTO_INCREMENT,
  `ID_DTR_DTL` bigint(20) NOT NULL,
  `LINEA_DTL` varchar(8) NOT NULL,
  `CODIGO_ART_DTL` varchar(20) NOT NULL,
  `CODIGO_UNIDAD_DTL` varchar(50) NOT NULL DEFAULT '',
  `CODIGO_ALM_DTL` varchar(10) DEFAULT NULL,
  `LOTE_DTL` varchar(50) NOT NULL DEFAULT '',
  `FECHA_CADUCIDAD_DTL` date DEFAULT NULL,
  `DESCRIPCION_ARTICULO_DTL` varchar(200) DEFAULT NULL,
  `DESCRIPCION_UNIDAD_DTL` varchar(200) DEFAULT NULL,
  `CANTIDAD_STOCK_DTL` decimal(19,6) NOT NULL DEFAULT 0.000000,
  `CANTIDAD_DTL` decimal(19,6) NOT NULL DEFAULT 0.000000,
  `INSTANTE_STOCK_DTL` datetime NOT NULL,
  `ORIGEN_DTL` varchar(30) DEFAULT NULL,
  `CODIGO_EMP_ORIGEN_DTL` varchar(20) DEFAULT NULL,
  `TIPO_DOCUMENTO_ORIGEN_DTL` varchar(5) DEFAULT NULL,
  `SERIE_DOCUMENTO_ORIGEN_DTL` varchar(20) DEFAULT NULL,
  `NUMERO_DOCUMENTO_ORIGEN_DTL` varchar(20) DEFAULT NULL,
  `LINEA_DOCUMENTO_ORIGEN_DTL` varchar(100) DEFAULT NULL,
  `OBSERVACIONES_DTL` varchar(500) DEFAULT NULL,
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL DEFAULT 'SISTEMA',
  `USUARIO_MODIF` varchar(100) NOT NULL DEFAULT 'SISTEMA',
  `ATTR1_VALOR_DTL` varchar(100) NOT NULL DEFAULT '',
  `ATTR1_NOMBRE_DTL` varchar(100) NOT NULL DEFAULT '',
  `ATTR2_VALOR_DTL` varchar(100) NOT NULL DEFAULT '',
  `ATTR2_NOMBRE_DTL` varchar(100) NOT NULL DEFAULT '',
  `ATTR3_VALOR_DTL` varchar(100) NOT NULL DEFAULT '',
  `ATTR3_NOMBRE_DTL` varchar(100) NOT NULL DEFAULT '',
  `ATTR4_VALOR_DTL` varchar(100) NOT NULL DEFAULT '',
  `ATTR4_NOMBRE_DTL` varchar(100) NOT NULL DEFAULT '',
  `ATTR5_VALOR_DTL` varchar(100) NOT NULL DEFAULT '',
  `ATTR5_NOMBRE_DTL` varchar(100) NOT NULL DEFAULT '',
  `NUM_ATRIBUTOS_DTL` int(11) NOT NULL DEFAULT 0 COMMENT 'Atributos requeridos del articulo',
  `ID_AC_PIVOT_DTL` int(11) NOT NULL DEFAULT 0 COMMENT 'Conjunto pivotado en tallas horizontal (0 = sin pivote)',
  PRIMARY KEY (`ID_DTL`),
  UNIQUE KEY `UQ_DTL_DTR_LINEA` (`ID_DTR_DTL`,`LINEA_DTL`),
  UNIQUE KEY `UQ_DTL_DTR_ORIGEN` (`ID_DTR_DTL`,`CODIGO_EMP_ORIGEN_DTL`,`TIPO_DOCUMENTO_ORIGEN_DTL`,`SERIE_DOCUMENTO_ORIGEN_DTL`,`NUMERO_DOCUMENTO_ORIGEN_DTL`,`LINEA_DOCUMENTO_ORIGEN_DTL`),
  KEY `IDX_DTL_ALM` (`CODIGO_ALM_DTL`),
  KEY `IDX_DTL_ART` (`CODIGO_ART_DTL`),
  KEY `IDX_DTL_DTR` (`ID_DTR_DTL`),
  KEY `IDX_DTL_UNIDAD` (`CODIGO_UNIDAD_DTL`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_efectos_compra`;
CREATE TABLE `fza_efectos_compra` (
  `SERIE_FACC_EFEC` varchar(20) NOT NULL COMMENT 'Factura de compra origen (serie)',
  `NUMERO_FACC_EFEC` varchar(20) NOT NULL COMMENT 'Factura de compra origen (numero)',
  `NUMERO_EFEC` int(11) NOT NULL COMMENT 'Secuencial del efecto dentro de la factura (1..N)',
  `CODIGO_EMP_EFEC` varchar(8) DEFAULT NULL,
  `CODIGO_PRV_EFEC` varchar(20) DEFAULT NULL COMMENT 'FK logica a fza_proveedores (denormalizado)',
  `RAZON_SOCIAL_PRV_EFEC` varchar(200) DEFAULT NULL,
  `NIF_PRV_EFEC` varchar(50) DEFAULT NULL,
  `CODIGO_TEFE_EFEC` varchar(20) DEFAULT NULL COMMENT 'FK logica a fza_tipos_efecto',
  `ESTADO_EFEC` varchar(20) DEFAULT 'PENDIENTE' COMMENT 'PENDIENTE, PARCIAL, PAGADO, REMESADO, DEVUELTO, ANULADO',
  `ORDEN_PLAZO_EFEC` int(11) DEFAULT 1 COMMENT 'Numero de plazo segun la forma de pago',
  `FECHA_EMISION_EFEC` date DEFAULT NULL,
  `FECHA_VENCIMIENTO_EFEC` date DEFAULT NULL COMMENT 'Vencimiento del pago (clave para el control contable)',
  `FECHA_PAGO_EFEC` date DEFAULT NULL COMMENT 'Fecha del ultimo pago aplicado',
  `TIPO_PAGO_EFEC` varchar(50) DEFAULT NULL COMMENT 'Medio de pago conciliado',
  `REFERENCIA_PAGO_EFEC` varchar(100) DEFAULT NULL COMMENT 'Nro transferencia / cheque / justificante',
  `ENTIDAD_PAGO_EFEC` varchar(100) DEFAULT NULL COMMENT 'Banco / entidad desde la que se paga',
  `ESCONCILIADO_EFEC` varchar(1) DEFAULT 'N' COMMENT 'S/N — conciliado con el extracto bancario',
  `IMPORTE_EFEC` decimal(18,6) DEFAULT 0.000000,
  `IMPORTE_PAGADO_EFEC` decimal(18,6) DEFAULT 0.000000 COMMENT 'Suma del historico de pagos del efecto',
  `IMPORTE_PENDIENTE_EFEC` decimal(18,6) DEFAULT 0.000000,
  `SERIE_REMC_EFEC` varchar(20) DEFAULT NULL COMMENT 'FK logica a fza_remesas_compra (si esta remesado)',
  `NUMERO_REMC_EFEC` varchar(20) DEFAULT NULL,
  `ENTIDAD_EFEC` varchar(4) DEFAULT NULL,
  `OFICINA_EFEC` varchar(4) DEFAULT NULL,
  `DIGITO_CONTROL_EFEC` varchar(2) DEFAULT NULL,
  `CUENTA_EFEC` varchar(10) DEFAULT NULL,
  `IBAN_EFEC` varchar(34) DEFAULT NULL,
  `CODIGO_EMPBAN_EFEC` varchar(8) DEFAULT NULL COMMENT 'Cuenta de la empresa (cargo) — FK a fza_empresas_bancos',
  `IBAN_EMP_EFEC` varchar(34) DEFAULT NULL COMMENT 'IBAN de la empresa (cargo), denormalizado del banco',
  `DOC_EXTERNO_EFEC` varchar(50) DEFAULT NULL COMMENT 'Nro de factura del proveedor (traza)',
  `REFERENCIA_DOCUMENTO_EFEC` varchar(100) DEFAULT NULL COMMENT 'Referencia del documento de conciliacion',
  `SERIE_FACC_CONCILIACION_EFEC` varchar(20) DEFAULT NULL COMMENT 'Serie factura del efecto que agrupa esta conciliacion',
  `NUMERO_FACC_CONCILIACION_EFEC` varchar(20) DEFAULT NULL COMMENT 'Numero factura del efecto que agrupa esta conciliacion',
  `NUMERO_EFEC_CONCILIACION_EFEC` int(11) DEFAULT NULL COMMENT 'Numero del efecto que agrupa esta conciliacion',
  `OBSERVACIONES_EFEC` varchar(1000) DEFAULT '',
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  PRIMARY KEY (`SERIE_FACC_EFEC`,`NUMERO_FACC_EFEC`,`NUMERO_EFEC`),
  KEY `IDX_EFEC_CONCILIACION` (`SERIE_FACC_CONCILIACION_EFEC`,`NUMERO_FACC_CONCILIACION_EFEC`,`NUMERO_EFEC_CONCILIACION_EFEC`),
  KEY `IDX_EFEC_ESTADO` (`ESTADO_EFEC`),
  KEY `IDX_EFEC_PROVEEDOR` (`CODIGO_PRV_EFEC`),
  KEY `IDX_EFEC_REMESA` (`SERIE_REMC_EFEC`,`NUMERO_REMC_EFEC`),
  KEY `IDX_EFEC_VENCIMIENTO` (`FECHA_VENCIMIENTO_EFEC`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_efectos_compra_pagos`;
CREATE TABLE `fza_efectos_compra_pagos` (
  `SERIE_FACC_EFECPAG` varchar(20) NOT NULL,
  `NUMERO_FACC_EFECPAG` varchar(20) NOT NULL,
  `NUMERO_EFEC_EFECPAG` int(11) NOT NULL COMMENT 'Efecto al que se aplica el pago',
  `NUMERO_PAGO_EFECPAG` int(11) NOT NULL COMMENT 'Secuencial del pago dentro del efecto (1..N)',
  `FECHA_EFECPAG` date DEFAULT NULL COMMENT 'Fecha del pago (control contable)',
  `IMPORTE_EFECPAG` decimal(18,6) DEFAULT 0.000000,
  `TIPO_EFECPAG` varchar(50) DEFAULT 'TRANSFERENCIA' COMMENT 'Medio de pago: TRANSFERENCIA, EFECTIVO, CHEQUE, ...',
  `CODIGO_FP_EFECPAG` varchar(20) DEFAULT NULL COMMENT 'FK logica a fza_formas_pago (opcional)',
  `REFERENCIA_EFECPAG` varchar(100) DEFAULT NULL COMMENT 'Nro de transferencia / cheque / justificante',
  `ENTIDAD_PAGO_EFECPAG` varchar(100) DEFAULT NULL COMMENT 'Banco / entidad desde la que se paga',
  `ESCONCILIADO_EFECPAG` varchar(1) DEFAULT 'N' COMMENT 'S/N — conciliado con el extracto bancario',
  `OBSERVACIONES_EFECPAG` varchar(500) DEFAULT '',
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  PRIMARY KEY (`SERIE_FACC_EFECPAG`,`NUMERO_FACC_EFECPAG`,`NUMERO_EFEC_EFECPAG`,`NUMERO_PAGO_EFECPAG`),
  KEY `IDX_EFECPAG_FECHA` (`FECHA_EFECPAG`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_efectos_venta`;
CREATE TABLE `fza_efectos_venta` (
  `SERIE_FAC_EFV` varchar(20) NOT NULL COMMENT 'Factura de venta origen (serie)',
  `NUMERO_FAC_EFV` varchar(20) NOT NULL COMMENT 'Factura de venta origen (numero)',
  `NUMERO_EFV` int(11) NOT NULL COMMENT 'Secuencial del efecto dentro de la factura (1..N)',
  `CODIGO_EMP_EFV` varchar(8) DEFAULT NULL,
  `CODIGO_CLI_EFV` varchar(20) DEFAULT NULL COMMENT 'FK logica a fza_clientes (denormalizado)',
  `RAZON_SOCIAL_CLI_EFV` varchar(200) DEFAULT NULL,
  `NIF_CLI_EFV` varchar(50) DEFAULT NULL,
  `CODIGO_TEFE_EFV` varchar(20) DEFAULT NULL COMMENT 'FK logica a fza_tipos_efecto',
  `ESTADO_EFV` varchar(20) DEFAULT 'PENDIENTE' COMMENT 'PENDIENTE, COBRADO, REMESADO, DEVUELTO, ANULADO, CONCILIADO',
  `ORDEN_PLAZO_EFV` int(11) DEFAULT 1,
  `FECHA_EMISION_EFV` date DEFAULT NULL,
  `FECHA_VENCIMIENTO_EFV` date DEFAULT NULL,
  `FECHA_COBRO_EFV` date DEFAULT NULL,
  `TIPO_COBRO_EFV` varchar(50) DEFAULT NULL,
  `REFERENCIA_COBRO_EFV` varchar(100) DEFAULT NULL,
  `ENTIDAD_COBRO_EFV` varchar(100) DEFAULT NULL,
  `ESCONCILIADO_EFV` varchar(1) DEFAULT 'N',
  `IMPORTE_EFV` decimal(18,6) DEFAULT 0.000000,
  `IMPORTE_COBRADO_EFV` decimal(18,6) DEFAULT 0.000000,
  `IMPORTE_PENDIENTE_EFV` decimal(18,6) DEFAULT 0.000000,
  `SERIE_REMV_EFV` varchar(20) DEFAULT NULL COMMENT 'FK logica a fza_remesas_venta (si esta remesado)',
  `NUMERO_REMV_EFV` varchar(20) DEFAULT NULL,
  `ENTIDAD_EFV` varchar(4) DEFAULT NULL,
  `OFICINA_EFV` varchar(4) DEFAULT NULL,
  `DIGITO_CONTROL_EFV` varchar(2) DEFAULT NULL,
  `CUENTA_EFV` varchar(10) DEFAULT NULL,
  `IBAN_EFV` varchar(34) DEFAULT NULL COMMENT 'IBAN del cliente',
  `CODIGO_EMPBAN_EFV` varchar(8) DEFAULT NULL COMMENT 'Cuenta de la empresa (ingreso)',
  `IBAN_EMP_EFV` varchar(34) DEFAULT NULL COMMENT 'IBAN de la empresa (ingreso)',
  `DOC_EXTERNO_EFV` varchar(50) DEFAULT NULL,
  `REFERENCIA_DOCUMENTO_EFV` varchar(100) DEFAULT NULL,
  `SERIE_FAC_CONCILIACION_EFV` varchar(20) DEFAULT NULL,
  `NUMERO_FAC_CONCILIACION_EFV` varchar(20) DEFAULT NULL,
  `NUMERO_EFV_CONCILIACION_EFV` int(11) DEFAULT NULL,
  `OBSERVACIONES_EFV` varchar(1000) DEFAULT '',
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  PRIMARY KEY (`SERIE_FAC_EFV`,`NUMERO_FAC_EFV`,`NUMERO_EFV`),
  KEY `IDX_EFV_CLIENTE` (`CODIGO_CLI_EFV`),
  KEY `IDX_EFV_CONCILIACION` (`SERIE_FAC_CONCILIACION_EFV`,`NUMERO_FAC_CONCILIACION_EFV`,`NUMERO_EFV_CONCILIACION_EFV`),
  KEY `IDX_EFV_ESTADO` (`ESTADO_EFV`),
  KEY `IDX_EFV_REMESA` (`SERIE_REMV_EFV`,`NUMERO_REMV_EFV`),
  KEY `IDX_EFV_VENCIMIENTO` (`FECHA_VENCIMIENTO_EFV`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_empleados`;
CREATE TABLE `fza_empleados` (
  `CODIGO_EMPL` varchar(20) NOT NULL COMMENT 'Número de empleado en caja',
  `NOMBRE_EMPL` varchar(100) DEFAULT NULL,
  `RAZON_SOCIAL_EMPL` varchar(100) DEFAULT NULL,
  `NIF_EMPL` varchar(20) DEFAULT NULL,
  `DIRECCION_EMPL` varchar(200) DEFAULT NULL,
  `DIRECCION2_EMPL` varchar(200) DEFAULT NULL,
  `CODIGO_POSTAL_EMPL` varchar(10) DEFAULT NULL,
  `POBLACION_EMPL` varchar(100) DEFAULT NULL,
  `PROVINCIA_EMPL` varchar(100) DEFAULT NULL,
  `TELEFONO_EMPL` varchar(20) DEFAULT NULL,
  `TELEFONO2_EMPL` varchar(20) DEFAULT NULL,
  `FAX_EMPL` varchar(20) DEFAULT NULL,
  `EMAIL_EMPL` varchar(100) DEFAULT NULL,
  `WEB_EMPL` varchar(200) DEFAULT NULL,
  `IBAN_EMPL` varchar(35) DEFAULT NULL,
  `BIC_EMPL` varchar(11) DEFAULT NULL,
  `DIMINUTIVO_TICKET_EMPL` varchar(10) DEFAULT NULL COMMENT 'Diminutivo de caja / abreviatura del ticket',
  `ESACTIVO_EMPL` char(1) NOT NULL DEFAULT 'S' COMMENT 'S/N. Caja/traspasos/arqueos listan solo S',
  `INSTANTE_MODIF` datetime DEFAULT NULL,
  `INSTANTE_ALTA` datetime NOT NULL,
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`CODIGO_EMPL`),
  KEY `IDX_EMPL_ACTIVO` (`ESACTIVO_EMPL`),
  KEY `IDX_EMPL_DIMINUTIVO` (`DIMINUTIVO_TICKET_EMPL`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_empresas`;
CREATE TABLE `fza_empresas` (
  `CODIGO_EMP_EMP` varchar(10) NOT NULL,
  `ORDEN_EMP` int(11) DEFAULT NULL,
  `ESACTIVO_EMP` varchar(1) DEFAULT 'S',
  `RAZON_SOCIAL_EMP` varchar(200) DEFAULT NULL,
  `NIF_EMP` varchar(50) DEFAULT NULL,
  `MOVIL_EMP` varchar(40) DEFAULT NULL,
  `EMAIL_EMP` varchar(200) DEFAULT NULL,
  `DIRECCION1_EMP` varchar(200) DEFAULT NULL,
  `DIRECCION2_EMP` varchar(200) DEFAULT NULL,
  `CODIGO_POSTAL_EMP` varchar(15) DEFAULT NULL,
  `POBLACION_EMP` varchar(200) DEFAULT NULL,
  `PROVINCIA_EMP` varchar(200) DEFAULT NULL,
  `CODIGO_PAI_EMP` varchar(3) DEFAULT '724',
  `NOMBRE_PAI_EMP` varchar(150) DEFAULT 'España',
  `SERIE_CON_EMP` varchar(12) DEFAULT NULL,
  `IBAN_EMP` varchar(100) DEFAULT NULL,
  `GRUPO_ZONA_IVA_EMP` varchar(10) DEFAULT NULL,
  `ESRETENCIONES_EMP` varchar(1) DEFAULT 'S',
  `ESIVA_RECARGO_COMPRAS_EMP` varchar(1) DEFAULT 'N',
  `ESREGIMENESPECIALAGRICOLA_EMP` varchar(1) DEFAULT 'N',
  `CODIGO_CERTIFICADO_EMP` varchar(64) DEFAULT NULL,
  `TITULAR_CERTIFICADO_EMP` varchar(1000) DEFAULT NULL,
  `TIPO_CERTIFICADO_EMP` varchar(40) DEFAULT NULL,
  `FECHA_DESDE_CERTIFICADO_EMP` datetime DEFAULT NULL,
  `FECHA_HASTA_CERTIFICADO_EMP` datetime DEFAULT NULL,
  `NUMERO_INSTALACION_EMP` varchar(60) DEFAULT NULL COMMENT 'NumeroInstalacion SIF devuelto por el servicio del productor',
  `VERSION_INSTALACION_EMP` varchar(60) DEFAULT NULL COMMENT 'Version de Factuzam usada al obtener NumeroInstalacion',
  `CODIGO_SIF_INSTALACION_EMP` varchar(2) DEFAULT NULL COMMENT 'IdSistemaInformatico usado al obtener NumeroInstalacion',
  `INSTANTE_INSTALACION_EMP` datetime DEFAULT NULL COMMENT 'Instante de obtencion de NumeroInstalacion',
  `TEXTO_LEGAL_FACTURA_EMP` varchar(1000) DEFAULT NULL,
  `TEXTO_PIE_TICKET_CAJA_1_EMP` varchar(42) DEFAULT NULL COMMENT 'Linea 1 del pie del ticket de caja',
  `TEXTO_PIE_TICKET_CAJA_2_EMP` varchar(42) DEFAULT NULL COMMENT 'Linea 2 del pie del ticket de caja',
  `TEXTO_PIE_TICKET_CAJA_3_EMP` varchar(42) DEFAULT NULL COMMENT 'Linea 3 del pie del ticket de caja',
  `TEXTO_PIE_TICKET_CAJA_4_EMP` varchar(42) DEFAULT NULL COMMENT 'Linea 4 del pie del ticket de caja',
  `FORMATO_DOCUMENTO_EMP` varchar(80) NOT NULL DEFAULT 'Serie.NroDocumento' COMMENT 'Formato visible de documentos. Tokens: Serie y NroDocumento',
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  `ESTOKENS_CALENDARIO_NATURAL_EMP` varchar(1) NOT NULL DEFAULT 'N',
  `CODIGO_CLI_TRASPASOS_EMP` varchar(20) DEFAULT NULL COMMENT 'Cliente al que se emiten las facturas internas TA/TV',
  `TOTAL_MAXIMO_LINEA_EMP` decimal(19,6) DEFAULT NULL COMMENT 'Total de línea que pide confirmación; NULL o 0 = sin límite',
  `ESLOTES_REPOSICION_EMP` varchar(1) NOT NULL DEFAULT 'N',
  PRIMARY KEY (`CODIGO_EMP_EMP`),
  KEY `IDX_EMPRESAS_ESTADO` (`ESACTIVO_EMP`,`CODIGO_EMP_EMP`),
  KEY `IDX_EMP_CLI_TRASPASOS` (`CODIGO_CLI_TRASPASOS_EMP`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_empresas_bancos`;
CREATE TABLE `fza_empresas_bancos` (
  `CODIGO_EMPBAN` varchar(8) NOT NULL,
  `CODIGO_EMP_EMPBAN` varchar(10) NOT NULL COMMENT 'FK logica a fza_empresas',
  `NOMBRE_EMPBAN` varchar(100) DEFAULT NULL COMMENT 'Alias de la cuenta (p.ej. Nomina Santander)',
  `CODIGO_BAN_EMPBAN` varchar(4) DEFAULT NULL COMMENT 'FK logica a fza_bancos (entidad, deducible del IBAN)',
  `IBAN_EMPBAN` varchar(34) DEFAULT NULL,
  `ENTIDAD_EMPBAN` varchar(4) DEFAULT NULL,
  `OFICINA_EMPBAN` varchar(4) DEFAULT NULL,
  `DIGITO_CONTROL_EMPBAN` varchar(2) DEFAULT NULL,
  `CUENTA_EMPBAN` varchar(10) DEFAULT NULL,
  `BIC_EMPBAN` varchar(11) DEFAULT NULL,
  `CODIGO_ACREEDOR_SEPA_EMPBAN` varchar(35) DEFAULT NULL COMMENT 'Identificador de acreedor SEPA para adeudos',
  `ESDEFECTO_COBRO_EMPBAN` varchar(1) NOT NULL DEFAULT 'N' COMMENT 'S/N — cuenta por defecto para COBRO (ingreso de ventas)',
  `ESDEFECTO_PAGO_EMPBAN` varchar(1) NOT NULL DEFAULT 'N' COMMENT 'S/N — cuenta por defecto para PAGO (cargo de compras)',
  `ESACTIVO_EMPBAN` varchar(1) NOT NULL DEFAULT 'S',
  `ORDEN_EMPBAN` int(11) DEFAULT 0,
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  PRIMARY KEY (`CODIGO_EMPBAN`),
  KEY `IDX_EMPBAN_EMP` (`CODIGO_EMP_EMPBAN`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_empresas_retenciones`;
CREATE TABLE `fza_empresas_retenciones` (
  `CODIGO_RETENCION_EMPRET` varchar(8) NOT NULL,
  `CODIGO_EMP_EMPRET` varchar(8) NOT NULL,
  `PORCENTAJE_EMPRET` decimal(18,6) DEFAULT NULL,
  `FECHA_DESDE_EMPRET` date DEFAULT NULL,
  `FECHA_HASTA_EMPRET` date DEFAULT NULL,
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  PRIMARY KEY (`CODIGO_RETENCION_EMPRET`),
  KEY `IDX_RETENCIONES_CALCULO` (`CODIGO_EMP_EMPRET`,`FECHA_DESDE_EMPRET`,`FECHA_HASTA_EMPRET`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_empresas_series`;
CREATE TABLE `fza_empresas_series` (
  `CODIGO_SERIE_EMPSER` varchar(10) NOT NULL,
  `CODIGO_EMP_EMPSER` varchar(10) NOT NULL,
  `CODIGO_ALM_EMPSER` varchar(10) DEFAULT NULL,
  `CODIGO_CAJA_EMPSER` varchar(10) DEFAULT NULL,
  `EMPSER` varchar(12) NOT NULL,
  `SERIE_TOKENIZADA_EMPSER` varchar(12) DEFAULT NULL,
  `TIPO_DOC_EMPSER` varchar(2) DEFAULT NULL,
  `SUBTIPO_EMPSER` varchar(20) DEFAULT NULL,
  `ESDEFECTO_EMPSER` varchar(1) NOT NULL DEFAULT 'S' COMMENT 'S = serie propuesta por defecto en su ámbito',
  `FECHA_DESDE_EMPSER` date DEFAULT NULL,
  `FECHA_HASTA_EMPSER` date DEFAULT NULL,
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  `CODIGO_PRV_EMPSER` varchar(20) DEFAULT NULL,
  PRIMARY KEY (`CODIGO_SERIE_EMPSER`),
  KEY `IDX_EMPSER_EMP_TIPO_FECHA` (`CODIGO_EMP_EMPSER`,`TIPO_DOC_EMPSER`,`FECHA_DESDE_EMPSER`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_errores_envios`;
CREATE TABLE `fza_errores_envios` (
  `ID_ERENV` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `INSTANTE_ERROR_ERENV` datetime NOT NULL,
  `INSTANTE_ENVIO_ERENV` datetime NOT NULL,
  `URL_SERVICIO_ERENV` varchar(500) NOT NULL,
  `URL_SEGUIMIENTO_ERENV` varchar(1000) DEFAULT NULL,
  `URL_ESTADO_ERENV` varchar(1000) DEFAULT NULL,
  `REFERENCIA_ERENV` varchar(40) DEFAULT NULL,
  `TOKEN_SEGUIMIENTO_ERENV` varchar(100) DEFAULT NULL,
  `ESTADO_ERENV` varchar(30) NOT NULL DEFAULT 'ERROR_ENVIO',
  `CODIGO_HTTP_ERENV` int(11) NOT NULL DEFAULT 0,
  `CLASE_ERROR_ERENV` varchar(255) NOT NULL,
  `MENSAJE_ERROR_ERENV` text NOT NULL,
  `DETALLE_ERROR_ERENV` mediumtext NOT NULL,
  `MENSAJE_ENVIO_ERENV` text DEFAULT NULL,
  `EMAIL_CONTACTO_ERENV` varchar(254) NOT NULL,
  `TELEFONO_CONTACTO_ERENV` varchar(50) NOT NULL,
  `DESCRIPCION_ERENV` text DEFAULT NULL,
  `COMENTARIO_TECNICO_ERENV` text DEFAULT NULL,
  `COMUNICACIONES_ERENV` mediumtext DEFAULT NULL,
  `INSTANTE_COMENTARIO_ERENV` datetime DEFAULT NULL,
  `INSTANTE_CONSULTA_ERENV` datetime DEFAULT NULL,
  `MENSAJE_CONSULTA_ERENV` varchar(1000) DEFAULT NULL,
  `ID_SCRIPT_REMOTO_ERENV` bigint(20) unsigned DEFAULT NULL,
  `DESCRIPCION_SCRIPT_ERENV` varchar(500) DEFAULT NULL,
  `SCRIPT_SQL_ERENV` mediumtext DEFAULT NULL,
  `SHA256_SCRIPT_ERENV` char(64) DEFAULT NULL,
  `ESTADO_SCRIPT_ERENV` varchar(30) DEFAULT NULL,
  `ID_EJECUTABLE_REMOTO_ERENV` bigint(20) unsigned DEFAULT NULL,
  `DESCRIPCION_EJECUTABLE_ERENV` varchar(500) DEFAULT NULL,
  `VERSION_EJECUTABLE_ERENV` varchar(50) DEFAULT NULL,
  `URL_EJECUTABLE_ERENV` varchar(1000) DEFAULT NULL,
  `NOMBRE_EJECUTABLE_ERENV` varchar(255) DEFAULT NULL,
  `CANTIDAD_BYTES_EJECUTABLE_ERENV` bigint(20) unsigned DEFAULT NULL,
  `SHA256_EJECUTABLE_ERENV` char(64) DEFAULT NULL,
  `ESTADO_EJECUTABLE_ERENV` varchar(30) DEFAULT NULL,
  `INSTANTE_ALTA` datetime NOT NULL DEFAULT current_timestamp(),
  `INSTANTE_MODIF` datetime DEFAULT NULL ON UPDATE current_timestamp(),
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`ID_ERENV`),
  KEY `IDX_ERENV_ESTADO_INSTANTE` (`ESTADO_ERENV`,`INSTANTE_ERROR_ERENV`),
  KEY `IDX_ERENV_REFERENCIA` (`REFERENCIA_ERENV`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_estadisticas_dia`;
CREATE TABLE `fza_estadisticas_dia` (
  `FECHA` date NOT NULL,
  `CODIGO_ALMACEN` varchar(10) NOT NULL,
  `CODIGO_FAMILIA` varchar(20) NOT NULL DEFAULT '',
  `TEMPORADA` varchar(100) NOT NULL DEFAULT '',
  `NUM_MOVIMIENTOS` int(11) NOT NULL DEFAULT 0,
  `UNIDADES_MOV` decimal(19,6) NOT NULL DEFAULT 0.000000,
  `COSTE_MOV` decimal(19,6) NOT NULL DEFAULT 0.000000,
  `NUM_LINEAS_VENTA` int(11) NOT NULL DEFAULT 0,
  `UNIDADES_VENTA` decimal(19,6) NOT NULL DEFAULT 0.000000,
  `IMPORTE_VENTA` decimal(19,6) NOT NULL DEFAULT 0.000000,
  `INSTANTE_REFRESCO` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`FECHA`,`CODIGO_ALMACEN`,`CODIGO_FAMILIA`,`TEMPORADA`),
  KEY `IDX_FZAEST_FAM_FECHA` (`CODIGO_FAMILIA`,`FECHA`),
  KEY `IDX_FZAEST_TEMP_FECHA` (`TEMPORADA`,`FECHA`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_facturacion_caja_periodos`;
CREATE TABLE `fza_facturacion_caja_periodos` (
  `ID_FACPER` bigint(20) NOT NULL AUTO_INCREMENT,
  `MODALIDAD_FACPER` varchar(2) NOT NULL,
  `CODIGO_EMP_ORIGEN_FACPER` varchar(10) DEFAULT NULL,
  `CODIGO_EMP_DESTINO_FACPER` varchar(10) NOT NULL,
  `FECHA_DESDE_FACPER` date NOT NULL,
  `FECHA_HASTA_FACPER` date NOT NULL,
  `ESTADO_FACPER` varchar(20) NOT NULL DEFAULT 'ABIERTO',
  `CANTIDAD_DOCUMENTOS_FACPER` int(11) NOT NULL DEFAULT 0,
  `CANTIDAD_OPERACIONES_FACPER` int(11) NOT NULL DEFAULT 0,
  `CANTIDAD_AJUSTES_FACPER` int(11) NOT NULL DEFAULT 0,
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT current_timestamp(),
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  PRIMARY KEY (`ID_FACPER`),
  KEY `IDX_FACPER_ESTADO` (`ESTADO_FACPER`),
  KEY `IDX_FACPER_REVISION` (`MODALIDAD_FACPER`,`CODIGO_EMP_ORIGEN_FACPER`,`CODIGO_EMP_DESTINO_FACPER`,`FECHA_DESDE_FACPER`,`FECHA_HASTA_FACPER`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_facturas`;
CREATE TABLE `fza_facturas` (
  `NUMERO_FAC` varchar(20) NOT NULL COMMENT 'Número de documento',
  `SERIE_FAC` varchar(20) NOT NULL COMMENT 'Serie de documento',
  `FECHA_FAC` date DEFAULT NULL COMMENT 'Fecha oficial del documento',
  `ESCONSOLIDADA_FAC` varchar(1) DEFAULT 'N' COMMENT 'Si la factura se ha emitido',
  `INSTANTECONSO_FAC` datetime DEFAULT NULL COMMENT 'Fecha y Hora de la consolidación',
  `TIPO_FAC` varchar(20) DEFAULT 'NORMAL' COMMENT 'NORMAL, SIMPLIFICADA, RECTIFICATIVA',
  `TIPO_RECTIFICATIVA_FAC` varchar(1) DEFAULT NULL COMMENT 'I=por diferencias; S=sustitutiva',
  `TIPO_FACTURA_VERIFACTU_FAC` varchar(2) DEFAULT NULL COMMENT 'F1, F2, F3, R1, R2, R3, R4 o R5',
  `ESMUEVE_STOCK_FAC` varchar(1) DEFAULT 'N' COMMENT 'Si la factura NORMAL genera movimientos de almacen al consolidar',
  `FASE_FAC` varchar(20) DEFAULT NULL COMMENT 'BORRADOR, ONLINE, OFFLINE, ERROR, ERROR_BORRADOR, VERIFICADA, CANCELADA',
  `CODIGO_EMP_FAC` varchar(8) DEFAULT NULL COMMENT 'Código de empresa del emisor del documento',
  `RAZON_SOCIAL_EMPRESA_FAC` varchar(200) DEFAULT NULL,
  `NIF_EMPRESA_FAC` varchar(50) DEFAULT NULL,
  `MOVIL_EMPRESA_FAC` varchar(40) DEFAULT NULL,
  `EMAIL_EMPRESA_FAC` varchar(200) DEFAULT NULL,
  `DIRECCION1_EMPRESA_FAC` varchar(200) DEFAULT NULL,
  `DIRECCION2_EMPRESA_FAC` varchar(200) DEFAULT NULL,
  `POBLACION_EMPRESA_FAC` varchar(200) DEFAULT NULL,
  `PROVINCIA_EMPRESA_FAC` varchar(200) DEFAULT NULL,
  `CODIGO_PAI_EMPRESA_FAC` varchar(3) DEFAULT '724',
  `NOMBRE_PAI_EMPRESA_FAC` varchar(150) DEFAULT 'España',
  `CODIGO_POSTAL_EMPRESA_FAC` varchar(15) DEFAULT NULL,
  `ESRETENCIONES_EMPRESA_FAC` varchar(1) DEFAULT 'S' COMMENT 'S o N si la empresa aplica retenciones como autónomos',
  `GRUPO_ZONA_IVA_EMPRESA_FAC` varchar(10) DEFAULT NULL,
  `ESREGIMENESPECIALAGRICOLA_EMPRESA_FAC` varchar(1) DEFAULT 'N',
  `CODIGO_CLI_FAC` varchar(20) DEFAULT NULL,
  `RAZON_SOCIAL_CLIENTE_FAC` varchar(200) DEFAULT NULL,
  `NIF_CLIENTE_FAC` varchar(50) DEFAULT NULL,
  `MOVIL_CLIENTE_FAC` varchar(40) DEFAULT NULL,
  `EMAIL_CLIENTE_FAC` varchar(200) DEFAULT NULL,
  `DIRECCION1_CLIENTE_FAC` varchar(200) DEFAULT NULL,
  `DIRECCION2_CLIENTE_FAC` varchar(200) DEFAULT NULL,
  `POBLACION_CLIENTE_FAC` varchar(200) DEFAULT NULL,
  `PROVINCIA_CLIENTE_FAC` varchar(200) DEFAULT NULL,
  `CODIGO_POSTAL_CLIENTE_FAC` varchar(15) DEFAULT NULL,
  `CODIGO_PAI_CLIENTE_FAC` varchar(3) DEFAULT '724',
  `NOMBRE_PAI_CLIENTE_FAC` varchar(150) DEFAULT 'España',
  `NOMBRE_PERSONA_CLIENTE_FAC` varchar(80) DEFAULT NULL,
  `APELLIDOS_PERSONA_CLIENTE_FAC` varchar(120) DEFAULT NULL,
  `CODIGO_OFICINA_CONTABLE_FAC` varchar(10) DEFAULT NULL,
  `CODIGO_ORGANO_GESTOR_FAC` varchar(10) DEFAULT NULL,
  `CODIGO_UNIDAD_TRAMITADORA_FAC` varchar(10) DEFAULT NULL,
  `CODIGO_IVA_FAC` varchar(20) DEFAULT NULL COMMENT 'Código de IVA de la tabla fza_ivas',
  `ESIVA_RECARGO_CLIENTE_FAC` varchar(1) DEFAULT 'N' COMMENT 'S o N si el cliente tiene RE',
  `ESIVA_EXENTO_CLIENTE_FAC` varchar(1) DEFAULT 'N' COMMENT 'S o N si el cliente tiene IVA EXENTO',
  `ESREGIMENESPECIALAGRICOLA_CLIENTE_FAC` varchar(1) DEFAULT 'N' COMMENT 'S o N si el cliente tiene REAGP',
  `ESRETENCIONES_CLIENTE_FAC` varchar(1) DEFAULT 'S' COMMENT 'S o N Si el cliente aplica retenciones',
  `TARIFA_ARTICULO_CLIENTE_FAC` varchar(10) DEFAULT NULL COMMENT 'Código de la tarifa que viene del cliente o configurada por el usuario',
  `ESIMP_INCL_TARIFA_CLIENTE_FAC` varchar(1) DEFAULT 'S' COMMENT 'Si el precio de la tarifa del cliente es con impuestos incl o no',
  `ESINTRACOMUNITARIO_CLIENTE_FAC` varchar(1) DEFAULT 'N' COMMENT 'Si la venta es hacia un país de la UE',
  `TIPO_OPER_VFACTU_FAC` varchar(20) DEFAULT NULL COMMENT 'Calificacion Verifactu: CODIGO_VFO de fza_verifactu_operaciones (NULL=auto)',
  `ESIRPF_IMP_INCL_ZONA_IVA_FAC` varchar(1) DEFAULT 'N' COMMENT 'Si la base del cáculo del irpf se hace desde BI o BI con impuestos',
  `ESAPLICA_RE_ZONA_IVA_FAC` varchar(1) DEFAULT 'S' COMMENT 'Si el tipo de IVA aplica Recargo de Equivalencia o no',
  `ESIVAAGRICOLA_ZONA_IVA_FAC` varchar(1) DEFAULT 'N' COMMENT 'Si el tipo de IVA es compatible con REAGP',
  `PALABRA_REPORTS_ZONA_IVA_FAC` varchar(10) DEFAULT 'IVA' COMMENT 'Palabra que sustituye a IVA desde la tabla de fza_ivas_grupos',
  `ESVENTA_ACTIVO_FIJO_FAC` varchar(1) DEFAULT 'N' COMMENT 'Sólo REAGP cuando se vende activos fijos, exime irpf',
  `PORCENTAJE_IVAN_FAC` decimal(19,6) DEFAULT NULL COMMENT 'Porcentaje IVA Normal',
  `TOTAL_IVAN_FAC` decimal(18,6) DEFAULT NULL COMMENT 'Total IVA Normal',
  `PORCENTAJE_REN_FAC` decimal(19,6) DEFAULT NULL COMMENT 'Porcentaje RE Normal',
  `TOTAL_REN_FAC` decimal(19,6) DEFAULT NULL COMMENT 'Total RE Normal',
  `TOTAL_BASEI_IVAN_FAC` decimal(18,6) DEFAULT NULL COMMENT 'Total Base Imponible IVA Normal',
  `PORCENTAJE_IVAR_FAC` decimal(19,6) DEFAULT NULL COMMENT 'Porcentaje IVA Reducido',
  `TOTAL_IVAR_FAC` decimal(18,6) DEFAULT NULL COMMENT 'TotaL IVA Reducido',
  `PORCENTAJE_RER_FAC` decimal(19,6) DEFAULT NULL COMMENT 'Porcentaje RE Reducido',
  `TOTAL_RER_FAC` decimal(19,6) DEFAULT NULL COMMENT 'Total RE Reducido',
  `TOTAL_BASEI_IVAR_FAC` decimal(18,6) DEFAULT NULL COMMENT 'Total Base Imponible IVA Reducido',
  `PORCENTAJE_IVAS_FAC` decimal(19,6) DEFAULT NULL COMMENT 'Porcentaje IVA SuperReducido',
  `TOTAL_IVAS_FAC` decimal(18,6) DEFAULT NULL COMMENT 'Total IVA SuperReducido',
  `PORCENTAJE_RES_FAC` decimal(19,6) DEFAULT NULL COMMENT 'Porcentaje IVA SuperReducido',
  `TOTAL_RES_FAC` decimal(19,6) DEFAULT NULL COMMENT 'Total RE SuperReducido',
  `TOTAL_BASEI_IVAS_FAC` decimal(18,6) DEFAULT NULL COMMENT 'Total sin IVA SuperReducido',
  `PORCENTAJE_IVAE_FAC` decimal(19,6) DEFAULT NULL COMMENT 'Porcentaje IVA Exento',
  `TOTAL_IVAE_FAC` decimal(18,6) DEFAULT NULL COMMENT 'Total IVA Exento',
  `PORCENTAJE_REE_FAC` decimal(19,6) DEFAULT NULL COMMENT 'Porcentaje IVA1 Exento',
  `TOTAL_REE_FAC` decimal(19,6) DEFAULT NULL COMMENT 'Total RE Exento',
  `TOTAL_BASEI_IVAE_FAC` decimal(18,6) DEFAULT NULL COMMENT 'Total sin IVA Exento',
  `TOTAL_BASES_FAC` decimal(18,6) DEFAULT NULL COMMENT 'Total Todas las bases imponibles',
  `TOTAL_IMPUESTOS_FAC` decimal(18,6) DEFAULT NULL COMMENT 'Total de todos los impuestos iva + re',
  `FORMA_PAGO_FAC` varchar(200) DEFAULT NULL COMMENT 'Codigo Forma de Pago',
  `PORCENTAJE_RETENCION_FAC` decimal(19,6) DEFAULT NULL COMMENT 'Porcentaje Retenciones',
  `TOTAL_RETENCION_FAC` decimal(18,6) DEFAULT NULL COMMENT 'Total Retenciones Factura',
  `TOTAL_LIQUIDO_FAC` decimal(18,6) DEFAULT NULL COMMENT 'Total Factura a pagar en el acto de emisión',
  `NUMERO_FAC_ABONO_FAC` varchar(20) DEFAULT NULL COMMENT 'Numero de la rectificativa o factura que sustituye a esta',
  `SERIE_FAC_ABONO_FAC` varchar(20) DEFAULT NULL COMMENT 'Serie de la rectificativa o factura que sustituye a esta',
  `TEXTO_LEGAL_CLIENTE_FAC` varchar(1000) DEFAULT '' COMMENT 'Texto legal desde el cliente',
  `TEXTO_LEGAL_EMPRESA_FAC` varchar(1000) DEFAULT '' COMMENT 'Texto legal desde la empresa',
  `DOCUMENTO_FAC` blob DEFAULT NULL COMMENT 'Documento Factura (en desuso)',
  `COMENTARIOS_FAC` varchar(1000) DEFAULT '',
  `CONTADOR_LINEAS_FAC` varchar(8) DEFAULT NULL COMMENT 'Contador de lineas para lineas de factura',
  `ESCREARARTICULOS_FAC` varchar(1) DEFAULT NULL COMMENT 'S o N si se crean articulos desde el detalle',
  `ESDESCRIPCIONES_AMP_FAC` varchar(1) DEFAULT 'N' COMMENT 'S o N si la factura contiene una descripción larga',
  `ESFECHADEENTREGA_FAC` varchar(1) DEFAULT 'N' COMMENT 'S o N si las descripciones tienen fecha de entrega',
  `XML_FAC` text DEFAULT NULL COMMENT 'xml de la factura electrónica firmado',
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  `CODIGO_CAJERO_FAC` varchar(20) DEFAULT NULL COMMENT 'Vendedor de la factura; en caja, quien cerro el ticket (fza_empleados)',
  `CODIGO_ALM_FAC` varchar(10) DEFAULT NULL,
  `CODIGO_CAJA_FAC` varchar(10) DEFAULT NULL,
  `NUMERO_OPERACION_FAC` varchar(20) DEFAULT NULL,
  `CODIGO_BARRAS_FAC` varchar(13) DEFAULT NULL COMMENT 'EAN-13 del ticket (prefijo 29) para devoluciones',
  `PDF_FAC` longblob DEFAULT NULL COMMENT 'PDF de la factura tal como se genero al consolidar/exportar',
  `NOMBRE_PDF_FAC` varchar(200) DEFAULT NULL COMMENT 'Nombre de fichero del PDF archivado',
  `TAMANO_PDF_FAC` bigint(20) DEFAULT NULL COMMENT 'Tamano en bytes del PDF archivado',
  `HUELLA_PDF_FAC` varchar(64) DEFAULT NULL COMMENT 'SHA-256 hexadecimal del PDF archivado',
  `INSTANTE_PDF_FAC` datetime DEFAULT NULL COMMENT 'Momento en que se archivo el PDF',
  `FORMATO_PDF_FAC` varchar(200) DEFAULT NULL COMMENT 'Formato de impresion con el que se genero el PDF archivado',
  `PORCENTAJE_DTO_COMERCIAL_FAC` decimal(19,6) DEFAULT 0.000000,
  `TOTAL_DTO_COMERCIAL_FAC` decimal(19,6) DEFAULT 0.000000,
  `PORCENTAJE_DTO_FINANCIERO_FAC` decimal(19,6) DEFAULT 0.000000,
  `TOTAL_DTO_FINANCIERO_FAC` decimal(19,6) DEFAULT 0.000000,
  PRIMARY KEY (`NUMERO_FAC`,`SERIE_FAC`),
  UNIQUE KEY `UQ_FAC_CODIGO_BARRAS` (`CODIGO_BARRAS_FAC`),
  KEY `IDX_FACTURAS_CLIENTE_FECHA` (`CODIGO_CLI_FAC`,`FECHA_FAC`),
  KEY `IDX_FACTURAS_CLI_EMP` (`CODIGO_CLI_FAC`,`CODIGO_EMP_FAC`),
  KEY `IDX_FACTURAS_EMPRESA` (`CODIGO_EMP_FAC`),
  KEY `IDX_FACTURAS_FECHA` (`FECHA_FAC`),
  KEY `IDX_FACTURAS_OPERACION` (`CODIGO_EMP_FAC`,`CODIGO_ALM_FAC`,`CODIGO_CAJA_FAC`,`NUMERO_OPERACION_FAC`),
  KEY `IDX_FACTURAS_SERIE` (`SERIE_FAC`,`NUMERO_FAC`),
  KEY `IDX_FAC_ABONO` (`SERIE_FAC_ABONO_FAC`,`NUMERO_FAC_ABONO_FAC`),
  KEY `IDX_FAC_EMP_INSTANTE` (`CODIGO_EMP_FAC`,`INSTANTE_ALTA`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_facturas_compra`;
CREATE TABLE `fza_facturas_compra` (
  `NUMERO_FACC` varchar(20) NOT NULL,
  `SERIE_FACC` varchar(20) NOT NULL,
  `FECHA_FACC` date DEFAULT NULL COMMENT 'Fecha de la factura del proveedor',
  `FECHA_VALOR_FACC` date DEFAULT NULL COMMENT 'Fecha valor / contable (legacy FechaValor)',
  `ESTADO_FACC` varchar(20) DEFAULT 'ABIERTA' COMMENT 'ABIERTA, CERRADA, CONTABILIZADA, PAGADA, CANCELADA',
  `TIPO_FACC` varchar(20) NOT NULL DEFAULT 'NORMAL' COMMENT 'NORMAL, RECTIFICATIVA',
  `SERIE_FACC_RECTIFICADA_FACC` varchar(20) DEFAULT NULL COMMENT 'Factura de compra que rectifica (abono)',
  `NUMERO_FACC_RECTIFICADA_FACC` varchar(20) DEFAULT NULL,
  `DOC_EXTERNO_FACC` varchar(50) DEFAULT NULL COMMENT 'Nro de factura segun el proveedor (legacy DocExterno)',
  `REF_PROVEEDOR_FACC` varchar(50) DEFAULT NULL,
  `CODIGO_EMP_FACC` varchar(8) DEFAULT NULL,
  `RAZON_SOCIAL_EMPRESA_FACC` varchar(200) DEFAULT NULL,
  `NIF_EMPRESA_FACC` varchar(50) DEFAULT NULL,
  `MOVIL_EMPRESA_FACC` varchar(40) DEFAULT NULL,
  `EMAIL_EMPRESA_FACC` varchar(200) DEFAULT NULL,
  `DIRECCION1_EMPRESA_FACC` varchar(200) DEFAULT NULL,
  `DIRECCION2_EMPRESA_FACC` varchar(200) DEFAULT NULL,
  `POBLACION_EMPRESA_FACC` varchar(200) DEFAULT NULL,
  `PROVINCIA_EMPRESA_FACC` varchar(200) DEFAULT NULL,
  `CODIGO_PAI_EMPRESA_FACC` varchar(3) DEFAULT '724',
  `NOMBRE_PAI_EMPRESA_FACC` varchar(150) DEFAULT 'Espana',
  `CODIGO_POSTAL_EMPRESA_FACC` varchar(15) DEFAULT NULL,
  `CODIGO_PRV_FACC` varchar(20) DEFAULT NULL COMMENT 'FK logica a fza_proveedores',
  `RAZON_SOCIAL_PRV_FACC` varchar(200) DEFAULT NULL,
  `NIF_PRV_FACC` varchar(50) DEFAULT NULL,
  `MOVIL_PRV_FACC` varchar(40) DEFAULT NULL,
  `EMAIL_PRV_FACC` varchar(200) DEFAULT NULL,
  `DIRECCION1_PRV_FACC` varchar(200) DEFAULT NULL,
  `DIRECCION2_PRV_FACC` varchar(200) DEFAULT NULL,
  `POBLACION_PRV_FACC` varchar(200) DEFAULT NULL,
  `PROVINCIA_PRV_FACC` varchar(200) DEFAULT NULL,
  `CODIGO_PAI_PRV_FACC` varchar(3) DEFAULT '724',
  `NOMBRE_PAI_PRV_FACC` varchar(150) DEFAULT 'Espana',
  `CODIGO_POSTAL_PRV_FACC` varchar(15) DEFAULT NULL,
  `CODIGO_ALM_FACC` varchar(10) DEFAULT NULL,
  `CODIGO_IVA_FACC` varchar(20) DEFAULT NULL,
  `ESIVA_RECARGO_COMPRAS_FACC` varchar(1) DEFAULT 'N',
  `ESIVA_EXENTO_INTRACOMUNITARIO_FACC` varchar(1) NOT NULL DEFAULT 'N' COMMENT 'S = IVA exento por proveedor intracomunitario',
  `PORCENTAJE_IVAN_FACC` decimal(19,6) DEFAULT NULL,
  `TOTAL_BASEI_IVAN_FACC` decimal(18,6) DEFAULT NULL,
  `TOTAL_IVAN_FACC` decimal(18,6) DEFAULT NULL,
  `PORCENTAJE_REN_FACC` decimal(19,6) DEFAULT NULL,
  `TOTAL_REN_FACC` decimal(18,6) DEFAULT NULL,
  `PORCENTAJE_IVAR_FACC` decimal(19,6) DEFAULT NULL,
  `TOTAL_BASEI_IVAR_FACC` decimal(18,6) DEFAULT NULL,
  `TOTAL_IVAR_FACC` decimal(18,6) DEFAULT NULL,
  `PORCENTAJE_RER_FACC` decimal(19,6) DEFAULT NULL,
  `TOTAL_RER_FACC` decimal(18,6) DEFAULT NULL,
  `PORCENTAJE_IVAS_FACC` decimal(19,6) DEFAULT NULL,
  `TOTAL_BASEI_IVAS_FACC` decimal(18,6) DEFAULT NULL,
  `TOTAL_IVAS_FACC` decimal(18,6) DEFAULT NULL,
  `PORCENTAJE_RES_FACC` decimal(19,6) DEFAULT NULL,
  `TOTAL_RES_FACC` decimal(18,6) DEFAULT NULL,
  `PORCENTAJE_IVAE_FACC` decimal(19,6) DEFAULT NULL,
  `TOTAL_BASEI_IVAE_FACC` decimal(18,6) DEFAULT NULL,
  `TOTAL_IVAE_FACC` decimal(18,6) DEFAULT NULL,
  `PORCENTAJE_REE_FACC` decimal(19,6) DEFAULT NULL,
  `TOTAL_REE_FACC` decimal(18,6) DEFAULT NULL,
  `PORCENTAJE_DTO_COMERCIAL_FACC` decimal(19,6) DEFAULT NULL,
  `TOTAL_DTO_COMERCIAL_FACC` decimal(18,6) DEFAULT NULL,
  `PORCENTAJE_DTO_FINANCIERO_FACC` decimal(19,6) DEFAULT 0.000000,
  `TOTAL_DTO_FINANCIERO_FACC` decimal(18,6) DEFAULT 0.000000,
  `PORCENTAJE_PRONTO_PAGO_FACC` decimal(19,6) DEFAULT NULL,
  `TOTAL_PRONTO_PAGO_FACC` decimal(18,6) DEFAULT NULL,
  `PORCENTAJE_RAPPEL_FACC` decimal(19,6) DEFAULT NULL,
  `TOTAL_RAPPEL_FACC` decimal(18,6) DEFAULT NULL,
  `PORCENTAJE_FINANCIACION_FACC` decimal(19,6) DEFAULT NULL,
  `TOTAL_FINANCIACION_FACC` decimal(18,6) DEFAULT NULL,
  `TOTAL_PORTES_FACC` decimal(18,6) DEFAULT NULL,
  `PORCENTAJE_RETENCION_FACC` decimal(19,6) DEFAULT NULL,
  `TOTAL_RETENCION_FACC` decimal(18,6) DEFAULT NULL,
  `TOTAL_BRUTO_FACC` decimal(18,6) DEFAULT NULL COMMENT 'Suma de lineas antes de descuentos',
  `TOTAL_BASES_FACC` decimal(18,6) DEFAULT NULL,
  `TOTAL_IMPUESTOS_FACC` decimal(18,6) DEFAULT NULL,
  `TOTAL_FACC` decimal(18,6) DEFAULT NULL COMMENT 'Total factura = bases + impuestos',
  `TOTAL_LIQUIDO_FACC` decimal(18,6) DEFAULT NULL COMMENT 'A pagar al proveedor (con retencion / descuentos)',
  `FORMA_PAGO_FACC` varchar(200) DEFAULT NULL COMMENT 'Codigo de forma de pago (fza_formas_pago)',
  `ID_PV_TEMPORADA_FACC` int(11) DEFAULT NULL COMMENT 'FK logica fza_propiedades_valores.ID_PV_ARTPROP con ID_PROP_PV=TEMPORADA. Procede de ocfacpro.Temporada en la migracion.',
  `ESAGRUPAR_ALBARANES_FACC` varchar(1) DEFAULT 'S' COMMENT 'S/N — agrupa varios albaranes en esta factura',
  `ENTIDAD_FACC` varchar(4) DEFAULT NULL,
  `OFICINA_FACC` varchar(4) DEFAULT NULL,
  `DIGITO_CONTROL_FACC` varchar(2) DEFAULT NULL,
  `CUENTA_FACC` varchar(10) DEFAULT NULL,
  `IBAN_FACC` varchar(34) DEFAULT NULL COMMENT 'Cuenta del proveedor para domiciliar el pago',
  `CONTADOR_LINEAS_FACC` varchar(8) DEFAULT NULL,
  `COMENTARIOS_FACC` varchar(1000) DEFAULT '',
  `OBSERVACIONES_FACC` varchar(2000) DEFAULT '',
  `ESPIVOTE_HORIZONTAL_FACC` varchar(1) NOT NULL DEFAULT 'N',
  `INSTANTE_CONTABILIZACION_FACC` datetime DEFAULT NULL COMMENT 'Control contable: cuando se contabilizo la factura',
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  `MODALIDAD_FACC` varchar(12) NOT NULL DEFAULT 'ORDINARIA',
  `ESMUEVE_STOCK_FACC` varchar(1) NOT NULL DEFAULT 'N' COMMENT 'S = la compra directa mueve stock al cerrarse',
  `PORCENTAJE_COMPENSACION_FACC` decimal(9,4) NOT NULL DEFAULT 0.0000,
  `TOTAL_COMPENSACION_FACC` decimal(18,6) NOT NULL DEFAULT 0.000000,
  `ESACUERDO_AUTOFAC_FACC` varchar(1) NOT NULL DEFAULT 'N',
  `ESREPRESENTACION_FISCAL_FACC` varchar(1) NOT NULL DEFAULT 'N',
  `SISTEMA_FISCAL_FACC` varchar(20) DEFAULT NULL,
  `ESTADO_FISCAL_FACC` varchar(20) DEFAULT NULL,
  `XML_PETICION_FISCAL_FACC` longtext DEFAULT NULL,
  `XML_RESPUESTA_FISCAL_FACC` longtext DEFAULT NULL,
  `HUELLA_FISCAL_FACC` varchar(64) DEFAULT NULL,
  `URL_QR_FISCAL_FACC` varchar(1000) DEFAULT NULL,
  `FECHA_HORA_FISCAL_FACC` varchar(40) DEFAULT NULL,
  `CSV_FISCAL_FACC` varchar(100) DEFAULT NULL,
  `ERROR_FISCAL_FACC` text DEFAULT NULL,
  `ENTORNO_FISCAL_FACC` varchar(3) DEFAULT NULL,
  `FECHA_REGISTRO_CONTABLE_FACC` date DEFAULT NULL,
  `CUOTA_DEDUCIBLE_FACC` decimal(18,6) DEFAULT NULL,
  `DOCUMENTO_FISCAL_FACC` varchar(60) DEFAULT NULL,
  `CODIGO_CLI_FACC` varchar(20) DEFAULT NULL COMMENT 'Cliente agricultor emisor del recibo REAGP',
  `LOTE_REPOSICION_FACC` varchar(50) DEFAULT NULL,
  `ID_PV_TEMPORADA_REPOSICION_FACC` int(11) DEFAULT NULL,
  `ESREPOSICION_AUTO_FACC` varchar(1) NOT NULL DEFAULT 'N',
  PRIMARY KEY (`NUMERO_FACC`,`SERIE_FACC`),
  KEY `IDX_FACC_DOC_EXTERNO` (`CODIGO_PRV_FACC`,`DOC_EXTERNO_FACC`),
  KEY `IDX_FACC_EMPRESA` (`CODIGO_EMP_FACC`),
  KEY `IDX_FACC_EMP_INSTANTE` (`CODIGO_EMP_FACC`,`INSTANTE_ALTA`),
  KEY `IDX_FACC_ESTADO` (`ESTADO_FACC`),
  KEY `IDX_FACC_PROVEEDOR_FECHA` (`CODIGO_PRV_FACC`,`FECHA_FACC`),
  KEY `IDX_FACC_TEMPORADA` (`ID_PV_TEMPORADA_FACC`),
  KEY `IDX_FACC_CLI_FECHA` (`CODIGO_CLI_FACC`,`FECHA_FACC`),
  KEY `IDX_FACC_RECTIFICADA` (`SERIE_FACC_RECTIFICADA_FACC`,`NUMERO_FACC_RECTIFICADA_FACC`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_facturas_compra_celdas`;
CREATE TABLE `fza_facturas_compra_celdas` (
  `SERIE_FACC_FACCCEL` varchar(20) NOT NULL,
  `NUMERO_FACC_FACCCEL` varchar(20) NOT NULL,
  `LINEA_FACC_FACCCEL` varchar(4) NOT NULL,
  `ID_FILA_FACC_FACCCEL` int(11) NOT NULL DEFAULT 1,
  `ID_AV_PIVOT_FACCCEL` int(11) NOT NULL COMMENT 'ID del valor de atributo (talla) que pivota',
  `CANTIDAD_FACCCEL` decimal(19,6) NOT NULL DEFAULT 0.000000,
  `CODIGO_ALM_FACCCEL` varchar(10) DEFAULT NULL,
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  PRIMARY KEY (`SERIE_FACC_FACCCEL`,`NUMERO_FACC_FACCCEL`,`LINEA_FACC_FACCCEL`,`ID_FILA_FACC_FACCCEL`,`ID_AV_PIVOT_FACCCEL`),
  KEY `IDX_FACCCEL_LINEA` (`SERIE_FACC_FACCCEL`,`NUMERO_FACC_FACCCEL`,`LINEA_FACC_FACCCEL`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_facturas_compra_lineas`;
CREATE TABLE `fza_facturas_compra_lineas` (
  `NUMERO_FACC_FACCLIN` varchar(20) NOT NULL,
  `SERIE_FACC_FACCLIN` varchar(20) NOT NULL,
  `LINEA_FACCLIN` varchar(4) NOT NULL,
  `NUMERO_ALBC_FACCLIN` varchar(20) DEFAULT NULL,
  `SERIE_ALBC_FACCLIN` varchar(20) DEFAULT NULL,
  `LINEA_ALBC_FACCLIN` varchar(4) DEFAULT NULL COMMENT 'Linea de origen en fza_albaranes_compra_lineas',
  `NUMERO_DEVC_FACCLIN` varchar(20) DEFAULT NULL COMMENT 'Devolucion a proveedor de origen (abono)',
  `SERIE_DEVC_FACCLIN` varchar(20) DEFAULT NULL,
  `LINEA_DEVC_FACCLIN` varchar(4) DEFAULT NULL,
  `CODIGO_ART_FACCLIN` varchar(20) DEFAULT NULL,
  `CODIGO_UNIDAD_FACCLIN` varchar(50) DEFAULT NULL COMMENT 'SKU del articulo',
  `REF_PRV_FACCLIN` varchar(100) DEFAULT NULL,
  `ID_AC_PIVOT_FACCLIN` int(11) DEFAULT NULL COMMENT 'Conjunto de atributos pivot (fza_atributos_conjuntos)',
  `CODIGO_FAM_FACCLIN` varchar(20) DEFAULT NULL,
  `NOMBRE_FAM_FACCLIN` varchar(200) DEFAULT NULL,
  `DESCRIPCION_ARTICULO_FACCLIN` varchar(100) DEFAULT NULL,
  `TIPO_CANTIDAD_ARTICULO_FACCLIN` varchar(20) DEFAULT 'Uds',
  `CANTIDAD_FACCLIN` decimal(19,6) DEFAULT 1.000000,
  `TOTAL_UNIDADES_FACCLIN` decimal(19,6) DEFAULT 0.000000,
  `TIPO_IVA_ARTICULO_FACCLIN` varchar(2) DEFAULT 'N',
  `PORCENTAJE_IVA_FACCLIN` decimal(19,6) DEFAULT 0.000000,
  `PRECIO_COMPRA_SIVA_ARTICULO_FACCLIN` decimal(19,6) DEFAULT 0.000000,
  `PRECIO_COMPRA_CIVA_ARTICULO_FACCLIN` decimal(19,6) DEFAULT 0.000000,
  `TOTAL_FACCLIN` decimal(19,6) DEFAULT 0.000000 COMMENT 'Base imponible de la linea (precio compra siva x cantidad)',
  `CODIGO_ALMACEN_FACCLIN` varchar(10) DEFAULT NULL,
  `LOTE_FACCLIN` varchar(50) DEFAULT NULL,
  `FECHA_CADUCIDAD_FACCLIN` date DEFAULT NULL,
  `DESCRIPCION_VARIACION_FACCLIN` varchar(200) DEFAULT NULL,
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  `ATTR1_VALOR_FACCLIN` varchar(100) NOT NULL DEFAULT '',
  `ATTR1_NOMBRE_FACCLIN` varchar(100) NOT NULL DEFAULT '',
  `ATTR2_VALOR_FACCLIN` varchar(100) NOT NULL DEFAULT '',
  `ATTR2_NOMBRE_FACCLIN` varchar(100) NOT NULL DEFAULT '',
  `ATTR3_VALOR_FACCLIN` varchar(100) NOT NULL DEFAULT '',
  `ATTR3_NOMBRE_FACCLIN` varchar(100) NOT NULL DEFAULT '',
  `ATTR4_VALOR_FACCLIN` varchar(100) NOT NULL DEFAULT '',
  `ATTR4_NOMBRE_FACCLIN` varchar(100) NOT NULL DEFAULT '',
  `ATTR5_VALOR_FACCLIN` varchar(100) NOT NULL DEFAULT '',
  `ATTR5_NOMBRE_FACCLIN` varchar(100) NOT NULL DEFAULT '',
  `NUM_ATRIBUTOS_FACCLIN` int(11) NOT NULL DEFAULT 0 COMMENT 'Atributos requeridos del articulo',
  PRIMARY KEY (`NUMERO_FACC_FACCLIN`,`SERIE_FACC_FACCLIN`,`LINEA_FACCLIN`),
  KEY `IDX_FACCLIN_ALBARAN` (`SERIE_ALBC_FACCLIN`,`NUMERO_ALBC_FACCLIN`,`LINEA_ALBC_FACCLIN`),
  KEY `IDX_FACCLIN_ARTICULO` (`CODIGO_ART_FACCLIN`),
  KEY `IDX_FACCLIN_DEVOLUCION` (`SERIE_DEVC_FACCLIN`,`NUMERO_DEVC_FACCLIN`,`LINEA_DEVC_FACCLIN`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_facturas_consolidaciones`;
CREATE TABLE `fza_facturas_consolidaciones` (
  `ID_FACCON` int(11) NOT NULL,
  `SERIE_FAC_FACCON` varchar(20) NOT NULL,
  `NUMERO_FAC_FACCON` varchar(20) NOT NULL,
  `REQUEST_ID_CONSOLIDACION_FACCON` varchar(100) DEFAULT NULL COMMENT 'ID único de la petición',
  `QUEUE_ID_CONSOLIDACION_FACCON` int(11) DEFAULT NULL COMMENT 'ID de cola del sistema',
  `QUEUE_ID_CANCEL_FACCON` int(11) DEFAULT NULL COMMENT 'ID de cola del documento cancelado',
  `ISSUER_IRS_ID_CONSOLIDACION_FACCON` varchar(50) DEFAULT NULL COMMENT 'NIF del emisor',
  `ISSUED_TIME_FACCON` datetime DEFAULT NULL COMMENT 'Fecha y hora de emisión',
  `CHAIN_NUMBER_FACCON` varchar(100) DEFAULT NULL COMMENT 'Número de cadena del sistema',
  `CHAIN_HASH_FACCON` varchar(256) DEFAULT NULL COMMENT 'Hash de la cadena blockchain',
  `VERIFACTU_URL_FACCON` text DEFAULT NULL COMMENT 'URL de verificación en AEAT',
  `QRCODE_BASE64_FACCON` longtext DEFAULT NULL COMMENT 'Código QR en base64',
  `QRCODE_PNG_FACCON` blob DEFAULT NULL COMMENT 'Código QR en PNG',
  `FECHA_PROCESAMIENTO_FACCON` datetime DEFAULT current_timestamp() COMMENT 'Fecha de procesamiento',
  `ESTADO_FACCON` varchar(20) DEFAULT 'PROCESADO' COMMENT 'Estado del procesamiento. SII: SII_PROCESADO, SII_ACEPT_ERR, SII_DUPLICADO, SII_MODIFICADO, SII_ANULADO',
  `CODIGO_ERROR_AEAT_FACCON` varchar(20) DEFAULT NULL,
  `DESCRIPCION_ERROR_AEAT_FACCON` text DEFAULT NULL,
  `ESTADO_ORIGINAL_FACCON` varchar(30) DEFAULT NULL,
  `CODIGO_ERROR_ORIGINAL_FACCON` varchar(20) DEFAULT NULL,
  `DESCRIPCION_ERROR_ORIGINAL_FACCON` text DEFAULT NULL,
  `RESPUESTA_ORIGINAL_FACCON` longtext DEFAULT NULL,
  `PETICION_ORIGINAL_FACCON` longtext DEFAULT NULL,
  `REGISTRO_XML_ORIGINAL_FACCON` longtext DEFAULT NULL,
  `FIRMA_DIGITAL_ORIGINAL_FACCON` longtext DEFAULT NULL,
  `MOTIVO_SUBSANACION_FACCON` varchar(500) DEFAULT NULL,
  `INSTANTE_SUBSANACION_FACCON` datetime DEFAULT NULL,
  `USUARIO_SUBSANACION_FACCON` varchar(50) DEFAULT NULL,
  `RESPUESTA_COMPLETA_FACCON` longtext DEFAULT NULL COMMENT 'JSON completo de respuesta del webservice',
  `PETICION_COMPLETA_FACCON` longtext DEFAULT NULL COMMENT 'JSON completo de petición del webservice',
  `REGISTRO_XML_FACCON` longtext DEFAULT NULL,
  `FIRMA_DIGITAL_FACCON` longtext DEFAULT NULL,
  `SERIE_CERTIFICADO_FACCON` varchar(128) DEFAULT NULL,
  `TITULAR_CERTIFICADO_FACCON` varchar(1000) DEFAULT NULL,
  `HUELLA_CERTIFICADO_FACCON` char(40) DEFAULT NULL,
  `REQUEST_ID_ORIGINAL_FACCON` varchar(255) DEFAULT NULL,
  `CHAIN_NUMBER_ORIGINAL_FACCON` varchar(100) DEFAULT NULL,
  `CHAIN_HASH_ORIGINAL_FACCON` varchar(255) DEFAULT NULL,
  `SERIE_CERTIFICADO_ORIGINAL_FACCON` varchar(128) DEFAULT NULL,
  `TITULAR_CERTIFICADO_ORIGINAL_FACCON` varchar(1000) DEFAULT NULL,
  `HUELLA_CERTIFICADO_ORIGINAL_FACCON` char(40) DEFAULT NULL,
  PRIMARY KEY (`ID_FACCON`),
  UNIQUE KEY `UK_FACTURA` (`SERIE_FAC_FACCON`,`NUMERO_FAC_FACCON`),
  KEY `IDX_FECHA_PROCESAMIENTO_CONSOLIDACION` (`FECHA_PROCESAMIENTO_FACCON`),
  KEY `IDX_REQUEST_ID` (`REQUEST_ID_CONSOLIDACION_FACCON`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_facturas_lineas`;
CREATE TABLE `fza_facturas_lineas` (
  `NUMERO_FAC_FACLIN` varchar(20) NOT NULL,
  `SERIE_FAC_FACLIN` varchar(20) NOT NULL,
  `CODIGO_EMP_FACLIN` varchar(8) DEFAULT NULL,
  `LINEA_FACLIN` varchar(4) NOT NULL,
  `CODIGO_ART_FACLIN` varchar(20) DEFAULT NULL,
  `CODIGO_UNIDAD_FACLIN` varchar(50) DEFAULT NULL,
  `LOTE_FACLIN` varchar(50) DEFAULT NULL,
  `FECHA_CADUCIDAD_FACLIN` date DEFAULT NULL,
  `CODIGO_FAM_FACLIN` varchar(20) DEFAULT NULL,
  `NOMBRE_FAM_FACLIN` varchar(200) DEFAULT NULL,
  `PRECIO_ULT_COMPRA_FACLIN` decimal(19,6) DEFAULT NULL,
  `CODIGO_PRV_FACLIN` varchar(20) DEFAULT NULL,
  `RAZON_SOCIAL_PROVEEDOR_FACLIN` varchar(200) DEFAULT NULL,
  `ESPROVEEDORPRINCIPAL_FACLIN` varchar(1) DEFAULT NULL,
  `FECHA_ENTREGA_FACLIN` datetime DEFAULT NULL,
  `TIPO_ARTICULO_FACLIN` varchar(10) DEFAULT 'ESTANDAR' COMMENT 'ESTANDAR=Físico (Control Stock), SERVICIO=Intangible (Sin Stock), KIT=Pack',
  `TIPO_CANTIDAD_ARTICULO_FACLIN` varchar(20) DEFAULT 'Uds',
  `CANTIDAD_FACLIN` decimal(19,6) DEFAULT 1.000000,
  `DESCRIPCION_ARTICULO_FACLIN` varchar(100) DEFAULT NULL,
  `DESCRIPCION_VARIACION_FACLIN` varchar(200) DEFAULT NULL,
  `CODIGO_TAR_FACLIN` varchar(10) DEFAULT NULL,
  `ESIMP_INCL_TARIFA_FACLIN` varchar(1) DEFAULT 'S',
  `PRECIO_SALIDA_FACLIN` decimal(19,6) DEFAULT NULL,
  `PORCENTAJE_DTO_FACLIN` decimal(19,6) DEFAULT NULL,
  `PRECIO_DTO_FACLIN` decimal(19,6) DEFAULT NULL,
  `PRECIO_VENTA_SIVA_ARTICULO_FACLIN` decimal(19,6) DEFAULT 0.000000,
  `TIPO_IVA_ARTICULO_FACLIN` varchar(2) DEFAULT 'N',
  `PORCENTAJE_IVA_FACLIN` decimal(19,6) DEFAULT 0.000000,
  `PRECIO_VENTA_CIVA_ARTICULO_FACLIN` decimal(19,6) DEFAULT 0.000000,
  `TOTAL_FACLIN` decimal(19,6) DEFAULT 0.000000,
  `TOTAL_FAC_SIVA_FACLIN` decimal(19,6) DEFAULT NULL,
  `CODIGO_VENDEDOR_FACLIN` varchar(20) DEFAULT NULL COMMENT 'Vendedor que se lleva la comision (fza_empleados)',
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  `CODIGO_ALM_FACLIN` varchar(10) DEFAULT NULL,
  `CODIGO_CAJA_FACLIN` varchar(10) DEFAULT NULL,
  `NUMERO_OPERACION_FACLIN` varchar(20) DEFAULT NULL,
  `NUMERO_MOV_FACLIN` varchar(20) DEFAULT NULL,
  `ATTR1_VALOR_FACLIN` varchar(100) NOT NULL DEFAULT '',
  `ATTR1_NOMBRE_FACLIN` varchar(100) NOT NULL DEFAULT '',
  `ATTR2_VALOR_FACLIN` varchar(100) NOT NULL DEFAULT '',
  `ATTR2_NOMBRE_FACLIN` varchar(100) NOT NULL DEFAULT '',
  `ATTR3_VALOR_FACLIN` varchar(100) NOT NULL DEFAULT '',
  `ATTR3_NOMBRE_FACLIN` varchar(100) NOT NULL DEFAULT '',
  `ATTR4_VALOR_FACLIN` varchar(100) NOT NULL DEFAULT '',
  `ATTR4_NOMBRE_FACLIN` varchar(100) NOT NULL DEFAULT '',
  `ATTR5_VALOR_FACLIN` varchar(100) NOT NULL DEFAULT '',
  `ATTR5_NOMBRE_FACLIN` varchar(100) NOT NULL DEFAULT '',
  `NUM_ATRIBUTOS_FACLIN` int(11) NOT NULL DEFAULT 0 COMMENT 'Atributos requeridos del articulo',
  PRIMARY KEY (`NUMERO_FAC_FACLIN`,`SERIE_FAC_FACLIN`,`LINEA_FACLIN`),
  KEY `FT_FACLIN_DESC` (`DESCRIPCION_ARTICULO_FACLIN`),
  KEY `IDX_FACLIN_NUMMOV` (`NUMERO_MOV_FACLIN`),
  KEY `IDX_FACLIN_OPERACION` (`CODIGO_EMP_FACLIN`,`CODIGO_ALM_FACLIN`,`CODIGO_CAJA_FACLIN`,`NUMERO_OPERACION_FACLIN`),
  KEY `IDX_FACLIN_UNIDAD` (`CODIGO_UNIDAD_FACLIN`),
  KEY `IDX_FAC_LIN_ARTICULO` (`CODIGO_ART_FACLIN`,`SERIE_FAC_FACLIN`),
  KEY `IDX_FAC_LIN_FAMILIA` (`CODIGO_FAM_FACLIN`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_facturas_operaciones_caja`;
CREATE TABLE `fza_facturas_operaciones_caja` (
  `ID_FACOP` bigint(20) NOT NULL AUTO_INCREMENT,
  `ID_FACPER_FACOP` bigint(20) NOT NULL,
  `ID_OPCAJA_FACOP` bigint(20) NOT NULL,
  `SERIE_FAC_FACOP` varchar(20) NOT NULL,
  `NUMERO_FAC_FACOP` varchar(20) NOT NULL,
  `CODIGO_EMP_ORIGEN_FACOP` varchar(10) NOT NULL,
  `CODIGO_EMP_DESTINO_FACOP` varchar(10) NOT NULL,
  `NUMERO_OPERACION_FACOP` varchar(20) NOT NULL,
  `FECHA_OPERACION_FACOP` date NOT NULL,
  `IMPORTE_OPERACION_FACOP` decimal(19,6) NOT NULL DEFAULT 0.000000,
  `ESTADO_FACOP` varchar(20) NOT NULL DEFAULT 'FACTURADA',
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT current_timestamp(),
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  PRIMARY KEY (`ID_FACOP`),
  UNIQUE KEY `UQ_FACOP_OPERACION` (`ID_OPCAJA_FACOP`),
  KEY `IDX_FACOP_EMPRESAS` (`CODIGO_EMP_ORIGEN_FACOP`,`CODIGO_EMP_DESTINO_FACOP`),
  KEY `IDX_FACOP_ESTADO` (`ESTADO_FACOP`),
  KEY `IDX_FACOP_FACTURA` (`SERIE_FAC_FACOP`,`NUMERO_FAC_FACOP`),
  KEY `IDX_FACOP_PERIODO` (`ID_FACPER_FACOP`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_facturas_pagos`;
CREATE TABLE `fza_facturas_pagos` (
  `SERIE_FAC_FACPAG` varchar(20) NOT NULL COMMENT 'Vinculo con Cabecera SERIE',
  `NUMERO_FAC_FACPAG` varchar(20) NOT NULL COMMENT 'Vinculo con Cabecera NRO',
  `LINEA_FACPAG` int(11) NOT NULL COMMENT 'Contador secuencial (1, 2, 3...) para permitir varios pagos',
  `TIPO_FACPAG` varchar(50) DEFAULT 'EFECTIVO' COMMENT 'EFECTIVO, TARJETA, BONO_AYTO, VALE_TIENDA, ETC',
  `IMPORTE_FACPAG` decimal(19,6) NOT NULL DEFAULT 0.000000 COMMENT 'Cuantía pagada con este medio',
  `REFERENCIA_FACPAG` varchar(100) DEFAULT NULL COMMENT 'Aquí guardas el CÓDIGO DE BARRAS del bono o ref de tarjeta',
  `DESCRIPCION_FACPAG` varchar(200) DEFAULT NULL COMMENT 'Ej: Bono Comercio Campaña Navidad',
  `ENTIDAD_FACPAG` varchar(100) DEFAULT NULL COMMENT 'Banco, Ayuntamiento X, Asoc. Comerciantes',
  `FECHA_FACPAG` datetime DEFAULT NULL COMMENT 'Instante exacto del cobro',
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  PRIMARY KEY (`SERIE_FAC_FACPAG`,`NUMERO_FAC_FACPAG`,`LINEA_FACPAG`),
  KEY `IDX_FECHA_PAGO` (`FECHA_FACPAG`),
  KEY `IDX_TIPO_PAGO` (`TIPO_FACPAG`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_facturas_relaciones`;
CREATE TABLE `fza_facturas_relaciones` (
  `ID_FACREL` bigint(20) NOT NULL AUTO_INCREMENT,
  `SERIE_FAC_FACREL` varchar(20) NOT NULL COMMENT 'Serie de la factura hija (rectificativa o F3)',
  `NUMERO_FAC_FACREL` varchar(20) NOT NULL COMMENT 'Numero de la factura hija',
  `SERIE_FAC_ORIGEN_FACREL` varchar(20) NOT NULL COMMENT 'Serie de la factura original',
  `NUMERO_FAC_ORIGEN_FACREL` varchar(20) NOT NULL COMMENT 'Numero de la factura original',
  `TIPO_RELACION_FACREL` varchar(20) NOT NULL DEFAULT 'RECTIFICA' COMMENT 'RECTIFICA o SUSTITUYE',
  `INSTANTE_ALTA` datetime NOT NULL,
  `USUARIO_ALTA` varchar(50) DEFAULT NULL,
  `INSTANTE_MODIF` datetime DEFAULT NULL,
  `USUARIO_MODIF` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`ID_FACREL`),
  UNIQUE KEY `UQ_FACREL_FACTURA_ORIGEN_TIPO` (`SERIE_FAC_FACREL`,`NUMERO_FAC_FACREL`,`TIPO_RELACION_FACREL`,`SERIE_FAC_ORIGEN_FACREL`,`NUMERO_FAC_ORIGEN_FACREL`),
  KEY `IDX_FACREL_ORIGEN` (`SERIE_FAC_ORIGEN_FACREL`,`NUMERO_FAC_ORIGEN_FACREL`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_facturas_traspasos_vendidos`;
CREATE TABLE `fza_facturas_traspasos_vendidos` (
  `ID_FACTV` bigint(20) NOT NULL AUTO_INCREMENT,
  `ID_FACPER_FACTV` bigint(20) NOT NULL COMMENT 'Periodo de facturacion que genero la fila',
  `SERIE_FAC_FACTV` varchar(20) NOT NULL,
  `NUMERO_FAC_FACTV` varchar(20) NOT NULL,
  `NUMERO_MOV_TA_FACTV` varchar(20) NOT NULL COMMENT 'Salida TA del almacen origen que se factura',
  `NUMERO_MOV_VE_FACTV` varchar(20) NOT NULL COMMENT 'Venta o devolucion VE de la tienda destino',
  `ID_OPCAJA_TA_FACTV` bigint(20) NOT NULL COMMENT 'Operacion de caja del traspaso',
  `TIPO_FACTV` varchar(12) NOT NULL DEFAULT 'VENTA' COMMENT 'VENTA o DEVOLUCION',
  `CODIGO_EMP_ORIGEN_FACTV` varchar(10) NOT NULL,
  `CODIGO_EMP_DESTINO_FACTV` varchar(10) NOT NULL,
  `CODIGO_ALM_ORIGEN_FACTV` varchar(10) NOT NULL COMMENT 'Almacen del que salio la mercancia',
  `CODIGO_ALM_DESTINO_FACTV` varchar(10) NOT NULL COMMENT 'Tienda que la recibio y la vendio',
  `CODIGO_ART_FACTV` varchar(20) DEFAULT NULL,
  `CODIGO_UNIDAD_FACTV` varchar(50) NOT NULL COMMENT 'SKU',
  `CANTIDAD_FACTV` decimal(19,6) NOT NULL DEFAULT 0.000000 COMMENT 'Positiva si se factura, negativa si se devuelve',
  `PRECIO_FACTV` decimal(19,6) NOT NULL DEFAULT 0.000000 COMMENT 'Precio unitario sin IVA con el que se facturo',
  `FECHA_VENTA_FACTV` date NOT NULL COMMENT 'Fecha del movimiento de venta o devolucion',
  `FECHA_TRASPASO_FACTV` date DEFAULT NULL COMMENT 'Fecha del traspaso que se consume',
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  PRIMARY KEY (`ID_FACTV`),
  KEY `IDX_FACTV_DESTINO_SKU` (`CODIGO_ALM_DESTINO_FACTV`,`CODIGO_UNIDAD_FACTV`,`CODIGO_EMP_ORIGEN_FACTV`),
  KEY `IDX_FACTV_FACTURA` (`SERIE_FAC_FACTV`,`NUMERO_FAC_FACTV`),
  KEY `IDX_FACTV_MOV_TA` (`NUMERO_MOV_TA_FACTV`),
  KEY `IDX_FACTV_MOV_VE` (`NUMERO_MOV_VE_FACTV`),
  KEY `IDX_FACTV_OPERACION` (`ID_OPCAJA_TA_FACTV`),
  KEY `IDX_FACTV_PERIODO` (`ID_FACPER_FACTV`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_familias_atributos`;
CREATE TABLE `fza_familias_atributos` (
  `CODIGO_FAM_FAM` varchar(20) NOT NULL COMMENT 'FK hacia fza_articulos_familias',
  `CODIGO_PROP_ARTPROP` varchar(20) NOT NULL COMMENT 'FK hacia fza_propiedades',
  `ESREQUERIDO_FA` varchar(1) DEFAULT 'N' COMMENT 'S para obligatorio',
  `ORDEN_MOSTRAR_FA` int(11) DEFAULT 0 COMMENT 'Para ordenar el formulario',
  PRIMARY KEY (`CODIGO_FAM_FAM`,`CODIGO_PROP_ARTPROP`),
  KEY `IDX_FAM_ATR_ATR` (`CODIGO_PROP_ARTPROP`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_familias_atributos_defecto`;
CREATE TABLE `fza_familias_atributos_defecto` (
  `CODIGO_FAM_FAD` varchar(20) NOT NULL,
  `ID_VA_ATB_FAD` varchar(20) NOT NULL,
  `ESOBLIGATORIO_FAD` varchar(1) DEFAULT 'N',
  PRIMARY KEY (`CODIGO_FAM_FAD`,`ID_VA_ATB_FAD`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_familias_claves_info_defecto`;
CREATE TABLE `fza_familias_claves_info_defecto` (
  `CODIGO_FAM_FCI` varchar(20) NOT NULL,
  `ID_VA_ATB_FCI` varchar(20) NOT NULL,
  `CLAVE_FCI` varchar(50) NOT NULL,
  `VALOR_DEFECTO_FCI` varchar(100) DEFAULT NULL,
  `ESOBLIGATORIO_FCI` varchar(1) DEFAULT 'N',
  PRIMARY KEY (`CODIGO_FAM_FCI`,`ID_VA_ATB_FCI`,`CLAVE_FCI`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_filtros_guardados`;
CREATE TABLE `fza_filtros_guardados` (
  `ID_FILT` bigint(20) NOT NULL AUTO_INCREMENT,
  `MTO_FILT` varchar(100) NOT NULL,
  `VISTA_FILT` varchar(100) NOT NULL,
  `NOMBRE_FILT` varchar(100) NOT NULL,
  `DESCRIPCION_FILT` varchar(255) DEFAULT NULL,
  `FILTRO_FILT` mediumtext NOT NULL,
  `USUARIO_PROPIETARIO_FILT` varchar(100) NOT NULL,
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL DEFAULT 'SISTEMA',
  `USUARIO_MODIF` varchar(100) NOT NULL DEFAULT 'SISTEMA',
  PRIMARY KEY (`ID_FILT`),
  UNIQUE KEY `UQ_FILT_MTO_VISTA_NOMBRE_PROP` (`MTO_FILT`,`VISTA_FILT`,`NOMBRE_FILT`,`USUARIO_PROPIETARIO_FILT`),
  KEY `IDX_FILT_MTO_VISTA` (`MTO_FILT`,`VISTA_FILT`),
  KEY `IDX_FILT_PROPIETARIO` (`USUARIO_PROPIETARIO_FILT`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_filtros_guardados_compartidos`;
CREATE TABLE `fza_filtros_guardados_compartidos` (
  `ID_FILTC` bigint(20) NOT NULL AUTO_INCREMENT,
  `ID_FILT_FILTC` bigint(20) NOT NULL,
  `USUARIO_GRUPO_FILTC` varchar(200) NOT NULL DEFAULT '',
  `TIPO_DESTINO_FILTC` varchar(20) NOT NULL DEFAULT 'USUARIO',
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL DEFAULT 'SISTEMA',
  `USUARIO_MODIF` varchar(100) NOT NULL DEFAULT 'SISTEMA',
  PRIMARY KEY (`ID_FILTC`),
  UNIQUE KEY `UQ_FILTC_FILT_TIPO_DESTINO` (`ID_FILT_FILTC`,`TIPO_DESTINO_FILTC`,`USUARIO_GRUPO_FILTC`),
  KEY `IDX_FILTC_FILT` (`ID_FILT_FILTC`),
  KEY `IDX_FILTC_TIPO_DESTINO_USUARIO_GRUPO` (`TIPO_DESTINO_FILTC`,`USUARIO_GRUPO_FILTC`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_formas_pago`;
CREATE TABLE `fza_formas_pago` (
  `CODIGO_FP_FP` varchar(20) NOT NULL,
  `ESACTIVO_FORMA_PAGO_FP` varchar(1) DEFAULT NULL,
  `ORDEN_FORMA_PAGO_FP` int(11) DEFAULT NULL,
  `DESCRIPCION_FORMA_PAGO_FP` varchar(100) DEFAULT NULL,
  `N_PLAZOS_FORMA_PAGO_FP` int(11) DEFAULT 1,
  `N_DIAS_ENTRE_PLAZOS_FORMA_PAGO_FP` int(11) DEFAULT 0,
  `PORCENTAJE_ANTICIPO_FORMA_PAGO_FP` int(11) DEFAULT NULL,
  `ESVERBANCOEMPRESA_FORMA_PAGO_FP` varchar(1) DEFAULT NULL,
  `CODIGO_FACTURAE_FP` varchar(2) DEFAULT '01',
  `ESCONTADO_FORMA_PAGO_FP` varchar(1) DEFAULT NULL,
  `CODIGO_TEFE_FP` varchar(20) DEFAULT NULL,
  `ESDEFAULT_FORMA_PAGO_FP` varchar(1) DEFAULT 'N',
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  PRIMARY KEY (`CODIGO_FP_FP`),
  KEY `IDX_FP_CODIGO_TEFE` (`CODIGO_TEFE_FP`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_garantias_fases`;
CREATE TABLE `fza_garantias_fases` (
  `CODIGO_GARFA` varchar(32) NOT NULL,
  `DESCRIPCION_GARFA` varchar(120) NOT NULL,
  `ORDEN_GARFA` int(11) NOT NULL DEFAULT 100,
  `ESACTIVO_GARFA` varchar(1) NOT NULL DEFAULT 'S',
  `INSTANTE_ALTA` datetime(6) NOT NULL,
  `USUARIO_ALTA` varchar(50) NOT NULL,
  `INSTANTE_MODIF` datetime(6) DEFAULT NULL,
  `USUARIO_MODIF` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`CODIGO_GARFA`),
  UNIQUE KEY `UQ_GARFA_DESCRIPCION` (`DESCRIPCION_GARFA`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_garantias_fases_avisos`;
CREATE TABLE `fza_garantias_fases_avisos` (
  `ID_GARAVI` varchar(32) NOT NULL,
  `ID_GAR_GARAVI` bigint(20) NOT NULL,
  `ID_GARHIS_GARAVI` bigint(20) NOT NULL,
  `EMAIL_GARAVI` varchar(254) NOT NULL,
  `ASUNTO_GARAVI` varchar(200) NOT NULL,
  `TEXTO_GARAVI` text NOT NULL,
  `ESTADO_GARAVI` varchar(20) NOT NULL,
  `RESULTADO_GARAVI` text DEFAULT NULL,
  `INSTANTE_ALTA` datetime(6) NOT NULL,
  `USUARIO_ALTA` varchar(50) NOT NULL,
  `INSTANTE_MODIF` datetime(6) DEFAULT NULL,
  `USUARIO_MODIF` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`ID_GARAVI`),
  KEY `IDX_GARAVI_GAR_INSTANTE` (`ID_GAR_GARAVI`,`INSTANTE_ALTA`),
  KEY `IDX_GARAVI_GARHIS` (`ID_GARHIS_GARAVI`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_garantias_fases_hist`;
CREATE TABLE `fza_garantias_fases_hist` (
  `ID_GARHIS` bigint(20) NOT NULL AUTO_INCREMENT,
  `ID_GAR_GARHIS` bigint(20) NOT NULL,
  `CODIGO_ANTERIOR_GARHIS` varchar(32) DEFAULT NULL,
  `FASE_ANTERIOR_GARHIS` varchar(120) DEFAULT NULL,
  `CODIGO_GARFA_GARHIS` varchar(32) NOT NULL,
  `FASE_GARHIS` varchar(120) NOT NULL,
  `INSTANTE_GARHIS` datetime(6) NOT NULL,
  `OBSERVACIONES_GARHIS` text DEFAULT NULL,
  `INSTANTE_ALTA` datetime(6) NOT NULL,
  `USUARIO_ALTA` varchar(50) NOT NULL,
  `INSTANTE_MODIF` datetime(6) DEFAULT NULL,
  `USUARIO_MODIF` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`ID_GARHIS`),
  KEY `IDX_GARHIS_GAR_ID` (`ID_GAR_GARHIS`,`ID_GARHIS`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_garantias_lineas`;
CREATE TABLE `fza_garantias_lineas` (
  `ID_GARLIN` bigint(20) NOT NULL AUTO_INCREMENT,
  `ID_GAR_GARLIN` bigint(20) NOT NULL,
  `LINEA_GARLIN` int(11) NOT NULL,
  `TIPO_LINEA_GARLIN` varchar(10) NOT NULL DEFAULT 'MANO_OBRA' COMMENT 'MANO_OBRA o MATERIAL',
  `CODIGO_GARTIP_GARLIN` varchar(20) DEFAULT NULL,
  `DESCRIPCION_GARLIN` varchar(200) NOT NULL,
  `TIPO_EJECUTOR_GARLIN` varchar(10) DEFAULT NULL COMMENT 'OPERARIO o EXTERNO (solo mano de obra)',
  `CODIGO_EMPL_GARLIN` varchar(20) DEFAULT NULL,
  `CODIGO_PRV_GARLIN` varchar(20) DEFAULT NULL,
  `CODIGO_UNIDAD_GARLIN` varchar(50) DEFAULT NULL COMMENT 'SKU (material)',
  `CANTIDAD_GARLIN` decimal(19,6) NOT NULL DEFAULT 1.000000 COMMENT 'Horas o unidades',
  `PRECIO_CLIENTE_GARLIN` decimal(19,6) NOT NULL DEFAULT 0.000000 COMMENT 'Unitario al cliente con impuestos',
  `PRECIO_COSTE_GARLIN` decimal(19,6) NOT NULL DEFAULT 0.000000 COMMENT 'Unitario sin impuestos',
  `FECHA_INICIO_GARLIN` datetime DEFAULT NULL,
  `FECHA_FIN_GARLIN` datetime DEFAULT NULL,
  `ESINCIDENCIA_GARLIN` varchar(1) NOT NULL DEFAULT 'N',
  `INCIDENCIA_GARLIN` varchar(500) DEFAULT NULL,
  `ID_GARLIQ_GARLIN` bigint(20) DEFAULT NULL COMMENT 'Liquidacion PAGO al externo',
  `ID_GARLIQ_CARGO_GARLIN` bigint(20) DEFAULT NULL COMMENT 'Liquidacion CARGO al fabricante',
  `INSTANTE_ALTA` datetime NOT NULL,
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `INSTANTE_MODIF` datetime DEFAULT NULL,
  `USUARIO_MODIF` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`ID_GARLIN`),
  UNIQUE KEY `UQ_GARLIN_GAR_LINEA` (`ID_GAR_GARLIN`,`LINEA_GARLIN`),
  KEY `IDX_GARLIN_PRV_FIN` (`CODIGO_PRV_GARLIN`,`FECHA_FIN_GARLIN`),
  KEY `IDX_GARLIN_EMPL_FIN` (`CODIGO_EMPL_GARLIN`,`FECHA_FIN_GARLIN`),
  KEY `IDX_GARLIN_UNIDAD` (`CODIGO_UNIDAD_GARLIN`),
  KEY `IDX_GARLIN_GARLIQ` (`ID_GARLIQ_GARLIN`),
  KEY `IDX_GARLIN_GARLIQ_CARGO` (`ID_GARLIQ_CARGO_GARLIN`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_garantias_liquidaciones`;
CREATE TABLE `fza_garantias_liquidaciones` (
  `ID_GARLIQ` bigint(20) NOT NULL AUTO_INCREMENT,
  `SENTIDO_GARLIQ` varchar(6) NOT NULL DEFAULT 'PAGO' COMMENT 'PAGO a un externo o CARGO al fabricante',
  `CODIGO_EMP_GARLIQ` varchar(10) NOT NULL,
  `CODIGO_PRV_GARLIQ` varchar(20) NOT NULL,
  `FECHA_GARLIQ` date NOT NULL,
  `FECHA_HASTA_GARLIQ` date NOT NULL COMMENT 'Lineas terminadas hasta esta fecha',
  `CANTIDAD_LINEAS_GARLIQ` int(11) NOT NULL DEFAULT 0,
  `TOTAL_GARLIQ` decimal(19,6) NOT NULL DEFAULT 0.000000 COMMENT 'Suma de costes sin impuestos',
  `TIPO_DOC_GARLIQ` varchar(5) DEFAULT NULL COMMENT 'Documento que lo salda: FP (compra) o FA (venta)',
  `SERIE_DOC_GARLIQ` varchar(20) DEFAULT NULL,
  `NUMERO_DOC_GARLIQ` varchar(20) DEFAULT NULL,
  `FECHA_ABONO_GARLIQ` date DEFAULT NULL COMMENT 'Cargo: fecha en que el fabricante lo abona',
  `OBSERVACIONES_GARLIQ` varchar(500) DEFAULT NULL,
  `INSTANTE_ALTA` datetime NOT NULL,
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `INSTANTE_MODIF` datetime DEFAULT NULL,
  `USUARIO_MODIF` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`ID_GARLIQ`),
  KEY `IDX_GARLIQ_PRV_FECHA` (`CODIGO_PRV_GARLIQ`,`FECHA_GARLIQ`),
  KEY `IDX_GARLIQ_SENTIDO_ABONO` (`SENTIDO_GARLIQ`,`FECHA_ABONO_GARLIQ`),
  KEY `IDX_GARLIQ_DOC` (`TIPO_DOC_GARLIQ`,`SERIE_DOC_GARLIQ`,`NUMERO_DOC_GARLIQ`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_garantias_movimientos`;
CREATE TABLE `fza_garantias_movimientos` (
  `ID_GARMOV` bigint(20) NOT NULL AUTO_INCREMENT,
  `ID_GAR_GARMOV` bigint(20) NOT NULL,
  `ID_ANTERIOR_GARMOV` bigint(20) DEFAULT NULL,
  `INSTANTE_GARMOV` datetime NOT NULL,
  `ORIGEN_GARMOV` varchar(100) NOT NULL,
  `DESTINO_GARMOV` varchar(100) NOT NULL,
  `ESTADO_GARMOV` varchar(20) NOT NULL,
  `OBJETO_GARMOV` varchar(200) NOT NULL,
  `AGENCIA_GARMOV` varchar(100) DEFAULT NULL,
  `TRACKING_GARMOV` varchar(100) DEFAULT NULL,
  `INCIDENCIA_GARMOV` text DEFAULT NULL,
  `FASE_INICIAL_GARMOV` int(11) DEFAULT NULL,
  `INSTANTE_ALTA` datetime NOT NULL,
  `USUARIO_ALTA` varchar(50) NOT NULL,
  `INSTANTE_MODIF` datetime DEFAULT NULL,
  `USUARIO_MODIF` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`ID_GARMOV`),
  UNIQUE KEY `UQ_GARMOV_GAR_FASE` (`ID_GAR_GARMOV`,`FASE_INICIAL_GARMOV`),
  KEY `IDX_GARMOV_GAR_INSTANTE` (`ID_GAR_GARMOV`,`INSTANTE_GARMOV`,`ID_GARMOV`),
  KEY `IDX_GARMOV_ANTERIOR` (`ID_ANTERIOR_GARMOV`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_garantias_reclamaciones`;
CREATE TABLE `fza_garantias_reclamaciones` (
  `ID_GAR` bigint(20) NOT NULL AUTO_INCREMENT,
  `CODIGO_UNIDAD_GAR` varchar(50) DEFAULT NULL,
  `LOTE_GAR` varchar(50) DEFAULT NULL,
  `CODIGO_ART_GAR` varchar(20) DEFAULT NULL,
  `CODIGO_CLI_GAR` varchar(20) DEFAULT NULL,
  `TIPO_DOC_VENTA_GAR` varchar(5) DEFAULT NULL,
  `SERIE_DOC_VENTA_GAR` varchar(20) DEFAULT NULL,
  `NUMERO_DOC_VENTA_GAR` varchar(20) DEFAULT NULL,
  `FECHA_VENTA_GAR` date DEFAULT NULL,
  `FECHA_FIN_GARANTIA_GAR` date DEFAULT NULL,
  `FECHA_RECLAMACION_GAR` datetime NOT NULL,
  `MOTIVO_GAR` varchar(500) DEFAULT NULL,
  `ESTADO_GAR` varchar(12) NOT NULL DEFAULT 'ABIERTA',
  `RESOLUCION_GAR` varchar(12) DEFAULT NULL,
  `LOTE_SUSTITUTO_GAR` varchar(50) DEFAULT NULL,
  `FECHA_RESOLUCION_GAR` datetime DEFAULT NULL,
  `CODIGO_ALM_GAR` varchar(10) DEFAULT NULL,
  `NUMERO_ORDEN_GAR` bigint(20) DEFAULT NULL,
  `OBSERVACIONES_GAR` varchar(500) DEFAULT NULL,
  `MODELO_GAR` varchar(100) DEFAULT NULL,
  `CODIGO_PRV_GAR` varchar(20) DEFAULT NULL,
  `NOMBRE_CLIENTE_GAR` varchar(200) DEFAULT NULL,
  `TELEFONO_CLIENTE_GAR` varchar(40) DEFAULT NULL,
  `EMAIL_CLIENTE_GAR` varchar(200) DEFAULT NULL,
  `DIRECCION_CLIENTE_GAR` varchar(200) DEFAULT NULL,
  `CODIGO_POSTAL_CLIENTE_GAR` varchar(15) DEFAULT NULL,
  `POBLACION_CLIENTE_GAR` varchar(200) DEFAULT NULL,
  `PROVINCIA_CLIENTE_GAR` varchar(200) DEFAULT NULL,
  `FECHA_RECEPCION_GAR` date DEFAULT NULL,
  `MEDIO_RECEPCION_GAR` varchar(10) NOT NULL DEFAULT 'TIENDA',
  `AGENCIA_RECEPCION_GAR` varchar(100) DEFAULT NULL,
  `TRACKING_RECEPCION_GAR` varchar(100) DEFAULT NULL,
  `OBSERVACIONES_RECEPCION_GAR` varchar(500) DEFAULT NULL,
  `FECHA_ENVIO_FAB_GAR` date DEFAULT NULL,
  `RMA_GAR` varchar(100) DEFAULT NULL,
  `DIRECCION_ENVIO_FAB_GAR` varchar(500) DEFAULT NULL,
  `AGENCIA_ENVIO_FAB_GAR` varchar(100) DEFAULT NULL,
  `TRACKING_ENVIO_FAB_GAR` varchar(100) DEFAULT NULL,
  `ESINCIDENCIA_ENVIO_FAB_GAR` varchar(1) NOT NULL DEFAULT 'N',
  `INCIDENCIA_ENVIO_FAB_GAR` varchar(500) DEFAULT NULL,
  `RECLAMACION_TRANSPORTE_ENVIO_FAB_GAR` varchar(100) DEFAULT NULL,
  `FECHA_RECEPCION_FAB_GAR` date DEFAULT NULL,
  `TRACKING_RECEPCION_FAB_GAR` varchar(100) DEFAULT NULL,
  `ESINCIDENCIA_RECEPCION_FAB_GAR` varchar(1) NOT NULL DEFAULT 'N',
  `INCIDENCIA_RECEPCION_FAB_GAR` varchar(500) DEFAULT NULL,
  `RECLAMACION_TRANSPORTE_RECEPCION_FAB_GAR` varchar(100) DEFAULT NULL,
  `OBSERVACIONES_RECEPCION_FAB_GAR` varchar(500) DEFAULT NULL,
  `FECHA_ENTREGA_CLI_GAR` date DEFAULT NULL,
  `MEDIO_ENTREGA_CLI_GAR` varchar(10) NOT NULL DEFAULT 'TIENDA',
  `AGENCIA_ENTREGA_CLI_GAR` varchar(100) DEFAULT NULL,
  `TRACKING_ENTREGA_CLI_GAR` varchar(100) DEFAULT NULL,
  `ESINCIDENCIA_ENTREGA_CLI_GAR` varchar(1) NOT NULL DEFAULT 'N',
  `INCIDENCIA_ENTREGA_CLI_GAR` varchar(500) DEFAULT NULL,
  `RECLAMACION_TRANSPORTE_ENTREGA_CLI_GAR` varchar(100) DEFAULT NULL,
  `INSTANTE_ALTA` datetime NOT NULL DEFAULT current_timestamp(),
  `USUARIO_ALTA` varchar(50) NOT NULL,
  `INSTANTE_MODIF` datetime DEFAULT NULL,
  `USUARIO_MODIF` varchar(50) DEFAULT NULL,
  `MODALIDAD_GAR` varchar(10) NOT NULL DEFAULT 'GARANTIA' COMMENT 'GARANTIA, PAGO o CORTESIA',
  `CODIGO_GARTIP_GAR` varchar(20) DEFAULT NULL,
  `CATEGORIA_GAR` varchar(20) DEFAULT NULL,
  `ORIGEN_OBJETO_GAR` varchar(10) DEFAULT NULL COMMENT 'VENDIDO, CLIENTE o TIENDA',
  `DESCRIPCION_OBJETO_GAR` varchar(200) DEFAULT NULL,
  `REFERENCIA_OBJETO_GAR` varchar(100) DEFAULT NULL COMMENT 'Matricula, bastidor, modelo',
  `DETALLES_GAR` varchar(500) DEFAULT NULL COMMENT 'Medidas, kilometros, averia',
  `FECHA_PREVISTA_GAR` date DEFAULT NULL COMMENT 'Fecha aproximada de entrega',
  `ESPRESUPUESTO_GAR` varchar(1) NOT NULL DEFAULT 'N',
  `TOTAL_PRESUPUESTO_GAR` decimal(19,6) DEFAULT NULL,
  `FECHA_PRESUPUESTO_GAR` date DEFAULT NULL,
  `ESTADO_PRESUPUESTO_GAR` varchar(10) DEFAULT NULL COMMENT 'PENDIENTE, ACEPTADO o RECHAZADO',
  `FECHA_RESPUESTA_PRESUPUESTO_GAR` date DEFAULT NULL,
  `MODO_COBRO_GAR` varchar(10) DEFAULT NULL COMMENT 'COMPRA, RECOGIDA o GRATIS',
  `ESCOBRADO_GAR` varchar(1) NOT NULL DEFAULT 'N',
  `SERIE_COBRO_GAR` varchar(20) DEFAULT NULL,
  `NUMERO_COBRO_GAR` varchar(20) DEFAULT NULL,
  `CODIGO_GARFA_GAR` varchar(32) DEFAULT NULL,
  `CODIGO_CLI_PAGADOR_GAR` varchar(20) DEFAULT NULL,
  `FRANQUICIA_GAR` decimal(18,2) NOT NULL DEFAULT 0.00,
  PRIMARY KEY (`ID_GAR`),
  UNIQUE KEY `UQ_GAR_ALMACEN_NUMERO_ORDEN` (`CODIGO_ALM_GAR`,`NUMERO_ORDEN_GAR`),
  KEY `IDX_GAR_CLIENTE` (`CODIGO_CLI_GAR`),
  KEY `IDX_GAR_ESTADO` (`ESTADO_GAR`,`FECHA_RECLAMACION_GAR`),
  KEY `IDX_GAR_LOTE` (`LOTE_GAR`),
  KEY `IDX_GAR_PRV` (`CODIGO_PRV_GAR`),
  KEY `IDX_GAR_MODALIDAD_ESTADO` (`MODALIDAD_GAR`,`ESTADO_GAR`),
  KEY `IDX_GAR_PREVISTA` (`FECHA_PREVISTA_GAR`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_garantias_tipos`;
CREATE TABLE `fza_garantias_tipos` (
  `CODIGO_GARTIP` varchar(20) NOT NULL,
  `CATEGORIA_GARTIP` varchar(20) NOT NULL DEFAULT 'GENERAL' COMMENT 'ARREGLOS, TALLER, ELECTRONICA...',
  `DESCRIPCION_GARTIP` varchar(100) NOT NULL,
  `MODALIDAD_GARTIP` varchar(10) NOT NULL DEFAULT 'PAGO' COMMENT 'GARANTIA, PAGO o CORTESIA',
  `ESPRESUPUESTO_GARTIP` varchar(1) NOT NULL DEFAULT 'N',
  `PRECIO_CLIENTE_GARTIP` decimal(19,6) NOT NULL DEFAULT 0.000000 COMMENT 'Precio unitario al cliente con impuestos',
  `PRECIO_COSTE_GARTIP` decimal(19,6) NOT NULL DEFAULT 0.000000 COMMENT 'Coste unitario sin impuestos',
  `CANTIDAD_GARTIP` decimal(19,6) NOT NULL DEFAULT 1.000000 COMMENT 'Horas o unidades por defecto',
  `MODO_COBRO_GARTIP` varchar(10) NOT NULL DEFAULT 'RECOGIDA' COMMENT 'COMPRA, RECOGIDA o GRATIS',
  `DIAS_PLAZO_GARTIP` int(11) NOT NULL DEFAULT 3,
  `CODIGO_ART_GARTIP` varchar(20) DEFAULT NULL COMMENT 'Articulo de servicio con que se cobra en el TPV',
  `TIPO_EJECUTOR_GARTIP` varchar(10) DEFAULT NULL COMMENT 'OPERARIO o EXTERNO',
  `CODIGO_EMPL_GARTIP` varchar(20) DEFAULT NULL,
  `CODIGO_PRV_GARTIP` varchar(20) DEFAULT NULL,
  `ORDEN_GARTIP` int(11) NOT NULL DEFAULT 0,
  `ESACTIVO_GARTIP` varchar(1) NOT NULL DEFAULT 'S',
  `INSTANTE_ALTA` datetime NOT NULL,
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `INSTANTE_MODIF` datetime DEFAULT NULL,
  `USUARIO_MODIF` varchar(100) DEFAULT NULL,
  `CLASE_SERVICIO_GARTIP` varchar(20) NOT NULL DEFAULT 'TALLER',
  PRIMARY KEY (`CODIGO_GARTIP`),
  KEY `IDX_GARTIP_CATEGORIA` (`CATEGORIA_GARTIP`,`ORDEN_GARTIP`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_generadorprocesos`;
CREATE TABLE `fza_generadorprocesos` (
  `CODIGO_GENERADOR_PROCESO_GP` varchar(20) NOT NULL,
  `NOMBRE_GENERADOR_PROCESO_GP` varchar(100) DEFAULT NULL,
  `PROCESO_GENERADOR_PROCESO_GP` mediumtext DEFAULT NULL,
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  PRIMARY KEY (`CODIGO_GENERADOR_PROCESO_GP`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_informes_guias`;
CREATE TABLE `fza_informes_guias` (
  `CODIGO_INFGUI` varchar(120) NOT NULL,
  `INFORME_INFGUI` varchar(100) NOT NULL,
  `FORMATO_INFGUI` varchar(200) NOT NULL DEFAULT '',
  `DATASET_MASTER_INFGUI` varchar(100) NOT NULL,
  `TIPO_INFGUI` varchar(10) NOT NULL,
  `TABLA_INFGUI` varchar(60) DEFAULT NULL,
  `SQL_INFGUI` text DEFAULT NULL,
  `MASTER_FIELDS_INFGUI` varchar(200) NOT NULL,
  `DETAIL_FIELDS_INFGUI` varchar(200) NOT NULL,
  `ORDEN_INFGUI` int(11) NOT NULL DEFAULT 0,
  `ESACTIVO_INFGUI` varchar(1) NOT NULL DEFAULT 'S',
  `COLUMNAS_VISIBLES_INFGUI` text DEFAULT NULL,
  `INSTANTE_ALTA` datetime NOT NULL,
  `USUARIO_ALTA` varchar(50) NOT NULL,
  `INSTANTE_MODIF` datetime DEFAULT NULL,
  `USUARIO_MODIF` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`CODIGO_INFGUI`,`INFORME_INFGUI`,`FORMATO_INFGUI`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_inventarios`;
CREATE TABLE `fza_inventarios` (
  `CODIGO_EMP_INV` varchar(10) NOT NULL,
  `CODIGO_ALM_INV` varchar(10) NOT NULL,
  `SERIE_INV` varchar(20) NOT NULL,
  `NUMERO_INV` varchar(20) NOT NULL,
  `TIPO_DOC_INV` varchar(5) NOT NULL DEFAULT 'IN',
  `FECHA_INV` datetime NOT NULL,
  `ESTADO_INV` varchar(20) NOT NULL DEFAULT 'ABIERTO' COMMENT 'ABIERTO, CERRADO, APLICADO, CANCELADO',
  `DESCRIPCION_INV` varchar(200) DEFAULT NULL,
  `OBSERVACIONES_INV` text DEFAULT NULL,
  `TOTAL_UNIDADES_DIFERENCIA_INV` decimal(19,6) DEFAULT 0.000000 COMMENT 'Suma total de unidades de descuadre',
  `TOTAL_EUROS_DIFERENCIA_INV` decimal(19,6) DEFAULT 0.000000 COMMENT 'Variación económica total (apreciación/depreciación global)',
  `CONTADOR_LINEAS_INV` varchar(8) NOT NULL DEFAULT '00000000' COMMENT 'Contador de lineas de inventario',
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  `ESRECUENTO_REMOTO_INV` char(1) NOT NULL DEFAULT 'N',
  `INSTANTE_ENVIO_RECUENTO_INV` datetime DEFAULT NULL,
  `INSTANTE_RECOGIDA_RECUENTO_INV` datetime DEFAULT NULL,
  `ID_RECUENTO_REMOTO_INV` varchar(40) DEFAULT NULL,
  `ESSOLONEGATIVOS_INV` varchar(1) NOT NULL DEFAULT 'N',
  PRIMARY KEY (`CODIGO_EMP_INV`,`CODIGO_ALM_INV`,`SERIE_INV`,`NUMERO_INV`),
  KEY `IDX_INV_EMP_INSTANTE` (`CODIGO_EMP_INV`,`INSTANTE_ALTA`),
  KEY `IDX_INV_ESTADO` (`CODIGO_EMP_INV`,`CODIGO_ALM_INV`,`ESTADO_INV`),
  KEY `IDX_INV_FECHA` (`FECHA_INV`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_inventarios_celdas`;
CREATE TABLE `fza_inventarios_celdas` (
  `CODIGO_EMP_INVCEL` varchar(10) NOT NULL,
  `CODIGO_ALM_INV_INVCEL` varchar(10) NOT NULL,
  `SERIE_INV_INVCEL` varchar(20) NOT NULL,
  `NUMERO_INV_INVCEL` varchar(20) NOT NULL,
  `LINEA_INVCEL` int(11) NOT NULL,
  `ID_FILA_INVCEL` int(11) NOT NULL,
  `ID_AV_PIVOT_INVCEL` int(11) NOT NULL COMMENT 'FK logica fza_atributos_valores del eje pivot (TALLA)',
  `CODIGO_ALM_INVCEL` varchar(10) NOT NULL DEFAULT '' COMMENT 'Almacen de celda (uniformidad gestor; en inventario va vacio)',
  `CANTIDAD_INVCEL` decimal(19,6) NOT NULL COMMENT 'Cantidad CONTADA en la celda',
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL DEFAULT '',
  `INSTANTE_MODIF` datetime DEFAULT NULL,
  `USUARIO_MODIF` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`CODIGO_EMP_INVCEL`,`CODIGO_ALM_INV_INVCEL`,`SERIE_INV_INVCEL`,`NUMERO_INV_INVCEL`,`LINEA_INVCEL`,`ID_FILA_INVCEL`,`ID_AV_PIVOT_INVCEL`,`CODIGO_ALM_INVCEL`),
  KEY `IDX_INVCEL_AV_PIVOT` (`ID_AV_PIVOT_INVCEL`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_inventarios_lineas`;
CREATE TABLE `fza_inventarios_lineas` (
  `CODIGO_EMP_INVLIN` varchar(10) NOT NULL,
  `CODIGO_ALM_INVLIN` varchar(10) NOT NULL,
  `SERIE_INV_INVLIN` varchar(20) NOT NULL,
  `NUMERO_INV_INVLIN` varchar(20) NOT NULL,
  `LINEA_INVLIN` varchar(8) NOT NULL COMMENT 'Secuencial de la línea (00000001, 00000002...)',
  `CODIGO_ART_INVLIN` varchar(20) NOT NULL,
  `CODIGO_UNIDAD_INVLIN` varchar(50) NOT NULL COMMENT 'El SKU específico contado',
  `ID_AC_PIVOT_INVLIN` int(11) NOT NULL DEFAULT 0 COMMENT 'Conjunto de atributos pivotado en tallas horizontal (0 = sin pivote)',
  `LOTE_INVLIN` varchar(50) DEFAULT '',
  `FECHA_CADUCIDAD_INVLIN` date DEFAULT NULL,
  `DESCRIPCION_ARTICULO_INVLIN` varchar(200) DEFAULT NULL,
  `CANTIDAD_TEORICA_INVLIN` decimal(19,6) NOT NULL DEFAULT 0.000000 COMMENT 'Stock actual en sistema',
  `CANTIDAD_FISICA_INVLIN` decimal(19,6) NOT NULL DEFAULT 0.000000 COMMENT 'Stock contado',
  `CANTIDAD_DIFERENCIA_INVLIN` decimal(19,6) NOT NULL DEFAULT 0.000000 COMMENT 'Física - Teórica',
  `PRECIO_MEDIO_INVLIN` decimal(19,6) DEFAULT 0.000000 COMMENT 'PMP que tenía el sistema antes del inventario',
  `PRECIO_MEDIO_NUEVO_INVLIN` decimal(19,6) DEFAULT 0.000000 COMMENT 'PMP corregido por el usuario (apreciación/depreciación)',
  `TOTAL_COSTE_DIFERENCIA_INVLIN` decimal(19,6) DEFAULT 0.000000 COMMENT 'Fórmula sugerida: (CANTIDAD_FISICA * PRECIO_MEDIO_NUEVO) - (CANTIDAD_TEORICA * PRECIO_MEDIO_ACTUAL)',
  `FECHA_RECUENTO_INVLIN` datetime DEFAULT NULL COMMENT 'Instante exacto del escaneo',
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  `ESPRECIO_MEDIO_CORREGIDO_INVLIN` varchar(1) NOT NULL DEFAULT 'N' COMMENT 'S si el PMP nuevo fue indicado expresamente',
  PRIMARY KEY (`CODIGO_EMP_INVLIN`,`CODIGO_ALM_INVLIN`,`SERIE_INV_INVLIN`,`NUMERO_INV_INVLIN`,`LINEA_INVLIN`),
  KEY `IDX_INV_LIN_ARTICULO` (`CODIGO_ART_INVLIN`),
  KEY `IDX_INV_LIN_UNIDAD` (`CODIGO_UNIDAD_INVLIN`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_inventarios_recuentos`;
CREATE TABLE `fza_inventarios_recuentos` (
  `ID_INVREC` bigint(20) NOT NULL AUTO_INCREMENT,
  `UUID_INVREC` varchar(36) NOT NULL,
  `CODIGO_EMP_INVREC` varchar(10) NOT NULL,
  `CODIGO_ALM_INVREC` varchar(10) NOT NULL,
  `SERIE_INV_INVREC` varchar(20) NOT NULL,
  `NUMERO_INV_INVREC` varchar(20) NOT NULL,
  `CODIGO_ART_INVREC` varchar(20) DEFAULT NULL,
  `CODIGO_UNIDAD_INVREC` varchar(50) DEFAULT NULL,
  `CODIGO_BARRAS_INVREC` varchar(50) DEFAULT NULL,
  `CANTIDAD_INVREC` decimal(19,6) NOT NULL DEFAULT 1.000000,
  `LOTE_INVREC` varchar(50) DEFAULT '',
  `FECHA_CADUCIDAD_INVREC` date DEFAULT NULL,
  `INSTANTE_RECUENTO_INVREC` datetime NOT NULL,
  `INSTANTE_RECUENTO_UTC_INVREC` datetime DEFAULT NULL,
  `OPERARIO_INVREC` varchar(100) DEFAULT NULL,
  `DISPOSITIVO_INVREC` varchar(100) DEFAULT NULL,
  `ZONA_INVREC` varchar(100) DEFAULT NULL,
  `ESANULADO_INVREC` char(1) NOT NULL DEFAULT 'N',
  `INSTANTE_ALTA` datetime NOT NULL,
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `INSTANTE_MODIF` datetime DEFAULT NULL,
  `USUARIO_MODIF` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`ID_INVREC`),
  UNIQUE KEY `UQ_INVREC_UUID` (`UUID_INVREC`),
  KEY `IDX_INVREC_DOC` (`CODIGO_EMP_INVREC`,`CODIGO_ALM_INVREC`,`SERIE_INV_INVREC`,`NUMERO_INV_INVREC`),
  KEY `IDX_INVREC_UNIDAD` (`CODIGO_UNIDAD_INVREC`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_ivas`;
CREATE TABLE `fza_ivas` (
  `CODIGO_IVA` varchar(20) NOT NULL DEFAULT '0',
  `IVA_IVAGRP` varchar(10) NOT NULL,
  `DESCRIPCION_IVA_IVAGRP` varchar(100) NOT NULL,
  `PORCENTAJE_EXENTO_IVA` decimal(18,6) unsigned NOT NULL DEFAULT 0.000000,
  `PORCENTAJE_EXENTO_RE_IVA` decimal(18,6) unsigned NOT NULL DEFAULT 0.000000,
  `PORCENTAJE_NORMAL_IVA` decimal(18,6) unsigned NOT NULL DEFAULT 0.000000,
  `PORCENTAJE_NORMAL_RE_IVA` decimal(18,6) unsigned NOT NULL DEFAULT 0.000000,
  `PORCENTAJE_REDUCIDO_IVA` decimal(18,6) unsigned NOT NULL DEFAULT 0.000000,
  `PORCENTAJE_REDUCIDO_RE_IVA` decimal(18,6) unsigned NOT NULL DEFAULT 0.000000,
  `PORCENTAJE_SUPERREDUCIDO_IVA` decimal(18,6) unsigned NOT NULL DEFAULT 0.000000,
  `PORCENTAJE_SUPERREDUCIDO_RE_IVA` decimal(18,6) unsigned NOT NULL DEFAULT 0.000000,
  `FECHA_DESDE_IVA` date NOT NULL,
  `FECHA_HASTA_IVA` date DEFAULT NULL,
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  PRIMARY KEY (`CODIGO_IVA`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_ivas_grupos`;
CREATE TABLE `fza_ivas_grupos` (
  `IVA_IVAGRP` varchar(10) NOT NULL DEFAULT '0',
  `CODIGO_PAI_IVA_IVAGRP` varchar(3) NOT NULL DEFAULT '724',
  `NOMBRE_PAI_IVA_IVAGRP` varchar(100) NOT NULL DEFAULT 'España',
  `DESCRIPCION_IVA_IVAGRP` varchar(100) NOT NULL,
  `ESIRPF_IMP_INCL_IVA_IVAGRP` varchar(1) DEFAULT 'N',
  `ESIVAAGRICOLA_IVA_IVAGRP` varchar(1) DEFAULT 'N',
  `ESAPLICA_RE_IVA_IVAGRP` varchar(1) DEFAULT 'S' COMMENT 'Cuando el grupo de iva no aplica RE en sus documentos',
  `ESDEFAULT_IVA_IVAGRP` varchar(1) DEFAULT 'N',
  `PALABRA_REPORTS_IVA_IVAGRP` varchar(10) DEFAULT 'IVA',
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  PRIMARY KEY (`IVA_IVAGRP`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_ivas_tipos`;
CREATE TABLE `fza_ivas_tipos` (
  `CODIGO_ABREVIATURA_IVA_IVATIP` varchar(1) DEFAULT NULL,
  `NOMBRE_TIPO_IVA_IVATIP` varchar(20) DEFAULT NULL,
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_ivas_zonas`;
CREATE TABLE `fza_ivas_zonas` (
  `CODIGO_ZONA_IVA_IVAZON` int(11) NOT NULL,
  `DESCRIPCION_IVA_IVAGRP` varchar(100) DEFAULT NULL,
  `ESDEFAULT_IVA_IVAGRP` varchar(1) DEFAULT NULL,
  PRIMARY KEY (`CODIGO_ZONA_IVA_IVAZON`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_lotes_retiradas`;
CREATE TABLE `fza_lotes_retiradas` (
  `ID_LRET` varchar(36) NOT NULL,
  `LINEA_LRET` int(11) NOT NULL,
  `ESADICIONAL_LRET` varchar(1) NOT NULL DEFAULT 'N',
  `INSTANTE_LRET` datetime NOT NULL,
  `ESURGENTE_LRET` varchar(1) NOT NULL DEFAULT 'N',
  `CODIGO_EMP_LRET` varchar(20) NOT NULL,
  `EMPLEADO_LRET` varchar(50) NOT NULL,
  `MOTIVO_LRET` varchar(20) NOT NULL,
  `DESTINO_LRET` varchar(20) NOT NULL,
  `CODIGO_ALM_DESTINO_LRET` varchar(10) DEFAULT NULL,
  `CODIGO_ART_LRET` varchar(20) NOT NULL,
  `CODIGO_UNIDAD_LRET` varchar(50) NOT NULL,
  `DESCRIPCION_LRET` varchar(200) NOT NULL,
  `LOTE_LRET` varchar(50) NOT NULL,
  `FECHA_CADUCIDAD_LRET` date DEFAULT NULL,
  `CANTIDAD_LRET` decimal(19,6) NOT NULL,
  `CODIGO_ALM_LRET` varchar(10) NOT NULL,
  `UBICACION_LRET` varchar(255) NOT NULL,
  `NUMERO_MOV_LRET` varchar(20) DEFAULT NULL,
  `NUMERO_MOV_DESTINO_LRET` varchar(20) DEFAULT NULL,
  `INSTANTE_ALTA` datetime NOT NULL,
  `USUARIO_ALTA` varchar(50) NOT NULL,
  `INSTANTE_MODIF` datetime DEFAULT NULL,
  `USUARIO_MODIF` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`ID_LRET`,`LINEA_LRET`),
  UNIQUE KEY `UQ_LRET_MOV` (`NUMERO_MOV_LRET`),
  KEY `IDX_LRET_MOV_DESTINO` (`NUMERO_MOV_DESTINO_LRET`),
  KEY `IDX_LRET_SKU_LOTE` (`CODIGO_UNIDAD_LRET`,`LOTE_LRET`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_metadatos`;
CREATE TABLE `fza_metadatos` (
  `CODIGO_META_META` int(20) NOT NULL AUTO_INCREMENT,
  `NOMBRE_META_META` varchar(100) NOT NULL,
  `PARENT_META` varchar(20) NOT NULL,
  PRIMARY KEY (`CODIGO_META_META`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_movimientos_almacen`;
CREATE TABLE `fza_movimientos_almacen` (
  `NUMERO_MOV` varchar(20) NOT NULL,
  `TIPO_DOC_MOV` varchar(5) NOT NULL COMMENT 'VE, TR, AT, AL, IN, AC, AE',
  `SERIE_DOC_MOV` varchar(20) NOT NULL,
  `NUMERO_DOC_MOV` varchar(20) NOT NULL,
  `LINEA_MOV` varchar(10) NOT NULL COMMENT 'Linea del documento origen',
  `CODIGO_EMP_MOV` varchar(20) NOT NULL,
  `CODIGO_ALM_MOV` varchar(10) NOT NULL,
  `FECHA_MOV` datetime DEFAULT NULL,
  `CODIGO_ART_MOV` varchar(20) DEFAULT NULL COMMENT 'Código Padre (ej: 003)',
  `CODIGO_UNIDAD_MOV` varchar(50) NOT NULL COMMENT 'SKU (ej: 003BLANCO45)',
  `DESCRIPCION_ARTICULO_MOV` varchar(100) DEFAULT NULL,
  `TIPO_MOV` varchar(1) NOT NULL COMMENT 'E = Entrada, S = Salida',
  `CANTIDAD_MOV` decimal(19,6) DEFAULT 0.000000,
  `PRECIO_COSTE_UNITARIO_MOV` decimal(19,6) DEFAULT 0.000000,
  `TOTAL_COSTE_MOV` decimal(19,6) DEFAULT 0.000000 COMMENT 'Cantidad * Coste Unitario',
  `PRECIO_MEDIO_MOV` decimal(19,6) DEFAULT 0.000000 COMMENT 'PMP capturado en el momento de la transacción',
  `CODIGO_ALM_CONTRA_MOV` varchar(10) DEFAULT NULL COMMENT 'Para traspasos: a qué almacén va',
  `CODIGO_CLI_MOV` varchar(20) DEFAULT NULL COMMENT 'Para ventas o depósitos',
  `CODIGO_PRV_MOV` varchar(20) DEFAULT NULL COMMENT 'Para entradas de compra',
  `ESACTIVO_MOV` varchar(1) DEFAULT 'S',
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT current_timestamp(),
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  `TIPO_DOC_REF_MOV` varchar(5) DEFAULT NULL,
  `SERIE_DOC_REF_MOV` varchar(20) DEFAULT NULL,
  `NUMERO_DOC_REF_MOV` varchar(20) DEFAULT NULL,
  `LINEA_REF_MOV` varchar(4) DEFAULT NULL,
  `LOTE_MOV` varchar(50) DEFAULT '' COMMENT 'Número de lote impreso',
  `FECHA_CADUCIDAD_MOV` date DEFAULT NULL,
  `CODIGO_ALM_DOC_MOV` varchar(10) DEFAULT NULL COMMENT 'Almacén/Tienda donde se originó el ticket/operación',
  `NUMERO_OPERACION_DOC_MOV` varchar(20) DEFAULT NULL COMMENT 'Número de operación de caja que causó el movimiento',
  `CODIGO_CAJA_DOC_MOV` varchar(10) DEFAULT NULL COMMENT 'Código de caja donde se originó la operación',
  `CLAVE_FCVE_MOV` varchar(50) DEFAULT NULL,
  `VALOR_STOCK_MOV` decimal(19,6) DEFAULT NULL,
  PRIMARY KEY (`NUMERO_MOV`),
  UNIQUE KEY `UX_MOV_CLAVE_FCVE` (`CLAVE_FCVE_MOV`),
  KEY `IDX_FECHA_MOV` (`FECHA_MOV`),
  KEY `IDX_MOV_ALMACEN_FECHA` (`CODIGO_ALM_MOV`,`FECHA_MOV`),
  KEY `IDX_MOV_ALM_UNIDAD_ACTIVO_FECHA` (`CODIGO_ALM_MOV`,`CODIGO_UNIDAD_MOV`,`ESACTIVO_MOV`,`FECHA_MOV`,`INSTANTE_ALTA`,`NUMERO_MOV`),
  KEY `IDX_MOV_ART_ALM` (`CODIGO_ART_MOV`,`CODIGO_ALM_MOV`),
  KEY `IDX_MOV_CONTRA_UNIDAD_FECHA` (`CODIGO_ALM_CONTRA_MOV`,`CODIGO_UNIDAD_MOV`,`TIPO_DOC_MOV`,`TIPO_MOV`,`FECHA_MOV`),
  KEY `IDX_MOV_NUMERO_OPERACION_DOC` (`NUMERO_OPERACION_DOC_MOV`),
  KEY `IDX_MOV_OP_CAJA` (`CODIGO_EMP_MOV`,`CODIGO_ALM_DOC_MOV`,`CODIGO_CAJA_DOC_MOV`,`NUMERO_OPERACION_DOC_MOV`),
  KEY `IDX_MOV_SERIE_DOC_NUMERO_DOC_TIPO_DOC_LINEA` (`SERIE_DOC_MOV`,`NUMERO_DOC_MOV`,`TIPO_DOC_MOV`,`LINEA_MOV`),
  KEY `IDX_MOV_SKU_FECHA` (`CODIGO_UNIDAD_MOV`,`FECHA_MOV`),
  KEY `IDX_REF_MOV` (`TIPO_DOC_REF_MOV`,`SERIE_DOC_REF_MOV`,`NUMERO_DOC_REF_MOV`,`LINEA_REF_MOV`),
  KEY `IDX_SKU_ALM_MOV` (`CODIGO_UNIDAD_MOV`,`CODIGO_ALM_MOV`,`FECHA_MOV`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_movimientos_recalculos_pendientes`;
CREATE TABLE `fza_movimientos_recalculos_pendientes` (
  `NUMERO_MOV_MOVREC` varchar(20) NOT NULL,
  `CODIGO_EMP_MOVREC` varchar(20) NOT NULL DEFAULT '',
  `CODIGO_ALM_MOVREC` varchar(10) NOT NULL,
  `CODIGO_UNIDAD_MOVREC` varchar(50) NOT NULL,
  `INSTANTE_DESDE_MOVREC` datetime NOT NULL,
  `MOTIVO_MOVREC` varchar(255) NOT NULL,
  `ESTADO_MOVREC` varchar(20) NOT NULL DEFAULT 'PENDIENTE',
  `ESPROCESADO_MOVREC` varchar(1) NOT NULL DEFAULT 'N',
  `VERSION_MOVREC` int(11) NOT NULL DEFAULT 1,
  `CONTADOR_INTENTOS_MOVREC` int(11) NOT NULL DEFAULT 0,
  `INSTANTE_PROXIMO_INTENTO_MOVREC` datetime DEFAULT NULL,
  `TOKEN_RECLAMACION_MOVREC` char(36) DEFAULT NULL,
  `INSTANTE_RECLAMACION_MOVREC` datetime DEFAULT NULL,
  `INSTANTE_LIMITE_RECLAMACION_MOVREC` datetime DEFAULT NULL,
  `MENSAJE_ERROR_MOVREC` text DEFAULT NULL,
  `RESUMEN_CORRECCION_MOVREC` text DEFAULT NULL,
  `INSTANTE_PROCESADO_MOVREC` datetime DEFAULT NULL,
  `INSTANTE_ALTA` datetime NOT NULL,
  `USUARIO_ALTA` varchar(50) NOT NULL,
  `INSTANTE_MODIF` datetime DEFAULT NULL,
  `USUARIO_MODIF` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`NUMERO_MOV_MOVREC`),
  KEY `IDX_MOVREC_GRUPO` (`CODIGO_ALM_MOVREC`,`CODIGO_UNIDAD_MOVREC`,`ESPROCESADO_MOVREC`,`ESTADO_MOVREC`,`INSTANTE_DESDE_MOVREC`),
  KEY `IDX_MOVREC_RECLAMAR` (`ESPROCESADO_MOVREC`,`ESTADO_MOVREC`,`INSTANTE_PROXIMO_INTENTO_MOVREC`,`INSTANTE_ALTA`),
  KEY `IDX_MOVREC_TOKEN` (`TOKEN_RECLAMACION_MOVREC`,`ESTADO_MOVREC`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_paises`;
CREATE TABLE `fza_paises` (
  `CODIGO_PAI_PAI` char(3) NOT NULL,
  `COD_ALPHA3_PAI` varchar(3) DEFAULT NULL,
  `COD_ALPHA2_PAI` varchar(2) DEFAULT NULL,
  `NOMBRE_SPA_PAI` varchar(100) DEFAULT NULL,
  `NOMBRE_ENG_PAI` varchar(100) DEFAULT NULL,
  `ESMIEMBRO_UE_PAI` varchar(1) DEFAULT NULL COMMENT 'S SI ES MIEMBRO DE LA UE, N CUANDO NO LO ES',
  `ORDEN_PAI` int(11) DEFAULT NULL,
  PRIMARY KEY (`CODIGO_PAI_PAI`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_pedidos`;
CREATE TABLE `fza_pedidos` (
  `NUMERO_PED` varchar(12) NOT NULL,
  `SERIE_PED` varchar(12) NOT NULL,
  `FECHA_PED` date DEFAULT NULL,
  `ESCONSOLIDADO_PED` varchar(1) DEFAULT 'N' COMMENT 'S si el pedido ya no se puede modificar (todo entregado o cerrado)',
  `ESTADO_PED` varchar(20) DEFAULT 'ABIERTO' COMMENT 'ABIERTO, PARCIAL, ENTREGADO, CANCELADO, IMPORTADO',
  `FECHA_ENTREGA_PED` date DEFAULT NULL COMMENT 'Fecha prevista de entrega del pedido',
  `CODIGO_EMP_PED` varchar(8) DEFAULT NULL,
  `CODIGO_ALM_PED` varchar(10) DEFAULT NULL COMMENT 'Almacen de salida por defecto del pedido',
  `RAZON_SOCIAL_EMPRESA_PED` varchar(200) DEFAULT NULL,
  `NIF_EMPRESA_PED` varchar(50) DEFAULT NULL,
  `MOVIL_EMPRESA_PED` varchar(40) DEFAULT NULL,
  `EMAIL_EMPRESA_PED` varchar(200) DEFAULT NULL,
  `DIRECCION1_EMPRESA_PED` varchar(200) DEFAULT NULL,
  `DIRECCION2_EMPRESA_PED` varchar(200) DEFAULT NULL,
  `POBLACION_EMPRESA_PED` varchar(200) DEFAULT NULL,
  `PROVINCIA_EMPRESA_PED` varchar(200) DEFAULT NULL,
  `CODIGO_PAI_EMPRESA_PED` varchar(3) DEFAULT '724',
  `NOMBRE_PAI_EMPRESA_PED` varchar(150) DEFAULT 'España',
  `CODIGO_POSTAL_EMPRESA_PED` varchar(15) DEFAULT NULL,
  `ESRETENCIONES_EMPRESA_PED` varchar(1) DEFAULT 'N' COMMENT 'S o N si la empresa aplica retenciones como autónomos',
  `GRUPO_ZONA_IVA_EMPRESA_PED` varchar(10) DEFAULT NULL,
  `ESREGIMENESPECIALAGRICOLA_EMPRESA_PED` varchar(1) DEFAULT 'N',
  `CODIGO_CLI_PED` varchar(20) DEFAULT NULL,
  `NIF_CLIENTE_PED` varchar(50) DEFAULT NULL,
  `EMAIL_CLIENTE_PED` varchar(200) DEFAULT NULL,
  `REFERENCIAPS_PED` varchar(20) DEFAULT NULL,
  `IDPS_PED` varchar(20) DEFAULT NULL,
  `ORIGENPS_PED` varchar(255) DEFAULT NULL,
  `FECHAPS_PED` datetime DEFAULT NULL,
  `FORMAPAGOPS_PED` varchar(200) DEFAULT NULL,
  `TRANSPORTISTAPS_PED` varchar(200) DEFAULT NULL,
  `ESTADOPEDIDOPS_PED` varchar(300) DEFAULT NULL,
  `ESTADOMENSAJEPS_PED` varchar(300) DEFAULT NULL,
  `IDHILOPS_MENSAJES_PED` varchar(20) DEFAULT NULL,
  `NOMBRE_CLI_ENVIO_PED` varchar(200) DEFAULT NULL,
  `MOVIL_CLIENTE_ENVIO_PED` varchar(40) DEFAULT NULL,
  `DIRECCION1_CLIENTE_ENVIO_PED` varchar(200) DEFAULT NULL,
  `DIRECCION2_CLIENTE_ENVIO_PED` varchar(200) DEFAULT NULL,
  `POBLACION_CLIENTE_ENVIO_PED` varchar(200) DEFAULT NULL,
  `PROVINCIA_CLIENTE_ENVIO_PED` varchar(200) DEFAULT NULL,
  `CODIGO_POSTAL_CLIENTE_ENVIO_PED` varchar(15) DEFAULT NULL,
  `CODIGO_PAI_CLIENTE_ENVIO_PED` varchar(3) DEFAULT '724',
  `NOMBRE_PAI_CLIENTE_ENVIO_PED` varchar(150) DEFAULT 'España',
  `RAZON_SOCIAL_CLIENTE_FISCAL_PED` varchar(200) DEFAULT NULL,
  `MOVIL_CLIENTE_FISCAL_PED` varchar(40) DEFAULT NULL,
  `EMAIL_CLIENTE_FISCAL_PED` varchar(200) DEFAULT NULL,
  `DIRECCION1_CLIENTE_FISCAL_PED` varchar(200) DEFAULT NULL,
  `DIRECCION2_CLIENTE_FISCAL_PED` varchar(200) DEFAULT NULL,
  `POBLACION_CLIENTE_FISCAL_PED` varchar(200) DEFAULT NULL,
  `PROVINCIA_CLIENTE_FISCAL_PED` varchar(200) DEFAULT NULL,
  `CODIGO_POSTAL_CLIENTE_FISCAL_PED` varchar(15) DEFAULT NULL,
  `CODIGO_PAI_CLIENTE_FISCAL_PED` varchar(3) DEFAULT '724',
  `NOMBRE_PAI_CLIENTE_FISCAL_PED` varchar(150) DEFAULT 'España',
  `ESIVA_RECARGO_CLIENTE_PED` varchar(1) DEFAULT 'N',
  `ESIVA_EXENTO_CLIENTE_PED` varchar(1) DEFAULT 'N',
  `ESREGIMENESPECIALAGRICOLA_CLIENTE_PED` varchar(1) DEFAULT 'N',
  `ESRETENCIONES_CLIENTE_PED` varchar(1) DEFAULT 'S' COMMENT 'S o N Si el cliente aplica retenciones',
  `TARIFA_ARTICULO_CLIENTE_PED` varchar(10) DEFAULT NULL COMMENT 'Código de la tarifa que viene del cliente o configurada por el usuario',
  `ESIMP_INCL_TARIFA_CLIENTE_PED` varchar(1) DEFAULT 'S' COMMENT 'Si el precio de la tarifa del cliente es con impuestos incl o no',
  `ESINTRACOMUNITARIO_CLIENTE_PED` varchar(1) DEFAULT 'N' COMMENT 'Si la venta es hacia un país de la UE',
  `ESIRPF_IMP_INCL_ZONA_IVA_PED` varchar(1) DEFAULT 'N' COMMENT 'Si la base del cáculo del irpf se hace desde BI o BI con impuestos',
  `ESAPLICA_RE_ZONA_IVA_PED` varchar(1) DEFAULT 'S' COMMENT 'Si el tipo de IVA aplica Recargo de Equivalencia o no',
  `ESIVAAGRICOLA_ZONA_IVA_PED` varchar(1) DEFAULT 'N' COMMENT 'Si el tipo de IVA es compatible con REAGP',
  `PALABRA_REPORTS_ZONA_IVA_PED` varchar(10) DEFAULT 'IVA' COMMENT 'Palabra que sustituye a IVA desde la tabla de fza_ivas_grupos',
  `CODIGO_IVA_PED` varchar(20) DEFAULT NULL COMMENT 'Código de IVA de la tabla fza_ivas',
  `ESVENTA_ACTIVO_FIJO_PED` varchar(1) DEFAULT 'N' COMMENT 'Sólo REAGP cuando se vende activos fijos, exime irpf',
  `PORCENTAJE_IVAN_PED` decimal(19,6) DEFAULT NULL COMMENT 'Porcentaje IVA Normal',
  `TOTAL_IVAN_PED` decimal(18,6) DEFAULT NULL COMMENT 'Total IVA Normal',
  `PORCENTAJE_REN_PED` decimal(19,6) DEFAULT NULL COMMENT 'Porcentaje RE Normal',
  `TOTAL_REN_PED` decimal(19,6) DEFAULT NULL COMMENT 'Total RE Normal',
  `TOTAL_BASEI_IVAN_PED` decimal(18,6) DEFAULT NULL COMMENT 'Total Base Imponible IVA Normal',
  `PORCENTAJE_IVAR_PED` decimal(19,6) DEFAULT NULL COMMENT 'Porcentaje IVA Reducido',
  `TOTAL_IVAR_PED` decimal(18,6) DEFAULT NULL COMMENT 'TotaL IVA Reducido',
  `PORCENTAJE_RER_PED` decimal(19,6) DEFAULT NULL COMMENT 'Porcentaje RE Reducido',
  `TOTAL_RER_PED` decimal(19,6) DEFAULT NULL COMMENT 'Total RE Reducido',
  `TOTAL_BASEI_IVAR_PED` decimal(18,6) DEFAULT NULL COMMENT 'Total Base Imponible IVA Reducido',
  `PORCENTAJE_IVAS_PED` decimal(19,6) DEFAULT NULL COMMENT 'Porcentaje IVA SuperReducido',
  `TOTAL_IVAS_PED` decimal(18,6) DEFAULT NULL COMMENT 'Total IVA SuperReducido',
  `PORCENTAJE_RES_PED` decimal(19,6) DEFAULT NULL COMMENT 'Porcentaje IVA SuperReducido',
  `TOTAL_RES_PED` decimal(19,6) DEFAULT NULL COMMENT 'Total RE SuperReducido',
  `TOTAL_BASEI_IVAS_PED` decimal(18,6) DEFAULT NULL COMMENT 'Total sin IVA SuperReducido',
  `PORCENTAJE_IVAE_PED` decimal(19,6) DEFAULT NULL COMMENT 'Porcentaje IVA Exento',
  `TOTAL_IVAE_PED` decimal(18,6) DEFAULT NULL COMMENT 'Total IVA Exento',
  `PORCENTAJE_REE_PED` decimal(19,6) DEFAULT NULL COMMENT 'Porcentaje IVA1 Exento',
  `TOTAL_REE_PED` decimal(19,6) DEFAULT NULL COMMENT 'Total RE Exento',
  `TOTAL_BASEI_IVAE_PED` decimal(18,6) DEFAULT NULL COMMENT 'Total sin IVA Exento',
  `TOTAL_BASES_PED` decimal(18,6) DEFAULT NULL COMMENT 'Total Todas las bases imponibles',
  `TOTAL_IMPUESTOS_PED` decimal(18,6) DEFAULT NULL COMMENT 'Total de todos los impuestos iva + re',
  `FORMA_PAGO_PED` varchar(200) DEFAULT NULL COMMENT 'Codigo Forma de Pago',
  `CODIGO_VENDEDOR_PED` varchar(20) DEFAULT NULL COMMENT 'Vendedor del pedido (fza_empleados)',
  `PORCENTAJE_RETENCION_PED` decimal(19,6) DEFAULT NULL COMMENT 'Porcentaje Retenciones',
  `TOTAL_RETENCION_PED` decimal(18,6) DEFAULT NULL COMMENT 'Total Retenciones PEDIDO',
  `TOTAL_LIQUIDO_PED` decimal(18,6) DEFAULT NULL COMMENT 'Total PEDIDO a pagar',
  `TOTAL_PAGADOREALPS_PED` decimal(18,6) DEFAULT NULL COMMENT 'Total pagado cliente',
  `NUMERO_PED_ABONO_PED` varchar(8) DEFAULT NULL COMMENT 'Nro PEDIDO Abono',
  `SERIE_PED_ABONO_PED` varchar(8) DEFAULT NULL COMMENT 'Serie PEDIDO Abono',
  `TEXTO_LEGAL_CLIENTE_PED` varchar(1000) DEFAULT '',
  `TEXTO_LEGAL_EMPRESA_PED` varchar(1000) DEFAULT '',
  `DOCUMENTO_PED` blob DEFAULT NULL COMMENT 'Copia en PDF del documento final',
  `COMENTARIOS_PED` varchar(1000) DEFAULT '',
  `OBSERVACIONES_PED` varchar(2000) DEFAULT '',
  `CONTADOR_LINEAS_PED` varchar(8) DEFAULT NULL COMMENT 'Contador de lineas para lineas de PEDIDO',
  `ESCREARARTICULOS_PED` varchar(1) DEFAULT NULL COMMENT 'S o N si se crean articulos desde el detalle',
  `ESDESCRIPCIONES_AMP_PED` varchar(1) DEFAULT 'S' COMMENT 'S o N si la PEDIDO contiene una descripción larga',
  `ESFECHADEENTREGA_PED` varchar(1) DEFAULT NULL COMMENT 'S o N si las descripciones tienen fecha de entrega',
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  `PORCENTAJE_DTO_COMERCIAL_PED` decimal(19,6) DEFAULT 0.000000,
  `TOTAL_DTO_COMERCIAL_PED` decimal(19,6) DEFAULT 0.000000,
  `PORCENTAJE_DTO_FINANCIERO_PED` decimal(19,6) DEFAULT 0.000000,
  `TOTAL_DTO_FINANCIERO_PED` decimal(19,6) DEFAULT 0.000000,
  PRIMARY KEY (`NUMERO_PED`,`SERIE_PED`),
  UNIQUE KEY `UQ_PED_ORIGENPS_IDPS` (`ORIGENPS_PED`,`IDPS_PED`),
  KEY `IDX_PED_ALMACEN` (`CODIGO_ALM_PED`),
  KEY `IDX_PED_CLIENTE_FECHA` (`CODIGO_CLI_PED`,`FECHA_PED`),
  KEY `IDX_PED_EMPRESA` (`CODIGO_EMP_PED`),
  KEY `IDX_PED_EMP_INSTANTE` (`CODIGO_EMP_PED`,`INSTANTE_ALTA`),
  KEY `IDX_PED_ESTADO` (`ESTADO_PED`),
  KEY `IDX_PED_IDPS` (`IDPS_PED`),
  KEY `IDX_PED_VENDEDOR` (`CODIGO_VENDEDOR_PED`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_pedidos_celdas`;
CREATE TABLE `fza_pedidos_celdas` (
  `SERIE_PED_PEDCEL` varchar(12) NOT NULL,
  `NUMERO_PED_PEDCEL` varchar(12) NOT NULL,
  `LINEA_PEDCEL` int(11) NOT NULL,
  `ID_FILA_PEDCEL` int(11) NOT NULL,
  `ID_AV_PIVOT_PEDCEL` int(11) NOT NULL COMMENT 'FK logica fza_atributos_valores del eje pivot (TALLA)',
  `CODIGO_ALM_PEDCEL` varchar(10) NOT NULL DEFAULT '',
  `CANTIDAD_PEDCEL` decimal(19,6) NOT NULL,
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL DEFAULT '',
  `INSTANTE_MODIF` datetime DEFAULT NULL,
  `USUARIO_MODIF` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`SERIE_PED_PEDCEL`,`NUMERO_PED_PEDCEL`,`LINEA_PEDCEL`,`ID_FILA_PEDCEL`,`ID_AV_PIVOT_PEDCEL`,`CODIGO_ALM_PEDCEL`),
  KEY `IDX_PEDCEL_AV_PIVOT` (`ID_AV_PIVOT_PEDCEL`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_pedidos_compra`;
CREATE TABLE `fza_pedidos_compra` (
  `NUMERO_PEDC` varchar(20) NOT NULL,
  `SERIE_PEDC` varchar(20) NOT NULL,
  `FECHA_PEDC` date DEFAULT NULL,
  `FECHA_PREVISTA_PEDC` date DEFAULT NULL COMMENT 'Fecha estimada de recepcion',
  `FECHA_TOPE_RECEPCION_PEDC` date DEFAULT NULL COMMENT 'Fecha limite prevista para recibir la mercancia',
  `ESTADO_PEDC` varchar(20) DEFAULT 'ABIERTO' COMMENT 'ABIERTO, PARCIAL, RECIBIDO, CANCELADO',
  `CODIGO_EMP_PEDC` varchar(8) DEFAULT NULL,
  `RAZON_SOCIAL_EMPRESA_PEDC` varchar(200) DEFAULT NULL,
  `NIF_EMPRESA_PEDC` varchar(50) DEFAULT NULL,
  `MOVIL_EMPRESA_PEDC` varchar(40) DEFAULT NULL,
  `EMAIL_EMPRESA_PEDC` varchar(200) DEFAULT NULL,
  `DIRECCION1_EMPRESA_PEDC` varchar(200) DEFAULT NULL,
  `DIRECCION2_EMPRESA_PEDC` varchar(200) DEFAULT NULL,
  `POBLACION_EMPRESA_PEDC` varchar(200) DEFAULT NULL,
  `PROVINCIA_EMPRESA_PEDC` varchar(200) DEFAULT NULL,
  `CODIGO_PAI_EMPRESA_PEDC` varchar(3) DEFAULT '724',
  `NOMBRE_PAI_EMPRESA_PEDC` varchar(150) DEFAULT 'Espana',
  `CODIGO_POSTAL_EMPRESA_PEDC` varchar(15) DEFAULT NULL,
  `CODIGO_PRV_PEDC` varchar(20) DEFAULT NULL COMMENT 'FK logica a fza_proveedores',
  `RAZON_SOCIAL_PRV_PEDC` varchar(200) DEFAULT NULL,
  `NIF_PRV_PEDC` varchar(50) DEFAULT NULL,
  `MOVIL_PRV_PEDC` varchar(40) DEFAULT NULL,
  `EMAIL_PRV_PEDC` varchar(200) DEFAULT NULL,
  `DIRECCION1_PRV_PEDC` varchar(200) DEFAULT NULL,
  `DIRECCION2_PRV_PEDC` varchar(200) DEFAULT NULL,
  `POBLACION_PRV_PEDC` varchar(200) DEFAULT NULL,
  `PROVINCIA_PRV_PEDC` varchar(200) DEFAULT NULL,
  `CODIGO_PAI_PRV_PEDC` varchar(3) DEFAULT '724',
  `NOMBRE_PAI_PRV_PEDC` varchar(150) DEFAULT 'Espana',
  `CODIGO_POSTAL_PRV_PEDC` varchar(15) DEFAULT NULL,
  `REF_PROVEEDOR_PEDC` varchar(50) DEFAULT NULL COMMENT 'Numero de pedido segun el proveedor',
  `CODIGO_ALM_PEDC` varchar(10) DEFAULT NULL COMMENT 'Almacen destino por defecto (cada linea puede tener el suyo)',
  `TRANSPORTISTA_PEDC` varchar(200) DEFAULT NULL,
  `CODIGO_IVA_PEDC` varchar(20) DEFAULT NULL,
  `ESIVA_RECARGO_COMPRAS_PEDC` varchar(1) DEFAULT 'N',
  `ESIVA_EXENTO_INTRACOMUNITARIO_PEDC` varchar(1) NOT NULL DEFAULT 'N' COMMENT 'S = IVA exento por proveedor intracomunitario',
  `PORCENTAJE_IVAN_PEDC` decimal(19,6) DEFAULT NULL,
  `TOTAL_BASEI_IVAN_PEDC` decimal(18,6) DEFAULT NULL,
  `TOTAL_IVAN_PEDC` decimal(18,6) DEFAULT NULL,
  `PORCENTAJE_REN_PEDC` decimal(19,6) DEFAULT NULL,
  `TOTAL_REN_PEDC` decimal(18,6) DEFAULT NULL,
  `PORCENTAJE_IVAR_PEDC` decimal(19,6) DEFAULT NULL,
  `TOTAL_BASEI_IVAR_PEDC` decimal(18,6) DEFAULT NULL,
  `TOTAL_IVAR_PEDC` decimal(18,6) DEFAULT NULL,
  `PORCENTAJE_RER_PEDC` decimal(19,6) DEFAULT NULL,
  `TOTAL_RER_PEDC` decimal(18,6) DEFAULT NULL,
  `PORCENTAJE_IVAS_PEDC` decimal(19,6) DEFAULT NULL,
  `TOTAL_BASEI_IVAS_PEDC` decimal(18,6) DEFAULT NULL,
  `TOTAL_IVAS_PEDC` decimal(18,6) DEFAULT NULL,
  `PORCENTAJE_RES_PEDC` decimal(19,6) DEFAULT NULL,
  `TOTAL_RES_PEDC` decimal(18,6) DEFAULT NULL,
  `PORCENTAJE_IVAE_PEDC` decimal(19,6) DEFAULT NULL,
  `TOTAL_BASEI_IVAE_PEDC` decimal(18,6) DEFAULT NULL,
  `TOTAL_IVAE_PEDC` decimal(18,6) DEFAULT NULL,
  `PORCENTAJE_REE_PEDC` decimal(19,6) DEFAULT NULL,
  `TOTAL_REE_PEDC` decimal(18,6) DEFAULT NULL,
  `TOTAL_BASES_PEDC` decimal(18,6) DEFAULT NULL,
  `TOTAL_IMPUESTOS_PEDC` decimal(18,6) DEFAULT NULL,
  `PORCENTAJE_RETENCION_PEDC` decimal(19,6) DEFAULT NULL,
  `TOTAL_RETENCION_PEDC` decimal(18,6) DEFAULT NULL,
  `TOTAL_BRUTO_PEDC` decimal(18,6) DEFAULT 0.000000,
  `PORCENTAJE_DTO_COMERCIAL_PEDC` decimal(19,6) DEFAULT 0.000000,
  `TOTAL_DTO_COMERCIAL_PEDC` decimal(18,6) DEFAULT 0.000000,
  `PORCENTAJE_DTO_FINANCIERO_PEDC` decimal(19,6) DEFAULT 0.000000,
  `TOTAL_DTO_FINANCIERO_PEDC` decimal(18,6) DEFAULT 0.000000,
  `TOTAL_LIQUIDO_PEDC` decimal(18,6) DEFAULT NULL,
  `FORMA_PAGO_PEDC` varchar(200) DEFAULT NULL,
  `CONTADOR_LINEAS_PEDC` varchar(8) DEFAULT NULL,
  `COMENTARIOS_PEDC` varchar(1000) DEFAULT '',
  `OBSERVACIONES_PEDC` varchar(2000) DEFAULT '',
  `ESPIVOTE_HORIZONTAL_PEDC` varchar(1) DEFAULT 'N' COMMENT 'S/N — recordar vista pivote de tallas al reabrir',
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  `ID_PV_TEMPORADA_PEDC` int(11) DEFAULT NULL COMMENT 'FK logica fza_propiedades_valores.ID_PV_ARTPROP con ID_PROP_PV=TEMPORADA. Se hereda de la sesion al materializar y se pre-rellena en el modal Crear Albaran al generar albaran desde pedido.',
  PRIMARY KEY (`NUMERO_PEDC`,`SERIE_PEDC`),
  KEY `IDX_PEDC_EMPRESA` (`CODIGO_EMP_PEDC`),
  KEY `IDX_PEDC_EMP_INSTANTE` (`CODIGO_EMP_PEDC`,`INSTANTE_ALTA`),
  KEY `IDX_PEDC_ESTADO` (`ESTADO_PEDC`),
  KEY `IDX_PEDC_FECHA_TOPE_RECEPCION` (`FECHA_TOPE_RECEPCION_PEDC`),
  KEY `IDX_PEDC_PROVEEDOR_FECHA` (`CODIGO_PRV_PEDC`,`FECHA_PEDC`),
  KEY `IDX_PEDC_TEMPORADA` (`ID_PV_TEMPORADA_PEDC`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_pedidos_compra_celdas`;
CREATE TABLE `fza_pedidos_compra_celdas` (
  `SERIE_PEDC_PEDCCEL` varchar(20) NOT NULL,
  `NUMERO_PEDC_PEDCCEL` varchar(20) NOT NULL,
