  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  PRIMARY KEY (`SERIE_PEDC_PEDCCEL`,`NUMERO_PEDC_PEDCCEL`,`LINEA_PEDC_PEDCCEL`,`ID_FILA_PEDC_PEDCCEL`,`ID_AV_PIVOT_PEDCCEL`),
  KEY `IDX_PEDCCEL_AV_PIVOT` (`ID_AV_PIVOT_PEDCCEL`),
  KEY `IDX_PEDCCEL_LINEA` (`SERIE_PEDC_PEDCCEL`,`NUMERO_PEDC_PEDCCEL`,`LINEA_PEDC_PEDCCEL`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_pedidos_compra_lineas`;
CREATE TABLE `fza_pedidos_compra_lineas` (
  `NUMERO_PEDC_PEDCLIN` varchar(20) NOT NULL,
  `SERIE_PEDC_PEDCLIN` varchar(20) NOT NULL,
