  `CODIGO_ART_PEDCLIN` varchar(20) DEFAULT NULL,
  `CODIGO_UNIDAD_PEDCLIN` varchar(50) DEFAULT NULL COMMENT 'SKU del articulo',
  `ID_AC_PIVOT_PEDCLIN` int(11) DEFAULT NULL COMMENT 'Conjunto de atributos pivot (fza_atributos_conjuntos)',
  `CODIGO_FAM_PEDCLIN` varchar(20) DEFAULT NULL,
  `NOMBRE_FAM_PEDCLIN` varchar(200) DEFAULT NULL,
  `COLOR_TEXTO_PEDCLIN` varchar(100) DEFAULT NULL COMMENT 'Texto libre del color del articulo del proveedor',
  `DESCRIPCION_ARTICULO_PEDCLIN` varchar(100) DEFAULT NULL,
  `TIPO_CANTIDAD_ARTICULO_PEDCLIN` varchar(20) DEFAULT 'Uds',
  `CANTIDAD_PEDCLIN` decimal(19,6) DEFAULT 1.000000 COMMENT 'Cantidad PEDIDA por el cliente',
  `CANTIDAD_RECIBIDA_PEDCLIN` decimal(19,6) DEFAULT 0.000000 COMMENT 'Suma de cantidades ya albaraneadas (acumulado)',
  `TOTAL_UNIDADES_PEDCLIN` decimal(19,6) DEFAULT 0.000000 COMMENT 'SUM(CANTIDAD) celdas pedidas cuando hay pivote',
  `TIPO_IVA_ARTICULO_PEDCLIN` varchar(2) DEFAULT 'N',
  `PORCENTAJE_IVA_PEDCLIN` decimal(19,6) DEFAULT 0.000000,
  `PRECIO_COMPRA_SIVA_ARTICULO_PEDCLIN` decimal(19,6) DEFAULT 0.000000,
  `PRECIO_COMPRA_CIVA_ARTICULO_PEDCLIN` decimal(19,6) DEFAULT 0.000000,
  `TOTAL_PEDCLIN` decimal(19,6) DEFAULT 0.000000,
  `CODIGO_ALMACEN_PEDCLIN` varchar(10) DEFAULT NULL COMMENT 'Almacen destino de la linea — un pedido puede agrupar varios',
  `REF_PRV_PEDCLIN` varchar(50) DEFAULT NULL,
  `DESCRIPCION_VARIACION_PEDCLIN` varchar(200) DEFAULT NULL,
  `FECHA_ENTREGA_PEDCLIN` date DEFAULT NULL,
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  `ATTR1_VALOR_PEDCLIN` varchar(100) NOT NULL DEFAULT '',
  `ATTR1_NOMBRE_PEDCLIN` varchar(100) NOT NULL DEFAULT '',
  `ATTR2_VALOR_PEDCLIN` varchar(100) NOT NULL DEFAULT '',
  `ATTR2_NOMBRE_PEDCLIN` varchar(100) NOT NULL DEFAULT '',
  `ATTR3_VALOR_PEDCLIN` varchar(100) NOT NULL DEFAULT '',
