  `CODIGO_PAI_EMPRESA_PROCAJ` varchar(3) DEFAULT NULL,
  `NOMBRE_PAI_EMPRESA_PROCAJ` varchar(150) DEFAULT NULL,
  `CODIGO_CLI_PROCAJ` varchar(20) NOT NULL DEFAULT '0',
  `RAZON_SOCIAL_CLIENTE_PROCAJ` varchar(200) NOT NULL DEFAULT 'VENTA CONTADO',
  `TOTAL_BASE_PROCAJ` decimal(19,6) NOT NULL DEFAULT 0.000000,
  `TOTAL_IMPUESTOS_PROCAJ` decimal(19,6) NOT NULL DEFAULT 0.000000,
  `TOTAL_PROCAJ` decimal(19,6) NOT NULL DEFAULT 0.000000,
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT current_timestamp(),
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  PRIMARY KEY (`ID_PROCAJ`),
  UNIQUE KEY `UQ_PROCAJ_DOCUMENTO` (`CODIGO_EMP_PROCAJ`,`SERIE_PROCAJ`,`NUMERO_PROCAJ`),
  KEY `IDX_PROCAJ_EMP_FECHA` (`CODIGO_EMP_PROCAJ`,`FECHA_PROCAJ`),
  KEY `IDX_PROCAJ_ESTADO` (`ESTADO_PROCAJ`),
  KEY `IDX_PROCAJ_PERIODO` (`FECHA_DESDE_PROCAJ`,`FECHA_HASTA_PROCAJ`),
  KEY `IDX_PROCAJ_PERIODO_REG` (`ID_FACPER_PROCAJ`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_proformas_caja_lineas`;
CREATE TABLE `fza_proformas_caja_lineas` (
  `ID_PROCAJ_PROCLIN` bigint(20) NOT NULL,
  `LINEA_PROCLIN` varchar(8) NOT NULL,
  `ID_OPCAJA_PROCLIN` bigint(20) NOT NULL,
  `TIPO_VINCULO_PROCLIN` varchar(10) NOT NULL DEFAULT 'ORIGEN',
  `ID_PROCAJ_ORIGEN_PROCLIN` bigint(20) DEFAULT NULL,
  `LINEA_PROCAJ_ORIGEN_PROCLIN` varchar(8) DEFAULT NULL,
  `SERIE_FAC_ORIGEN_PROCLIN` varchar(20) NOT NULL,
  `NUMERO_FAC_ORIGEN_PROCLIN` varchar(20) NOT NULL,
  `LINEA_FAC_ORIGEN_PROCLIN` varchar(4) NOT NULL,
  `NUMERO_OPERACION_PROCLIN` varchar(20) NOT NULL,
  `FECHA_OPERACION_PROCLIN` date NOT NULL,
  `CODIGO_ART_PROCLIN` varchar(20) DEFAULT NULL,
  `CODIGO_UNIDAD_PROCLIN` varchar(50) DEFAULT NULL,
  `DESCRIPCION_ARTICULO_PROCLIN` varchar(200) DEFAULT NULL,
  `TIPO_IVA_PROCLIN` varchar(2) DEFAULT NULL,
  `CANTIDAD_PROCLIN` decimal(19,6) NOT NULL DEFAULT 0.000000,
  `PRECIO_SIVA_PROCLIN` decimal(19,6) NOT NULL DEFAULT 0.000000,
  `PORCENTAJE_IVA_PROCLIN` decimal(19,6) NOT NULL DEFAULT 0.000000,
  `TOTAL_SIVA_PROCLIN` decimal(19,6) NOT NULL DEFAULT 0.000000,
  `TOTAL_PROCLIN` decimal(19,6) NOT NULL DEFAULT 0.000000,
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT current_timestamp(),
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  PRIMARY KEY (`ID_PROCAJ_PROCLIN`,`LINEA_PROCLIN`),
  UNIQUE KEY `UQ_PROCLIN_ORIGEN` (`ID_OPCAJA_PROCLIN`,`TIPO_VINCULO_PROCLIN`,`SERIE_FAC_ORIGEN_PROCLIN`,`NUMERO_FAC_ORIGEN_PROCLIN`,`LINEA_FAC_ORIGEN_PROCLIN`),
  KEY `IDX_PROCLIN_OPERACION` (`ID_OPCAJA_PROCLIN`),
  KEY `IDX_PROCLIN_PROFORMA_ORIGEN` (`ID_PROCAJ_ORIGEN_PROCLIN`,`LINEA_PROCAJ_ORIGEN_PROCLIN`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_proformas_caja_vales`;
CREATE TABLE `fza_proformas_caja_vales` (
  `CODIGO_VL_PROCVL` varchar(50) NOT NULL,
  `ID_PROCAJ_PROCVL` bigint(20) NOT NULL,
  `CODIGO_EMP_EMI_PROCVL` varchar(20) NOT NULL,
  `CODIGO_EMP_RED_PROCVL` varchar(20) NOT NULL,
  `FECHA_REDENCION_PROCVL` date NOT NULL,
  `NUMERO_OPERACION_RED_PROCVL` varchar(20) DEFAULT NULL,
  `IMPORTE_COMPENSACION_PROCVL` decimal(19,6) NOT NULL,
  `SERIE_FAC_PROCVL` varchar(20) DEFAULT NULL,
  `NUMERO_FAC_PROCVL` varchar(20) DEFAULT NULL,
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT current_timestamp(),
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  PRIMARY KEY (`CODIGO_VL_PROCVL`),
  KEY `IDX_PROCVL_EMPRESAS_FECHA` (`CODIGO_EMP_EMI_PROCVL`,`CODIGO_EMP_RED_PROCVL`,`FECHA_REDENCION_PROCVL`),
  KEY `IDX_PROCVL_FACTURA` (`SERIE_FAC_PROCVL`,`NUMERO_FAC_PROCVL`),
  KEY `IDX_PROCVL_PROFORMA` (`ID_PROCAJ_PROCVL`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_propiedades`;
CREATE TABLE `fza_propiedades` (
  `CODIGO_PROP_ARTPROP` varchar(20) NOT NULL COMMENT 'Identificador único (ej: MATERIAL, MARCA, EDAD_MAX)',
  `NOMBRE_PROP_PROP` varchar(100) NOT NULL COMMENT 'Nombre público para la web o app (ej: Material, Marca, Edad Recomendada)',
  `TIPO_VALOR_PROP` varchar(20) DEFAULT 'LISTA' COMMENT 'Cómo se rellena: LISTA, TEXTO_LIBRE, NUMERO, BOOLEANO',
  `NIVEL_PROP` varchar(10) NOT NULL DEFAULT 'ARTICULO' COMMENT 'Nivel maximo de desglose: ARTICULO < COLOR < SKU',
  `ESACTIVO_PROP` varchar(1) DEFAULT 'S' COMMENT 'S para activo, N para inactivo',
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT current_timestamp(),
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  PRIMARY KEY (`CODIGO_PROP_ARTPROP`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_propiedades_valores`;
CREATE TABLE `fza_propiedades_valores` (
  `ID_PV_ARTPROP` int(11) NOT NULL AUTO_INCREMENT COMMENT 'Identificador único del valor de la propiedad',
  `ID_PROP_PV` varchar(20) NOT NULL COMMENT 'FK hacia fza_propiedades (ej: MATERIAL, EDAD_MAX)',
  `PV` varchar(100) NOT NULL COMMENT 'El valor real (ej: Acero Inoxidable, +3 años, Lego)',
  `DESCRIPCION_PV` varchar(255) DEFAULT NULL COMMENT 'Descripción comercial ampliada si es necesaria',
  `ESACTIVO_PV` varchar(1) DEFAULT 'S' COMMENT 'S para activo, N para inactivo',
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  PRIMARY KEY (`ID_PV_ARTPROP`),
  KEY `IDX_PROPIEDAD_PV` (`ID_PROP_PV`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_proveedores`;
CREATE TABLE `fza_proveedores` (
  `CODIGO_PRV_PRV` varchar(20) NOT NULL,
  `ESACTIVO_PRV` varchar(1) DEFAULT 'S',
  `ORDEN_PRV` int(11) DEFAULT NULL,
  `RAZON_SOCIAL_PRV` varchar(200) DEFAULT NULL,
  `NOMBRE_PRV` varchar(200) DEFAULT NULL,
  `NIF_PRV` varchar(50) DEFAULT NULL,
  `MOVIL_PRV` varchar(40) DEFAULT NULL,
  `EMAIL_PRV` varchar(200) DEFAULT NULL,
  `DIRECCION1_PRV` varchar(200) DEFAULT NULL,
  `DIRECCION2_PRV` varchar(200) DEFAULT NULL,
  `POBLACION_PRV` varchar(200) DEFAULT NULL,
  `PROVINCIA_PRV` varchar(200) DEFAULT NULL,
  `CODIGO_POSTAL_PRV` varchar(15) DEFAULT NULL,
  `PAIS_PRV` varchar(150) DEFAULT NULL,
  `CODIGO_PAI_PRV` varchar(3) DEFAULT NULL COMMENT 'FK logica fza_paises.COD_ALPHA2_PAI (combo pais, ver vi_paises)',
  `OBSERVACIONES_PRV` text DEFAULT NULL,
  `REFERENCIA_PRV` varchar(100) DEFAULT NULL,
  `CONTACTO_PRV` varchar(100) DEFAULT NULL,
  `TELEFONO_CONTACTO_PRV` varchar(100) DEFAULT NULL,
  `TELEFONO_PRV` varchar(40) DEFAULT NULL,
  `IBAN_PRV` varchar(100) DEFAULT NULL,
  `CODIGO_FP_PRV` varchar(20) DEFAULT NULL COMMENT 'Forma de pago por defecto — FK a fza_formas_pago',
  `CODIGO_EMPBAN_PRV` varchar(8) DEFAULT NULL COMMENT 'Cuenta de la empresa (cargo) por defecto — FK a fza_empresas_bancos',
  `PORCENTAJE_MARGEN_PRV` decimal(7,4) DEFAULT NULL COMMENT 'Margen comercial defecto: se copia a PORCENTAJE_MARGEN_SES',
  `ESVARIOS_TIPOS_IVA_PRV` varchar(1) NOT NULL DEFAULT 'N',
  `ESIVA_EXENTO_INTRACOMUNITARIO_PRV` varchar(1) NOT NULL DEFAULT 'N' COMMENT 'S = IVA exento por proveedor intracomunitario',
  `ID_AC_TALLAS_PRV` int(11) DEFAULT NULL COMMENT 'FK logica fza_atributos_conjuntos (ID_VA_AC=TAL): sistema de tallas defecto para sesiones',
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  `ESDESCRIPCION_BLANCO_PRV` varchar(1) NOT NULL DEFAULT 'N',
  `ESFACTURACION_DIRECTA_PRV` varchar(1) NOT NULL DEFAULT 'N',
  `MODO_LIQUIDACION_SERVICIOS_PRV` varchar(10) DEFAULT NULL COMMENT 'Reparaciones: PERIODICA o LINEA (NULL = PERIODICA)',
  PRIMARY KEY (`CODIGO_PRV_PRV`),
  KEY `IDX_PROVEEDORES_LISTADO` (`CODIGO_PRV_PRV`,`RAZON_SOCIAL_PRV`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_proveedores_familias`;
CREATE TABLE `fza_proveedores_familias` (
  `CODIGO_PRV_PF` varchar(20) NOT NULL,
  `CODIGO_FAM_PF` varchar(20) NOT NULL,
  `TIPO_VAR_PF` varchar(20) DEFAULT NULL,
  `OBSERVACIONES_PF` varchar(200) DEFAULT NULL,
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  PRIMARY KEY (`CODIGO_PRV_PF`,`CODIGO_FAM_PF`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_proveedores_familias_conjuntos`;
CREATE TABLE `fza_proveedores_familias_conjuntos` (
  `CODIGO_PRV_PFC` varchar(20) NOT NULL,
  `CODIGO_FAM_PFC` varchar(20) NOT NULL,
  `ID_AC_PFC` int(11) NOT NULL,
  `ESGENERACION_AUTO_ACA` char(1) DEFAULT 'S',
  `ORDEN_PFC` int(11) DEFAULT 0,
  PRIMARY KEY (`CODIGO_PRV_PFC`,`CODIGO_FAM_PFC`,`ID_AC_PFC`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_proveedores_kits`;
CREATE TABLE `fza_proveedores_kits` (
  `CODIGO_PRV_PRVKIT` varchar(20) NOT NULL COMMENT 'FK logica a fza_proveedores',
  `CODIGO_PRVKIT` varchar(20) NOT NULL COMMENT 'CURVA-STD, MUESTRA, etc.',
  `NOMBRE_PRVKIT` varchar(100) NOT NULL,
  `DESCRIPCION_PRVKIT` varchar(255) DEFAULT NULL,
  `ID_AC_TALLAS_PRVKIT` int(11) DEFAULT NULL COMMENT 'FK logica fza_atributos_conjuntos: sistema de tallas para el que se definio el kit (informativo; el casado real es por texto de talla)',
  `ORDEN_PRVKIT` int(11) NOT NULL DEFAULT 0,
  `INSTANTE_ALTA` datetime NOT NULL,
  `USUARIO_ALTA` varchar(50) NOT NULL,
  `INSTANTE_MODIF` datetime DEFAULT NULL,
  `USUARIO_MODIF` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`CODIGO_PRV_PRVKIT`,`CODIGO_PRVKIT`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_proveedores_kits_det`;
CREATE TABLE `fza_proveedores_kits_det` (
  `CODIGO_PRV_PRVKITD` varchar(20) NOT NULL,
  `CODIGO_PRVKIT_PRVKITD` varchar(20) NOT NULL,
  `VALOR_DESTINO_PRVKITD` varchar(50) NOT NULL COMMENT 'Valor de la talla destino: "38", "M", etc. Se casa contra fza_atributos_valores.AV del sistema de la linea',
  `CANTIDAD_PRVKITD` decimal(19,6) NOT NULL DEFAULT 0.000000,
  `ORDEN_PRVKITD` int(11) NOT NULL DEFAULT 0,
  `INSTANTE_ALTA` datetime NOT NULL,
  `USUARIO_ALTA` varchar(50) NOT NULL,
  `INSTANTE_MODIF` datetime DEFAULT NULL,
  `USUARIO_MODIF` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`CODIGO_PRV_PRVKITD`,`CODIGO_PRVKIT_PRVKITD`,`VALOR_DESTINO_PRVKITD`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_prueba_skucel`;
CREATE TABLE `fza_prueba_skucel` (
  `SERIE_PSC` varchar(10) NOT NULL,
  `NUMERO_PSC` int(11) NOT NULL,
  `LINEA_PSC` int(11) NOT NULL,
  `ID_FILA_PSC` int(11) NOT NULL DEFAULT 1,
  `CODIGO_ALM_PSC` varchar(10) NOT NULL DEFAULT '',
  `ID_AV_PIVOT_PSC` int(11) NOT NULL,
  `CANTIDAD_PSC` double NOT NULL DEFAULT 0,
  `INSTANTE_ALTA` datetime DEFAULT NULL,
  `INSTANTE_MODIF` datetime DEFAULT NULL,
  `USUARIO_ALTA` varchar(50) DEFAULT NULL,
  `USUARIO_MODIF` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`SERIE_PSC`,`NUMERO_PSC`,`LINEA_PSC`,`ID_FILA_PSC`,`CODIGO_ALM_PSC`,`ID_AV_PIVOT_PSC`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_recibos`;
CREATE TABLE `fza_recibos` (
  `NUMERO_FAC_REC` varchar(12) NOT NULL,
  `SERIE_FAC_REC` varchar(12) NOT NULL,
  `NUMERO_PLAZO_REC` int(11) NOT NULL,
  `FORMA_PAGO_ORIGEN_RECIBO_REC` varchar(20) DEFAULT NULL,
  `FORMA_PAGO_DESCRIPCION_ORIGEN_RECIBO_REC` varchar(100) DEFAULT NULL,
  `EUROS_RECIBO_REC` decimal(18,6) DEFAULT NULL,
  `ESTADO_RECIBO_REC` varchar(10) DEFAULT NULL,
  `FECHA_EXPEDICION_RECIBO_REC` date DEFAULT NULL,
  `FECHA_VENCIMIENTO_RECIBO_REC` date DEFAULT NULL,
  `IBAN_CLI_REC` varchar(34) DEFAULT NULL,
  `CODIGO_EMPBAN_REC` varchar(8) DEFAULT NULL COMMENT 'Cuenta de la empresa (ingreso) — FK a fza_empresas_bancos',
  `IBAN_EMP_REC` varchar(34) DEFAULT NULL COMMENT 'IBAN de la empresa (ingreso), denormalizado del banco',
  `FECHA_PAGO_RECIBO_REC` date DEFAULT NULL,
  `LOCALIDAD_EXPEDICION_RECIBO_REC` varchar(200) DEFAULT NULL,
  `CODIGO_CLI_REC` varchar(20) DEFAULT NULL,
  `RAZON_SOCIAL_CLI_REC` varchar(200) DEFAULT NULL,
  `DIRECCION1_CLIENTE_RECIBO_REC` varchar(200) DEFAULT NULL,
  `POBLACION_CLI_REC` varchar(200) DEFAULT NULL,
  `PROVINCIA_CLI_REC` varchar(200) DEFAULT NULL,
  `CODIGO_POSTAL_CLI_REC` varchar(15) DEFAULT NULL,
  `CODIGO_PAI_CLI_REC` varchar(3) DEFAULT '724',
  `NOMBRE_PAI_CLI_REC` varchar(150) DEFAULT 'España',
  `IMPORTE_LETRA_RECIBO_REC` varchar(150) DEFAULT NULL,
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  PRIMARY KEY (`NUMERO_FAC_REC`,`SERIE_FAC_REC`,`NUMERO_PLAZO_REC`),
  KEY `IDX_REC_CLI` (`CODIGO_CLI_REC`),
  KEY `IDX_REC_ESTADO_VENC` (`ESTADO_RECIBO_REC`,`FECHA_VENCIMIENTO_RECIBO_REC`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_remesas_compra`;
CREATE TABLE `fza_remesas_compra` (
  `NUMERO_REMC` varchar(20) NOT NULL,
  `SERIE_REMC` varchar(20) NOT NULL,
  `FECHA_REMC` date DEFAULT NULL,
  `ESTADO_REMC` varchar(20) DEFAULT 'ABIERTA' COMMENT 'ABIERTA, CERRADA, ENVIADA, PAGADA, CANCELADA',
  `CODIGO_EMP_REMC` varchar(8) DEFAULT NULL,
  `TIPO_REMC` varchar(20) DEFAULT 'NORMA34' COMMENT 'Norma SEPA de pago (p.ej. cuaderno 34)',
  `NORMA_REMC` varchar(10) DEFAULT NULL,
  `ENTIDAD_REMC` varchar(4) DEFAULT NULL,
  `OFICINA_REMC` varchar(4) DEFAULT NULL,
  `DIGITO_CONTROL_REMC` varchar(2) DEFAULT NULL,
  `CUENTA_REMC` varchar(10) DEFAULT NULL,
  `IBAN_REMC` varchar(34) DEFAULT NULL COMMENT 'Cuenta de cargo de la empresa',
  `CONTADOR_EFECTOS_REMC` int(11) DEFAULT 0,
  `TOTAL_REMC` decimal(18,6) DEFAULT 0.000000,
  `TOTAL_GASTOS_REMC` decimal(18,6) DEFAULT 0.000000,
  `TOTAL_COMISION_REMC` decimal(18,6) DEFAULT 0.000000,
  `FECHA_CARGO_REMC` date DEFAULT NULL COMMENT 'Fecha de cargo en cuenta',
  `ARCHIVO_REMC` varchar(200) DEFAULT NULL COMMENT 'Fichero SEPA generado',
  `ID_MENSAJE_SEPA_REMC` varchar(35) DEFAULT NULL COMMENT 'MsgId del fichero SEPA; fijo hasta reabrir',
  `FORMATO_SEPA_REMC` varchar(20) DEFAULT NULL COMMENT 'pain.001.001.03 o pain.001.001.09',
  `INSTANTE_FICHERO_SEPA_REMC` datetime DEFAULT NULL COMMENT 'Ultima generacion del fichero SEPA',
  `OBSERVACIONES_REMC` varchar(1000) DEFAULT '',
  `INSTANTE_CONTABILIZACION_REMC` datetime DEFAULT NULL,
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  PRIMARY KEY (`NUMERO_REMC`,`SERIE_REMC`),
  KEY `IDX_REMC_EMPRESA` (`CODIGO_EMP_REMC`),
  KEY `IDX_REMC_ESTADO` (`ESTADO_REMC`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_remesas_venta`;
CREATE TABLE `fza_remesas_venta` (
  `NUMERO_REMV` varchar(20) NOT NULL,
  `SERIE_REMV` varchar(20) NOT NULL,
  `FECHA_REMV` date DEFAULT NULL,
  `ESTADO_REMV` varchar(20) DEFAULT 'ABIERTA' COMMENT 'ABIERTA, PARCIAL, CERRADA, ENVIADA, COBRADA, CANCELADA',
  `CODIGO_EMP_REMV` varchar(8) DEFAULT NULL,
  `TIPO_REMV` varchar(20) DEFAULT 'NORMA19' COMMENT 'Norma SEPA de cobro (p.ej. cuaderno 19)',
  `NORMA_REMV` varchar(10) DEFAULT NULL,
  `TIPO_SECUENCIA_SEPA_REMV` varchar(4) DEFAULT 'RCUR' COMMENT 'Secuencia SEPA del adeudo: FRST, RCUR, OOFF o FNAL',
  `ENTIDAD_REMV` varchar(4) DEFAULT NULL,
  `OFICINA_REMV` varchar(4) DEFAULT NULL,
  `DIGITO_CONTROL_REMV` varchar(2) DEFAULT NULL,
  `CUENTA_REMV` varchar(10) DEFAULT NULL,
  `IBAN_REMV` varchar(34) DEFAULT NULL COMMENT 'Cuenta de ingreso de la empresa',
  `CONTADOR_EFECTOS_REMV` int(11) DEFAULT 0,
  `TOTAL_REMV` decimal(18,6) DEFAULT 0.000000,
  `TOTAL_GASTOS_REMV` decimal(18,6) DEFAULT 0.000000,
  `TOTAL_COMISION_REMV` decimal(18,6) DEFAULT 0.000000,
  `FECHA_CARGO_REMV` date DEFAULT NULL,
  `ARCHIVO_REMV` varchar(200) DEFAULT NULL,
  `OBSERVACIONES_REMV` varchar(1000) DEFAULT '',
  `INSTANTE_CONTABILIZACION_REMV` datetime DEFAULT NULL,
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  PRIMARY KEY (`NUMERO_REMV`,`SERIE_REMV`),
  KEY `IDX_REMV_EMPRESA` (`CODIGO_EMP_REMV`),
  KEY `IDX_REMV_ESTADO` (`ESTADO_REMV`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_reparaciones_acuerdos`;
CREATE TABLE `fza_reparaciones_acuerdos` (
  `ID_GAR_RAC` bigint(20) NOT NULL,
  `REFERENCIA_RAC` varchar(100) NOT NULL DEFAULT '',
  `AUTORIZACION_RAC` varchar(200) NOT NULL DEFAULT '',
  `PORCENTAJE_MANO_OBRA_RAC` decimal(7,4) NOT NULL DEFAULT 0.0000,
  `PORCENTAJE_MATERIAL_RAC` decimal(7,4) NOT NULL DEFAULT 0.0000,
  `TOTAL_LIMITE_RAC` decimal(18,2) DEFAULT NULL,
  `TOTAL_FRANQUICIA_RAC` decimal(18,2) NOT NULL DEFAULT 0.00,
  `ESAUTORIZADO_RAC` varchar(1) NOT NULL DEFAULT 'N',
  `ESACEPTADO_CLIENTE_RAC` varchar(1) NOT NULL DEFAULT 'N',
  `ESCIERRE_TECNICO_RAC` varchar(1) NOT NULL DEFAULT 'N',
  `ESCIERRE_ECONOMICO_RAC` varchar(1) NOT NULL DEFAULT 'N',
  `EXCEPCION_ENTREGA_RAC` varchar(500) NOT NULL DEFAULT '',
  `REVISION_RAC` int(11) NOT NULL DEFAULT 0,
  `INSTANTE_ALTA` datetime NOT NULL DEFAULT current_timestamp(),
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `INSTANTE_MODIF` datetime DEFAULT NULL,
  `USUARIO_MODIF` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`ID_GAR_RAC`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_reparaciones_albaranes`;
CREATE TABLE `fza_reparaciones_albaranes` (
  `ID_GAR_GARALB` bigint(20) NOT NULL,
  `TIPO_GARALB` varchar(2) NOT NULL COMMENT 'CL cliente; PR proveedor',
  `SERIE_GARALB` varchar(20) NOT NULL,
  `NUMERO_GARALB` varchar(20) NOT NULL,
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT current_timestamp(),
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `INSTANTE_MODIF` timestamp NULL DEFAULT NULL,
  `USUARIO_MODIF` varchar(100) DEFAULT NULL,
