  PRIMARY KEY (`CODIGO_TAR_TARDVA`,`ID_PV_TARDVA`),
  KEY `IDX_TARDVA_VALOR` (`ID_PV_TARDVA`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_tarifas_periodos`;
CREATE TABLE `fza_tarifas_periodos` (
  `CODIGO_TAR_TPER` varchar(10) NOT NULL,
  `NUMERO_LINEA_TPER` int(11) NOT NULL,
  `TIPO_TPER` varchar(6) NOT NULL,
  `DIA_DESDE_TPER` int(11) NOT NULL,
  `DIA_HASTA_TPER` int(11) NOT NULL,
  `INSTANTE_ALTA` datetime NOT NULL,
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `INSTANTE_MODIF` datetime DEFAULT NULL,
  `USUARIO_MODIF` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`CODIGO_TAR_TPER`,`NUMERO_LINEA_TPER`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_tipos_documentos`;
CREATE TABLE `fza_tipos_documentos` (
  `CODIGO_TIPO_DOCUMENTO_TD` varchar(2) NOT NULL,
  `DESCRIPCION_TIPO_DOCUMENTO_TD` varchar(100) NOT NULL,
  `TABLA_ORIGEN_TIPO_DOCUMENTO_TD` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`CODIGO_TIPO_DOCUMENTO_TD`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_tipos_efecto`;
CREATE TABLE `fza_tipos_efecto` (
  `CODIGO_TEFE` varchar(20) NOT NULL,
  `DESCRIPCION_TEFE` varchar(100) NOT NULL,
  `ESDOMICILIADO_TEFE` varchar(1) DEFAULT 'N' COMMENT 'S/N — el pago se domicilia en cuenta bancaria',
  `ESREMESABLE_TEFE` varchar(1) DEFAULT 'N' COMMENT 'S/N — el efecto puede agruparse en una remesa',
  `ORDEN_TEFE` int(11) DEFAULT 0,
  `ESACTIVO_TEFE` varchar(1) DEFAULT 'S',
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  PRIMARY KEY (`CODIGO_TEFE`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_traducciones`;
CREATE TABLE `fza_traducciones` (
  `ID_TRAD` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `CLAVE_TRAD` varchar(255) NOT NULL,
  `IDIOMA_TRAD` varchar(20) NOT NULL,
  `TEXTO_TRAD` text NOT NULL,
  `CONTEXTO_TRAD` varchar(500) DEFAULT NULL,
  `ESACTIVO_TRAD` varchar(1) NOT NULL DEFAULT 'S',
  `ESDESCARGADA_TRAD` varchar(1) NOT NULL DEFAULT 'N',
  `INSTANTE_ALTA` datetime NOT NULL DEFAULT current_timestamp(),
  `USUARIO_ALTA` varchar(50) NOT NULL,
  `INSTANTE_MODIF` datetime DEFAULT NULL,
  `USUARIO_MODIF` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`ID_TRAD`),
  UNIQUE KEY `UQ_TRAD_CLAVE_IDIOMA` (`CLAVE_TRAD`,`IDIOMA_TRAD`),
  KEY `IDX_TRAD_DESCARGADA_IDIOMA` (`ESDESCARGADA_TRAD`,`IDIOMA_TRAD`),
  KEY `IDX_TRAD_IDIOMA_ACTIVO` (`IDIOMA_TRAD`,`ESACTIVO_TRAD`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_traspasos_propuestas`;
CREATE TABLE `fza_traspasos_propuestas` (
  `ID_TRPRO` bigint(20) NOT NULL AUTO_INCREMENT,
  `ID_DTR_TRPRO` bigint(20) NOT NULL COMMENT 'Documento de trabajo que se reparte',
  `INSTANTE_PROPUESTA_TRPRO` datetime NOT NULL,
  `ESTADO_TRPRO` varchar(20) NOT NULL DEFAULT 'PENDIENTE' COMMENT 'PENDIENTE, TRASLADADO, NO ACEPTADO',
  `CODIGO_ALM_ORIGEN_TRPRO` varchar(10) NOT NULL COMMENT 'Almacen donde esta la mercancia',
  `CODIGO_ALM_DESTINO_TRPRO` varchar(10) NOT NULL COMMENT 'Tienda que la recibe',
  `TIPO_DOC_TRPRO` varchar(2) DEFAULT NULL COMMENT 'TR/TA del traspaso generado al confirmar',
  `SERIE_DOC_TRPRO` varchar(20) DEFAULT NULL,
  `NUMERO_DOC_TRPRO` varchar(20) DEFAULT NULL,
  `NUMERO_OPERACION_TRPRO` varchar(20) DEFAULT NULL COMMENT 'Operacion de caja del traspaso',
  `CODIGO_CAJA_TRPRO` varchar(10) DEFAULT NULL COMMENT 'Caja que confirmo la propuesta',
  `INSTANTE_RESOLUCION_TRPRO` datetime DEFAULT NULL COMMENT 'Cuando se traslado o no se acepto',
  `USUARIO_RESOLUCION_TRPRO` varchar(100) DEFAULT NULL,
  `MOTIVO_RECHAZO_TRPRO` varchar(255) DEFAULT NULL COMMENT 'Motivo si la propuesta no se acepta',
  `OBSERVACIONES_TRPRO` varchar(1000) DEFAULT NULL,
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  PRIMARY KEY (`ID_TRPRO`),
  KEY `IDX_TRPRO_ALM_ORIGEN_ESTADO` (`CODIGO_ALM_ORIGEN_TRPRO`,`ESTADO_TRPRO`),
  KEY `IDX_TRPRO_DTR` (`ID_DTR_TRPRO`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_traspasos_propuestas_lineas`;
CREATE TABLE `fza_traspasos_propuestas_lineas` (
  `ID_TRPRO_TRPROLIN` bigint(20) NOT NULL,
  `CODIGO_UNIDAD_TRPROLIN` varchar(50) NOT NULL COMMENT 'SKU propuesto',
  `LOTE_TRPROLIN` varchar(50) DEFAULT NULL,
  `FECHA_CADUCIDAD_TRPROLIN` date DEFAULT NULL,
  `CODIGO_ART_TRPROLIN` varchar(20) NOT NULL,
  `DESCRIPCION_ARTICULO_TRPROLIN` varchar(200) DEFAULT NULL,
  `CANTIDAD_TRPROLIN` decimal(19,6) NOT NULL DEFAULT 0.000000 COMMENT 'Unidades propuestas',
  `CANTIDAD_TRASPASADA_TRPROLIN` decimal(19,6) NOT NULL DEFAULT 0.000000 COMMENT 'Unidades del traspaso real al confirmar',
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  PRIMARY KEY (`ID_TRPRO_TRPROLIN`,`CODIGO_UNIDAD_TRPROLIN`),
  KEY `IDX_TRPROLIN_ART` (`CODIGO_ART_TRPROLIN`),
  KEY `IDX_TRPROLIN_UNIDAD` (`CODIGO_UNIDAD_TRPROLIN`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_traspasos_solicitudes`;
CREATE TABLE `fza_traspasos_solicitudes` (
  `NUMERO_TRSOL` varchar(20) NOT NULL,
  `SERIE_TRSOL` varchar(20) NOT NULL,
  `FECHA_TRSOL` datetime DEFAULT current_timestamp(),
  `ESTADO_TRSOL` varchar(20) DEFAULT 'PENDIENTE' COMMENT 'Estado de peticiones MANUAL; NULL para AUTO',
  `CODIGO_EMP_TRSOL` varchar(20) NOT NULL,
  `CODIGO_ALM_ORIGEN_TRSOL` varchar(10) NOT NULL COMMENT 'A quien se pide = origen del futuro traspaso',
  `CODIGO_ALM_DESTINO_TRSOL` varchar(10) NOT NULL COMMENT 'Quien pide = propio = destino del futuro traspaso',
  `CODIGO_EMP_CONTRA_TRSOL` varchar(20) DEFAULT NULL,
  `CODIGO_CAJA_TRSOL` varchar(10) DEFAULT NULL,
  `CODIGO_EMPLEADO_TRSOL` varchar(20) DEFAULT NULL,
  `OBSERVACIONES_TRSOL` varchar(1000) DEFAULT '',
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  `TIPO_TRSOL` varchar(20) NOT NULL DEFAULT 'MANUAL' COMMENT 'MANUAL=petición ordinaria, AUTO=reposición desde ventas',
  `INSTANTE_VENTAS_DESDE_TRSOL` datetime DEFAULT NULL COMMENT 'Inicio inclusivo de las ventas',
  `INSTANTE_VENTAS_HASTA_TRSOL` datetime DEFAULT NULL COMMENT 'Fin exclusivo de las ventas',
  PRIMARY KEY (`NUMERO_TRSOL`,`SERIE_TRSOL`),
  KEY `IDX_TRSOL_DESTINO` (`CODIGO_ALM_DESTINO_TRSOL`,`ESTADO_TRSOL`),
  KEY `IDX_TRSOL_EMP` (`CODIGO_EMP_TRSOL`),
  KEY `IDX_TRSOL_EMP_INSTANTE` (`CODIGO_EMP_TRSOL`,`INSTANTE_ALTA`),
  KEY `IDX_TRSOL_ESTADO` (`ESTADO_TRSOL`),
  KEY `IDX_TRSOL_ORIGEN` (`CODIGO_ALM_ORIGEN_TRSOL`,`ESTADO_TRSOL`),
  KEY `IDX_TRSOL_TIPO_INSTANTE` (`TIPO_TRSOL`,`INSTANTE_ALTA`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_traspasos_solicitudes_lineas`;
CREATE TABLE `fza_traspasos_solicitudes_lineas` (
  `NUMERO_TRSOL_TRSOLLIN` varchar(20) NOT NULL,
  `SERIE_TRSOL_TRSOLLIN` varchar(20) NOT NULL,
  `LINEA_TRSOLLIN` varchar(4) NOT NULL,
  `CODIGO_ART_TRSOLLIN` varchar(20) DEFAULT NULL,
  `CODIGO_UNIDAD_TRSOLLIN` varchar(50) NOT NULL COMMENT 'SKU solicitado',
  `LOTE_TRSOLLIN` varchar(50) DEFAULT NULL,
  `FECHA_CADUCIDAD_TRSOLLIN` date DEFAULT NULL,
  `DESCRIPCION_ARTICULO_TRSOLLIN` varchar(100) DEFAULT NULL,
  `CANTIDAD_PEDIDA_TRSOLLIN` decimal(19,6) NOT NULL DEFAULT 0.000000,
  `CANTIDAD_SERVIDA_TRSOLLIN` decimal(19,6) NOT NULL DEFAULT 0.000000 COMMENT 'Unidades ya atendidas (para estado PARCIAL)',
  `ESATENDIDA_TRSOLLIN` varchar(1) NOT NULL DEFAULT 'N',
  `MOTIVO_RECHAZO_TRSOLLIN` varchar(255) DEFAULT NULL COMMENT 'Motivo si la linea se deniega (servida=0)',
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  `CODIGO_PRV_TRSOLLIN` varchar(20) DEFAULT NULL COMMENT 'Proveedor histórico de la venta',
  `RAZON_SOCIAL_PRV_TRSOLLIN` varchar(200) DEFAULT NULL COMMENT 'Nombre histórico del proveedor',
  PRIMARY KEY (`NUMERO_TRSOL_TRSOLLIN`,`SERIE_TRSOL_TRSOLLIN`,`LINEA_TRSOLLIN`),
  KEY `IDX_TRSOLLIN_SKU` (`CODIGO_UNIDAD_TRSOLLIN`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_traspasos_transito`;
CREATE TABLE `fza_traspasos_transito` (
  `ID_TRTRA` bigint(20) NOT NULL AUTO_INCREMENT,
  `CODIGO_EMP_TRTRA` varchar(20) NOT NULL,
  `CODIGO_ALM_ORIGEN_TRTRA` varchar(10) NOT NULL COMMENT 'Almacen que carga',
  `CODIGO_ALM_TRANSITO_TRTRA` varchar(10) NOT NULL COMMENT 'Almacen TRANSITO: furgoneta o agencia',
  `CODIGO_ALM_DESTINO_TRTRA` varchar(10) NOT NULL COMMENT 'Destino final que recibe la carga',
  `TIPO_DOC_CARGA_TRTRA` varchar(2) NOT NULL COMMENT 'TR o TA: documento de los movimientos de la carga',
  `SERIE_CARGA_TRTRA` varchar(20) NOT NULL,
  `NUMERO_CARGA_TRTRA` varchar(20) NOT NULL,
  `NUMERO_OPERACION_CARGA_TRTRA` varchar(20) DEFAULT NULL,
  `CODIGO_CAJA_CARGA_TRTRA` varchar(10) DEFAULT NULL,
  `FECHA_CARGA_TRTRA` datetime NOT NULL,
  `ESTADO_TRTRA` varchar(20) NOT NULL DEFAULT 'PENDIENTE' COMMENT 'PENDIENTE, RECIBIDO, RECIBIDO_INCIDENCIAS, DEVUELTO, PERDIDO, ANULADO',
  `TIPO_DOC_RECEPCION_TRTRA` varchar(2) DEFAULT NULL,
  `SERIE_RECEPCION_TRTRA` varchar(20) DEFAULT NULL,
  `NUMERO_RECEPCION_TRTRA` varchar(20) DEFAULT NULL,
  `NUMERO_OPERACION_RECEPCION_TRTRA` varchar(20) DEFAULT NULL,
  `CODIGO_CAJA_RECEPCION_TRTRA` varchar(10) DEFAULT NULL,
  `FECHA_RECEPCION_TRTRA` datetime DEFAULT NULL,
  `TIPO_DESBLOQUEO_TRTRA` varchar(20) DEFAULT NULL COMMENT 'DEVOLUCION, CAMBIO_DESTINO, PERDIDA',
  `MOTIVO_DESBLOQUEO_TRTRA` varchar(255) DEFAULT NULL,
  `USUARIO_DESBLOQUEO_TRTRA` varchar(100) DEFAULT NULL,
  `INSTANTE_DESBLOQUEO_TRTRA` datetime DEFAULT NULL,
  `CODIGO_ALM_DESTINO_INICIAL_TRTRA` varchar(10) DEFAULT NULL COMMENT 'Destino con el que se cargo, si despues se cambio',
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  PRIMARY KEY (`ID_TRTRA`),
  UNIQUE KEY `UQ_TRTRA_TIPO_DOC_CARGA_SERIE_CARGA_NUMERO_CARGA` (`TIPO_DOC_CARGA_TRTRA`,`SERIE_CARGA_TRTRA`,`NUMERO_CARGA_TRTRA`),
  KEY `IDX_TRTRA_ALM_DESTINO_ESTADO` (`CODIGO_ALM_DESTINO_TRTRA`,`ESTADO_TRTRA`),
  KEY `IDX_TRTRA_ALM_TRANSITO_ESTADO` (`CODIGO_ALM_TRANSITO_TRTRA`,`ESTADO_TRTRA`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_traspasos_transito_incidencias`;
CREATE TABLE `fza_traspasos_transito_incidencias` (
  `ID_TRTINC` bigint(20) NOT NULL AUTO_INCREMENT,
  `ID_TRTRA_TRTINC` bigint(20) NOT NULL COMMENT 'Carga en transito de la incidencia',
  `TIPO_TRTINC` varchar(20) NOT NULL COMMENT 'PERDIDA, DETERIORO',
  `CODIGO_UNIDAD_TRTINC` varchar(50) NOT NULL COMMENT 'SKU',
  `LOTE_TRTINC` varchar(50) DEFAULT NULL,
  `FECHA_CADUCIDAD_TRTINC` date DEFAULT NULL,
  `CODIGO_ART_TRTINC` varchar(20) DEFAULT NULL,
  `DESCRIPCION_ARTICULO_TRTINC` varchar(100) DEFAULT NULL,
  `CANTIDAD_TRTINC` decimal(19,6) NOT NULL DEFAULT 0.000000,
  `PRECIO_COSTE_TRTINC` decimal(19,6) NOT NULL DEFAULT 0.000000 COMMENT 'Coste unitario de la carga',
  `TOTAL_COSTE_TRTINC` decimal(19,6) NOT NULL DEFAULT 0.000000,
  `CODIGO_ALM_TARAS_TRTINC` varchar(10) DEFAULT NULL COMMENT 'Almacen de taras que recibe lo deteriorado',
  `MOTIVO_TRTINC` varchar(255) DEFAULT NULL,
  `REFERENCIA_RECLAMACION_TRTINC` varchar(100) DEFAULT NULL COMMENT 'Referencia de la reclamacion al transportista',
  `ESTADO_RECLAMACION_TRTINC` varchar(20) NOT NULL DEFAULT 'PENDIENTE' COMMENT 'PENDIENTE, ENVIADA, ACEPTADA, COBRADA, RECHAZADA',
  `IMPORTE_RECLAMADO_TRTINC` decimal(19,6) DEFAULT NULL COMMENT 'Parte de la reclamacion; NULL = el coste',
  `IMPORTE_INDEMNIZADO_TRTINC` decimal(19,6) DEFAULT NULL COMMENT 'Parte de la indemnizacion; NULL = aun no se sabe',
  `TIPO_DOC_TRTINC` varchar(5) DEFAULT NULL COMMENT 'Documento de los movimientos de la incidencia',
  `SERIE_DOC_TRTINC` varchar(20) DEFAULT NULL,
  `NUMERO_DOC_TRTINC` varchar(20) DEFAULT NULL,
  `FECHA_TRTINC` datetime NOT NULL,
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  PRIMARY KEY (`ID_TRTINC`),
  KEY `IDX_TRTINC_FECHA` (`FECHA_TRTINC`),
  KEY `IDX_TRTINC_TRTRA` (`ID_TRTRA_TRTINC`),
  KEY `IDX_TRTINC_RECLAMACION` (`REFERENCIA_RECLAMACION_TRTINC`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_unidades_medida`;
CREATE TABLE `fza_unidades_medida` (
  `CODIGO_UNIMED` varchar(20) NOT NULL COMMENT 'Clave de la unidad: Uds, m, cm, kg, g, rollo...',
  `DESCRIPCION_UNIMED` varchar(100) NOT NULL COMMENT 'Nombre legible: Metros, Kilogramos...',
  `DECIMALES_UNIMED` int(11) NOT NULL DEFAULT 2 COMMENT 'Numero de decimales a mostrar/teclear para esta unidad',
  `MAGNITUD_UNIMED` varchar(20) NOT NULL DEFAULT 'OTROS' COMMENT 'Familia fisica: UNIDAD, LONGITUD, MASA, VOLUMEN... Solo se convierten entre si unidades de la misma magnitud',
  `ESBASE_UNIMED` varchar(1) NOT NULL DEFAULT 'N' COMMENT 'S = unidad estandar/base de su magnitud (metro, kilo...)',
  `FACTOR_BASE_UNIMED` decimal(19,6) NOT NULL DEFAULT 1.000000 COMMENT 'Factor a la unidad base: valor_base = valor * FACTOR (cm->m = 0.01, g->kg = 0.001)',
  `ORDEN_UNIMED` int(11) DEFAULT 0 COMMENT 'Orden de presentacion en desplegables',
  `ESACTIVO_UNIMED` varchar(1) NOT NULL DEFAULT 'S' COMMENT 'S/N: unidad activa',
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL DEFAULT 'SISTEMA',
  `USUARIO_MODIF` varchar(100) NOT NULL DEFAULT 'SISTEMA',
  PRIMARY KEY (`CODIGO_UNIMED`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_usuarios`;
CREATE TABLE `fza_usuarios` (
  `USUARIO_USU` varchar(100) NOT NULL,
  `PASSWORD_USU` varchar(100) DEFAULT NULL,
  `GRUPO_USU` varchar(200) DEFAULT NULL,
  `ESACTIVO_USU` varchar(1) DEFAULT NULL,
  `EMPRESA_DEFECTO_USU` varchar(10) DEFAULT NULL,
  `ULTIMO_LOGIN_USU` timestamp NULL DEFAULT NULL,
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  `ALMACEN_DEFECTO_USU` varchar(10) DEFAULT NULL,
  `CAJA_DEFECTO_USU` varchar(10) DEFAULT NULL,
  PRIMARY KEY (`USUARIO_USU`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_usuarios_empl_bak`;
CREATE TABLE `fza_usuarios_empl_bak` (
  `USUARIO_USU` varchar(100) NOT NULL,
  `CODIGO_EMPLEADO_USU` varchar(10) DEFAULT NULL,
  `DIMINUTIVO_TICKET_USU` varchar(10) DEFAULT NULL,
  PRIMARY KEY (`USUARIO_USU`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_usuarios_grupos`;
CREATE TABLE `fza_usuarios_grupos` (
  `GRUPO_USUGRP` varchar(200) NOT NULL,
  `ESGRUPOADMINISTRADOR_USUGRP` varchar(1) DEFAULT 'N',
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  PRIMARY KEY (`GRUPO_USUGRP`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_usuarios_perfiles`;
CREATE TABLE `fza_usuarios_perfiles` (
  `USUARIO_GRUPO_USUPER` varchar(200) NOT NULL,
  `KEY_USUPER` varchar(100) NOT NULL,
  `SUBKEY_USUPER` varchar(100) NOT NULL,
  `VALUE_USUPER` varchar(200) NOT NULL,
  `VALUE_TEXT_USUPER` text DEFAULT NULL,
  `TYPE_BLOB_USUPER` varchar(10) DEFAULT NULL,
  `VALUE_BLOB_USUPER` mediumblob DEFAULT NULL,
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  PRIMARY KEY (`USUARIO_GRUPO_USUPER`,`KEY_USUPER`,`SUBKEY_USUPER`),
  KEY `IDX_KEYPERFIL` (`KEY_USUPER`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_valores_defecto`;
CREATE TABLE `fza_valores_defecto` (
  `TABLA_OBJETIVO_DEF_VD` varchar(60) NOT NULL COMMENT 'Nombre de la tabla, ej: fza_articulos',
  `CAMPO_OBJETIVO_DEF_VD` varchar(60) NOT NULL COMMENT 'Nombre del campo, ej: TIPO_IVA_ART',
  `VALOR_DEF_VD` varchar(255) DEFAULT NULL COMMENT 'El valor fijo a insertar',
  `TIPO_DATO_DEF_VD` varchar(20) DEFAULT 'STRING' COMMENT 'STRING, INTEGER, FLOAT, BOOLEAN, MACRO',
  `DESCRIPCION_DEF_VD` varchar(100) DEFAULT NULL COMMENT 'Para que sepas qué es esto',
  `VALORES_POSIBLES_DEF_VD` varchar(500) DEFAULT NULL COMMENT 'Lista separada por comas (ej: S,N o 21,10,4)',
  PRIMARY KEY (`TABLA_OBJETIVO_DEF_VD`,`CAMPO_OBJETIVO_DEF_VD`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_variaciones`;
CREATE TABLE `fza_variaciones` (
  `CODIGO_VAR` varchar(20) NOT NULL,
  `NOMBRE_VAR` varchar(100) DEFAULT NULL,
  `ESACTIVO_VAR` varchar(1) DEFAULT 'S',
  `ORDEN_VAR` int(11) DEFAULT NULL,
  `ROTULO_OTRO_VAR` varchar(50) DEFAULT NULL COMMENT 'Botón que repite la línea con otro valor del eje de fila en sesiones de compra (Otro color, Otro aroma)',
  `ESCOLOR_BASICO_VAR` varchar(1) NOT NULL DEFAULT 'N' COMMENT 'S = el eje de fila es un color con color básico (columna C. básico en sesiones de compra)',
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  PRIMARY KEY (`CODIGO_VAR`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_variaciones_atributos`;
CREATE TABLE `fza_variaciones_atributos` (
  `ID_VAR_VA` varchar(20) NOT NULL,
  `ID_ATB_VA` varchar(20) NOT NULL,
  `NOMBRE_VA` varchar(50) DEFAULT NULL,
  `ORDEN_VA` int(11) DEFAULT NULL,
  `NOMBRE_VISIBLE_VA` varchar(50) DEFAULT NULL COMMENT 'Etiqueta a mostrar en formularios cuando este atributo pivota',
  `EJE_VA` varchar(1) DEFAULT NULL COMMENT 'Eje declarado: S = pestañas; NULL = por posición',
  PRIMARY KEY (`ID_VAR_VA`,`ID_ATB_VA`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_ventas_ws_cola`;
CREATE TABLE `fza_ventas_ws_cola` (
  `ID_VWSC` bigint(20) NOT NULL AUTO_INCREMENT,
