  `TIPO_EVENTO_VWSC` varchar(30) NOT NULL,
  `VERSION_CONTRATO_VWSC` int(11) NOT NULL DEFAULT 1,
  `ESTADO_VWSC` varchar(20) NOT NULL DEFAULT 'PENDIENTE',
  `CONTADOR_INTENTOS_VWSC` int(11) NOT NULL DEFAULT 0,
  `INSTANTE_PROXIMO_INTENTO_VWSC` datetime DEFAULT NULL,
  `INSTANTE_ENVIO_VWSC` datetime DEFAULT NULL,
  `ID_PETICION_VWSC` varchar(64) DEFAULT NULL,
  `CONTENIDO_JSON_VWSC` longtext DEFAULT NULL,
  `HUELLA_CONTENIDO_VWSC` char(64) DEFAULT NULL,
  `NOMBRE_PDF_VWSC` varchar(255) DEFAULT NULL,
  `TICKET_PDF_VWSC` longblob DEFAULT NULL,
  `TAMANO_PDF_VWSC` bigint(20) DEFAULT NULL,
  `HUELLA_PDF_VWSC` char(64) DEFAULT NULL,
  `NOMBRE_FACTURA_PDF_VWSC` varchar(255) DEFAULT NULL,
  `FACTURA_PDF_VWSC` longblob DEFAULT NULL,
  `TAMANO_FACTURA_PDF_VWSC` bigint(20) DEFAULT NULL,
  `HUELLA_FACTURA_PDF_VWSC` char(64) DEFAULT NULL,
  `MENSAJE_ERROR_VWSC` text DEFAULT NULL,
  `INSTANTE_ALTA` datetime NOT NULL,
  `USUARIO_ALTA` varchar(50) DEFAULT NULL,
  `INSTANTE_MODIF` datetime DEFAULT NULL,
  `USUARIO_MODIF` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`ID_VWSC`),
  UNIQUE KEY `UQ_VWSC_EVENTO` (`ID_EVENTO_VWSC`),
  KEY `IDX_VWSC_DOCUMENTO` (`CODIGO_EMP_VWSC`,`SERIE_FAC_VWSC`,`NUMERO_FAC_VWSC`),
  KEY `IDX_VWSC_ESTADO_PROXIMO` (`ESTADO_VWSC`,`INSTANTE_PROXIMO_INTENTO_VWSC`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_ventas_ws_cola_intentos`;
CREATE TABLE `fza_ventas_ws_cola_intentos` (
  `ID_VWSCI` bigint(20) NOT NULL AUTO_INCREMENT,
  `ID_VWSC_VWSCI` bigint(20) NOT NULL,
  `ID_EVENTO_VWSCI` char(36) NOT NULL,
  `CONTADOR_INTENTO_VWSCI` int(11) NOT NULL DEFAULT 0,
  `ID_PETICION_VWSCI` varchar(64) DEFAULT NULL,
  `METODO_HTTP_VWSCI` varchar(10) NOT NULL,
  `RECURSO_HTTP_VWSCI` varchar(1000) NOT NULL,
  `ESTADO_HTTP_VWSCI` int(11) NOT NULL DEFAULT 0,
  `PETICION_VWSCI` longtext DEFAULT NULL,
  `RESPUESTA_VWSCI` longtext DEFAULT NULL,
  `RESULTADO_VWSCI` varchar(20) NOT NULL,
  `MENSAJE_VWSCI` text DEFAULT NULL,
  `CANTIDAD_MILISEGUNDOS_VWSCI` bigint(20) unsigned NOT NULL DEFAULT 0,
  `INSTANTE_INICIO_VWSCI` datetime NOT NULL,
  `INSTANTE_FIN_VWSCI` datetime NOT NULL,
  `INSTANTE_ALTA` datetime NOT NULL,
  `USUARIO_ALTA` varchar(50) DEFAULT NULL,
  `INSTANTE_MODIF` datetime DEFAULT NULL,
  `USUARIO_MODIF` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`ID_VWSCI`),
  KEY `IDX_VWSCI_INICIO_RESULTADO` (`INSTANTE_INICIO_VWSCI`,`RESULTADO_VWSCI`),
  KEY `IDX_VWSCI_VWSC_ID` (`ID_VWSC_VWSCI`,`ID_VWSCI`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_verifactu_cadena`;
CREATE TABLE `fza_verifactu_cadena` (
  `NIF_VFCAD` varchar(50) NOT NULL COMMENT 'NIF del obligado de emision',
  `CONTADOR_VFCAD` bigint(20) NOT NULL DEFAULT 0 COMMENT 'Numero de registros aceptados (eslabones)',
  `SERIE_FAC_VFCAD` varchar(20) DEFAULT NULL COMMENT 'Serie de la ultima factura encadenada',
  `NUMERO_FAC_VFCAD` varchar(20) DEFAULT NULL COMMENT 'Numero de la ultima factura encadenada',
  `FECHA_FAC_VFCAD` date DEFAULT NULL COMMENT 'Fecha de expedicion de la ultima factura',
  `HUELLA_VFCAD` char(64) DEFAULT NULL COMMENT 'Huella SHA-256 del ultimo registro aceptado',
  `INSTANTE_ALTA` datetime NOT NULL,
  `USUARIO_ALTA` varchar(50) DEFAULT NULL,
  `INSTANTE_MODIF` datetime DEFAULT NULL,
  `USUARIO_MODIF` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`NIF_VFCAD`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_verifactu_cola`;
CREATE TABLE `fza_verifactu_cola` (
  `ID_VFCOLA` bigint(20) NOT NULL AUTO_INCREMENT,
  `SERIE_FAC_VFCOLA` varchar(20) NOT NULL,
  `NUMERO_FAC_VFCOLA` varchar(20) NOT NULL,
  `TIPO_OPERACION_VFCOLA` varchar(20) NOT NULL DEFAULT 'ALTA' COMMENT 'ALTA, ANULACION o SUBSANACION (en SII la subsanacion se envia como A1)',
  `SISTEMA_VFCOLA` varchar(10) NOT NULL DEFAULT 'VERIFACTU' COMMENT 'VERIFACTU o SII: sistema con el que se encolo la fila',
  `ESTADO_VFCOLA` varchar(20) NOT NULL DEFAULT 'PENDIENTE' COMMENT 'PENDIENTE, PROCESANDO, ENVIADA, ERROR',
  `CONTADOR_INTENTOS_VFCOLA` int(11) NOT NULL DEFAULT 0 COMMENT 'Numero de intentos de envio realizados',
  `FECHA_HORA_GEN_VFCOLA` varchar(40) DEFAULT NULL,
  `INSTANTE_PROXIMO_INTENTO_VFCOLA` datetime DEFAULT NULL COMMENT 'No reintentar antes de este instante (backoff)',
  `INSTANTE_ENVIO_VFCOLA` datetime DEFAULT NULL COMMENT 'Instante del envio aceptado por la AEAT',
  `MENSAJE_ERROR_VFCOLA` text DEFAULT NULL,
  `MOTIVO_VFCOLA` varchar(500) DEFAULT NULL,
  `INSTANTE_ALTA` datetime NOT NULL,
  `USUARIO_ALTA` varchar(50) DEFAULT NULL,
  `INSTANTE_MODIF` datetime DEFAULT NULL,
  `USUARIO_MODIF` varchar(50) DEFAULT NULL,
  `ORDEN_SUBSANACION_VFCOLA` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`ID_VFCOLA`),
  UNIQUE KEY `UQ_VFCOLA_SERIE_NUMERO_TIPO_ORDEN` (`SERIE_FAC_VFCOLA`,`NUMERO_FAC_VFCOLA`,`TIPO_OPERACION_VFCOLA`,`ORDEN_SUBSANACION_VFCOLA`),
  KEY `IDX_VFCOLA_ESTADO_PROXIMO` (`ESTADO_VFCOLA`,`INSTANTE_PROXIMO_INTENTO_VFCOLA`),
  KEY `IDX_VFCOLA_SISTEMA_ESTADO_PROXIMO` (`SISTEMA_VFCOLA`,`ESTADO_VFCOLA`,`INSTANTE_PROXIMO_INTENTO_VFCOLA`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_verifactu_eventos`;
CREATE TABLE `fza_verifactu_eventos` (
  `ID_LOG` bigint(20) NOT NULL AUTO_INCREMENT,
  `TIMESTAMP_LOG` datetime(3) NOT NULL,
  `TIPO_EVENTO_LOG` tinyint(3) unsigned NOT NULL,
  `USUARIO_LOG` varchar(100) NOT NULL,
  `VERSION_LOG` varchar(100) NOT NULL,
  `DESCRIPCION_LOG` text NOT NULL,
  `DATOS_ADICIONALES_LOG` longtext DEFAULT NULL,
  `HASH_ANTERIOR_LOG` char(64) NOT NULL,
  `HASH_PROPIO_LOG` char(64) NOT NULL,
  `FIRMA_DIGITAL_LOG` char(64) NOT NULL,
  `CREATED_AT_LOG` timestamp NULL DEFAULT current_timestamp(),
  `NUMERO_FAC_LOG` varchar(20) DEFAULT NULL,
  `SERIE_FAC_LOG` varchar(20) DEFAULT NULL,
  `REGISTRO_XML_LOG` longtext DEFAULT NULL,
  `FIRMA_XADES_LOG` longtext DEFAULT NULL,
  `SERIE_CERTIFICADO_LOG` varchar(128) DEFAULT NULL,
  `TITULAR_CERTIFICADO_LOG` varchar(1000) DEFAULT NULL,
  `HUELLA_CERTIFICADO_LOG` char(40) DEFAULT NULL,
  PRIMARY KEY (`ID_LOG`),
  KEY `idx_hash_propio` (`HASH_PROPIO_LOG`),
  KEY `idx_timestamp` (`TIMESTAMP_LOG`),
  KEY `idx_tipo_evento` (`TIPO_EVENTO_LOG`),
  KEY `idx_usuario` (`USUARIO_LOG`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_verifactu_historial`;
CREATE TABLE `fza_verifactu_historial` (
  `ID_VFHIST` bigint(20) NOT NULL AUTO_INCREMENT,
  `CLAVE_REGISTRO_VFHIST` varchar(64) NOT NULL,
  `ID_COLA_VFHIST` bigint(20) DEFAULT NULL,
  `ID_FACCON_VFHIST` int(11) DEFAULT NULL,
  `TIPO_REGISTRO_VFHIST` varchar(20) NOT NULL,
  `SERIE_FAC_VFHIST` varchar(20) NOT NULL,
  `NUMERO_FAC_VFHIST` varchar(20) NOT NULL,
  `MOTIVO_VFHIST` varchar(500) DEFAULT NULL,
  `ESTADO_VFHIST` varchar(30) DEFAULT NULL,
  `REQUEST_ID_VFHIST` varchar(255) DEFAULT NULL,
  `CHAIN_NUMBER_VFHIST` varchar(100) DEFAULT NULL,
  `CHAIN_HASH_VFHIST` varchar(256) DEFAULT NULL,
  `CODIGO_ERROR_AEAT_VFHIST` varchar(20) DEFAULT NULL,
  `DESCRIPCION_ERROR_AEAT_VFHIST` text DEFAULT NULL,
  `RESPUESTA_COMPLETA_VFHIST` longtext DEFAULT NULL,
  `PETICION_COMPLETA_VFHIST` longtext DEFAULT NULL,
  `REGISTRO_XML_VFHIST` longtext DEFAULT NULL,
  `FIRMA_DIGITAL_VFHIST` longtext DEFAULT NULL,
  `SERIE_CERTIFICADO_VFHIST` varchar(128) DEFAULT NULL,
  `TITULAR_CERTIFICADO_VFHIST` varchar(1000) DEFAULT NULL,
  `HUELLA_CERTIFICADO_VFHIST` char(40) DEFAULT NULL,
  `VERIFACTU_URL_VFHIST` text DEFAULT NULL,
  `QRCODE_BASE64_VFHIST` longtext DEFAULT NULL,
  `QRCODE_PNG_VFHIST` blob DEFAULT NULL,
  `INSTANTE_ALTA` datetime NOT NULL,
  `USUARIO_ALTA` varchar(50) DEFAULT NULL,
  `INSTANTE_MODIF` datetime DEFAULT NULL,
  `USUARIO_MODIF` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`ID_VFHIST`),
  UNIQUE KEY `UQ_VFHIST_CLAVE` (`CLAVE_REGISTRO_VFHIST`),
  KEY `IDX_VFHIST_COLA` (`ID_COLA_VFHIST`),
  KEY `IDX_VFHIST_SERIE_NUMERO` (`SERIE_FAC_VFHIST`,`NUMERO_FAC_VFHIST`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_verifactu_operaciones`;
CREATE TABLE `fza_verifactu_operaciones` (
  `CODIGO_VFO` varchar(20) NOT NULL,
  `DESCRIPCION_VFO` varchar(100) DEFAULT NULL,
  `AYUDA_VFO` varchar(255) DEFAULT NULL,
  `CLAVE_REGIMEN_VFO` varchar(2) DEFAULT '01',
  `CLAVE_REGIMEN_SII_VFO` varchar(2) DEFAULT NULL COMMENT 'Clave de regimen del SII; 18, 19 y 20 de VeriFactu pasan a 01',
  `CALIFICACION_VFO` varchar(2) DEFAULT NULL,
  `OPERACION_EXENTA_VFO` varchar(2) DEFAULT NULL,
  `ESREPERCUTE_IVA_VFO` varchar(1) DEFAULT 'S',
  `AMBITO_VFO` varchar(10) DEFAULT NULL,
  `ORDEN_VFO` int(11) DEFAULT NULL,
  `ESACTIVO_VFO` varchar(1) DEFAULT 'S',
  `INSTANTE_ALTA` datetime DEFAULT NULL,
  `INSTANTE_MODIF` datetime DEFAULT NULL,
  `USUARIO_ALTA` varchar(50) DEFAULT NULL,
  `USUARIO_MODIF` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`CODIGO_VFO`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `fza_winforms`;
CREATE TABLE `fza_winforms` (
  `CALL_WINF` varchar(255) NOT NULL,
  `CAPTION_WINF` varchar(255) DEFAULT NULL,
  `MENUITEM_WINF` varchar(255) DEFAULT NULL,
  `UNITF_WINF` varchar(255) DEFAULT NULL,
  `SHORTCUT_WINF` varchar(20) DEFAULT NULL,
  `DATAMODULE_WINF` varchar(255) DEFAULT NULL,
  `NUM_VENTANAS_WINF` int(11) NOT NULL DEFAULT 1,
  PRIMARY KEY (`CALL_WINF`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `inv_almacenes`;
CREATE TABLE `inv_almacenes` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `carpeta_cliente` varchar(80) NOT NULL,
  `codigo_emp` varchar(10) NOT NULL,
  `codigo_alm` varchar(10) NOT NULL,
  `nombre` varchar(100) DEFAULT NULL,
  `esactivo` char(1) NOT NULL DEFAULT 'S',
  `instante_modif` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_alm` (`carpeta_cliente`,`codigo_emp`,`codigo_alm`),
  KEY `idx_alm_cliente` (`carpeta_cliente`,`esactivo`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `inv_catalogo`;
CREATE TABLE `inv_catalogo` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `id_recuento` bigint(20) unsigned NOT NULL,
  `codigo_articulo` varchar(20) NOT NULL,
  `codigo_unidad` varchar(50) NOT NULL,
  `descripcion` varchar(200) DEFAULT NULL,
  `codigo_barras` varchar(50) DEFAULT NULL,
  `cantidad_teorica` decimal(19,6) DEFAULT NULL,
  `estrazable` char(1) NOT NULL DEFAULT 'N',
  PRIMARY KEY (`id`),
  KEY `idx_cat_barras` (`id_recuento`,`codigo_barras`),
  KEY `idx_cat_recuento` (`id_recuento`),
  KEY `idx_cat_sku` (`id_recuento`,`codigo_unidad`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `inv_dispositivos`;
CREATE TABLE `inv_dispositivos` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `carpeta_cliente` varchar(80) NOT NULL,
  `nombre` varchar(100) NOT NULL,
  `operario` varchar(100) DEFAULT NULL,
  `token` char(64) NOT NULL,
  `esactivo` char(1) NOT NULL DEFAULT 'S',
  `esadmin` char(1) NOT NULL DEFAULT 'N',
  `instante_alta` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_disp_token` (`token`),
  KEY `idx_disp_cliente` (`carpeta_cliente`,`esactivo`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `inv_eventos`;
CREATE TABLE `inv_eventos` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `id_recuento` bigint(20) unsigned NOT NULL,
  `uuid_evento` char(36) NOT NULL,
  `codigo_barras` varchar(50) DEFAULT NULL,
  `codigo_articulo` varchar(20) DEFAULT NULL,
  `codigo_unidad` varchar(50) DEFAULT NULL,
  `cantidad` decimal(19,6) NOT NULL DEFAULT 1.000000,
  `lote` varchar(50) DEFAULT NULL,
  `fecha_caducidad` date DEFAULT NULL,
  `instante_recuento` datetime NOT NULL,
  `operario` varchar(100) DEFAULT NULL,
  `dispositivo` varchar(100) DEFAULT NULL,
  `zona` varchar(100) DEFAULT NULL,
  `anulado` char(1) NOT NULL DEFAULT 'N',
  `instante_recibido` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_evento_uuid` (`uuid_evento`),
  KEY `idx_evt_recuento` (`id_recuento`,`id`),
  KEY `idx_evt_sku` (`id_recuento`,`codigo_unidad`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
DROP TABLE IF EXISTS `inv_recuentos`;
CREATE TABLE `inv_recuentos` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `carpeta_cliente` varchar(80) NOT NULL,
  `origen` enum('FACTUZAM','APP') NOT NULL,
  `modo` enum('DIRIGIDO','LIBRE') NOT NULL DEFAULT 'DIRIGIDO',
  `tipo` enum('RECUENTO','TRASPASO') NOT NULL DEFAULT 'RECUENTO',
  `codigo_emp` varchar(10) DEFAULT NULL,
  `codigo_alm` varchar(10) NOT NULL,
  `codigo_alm_destino` varchar(10) DEFAULT NULL,
  `serie` varchar(20) DEFAULT NULL,
  `numero` varchar(20) DEFAULT NULL,
  `descripcion` varchar(200) DEFAULT NULL,
  `estado` enum('PENDIENTE','EN_RECUENTO','RECONTADO','RECOGIDO','CANCELADO') NOT NULL DEFAULT 'PENDIENTE',
  `dispositivo_origen` varchar(100) DEFAULT NULL,
  `usuario_envio` varchar(100) DEFAULT NULL,
  `instante_envio` datetime DEFAULT NULL,
  `instante_recogida` datetime DEFAULT NULL,
  `instante_alta` datetime NOT NULL DEFAULT current_timestamp(),
  `instante_modif` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_recuento_doc` (`carpeta_cliente`,`codigo_emp`,`codigo_alm`,`serie`,`numero`),
  KEY `idx_recuento_alm` (`carpeta_cliente`,`codigo_alm`),
  KEY `idx_recuento_estado` (`carpeta_cliente`,`estado`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
