      ', ''-'', ''-'', COALESCE(MAX(CAST(SUBSTRING(TRIM(`',
      REPLACE(pColumna, '`', '``'), '`), 3, 10) AS UNSIGNED)), 0) + 1, ',
      '10, ''S'', ''S'', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, ',
