/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_spanish_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_ALB_CREAR_FACTURA_INICIO_OPCIONES`(
  IN p_NUMERO_ALB varchar(20), IN p_SERIE_ALB varchar(20),
  IN p_SERIE_FAC_NUEVA varchar(12), IN p_NUMERO_MANUAL varchar(20),
  IN p_FECHA date, IN p_FORMA_PAGO varchar(20),
  IN p_USUARIO varchar(100),
  OUT p_NUMERO_FAC varchar(20), OUT p_SERIE_FAC varchar(20))
BEGIN
  DECLARE v_EMPRESA varchar(10);
  DECLARE v_SERIE varchar(20);
  DECLARE v_NUMERO varchar(20);
  DECLARE v_DIGITOS int;
  SELECT CODIGO_EMP_ALB,
         COALESCE(NULLIF(TRIM(p_SERIE_FAC_NUEVA), ''), SERIE_ALB)
    INTO v_EMPRESA, v_SERIE
    FROM fza_albaranes
   WHERE NUMERO_ALB = p_NUMERO_ALB
     AND SERIE_ALB = p_SERIE_ALB;
  IF v_SERIE IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'El albarán no existe';
  END IF;
  IF COALESCE(TRIM(p_NUMERO_MANUAL), '') = '' THEN
    CALL PRC_PRE_RESERVAR_NUMERO('FC', v_EMPRESA, v_SERIE, p_USUARIO,
      v_NUMERO);
  ELSE
    SET v_NUMERO = TRIM(p_NUMERO_MANUAL);
    SELECT MAX(NUM_DIGITOS_CON) INTO v_DIGITOS FROM fza_contadores
     WHERE TIPO_DOC_CON = 'FC' AND EMPRESA_CON IN (v_EMPRESA, '-')
       AND SERIE_CON = v_SERIE;
    IF v_NUMERO REGEXP '^[0-9]+$' AND
       COALESCE(v_DIGITOS, 6) > LENGTH(v_NUMERO) THEN
      SET v_NUMERO = LPAD(v_NUMERO, COALESCE(v_DIGITOS, 6), '0');
    END IF;
    IF EXISTS (SELECT 1 FROM fza_facturas
                WHERE SERIE_FAC = v_SERIE AND NUMERO_FAC = v_NUMERO) THEN
      SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'El número indicado ya existe en la serie';
    END IF;
  END IF;
  CALL PRC_ALB_PREPARAR_RECARGO(p_SERIE_ALB, p_NUMERO_ALB);
  INSERT INTO fza_facturas (
    CODIGO_CAJERO_FAC,
    NUMERO_FAC, SERIE_FAC, FECHA_FAC, FASE_FAC, TIPO_FAC,
    CODIGO_EMP_FAC, CODIGO_ALM_FAC,
    RAZON_SOCIAL_EMPRESA_FAC, NIF_EMPRESA_FAC,
    MOVIL_EMPRESA_FAC, EMAIL_EMPRESA_FAC,
    DIRECCION1_EMPRESA_FAC, DIRECCION2_EMPRESA_FAC,
    POBLACION_EMPRESA_FAC, PROVINCIA_EMPRESA_FAC,
    CODIGO_PAI_EMPRESA_FAC, NOMBRE_PAI_EMPRESA_FAC,
    CODIGO_POSTAL_EMPRESA_FAC, GRUPO_ZONA_IVA_EMPRESA_FAC,
    ESRETENCIONES_EMPRESA_FAC, ESRETENCIONES_CLIENTE_FAC,
    ESREGIMENESPECIALAGRICOLA_EMPRESA_FAC,
    ESREGIMENESPECIALAGRICOLA_CLIENTE_FAC,
    CODIGO_CLI_FAC, RAZON_SOCIAL_CLIENTE_FAC, NIF_CLIENTE_FAC,
    MOVIL_CLIENTE_FAC, EMAIL_CLIENTE_FAC,
    DIRECCION1_CLIENTE_FAC, DIRECCION2_CLIENTE_FAC,
    POBLACION_CLIENTE_FAC, PROVINCIA_CLIENTE_FAC,
    CODIGO_POSTAL_CLIENTE_FAC, CODIGO_PAI_CLIENTE_FAC,
    NOMBRE_PAI_CLIENTE_FAC, CODIGO_IVA_FAC,
    ESIVA_RECARGO_CLIENTE_FAC, ESIVA_EXENTO_CLIENTE_FAC,
    ESINTRACOMUNITARIO_CLIENTE_FAC,
    TARIFA_ARTICULO_CLIENTE_FAC, ESIMP_INCL_TARIFA_CLIENTE_FAC,
    ESAPLICA_RE_ZONA_IVA_FAC,
    PORCENTAJE_REN_FAC,
    TOTAL_REN_FAC,
    PORCENTAJE_RER_FAC,
    TOTAL_RER_FAC,
    PORCENTAJE_RES_FAC,
    TOTAL_RES_FAC,
    PORCENTAJE_REE_FAC,
    TOTAL_REE_FAC,
    TOTAL_BASEI_IVAN_FAC,
    TOTAL_BASEI_IVAR_FAC,
    TOTAL_BASEI_IVAS_FAC,
    TOTAL_BASEI_IVAE_FAC,
    PORCENTAJE_IVAN_FAC, PORCENTAJE_IVAR_FAC,
    PORCENTAJE_IVAS_FAC, PORCENTAJE_IVAE_FAC,
    PORCENTAJE_RETENCION_FAC, FORMA_PAGO_FAC, CONTADOR_LINEAS_FAC,
    INSTANTE_ALTA, USUARIO_ALTA, USUARIO_MODIF)
  SELECT NULLIF(TRIM(A.CODIGO_VENDEDOR_ALB), ''),
         v_NUMERO, v_SERIE, COALESCE(p_FECHA, CURRENT_DATE()),
         'BORRADOR', 'NORMAL',
         A.CODIGO_EMP_ALB, NULLIF(TRIM(A.CODIGO_ALM_ALB), ''),
         A.RAZON_SOCIAL_EMPRESA_ALB,
         A.NIF_EMPRESA_ALB, A.MOVIL_EMPRESA_ALB, A.EMAIL_EMPRESA_ALB,
         A.DIRECCION1_EMPRESA_ALB, A.DIRECCION2_EMPRESA_ALB,
         A.POBLACION_EMPRESA_ALB, A.PROVINCIA_EMPRESA_ALB,
         A.CODIGO_PAI_EMPRESA_ALB, A.NOMBRE_PAI_EMPRESA_ALB,
         A.CODIGO_POSTAL_EMPRESA_ALB, A.GRUPO_ZONA_IVA_EMPRESA_ALB,
         COALESCE(A.ESRETENCIONES_EMPRESA_ALB, 'N'),
         COALESCE(A.ESRETENCIONES_CLIENTE_ALB, 'N'),
         COALESCE(A.ESREGIMENESPECIALAGRICOLA_EMPRESA_ALB, 'N'),
         COALESCE(A.ESREGIMENESPECIALAGRICOLA_CLIENTE_ALB, 'N'),
         A.CODIGO_CLI_ALB, A.RAZON_SOCIAL_CLIENTE_ALB,
         A.NIF_CLIENTE_ALB, A.MOVIL_CLIENTE_ALB, A.EMAIL_CLIENTE_ALB,
         A.DIRECCION1_CLIENTE_ALB, A.DIRECCION2_CLIENTE_ALB,
         A.POBLACION_CLIENTE_ALB, A.PROVINCIA_CLIENTE_ALB,
         A.CODIGO_POSTAL_CLIENTE_ALB, A.CODIGO_PAI_CLIENTE_ALB,
         A.NOMBRE_PAI_CLIENTE_ALB, A.CODIGO_IVA_ALB,
         A.ESIVA_RECARGO_CLIENTE_ALB, A.ESIVA_EXENTO_CLIENTE_ALB,
         A.ESINTRACOMUNITARIO_CLIENTE_ALB,
         A.TARIFA_ARTICULO_CLIENTE_ALB,
         A.ESIMP_INCL_TARIFA_CLIENTE_ALB,
         A.ESAPLICA_RE_ZONA_IVA_ALB,
    A.PORCENTAJE_REN_ALB,
    A.TOTAL_REN_ALB,
    A.PORCENTAJE_RER_ALB,
    A.TOTAL_RER_ALB,
    A.PORCENTAJE_RES_ALB,
    A.TOTAL_RES_ALB,
    A.PORCENTAJE_REE_ALB,
    A.TOTAL_REE_ALB,
    A.TOTAL_BASEI_IVAN_ALB,
    A.TOTAL_BASEI_IVAR_ALB,
    A.TOTAL_BASEI_IVAS_ALB,
    A.TOTAL_BASEI_IVAE_ALB,
    A.PORCENTAJE_IVAN_ALB, A.PORCENTAJE_IVAR_ALB,
         A.PORCENTAJE_IVAS_ALB, A.PORCENTAJE_IVAE_ALB,
         A.PORCENTAJE_RETENCION_ALB,
         COALESCE(NULLIF(TRIM(p_FORMA_PAGO), ''), A.FORMA_PAGO_ALB), '0',
         NOW(), p_USUARIO, p_USUARIO
    FROM fza_albaranes A
   WHERE A.NUMERO_ALB = p_NUMERO_ALB
     AND A.SERIE_ALB = p_SERIE_ALB;
  SET p_NUMERO_FAC = v_NUMERO;
  SET p_SERIE_FAC = v_SERIE;
END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
