/*!50003 DROP PROCEDURE IF EXISTS `PRC_ALB_CREAR_FACTURA_LINEA` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_spanish_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_ALB_CREAR_FACTURA_LINEA`(
  IN p_NUMERO_FAC varchar(20),
  IN p_SERIE_FAC varchar(20),
  IN p_NUMERO_ALB varchar(20),
  IN p_SERIE_ALB varchar(20),
  IN p_LINEA_ALB varchar(4),
  IN p_USUARIO varchar(100))
PRC: BEGIN
  DECLARE v_linea_fac varchar(4);
  DECLARE v_contador_fac int DEFAULT 0;
  DECLARE v_facturada varchar(1);
  SELECT IFNULL(`ESFACTURADA_ALBLIN`, 'N')
    INTO v_facturada
    FROM `fza_albaranes_lineas`
   WHERE `NUMERO_ALB_ALBLIN` = p_NUMERO_ALB
     AND `SERIE_ALB_ALBLIN` = p_SERIE_ALB
     AND `LINEA_ALBLIN` = p_LINEA_ALB;
  IF v_facturada = 'S' THEN
    LEAVE PRC;
  END IF;
  SELECT IFNULL(CAST(NULLIF(`CONTADOR_LINEAS_FAC`, '') AS UNSIGNED), 0) + 10
    INTO v_contador_fac
    FROM `fza_facturas`
   WHERE `NUMERO_FAC` = p_NUMERO_FAC
     AND `SERIE_FAC` = p_SERIE_FAC
   FOR UPDATE;
  IF v_contador_fac = 0 THEN
    LEAVE PRC;
  END IF;
  UPDATE `fza_facturas`
     SET `CONTADOR_LINEAS_FAC` = LPAD(v_contador_fac, 8, '0')
   WHERE `NUMERO_FAC` = p_NUMERO_FAC
     AND `SERIE_FAC` = p_SERIE_FAC;
  IF ROW_COUNT() = 0 THEN
    LEAVE PRC;
  END IF;
  SET v_linea_fac = LPAD(v_contador_fac, 4, '0');
  INSERT INTO `fza_facturas_lineas` (
    `NUMERO_FAC_FACLIN`, `SERIE_FAC_FACLIN`, `LINEA_FACLIN`,
    `CODIGO_ART_FACLIN`, `CODIGO_UNIDAD_FACLIN`,
    `LOTE_FACLIN`, `FECHA_CADUCIDAD_FACLIN`,
    `CODIGO_FAM_FACLIN`, `NOMBRE_FAM_FACLIN`,
    `DESCRIPCION_ARTICULO_FACLIN`, `DESCRIPCION_VARIACION_FACLIN`,
    `TIPO_ARTICULO_FACLIN`, `TIPO_CANTIDAD_ARTICULO_FACLIN`,
    `CANTIDAD_FACLIN`,
    `CODIGO_TAR_FACLIN`, `ESIMP_INCL_TARIFA_FACLIN`,
    `PRECIO_SALIDA_FACLIN`,
    `TIPO_IVA_ARTICULO_FACLIN`, `PORCENTAJE_IVA_FACLIN`,
    `PRECIO_VENTA_SIVA_ARTICULO_FACLIN`,
    `PRECIO_VENTA_CIVA_ARTICULO_FACLIN`,
    `TOTAL_FACLIN`, `CODIGO_ALM_FACLIN`,
    `CODIGO_VENDEDOR_FACLIN`,
    `INSTANTE_ALTA`, `USUARIO_ALTA`, `USUARIO_MODIF`)
  SELECT p_NUMERO_FAC, p_SERIE_FAC, v_linea_fac,
         AL.`CODIGO_ART_ALBLIN`, AL.`CODIGO_UNIDAD_ALBLIN`,
         AL.`LOTE_ALBLIN`, AL.`FECHA_CADUCIDAD_ALBLIN`,
         AL.`CODIGO_FAM_ALBLIN`, AL.`NOMBRE_FAM_ALBLIN`,
         AL.`DESCRIPCION_ARTICULO_ALBLIN`,
         AL.`DESCRIPCION_VARIACION_ALBLIN`,
         COALESCE(NULLIF(TRIM(A.`TIPO_ART`), ''), 'ESTANDAR'),
         AL.`TIPO_CANTIDAD_ARTICULO_ALBLIN`, AL.`CANTIDAD_ALBLIN`,
         AL.`CODIGO_TAR_ALBLIN`, AL.`ESIMP_INCL_TARIFA_ALBLIN`,
         
         
         
         CASE WHEN AL.`ESIMP_INCL_TARIFA_ALBLIN` = 'S'
              THEN AL.`PRECIO_VENTA_CIVA_ARTICULO_ALBLIN`
              ELSE AL.`PRECIO_VENTA_SIVA_ARTICULO_ALBLIN` END,
         AL.`TIPO_IVA_ARTICULO_ALBLIN`, AL.`PORCENTAJE_IVA_ALBLIN`,
         AL.`PRECIO_VENTA_SIVA_ARTICULO_ALBLIN`,
         AL.`PRECIO_VENTA_CIVA_ARTICULO_ALBLIN`, AL.`TOTAL_ALBLIN`,
         AL.`CODIGO_ALMACEN_ALBLIN`,
         (SELECT NULLIF(TRIM(AB.`CODIGO_VENDEDOR_ALB`), '')
            FROM `fza_albaranes` AB
           WHERE AB.`NUMERO_ALB` = p_NUMERO_ALB
             AND AB.`SERIE_ALB` = p_SERIE_ALB),
         NOW(), p_USUARIO, p_USUARIO
    FROM `fza_albaranes_lineas` AL
    LEFT JOIN `fza_articulos` A
      ON A.`CODIGO_ART_ART` = AL.`CODIGO_ART_ALBLIN`
   WHERE AL.`NUMERO_ALB_ALBLIN` = p_NUMERO_ALB
     AND AL.`SERIE_ALB_ALBLIN` = p_SERIE_ALB
     AND AL.`LINEA_ALBLIN` = p_LINEA_ALB;
  UPDATE `fza_albaranes_lineas`
     SET `ESFACTURADA_ALBLIN` = 'S',
         `NUMERO_FAC_ALBLIN` = p_NUMERO_FAC,
         `SERIE_FAC_ALBLIN` = p_SERIE_FAC,
         `LINEA_FAC_ALBLIN` = v_linea_fac,
         `INSTANTE_MODIF` = NOW(),
         `USUARIO_MODIF` = p_USUARIO
   WHERE `NUMERO_ALB_ALBLIN` = p_NUMERO_ALB
     AND `SERIE_ALB_ALBLIN` = p_SERIE_ALB
     AND `LINEA_ALBLIN` = p_LINEA_ALB;
END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_VALUE_ON_ZERO' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `PRC_ALB_PREPARAR_RECARGO` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_spanish_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_ALB_PREPARAR_RECARGO`(
  IN p_SERIE varchar(20), IN p_NUMERO varchar(20))
BEGIN
  UPDATE fza_albaranes D
  LEFT JOIN fza_ivas I ON I.CODIGO_IVA = D.CODIGO_IVA_ALB
  LEFT JOIN fza_ivas_grupos G ON G.IVA_IVAGRP = I.IVA_IVAGRP
     SET D.ESAPLICA_RE_ZONA_IVA_ALB = COALESCE(
      D.ESAPLICA_RE_ZONA_IVA_ALB, G.ESAPLICA_RE_IVA_IVAGRP, 'S'),
         D.PORCENTAJE_REN_ALB = COALESCE(
      D.PORCENTAJE_REN_ALB, I.PORCENTAJE_NORMAL_RE_IVA, 0),
         D.PORCENTAJE_RER_ALB = COALESCE(
      D.PORCENTAJE_RER_ALB, I.PORCENTAJE_REDUCIDO_RE_IVA, 0),
         D.PORCENTAJE_RES_ALB = COALESCE(
      D.PORCENTAJE_RES_ALB, I.PORCENTAJE_SUPERREDUCIDO_RE_IVA, 0),
         D.PORCENTAJE_REE_ALB = COALESCE(
      D.PORCENTAJE_REE_ALB, I.PORCENTAJE_EXENTO_RE_IVA, 0)
   WHERE D.SERIE_ALB = p_SERIE AND D.NUMERO_ALB = p_NUMERO;
END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_VALUE_ON_ZERO' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `PRC_ALB_TOTALES_RECARGO` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_spanish_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_ALB_TOTALES_RECARGO`(
  IN p_SERIE varchar(20), IN p_NUMERO varchar(20))
BEGIN
  
  
  
  
  
  UPDATE fza_albaranes D
  CROSS JOIN (
    SELECT
           COALESCE(SUM(IF(X.TIPO = 'N', X.BASE_LIN, 0)), 0)
             AS BASE_N,
           COALESCE(SUM(IF(X.TIPO = 'N' AND X.INCLUIDO <> 'S',
             X.IVA_LIN, 0)), 0) AS IVASIN_N,
           COALESCE(SUM(IF(X.TIPO = 'N' AND X.INCLUIDO = 'S',
             X.TOTAL_LIN - X.BASE_LIN, 0)), 0) AS IVAINC_N,
           COALESCE(SUM(IF(X.TIPO = 'R', X.BASE_LIN, 0)), 0)
             AS BASE_R,
           COALESCE(SUM(IF(X.TIPO = 'R' AND X.INCLUIDO <> 'S',
             X.IVA_LIN, 0)), 0) AS IVASIN_R,
           COALESCE(SUM(IF(X.TIPO = 'R' AND X.INCLUIDO = 'S',
             X.TOTAL_LIN - X.BASE_LIN, 0)), 0) AS IVAINC_R,
           COALESCE(SUM(IF(X.TIPO = 'S', X.BASE_LIN, 0)), 0)
             AS BASE_S,
           COALESCE(SUM(IF(X.TIPO = 'S' AND X.INCLUIDO <> 'S',
             X.IVA_LIN, 0)), 0) AS IVASIN_S,
           COALESCE(SUM(IF(X.TIPO = 'S' AND X.INCLUIDO = 'S',
             X.TOTAL_LIN - X.BASE_LIN, 0)), 0) AS IVAINC_S,
           COALESCE(SUM(IF(X.TIPO = 'E', X.BASE_LIN, 0)), 0)
             AS BASE_E,
           COALESCE(SUM(IF(X.TIPO = 'E' AND X.INCLUIDO <> 'S',
             X.IVA_LIN, 0)), 0) AS IVASIN_E,
           COALESCE(SUM(IF(X.TIPO = 'E' AND X.INCLUIDO = 'S',
             X.TOTAL_LIN - X.BASE_LIN, 0)), 0) AS IVAINC_E
      FROM (SELECT
          ROUND(CAST(COALESCE(L.CANTIDAD_ALBLIN, 0) *
            COALESCE(L.PRECIO_VENTA_SIVA_ARTICULO_ALBLIN, 0) AS DECIMAL(24,8)), 2) AS BASE_LIN,
          IF((COALESCE(D.ESIVA_EXENTO_CLIENTE_ALB, 'N') = 'S'
            OR COALESCE(D.ESINTRACOMUNITARIO_CLIENTE_ALB, 'N') = 'S'), 0,
            ROUND(CAST(COALESCE(L.CANTIDAD_ALBLIN, 0) *
              COALESCE(L.PRECIO_VENTA_CIVA_ARTICULO_ALBLIN, 0) AS DECIMAL(24,8)), 2)) AS TOTAL_LIN,
          IF((COALESCE(D.ESIVA_EXENTO_CLIENTE_ALB, 'N') = 'S'
            OR COALESCE(D.ESINTRACOMUNITARIO_CLIENTE_ALB, 'N') = 'S'), 0,
            COALESCE(L.CANTIDAD_ALBLIN, 0) *
            (COALESCE(L.PRECIO_VENTA_CIVA_ARTICULO_ALBLIN, 0) -
             COALESCE(L.PRECIO_VENTA_SIVA_ARTICULO_ALBLIN, 0))) AS IVA_LIN,
          IF((COALESCE(D.ESIVA_EXENTO_CLIENTE_ALB, 'N') = 'S'
            OR COALESCE(D.ESINTRACOMUNITARIO_CLIENTE_ALB, 'N') = 'S'), 'N',
            UPPER(COALESCE(L.ESIMP_INCL_TARIFA_ALBLIN, 'N'))) AS INCLUIDO,
          CASE WHEN (COALESCE(D.ESIVA_EXENTO_CLIENTE_ALB, 'N') = 'S'
            OR COALESCE(D.ESINTRACOMUNITARIO_CLIENTE_ALB, 'N') = 'S') THEN 'E'
          WHEN UPPER(TRIM(L.TIPO_IVA_ARTICULO_ALBLIN)) IN ('R', 'S', 'E')
            THEN UPPER(TRIM(L.TIPO_IVA_ARTICULO_ALBLIN))
          ELSE 'N' END AS TIPO
        FROM fza_albaranes_lineas L
        JOIN fza_albaranes D ON D.SERIE_ALB = L.SERIE_ALB_ALBLIN
         AND D.NUMERO_ALB = L.NUMERO_ALB_ALBLIN
        WHERE D.SERIE_ALB = p_SERIE AND D.NUMERO_ALB = p_NUMERO) X
  ) B
     SET
         D.TOTAL_BASEI_IVAN_ALB = B.BASE_N,
         D.TOTAL_IVAN_ALB = ROUND(CAST(B.IVASIN_N AS DECIMAL(24,8)), 2) + B.IVAINC_N,
         D.TOTAL_REN_ALB = IF(D.ESIVA_RECARGO_CLIENTE_ALB = 'S'
          AND COALESCE(D.ESAPLICA_RE_ZONA_IVA_ALB, 'S') <> 'N'
          AND COALESCE(D.ESIVA_EXENTO_CLIENTE_ALB, 'N') <> 'S'
          AND COALESCE(D.ESINTRACOMUNITARIO_CLIENTE_ALB, 'N') <> 'S',
          ROUND(CAST(B.BASE_N *
            COALESCE(D.PORCENTAJE_REN_ALB, 0) / 100 AS DECIMAL(24,8)), 2), 0),
         D.TOTAL_BASEI_IVAR_ALB = B.BASE_R,
         D.TOTAL_IVAR_ALB = ROUND(CAST(B.IVASIN_R AS DECIMAL(24,8)), 2) + B.IVAINC_R,
         D.TOTAL_RER_ALB = IF(D.ESIVA_RECARGO_CLIENTE_ALB = 'S'
          AND COALESCE(D.ESAPLICA_RE_ZONA_IVA_ALB, 'S') <> 'N'
          AND COALESCE(D.ESIVA_EXENTO_CLIENTE_ALB, 'N') <> 'S'
          AND COALESCE(D.ESINTRACOMUNITARIO_CLIENTE_ALB, 'N') <> 'S',
          ROUND(CAST(B.BASE_R *
            COALESCE(D.PORCENTAJE_RER_ALB, 0) / 100 AS DECIMAL(24,8)), 2), 0),
         D.TOTAL_BASEI_IVAS_ALB = B.BASE_S,
         D.TOTAL_IVAS_ALB = ROUND(CAST(B.IVASIN_S AS DECIMAL(24,8)), 2) + B.IVAINC_S,
         D.TOTAL_RES_ALB = IF(D.ESIVA_RECARGO_CLIENTE_ALB = 'S'
          AND COALESCE(D.ESAPLICA_RE_ZONA_IVA_ALB, 'S') <> 'N'
          AND COALESCE(D.ESIVA_EXENTO_CLIENTE_ALB, 'N') <> 'S'
          AND COALESCE(D.ESINTRACOMUNITARIO_CLIENTE_ALB, 'N') <> 'S',
          ROUND(CAST(B.BASE_S *
            COALESCE(D.PORCENTAJE_RES_ALB, 0) / 100 AS DECIMAL(24,8)), 2), 0),
         D.TOTAL_BASEI_IVAE_ALB = B.BASE_E,
         D.TOTAL_IVAE_ALB = ROUND(CAST(B.IVASIN_E AS DECIMAL(24,8)), 2) + B.IVAINC_E,
         D.TOTAL_REE_ALB = IF(D.ESIVA_RECARGO_CLIENTE_ALB = 'S'
          AND COALESCE(D.ESAPLICA_RE_ZONA_IVA_ALB, 'S') <> 'N'
          AND COALESCE(D.ESIVA_EXENTO_CLIENTE_ALB, 'N') <> 'S'
          AND COALESCE(D.ESINTRACOMUNITARIO_CLIENTE_ALB, 'N') <> 'S',
          ROUND(CAST(B.BASE_E *
            COALESCE(D.PORCENTAJE_REE_ALB, 0) / 100 AS DECIMAL(24,8)), 2), 0)
   WHERE D.SERIE_ALB = p_SERIE AND D.NUMERO_ALB = p_NUMERO;
  UPDATE fza_albaranes
     SET TOTAL_BASES_ALB = COALESCE(TOTAL_BASEI_IVAN_ALB, 0) + COALESCE(TOTAL_BASEI_IVAR_ALB, 0) + COALESCE(TOTAL_BASEI_IVAS_ALB, 0) + COALESCE(TOTAL_BASEI_IVAE_ALB, 0),
         TOTAL_IMPUESTOS_ALB = COALESCE(TOTAL_IVAN_ALB, 0) +
           COALESCE(TOTAL_IVAR_ALB, 0) +
           COALESCE(TOTAL_IVAS_ALB, 0) +
           COALESCE(TOTAL_IVAE_ALB, 0) +
           COALESCE(TOTAL_REN_ALB, 0) +
           COALESCE(TOTAL_RER_ALB, 0) +
           COALESCE(TOTAL_RES_ALB, 0) +
           COALESCE(TOTAL_REE_ALB, 0)
   WHERE SERIE_ALB = p_SERIE AND NUMERO_ALB = p_NUMERO;
  UPDATE fza_albaranes
     SET TOTAL_RETENCION_ALB = ROUND(CAST((TOTAL_BASES_ALB) *
           COALESCE(PORCENTAJE_RETENCION_ALB, 0) / 100 AS DECIMAL(24,8)), 2)
   WHERE SERIE_ALB = p_SERIE AND NUMERO_ALB = p_NUMERO;
  UPDATE fza_albaranes
     SET TOTAL_LIQUIDO_ALB = TOTAL_BASES_ALB + TOTAL_IMPUESTOS_ALB -
           TOTAL_RETENCION_ALB
   WHERE SERIE_ALB = p_SERIE AND NUMERO_ALB = p_NUMERO;
END
;;
DELIMITER ;
