/*!50003 DROP PROCEDURE IF EXISTS `PRC_BALANCE_VALORAR_TALLAS` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_spanish_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_BALANCE_VALORAR_TALLAS`(
    IN p_POR_ALMACEN BOOLEAN)
BEGIN
    DROP TEMPORARY TABLE IF EXISTS `tmp_bat_cst`;
    CREATE TEMPORARY TABLE `tmp_bat_cst` AS
    SELECT sk.`CODIGO_ART`, sk.`CLAVE_FILA`, sk.`POSICION`,
           IF(p_POR_ALMACEN, st.`CODIGO_ALM_STK`, '') AS `CODIGO_ALM`,
           COALESCE(SUM(st.`VALOR_TOTAL_STK`) /
             NULLIF(SUM(st.`CANTIDAD_STK`), 0),
             MAX(st.`PRECIO_MEDIO_STK`)) AS `COSTE`
      FROM `fza_articulos_stockactual` st
      JOIN `tmp_bat_sku` sk
        ON sk.`CODIGO_UNIDAD` = st.`CODIGO_UNIDAD_STK`
     WHERE st.`CODIGO_ALM_STK` IN
           (SELECT `CODIGO_ALM` FROM `tmp_bat_alm`)
     GROUP BY sk.`CODIGO_ART`, sk.`CLAVE_FILA`, sk.`POSICION`,
              IF(p_POR_ALMACEN, st.`CODIGO_ALM_STK`, '');
    ALTER TABLE `tmp_bat_cst` ADD PRIMARY KEY
      (`CODIGO_ART`, `CODIGO_ALM`, `CLAVE_FILA`, `POSICION`);
    
    ALTER TABLE `tmp_bat_medidas` ADD COLUMN
      `IMPORTE_COSTE` DECIMAL(19,6) NOT NULL DEFAULT 0;
    UPDATE `tmp_bat_medidas` m
    LEFT JOIN `tmp_bat_cst` c
      ON c.`CODIGO_ART` = m.`CODIGO_ART`
     
     AND c.`CODIGO_ALM` = SUBSTRING_INDEX(m.`CODIGO_ALM`, CHAR(31 USING utf8mb4), 1)
     AND c.`CLAVE_FILA` = m.`CLAVE_FILA`
     AND c.`POSICION` = m.`POSICION`
    LEFT JOIN `tmp_bat_prov` pr ON pr.`CODIGO_ART` = m.`CODIGO_ART`
       SET m.`IMPORTE_COSTE` = m.`CANTIDAD` *
           COALESCE(c.`COSTE`, pr.`COSTE_PRV`, 0)
     WHERE m.`CODIGO_ART` IS NOT NULL;
END
;;
DELIMITER ;
