      START TRANSACTION;
    END IF;
    IF ((TRIM(pCODIGO_PROVEEDOR) <> '') AND (TRIM(pCODIGO_ARTICULO) <> '')) THEN
        IF ( EXISTS( SELECT *
                     FROM fza_articulos_proveedores
                     WHERE `CODIGO_PRV_AP` = pCODIGO_PROVEEDOR
