                USUARIO_MODIF                            = pUSUARIO,
                INSTANTE_MODIF                           = CURRENT_TIMESTAMP
            WHERE `CODIGO_PRV_AP` = pCODIGO_PROVEEDOR
              AND CODIGO_ART_AP = pCODIGO_ARTICULO;
