                INSTANTE_ALTA
            ) VALUES (
                pCODIGO_PROVEEDOR,
                pCODIGO_ARTICULO,
                pPRECIO_ULT_COMPRA,
                pESPROVEEDORPRINCIPAL,
                pUSUARIO,
                CURRENT_TIMESTAMP,
                pUSUARIO,
                CURRENT_TIMESTAMP
            );
        END IF;
    END IF;
    IF v_TRANSACCION_PROPIA = 'S' THEN
      COMMIT;
    END IF;
END
