CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_CREAR_ACTUALIZAR_KEY`(
    IN pUSUARIO       varchar(200),
    IN pKEY           varchar(100),
    IN pSUBKEY        varchar(100),
    IN pVALUE         varchar(200),
    IN pVALUE_TEXT    text,
    IN pUSUARIO_MODIF varchar(100)
)
BEGIN
    DECLARE v_TRANSACCION_PROPIA varchar(1) DEFAULT 'N';
    
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    kk: BEGIN
        IF v_TRANSACCION_PROPIA = 'S' THEN
          ROLLBACK;
        END IF;
        RESIGNAL;
    END kk;
    IF @@in_transaction = 0 THEN
      SET v_TRANSACCION_PROPIA = 'S';
      START TRANSACTION;
    END IF;
    IF ( EXISTS(
             SELECT 1
             FROM `fza_usuarios_perfiles`
             WHERE `USUARIO_GRUPO_USUPER` = pUSUARIO
               AND `KEY_USUPER`           = pKEY
               AND `SUBKEY_USUPER`        = pSUBKEY
        )) THEN
        UPDATE `fza_usuarios_perfiles`
        SET `VALUE_USUPER`      = pVALUE,
            `VALUE_TEXT_USUPER` = pVALUE_TEXT,
            `USUARIO_MODIF`        = pUSUARIO_MODIF
        WHERE `USUARIO_GRUPO_USUPER` = pUSUARIO
          AND `KEY_USUPER`           = pKEY
          AND `SUBKEY_USUPER`        = pSUBKEY;
    ELSE
        INSERT INTO fza_usuarios_perfiles (
            `USUARIO_GRUPO_USUPER`,
            `KEY_USUPER`,
            `SUBKEY_USUPER`,
            `VALUE_USUPER`,
            `VALUE_TEXT_USUPER`,
            `INSTANTE_ALTA`,
            `USUARIO_ALTA`,
            `USUARIO_MODIF`
        ) VALUES (
            pUSUARIO,
            pKEY,
            pSUBKEY,
            pVALUE,
            pVALUE_TEXT,
            CURRENT_TIMESTAMP,
            pUSUARIO_MODIF,
            pUSUARIO_MODIF
        );
    END IF;
    IF v_TRANSACCION_PROPIA = 'S' THEN
      COMMIT;
    END IF;
END
;;
