CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_CREAR_ACTUALIZAR_PROVEEDOR`(
    IN pCODIGO_PROVEEDOR      varchar(20),
    IN pRAZONSOCIAL_PROVEEDOR varchar(200),
    IN pUSUARIO               varchar(100)
)
BEGIN
    DECLARE v_TRANSACCION_PROPIA varchar(1) DEFAULT 'N';
    
    DECLARE pCONT BIGINT;
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    kk: BEGIN
        IF v_TRANSACCION_PROPIA = 'S' THEN
          ROLLBACK;
        END IF;
        RESIGNAL;
    END kk;
    IF @@in_transaction = 0 THEN
      SET v_TRANSACCION_PROPIA = 'S';
      START TRANSACTION;
    END IF;
    IF (TRIM(pCODIGO_PROVEEDOR) <> '') THEN
        IF ( EXISTS( SELECT *
                     FROM fza_proveedores
                     WHERE `CODIGO_PRV_PRV` = pCODIGO_PROVEEDOR) ) THEN
            UPDATE fza_proveedores
            SET
                RAZON_SOCIAL_PRV = pRAZONSOCIAL_PROVEEDOR,
                USUARIO_MODIF          = pUSUARIO,
                INSTANTE_MODIF         = CURRENT_TIMESTAMP
            WHERE CODIGO_PRV_PRV = pCODIGO_PROVEEDOR;
        ELSE
            CALL PRC_FNC_GET_NEXT_NRO_DOC('PO', pCONT);
            INSERT INTO fza_proveedores (
                CODIGO_PRV_PRV,
                ORDEN_PRV,
                RAZON_SOCIAL_PRV,
                USUARIO_MODIF,
                INSTANTE_MODIF,
                USUARIO_ALTA,
                INSTANTE_ALTA
            ) VALUES (
                pCODIGO_PROVEEDOR,
                pCONT,
                pRAZONSOCIAL_PROVEEDOR,
                pUSUARIO,
                CURRENT_TIMESTAMP,
                pUSUARIO,
                CURRENT_TIMESTAMP
            );
        END IF;
    END IF;
    IF v_TRANSACCION_PROPIA = 'S' THEN
      COMMIT;
    END IF;
END
;;
