CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_CREAR_FACTURA_ABONO`(
    IN pidseriefactura      varchar(200),
    IN pidnumfactura        varchar(200),
    IN pidseriefacturaabono varchar(200),
    IN pidcodigo_empresa    varchar(200),
    IN pfechafacturaabono   date,
    OUT pidnumfacturaabono  varchar(200),
    IN pUSUARIO             varchar(100)
)
BEGIN
    DECLARE v_TRANSACCION_PROPIA varchar(1) DEFAULT 'N';
    
    DECLARE contadorped varchar(200);
    DECLARE nOrigen int DEFAULT 0;
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        IF v_TRANSACCION_PROPIA = 'S' THEN
          ROLLBACK;
        END IF;
        RESIGNAL;
    END;
    SELECT COUNT(*)
      INTO nOrigen
      FROM fza_facturas
     WHERE SERIE_FAC = pidseriefactura
       AND NUMERO_FAC = pidnumfactura;
    IF nOrigen = 0 THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'La factura de origen no existe';
    END IF;
    IF @@in_transaction = 0 THEN
      SET v_TRANSACCION_PROPIA = 'S';
      START TRANSACTION;
    END IF;
    CALL PRC_GET_NEXT_CONT_FACT_SERIE(pidseriefacturaabono,
                                      'FC',
                                      pidcodigo_empresa,
