        `DESCRIPCION_VARIACION_FACLIN`,
        `CODIGO_TAR_FACLIN`,
        `ESIMP_INCL_TARIFA_FACLIN`,
        `PRECIO_SALIDA_FACLIN`,
        `PORCENTAJE_DTO_FACLIN`,
        `PRECIO_DTO_FACLIN`,
        `PRECIO_VENTA_SIVA_ARTICULO_FACLIN`,
        `TIPO_IVA_ARTICULO_FACLIN`,
        `PORCENTAJE_IVA_FACLIN`,
        `PRECIO_VENTA_CIVA_ARTICULO_FACLIN`,
        `CODIGO_VENDEDOR_FACLIN`,
        `CODIGO_ALM_FACLIN`,
        `CODIGO_CAJA_FACLIN`,
        `ATTR1_VALOR_FACLIN`,
        `ATTR1_NOMBRE_FACLIN`,
        `ATTR2_VALOR_FACLIN`,
        `ATTR2_NOMBRE_FACLIN`,
        `ATTR3_VALOR_FACLIN`,
        `ATTR3_NOMBRE_FACLIN`,
        `ATTR4_VALOR_FACLIN`,
        `ATTR4_NOMBRE_FACLIN`,
        `ATTR5_VALOR_FACLIN`,
        `ATTR5_NOMBRE_FACLIN`,
        `NUM_ATRIBUTOS_FACLIN`,
        -`CANTIDAD_FACLIN`,
        -`TOTAL_FACLIN`,
        -`TOTAL_FAC_SIVA_FACLIN`,
        CURRENT_TIMESTAMP,
        CURRENT_TIMESTAMP,
        pUSUARIO,
        pUSUARIO
    FROM fza_facturas_lineas
    WHERE SERIE_FAC_FACLIN = pidseriefactura
      AND NUMERO_FAC_FACLIN = pidnumfactura
    ORDER BY LINEA_FACLIN;
    IF v_TRANSACCION_PROPIA = 'S' THEN
      COMMIT;
    END IF;
END
;;
