        `ESIVA_EXENTO_CLIENTE_FAC`,
        `ESREGIMENESPECIALAGRICOLA_CLIENTE_FAC`,
        `ESRETENCIONES_CLIENTE_FAC`,
        `TARIFA_ARTICULO_CLIENTE_FAC`,
        `ESIMP_INCL_TARIFA_CLIENTE_FAC`,
        `ESINTRACOMUNITARIO_CLIENTE_FAC`,
        `TIPO_OPER_VFACTU_FAC`,
        `ESIRPF_IMP_INCL_ZONA_IVA_FAC`,
        `ESAPLICA_RE_ZONA_IVA_FAC`,
        `ESIVAAGRICOLA_ZONA_IVA_FAC`,
        `PALABRA_REPORTS_ZONA_IVA_FAC`,
        `ESVENTA_ACTIVO_FIJO_FAC`,
        `PORCENTAJE_IVAN_FAC`,
        `PORCENTAJE_REN_FAC`,
        `PORCENTAJE_IVAR_FAC`,
        `PORCENTAJE_RER_FAC`,
        `PORCENTAJE_IVAS_FAC`,
        `PORCENTAJE_RES_FAC`,
        `PORCENTAJE_IVAE_FAC`,
        `PORCENTAJE_REE_FAC`,
        `FORMA_PAGO_FAC`,
        `PORCENTAJE_RETENCION_FAC`,
        `TEXTO_LEGAL_CLIENTE_FAC`,
        `TEXTO_LEGAL_EMPRESA_FAC`,
        `COMENTARIOS_FAC`,
        `CONTADOR_LINEAS_FAC`,
        `ESCREARARTICULOS_FAC`,
        `ESDESCRIPCIONES_AMP_FAC`,
        `ESFECHADEENTREGA_FAC`,
        `CODIGO_ALM_FAC`,
        `CODIGO_CAJA_FAC`,
        `TOTAL_IVAN_FAC`,
