        `TOTAL_IMPUESTOS_FAC`,
        `TOTAL_RETENCION_FAC`,
        `TOTAL_LIQUIDO_FAC`,
        `INSTANTE_MODIF`,
        `INSTANTE_ALTA`,
        `USUARIO_ALTA`,
        `USUARIO_MODIF`
    )
    SELECT
        contadorped,
