        `ESREGIMENESPECIALAGRICOLA_EMPRESA_FAC`,
        `CODIGO_CLI_FAC`,
        `RAZON_SOCIAL_CLIENTE_FAC`,
        `NIF_CLIENTE_FAC`,
        `MOVIL_CLIENTE_FAC`,
        `EMAIL_CLIENTE_FAC`,
        `DIRECCION1_CLIENTE_FAC`,
        `DIRECCION2_CLIENTE_FAC`,
        `POBLACION_CLIENTE_FAC`,
        `PROVINCIA_CLIENTE_FAC`,
        `CODIGO_POSTAL_CLIENTE_FAC`,
        `CODIGO_PAI_CLIENTE_FAC`,
        `NOMBRE_PAI_CLIENTE_FAC`,
        `NOMBRE_PERSONA_CLIENTE_FAC`,
        `APELLIDOS_PERSONA_CLIENTE_FAC`,
        `CODIGO_OFICINA_CONTABLE_FAC`,
        `CODIGO_ORGANO_GESTOR_FAC`,
        `CODIGO_UNIDAD_TRAMITADORA_FAC`,
        `CODIGO_IVA_FAC`,
        `ESIVA_RECARGO_CLIENTE_FAC`,
        `ESIVA_EXENTO_CLIENTE_FAC`,
        `ESREGIMENESPECIALAGRICOLA_CLIENTE_FAC`,
