        `ESVENTA_ACTIVO_FIJO_FAC`,
        `PORCENTAJE_IVAN_FAC`,
        `PORCENTAJE_REN_FAC`,
        `PORCENTAJE_IVAR_FAC`,
        `PORCENTAJE_RER_FAC`,
        `PORCENTAJE_IVAS_FAC`,
        `PORCENTAJE_RES_FAC`,
        `PORCENTAJE_IVAE_FAC`,
        `PORCENTAJE_REE_FAC`,
        `FORMA_PAGO_FAC`,
        `PORCENTAJE_RETENCION_FAC`,
        `TEXTO_LEGAL_CLIENTE_FAC`,
        `TEXTO_LEGAL_EMPRESA_FAC`,
        `COMENTARIOS_FAC`,
        `CONTADOR_LINEAS_FAC`,
        `ESCREARARTICULOS_FAC`,
        'N',
        'N',
        `CODIGO_ALM_FAC`,
        `CODIGO_CAJA_FAC`,
        `TOTAL_IVAN_FAC`,
        `TOTAL_REN_FAC`,
        `TOTAL_BASEI_IVAN_FAC`,
        `TOTAL_IVAR_FAC`,
        `TOTAL_RER_FAC`,
        `TOTAL_BASEI_IVAR_FAC`,
        `TOTAL_IVAS_FAC`,
        `TOTAL_RES_FAC`,
        `TOTAL_BASEI_IVAS_FAC`,
        `TOTAL_IVAE_FAC`,
        `TOTAL_REE_FAC`,
        `TOTAL_BASEI_IVAE_FAC`,
        `TOTAL_BASES_FAC`,
        `TOTAL_IMPUESTOS_FAC`,
        `TOTAL_RETENCION_FAC`,
        `TOTAL_LIQUIDO_FAC`,
        CURRENT_TIMESTAMP,
        CURRENT_TIMESTAMP,
        pUSUARIO,
        pUSUARIO
    FROM fza_facturas
    WHERE SERIE_FAC = pidseriefactura
      AND NUMERO_FAC = pidnumfactura;
    
    
    
    INSERT INTO fza_facturas_lineas (
        `NUMERO_FAC_FACLIN`,
        `SERIE_FAC_FACLIN`,
        `CODIGO_EMP_FACLIN`,
