        `ATTR3_NOMBRE_FACLIN`,
        `ATTR4_VALOR_FACLIN`,
        `ATTR4_NOMBRE_FACLIN`,
        `ATTR5_VALOR_FACLIN`,
        `ATTR5_NOMBRE_FACLIN`,
        `NUM_ATRIBUTOS_FACLIN`,
        `CANTIDAD_FACLIN`,
        `TOTAL_FACLIN`,
        `TOTAL_FAC_SIVA_FACLIN`,
        CURRENT_TIMESTAMP,
        CURRENT_TIMESTAMP,
        pUSUARIO,
