/*!50003 DROP PROCEDURE IF EXISTS `PRC_FAC_TOTALES_RECARGO` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_spanish_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_FAC_TOTALES_RECARGO`(
  IN p_SERIE varchar(20), IN p_NUMERO varchar(20))
BEGIN
  
  
  
  
  
  UPDATE fza_facturas D
  CROSS JOIN (
    SELECT
           COALESCE(SUM(IF(X.TIPO = 'N', X.BASE_LIN, 0)), 0)
             AS BASE_N,
           COALESCE(SUM(IF(X.TIPO = 'N' AND X.INCLUIDO <> 'S',
             X.IVA_LIN, 0)), 0) AS IVASIN_N,
           COALESCE(SUM(IF(X.TIPO = 'N' AND X.INCLUIDO = 'S',
             X.TOTAL_LIN - X.BASE_LIN, 0)), 0) AS IVAINC_N,
           COALESCE(SUM(IF(X.TIPO = 'R', X.BASE_LIN, 0)), 0)
             AS BASE_R,
           COALESCE(SUM(IF(X.TIPO = 'R' AND X.INCLUIDO <> 'S',
             X.IVA_LIN, 0)), 0) AS IVASIN_R,
           COALESCE(SUM(IF(X.TIPO = 'R' AND X.INCLUIDO = 'S',
             X.TOTAL_LIN - X.BASE_LIN, 0)), 0) AS IVAINC_R,
           COALESCE(SUM(IF(X.TIPO = 'S', X.BASE_LIN, 0)), 0)
             AS BASE_S,
           COALESCE(SUM(IF(X.TIPO = 'S' AND X.INCLUIDO <> 'S',
             X.IVA_LIN, 0)), 0) AS IVASIN_S,
           COALESCE(SUM(IF(X.TIPO = 'S' AND X.INCLUIDO = 'S',
             X.TOTAL_LIN - X.BASE_LIN, 0)), 0) AS IVAINC_S,
           COALESCE(SUM(IF(X.TIPO = 'E', X.BASE_LIN, 0)), 0)
             AS BASE_E,
           COALESCE(SUM(IF(X.TIPO = 'E' AND X.INCLUIDO <> 'S',
             X.IVA_LIN, 0)), 0) AS IVASIN_E,
           COALESCE(SUM(IF(X.TIPO = 'E' AND X.INCLUIDO = 'S',
             X.TOTAL_LIN - X.BASE_LIN, 0)), 0) AS IVAINC_E
      FROM (SELECT
          ROUND(CAST(COALESCE(L.CANTIDAD_FACLIN, 0) *
            COALESCE(L.PRECIO_VENTA_SIVA_ARTICULO_FACLIN, 0) AS DECIMAL(24,8)), 2) AS BASE_LIN,
          IF((COALESCE(D.ESIVA_EXENTO_CLIENTE_FAC, 'N') = 'S'
            OR COALESCE(D.ESINTRACOMUNITARIO_CLIENTE_FAC, 'N') = 'S'), 0,
            ROUND(CAST(COALESCE(L.CANTIDAD_FACLIN, 0) *
              COALESCE(L.PRECIO_VENTA_CIVA_ARTICULO_FACLIN, 0) AS DECIMAL(24,8)), 2)) AS TOTAL_LIN,
          IF((COALESCE(D.ESIVA_EXENTO_CLIENTE_FAC, 'N') = 'S'
            OR COALESCE(D.ESINTRACOMUNITARIO_CLIENTE_FAC, 'N') = 'S'), 0,
            COALESCE(L.CANTIDAD_FACLIN, 0) *
            (COALESCE(L.PRECIO_VENTA_CIVA_ARTICULO_FACLIN, 0) -
             COALESCE(L.PRECIO_VENTA_SIVA_ARTICULO_FACLIN, 0))) AS IVA_LIN,
          IF((COALESCE(D.ESIVA_EXENTO_CLIENTE_FAC, 'N') = 'S'
            OR COALESCE(D.ESINTRACOMUNITARIO_CLIENTE_FAC, 'N') = 'S'), 'N',
            UPPER(COALESCE(L.ESIMP_INCL_TARIFA_FACLIN, 'N'))) AS INCLUIDO,
          CASE WHEN (COALESCE(D.ESIVA_EXENTO_CLIENTE_FAC, 'N') = 'S'
            OR COALESCE(D.ESINTRACOMUNITARIO_CLIENTE_FAC, 'N') = 'S') THEN 'E'
          WHEN UPPER(TRIM(L.TIPO_IVA_ARTICULO_FACLIN)) IN ('R', 'S', 'E')
            THEN UPPER(TRIM(L.TIPO_IVA_ARTICULO_FACLIN))
          ELSE 'N' END AS TIPO
        FROM fza_facturas_lineas L
        JOIN fza_facturas D ON D.SERIE_FAC = L.SERIE_FAC_FACLIN
         AND D.NUMERO_FAC = L.NUMERO_FAC_FACLIN
        WHERE D.SERIE_FAC = p_SERIE AND D.NUMERO_FAC = p_NUMERO) X
  ) B
     SET
         D.TOTAL_BASEI_IVAN_FAC = B.BASE_N,
         D.TOTAL_IVAN_FAC = ROUND(CAST(B.IVASIN_N AS DECIMAL(24,8)), 2) + B.IVAINC_N,
         D.TOTAL_REN_FAC = IF(D.ESIVA_RECARGO_CLIENTE_FAC = 'S'
          AND COALESCE(D.ESAPLICA_RE_ZONA_IVA_FAC, 'S') <> 'N'
          AND COALESCE(D.ESIVA_EXENTO_CLIENTE_FAC, 'N') <> 'S'
          AND COALESCE(D.ESINTRACOMUNITARIO_CLIENTE_FAC, 'N') <> 'S',
          ROUND(CAST(B.BASE_N *
            COALESCE(D.PORCENTAJE_REN_FAC, 0) / 100 AS DECIMAL(24,8)), 2), 0),
         D.TOTAL_BASEI_IVAR_FAC = B.BASE_R,
         D.TOTAL_IVAR_FAC = ROUND(CAST(B.IVASIN_R AS DECIMAL(24,8)), 2) + B.IVAINC_R,
         D.TOTAL_RER_FAC = IF(D.ESIVA_RECARGO_CLIENTE_FAC = 'S'
          AND COALESCE(D.ESAPLICA_RE_ZONA_IVA_FAC, 'S') <> 'N'
          AND COALESCE(D.ESIVA_EXENTO_CLIENTE_FAC, 'N') <> 'S'
          AND COALESCE(D.ESINTRACOMUNITARIO_CLIENTE_FAC, 'N') <> 'S',
          ROUND(CAST(B.BASE_R *
            COALESCE(D.PORCENTAJE_RER_FAC, 0) / 100 AS DECIMAL(24,8)), 2), 0),
         D.TOTAL_BASEI_IVAS_FAC = B.BASE_S,
         D.TOTAL_IVAS_FAC = ROUND(CAST(B.IVASIN_S AS DECIMAL(24,8)), 2) + B.IVAINC_S,
         D.TOTAL_RES_FAC = IF(D.ESIVA_RECARGO_CLIENTE_FAC = 'S'
          AND COALESCE(D.ESAPLICA_RE_ZONA_IVA_FAC, 'S') <> 'N'
          AND COALESCE(D.ESIVA_EXENTO_CLIENTE_FAC, 'N') <> 'S'
          AND COALESCE(D.ESINTRACOMUNITARIO_CLIENTE_FAC, 'N') <> 'S',
          ROUND(CAST(B.BASE_S *
            COALESCE(D.PORCENTAJE_RES_FAC, 0) / 100 AS DECIMAL(24,8)), 2), 0),
         D.TOTAL_BASEI_IVAE_FAC = B.BASE_E,
         D.TOTAL_IVAE_FAC = ROUND(CAST(B.IVASIN_E AS DECIMAL(24,8)), 2) + B.IVAINC_E,
         D.TOTAL_REE_FAC = IF(D.ESIVA_RECARGO_CLIENTE_FAC = 'S'
          AND COALESCE(D.ESAPLICA_RE_ZONA_IVA_FAC, 'S') <> 'N'
          AND COALESCE(D.ESIVA_EXENTO_CLIENTE_FAC, 'N') <> 'S'
          AND COALESCE(D.ESINTRACOMUNITARIO_CLIENTE_FAC, 'N') <> 'S',
          ROUND(CAST(B.BASE_E *
            COALESCE(D.PORCENTAJE_REE_FAC, 0) / 100 AS DECIMAL(24,8)), 2), 0)
   WHERE D.SERIE_FAC = p_SERIE AND D.NUMERO_FAC = p_NUMERO;
  UPDATE fza_facturas
     SET TOTAL_BASES_FAC = COALESCE(TOTAL_BASEI_IVAN_FAC, 0) + COALESCE(TOTAL_BASEI_IVAR_FAC, 0) + COALESCE(TOTAL_BASEI_IVAS_FAC, 0) + COALESCE(TOTAL_BASEI_IVAE_FAC, 0),
         TOTAL_IMPUESTOS_FAC = COALESCE(TOTAL_IVAN_FAC, 0) +
           COALESCE(TOTAL_IVAR_FAC, 0) +
           COALESCE(TOTAL_IVAS_FAC, 0) +
           COALESCE(TOTAL_IVAE_FAC, 0) +
           COALESCE(TOTAL_REN_FAC, 0) +
           COALESCE(TOTAL_RER_FAC, 0) +
           COALESCE(TOTAL_RES_FAC, 0) +
           COALESCE(TOTAL_REE_FAC, 0)
   WHERE SERIE_FAC = p_SERIE AND NUMERO_FAC = p_NUMERO;
  UPDATE fza_facturas
     SET TOTAL_RETENCION_FAC = ROUND(CAST((TOTAL_BASES_FAC +
           IF(COALESCE(ESIRPF_IMP_INCL_ZONA_IVA_FAC, 'N') = 'S',
              TOTAL_IMPUESTOS_FAC, 0)) *
           COALESCE(PORCENTAJE_RETENCION_FAC, 0) / 100 AS DECIMAL(24,8)), 2)
   WHERE SERIE_FAC = p_SERIE AND NUMERO_FAC = p_NUMERO;
  UPDATE fza_facturas
     SET TOTAL_LIQUIDO_FAC = TOTAL_BASES_FAC + TOTAL_IMPUESTOS_FAC -
           TOTAL_RETENCION_FAC
   WHERE SERIE_FAC = p_SERIE AND NUMERO_FAC = p_NUMERO;
END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
