/*!50003 DROP PROCEDURE IF EXISTS `PRC_FNC_GET_NEXT_LINEA_FACTURA` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_spanish_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_FNC_GET_NEXT_LINEA_FACTURA`(
    IN  `pnumfac` VARCHAR(12),
    IN  `pserie`  VARCHAR(12),
    OUT `presul`  VARCHAR(3)
)
BEGIN
    DECLARE v_TRANSACCION_PROPIA varchar(1) DEFAULT 'N';
    
    DECLARE v_NextValue BIGINT;
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    kk: BEGIN
        IF v_TRANSACCION_PROPIA = 'S' THEN
          ROLLBACK;
        END IF;
        RESIGNAL;
    END kk;
    IF @@in_transaction = 0 THEN
      SET v_TRANSACCION_PROPIA = 'S';
      START TRANSACTION;
    END IF;
    UPDATE `fza_facturas`
    SET `CONTADOR_LINEAS_FAC` = LPAD(
        LAST_INSERT_ID(
            CASE
                WHEN `CONTADOR_LINEAS_FAC` IS NULL
                  OR `CONTADOR_LINEAS_FAC` = ''
                  OR `CONTADOR_LINEAS_FAC` = '0' THEN 20
                ELSE CAST(`CONTADOR_LINEAS_FAC` AS UNSIGNED) + 10
            END
        ), 3, '0'
    )
    WHERE `SERIE_FAC` = pserie
      AND `NUMERO_FAC`   = pnumfac;
    IF ROW_COUNT() > 0 THEN
        SET v_NextValue = LAST_INSERT_ID() - 10;
        SET `presul` = LPAD(v_NextValue, 3, '0');
    ELSE
        SET `presul` = '010';
    END IF;
    IF v_TRANSACCION_PROPIA = 'S' THEN
      COMMIT;
    END IF;
END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
