CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_FZA_FUSION_RECALCULAR_PMP`(
  IN p_EMPRESA varchar(20),
  IN p_ALMACEN varchar(10),
  IN p_SKU varchar(50)
)
BEGIN
  DECLARE v_FIN varchar(1) DEFAULT 'N';
  DECLARE v_TRANSACCION_PROPIA varchar(1) DEFAULT 'N';
  DECLARE v_SAVEPOINT_PROPIO varchar(1) DEFAULT 'N';
  DECLARE v_EMPRESA_AMBITO varchar(20);
  DECLARE v_ALMACEN_AMBITO varchar(10);
  DECLARE v_SKU_AMBITO varchar(50);
  DECLARE v_NUMERO_MOV varchar(20);
  DECLARE v_TIPO_MOV varchar(1);
  DECLARE v_ES_CIERRE_INVENTARIO varchar(1);
  DECLARE v_ES_PMP_MANUAL varchar(1);
  DECLARE v_CANTIDAD_MOV decimal(19,6);
  DECLARE v_COSTE_UNITARIO_MOV decimal(19,6);
  DECLARE v_STOCK decimal(38,6) DEFAULT 0;
  DECLARE v_PMP decimal(19,6) DEFAULT 0;
  DECLARE v_TOTAL_MOV decimal(38,6) DEFAULT 0;
  DECLARE v_CANTIDAD_STOCK decimal(38,6) DEFAULT 0;
  DECLARE v_VALOR_STOCK decimal(38,6) DEFAULT 0;
  DECLARE v_CANTIDAD_SEMILLA decimal(38,6) DEFAULT 0;
  DECLARE v_VALOR_SEMILLA decimal(38,6) DEFAULT 0;
  DECLARE v_AJUSTE_SIN_LOTE decimal(38,6) DEFAULT 0;
  DECLARE v_CON_LOTES varchar(1) DEFAULT 'N';
  DECLARE v_CANTIDAD_MOVIMIENTOS bigint DEFAULT 0;
  DECLARE v_CANTIDAD_FILAS_STOCK bigint DEFAULT 0;
  DECLARE v_CANTIDAD_ALMACENES bigint DEFAULT 0;
  DECLARE v_CANTIDAD_INCOHERENTES bigint DEFAULT 0;
  DECLARE v_EMPRESA_INCOHERENTE varchar(20);
  DECLARE v_ALMACEN_INCOHERENTE varchar(10);
  DECLARE v_MENSAJE varchar(128);
  DECLARE v_CAMBIOS bigint DEFAULT 1;
  DECLARE v_PASADA int DEFAULT 0;
  DECLARE cur_MOVIMIENTOS CURSOR FOR
    SELECT m.NUMERO_MOV,
           m.TIPO_MOV,
           IFNULL(m.CANTIDAD_MOV, 0),
           IFNULL(m.PRECIO_COSTE_UNITARIO_MOV, 0),
           IF(m.TIPO_DOC_MOV = 'IN' AND EXISTS(
                SELECT 1
                  FROM fza_inventarios i
                  JOIN fza_inventarios_lineas l
                    ON l.CODIGO_EMP_INVLIN = i.CODIGO_EMP_INV
                   AND l.CODIGO_ALM_INVLIN = i.CODIGO_ALM_INV
                   AND l.SERIE_INV_INVLIN = i.SERIE_INV
                   AND l.NUMERO_INV_INVLIN = i.NUMERO_INV
                 WHERE i.CODIGO_EMP_INV = m.CODIGO_EMP_MOV
                   AND i.CODIGO_ALM_INV = m.CODIGO_ALM_MOV
                   AND i.SERIE_INV = m.SERIE_DOC_MOV
                   AND i.NUMERO_INV = m.NUMERO_DOC_MOV
                   AND i.ESTADO_INV = 'APLICADO'
                   AND l.CODIGO_UNIDAD_INVLIN = m.CODIGO_UNIDAD_MOV
                   AND (l.LINEA_INVLIN = m.LINEA_MOV OR
                        (l.LINEA_INVLIN REGEXP '^[0-9]+$' AND
                         m.LINEA_MOV REGEXP '^[0-9]+$' AND
                         CAST(l.LINEA_INVLIN AS UNSIGNED) =
                           CAST(m.LINEA_MOV AS UNSIGNED)))), 'S', 'N'),
           IFNULL((
             SELECT MAX(l.ESPRECIO_MEDIO_CORREGIDO_INVLIN)
               FROM fza_inventarios i
               JOIN fza_inventarios_lineas l
                 ON l.CODIGO_EMP_INVLIN = i.CODIGO_EMP_INV
                AND l.CODIGO_ALM_INVLIN = i.CODIGO_ALM_INV
                AND l.SERIE_INV_INVLIN = i.SERIE_INV
                AND l.NUMERO_INV_INVLIN = i.NUMERO_INV
              WHERE m.TIPO_DOC_MOV = 'IN'
                AND i.CODIGO_EMP_INV = m.CODIGO_EMP_MOV
                AND i.CODIGO_ALM_INV = m.CODIGO_ALM_MOV
                AND i.SERIE_INV = m.SERIE_DOC_MOV
                AND i.NUMERO_INV = m.NUMERO_DOC_MOV
                AND i.ESTADO_INV = 'APLICADO'
                AND l.CODIGO_UNIDAD_INVLIN = m.CODIGO_UNIDAD_MOV
                AND (l.LINEA_INVLIN = m.LINEA_MOV OR
                     (l.LINEA_INVLIN REGEXP '^[0-9]+$' AND
                      m.LINEA_MOV REGEXP '^[0-9]+$' AND
                      CAST(l.LINEA_INVLIN AS UNSIGNED) =
                        CAST(m.LINEA_MOV AS UNSIGNED)))), 'N')
      FROM fza_movimientos_almacen m
     WHERE m.CODIGO_EMP_MOV = v_EMPRESA_AMBITO
       AND m.CODIGO_ALM_MOV = v_ALMACEN_AMBITO
       AND m.CODIGO_UNIDAD_MOV = v_SKU_AMBITO
       AND m.ESACTIVO_MOV = 'S'
     ORDER BY m.FECHA_MOV, m.INSTANTE_ALTA, m.NUMERO_MOV
       FOR UPDATE;
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_FIN = 'S';
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    DROP TEMPORARY TABLE IF EXISTS tmp_fza_fusion_traspasos;
    DROP TEMPORARY TABLE IF EXISTS tmp_fza_fusion_inventarios;
    DROP TEMPORARY TABLE IF EXISTS tmp_fza_fusion_ambitos;
    IF v_TRANSACCION_PROPIA = 'S' THEN
      ROLLBACK;
    ELSEIF v_SAVEPOINT_PROPIO = 'S' THEN
      ROLLBACK TO SAVEPOINT SP_FZA_FUSION_PMP;
      RELEASE SAVEPOINT SP_FZA_FUSION_PMP;
    END IF;
    RESIGNAL;
  END;
  IF @@in_transaction = 0 THEN
    START TRANSACTION;
    SET v_TRANSACCION_PROPIA = 'S';
  ELSE
    SAVEPOINT SP_FZA_FUSION_PMP;
    SET v_SAVEPOINT_PROPIO = 'S';
  END IF;
  IF IFNULL(p_EMPRESA, '') = '' OR IFNULL(p_ALMACEN, '') = '' OR
     IFNULL(p_SKU, '') = '' THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'Empresa, almacen y SKU son obligatorios';
  END IF;
  SELECT COUNT(*)
    INTO v_CANTIDAD_ALMACENES
    FROM fza_almacenes a
   WHERE a.CODIGO_ALM_ALM = p_ALMACEN
     AND a.CODIGO_EMP_ALM = p_EMPRESA
     FOR UPDATE;
  IF v_CANTIDAD_ALMACENES <> 1 THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'El almacen no pertenece a la empresa indicada';
  END IF;
  
  
  SELECT COUNT(*), MIN(m.CODIGO_EMP_MOV)
    INTO v_CANTIDAD_INCOHERENTES, v_EMPRESA_INCOHERENTE
    FROM fza_movimientos_almacen m
   WHERE m.CODIGO_ALM_MOV = p_ALMACEN
     AND m.CODIGO_UNIDAD_MOV = p_SKU
     AND m.CODIGO_EMP_MOV <> p_EMPRESA
     AND m.ESACTIVO_MOV = 'S'
     FOR UPDATE;
  IF v_CANTIDAD_INCOHERENTES > 0 THEN
    SET v_MENSAJE = LEFT(CONCAT('Almacen ', p_ALMACEN, ' (empresa ',
      p_EMPRESA, '): ', v_CANTIDAD_INCOHERENTES,
      ' movimientos de la empresa ', v_EMPRESA_INCOHERENTE,
      ' para el SKU ', p_SKU), 128);
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = v_MENSAJE;
  END IF;
  DROP TEMPORARY TABLE IF EXISTS tmp_fza_fusion_ambitos;
  CREATE TEMPORARY TABLE tmp_fza_fusion_ambitos (
    empresa varchar(20) NOT NULL,
    almacen varchar(10) NOT NULL,
    sku varchar(50) NOT NULL,
    cantidad_semilla decimal(38,6) NOT NULL DEFAULT 0,
    valor_semilla decimal(38,6) NOT NULL DEFAULT 0,
    procesado varchar(1) NOT NULL DEFAULT 'N',
    PRIMARY KEY (empresa, almacen, sku)
  ) ENGINE=InnoDB;
  INSERT IGNORE INTO tmp_fza_fusion_ambitos (empresa, almacen, sku)
  VALUES (p_EMPRESA, p_ALMACEN, p_SKU);
  DROP TEMPORARY TABLE IF EXISTS tmp_fza_fusion_traspasos;
  CREATE TEMPORARY TABLE tmp_fza_fusion_traspasos (
    numero_salida varchar(20) NOT NULL,
    numero_entrada varchar(20) NOT NULL,
    empresa_origen varchar(20) NOT NULL,
    almacen_origen varchar(10) NOT NULL,
    empresa_destino varchar(20) NOT NULL,
    almacen_destino varchar(10) NOT NULL,
    sku varchar(50) NOT NULL,
    cantidad_salida decimal(19,6) NOT NULL,
    cantidad_entrada decimal(19,6) NOT NULL,
    coste_salida decimal(19,6) NULL,
    PRIMARY KEY (numero_salida, numero_entrada)
  ) ENGINE=InnoDB;
  INSERT INTO tmp_fza_fusion_traspasos
    (numero_salida, numero_entrada, empresa_origen, almacen_origen,
     empresa_destino, almacen_destino, sku, cantidad_salida,
     cantidad_entrada, coste_salida)
  SELECT s.NUMERO_MOV,
         e.NUMERO_MOV,
         s.CODIGO_EMP_MOV,
         s.CODIGO_ALM_MOV,
         e.CODIGO_EMP_MOV,
         e.CODIGO_ALM_MOV,
         s.CODIGO_UNIDAD_MOV,
         IFNULL(s.CANTIDAD_MOV, 0),
         IFNULL(e.CANTIDAD_MOV, 0),
         IF(ABS(IFNULL(s.CANTIDAD_MOV, 0)) >= 0.0000005,
            CAST(IFNULL(s.TOTAL_COSTE_MOV, 0) /
                 s.CANTIDAD_MOV AS decimal(19,6)), NULL)
    FROM fza_movimientos_almacen s
    JOIN fza_movimientos_almacen e
      ON e.TIPO_DOC_MOV = s.TIPO_DOC_MOV
     AND e.SERIE_DOC_MOV = s.SERIE_DOC_MOV
     AND e.NUMERO_DOC_MOV = s.NUMERO_DOC_MOV
     AND e.CODIGO_UNIDAD_MOV = s.CODIGO_UNIDAD_MOV
     AND e.CODIGO_ALM_MOV = s.CODIGO_ALM_CONTRA_MOV
     AND e.CODIGO_ALM_CONTRA_MOV = s.CODIGO_ALM_MOV
     AND e.ESACTIVO_MOV = 'S'
     AND e.TIPO_MOV = 'E'
     AND (e.LINEA_MOV = s.LINEA_MOV OR
          (IFNULL(s.NUMERO_OPERACION_DOC_MOV, '') <> '' AND
           e.NUMERO_OPERACION_DOC_MOV = s.NUMERO_OPERACION_DOC_MOV AND
           NOT EXISTS(
             SELECT 1
               FROM fza_movimientos_almacen ex
              WHERE ex.TIPO_DOC_MOV = s.TIPO_DOC_MOV
                AND ex.SERIE_DOC_MOV = s.SERIE_DOC_MOV
                AND ex.NUMERO_DOC_MOV = s.NUMERO_DOC_MOV
                AND ex.CODIGO_UNIDAD_MOV = s.CODIGO_UNIDAD_MOV
                AND ex.CODIGO_ALM_MOV = s.CODIGO_ALM_CONTRA_MOV
                AND ex.CODIGO_ALM_CONTRA_MOV = s.CODIGO_ALM_MOV
                AND ex.ESACTIVO_MOV = 'S'
                AND ex.TIPO_MOV = 'E'
                AND ex.LINEA_MOV = s.LINEA_MOV)))
   WHERE s.CODIGO_UNIDAD_MOV = p_SKU
     AND s.ESACTIVO_MOV = 'S'
     AND s.TIPO_DOC_MOV IN ('TR', 'AT', 'TA')
     AND s.TIPO_MOV = 'S';
  SET v_CAMBIOS = 1;
  WHILE v_CAMBIOS > 0 DO
    SET v_CAMBIOS = 0;
    INSERT IGNORE INTO tmp_fza_fusion_ambitos (empresa, almacen, sku)
    SELECT t.empresa_destino, t.almacen_destino, t.sku
      FROM tmp_fza_fusion_traspasos t
      JOIN tmp_fza_fusion_ambitos q
        ON q.empresa = t.empresa_origen
       AND q.almacen = t.almacen_origen
       AND q.sku = t.sku
     GROUP BY t.empresa_destino, t.almacen_destino, t.sku;
    SET v_CAMBIOS = ROW_COUNT();
    INSERT IGNORE INTO tmp_fza_fusion_ambitos (empresa, almacen, sku)
    SELECT t.empresa_origen, t.almacen_origen, t.sku
      FROM tmp_fza_fusion_traspasos t
      JOIN tmp_fza_fusion_ambitos q
        ON q.empresa = t.empresa_destino
       AND q.almacen = t.almacen_destino
       AND q.sku = t.sku
     GROUP BY t.empresa_origen, t.almacen_origen, t.sku;
    SET v_CAMBIOS = v_CAMBIOS + ROW_COUNT();
  END WHILE;
  SELECT COUNT(*)
    INTO v_CANTIDAD_INCOHERENTES
    FROM tmp_fza_fusion_ambitos q
    LEFT JOIN fza_almacenes a
      ON a.CODIGO_ALM_ALM = q.almacen
     AND a.CODIGO_EMP_ALM = q.empresa
   WHERE a.CODIGO_ALM_ALM IS NULL
     FOR UPDATE;
  IF v_CANTIDAD_INCOHERENTES > 0 THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'Un almacen conectado no pertenece a su empresa';
  END IF;
  SELECT COUNT(*), MIN(q.almacen), MIN(m.CODIGO_EMP_MOV)
    INTO v_CANTIDAD_INCOHERENTES, v_ALMACEN_INCOHERENTE,
      v_EMPRESA_INCOHERENTE
    FROM tmp_fza_fusion_ambitos q
    JOIN fza_movimientos_almacen m
      ON m.CODIGO_ALM_MOV = q.almacen
     AND m.CODIGO_UNIDAD_MOV = q.sku
     AND m.CODIGO_EMP_MOV <> q.empresa
     AND m.ESACTIVO_MOV = 'S'
     FOR UPDATE;
  IF v_CANTIDAD_INCOHERENTES > 0 THEN
    SET v_MENSAJE = LEFT(CONCAT('Almacen conectado ', v_ALMACEN_INCOHERENTE,
      ': ', v_CANTIDAD_INCOHERENTES, ' movimientos de la empresa ',
      v_EMPRESA_INCOHERENTE, ' para el SKU ', p_SKU), 128);
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = v_MENSAJE;
  END IF;
  SELECT COUNT(*)
    INTO v_CANTIDAD_MOVIMIENTOS
    FROM tmp_fza_fusion_ambitos q
    JOIN fza_movimientos_almacen m
      ON m.CODIGO_EMP_MOV = q.empresa
     AND m.CODIGO_ALM_MOV = q.almacen
     AND m.CODIGO_UNIDAD_MOV = q.sku
     AND m.ESACTIVO_MOV = 'S'
     FOR UPDATE;
  SELECT COUNT(*)
    INTO v_CANTIDAD_FILAS_STOCK
    FROM tmp_fza_fusion_ambitos q
    JOIN fza_articulos_stockactual s
      ON s.CODIGO_ALM_STK = q.almacen
     AND s.CODIGO_UNIDAD_STK = q.sku
     FOR UPDATE;
  UPDATE tmp_fza_fusion_ambitos q
     SET q.cantidad_semilla = IF(EXISTS(
           SELECT 1
             FROM fza_articulos_stockactual sx
            WHERE sx.CODIGO_ALM_STK = q.almacen
              AND sx.CODIGO_UNIDAD_STK = q.sku),
           (SELECT IFNULL(SUM(IFNULL(s.CANTIDAD_STK, 0)), 0)
              FROM fza_articulos_stockactual s
             WHERE s.CODIGO_ALM_STK = q.almacen
               AND s.CODIGO_UNIDAD_STK = q.sku) -
           (SELECT IFNULL(SUM(CASE
                     WHEN m.TIPO_MOV = 'E' THEN IFNULL(m.CANTIDAD_MOV, 0)
                     WHEN m.TIPO_MOV = 'S' THEN -IFNULL(m.CANTIDAD_MOV, 0)
                     ELSE 0 END), 0)
              FROM fza_movimientos_almacen m
             WHERE m.CODIGO_EMP_MOV = q.empresa
               AND m.CODIGO_ALM_MOV = q.almacen
               AND m.CODIGO_UNIDAD_MOV = q.sku
               AND m.ESACTIVO_MOV = 'S'), 0),
         q.valor_semilla = IF(EXISTS(
           SELECT 1
             FROM fza_articulos_stockactual sx
            WHERE sx.CODIGO_ALM_STK = q.almacen
              AND sx.CODIGO_UNIDAD_STK = q.sku),
           (SELECT IFNULL(SUM(IFNULL(s.VALOR_TOTAL_STK, 0)), 0)
              FROM fza_articulos_stockactual s
             WHERE s.CODIGO_ALM_STK = q.almacen
               AND s.CODIGO_UNIDAD_STK = q.sku) -
           (SELECT IFNULL(SUM(CASE
                     WHEN m.TIPO_MOV = 'E' THEN
                       IFNULL(m.CANTIDAD_MOV, 0) *
                       IFNULL(m.PRECIO_COSTE_UNITARIO_MOV, 0)
                     WHEN m.TIPO_MOV = 'S' THEN
                       -IFNULL(m.CANTIDAD_MOV, 0) *
                       IFNULL(m.PRECIO_MEDIO_MOV, 0)
                     ELSE 0 END), 0)
              FROM fza_movimientos_almacen m
             WHERE m.CODIGO_EMP_MOV = q.empresa
               AND m.CODIGO_ALM_MOV = q.almacen
               AND m.CODIGO_UNIDAD_MOV = q.sku
               AND m.ESACTIVO_MOV = 'S'), 0);
  DROP TEMPORARY TABLE IF EXISTS tmp_fza_fusion_inventarios;
  CREATE TEMPORARY TABLE tmp_fza_fusion_inventarios (
    empresa varchar(20) NOT NULL,
    almacen varchar(10) NOT NULL,
    serie varchar(20) NOT NULL,
    numero varchar(20) NOT NULL,
    linea varchar(10) NOT NULL,
    numero_salida varchar(20) NOT NULL,
    numero_entrada varchar(20) NULL,
    cantidad_salidas int NOT NULL,
    cantidad_entradas int NOT NULL,
    PRIMARY KEY (empresa, almacen, serie, numero, linea)
  ) ENGINE=InnoDB;
  SET v_CAMBIOS = 1;
  SET v_PASADA = 0;
  bucle_PROPAGACION: WHILE v_CAMBIOS > 0 DO
    IF v_PASADA >= 100 THEN
      SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'No converge la propagacion de traspasos fusionados';
    END IF;
    SET v_PASADA = v_PASADA + 1;
    UPDATE tmp_fza_fusion_ambitos SET procesado = 'N';
    bucle_AMBITOS: WHILE EXISTS(
      SELECT 1 FROM tmp_fza_fusion_ambitos WHERE procesado = 'N'
    ) DO
      SELECT q.empresa, q.almacen, q.sku,
             q.cantidad_semilla, q.valor_semilla
        INTO v_EMPRESA_AMBITO, v_ALMACEN_AMBITO, v_SKU_AMBITO,
             v_CANTIDAD_SEMILLA, v_VALOR_SEMILLA
        FROM tmp_fza_fusion_ambitos q
       WHERE q.procesado = 'N'
       ORDER BY q.empresa, q.almacen, q.sku
       LIMIT 1;
      UPDATE tmp_fza_fusion_ambitos q
         SET q.procesado = 'S'
       WHERE q.empresa = v_EMPRESA_AMBITO
         AND q.almacen = v_ALMACEN_AMBITO
         AND q.sku = v_SKU_AMBITO;
      SELECT COUNT(*),
             IFNULL(SUM(IFNULL(s.CANTIDAD_STK, 0)), 0),
             IFNULL(SUM(IFNULL(s.VALOR_TOTAL_STK, 0)), 0)
        INTO v_CANTIDAD_FILAS_STOCK, v_CANTIDAD_STOCK, v_VALOR_STOCK
        FROM fza_articulos_stockactual s
       WHERE s.CODIGO_ALM_STK = v_ALMACEN_AMBITO
         AND s.CODIGO_UNIDAD_STK = v_SKU_AMBITO
         FOR UPDATE;
      SELECT COUNT(*)
        INTO v_CANTIDAD_MOVIMIENTOS
        FROM fza_movimientos_almacen m
       WHERE m.CODIGO_EMP_MOV = v_EMPRESA_AMBITO
         AND m.CODIGO_ALM_MOV = v_ALMACEN_AMBITO
         AND m.CODIGO_UNIDAD_MOV = v_SKU_AMBITO
         AND m.ESACTIVO_MOV = 'S'
         FOR UPDATE;
      IF ABS(v_CANTIDAD_SEMILLA) < 0.0000005 THEN
        SET v_CANTIDAD_SEMILLA = 0;
        SET v_VALOR_SEMILLA = 0;
        SET v_PMP = 0;
      ELSE
        SET v_PMP = v_VALOR_SEMILLA / v_CANTIDAD_SEMILLA;
      END IF;
      SET v_STOCK = v_CANTIDAD_SEMILLA;
      SET v_FIN = 'N';
      OPEN cur_MOVIMIENTOS;
      bucle_MOVIMIENTOS: LOOP
        FETCH cur_MOVIMIENTOS
          INTO v_NUMERO_MOV, v_TIPO_MOV, v_CANTIDAD_MOV,
               v_COSTE_UNITARIO_MOV, v_ES_CIERRE_INVENTARIO,
               v_ES_PMP_MANUAL;
        IF v_FIN = 'S' THEN
          LEAVE bucle_MOVIMIENTOS;
        END IF;
        IF v_ES_CIERRE_INVENTARIO = 'S' AND v_TIPO_MOV = 'S' THEN
          SET v_COSTE_UNITARIO_MOV = v_PMP;
        ELSEIF v_ES_CIERRE_INVENTARIO = 'S' AND v_TIPO_MOV = 'E' AND
               v_ES_PMP_MANUAL <> 'S' THEN
          SET v_COSTE_UNITARIO_MOV = v_PMP;
        END IF;
        IF v_TIPO_MOV = 'E' THEN
          IF v_STOCK <= 0 OR v_STOCK + v_CANTIDAD_MOV = 0 THEN
            SET v_PMP = v_COSTE_UNITARIO_MOV;
          ELSE
            SET v_PMP = ((v_STOCK * v_PMP) +
                        (v_CANTIDAD_MOV * v_COSTE_UNITARIO_MOV)) /
                        (v_STOCK + v_CANTIDAD_MOV);
          END IF;
          SET v_TOTAL_MOV = v_CANTIDAD_MOV * v_COSTE_UNITARIO_MOV;
          SET v_STOCK = v_STOCK + v_CANTIDAD_MOV;
        ELSEIF v_TIPO_MOV = 'S' THEN
          SET v_TOTAL_MOV = v_CANTIDAD_MOV * v_PMP;
          SET v_STOCK = v_STOCK - v_CANTIDAD_MOV;
        ELSE
          SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Movimiento activo con tipo distinto de E o S';
        END IF;
        UPDATE fza_movimientos_almacen m
           SET m.PRECIO_COSTE_UNITARIO_MOV = IF(
                 v_ES_CIERRE_INVENTARIO = 'S',
                 v_COSTE_UNITARIO_MOV,
                 m.PRECIO_COSTE_UNITARIO_MOV),
               m.PRECIO_MEDIO_MOV = v_PMP,
               m.TOTAL_COSTE_MOV = v_TOTAL_MOV
         WHERE m.NUMERO_MOV = v_NUMERO_MOV
           AND m.CODIGO_EMP_MOV = v_EMPRESA_AMBITO
           AND m.CODIGO_ALM_MOV = v_ALMACEN_AMBITO
           AND m.CODIGO_UNIDAD_MOV = v_SKU_AMBITO
           AND m.ESACTIVO_MOV = 'S';
      END LOOP;
      CLOSE cur_MOVIMIENTOS;
      IF ABS(v_STOCK) < 0.0000005 THEN
        SET v_STOCK = 0;
      END IF;
      SET v_AJUSTE_SIN_LOTE = v_STOCK - v_CANTIDAD_STOCK;
      IF ABS(v_AJUSTE_SIN_LOTE) >= 0.0000005 OR
         (v_CANTIDAD_FILAS_STOCK = 0 AND
          v_CANTIDAD_MOVIMIENTOS > 0) THEN
        INSERT INTO fza_articulos_stockactual
          (CODIGO_ALM_STK, CODIGO_UNIDAD_STK, LOTE_STK,
           FECHA_CADUCIDAD_STK, CANTIDAD_STK, VALOR_TOTAL_STK,
           PRECIO_MEDIO_STK)
        VALUES
          (v_ALMACEN_AMBITO, v_SKU_AMBITO, '', NULL,
           v_AJUSTE_SIN_LOTE, 0, 0)
        ON DUPLICATE KEY UPDATE
          CANTIDAD_STK = IFNULL(CANTIDAD_STK, 0) + VALUES(CANTIDAD_STK);
      END IF;
      
      
      CALL PRC_FZA_STOCK_LOTES_REPARTIR_SKU(
        v_ALMACEN_AMBITO, v_SKU_AMBITO, v_STOCK, v_CON_LOTES);
      UPDATE fza_articulos_stockactual s
         SET s.VALOR_TOTAL_STK = IF(v_STOCK > 0,
               IFNULL(s.CANTIDAD_STK, 0) * v_PMP, 0),
             s.PRECIO_MEDIO_STK = IF(v_STOCK > 0, v_PMP, 0)
       WHERE s.CODIGO_ALM_STK = v_ALMACEN_AMBITO
         AND s.CODIGO_UNIDAD_STK = v_SKU_AMBITO;
      DELETE FROM tmp_fza_fusion_inventarios;
      INSERT INTO tmp_fza_fusion_inventarios
        (empresa, almacen, serie, numero, linea, numero_salida,
         numero_entrada, cantidad_salidas, cantidad_entradas)
      SELECT l.CODIGO_EMP_INVLIN,
             l.CODIGO_ALM_INVLIN,
             l.SERIE_INV_INVLIN,
             l.NUMERO_INV_INVLIN,
             l.LINEA_INVLIN,
             MIN(s.NUMERO_MOV),
             MIN(e.NUMERO_MOV),
             COUNT(DISTINCT s.NUMERO_MOV),
             COUNT(DISTINCT e.NUMERO_MOV)
        FROM fza_inventarios_lineas l
        JOIN fza_inventarios i
          ON i.CODIGO_EMP_INV = l.CODIGO_EMP_INVLIN
         AND i.CODIGO_ALM_INV = l.CODIGO_ALM_INVLIN
         AND i.SERIE_INV = l.SERIE_INV_INVLIN
         AND i.NUMERO_INV = l.NUMERO_INV_INVLIN
        JOIN fza_movimientos_almacen s
          ON s.CODIGO_EMP_MOV = l.CODIGO_EMP_INVLIN
         AND s.CODIGO_ALM_MOV = l.CODIGO_ALM_INVLIN
         AND s.CODIGO_UNIDAD_MOV = l.CODIGO_UNIDAD_INVLIN
         AND s.SERIE_DOC_MOV = l.SERIE_INV_INVLIN
         AND s.NUMERO_DOC_MOV = l.NUMERO_INV_INVLIN
         AND (s.LINEA_MOV = l.LINEA_INVLIN OR
              (s.LINEA_MOV REGEXP '^[0-9]+$' AND
               l.LINEA_INVLIN REGEXP '^[0-9]+$' AND
               CAST(s.LINEA_MOV AS UNSIGNED) =
                 CAST(l.LINEA_INVLIN AS UNSIGNED)))
         AND s.TIPO_DOC_MOV = 'IN'
         AND s.TIPO_MOV = 'S'
         AND s.ESACTIVO_MOV = 'S'
        LEFT JOIN fza_movimientos_almacen e
          ON e.CODIGO_EMP_MOV = l.CODIGO_EMP_INVLIN
         AND e.CODIGO_ALM_MOV = l.CODIGO_ALM_INVLIN
         AND e.CODIGO_UNIDAD_MOV = l.CODIGO_UNIDAD_INVLIN
         AND e.SERIE_DOC_MOV = l.SERIE_INV_INVLIN
         AND e.NUMERO_DOC_MOV = l.NUMERO_INV_INVLIN
         AND (e.LINEA_MOV = l.LINEA_INVLIN OR
              (e.LINEA_MOV REGEXP '^[0-9]+$' AND
               l.LINEA_INVLIN REGEXP '^[0-9]+$' AND
               CAST(e.LINEA_MOV AS UNSIGNED) =
                 CAST(l.LINEA_INVLIN AS UNSIGNED)))
         AND e.TIPO_DOC_MOV = 'IN'
         AND e.TIPO_MOV = 'E'
         AND e.ESACTIVO_MOV = 'S'
       WHERE l.CODIGO_EMP_INVLIN = v_EMPRESA_AMBITO
         AND l.CODIGO_ALM_INVLIN = v_ALMACEN_AMBITO
         AND l.CODIGO_UNIDAD_INVLIN = v_SKU_AMBITO
         AND i.ESTADO_INV = 'APLICADO'
       GROUP BY l.CODIGO_EMP_INVLIN,
                l.CODIGO_ALM_INVLIN,
                l.SERIE_INV_INVLIN,
                l.NUMERO_INV_INVLIN,
                l.LINEA_INVLIN;
      IF EXISTS(
        SELECT 1
          FROM tmp_fza_fusion_inventarios t
         WHERE t.cantidad_salidas <> 1 OR t.cantidad_entradas <> 1
      ) OR EXISTS(
        SELECT 1
          FROM fza_inventarios_lineas l
          JOIN fza_inventarios i
            ON i.CODIGO_EMP_INV = l.CODIGO_EMP_INVLIN
           AND i.CODIGO_ALM_INV = l.CODIGO_ALM_INVLIN
           AND i.SERIE_INV = l.SERIE_INV_INVLIN
           AND i.NUMERO_INV = l.NUMERO_INV_INVLIN
         WHERE l.CODIGO_EMP_INVLIN = v_EMPRESA_AMBITO
           AND l.CODIGO_ALM_INVLIN = v_ALMACEN_AMBITO
           AND l.CODIGO_UNIDAD_INVLIN = v_SKU_AMBITO
           AND i.ESTADO_INV = 'APLICADO'
           AND NOT EXISTS(
             SELECT 1
               FROM tmp_fza_fusion_inventarios t
              WHERE t.empresa = l.CODIGO_EMP_INVLIN
                AND t.almacen = l.CODIGO_ALM_INVLIN
                AND t.serie = l.SERIE_INV_INVLIN
                AND t.numero = l.NUMERO_INV_INVLIN
                AND t.linea = l.LINEA_INVLIN)
      ) OR EXISTS(
        SELECT 1
          FROM tmp_fza_fusion_inventarios t
         GROUP BY t.numero_salida
        HAVING COUNT(*) > 1
      ) OR EXISTS(
        SELECT 1
          FROM tmp_fza_fusion_inventarios t
         WHERE t.numero_entrada IS NOT NULL
         GROUP BY t.numero_entrada
        HAVING COUNT(*) > 1
      ) THEN
        SIGNAL SQLSTATE '45000'
          SET MESSAGE_TEXT = 'Inventario ambiguo para el SKU fusionado';
      END IF;
      IF EXISTS(
        SELECT 1
          FROM tmp_fza_fusion_inventarios t
          JOIN fza_inventarios_lineas l
            ON l.CODIGO_EMP_INVLIN = t.empresa
           AND l.CODIGO_ALM_INVLIN = t.almacen
           AND l.SERIE_INV_INVLIN = t.serie
           AND l.NUMERO_INV_INVLIN = t.numero
           AND l.LINEA_INVLIN = t.linea
          JOIN fza_movimientos_almacen s
            ON s.NUMERO_MOV = t.numero_salida
           AND s.CODIGO_EMP_MOV = t.empresa
           AND s.CODIGO_ALM_MOV = t.almacen
           AND s.CODIGO_UNIDAD_MOV = v_SKU_AMBITO
          JOIN fza_movimientos_almacen e
            ON e.NUMERO_MOV = t.numero_entrada
           AND e.CODIGO_EMP_MOV = t.empresa
           AND e.CODIGO_ALM_MOV = t.almacen
           AND e.CODIGO_UNIDAD_MOV = v_SKU_AMBITO
         WHERE ABS(IFNULL(l.CANTIDAD_TEORICA_INVLIN, 0) -
                   IFNULL(s.CANTIDAD_MOV, 0)) >= 0.0000005
            OR ABS(IFNULL(l.CANTIDAD_FISICA_INVLIN, 0) -
                   IFNULL(e.CANTIDAD_MOV, 0)) >= 0.0000005
      ) THEN
        SIGNAL SQLSTATE '45000'
          SET MESSAGE_TEXT =
            'Las cantidades del inventario aplicado no coinciden';
      END IF;
      UPDATE fza_inventarios_lineas l
      JOIN tmp_fza_fusion_inventarios t
        ON t.empresa = l.CODIGO_EMP_INVLIN
       AND t.almacen = l.CODIGO_ALM_INVLIN
       AND t.serie = l.SERIE_INV_INVLIN
       AND t.numero = l.NUMERO_INV_INVLIN
       AND t.linea = l.LINEA_INVLIN
      JOIN fza_movimientos_almacen s
        ON s.NUMERO_MOV = t.numero_salida
       AND s.CODIGO_EMP_MOV = t.empresa
       AND s.CODIGO_ALM_MOV = t.almacen
       AND s.CODIGO_UNIDAD_MOV = v_SKU_AMBITO
      LEFT JOIN fza_movimientos_almacen e
        ON e.NUMERO_MOV = t.numero_entrada
       AND e.CODIGO_EMP_MOV = t.empresa
       AND e.CODIGO_ALM_MOV = t.almacen
       AND e.CODIGO_UNIDAD_MOV = v_SKU_AMBITO
         SET l.PRECIO_MEDIO_INVLIN = s.PRECIO_MEDIO_MOV,
             l.PRECIO_MEDIO_NUEVO_INVLIN = IF(
               l.ESPRECIO_MEDIO_CORREGIDO_INVLIN = 'S',
               l.PRECIO_MEDIO_NUEVO_INVLIN,
               IFNULL(e.PRECIO_COSTE_UNITARIO_MOV, s.PRECIO_MEDIO_MOV)),
             l.CANTIDAD_DIFERENCIA_INVLIN =
               l.CANTIDAD_FISICA_INVLIN -
               l.CANTIDAD_TEORICA_INVLIN,
             l.TOTAL_COSTE_DIFERENCIA_INVLIN = ROUND(
               (l.CANTIDAD_FISICA_INVLIN * IF(
                 l.ESPRECIO_MEDIO_CORREGIDO_INVLIN = 'S',
                 l.PRECIO_MEDIO_NUEVO_INVLIN,
                 IFNULL(e.PRECIO_COSTE_UNITARIO_MOV,
                        s.PRECIO_MEDIO_MOV))) -
              (l.CANTIDAD_TEORICA_INVLIN * s.PRECIO_MEDIO_MOV), 2);
      UPDATE fza_inventarios i
      JOIN (
        SELECT DISTINCT empresa, almacen, serie, numero
          FROM tmp_fza_fusion_inventarios
      ) t
        ON t.empresa = i.CODIGO_EMP_INV
       AND t.almacen = i.CODIGO_ALM_INV
       AND t.serie = i.SERIE_INV
       AND t.numero = i.NUMERO_INV
         SET i.TOTAL_UNIDADES_DIFERENCIA_INV = (
               SELECT IFNULL(SUM(l.CANTIDAD_DIFERENCIA_INVLIN), 0)
                 FROM fza_inventarios_lineas l
                WHERE l.CODIGO_EMP_INVLIN = i.CODIGO_EMP_INV
                  AND l.CODIGO_ALM_INVLIN = i.CODIGO_ALM_INV
                  AND l.SERIE_INV_INVLIN = i.SERIE_INV
                  AND l.NUMERO_INV_INVLIN = i.NUMERO_INV),
             i.TOTAL_EUROS_DIFERENCIA_INV = (
               SELECT IFNULL(SUM(l.TOTAL_COSTE_DIFERENCIA_INVLIN), 0)
                 FROM fza_inventarios_lineas l
                WHERE l.CODIGO_EMP_INVLIN = i.CODIGO_EMP_INV
                  AND l.CODIGO_ALM_INVLIN = i.CODIGO_ALM_INV
                  AND l.SERIE_INV_INVLIN = i.SERIE_INV
                  AND l.NUMERO_INV_INVLIN = i.NUMERO_INV);
    END WHILE;
    UPDATE tmp_fza_fusion_traspasos t
    JOIN tmp_fza_fusion_ambitos q
      ON q.empresa = t.empresa_origen
     AND q.almacen = t.almacen_origen
     AND q.sku = t.sku
    JOIN fza_movimientos_almacen s
      ON s.NUMERO_MOV = t.numero_salida
     AND s.CODIGO_EMP_MOV = t.empresa_origen
     AND s.CODIGO_ALM_MOV = t.almacen_origen
     AND s.CODIGO_UNIDAD_MOV = t.sku
     AND s.ESACTIVO_MOV = 'S'
    JOIN fza_movimientos_almacen e
      ON e.NUMERO_MOV = t.numero_entrada
     AND e.CODIGO_EMP_MOV = t.empresa_destino
     AND e.CODIGO_ALM_MOV = t.almacen_destino
     AND e.CODIGO_UNIDAD_MOV = t.sku
     AND e.ESACTIVO_MOV = 'S'
       SET t.cantidad_salida = IFNULL(s.CANTIDAD_MOV, 0),
           t.cantidad_entrada = IFNULL(e.CANTIDAD_MOV, 0),
           t.coste_salida = IF(
             ABS(IFNULL(s.CANTIDAD_MOV, 0)) >= 0.0000005,
             CAST(IFNULL(s.TOTAL_COSTE_MOV, 0) /
                  s.CANTIDAD_MOV AS decimal(19,6)), NULL);
    IF EXISTS(
      SELECT 1
        FROM tmp_fza_fusion_ambitos q
        JOIN fza_movimientos_almacen s
          ON s.CODIGO_EMP_MOV = q.empresa
         AND s.CODIGO_ALM_MOV = q.almacen
         AND s.CODIGO_UNIDAD_MOV = q.sku
         AND s.ESACTIVO_MOV = 'S'
         AND s.TIPO_DOC_MOV IN ('TR', 'AT', 'TA')
         AND s.TIPO_MOV = 'S'
        LEFT JOIN tmp_fza_fusion_traspasos t
          ON t.numero_salida = s.NUMERO_MOV
       GROUP BY s.NUMERO_MOV
      HAVING COUNT(t.numero_entrada) <> 1
    ) OR EXISTS(
      SELECT 1
        FROM tmp_fza_fusion_ambitos q
        JOIN fza_movimientos_almacen e
          ON e.CODIGO_EMP_MOV = q.empresa
         AND e.CODIGO_ALM_MOV = q.almacen
         AND e.CODIGO_UNIDAD_MOV = q.sku
         AND e.ESACTIVO_MOV = 'S'
         AND e.TIPO_DOC_MOV IN ('TR', 'AT', 'TA')
         AND e.TIPO_MOV = 'E'
        LEFT JOIN tmp_fza_fusion_traspasos t
          ON t.numero_entrada = e.NUMERO_MOV
       GROUP BY e.NUMERO_MOV
      HAVING COUNT(t.numero_salida) <> 1
    ) THEN
      SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Contraparte de traspaso inexistente o ambigua';
    END IF;
    IF EXISTS(
      SELECT 1
        FROM tmp_fza_fusion_traspasos t
        JOIN tmp_fza_fusion_ambitos q
          ON q.empresa = t.empresa_origen
         AND q.almacen = t.almacen_origen
         AND q.sku = t.sku
       WHERE t.coste_salida IS NULL
          OR t.cantidad_salida <= 0
          OR t.cantidad_entrada <= 0
          OR ABS(t.cantidad_salida - t.cantidad_entrada) >= 0.0000005
    ) THEN
      SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT =
          'Las contrapartes de traspaso no tienen igual cantidad';
    END IF;
    SELECT COUNT(*)
      INTO v_CAMBIOS
      FROM tmp_fza_fusion_traspasos t
      JOIN tmp_fza_fusion_ambitos q
        ON q.empresa = t.empresa_origen
       AND q.almacen = t.almacen_origen
       AND q.sku = t.sku
      JOIN fza_movimientos_almacen e
        ON e.NUMERO_MOV = t.numero_entrada
       AND e.CODIGO_EMP_MOV = t.empresa_destino
       AND e.CODIGO_ALM_MOV = t.almacen_destino
       AND e.CODIGO_UNIDAD_MOV = t.sku
       AND e.ESACTIVO_MOV = 'S'
     WHERE ABS(IFNULL(e.PRECIO_COSTE_UNITARIO_MOV, 0) -
               t.coste_salida) >= 0.0000005;
    IF v_CAMBIOS = 0 THEN
      LEAVE bucle_PROPAGACION;
    END IF;
    UPDATE fza_movimientos_almacen e
    JOIN tmp_fza_fusion_traspasos t
      ON e.NUMERO_MOV = t.numero_entrada
     AND e.CODIGO_EMP_MOV = t.empresa_destino
     AND e.CODIGO_ALM_MOV = t.almacen_destino
     AND e.CODIGO_UNIDAD_MOV = t.sku
     AND e.ESACTIVO_MOV = 'S'
    JOIN tmp_fza_fusion_ambitos q
      ON q.empresa = t.empresa_origen
     AND q.almacen = t.almacen_origen
     AND q.sku = t.sku
       SET e.PRECIO_COSTE_UNITARIO_MOV = t.coste_salida
     WHERE ABS(IFNULL(e.PRECIO_COSTE_UNITARIO_MOV, 0) -
               t.coste_salida) >= 0.0000005;
  END WHILE;
  DROP TEMPORARY TABLE IF EXISTS tmp_fza_fusion_traspasos;
  DROP TEMPORARY TABLE IF EXISTS tmp_fza_fusion_inventarios;
  DROP TEMPORARY TABLE IF EXISTS tmp_fza_fusion_ambitos;
  IF v_TRANSACCION_PROPIA = 'S' THEN
    COMMIT;
  ELSEIF v_SAVEPOINT_PROPIO = 'S' THEN
    RELEASE SAVEPOINT SP_FZA_FUSION_PMP;
  END IF;
END
;;
DELIMITER ;
