/*!50003 DROP PROCEDURE IF EXISTS `PRC_FZA_GARANTIAS_ALTA` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_spanish_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_FZA_GARANTIAS_ALTA`(
  IN p_CODIGO_UNIDAD varchar(50),
  IN p_LOTE varchar(50),
  IN p_CODIGO_ART varchar(20),
  IN p_CODIGO_CLI varchar(20),
  IN p_TIPO_DOC_VENTA varchar(5),
  IN p_SERIE_DOC_VENTA varchar(20),
  IN p_NUMERO_DOC_VENTA varchar(20),
  IN p_FECHA_VENTA date,
  IN p_FECHA_FIN_GARANTIA date,
  IN p_MOTIVO varchar(500),
  IN p_CODIGO_ALM varchar(10),
  IN p_USUARIO varchar(50),
  OUT p_ID_GAR bigint
)
BEGIN
  
  
  
  
  DECLARE v_CODIGO_PRV varchar(20);
  DECLARE v_MODELO varchar(100);
  DECLARE v_DIRECCION_PRV varchar(500);
  SELECT AP.CODIGO_PRV_AP,
         LEFT(NULLIF(TRIM(AP.REF_PROVEEDOR_AP), ''), 100)
    INTO v_CODIGO_PRV, v_MODELO
    FROM fza_articulos_proveedores AP
   WHERE AP.CODIGO_ART_AP = p_CODIGO_ART
   ORDER BY AP.ESPROVEEDORPRINCIPAL_AP = 'S' DESC, AP.CODIGO_PRV_AP
   LIMIT 1;
  SELECT LEFT(CONCAT_WS(', ', P.RAZON_SOCIAL_PRV,
                 NULLIF(TRIM(P.DIRECCION1_PRV), ''),
                 NULLIF(TRIM(P.DIRECCION2_PRV), ''),
                 NULLIF(TRIM(CONCAT_WS(' ', P.CODIGO_POSTAL_PRV,
                                       P.POBLACION_PRV)), ''),
                 NULLIF(TRIM(P.PROVINCIA_PRV), ''),
                 NULLIF(TRIM(P.PAIS_PRV), '')), 500)
    INTO v_DIRECCION_PRV
    FROM fza_proveedores P
   WHERE P.CODIGO_PRV_PRV = v_CODIGO_PRV;
  INSERT INTO fza_garantias_reclamaciones (
    CODIGO_UNIDAD_GAR, LOTE_GAR, CODIGO_ART_GAR, CODIGO_CLI_GAR,
    TIPO_DOC_VENTA_GAR, SERIE_DOC_VENTA_GAR, NUMERO_DOC_VENTA_GAR,
    FECHA_VENTA_GAR, FECHA_FIN_GARANTIA_GAR, FECHA_RECLAMACION_GAR,
    MOTIVO_GAR, ESTADO_GAR, CODIGO_ALM_GAR, MODELO_GAR, CODIGO_PRV_GAR,
    NOMBRE_CLIENTE_GAR, TELEFONO_CLIENTE_GAR, EMAIL_CLIENTE_GAR,
    DIRECCION_CLIENTE_GAR, CODIGO_POSTAL_CLIENTE_GAR,
    POBLACION_CLIENTE_GAR, PROVINCIA_CLIENTE_GAR,
    FECHA_RECEPCION_GAR, MEDIO_RECEPCION_GAR, DIRECCION_ENVIO_FAB_GAR,
    USUARIO_ALTA)
  SELECT p_CODIGO_UNIDAD, p_LOTE, NULLIF(p_CODIGO_ART, ''),
         NULLIF(p_CODIGO_CLI, ''), NULLIF(p_TIPO_DOC_VENTA, ''),
         NULLIF(p_SERIE_DOC_VENTA, ''), NULLIF(p_NUMERO_DOC_VENTA, ''),
         p_FECHA_VENTA, p_FECHA_FIN_GARANTIA, NOW(),
         NULLIF(TRIM(p_MOTIVO), ''), 'ABIERTA', NULLIF(p_CODIGO_ALM, ''),
         v_MODELO, v_CODIGO_PRV,
         LEFT(NULLIF(TRIM(CONCAT_WS(' ', C.NOMBRE_PERSONA_CLIENTE_CLI,
                                    C.APELLIDOS_PERSONA_CLIENTE_CLI)), ''),
              200),
         LEFT(COALESCE(NULLIF(TRIM(C.MOVIL_CLI), ''),
                       NULLIF(TRIM(C.TELEFONO_CLI), '')), 40),
         C.EMAIL_CLI, C.DIRECCION1_CLI, C.CODIGO_POSTAL_CLI,
         C.POBLACION_CLI, C.PROVINCIA_CLI,
         CURDATE(), 'TIENDA', v_DIRECCION_PRV,
         LEFT(COALESCE(NULLIF(TRIM(p_USUARIO), ''), 'SISTEMA'), 50)
    FROM (SELECT 1 AS UNO) U
    LEFT JOIN fza_clientes C
      ON C.CODIGO_CLI_CLI = NULLIF(p_CODIGO_CLI, '');
  SET p_ID_GAR = LAST_INSERT_ID();
  
  
  UPDATE fza_garantias_reclamaciones G
    LEFT JOIN fza_clientes C ON C.CODIGO_CLI_CLI = G.CODIGO_CLI_GAR
     SET G.NOMBRE_CLIENTE_GAR = LEFT(C.RAZON_SOCIAL_CLI, 200)
   WHERE G.ID_GAR = p_ID_GAR
     AND G.NOMBRE_CLIENTE_GAR IS NULL
     AND C.RAZON_SOCIAL_CLI IS NOT NULL;
END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
