/*!50003 DROP PROCEDURE IF EXISTS `PRC_FZA_GARANTIAS_DATOS_SERIE` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_spanish_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_FZA_GARANTIAS_DATOS_SERIE`(
  IN p_LOTE varchar(50),
  IN p_CODIGO_UNIDAD varchar(50)
)
BEGIN
  
  
  
  
  SELECT L.CODIGO_UNIDAD_LOT,
         L.LOTE_LOT,
         K.CODIGO_ART_SKU,
         A.DESCRIPCION_ART,
         A.MESES_GARANTIA_ART,
         V.TIPO_DOC_MOV AS TIPO_DOC_VENTA,
         V.SERIE_DOC_MOV AS SERIE_DOC_VENTA,
         V.NUMERO_DOC_MOV AS NUMERO_DOC_VENTA,
         DATE(V.FECHA_MOV) AS FECHA_VENTA,
         COALESCE(NULLIF(FS.CODIGO_CLI_FAC, ''),
                  NULLIF(V.CODIGO_CLI_MOV, '')) AS CODIGO_CLI,
         C.RAZON_SOCIAL_CLI,
         V.CODIGO_ALM_MOV AS CODIGO_ALM_VENTA,
         IF(V.NUMERO_MOV IS NULL OR A.MESES_GARANTIA_ART IS NULL, NULL,
            DATE(V.FECHA_MOV) + INTERVAL A.MESES_GARANTIA_ART MONTH)
           AS FECHA_FIN_GARANTIA,
         IF(V.NUMERO_MOV IS NOT NULL AND A.MESES_GARANTIA_ART IS NOT NULL
            AND DATE(V.FECHA_MOV) + INTERVAL A.MESES_GARANTIA_ART MONTH
                >= CURDATE(), 'S', 'N') AS ESEN_GARANTIA,
         IF(EXISTS (
              SELECT 1
                FROM fza_movimientos_almacen D
               WHERE D.CODIGO_UNIDAD_MOV = L.CODIGO_UNIDAD_LOT
                 AND D.LOTE_MOV = L.LOTE_LOT
                 AND D.ESACTIVO_MOV = 'S'
                 AND D.TIPO_MOV = 'E'
                 AND D.TIPO_DOC_MOV IN ('VE', 'FC', 'AV')
                 AND D.FECHA_MOV >= V.FECHA_MOV), 'S', 'N') AS ESDEVUELTA,
         (SELECT MIN(S.CODIGO_ALM_STK)
            FROM fza_articulos_stockactual S
           WHERE S.CODIGO_UNIDAD_STK = L.CODIGO_UNIDAD_LOT
             AND S.LOTE_STK = L.LOTE_LOT
             AND S.CANTIDAD_STK > 0) AS CODIGO_ALM_STOCK,
         (SELECT COUNT(*)
            FROM fza_garantias_reclamaciones G
           WHERE G.LOTE_GAR = L.LOTE_LOT
             AND G.CODIGO_UNIDAD_GAR = L.CODIGO_UNIDAD_LOT
             AND G.ESTADO_GAR IN ('ABIERTA', 'EN_SAT'))
           AS RECLAMACIONES_ABIERTAS
    FROM fza_articulos_lotes L
    LEFT JOIN fza_articulos_skus K
      ON K.CODIGO_UNIDAD_SKU = L.CODIGO_UNIDAD_LOT
    LEFT JOIN fza_articulos A
      ON A.CODIGO_ART_ART = K.CODIGO_ART_SKU
    LEFT JOIN fza_movimientos_almacen V
      ON V.NUMERO_MOV = (
           SELECT X.NUMERO_MOV
             FROM fza_movimientos_almacen X
            WHERE X.CODIGO_UNIDAD_MOV = L.CODIGO_UNIDAD_LOT
              AND X.LOTE_MOV = L.LOTE_LOT
              AND X.ESACTIVO_MOV = 'S'
              AND X.TIPO_MOV = 'S'
              AND X.TIPO_DOC_MOV IN ('VE', 'FC', 'AV')
            ORDER BY X.FECHA_MOV DESC, X.INSTANTE_ALTA DESC,
                     X.NUMERO_MOV DESC
            LIMIT 1)
    LEFT JOIN fza_facturas_relaciones FR
      ON FR.ID_FACREL = (
           SELECT MAX(R.ID_FACREL)
             FROM fza_facturas_relaciones R
             JOIN fza_facturas FN
               ON FN.SERIE_FAC = R.SERIE_FAC_FACREL
              AND FN.NUMERO_FAC = R.NUMERO_FAC_FACREL
            WHERE V.TIPO_DOC_MOV IN ('VE', 'FC')
              AND R.SERIE_FAC_ORIGEN_FACREL = V.SERIE_DOC_MOV
              AND R.NUMERO_FAC_ORIGEN_FACREL = V.NUMERO_DOC_MOV
              AND R.TIPO_RELACION_FACREL = 'SUSTITUYE'
              AND FN.CODIGO_EMP_FAC = V.CODIGO_EMP_MOV
              AND COALESCE(FN.FASE_FAC, '') NOT IN (
                 'BORRADOR', 'ERROR_BORRADOR', 'CANCELADA', 'SIN_VERIF_ANULADA',
                 'VERIFACTU_ANULADA', 'NOVERIFACTU_ANULADA'))
    LEFT JOIN fza_facturas FS
      ON FS.SERIE_FAC = FR.SERIE_FAC_FACREL
     AND FS.NUMERO_FAC = FR.NUMERO_FAC_FACREL
    LEFT JOIN fza_clientes C
      ON C.CODIGO_CLI_CLI = COALESCE(NULLIF(FS.CODIGO_CLI_FAC, ''),
                                     NULLIF(V.CODIGO_CLI_MOV, ''))
   WHERE L.LOTE_LOT = TRIM(IFNULL(p_LOTE, ''))
     AND (NULLIF(TRIM(p_CODIGO_UNIDAD), '') IS NULL OR
          L.CODIGO_UNIDAD_LOT = p_CODIGO_UNIDAD)
   ORDER BY L.CODIGO_UNIDAD_LOT;
END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_VALUE_ON_ZERO' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `PRC_FZA_GARANTIAS_SUSTITUIR` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_spanish_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_FZA_GARANTIAS_SUSTITUIR`(
  IN p_ID_GAR bigint,
  IN p_LOTE_NUEVO varchar(50),
  IN p_ALMACEN varchar(10),
  IN p_ALMACEN_TARAS varchar(10),
  IN p_USUARIO varchar(50)
)
BEGIN
  
  
  
  
  DECLARE v_TRANSACCION_PROPIA varchar(1) DEFAULT 'N';
  DECLARE v_ESTADO varchar(12);
  DECLARE v_SKU varchar(50);
  DECLARE v_LOTE varchar(50);
  DECLARE v_ARTICULO varchar(20);
  DECLARE v_CLIENTE varchar(20);
  DECLARE v_EMPRESA varchar(20);
  DECLARE v_EMPRESA_TARAS varchar(20);
  DECLARE v_RESULTADO varchar(20);
  DECLARE v_CADUCADO varchar(1);
  DECLARE v_STOCK decimal(19,6);
  DECLARE v_CADUCIDAD date;
  DECLARE v_NUMERO varchar(20);
  DECLARE v_LOTE_NUEVO varchar(50);
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    IF v_TRANSACCION_PROPIA = 'S' THEN
      ROLLBACK;
    END IF;
    RESIGNAL;
  END;
  IF @@in_transaction = 0 THEN
    SET v_TRANSACCION_PROPIA = 'S';
    START TRANSACTION;
  END IF;
  SET v_LOTE_NUEVO = TRIM(IFNULL(p_LOTE_NUEVO, ''));
  SELECT G.ESTADO_GAR, G.CODIGO_UNIDAD_GAR, G.LOTE_GAR, G.CODIGO_ART_GAR,
         G.CODIGO_CLI_GAR
    INTO v_ESTADO, v_SKU, v_LOTE, v_ARTICULO, v_CLIENTE
    FROM fza_garantias_reclamaciones G
   WHERE G.ID_GAR = p_ID_GAR
     FOR UPDATE;
  IF v_ESTADO IS NULL THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'La reclamacion no existe';
  END IF;
  IF v_ESTADO NOT IN ('ABIERTA', 'EN_SAT') THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'La reclamacion ya esta cerrada';
  END IF;
  IF v_LOTE_NUEVO = '' OR v_LOTE_NUEVO = v_LOTE THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'Indique otra serie para sustituir';
  END IF;
  SELECT MAX(A.CODIGO_EMP_ALM) INTO v_EMPRESA
    FROM fza_almacenes A
   WHERE A.CODIGO_ALM_ALM = p_ALMACEN;
  SELECT MAX(A.CODIGO_EMP_ALM) INTO v_EMPRESA_TARAS
    FROM fza_almacenes A
   WHERE A.CODIGO_ALM_ALM = p_ALMACEN_TARAS
     AND A.TIPO_USO_ALM = 'TARAS';
  IF v_EMPRESA IS NULL OR v_EMPRESA_TARAS IS NULL OR
     v_EMPRESA <> v_EMPRESA_TARAS THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'Almacen o almacen de taras no validos';
  END IF;
  CALL PRC_FZA_LOTES_VALIDAR_SALIDA(
    v_SKU, p_ALMACEN, v_LOTE_NUEVO, 1,
    v_RESULTADO, v_CADUCADO, v_STOCK, v_CADUCIDAD);
  IF v_RESULTADO <> 'OK' THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'La serie nueva no esta disponible en el almacen';
  END IF;
  SET v_NUMERO = CAST(p_ID_GAR AS char);
  CALL PRC_FZA_MOVIMIENTOS_ALMACEN_INSERT_LOTE(
    CONCAT('GAS', LEFT(SHA2(CONCAT('GA', CHAR(31), v_NUMERO), 256), 17)),
    'GA', 'GARANTIA', v_NUMERO, '0001', v_EMPRESA, p_ALMACEN, NULL,
    v_SKU, 'S', 1, 0, 0, p_USUARIO, p_ALMACEN, NULL, NULL,
    v_CLIENTE, v_ARTICULO, v_LOTE_NUEVO, NULL);
  CALL PRC_FZA_MOVIMIENTOS_ALMACEN_INSERT_LOTE(
    CONCAT('GAE', LEFT(SHA2(CONCAT('GA', CHAR(31), v_NUMERO), 256), 17)),
    'GA', 'GARANTIA', v_NUMERO, '0002', v_EMPRESA, p_ALMACEN_TARAS, NULL,
    v_SKU, 'E', 1, 0, 0, p_USUARIO, p_ALMACEN, NULL, NULL,
    v_CLIENTE, v_ARTICULO, v_LOTE, NULL);
  UPDATE fza_garantias_reclamaciones
     SET ESTADO_GAR = 'RESUELTA',
         RESOLUCION_GAR = 'SUSTITUIDA',
         LOTE_SUSTITUTO_GAR = v_LOTE_NUEVO,
         FECHA_RESOLUCION_GAR = NOW(),
         CODIGO_ALM_GAR = p_ALMACEN,
         INSTANTE_MODIF = NOW(),
         USUARIO_MODIF = LEFT(COALESCE(NULLIF(TRIM(p_USUARIO), ''),
                                       'SISTEMA'), 50)
   WHERE ID_GAR = p_ID_GAR;
  IF v_TRANSACCION_PROPIA = 'S' THEN
    COMMIT;
  END IF;
END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_VALUE_ON_ZERO' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `PRC_FZA_HUELLA_ESQUEMA` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
