/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_spanish_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_FZA_HUELLA_ESQUEMA`(
    IN `p_DETALLE` VARCHAR(1)
)
BEGIN
    DECLARE v_longitud    BIGINT;
    DECLARE v_estructura  CHAR(64);
    DECLARE v_vistas      CHAR(64);
    DECLARE v_rutinas     CHAR(64);
    DECLARE v_definidores CHAR(64);
    DECLARE v_codigo      CHAR(64);
    DECLARE v_indices     CHAR(64);
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        SET SESSION group_concat_max_len = v_longitud;
        DROP TEMPORARY TABLE IF EXISTS `tmp_fza_huella_esquema`;
        DROP TEMPORARY TABLE IF EXISTS `tmp_fza_huella_vistas`;
        RESIGNAL;
    END;
    SET v_longitud = @@SESSION.group_concat_max_len;
    SET SESSION group_concat_max_len = 67108864;
    DROP TEMPORARY TABLE IF EXISTS `tmp_fza_huella_esquema`;
    CREATE TEMPORARY TABLE `tmp_fza_huella_esquema` (
        `APARTADO` VARCHAR(20)  NOT NULL,
        `OBJETO`   VARCHAR(300) NOT NULL,
        `FIRMA`    TEXT         NOT NULL,
        KEY `IDX_HUELLA_APARTADO` (`APARTADO`, `OBJETO`)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
    CALL `PRC_FZA_HUELLA_ESQUEMA_TABLAS`();
    CALL `PRC_FZA_HUELLA_ESQUEMA_RUTINAS`();
    CALL `PRC_FZA_HUELLA_ESQUEMA_APARTADO`('ESTRUCTURA', v_estructura);
    CALL `PRC_FZA_HUELLA_ESQUEMA_APARTADO`('VISTAS', v_vistas);
    CALL `PRC_FZA_HUELLA_ESQUEMA_APARTADO`('RUTINAS', v_rutinas);
    CALL `PRC_FZA_HUELLA_ESQUEMA_APARTADO`('DEFINIDORES', v_definidores);
    CALL `PRC_FZA_HUELLA_ESQUEMA_APARTADO`('CODIGO', v_codigo);
    CALL `PRC_FZA_HUELLA_ESQUEMA_APARTADO`('INDICES', v_indices);
    SET SESSION group_concat_max_len = v_longitud;
    SELECT 1 AS `VERSION_HUELLA`,
           SHA2(CONCAT(v_estructura, v_vistas, v_rutinas, v_definidores),
                256) AS `HUELLA_GLOBAL`,
           v_estructura AS `HUELLA_ESTRUCTURA`,
           v_vistas AS `HUELLA_VISTAS`,
           v_rutinas AS `HUELLA_RUTINAS`,
           v_definidores AS `HUELLA_DEFINIDORES`,
           v_codigo AS `HUELLA_CODIGO`,
           v_indices AS `HUELLA_INDICES`;
    IF p_DETALLE = 'S' THEN
        SELECT H.`APARTADO`,
               H.`OBJETO`,
               H.`FIRMA`
          FROM `tmp_fza_huella_esquema` H
         ORDER BY H.`APARTADO`, H.`OBJETO`;
    END IF;
    DROP TEMPORARY TABLE `tmp_fza_huella_esquema`;
END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_VALUE_ON_ZERO' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `PRC_FZA_HUELLA_ESQUEMA_APARTADO` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_spanish_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_FZA_HUELLA_ESQUEMA_APARTADO`(
    IN  `p_APARTADO` VARCHAR(20),
    OUT `p_HUELLA`   CHAR(64)
)
BEGIN
    
    SELECT SHA2(CONCAT('{',
                       IFNULL(GROUP_CONCAT(
                         CONCAT(JSON_QUOTE(H.`OBJETO`), ':',
                                JSON_QUOTE(H.`FIRMA`))
                         ORDER BY H.`OBJETO`
                         SEPARATOR ','), ''),
                       '}'), 256)
      INTO p_HUELLA
      FROM `tmp_fza_huella_esquema` H
     WHERE H.`APARTADO` = p_APARTADO;
END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_VALUE_ON_ZERO' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `PRC_FZA_HUELLA_ESQUEMA_DEFINIDORES` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_spanish_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_FZA_HUELLA_ESQUEMA_DEFINIDORES`()
BEGIN
    DECLARE v_sin_permiso INT DEFAULT 0;
    
    DECLARE CONTINUE HANDLER FOR 1142 SET v_sin_permiso = 1;
    
    
    INSERT INTO `tmp_fza_huella_esquema` (`APARTADO`, `OBJETO`, `FIRMA`)
    SELECT 'DEFINIDORES',
           LOWER(O.`OBJETO`),
           IF(O.`SEGURIDAD` = 'INVOKER', 'OK',
              CONVERT(O.`DEFINIDOR` USING utf8mb4) COLLATE utf8mb4_bin)
      FROM (SELECT CONCAT('view ', V.`TABLE_NAME`) AS `OBJETO`,
                   V.`SECURITY_TYPE` AS `SEGURIDAD`,
                   V.`DEFINER` AS `DEFINIDOR`
              FROM `information_schema`.`VIEWS` V
             WHERE V.`TABLE_SCHEMA` = DATABASE()
               AND V.`TABLE_NAME` NOT LIKE 'tmp\_%'
               AND V.`TABLE_NAME` NOT LIKE 'vu\_%'
            UNION ALL
            SELECT CONCAT(R.`ROUTINE_TYPE`, ' ', R.`ROUTINE_NAME`),
                   R.`SECURITY_TYPE`,
                   R.`DEFINER`
              FROM `information_schema`.`ROUTINES` R
             WHERE R.`ROUTINE_SCHEMA` = DATABASE()
               AND R.`ROUTINE_NAME` NOT LIKE 'PRC\_FZA\_HUELLA\_ESQUEMA%'
               AND R.`ROUTINE_NAME` NOT LIKE 'PRU\_%'
               AND R.`ROUTINE_NAME` <> 'PRC_FZA_EN_TRANSACCION'
           ) O;
    UPDATE `tmp_fza_huella_esquema` H
       SET H.`FIRMA` = IF(EXISTS(
             SELECT 1
               FROM `mysql`.`user` U
              WHERE CONVERT(CONCAT(U.`User`, '@', U.`Host`) USING utf8mb4)
                    COLLATE utf8mb4_bin = H.`FIRMA`), 'OK', 'NO_EXISTE')
     WHERE H.`APARTADO` = 'DEFINIDORES'
       AND H.`FIRMA` <> 'OK';
    IF v_sin_permiso = 1 THEN
        UPDATE `tmp_fza_huella_esquema` H
           SET H.`FIRMA` = 'SIN_PERMISO'
         WHERE H.`APARTADO` = 'DEFINIDORES'
           AND H.`FIRMA` NOT IN ('OK', 'NO_EXISTE');
    END IF;
END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_VALUE_ON_ZERO' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `PRC_FZA_HUELLA_ESQUEMA_RUTINAS` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_spanish_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_FZA_HUELLA_ESQUEMA_RUTINAS`()
BEGIN
    INSERT INTO `tmp_fza_huella_esquema` (`APARTADO`, `OBJETO`, `FIRMA`)
    SELECT 'RUTINAS',
           LOWER(CONCAT(R.`ROUTINE_TYPE`, ' ', R.`ROUTINE_NAME`)),
           IFNULL(LOWER(GROUP_CONCAT(
             CONCAT(IFNULL(P.`PARAMETER_MODE`, 'RETURNS'), ' ',
                    IFNULL(P.`PARAMETER_NAME`, ''), ' ',
                    P.`DATA_TYPE`, ' ',
                    IFNULL(P.`CHARACTER_MAXIMUM_LENGTH`, ''), ',',
                    IFNULL(P.`NUMERIC_PRECISION`, ''), ',',
                    IFNULL(P.`NUMERIC_SCALE`, ''))
             ORDER BY P.`ORDINAL_POSITION`
             SEPARATOR ';')), '')
      FROM `information_schema`.`ROUTINES` R
      LEFT JOIN `information_schema`.`PARAMETERS` P
        ON P.`SPECIFIC_SCHEMA` = R.`ROUTINE_SCHEMA`
       AND P.`SPECIFIC_NAME` = R.`SPECIFIC_NAME`
       AND P.`ROUTINE_TYPE` = R.`ROUTINE_TYPE`
     WHERE R.`ROUTINE_SCHEMA` = DATABASE()
       AND R.`ROUTINE_NAME` NOT LIKE 'PRC\_FZA\_HUELLA\_ESQUEMA%'
       AND R.`ROUTINE_NAME` NOT LIKE 'PRU\_%'
       AND R.`ROUTINE_NAME` <> 'PRC_FZA_EN_TRANSACCION'
     GROUP BY R.`ROUTINE_TYPE`, R.`ROUTINE_NAME`;
    INSERT INTO `tmp_fza_huella_esquema` (`APARTADO`, `OBJETO`, `FIRMA`)
    SELECT 'CODIGO',
           LOWER(CONCAT(R.`ROUTINE_TYPE`, ' ', R.`ROUTINE_NAME`)),
           MD5(REPLACE(IFNULL(R.`ROUTINE_DEFINITION`, ''), CHAR(13), ''))
      FROM `information_schema`.`ROUTINES` R
     WHERE R.`ROUTINE_SCHEMA` = DATABASE()
       AND R.`ROUTINE_NAME` NOT LIKE 'PRC\_FZA\_HUELLA\_ESQUEMA%'
       AND R.`ROUTINE_NAME` NOT LIKE 'PRU\_%'
       AND R.`ROUTINE_NAME` <> 'PRC_FZA_EN_TRANSACCION';
    CALL `PRC_FZA_HUELLA_ESQUEMA_DEFINIDORES`();
END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_VALUE_ON_ZERO' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `PRC_FZA_HUELLA_ESQUEMA_TABLAS` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_spanish_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_FZA_HUELLA_ESQUEMA_TABLAS`()
BEGIN
    
    
    DROP TEMPORARY TABLE IF EXISTS `tmp_fza_huella_vistas`;
    CREATE TEMPORARY TABLE `tmp_fza_huella_vistas` (
        `TABLA` VARCHAR(64) NOT NULL,
        PRIMARY KEY (`TABLA`)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
    INSERT INTO `tmp_fza_huella_vistas` (`TABLA`)
    SELECT LOWER(T.`TABLE_NAME`)
      FROM `information_schema`.`TABLES` T
     WHERE T.`TABLE_SCHEMA` = DATABASE()
       AND T.`TABLE_TYPE` = 'VIEW'
       AND T.`TABLE_NAME` NOT LIKE 'tmp\_%'
       AND T.`TABLE_NAME` NOT LIKE 'vu\_%';
    INSERT INTO `tmp_fza_huella_esquema` (`APARTADO`, `OBJETO`, `FIRMA`)
    SELECT 'VISTAS',
           V.`TABLA`,
           'VIEW'
      FROM `tmp_fza_huella_vistas` V;
    INSERT INTO `tmp_fza_huella_esquema` (`APARTADO`, `OBJETO`, `FIRMA`)
    SELECT IF(V.`TABLA` IS NULL, 'ESTRUCTURA', 'VISTAS'),
           LOWER(CONCAT(C.`TABLE_NAME`, '.', C.`COLUMN_NAME`)),
           IF(V.`TABLA` IS NULL,
              CONCAT(LOWER(C.`DATA_TYPE`), '|',
                     IFNULL(C.`CHARACTER_MAXIMUM_LENGTH`, ''), '|',
                     IFNULL(C.`NUMERIC_PRECISION`, ''), '|',
                     IFNULL(C.`NUMERIC_SCALE`, ''), '|',
                     C.`IS_NULLABLE`),
              'COLUMN')
      FROM `information_schema`.`COLUMNS` C
      LEFT JOIN `tmp_fza_huella_vistas` V
        ON V.`TABLA` = LOWER(C.`TABLE_NAME`)
     WHERE C.`TABLE_SCHEMA` = DATABASE()
       AND C.`TABLE_NAME` NOT LIKE 'tmp\_%'
       AND C.`TABLE_NAME` NOT LIKE 'bak\_%'
       AND C.`TABLE_NAME` NOT LIKE 'fzu\_%'
       AND C.`TABLE_NAME` NOT LIKE 'vu\_%'
       AND C.`TABLE_NAME` NOT LIKE '%\_print';
    DROP TEMPORARY TABLE `tmp_fza_huella_vistas`;
    INSERT INTO `tmp_fza_huella_esquema` (`APARTADO`, `OBJETO`, `FIRMA`)
    SELECT IF(S.`NON_UNIQUE` = 0, 'ESTRUCTURA', 'INDICES'),
           LOWER(CONCAT(S.`TABLE_NAME`, ':', S.`INDEX_NAME`)),
           LOWER(CONCAT(IF(S.`NON_UNIQUE` = 0, 'unique|', 'index|'),
                        GROUP_CONCAT(S.`COLUMN_NAME`
                                     ORDER BY S.`SEQ_IN_INDEX`
                                     SEPARATOR ',')))
      FROM `information_schema`.`STATISTICS` S
     WHERE S.`TABLE_SCHEMA` = DATABASE()
       AND S.`TABLE_NAME` NOT LIKE 'tmp\_%'
       AND S.`TABLE_NAME` NOT LIKE 'bak\_%'
       AND S.`TABLE_NAME` NOT LIKE 'fzu\_%'
     GROUP BY S.`TABLE_NAME`, S.`INDEX_NAME`, S.`NON_UNIQUE`;
END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_VALUE_ON_ZERO' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `PRC_FZA_INVENTARIOS_ACTUALIZAR_TEORICO` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_spanish_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_FZA_INVENTARIOS_ACTUALIZAR_TEORICO`(
  IN p_EMPRESA varchar(10),
  IN p_ALMACEN varchar(10),
  IN p_SERIE varchar(20),
  IN p_NUMERO varchar(20),
  IN p_USUARIO varchar(100)
)
BEGIN
  DECLARE v_TRANSACCION_PROPIA varchar(1) DEFAULT 'N';
  DECLARE v_ESTADO varchar(20);
  DECLARE v_FECHA datetime;
  DECLARE v_SOLO_NEGATIVOS varchar(1) DEFAULT 'N';
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    IF v_TRANSACCION_PROPIA = 'S' THEN
      ROLLBACK;
    END IF;
    RESIGNAL;
  END;
  IF @@in_transaction = 0 THEN
    SET v_TRANSACCION_PROPIA = 'S';
    START TRANSACTION;
  END IF;
  SELECT ESTADO_INV,
         FECHA_INV,
         IFNULL(ESSOLONEGATIVOS_INV, 'N')
    INTO v_ESTADO, v_FECHA, v_SOLO_NEGATIVOS
    FROM fza_inventarios
   WHERE CODIGO_EMP_INV = p_EMPRESA
     AND CODIGO_ALM_INV = p_ALMACEN
     AND SERIE_INV = p_SERIE
     AND NUMERO_INV = p_NUMERO
   FOR UPDATE;
  IF IFNULL(v_ESTADO, '') <> 'ABIERTO' THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'El inventario no esta ABIERTO';
  END IF;
  IF v_SOLO_NEGATIVOS = 'S' THEN
    
    
    UPDATE fza_inventarios_lineas
       SET FECHA_RECUENTO_INVLIN = NULL
     WHERE CODIGO_EMP_INVLIN = p_EMPRESA
       AND CODIGO_ALM_INVLIN = p_ALMACEN
       AND SERIE_INV_INVLIN = p_SERIE
       AND NUMERO_INV_INVLIN = p_NUMERO;
    SET v_FECHA = NOW();
    CALL PRC_FZA_INVENTARIOS_CALCULAR_LINEAS(
      p_EMPRESA, p_ALMACEN, p_SERIE, p_NUMERO, p_USUARIO, v_FECHA);
    
    
    UPDATE fza_inventarios_lineas
       SET CANTIDAD_FISICA_INVLIN = CANTIDAD_TEORICA_INVLIN
     WHERE CODIGO_EMP_INVLIN = p_EMPRESA
       AND CODIGO_ALM_INVLIN = p_ALMACEN
       AND SERIE_INV_INVLIN = p_SERIE
       AND NUMERO_INV_INVLIN = p_NUMERO
       AND CANTIDAD_TEORICA_INVLIN > 0
       AND CANTIDAD_FISICA_INVLIN = 0;
  ELSE
    
    CALL PRC_FZA_INVENTARIOS_LOTES_COMPLETAR(
      p_EMPRESA, p_ALMACEN, p_SERIE, p_NUMERO, p_USUARIO, v_FECHA);
  END IF;
  CALL PRC_FZA_INVENTARIOS_CALCULAR_LINEAS(
    p_EMPRESA, p_ALMACEN, p_SERIE, p_NUMERO, p_USUARIO, v_FECHA);
  IF v_TRANSACCION_PROPIA = 'S' THEN
    COMMIT;
  END IF;
END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_VALUE_ON_ZERO' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `PRC_FZA_INVENTARIOS_APLICAR` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_spanish_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_FZA_INVENTARIOS_APLICAR`(
  IN p_EMPRESA varchar(10),
  IN p_ALMACEN varchar(10),
  IN p_SERIE varchar(20),
  IN p_NUMERO varchar(20),
  IN p_USUARIO varchar(100)
)
BEGIN
  DECLARE v_TRANSACCION_PROPIA varchar(1) DEFAULT 'N';
  DECLARE v_FIN int DEFAULT 0;
  DECLARE v_ESTADO varchar(20);
  DECLARE v_FECHA datetime;
  DECLARE v_SOLO_NEGATIVOS varchar(1) DEFAULT 'N';
  DECLARE v_LINEA varchar(8);
  DECLARE v_ARTICULO varchar(20);
  DECLARE v_SKU varchar(50);
  DECLARE v_TEORICA decimal(19,6);
  DECLARE v_FISICA decimal(19,6);
  DECLARE v_PMP_HIST decimal(19,6);
  DECLARE v_PMP_NUEVO decimal(19,6);
  DECLARE v_RECUENTO datetime;
  DECLARE v_SALIDA datetime;
  DECLARE v_NUM_SALIDA varchar(20);
  DECLARE v_NUM_ENTRADA varchar(20);
  DECLARE v_LOTE varchar(50);
  DECLARE v_CADUCIDAD date;
  DECLARE cur CURSOR FOR
    SELECT LINEA_INVLIN, CODIGO_ART_INVLIN, CODIGO_UNIDAD_INVLIN,
           CANTIDAD_TEORICA_INVLIN, CANTIDAD_FISICA_INVLIN,
           PRECIO_MEDIO_INVLIN, PRECIO_MEDIO_NUEVO_INVLIN,
           FECHA_RECUENTO_INVLIN, IFNULL(LOTE_INVLIN, ''),
           FECHA_CADUCIDAD_INVLIN
      FROM fza_inventarios_lineas
     WHERE CODIGO_EMP_INVLIN = p_EMPRESA
       AND CODIGO_ALM_INVLIN = p_ALMACEN
       AND SERIE_INV_INVLIN = p_SERIE
       AND NUMERO_INV_INVLIN = p_NUMERO;
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_FIN = 1;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    IF v_TRANSACCION_PROPIA = 'S' THEN
      ROLLBACK;
    END IF;
    RESIGNAL;
  END;
  IF @@in_transaction = 0 THEN
    SET v_TRANSACCION_PROPIA = 'S';
    START TRANSACTION;
  END IF;
  SELECT ESTADO_INV,
         FECHA_INV,
         IFNULL(ESSOLONEGATIVOS_INV, 'N')
    INTO v_ESTADO, v_FECHA, v_SOLO_NEGATIVOS
    FROM fza_inventarios
   WHERE CODIGO_EMP_INV = p_EMPRESA
     AND CODIGO_ALM_INV = p_ALMACEN
     AND SERIE_INV = p_SERIE
     AND NUMERO_INV = p_NUMERO
   FOR UPDATE;
  IF IFNULL(v_ESTADO, '') <> 'ABIERTO' THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'El inventario no esta ABIERTO';
  END IF;
  IF v_SOLO_NEGATIVOS = 'S' THEN
    
    
    UPDATE fza_inventarios_lineas
       SET FECHA_RECUENTO_INVLIN = NULL
     WHERE CODIGO_EMP_INVLIN = p_EMPRESA
       AND CODIGO_ALM_INVLIN = p_ALMACEN
       AND SERIE_INV_INVLIN = p_SERIE
       AND NUMERO_INV_INVLIN = p_NUMERO;
    SET v_FECHA = NOW();
    CALL PRC_FZA_INVENTARIOS_CALCULAR_LINEAS(
      p_EMPRESA, p_ALMACEN, p_SERIE, p_NUMERO, p_USUARIO, v_FECHA);
    
    
    UPDATE fza_inventarios_lineas
       SET CANTIDAD_FISICA_INVLIN = CANTIDAD_TEORICA_INVLIN
     WHERE CODIGO_EMP_INVLIN = p_EMPRESA
       AND CODIGO_ALM_INVLIN = p_ALMACEN
       AND SERIE_INV_INVLIN = p_SERIE
       AND NUMERO_INV_INVLIN = p_NUMERO
       AND CANTIDAD_TEORICA_INVLIN > 0
       AND CANTIDAD_FISICA_INVLIN = 0;
  ELSE
    
    CALL PRC_FZA_INVENTARIOS_LOTES_COMPLETAR(
      p_EMPRESA, p_ALMACEN, p_SERIE, p_NUMERO, p_USUARIO, v_FECHA);
  END IF;
  
  
  IF v_SOLO_NEGATIVOS <> 'S' AND EXISTS (
    SELECT 1 FROM fza_inventarios_lineas L
    JOIN fza_movimientos_almacen M
      ON M.CODIGO_ALM_MOV = L.CODIGO_ALM_INVLIN
     AND M.CODIGO_UNIDAD_MOV = L.CODIGO_UNIDAD_INVLIN
     AND M.ESACTIVO_MOV = 'S'
     AND M.FECHA_MOV > IFNULL(L.FECHA_RECUENTO_INVLIN, v_FECHA)
    WHERE L.CODIGO_EMP_INVLIN = p_EMPRESA
      AND L.CODIGO_ALM_INVLIN = p_ALMACEN
      AND L.SERIE_INV_INVLIN = p_SERIE
      AND L.NUMERO_INV_INVLIN = p_NUMERO
  ) THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'Hay movimientos posteriores al recuento. Revise la fecha y hora del recuento antes de regularizar el inventario.';
  END IF;
  CALL PRC_FZA_INVENTARIOS_CALCULAR_LINEAS(
    p_EMPRESA, p_ALMACEN, p_SERIE, p_NUMERO, p_USUARIO, v_FECHA);
  CALL PRC_FZA_MOVIMIENTOS_RECALCULO_PREPARAR();
  
  OPEN cur;
  bucle: LOOP
    FETCH cur INTO v_LINEA, v_ARTICULO, v_SKU, v_TEORICA, v_FISICA,
                   v_PMP_HIST, v_PMP_NUEVO, v_RECUENTO, v_LOTE,
                   v_CADUCIDAD;
    IF v_FIN = 1 THEN
      LEAVE bucle;
    END IF;
    SET v_RECUENTO = IFNULL(v_RECUENTO, v_FECHA);
    
    
    IF v_FISICA <> v_TEORICA OR
       IFNULL(v_PMP_NUEVO, 0) <> IFNULL(v_PMP_HIST, 0) THEN
      SET v_SALIDA = DATE_SUB(v_RECUENTO, INTERVAL 1 SECOND);
      SET v_NUM_SALIDA = CONCAT('IVS', LEFT(SHA2(CONCAT_WS(CHAR(31),
        p_EMPRESA, p_ALMACEN, p_SERIE, p_NUMERO, v_LINEA), 256), 17));
      SET v_NUM_ENTRADA = CONCAT('IVE', LEFT(SHA2(CONCAT_WS(CHAR(31),
        p_EMPRESA, p_ALMACEN, p_SERIE, p_NUMERO, v_LINEA), 256), 17));
      CALL PRC_FZA_MOVIMIENTOS_ALMACEN_INSERT_LOTE(
        v_NUM_SALIDA, 'IN', p_SERIE, p_NUMERO, v_LINEA,
        p_EMPRESA, p_ALMACEN, NULL, v_SKU, 'S', v_TEORICA,
        v_PMP_HIST, v_TEORICA * v_PMP_HIST, p_USUARIO,
        p_ALMACEN, NULL, NULL, NULL, v_ARTICULO, v_LOTE, NULL);
      UPDATE fza_movimientos_almacen
         SET FECHA_MOV = v_SALIDA
       WHERE NUMERO_MOV = v_NUM_SALIDA;
      CALL PRC_FZA_MOVIMIENTOS_ALMACEN_INSERT_LOTE(
        v_NUM_ENTRADA, 'IN', p_SERIE, p_NUMERO, v_LINEA,
        p_EMPRESA, p_ALMACEN, NULL, v_SKU, 'E', v_FISICA,
        v_PMP_NUEVO, v_FISICA * v_PMP_NUEVO, p_USUARIO,
        p_ALMACEN, NULL, NULL, NULL, v_ARTICULO, v_LOTE, v_CADUCIDAD);
      UPDATE fza_movimientos_almacen
         SET FECHA_MOV = v_RECUENTO
       WHERE NUMERO_MOV = v_NUM_ENTRADA;
      CALL PRC_FZA_MOVIMIENTOS_RECALCULO_MARCAR(
        p_EMPRESA, p_ALMACEN, v_SKU, v_SALIDA);
    END IF;
  END LOOP;
  CLOSE cur;
  CALL PRC_FZA_MOVIMIENTOS_RECALCULO_EJECUTAR();
  UPDATE fza_inventarios
     SET ESTADO_INV = 'APLICADO',
         TOTAL_UNIDADES_DIFERENCIA_INV = (
           SELECT IFNULL(SUM(CANTIDAD_DIFERENCIA_INVLIN), 0)
             FROM fza_inventarios_lineas
            WHERE CODIGO_EMP_INVLIN = p_EMPRESA
              AND CODIGO_ALM_INVLIN = p_ALMACEN
              AND SERIE_INV_INVLIN = p_SERIE
              AND NUMERO_INV_INVLIN = p_NUMERO),
         TOTAL_EUROS_DIFERENCIA_INV = (
           SELECT IFNULL(SUM(TOTAL_COSTE_DIFERENCIA_INVLIN), 0)
             FROM fza_inventarios_lineas
            WHERE CODIGO_EMP_INVLIN = p_EMPRESA
              AND CODIGO_ALM_INVLIN = p_ALMACEN
              AND SERIE_INV_INVLIN = p_SERIE
              AND NUMERO_INV_INVLIN = p_NUMERO),
         USUARIO_MODIF = p_USUARIO,
         INSTANTE_MODIF = NOW()
   WHERE CODIGO_EMP_INV = p_EMPRESA
     AND CODIGO_ALM_INV = p_ALMACEN
     AND SERIE_INV = p_SERIE
     AND NUMERO_INV = p_NUMERO;
  IF v_TRANSACCION_PROPIA = 'S' THEN
    COMMIT;
  END IF;
END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_VALUE_ON_ZERO' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `PRC_FZA_INVENTARIOS_CALCULAR_LINEAS` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_spanish_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_FZA_INVENTARIOS_CALCULAR_LINEAS`(
  IN p_EMPRESA varchar(10),
  IN p_ALMACEN varchar(10),
  IN p_SERIE varchar(20),
  IN p_NUMERO varchar(20),
  IN p_USUARIO varchar(100),
  IN p_FECHA_DEFECTO datetime
)
BEGIN
  DECLARE v_FIN int DEFAULT 0;
  DECLARE v_LINEA varchar(8);
  DECLARE v_SKU varchar(50);
  DECLARE v_FISICA decimal(19,6);
  DECLARE v_PMP_NUEVO decimal(19,6);
  DECLARE v_ES_CORREGIDO varchar(1);
  DECLARE v_RECUENTO datetime;
  DECLARE v_STOCK decimal(19,6);
  DECLARE v_PMP decimal(19,6);
  DECLARE v_LOTE varchar(50);
  DECLARE cur CURSOR FOR
    SELECT LINEA_INVLIN, CODIGO_UNIDAD_INVLIN, CANTIDAD_FISICA_INVLIN,
           PRECIO_MEDIO_NUEVO_INVLIN,
           ESPRECIO_MEDIO_CORREGIDO_INVLIN, FECHA_RECUENTO_INVLIN,
           IFNULL(LOTE_INVLIN, '')
      FROM fza_inventarios_lineas
     WHERE CODIGO_EMP_INVLIN = p_EMPRESA
       AND CODIGO_ALM_INVLIN = p_ALMACEN
       AND SERIE_INV_INVLIN = p_SERIE
       AND NUMERO_INV_INVLIN = p_NUMERO;
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_FIN = 1;
  OPEN cur;
  bucle: LOOP
    FETCH cur INTO v_LINEA, v_SKU, v_FISICA, v_PMP_NUEVO,
                   v_ES_CORREGIDO, v_RECUENTO, v_LOTE;
    IF v_FIN = 1 THEN
      LEAVE bucle;
    END IF;
    SET v_RECUENTO = IFNULL(v_RECUENTO, p_FECHA_DEFECTO);
    
    
    IF v_LOTE <> '' OR EXISTS (
         SELECT 1
           FROM fza_articulos_stockactual S
          WHERE S.CODIGO_ALM_STK = p_ALMACEN
            AND S.CODIGO_UNIDAD_STK = v_SKU
            AND S.LOTE_STK <> '')
       OR EXISTS (
         SELECT 1
           FROM fza_articulos_skus K
           JOIN fza_articulos A
             ON A.CODIGO_ART_ART = K.CODIGO_ART_SKU
          WHERE K.CODIGO_UNIDAD_SKU = v_SKU
            AND IFNULL(A.TIPO_TRAZABILIDAD_ART, 'NINGUNA') <> 'NINGUNA')
       OR EXISTS (
         SELECT 1
           FROM fza_inventarios_lineas O
          WHERE O.CODIGO_EMP_INVLIN = p_EMPRESA
            AND O.CODIGO_ALM_INVLIN = p_ALMACEN
            AND O.SERIE_INV_INVLIN = p_SERIE
            AND O.NUMERO_INV_INVLIN = p_NUMERO
            AND O.CODIGO_UNIDAD_INVLIN = v_SKU
            AND IFNULL(O.LOTE_INVLIN, '') <> '') THEN
      IF EXISTS (
           SELECT 1
             FROM fza_inventarios_lineas O
            WHERE O.CODIGO_EMP_INVLIN = p_EMPRESA
              AND O.CODIGO_ALM_INVLIN = p_ALMACEN
              AND O.SERIE_INV_INVLIN = p_SERIE
              AND O.NUMERO_INV_INVLIN = p_NUMERO
              AND O.CODIGO_UNIDAD_INVLIN = v_SKU
              AND IFNULL(O.LOTE_INVLIN, '') = v_LOTE
              AND CAST(O.LINEA_INVLIN AS UNSIGNED) <
                  CAST(v_LINEA AS UNSIGNED)) THEN
        SET v_STOCK = 0;
      ELSE
        SELECT IFNULL(SUM(IF(TIPO_MOV = 'E', CANTIDAD_MOV, -CANTIDAD_MOV)), 0)
          INTO v_STOCK
          FROM fza_movimientos_almacen
         WHERE CODIGO_ALM_MOV = p_ALMACEN
           AND CODIGO_UNIDAD_MOV = v_SKU
           AND IFNULL(LOTE_MOV, '') = v_LOTE
           AND IFNULL(FECHA_MOV, '1000-01-01 00:00:00') <= v_RECUENTO
           AND ESACTIVO_MOV = 'S';
      END IF;
    ELSE
      SELECT IFNULL(SUM(IF(TIPO_MOV = 'E', CANTIDAD_MOV, -CANTIDAD_MOV)), 0)
        INTO v_STOCK
        FROM fza_movimientos_almacen
       WHERE CODIGO_ALM_MOV = p_ALMACEN
         AND CODIGO_UNIDAD_MOV = v_SKU
         AND IFNULL(FECHA_MOV, '1000-01-01 00:00:00') <= v_RECUENTO
         AND ESACTIVO_MOV = 'S';
    END IF;
    SET v_PMP = IFNULL((
      SELECT PRECIO_MEDIO_MOV
        FROM fza_movimientos_almacen
       WHERE CODIGO_ALM_MOV = p_ALMACEN
         AND CODIGO_UNIDAD_MOV = v_SKU
         AND IFNULL(FECHA_MOV, '1000-01-01 00:00:00') <= v_RECUENTO
         AND ESACTIVO_MOV = 'S'
       ORDER BY IFNULL(FECHA_MOV, '1000-01-01 00:00:00') DESC,
                IFNULL(INSTANTE_ALTA, '1000-01-01 00:00:00') DESC,
                NUMERO_MOV DESC
       LIMIT 1), 0);
    IF IFNULL(v_ES_CORREGIDO, 'N') <> 'S' THEN
      SET v_PMP_NUEVO = v_PMP;
    END IF;
    UPDATE fza_inventarios_lineas
       SET CANTIDAD_TEORICA_INVLIN = v_STOCK,
           PRECIO_MEDIO_INVLIN = v_PMP,
           PRECIO_MEDIO_NUEVO_INVLIN = IFNULL(v_PMP_NUEVO, 0),
           CANTIDAD_DIFERENCIA_INVLIN = v_FISICA - v_STOCK,
           TOTAL_COSTE_DIFERENCIA_INVLIN = ROUND(
             (v_FISICA * IFNULL(v_PMP_NUEVO, 0)) - (v_STOCK * v_PMP), 2),
           FECHA_RECUENTO_INVLIN = v_RECUENTO,
           USUARIO_MODIF = p_USUARIO,
           INSTANTE_MODIF = NOW()
     WHERE CODIGO_EMP_INVLIN = p_EMPRESA
       AND CODIGO_ALM_INVLIN = p_ALMACEN
       AND SERIE_INV_INVLIN = p_SERIE
       AND NUMERO_INV_INVLIN = p_NUMERO
       AND LINEA_INVLIN = v_LINEA;
  END LOOP;
  CLOSE cur;
  UPDATE fza_inventarios i
     SET TOTAL_UNIDADES_DIFERENCIA_INV = (
           SELECT IFNULL(SUM(CANTIDAD_DIFERENCIA_INVLIN), 0)
             FROM fza_inventarios_lineas
            WHERE CODIGO_EMP_INVLIN = p_EMPRESA
              AND CODIGO_ALM_INVLIN = p_ALMACEN
              AND SERIE_INV_INVLIN = p_SERIE
              AND NUMERO_INV_INVLIN = p_NUMERO),
         TOTAL_EUROS_DIFERENCIA_INV = (
           SELECT IFNULL(SUM(TOTAL_COSTE_DIFERENCIA_INVLIN), 0)
             FROM fza_inventarios_lineas
            WHERE CODIGO_EMP_INVLIN = p_EMPRESA
              AND CODIGO_ALM_INVLIN = p_ALMACEN
              AND SERIE_INV_INVLIN = p_SERIE
              AND NUMERO_INV_INVLIN = p_NUMERO),
         USUARIO_MODIF = p_USUARIO,
         INSTANTE_MODIF = NOW()
   WHERE CODIGO_EMP_INV = p_EMPRESA
     AND CODIGO_ALM_INV = p_ALMACEN
     AND SERIE_INV = p_SERIE
     AND NUMERO_INV = p_NUMERO;
END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_VALUE_ON_ZERO' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `PRC_FZA_INVENTARIOS_ELIMINAR_REGUL` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_spanish_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_FZA_INVENTARIOS_ELIMINAR_REGUL`(
  IN p_EMPRESA varchar(10),
  IN p_ALMACEN varchar(10),
  IN p_SERIE varchar(20),
  IN p_NRO varchar(20),
  IN p_USUARIO varchar(100)
)
BEGIN
  DECLARE v_CIERRE_ESTABLE varchar(1) DEFAULT 'N';
  DECLARE v_INTENTOS_CIERRE int DEFAULT 0;
  DECLARE v_ESTADO varchar(20);
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    RESIGNAL;
  END;
  IF @@in_transaction <> 0 THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT =
        'ELIMINAR_REGUL requiere una conexion sin transaccion';
  END IF;
  cierre: WHILE v_CIERRE_ESTABLE <> 'S' AND
                v_INTENTOS_CIERRE < 3 DO
    CALL PRC_FZA_MOVIMIENTOS_RECALCULO_PREPARAR();
    CALL PRC_FZA_MOVIMIENTOS_RECALCULO_MARCAR_DOCUMENTO(
      'IN', p_SERIE, p_NRO);
    CALL PRC_FZA_MOVIMIENTOS_RECALCULO_CIERRE_PREPARAR();
    
    
    COMMIT;
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED;
    START TRANSACTION;
    SELECT ESTADO_INV INTO v_ESTADO
      FROM fza_inventarios
     WHERE CODIGO_EMP_INV = p_EMPRESA
       AND CODIGO_ALM_INV = p_ALMACEN
       AND SERIE_INV = p_SERIE
       AND NUMERO_INV = p_NRO
     FOR UPDATE;
    IF IFNULL(v_ESTADO, '') <> 'APLICADO' THEN
      SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'El inventario no esta APLICADO';
    END IF;
    CALL PRC_FZA_MOVIMIENTOS_RECALCULO_CIERRE_BLOQUEAR(
      LEFT(COALESCE(NULLIF(TRIM(p_USUARIO), ''), 'DELETE_IN'), 50));
    CALL PRC_FZA_MOVIMIENTOS_RECALCULO_MARCAR_DOCUMENTO(
      'IN', p_SERIE, p_NRO);
    CALL PRC_FZA_MOVIMIENTOS_RECALCULO_CIERRE_VALIDAR(
      v_CIERRE_ESTABLE);
    IF v_CIERRE_ESTABLE <> 'S' THEN
      ROLLBACK;
    END IF;
    SET v_INTENTOS_CIERRE = v_INTENTOS_CIERRE + 1;
  END WHILE cierre;
  IF v_CIERRE_ESTABLE <> 'S' THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT =
        'El cierre de traspasos no se estabilizo al eliminar el inventario';
  END IF;
  CALL PRC_FZA_MOVIMIENTOS_RECALCULO_RAICES_RESTAURAR();
  CALL PRC_FZA_STOCK_ACUMULADOS_PREPARAR();
  INSERT INTO tmp_stock_acumulados_mov (numero_mov)
  SELECT NUMERO_MOV
    FROM fza_movimientos_almacen
   WHERE TIPO_DOC_MOV = 'IN'
     AND SERIE_DOC_MOV = p_SERIE
     AND NUMERO_DOC_MOV = p_NRO;
  CALL PRC_FZA_STOCK_ACUMULADOS_APLICAR(-1);
  DELETE FROM fza_movimientos_almacen
   WHERE TIPO_DOC_MOV = 'IN'
     AND SERIE_DOC_MOV = p_SERIE
     AND NUMERO_DOC_MOV = p_NRO;
  CALL PRC_FZA_MOVIMIENTOS_RECALCULO_EJECUTAR();
  UPDATE fza_inventarios
     SET ESTADO_INV = 'ABIERTO',
         USUARIO_MODIF = p_USUARIO,
         INSTANTE_MODIF = NOW()
   WHERE CODIGO_EMP_INV = p_EMPRESA
     AND CODIGO_ALM_INV = p_ALMACEN
     AND SERIE_INV = p_SERIE
     AND NUMERO_INV = p_NRO;
  COMMIT;
END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `PRC_FZA_INVENTARIOS_LOTES_COMPLETAR` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_spanish_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_FZA_INVENTARIOS_LOTES_COMPLETAR`(
  IN p_EMPRESA varchar(10),
  IN p_ALMACEN varchar(10),
  IN p_SERIE varchar(20),
  IN p_NUMERO varchar(20),
  IN p_USUARIO varchar(100),
  IN p_FECHA_DEFECTO datetime
)
BEGIN
  
  
  
  DECLARE v_LINEA bigint DEFAULT 0;
  DROP TEMPORARY TABLE IF EXISTS tmp_fza_inv_lotes_skus;
  CREATE TEMPORARY TABLE tmp_fza_inv_lotes_skus (
    sku varchar(50) NOT NULL,
    articulo varchar(20) NOT NULL,
    descripcion varchar(200) NULL,
    pivote int NOT NULL DEFAULT 0,
    recuento datetime NOT NULL,
    PRIMARY KEY (sku)
  ) ENGINE=InnoDB;
  INSERT INTO tmp_fza_inv_lotes_skus
    (sku, articulo, descripcion, pivote, recuento)
  SELECT X.sku, X.articulo, X.descripcion, X.pivote, X.recuento
    FROM (
      SELECT L.CODIGO_UNIDAD_INVLIN AS sku,
             MAX(L.CODIGO_ART_INVLIN) AS articulo,
             MAX(L.DESCRIPCION_ARTICULO_INVLIN) AS descripcion,
             MAX(L.ID_AC_PIVOT_INVLIN) AS pivote,
             MIN(IFNULL(L.FECHA_RECUENTO_INVLIN, p_FECHA_DEFECTO))
               AS recuento,
             MAX(IFNULL(L.LOTE_INVLIN, '')) AS lote_maximo
        FROM fza_inventarios_lineas L
       WHERE L.CODIGO_EMP_INVLIN = p_EMPRESA
         AND L.CODIGO_ALM_INVLIN = p_ALMACEN
         AND L.SERIE_INV_INVLIN = p_SERIE
         AND L.NUMERO_INV_INVLIN = p_NUMERO
         AND IFNULL(L.LOTE_INVLIN, '') = ''
       GROUP BY L.CODIGO_UNIDAD_INVLIN
    ) X
   WHERE X.recuento IS NOT NULL
     AND (X.lote_maximo <> ''
          OR EXISTS (
               SELECT 1
                 FROM fza_articulos_stockactual S
                WHERE S.CODIGO_ALM_STK = p_ALMACEN
                  AND S.CODIGO_UNIDAD_STK = X.sku
                  AND S.LOTE_STK <> '')
          OR EXISTS (
               SELECT 1
                 FROM fza_articulos_skus K
                 JOIN fza_articulos A
                   ON A.CODIGO_ART_ART = K.CODIGO_ART_SKU
                WHERE K.CODIGO_UNIDAD_SKU = X.sku
                  AND IFNULL(A.TIPO_TRAZABILIDAD_ART, 'NINGUNA') <>
                      'NINGUNA'));
  IF EXISTS (SELECT 1 FROM tmp_fza_inv_lotes_skus) THEN
    DROP TEMPORARY TABLE IF EXISTS tmp_fza_inv_lotes_faltan;
    CREATE TEMPORARY TABLE tmp_fza_inv_lotes_faltan (
      sku varchar(50) NOT NULL,
      lote varchar(50) NOT NULL,
      PRIMARY KEY (sku, lote)
    ) ENGINE=InnoDB;
    INSERT INTO tmp_fza_inv_lotes_faltan (sku, lote)
    SELECT K.sku, IFNULL(M.LOTE_MOV, '')
      FROM tmp_fza_inv_lotes_skus K
      JOIN fza_movimientos_almacen M
        ON M.CODIGO_ALM_MOV = p_ALMACEN
       AND M.CODIGO_UNIDAD_MOV = K.sku
       AND M.ESACTIVO_MOV = 'S'
       AND IFNULL(M.FECHA_MOV, '1000-01-01 00:00:00') <= K.recuento
     GROUP BY K.sku, IFNULL(M.LOTE_MOV, '')
    HAVING SUM(IF(M.TIPO_MOV = 'E', M.CANTIDAD_MOV, -M.CANTIDAD_MOV)) <> 0;
    DELETE F
      FROM tmp_fza_inv_lotes_faltan F
      JOIN fza_inventarios_lineas L
        ON L.CODIGO_EMP_INVLIN = p_EMPRESA
       AND L.CODIGO_ALM_INVLIN = p_ALMACEN
       AND L.SERIE_INV_INVLIN = p_SERIE
       AND L.NUMERO_INV_INVLIN = p_NUMERO
       AND L.CODIGO_UNIDAD_INVLIN = F.sku
       AND IFNULL(L.LOTE_INVLIN, '') = F.lote;
    SELECT IFNULL(MAX(CAST(L.LINEA_INVLIN AS UNSIGNED)), 0)
      INTO v_LINEA
      FROM fza_inventarios_lineas L
     WHERE L.CODIGO_EMP_INVLIN = p_EMPRESA
       AND L.CODIGO_ALM_INVLIN = p_ALMACEN
       AND L.SERIE_INV_INVLIN = p_SERIE
       AND L.NUMERO_INV_INVLIN = p_NUMERO;
    INSERT INTO fza_inventarios_lineas (
      CODIGO_EMP_INVLIN,
      CODIGO_ALM_INVLIN,
      SERIE_INV_INVLIN,
      NUMERO_INV_INVLIN,
      LINEA_INVLIN,
      CODIGO_ART_INVLIN,
      CODIGO_UNIDAD_INVLIN,
      ID_AC_PIVOT_INVLIN,
      LOTE_INVLIN,
      FECHA_CADUCIDAD_INVLIN,
      DESCRIPCION_ARTICULO_INVLIN,
      CANTIDAD_FISICA_INVLIN,
      FECHA_RECUENTO_INVLIN,
      ESPRECIO_MEDIO_CORREGIDO_INVLIN,
      INSTANTE_ALTA,
      USUARIO_ALTA,
      USUARIO_MODIF
    )
    SELECT p_EMPRESA,
           p_ALMACEN,
           p_SERIE,
           p_NUMERO,
           LPAD(N.linea, GREATEST(4, CHAR_LENGTH(N.linea)), '0'),
           K.articulo,
           N.sku,
           K.pivote,
           N.lote,
           C.FECHA_CADUCIDAD_LOT,
           K.descripcion,
           0,
           K.recuento,
           'N',
           NOW(),
           p_USUARIO,
           p_USUARIO
      FROM (
        SELECT F.sku,
               F.lote,
               CAST(v_LINEA + ROW_NUMBER() OVER (ORDER BY F.sku, F.lote)
                    AS char) AS linea
          FROM tmp_fza_inv_lotes_faltan F
      ) N
      JOIN tmp_fza_inv_lotes_skus K
        ON K.sku = N.sku
      LEFT JOIN fza_articulos_lotes C
        ON C.CODIGO_UNIDAD_LOT = N.sku
       AND C.LOTE_LOT = N.lote;
    DROP TEMPORARY TABLE IF EXISTS tmp_fza_inv_lotes_faltan;
  END IF;
  DROP TEMPORARY TABLE IF EXISTS tmp_fza_inv_lotes_skus;
END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
