/*!50003 DROP PROCEDURE IF EXISTS `PRC_FZA_LOTES_ASEGURAR` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_spanish_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_FZA_LOTES_ASEGURAR`(
  IN p_CODIGO_UNIDAD varchar(50),
  IN p_LOTE varchar(50),
  IN p_TIPO_LOT varchar(1),
  IN p_FECHA_CADUCIDAD date,
  IN p_FECHA_ENTRADA date,
  IN p_CODIGO_PRV varchar(20),
  IN p_TIPO_DOC varchar(5),
  IN p_SERIE_DOC varchar(20),
  IN p_NUMERO_DOC varchar(20),
  IN p_COMPROBAR_STOCK varchar(1),
  IN p_USUARIO varchar(50),
  OUT p_RESULTADO varchar(20)
)
cuerpo: BEGIN
  DECLARE v_LOTE varchar(50) DEFAULT '';
  DECLARE v_TIPO varchar(1) DEFAULT NULL;
  DECLARE v_EXISTE int DEFAULT 0;
  DECLARE v_USUARIO varchar(50);
  DECLARE v_CADUCIDAD date DEFAULT NULL;
  DECLARE v_MENSAJE varchar(128);
  DECLARE v_PROVEEDOR varchar(20);
  SET p_RESULTADO = NULL;
  SET v_LOTE = TRIM(IFNULL(p_LOTE, ''));
  IF v_LOTE = '' THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'No se puede dar de alta un lote vacio';
  END IF;
  IF NULLIF(TRIM(p_CODIGO_UNIDAD), '') IS NULL THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'No se puede dar de alta un lote sin SKU';
  END IF;
  SET v_USUARIO = LEFT(COALESCE(NULLIF(TRIM(p_USUARIO), ''), 'SISTEMA'), 50);
  SELECT COUNT(*), MAX(L.TIPO_LOT)
    INTO v_EXISTE, v_TIPO
    FROM fza_articulos_lotes L
   WHERE L.CODIGO_UNIDAD_LOT = p_CODIGO_UNIDAD
     AND L.LOTE_LOT = v_LOTE
     FOR UPDATE;
  IF v_EXISTE = 0 THEN
    SET v_TIPO = NULLIF(TRIM(p_TIPO_LOT), '');
    IF v_TIPO IS NULL THEN
      SELECT CASE MAX(A.TIPO_TRAZABILIDAD_ART)
               WHEN 'SERIE' THEN 'S'
               WHEN 'TEMPORADA' THEN 'T'
               ELSE 'L'
             END
        INTO v_TIPO
        FROM fza_articulos_skus K
        JOIN fza_articulos A
          ON A.CODIGO_ART_ART = K.CODIGO_ART_SKU
       WHERE K.CODIGO_UNIDAD_SKU = p_CODIGO_UNIDAD;
    END IF;
  END IF;
  IF v_TIPO = 'S' THEN
    IF EXISTS (
      SELECT 1
        FROM fza_articulos_lotes L
       WHERE L.LOTE_LOT = v_LOTE
         AND L.TIPO_LOT = 'S'
         AND L.CODIGO_UNIDAD_LOT <> p_CODIGO_UNIDAD
    ) THEN
      SET p_RESULTADO = 'SERIE_OTRO_ARTICULO';
      LEAVE cuerpo;
    END IF;
    IF IFNULL(p_COMPROBAR_STOCK, 'S') = 'S' AND (
      SELECT IFNULL(SUM(S.CANTIDAD_STK), 0)
        FROM fza_articulos_stockactual S
       WHERE S.CODIGO_UNIDAD_STK = p_CODIGO_UNIDAD
         AND S.LOTE_STK = v_LOTE
    ) > 0 THEN
      SET p_RESULTADO = 'SERIE_EN_STOCK';
      LEAVE cuerpo;
    END IF;
  END IF;
  IF v_EXISTE = 0 THEN
    INSERT IGNORE INTO fza_articulos_lotes (
      CODIGO_UNIDAD_LOT, LOTE_LOT, TIPO_LOT, FECHA_CADUCIDAD_LOT,
      FECHA_ENTRADA_LOT, CODIGO_PRV_LOT, TIPO_DOC_ORIGEN_LOT,
      SERIE_DOC_ORIGEN_LOT, NUMERO_DOC_ORIGEN_LOT, ESACTIVO_LOT,
      INSTANTE_ALTA, USUARIO_ALTA
    ) VALUES (
      p_CODIGO_UNIDAD, v_LOTE, v_TIPO, p_FECHA_CADUCIDAD,
      p_FECHA_ENTRADA, NULLIF(NULLIF(TRIM(p_CODIGO_PRV), ''), '0'),
      NULLIF(TRIM(p_TIPO_DOC), ''), NULLIF(TRIM(p_SERIE_DOC), ''),
      NULLIF(TRIM(p_NUMERO_DOC), ''), 'S',
      NOW(), v_USUARIO
    );
    IF ROW_COUNT() > 0 THEN
      SET p_RESULTADO = 'CREADO';
      LEAVE cuerpo;
    END IF;
  END IF;
  SELECT L.FECHA_CADUCIDAD_LOT, L.CODIGO_PRV_LOT
    INTO v_CADUCIDAD, v_PROVEEDOR
    FROM fza_articulos_lotes L
   WHERE L.CODIGO_UNIDAD_LOT = p_CODIGO_UNIDAD
     AND L.LOTE_LOT = v_LOTE
     FOR UPDATE;
  
  IF NULLIF(NULLIF(TRIM(v_PROVEEDOR), ''), '0') IS NOT NULL
     AND NULLIF(NULLIF(TRIM(p_CODIGO_PRV), ''), '0') IS NOT NULL
     AND TRIM(v_PROVEEDOR) <> TRIM(p_CODIGO_PRV) THEN
    SET v_MENSAJE = CONCAT('El lote ', LEFT(v_LOTE, 30),
      ' ya pertenece al proveedor ', TRIM(v_PROVEEDOR),
      '. Indique otro lote.');
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = v_MENSAJE;
  END IF;
  IF p_FECHA_CADUCIDAD IS NOT NULL AND v_CADUCIDAD IS NOT NULL
     AND p_FECHA_CADUCIDAD <> v_CADUCIDAD THEN
    SET v_MENSAJE = CONCAT('El lote ', LEFT(v_LOTE, 30),
      ' ya caduca el ', DATE_FORMAT(v_CADUCIDAD, '%d/%m/%Y'),
      '. Corrija la caducidad o indique otro lote.');
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = v_MENSAJE;
  END IF;
  UPDATE fza_articulos_lotes L
     SET L.FECHA_CADUCIDAD_LOT = COALESCE(L.FECHA_CADUCIDAD_LOT,
                                          p_FECHA_CADUCIDAD),
         L.FECHA_ENTRADA_LOT = COALESCE(L.FECHA_ENTRADA_LOT, p_FECHA_ENTRADA),
         L.CODIGO_PRV_LOT = COALESCE(
           NULLIF(NULLIF(TRIM(L.CODIGO_PRV_LOT), ''), '0'),
                                     NULLIF(NULLIF(TRIM(p_CODIGO_PRV), ''), '0')),
         L.TIPO_DOC_ORIGEN_LOT = COALESCE(L.TIPO_DOC_ORIGEN_LOT,
                                          NULLIF(TRIM(p_TIPO_DOC), '')),
         L.SERIE_DOC_ORIGEN_LOT = COALESCE(L.SERIE_DOC_ORIGEN_LOT,
                                           NULLIF(TRIM(p_SERIE_DOC), '')),
         L.NUMERO_DOC_ORIGEN_LOT = COALESCE(L.NUMERO_DOC_ORIGEN_LOT,
                                            NULLIF(TRIM(p_NUMERO_DOC), '')),
         L.ESACTIVO_LOT = 'S',
         L.INSTANTE_MODIF = NOW(),
         L.USUARIO_MODIF = v_USUARIO
   WHERE L.CODIGO_UNIDAD_LOT = p_CODIGO_UNIDAD
     AND L.LOTE_LOT = v_LOTE;
  SET p_RESULTADO = 'ACTUALIZADO';
END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
