/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_spanish_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_FZA_LOTES_BUSCAR`(
  IN p_LOTE varchar(50)
)
BEGIN
  
  
  
  SELECT L.CODIGO_UNIDAD_LOT,
         K.CODIGO_ART_SKU,
         A.DESCRIPCION_ART,
         L.TIPO_LOT,
         L.FECHA_CADUCIDAD_LOT,
         L.FECHA_ENTRADA_LOT,
         L.CODIGO_PRV_LOT,
         L.TIPO_DOC_ORIGEN_LOT,
         L.SERIE_DOC_ORIGEN_LOT,
         L.NUMERO_DOC_ORIGEN_LOT,
         L.ESACTIVO_LOT,
         S.CODIGO_ALM_STK,
         S.CANTIDAD_STK
    FROM fza_articulos_lotes L
    LEFT JOIN fza_articulos_skus K
      ON K.CODIGO_UNIDAD_SKU = L.CODIGO_UNIDAD_LOT
    LEFT JOIN fza_articulos A
      ON A.CODIGO_ART_ART = K.CODIGO_ART_SKU
    LEFT JOIN fza_articulos_stockactual S
      ON S.CODIGO_UNIDAD_STK = L.CODIGO_UNIDAD_LOT
     AND S.LOTE_STK = L.LOTE_LOT
     AND S.CANTIDAD_STK <> 0
   WHERE L.LOTE_LOT = TRIM(IFNULL(p_LOTE, ''))
   ORDER BY L.CODIGO_UNIDAD_LOT, S.CODIGO_ALM_STK;
END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
