/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_spanish_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_FZA_LOTES_HISTORICO`(
  IN p_CODIGO_UNIDAD varchar(50),
  IN p_LOTE varchar(50)
)
BEGIN
  
  
  
  
  SELECT M.NUMERO_MOV,
         M.FECHA_MOV,
         M.TIPO_DOC_MOV,
         M.SERIE_DOC_MOV,
         M.NUMERO_DOC_MOV,
         M.LINEA_MOV,
         M.CODIGO_UNIDAD_MOV,
         M.CODIGO_ART_MOV,
         M.CODIGO_ALM_MOV,
         M.CODIGO_ALM_CONTRA_MOV,
         M.TIPO_MOV,
         M.CANTIDAD_MOV,
         M.FECHA_CADUCIDAD_MOV,
         COALESCE(NULLIF(FS.CODIGO_CLI_FAC, ''), M.CODIGO_CLI_MOV)
           AS CODIGO_CLI_MOV,
         C.RAZON_SOCIAL_CLI,
         FR.SERIE_FAC_FACREL,
         FR.NUMERO_FAC_FACREL,
         COALESCE(ALBC.CODIGO_PRV_ALBC, DEVC.CODIGO_PRV_DEVC,
                  FACC.CODIGO_PRV_FACC) AS CODIGO_PRV,
         COALESCE(NULLIF(TRIM(P.RAZON_SOCIAL_PRV), ''), P.NOMBRE_PRV)
           AS NOMBRE_PRV
    FROM fza_movimientos_almacen M
    LEFT JOIN fza_facturas_relaciones FR
      ON FR.ID_FACREL = (
           SELECT MAX(R.ID_FACREL)
             FROM fza_facturas_relaciones R
             JOIN fza_facturas FN
               ON FN.SERIE_FAC = R.SERIE_FAC_FACREL
              AND FN.NUMERO_FAC = R.NUMERO_FAC_FACREL
            WHERE M.TIPO_DOC_MOV IN ('VE', 'FC')
              AND R.SERIE_FAC_ORIGEN_FACREL = M.SERIE_DOC_MOV
              AND R.NUMERO_FAC_ORIGEN_FACREL = M.NUMERO_DOC_MOV
              AND R.TIPO_RELACION_FACREL = 'SUSTITUYE'
              AND FN.CODIGO_EMP_FAC = M.CODIGO_EMP_MOV
              AND COALESCE(FN.FASE_FAC, '') NOT IN (
                 'BORRADOR', 'ERROR_BORRADOR', 'CANCELADA', 'SIN_VERIF_ANULADA',
                 'VERIFACTU_ANULADA', 'NOVERIFACTU_ANULADA'))
    LEFT JOIN fza_facturas FS
      ON FS.SERIE_FAC = FR.SERIE_FAC_FACREL
     AND FS.NUMERO_FAC = FR.NUMERO_FAC_FACREL
    LEFT JOIN fza_clientes C
      ON C.CODIGO_CLI_CLI = COALESCE(NULLIF(FS.CODIGO_CLI_FAC, ''),
                                     NULLIF(M.CODIGO_CLI_MOV, ''))
    LEFT JOIN fza_albaranes_compra ALBC
      ON M.TIPO_DOC_MOV = 'AC'
     AND ALBC.SERIE_ALBC = M.SERIE_DOC_MOV
     AND ALBC.NUMERO_ALBC = M.NUMERO_DOC_MOV
    LEFT JOIN fza_devoluciones_compra DEVC
      ON M.TIPO_DOC_MOV = 'DC'
     AND DEVC.SERIE_DEVC = M.SERIE_DOC_MOV
     AND DEVC.NUMERO_DEVC = M.NUMERO_DOC_MOV
    LEFT JOIN fza_facturas_compra FACC
      ON M.TIPO_DOC_MOV = 'FP'
     AND FACC.SERIE_FACC = M.SERIE_DOC_MOV
     AND FACC.NUMERO_FACC = M.NUMERO_DOC_MOV
    LEFT JOIN fza_proveedores P
      ON P.CODIGO_PRV_PRV = COALESCE(ALBC.CODIGO_PRV_ALBC,
                                     DEVC.CODIGO_PRV_DEVC,
                                     FACC.CODIGO_PRV_FACC)
   WHERE M.LOTE_MOV = TRIM(IFNULL(p_LOTE, ''))
     AND M.ESACTIVO_MOV = 'S'
     AND TRIM(IFNULL(p_LOTE, '')) <> ''
     AND M.CODIGO_UNIDAD_MOV IN (
           SELECT p_CODIGO_UNIDAD
            WHERE NULLIF(TRIM(p_CODIGO_UNIDAD), '') IS NOT NULL
           UNION
           SELECT L.CODIGO_UNIDAD_LOT
             FROM fza_articulos_lotes L
            WHERE NULLIF(TRIM(p_CODIGO_UNIDAD), '') IS NULL
              AND L.LOTE_LOT = TRIM(IFNULL(p_LOTE, '')))
   ORDER BY IFNULL(M.FECHA_MOV, '1000-01-01 00:00:00'),
            IFNULL(M.INSTANTE_ALTA, '1000-01-01 00:00:00'),
            M.NUMERO_MOV;
END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_VALUE_ON_ZERO' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `PRC_FZA_LOTES_MIGRAR_TEMPORADA` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_spanish_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_FZA_LOTES_MIGRAR_TEMPORADA`(
  IN p_EMPRESA varchar(20),
  IN p_ALMACEN varchar(10),
  IN p_CONFIRMAR varchar(2),
  IN p_USUARIO varchar(50),
  OUT p_DOCUMENTO varchar(20),
  OUT p_MOVIDOS int
)
BEGIN
  DECLARE v_FIN int DEFAULT 0;
  DECLARE v_ALMACEN varchar(10);
  DECLARE v_EMPRESA varchar(20);
  DECLARE v_SKU varchar(50);
  DECLARE v_ARTICULO varchar(20);
  DECLARE v_CANTIDAD decimal(19,6);
  DECLARE v_PMP decimal(19,6);
  DECLARE v_TEMPORADA varchar(50);
  DECLARE v_ENTRADA date;
  DECLARE v_RESULTADO varchar(20);
  DECLARE v_LINEA int DEFAULT 0;
  DECLARE v_USUARIO varchar(50);
  DECLARE cur_FILAS CURSOR FOR
    SELECT S.CODIGO_ALM_STK, ALM.CODIGO_EMP_ALM, S.CODIGO_UNIDAD_STK,
           K.CODIGO_ART_SKU, S.CANTIDAD_STK, S.PRECIO_MEDIO_STK
      FROM fza_articulos_stockactual S
      JOIN fza_almacenes ALM
        ON ALM.CODIGO_ALM_ALM = S.CODIGO_ALM_STK
      JOIN fza_articulos_skus K
        ON K.CODIGO_UNIDAD_SKU = S.CODIGO_UNIDAD_STK
      JOIN fza_articulos A
        ON A.CODIGO_ART_ART = K.CODIGO_ART_SKU
     WHERE A.TIPO_TRAZABILIDAD_ART = 'TEMPORADA'
       AND S.LOTE_STK = ''
       AND S.CANTIDAD_STK > 0
       AND (NULLIF(p_EMPRESA, '') IS NULL OR ALM.CODIGO_EMP_ALM = p_EMPRESA)
       AND (NULLIF(p_ALMACEN, '') IS NULL OR S.CODIGO_ALM_STK = p_ALMACEN)
     ORDER BY S.CODIGO_ALM_STK, S.CODIGO_UNIDAD_STK;
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_FIN = 1;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    RESIGNAL;
  END;
  IF IFNULL(p_CONFIRMAR, '') <> 'SI' THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'Migracion de temporadas: falta confirmar con SI';
  END IF;
  IF @@in_transaction <> 0 THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'Migracion de temporadas: transaccion abierta';
  END IF;
  SET v_USUARIO = LEFT(COALESCE(NULLIF(TRIM(p_USUARIO), ''), 'SISTEMA'), 50);
  SET p_DOCUMENTO = DATE_FORMAT(NOW(), '%Y%m%d%H%i%s');
  SET p_MOVIDOS = 0;
  START TRANSACTION;
  OPEN cur_FILAS;
  bucle: LOOP
    FETCH cur_FILAS INTO v_ALMACEN, v_EMPRESA, v_SKU, v_ARTICULO,
                         v_CANTIDAD, v_PMP;
    IF v_FIN = 1 THEN
      LEAVE bucle;
    END IF;
    CALL PRC_FZA_LOTES_TEMPORADA_DEFECTO(v_SKU, NULL, NULL, NULL,
                                         v_TEMPORADA);
    IF v_TEMPORADA IS NOT NULL THEN
      SELECT DATE(MIN(M.FECHA_MOV))
        INTO v_ENTRADA
        FROM fza_movimientos_almacen M
       WHERE M.CODIGO_ALM_MOV = v_ALMACEN
         AND M.CODIGO_UNIDAD_MOV = v_SKU
         AND M.ESACTIVO_MOV = 'S'
         AND M.TIPO_MOV = 'E';
      CALL PRC_FZA_LOTES_ASEGURAR(v_SKU, v_TEMPORADA, 'T', NULL, v_ENTRADA,
        NULL, 'LT', 'MIGRACION', p_DOCUMENTO, 'N', v_USUARIO, v_RESULTADO);
      SET v_LINEA = v_LINEA + 1;
      CALL PRC_FZA_MOVIMIENTOS_ALMACEN_INSERT_LOTE(
        CONCAT('LTS', LEFT(SHA2(CONCAT_WS(CHAR(31), p_DOCUMENTO, v_ALMACEN,
          v_SKU), 256), 17)),
        'LT', 'MIGRACION', p_DOCUMENTO, LPAD(v_LINEA, 4, '0'), v_EMPRESA,
        v_ALMACEN, NULL, v_SKU, 'S', v_CANTIDAD, v_PMP,
        v_CANTIDAD * v_PMP, v_USUARIO, v_ALMACEN, NULL, NULL, NULL,
        v_ARTICULO, '', NULL);
      CALL PRC_FZA_MOVIMIENTOS_ALMACEN_INSERT_LOTE(
        CONCAT('LTE', LEFT(SHA2(CONCAT_WS(CHAR(31), p_DOCUMENTO, v_ALMACEN,
          v_SKU), 256), 17)),
        'LT', 'MIGRACION', p_DOCUMENTO, LPAD(v_LINEA, 4, '0'), v_EMPRESA,
        v_ALMACEN, NULL, v_SKU, 'E', v_CANTIDAD, v_PMP,
        v_CANTIDAD * v_PMP, v_USUARIO, v_ALMACEN, NULL, NULL, NULL,
        v_ARTICULO, v_TEMPORADA, NULL);
      SET p_MOVIDOS = p_MOVIDOS + 1;
    END IF;
  END LOOP;
  CLOSE cur_FILAS;
  COMMIT;
END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_VALUE_ON_ZERO' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `PRC_FZA_LOTES_MIGRAR_TEMPORADA_PREVIA` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_spanish_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_FZA_LOTES_MIGRAR_TEMPORADA_PREVIA`(
  IN p_EMPRESA varchar(20),
  IN p_ALMACEN varchar(10)
)
BEGIN
  
  DECLARE v_FIN int DEFAULT 0;
  DECLARE v_SKU varchar(50);
  DECLARE v_TEMPORADA varchar(50);
  DECLARE cur_SKUS CURSOR FOR
    SELECT DISTINCT S.CODIGO_UNIDAD_STK
      FROM fza_articulos_stockactual S
      JOIN fza_almacenes ALM
        ON ALM.CODIGO_ALM_ALM = S.CODIGO_ALM_STK
      JOIN fza_articulos_skus K
        ON K.CODIGO_UNIDAD_SKU = S.CODIGO_UNIDAD_STK
      JOIN fza_articulos A
        ON A.CODIGO_ART_ART = K.CODIGO_ART_SKU
     WHERE A.TIPO_TRAZABILIDAD_ART = 'TEMPORADA'
       AND S.LOTE_STK = ''
       AND S.CANTIDAD_STK > 0
       AND (NULLIF(p_EMPRESA, '') IS NULL OR ALM.CODIGO_EMP_ALM = p_EMPRESA)
       AND (NULLIF(p_ALMACEN, '') IS NULL OR S.CODIGO_ALM_STK = p_ALMACEN);
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_FIN = 1;
  DROP TEMPORARY TABLE IF EXISTS tmp_fza_migrar_temporada;
  CREATE TEMPORARY TABLE tmp_fza_migrar_temporada (
    sku varchar(50) NOT NULL,
    temporada varchar(50) NULL,
    PRIMARY KEY (sku)
  ) ENGINE=InnoDB;
  OPEN cur_SKUS;
  bucle: LOOP
    FETCH cur_SKUS INTO v_SKU;
    IF v_FIN = 1 THEN
      LEAVE bucle;
    END IF;
    CALL PRC_FZA_LOTES_TEMPORADA_DEFECTO(v_SKU, NULL, NULL, NULL,
                                         v_TEMPORADA);
    INSERT INTO tmp_fza_migrar_temporada (sku, temporada)
    VALUES (v_SKU, v_TEMPORADA);
  END LOOP;
  CLOSE cur_SKUS;
  SELECT S.CODIGO_ALM_STK,
         S.CODIGO_UNIDAD_STK,
         K.CODIGO_ART_SKU,
         S.CANTIDAD_STK,
         S.PRECIO_MEDIO_STK,
         T.temporada AS TEMPORADA,
         IF(T.temporada IS NULL, 'SIN_TEMPORADA', '') AS MOTIVO
    FROM tmp_fza_migrar_temporada T
    JOIN fza_articulos_stockactual S
      ON S.CODIGO_UNIDAD_STK = T.sku
     AND S.LOTE_STK = ''
     AND S.CANTIDAD_STK > 0
    JOIN fza_almacenes ALM
      ON ALM.CODIGO_ALM_ALM = S.CODIGO_ALM_STK
    JOIN fza_articulos_skus K
      ON K.CODIGO_UNIDAD_SKU = S.CODIGO_UNIDAD_STK
   WHERE (NULLIF(p_EMPRESA, '') IS NULL OR ALM.CODIGO_EMP_ALM = p_EMPRESA)
     AND (NULLIF(p_ALMACEN, '') IS NULL OR S.CODIGO_ALM_STK = p_ALMACEN)
   ORDER BY S.CODIGO_ALM_STK, S.CODIGO_UNIDAD_STK;
END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `PRC_FZA_LOTES_STOCK_CONSULTA` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_spanish_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_FZA_LOTES_STOCK_CONSULTA`(
  IN p_EMPRESA varchar(20),
  IN p_ALMACEN varchar(10),
  IN p_CODIGO_ART varchar(20),
  IN p_TIPO_LOT varchar(1),
  IN p_FILTRO varchar(10),
  IN p_DIAS int,
  IN p_DIAS_DEFECTO int
)
BEGIN
  
  
  SELECT S.CODIGO_ALM_STK,
         ALM.NOMBRE_ALM_ALM,
         K.CODIGO_ART_SKU,
         A.DESCRIPCION_ART,
         A.CODIGO_FAM_ART,
         COALESCE(NULLIF(TRIM(FAM.DESCRIPCION_FAM), ''),
           NULLIF(TRIM(FAM.NOMBRE_FAM_FAM), ''),
           A.CODIGO_FAM_ART) AS DESCRIPCION_FAM,
         S.CODIGO_UNIDAD_STK,
         S.LOTE_STK,
         COALESCE(L.TIPO_LOT, '') AS TIPO_LOT,
         COALESCE(L.FECHA_CADUCIDAD_LOT, S.FECHA_CADUCIDAD_STK)
           AS FECHA_CADUCIDAD,
         DATEDIFF(COALESCE(L.FECHA_CADUCIDAD_LOT, S.FECHA_CADUCIDAD_STK),
                  CURDATE()) AS DIAS_PARA_CADUCAR,
         IF(COALESCE(L.FECHA_CADUCIDAD_LOT, S.FECHA_CADUCIDAD_STK)
              < CURDATE(), 'S', 'N') AS ESCADUCADO,
         L.FECHA_ENTRADA_LOT,
         DATEDIFF(CURDATE(), L.FECHA_ENTRADA_LOT) AS DIAS_DESDE_ENTRADA,
         L.CODIGO_PRV_LOT,
         COALESCE(NULLIF(TRIM(P.NOMBRE_PRV), ''),
           NULLIF(TRIM(P.RAZON_SOCIAL_PRV), ''),
           L.CODIGO_PRV_LOT) AS NOMBRE_PRV,
         S.CANTIDAD_STK,
         S.PRECIO_MEDIO_STK,
         S.VALOR_TOTAL_STK
    FROM fza_articulos_stockactual S
    JOIN fza_almacenes ALM
      ON ALM.CODIGO_ALM_ALM = S.CODIGO_ALM_STK
    LEFT JOIN fza_articulos_skus K
      ON K.CODIGO_UNIDAD_SKU = S.CODIGO_UNIDAD_STK
    LEFT JOIN fza_articulos A
      ON A.CODIGO_ART_ART = K.CODIGO_ART_SKU
    LEFT JOIN fza_articulos_familias FAM
      ON FAM.CODIGO_FAM_FAM = A.CODIGO_FAM_ART
    LEFT JOIN fza_articulos_lotes L
      ON L.CODIGO_UNIDAD_LOT = S.CODIGO_UNIDAD_STK
     AND L.LOTE_LOT = S.LOTE_STK
    LEFT JOIN fza_proveedores P
      ON P.CODIGO_PRV_PRV = L.CODIGO_PRV_LOT
   WHERE S.LOTE_STK <> ''
     AND S.CANTIDAD_STK <> 0
     AND (NULLIF(p_EMPRESA, '') IS NULL OR ALM.CODIGO_EMP_ALM = p_EMPRESA)
     AND (NULLIF(p_ALMACEN, '') IS NULL OR S.CODIGO_ALM_STK = p_ALMACEN)
     AND (NULLIF(p_CODIGO_ART, '') IS NULL OR K.CODIGO_ART_SKU = p_CODIGO_ART)
     AND (NULLIF(p_TIPO_LOT, '') IS NULL OR L.TIPO_LOT = p_TIPO_LOT)
     AND (IFNULL(p_FILTRO, 'TODO') = 'TODO'
          OR (p_FILTRO = 'CADUCADOS'
              AND COALESCE(L.FECHA_CADUCIDAD_LOT, S.FECHA_CADUCIDAD_STK)
                  < CURDATE())
          OR (p_FILTRO = 'PROXIMOS'
              AND COALESCE(L.FECHA_CADUCIDAD_LOT, S.FECHA_CADUCIDAD_STK)
                  <= CURDATE() + INTERVAL COALESCE(p_DIAS,
                       A.DIAS_AVISO_CADUCIDAD_ART, p_DIAS_DEFECTO, 30) DAY))
   ORDER BY S.CODIGO_ALM_STK,
            COALESCE(L.FECHA_CADUCIDAD_LOT, S.FECHA_CADUCIDAD_STK) IS NULL,
            COALESCE(L.FECHA_CADUCIDAD_LOT, S.FECHA_CADUCIDAD_STK),
            K.CODIGO_ART_SKU, S.CODIGO_UNIDAD_STK, S.LOTE_STK;
END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_VALUE_ON_ZERO' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `PRC_FZA_LOTES_TEMPORADA_ANTIGUEDAD` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_spanish_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_FZA_LOTES_TEMPORADA_ANTIGUEDAD`(
  IN p_EMPRESA varchar(20),
  IN p_ALMACEN varchar(10),
  IN p_CODIGO_FAM varchar(20)
)
BEGIN
  
  SELECT S.CODIGO_ALM_STK,
         ALM.NOMBRE_ALM_ALM,
         S.LOTE_STK AS TEMPORADA,
         MIN(L.FECHA_ENTRADA_LOT) AS PRIMERA_ENTRADA,
         DATEDIFF(CURDATE(), MIN(L.FECHA_ENTRADA_LOT)) AS DIAS_ANTIGUEDAD,
         COUNT(DISTINCT K.CODIGO_ART_SKU) AS ARTICULOS,
         COUNT(*) AS SKUS,
         SUM(S.CANTIDAD_STK) AS UNIDADES,
         SUM(S.VALOR_TOTAL_STK) AS VALOR
    FROM fza_articulos_stockactual S
    JOIN fza_articulos_lotes L
      ON L.CODIGO_UNIDAD_LOT = S.CODIGO_UNIDAD_STK
     AND L.LOTE_LOT = S.LOTE_STK
     AND L.TIPO_LOT = 'T'
    JOIN fza_almacenes ALM
      ON ALM.CODIGO_ALM_ALM = S.CODIGO_ALM_STK
    LEFT JOIN fza_articulos_skus K
      ON K.CODIGO_UNIDAD_SKU = S.CODIGO_UNIDAD_STK
    LEFT JOIN fza_articulos A
      ON A.CODIGO_ART_ART = K.CODIGO_ART_SKU
   WHERE S.CANTIDAD_STK <> 0
     AND (NULLIF(p_EMPRESA, '') IS NULL OR ALM.CODIGO_EMP_ALM = p_EMPRESA)
     AND (NULLIF(p_ALMACEN, '') IS NULL OR S.CODIGO_ALM_STK = p_ALMACEN)
     AND (NULLIF(p_CODIGO_FAM, '') IS NULL OR A.CODIGO_FAM_ART = p_CODIGO_FAM)
   GROUP BY S.CODIGO_ALM_STK, ALM.NOMBRE_ALM_ALM, S.LOTE_STK
   ORDER BY S.CODIGO_ALM_STK, MIN(L.FECHA_ENTRADA_LOT), S.LOTE_STK;
END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_VALUE_ON_ZERO' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `PRC_FZA_LOTES_TEMPORADA_DEFECTO` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_spanish_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_FZA_LOTES_TEMPORADA_DEFECTO`(
  IN p_CODIGO_UNIDAD varchar(50),
  IN p_TIPO_DOC varchar(5),
  IN p_SERIE_DOC varchar(20),
  IN p_NUMERO_DOC varchar(20),
  OUT p_TEMPORADA varchar(50)
)
BEGIN
  
  
  
  
  
  
  DECLARE v_ID int DEFAULT NULL;
  DECLARE v_LIBRE varchar(255) DEFAULT NULL;
  SET p_TEMPORADA = NULL;
  IF p_TIPO_DOC IN ('AC', 'AB') THEN
    SELECT MAX(D.ID_PV_TEMPORADA_ALBC) INTO v_ID
      FROM fza_albaranes_compra D
     WHERE D.SERIE_ALBC = p_SERIE_DOC AND D.NUMERO_ALBC = p_NUMERO_DOC;
  ELSEIF p_TIPO_DOC = 'SE' THEN
    SELECT MAX(D.ID_PV_TEMPORADA_SES) INTO v_ID
      FROM fza_compras_sesiones D
     WHERE D.SERIE_SES = p_SERIE_DOC AND D.NUMERO_SES = p_NUMERO_DOC;
  ELSEIF p_TIPO_DOC = 'FP' THEN
    SELECT MAX(D.ID_PV_TEMPORADA_FACC) INTO v_ID
      FROM fza_facturas_compra D
     WHERE D.SERIE_FACC = p_SERIE_DOC AND D.NUMERO_FACC = p_NUMERO_DOC;
  ELSEIF p_TIPO_DOC = 'PC' THEN
    SELECT MAX(D.ID_PV_TEMPORADA_PEDC) INTO v_ID
      FROM fza_pedidos_compra D
     WHERE D.SERIE_PEDC = p_SERIE_DOC AND D.NUMERO_PEDC = p_NUMERO_DOC;
  END IF;
  IF v_ID IS NULL THEN
    SELECT COALESCE(PS.ID_PV_ARTPROP, PC.ID_PV_ARTPROP, PA.ID_PV_ARTPROP),
           COALESCE(PS.VALOR_LIBRE_ARTPROP, PC.VALOR_LIBRE_ARTPROP,
                    PA.VALOR_LIBRE_ARTPROP)
      INTO v_ID, v_LIBRE
      FROM fza_articulos_skus K
      LEFT JOIN fza_articulos_propiedades PS
        ON PS.CODIGO_ART_ART = K.CODIGO_ART_SKU
       AND PS.CODIGO_PROP_ARTPROP = 'TEMPORADA'
       AND PS.CODIGO_UNIDAD_ARTPROP = K.CODIGO_UNIDAD_SKU
      LEFT JOIN fza_articulos_propiedades PC
        ON PC.CODIGO_ART_ART = K.CODIGO_ART_SKU
       AND PC.CODIGO_PROP_ARTPROP = 'TEMPORADA'
       AND PC.CODIGO_UNIDAD_ARTPROP = CASE
             WHEN CHAR_LENGTH(K.CODIGO_UNIDAD_SKU) -
                  CHAR_LENGTH(REPLACE(K.CODIGO_UNIDAD_SKU, '/', '')) >= 2
             THEN SUBSTRING_INDEX(K.CODIGO_UNIDAD_SKU, '/', 2)
             ELSE NULL
           END
      LEFT JOIN fza_articulos_propiedades PA
        ON PA.CODIGO_ART_ART = K.CODIGO_ART_SKU
       AND PA.CODIGO_PROP_ARTPROP = 'TEMPORADA'
       AND PA.CODIGO_UNIDAD_ARTPROP = ''
     WHERE K.CODIGO_UNIDAD_SKU = p_CODIGO_UNIDAD
     LIMIT 1;
  END IF;
  IF v_ID IS NOT NULL THEN
    SELECT LEFT(COALESCE(NULLIF(TRIM(V.DESCRIPCION_PV), ''),
                         NULLIF(TRIM(V.PV), '')), 50)
      INTO p_TEMPORADA
      FROM fza_propiedades_valores V
     WHERE V.ID_PV_ARTPROP = v_ID;
  END IF;
  IF p_TEMPORADA IS NULL THEN
    SET p_TEMPORADA = LEFT(NULLIF(TRIM(v_LIBRE), ''), 50);
  END IF;
END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_VALUE_ON_ZERO' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `PRC_FZA_LOTES_VALIDAR_SALIDA` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_spanish_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_FZA_LOTES_VALIDAR_SALIDA`(
  IN p_CODIGO_UNIDAD varchar(50),
  IN p_CODIGO_ALMACEN varchar(10),
  IN p_LOTE varchar(50),
  IN p_CANTIDAD decimal(19,6),
  OUT p_RESULTADO varchar(20),
  OUT p_ESCADUCADO varchar(1),
  OUT p_STOCK decimal(19,6),
  OUT p_FECHA_CADUCIDAD date
)
BEGIN
  
  
  
  
  
  
  DECLARE v_LOTE varchar(50) DEFAULT '';
  DECLARE v_EN_CATALOGO int DEFAULT 0;
  DECLARE v_EN_STOCK int DEFAULT 0;
  DECLARE v_TIPO varchar(1) DEFAULT NULL;
  DECLARE v_MODO varchar(10) DEFAULT NULL;
  DECLARE v_FECHA_CATALOGO date DEFAULT NULL;
  DECLARE v_FECHA_STOCK date DEFAULT NULL;
  SET v_LOTE = TRIM(IFNULL(p_LOTE, ''));
  SELECT COUNT(*), MAX(L.TIPO_LOT), MAX(L.FECHA_CADUCIDAD_LOT)
    INTO v_EN_CATALOGO, v_TIPO, v_FECHA_CATALOGO
    FROM fza_articulos_lotes L
   WHERE L.CODIGO_UNIDAD_LOT = p_CODIGO_UNIDAD
     AND L.LOTE_LOT = v_LOTE;
  SELECT COUNT(*), IFNULL(SUM(S.CANTIDAD_STK), 0),
         MAX(S.FECHA_CADUCIDAD_STK)
    INTO v_EN_STOCK, p_STOCK, v_FECHA_STOCK
    FROM fza_articulos_stockactual S
   WHERE S.CODIGO_ALM_STK = p_CODIGO_ALMACEN
     AND S.CODIGO_UNIDAD_STK = p_CODIGO_UNIDAD
     AND S.LOTE_STK = v_LOTE;
  SELECT MAX(A.TIPO_TRAZABILIDAD_ART)
    INTO v_MODO
    FROM fza_articulos_skus K
    JOIN fza_articulos A
      ON A.CODIGO_ART_ART = K.CODIGO_ART_SKU
   WHERE K.CODIGO_UNIDAD_SKU = p_CODIGO_UNIDAD;
  SET p_FECHA_CADUCIDAD = COALESCE(v_FECHA_CATALOGO, v_FECHA_STOCK);
  SET p_ESCADUCADO = IF(p_FECHA_CADUCIDAD IS NOT NULL AND
                        p_FECHA_CADUCIDAD < CURDATE(), 'S', 'N');
  IF v_LOTE <> '' AND v_EN_CATALOGO = 0 AND v_EN_STOCK = 0 THEN
    SET p_RESULTADO = 'INEXISTENTE';
  ELSEIF v_LOTE <> '' AND
         (v_TIPO = 'S' OR (v_TIPO IS NULL AND v_MODO = 'SERIE')) AND
         IFNULL(p_CANTIDAD, 0) <> 1 THEN
    SET p_RESULTADO = 'CANTIDAD_SERIE';
  ELSEIF p_STOCK < IFNULL(p_CANTIDAD, 0) THEN
    SET p_RESULTADO = 'SIN_STOCK';
  ELSE
    SET p_RESULTADO = 'OK';
  END IF;
END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_VALUE_ON_ZERO' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `PRC_FZA_MOVIMIENTOS_ALMACEN_DELETE` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
