CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_FZA_MOVIMIENTOS_ALMACEN_DELETE_DOC`(
  IN p_TIPO varchar(5),
  IN p_SERIE varchar(20),
  IN p_NUMERO varchar(20)
)
BEGIN
  DECLARE v_CIERRE_ESTABLE varchar(1) DEFAULT 'N';
  DECLARE v_INTENTOS_CIERRE int DEFAULT 0;
  DECLARE v_TransaccionPropia varchar(1) DEFAULT 'N';
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    IF v_TransaccionPropia = 'S' THEN
      ROLLBACK;
    END IF;
    RESIGNAL;
  END;
  IF @@autocommit = 1 AND @@in_transaction = 0 THEN
    SET v_TransaccionPropia = 'S';
  END IF;
  cierre: WHILE v_CIERRE_ESTABLE <> 'S' AND
                v_INTENTOS_CIERRE < 3 DO
    CALL PRC_FZA_MOVIMIENTOS_RECALCULO_PREPARAR();
    CALL PRC_FZA_MOVIMIENTOS_RECALCULO_MARCAR_DOCUMENTO(
      p_TIPO, p_SERIE, p_NUMERO);
    CALL PRC_FZA_MOVIMIENTOS_RECALCULO_CIERRE_PREPARAR();
    IF v_TransaccionPropia = 'S' THEN
      SET TRANSACTION ISOLATION LEVEL READ COMMITTED;
      START TRANSACTION;
    ELSEIF @@in_transaction = 0 THEN
      START TRANSACTION;
    END IF;
    CALL PRC_FZA_MOVIMIENTOS_RECALCULO_CIERRE_BLOQUEAR(
      'DELETE_MOV_DOC');
    
    
    CALL PRC_FZA_MOVIMIENTOS_RECALCULO_MARCAR_DOCUMENTO(
      p_TIPO, p_SERIE, p_NUMERO);
    CALL PRC_FZA_MOVIMIENTOS_RECALCULO_CIERRE_VALIDAR(
      v_CIERRE_ESTABLE);
    IF v_CIERRE_ESTABLE <> 'S' THEN
      IF v_TransaccionPropia = 'S' THEN
        ROLLBACK;
      ELSE
        SIGNAL SQLSTATE '45000'
          SET MESSAGE_TEXT =
            'El cierre de traspasos cambio antes de borrar el documento';
      END IF;
    END IF;
    SET v_INTENTOS_CIERRE = v_INTENTOS_CIERRE + 1;
  END WHILE cierre;
  IF v_CIERRE_ESTABLE <> 'S' THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT =
        'El cierre de traspasos no se estabilizo al borrar el documento';
  END IF;
  CALL PRC_FZA_MOVIMIENTOS_RECALCULO_RAICES_RESTAURAR();
  CALL PRC_FZA_STOCK_ACUMULADOS_PREPARAR();
  INSERT INTO tmp_stock_acumulados_mov (numero_mov)
  SELECT NUMERO_MOV
    FROM fza_movimientos_almacen
   WHERE TIPO_DOC_MOV = p_TIPO
     AND SERIE_DOC_MOV = p_SERIE
     AND NUMERO_DOC_MOV = p_NUMERO;
  CALL PRC_FZA_STOCK_ACUMULADOS_APLICAR(-1);
  DELETE FROM fza_movimientos_almacen
   WHERE TIPO_DOC_MOV = p_TIPO
     AND SERIE_DOC_MOV = p_SERIE
     AND NUMERO_DOC_MOV = p_NUMERO;
  CALL PRC_FZA_MOVIMIENTOS_RECALCULO_EJECUTAR();
  IF v_TransaccionPropia = 'S' THEN
    COMMIT;
  END IF;
END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_VALUE_ON_ZERO' */ ;
