/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_spanish_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_FZA_MOVIMIENTOS_ALMACEN_INSERT_LOTE`(
  IN p_NUMERO_MOV varchar(20),
  IN p_TIPO_DOC_MOV varchar(20),
  IN p_SERIE_DOC_MOV varchar(20),
  IN p_NRO_DOC_MOV varchar(20),
  IN p_LINEA_MOV varchar(10),
  IN p_CODIGO_EMPRESA_MOV varchar(20),
  IN p_CODIGO_ALMACEN_MOV varchar(10),
  IN p_CODIGO_ALMACEN_CONTRA_MOV varchar(10),
  IN p_CODIGO_UNIDAD_MOV varchar(50),
  IN p_TIPO_MOVIMIENTO_MOV varchar(1),
  IN p_CANTIDAD_MOV decimal(19,6),
  IN p_PRECIO_MEDIO_MOV decimal(19,6),
  IN p_TOTAL_COSTE_MOV decimal(19,6),
  IN p_USUARIO varchar(200),
  IN p_ALMACEN_DOC varchar(10),
  IN p_NUMOP_DOC varchar(20),
  IN p_CODIGO_CAJA_DOC_MOV varchar(10),
  IN p_CODCLIENTE varchar(20),
  IN p_CODARTICULO varchar(20),
  IN p_LOTE_MOV varchar(50),
  IN p_FECHA_CADUCIDAD_MOV date
)
BEGIN
  DECLARE v_PMPFinal decimal(19,6);
  DECLARE v_StockFinal decimal(19,6);
  DECLARE v_ValorFinal decimal(19,6);
  DECLARE v_PrecioFinal decimal(19,6);
  DECLARE v_CosteFinal decimal(19,6);
  DECLARE v_dEntCompra decimal(19,6) DEFAULT 0;
  DECLARE v_dEntTraspaso decimal(19,6) DEFAULT 0;
  DECLARE v_dSalTraspaso decimal(19,6) DEFAULT 0;
  DECLARE v_dEntDeposito decimal(19,6) DEFAULT 0;
  DECLARE v_dSalDeposito decimal(19,6) DEFAULT 0;
  DECLARE v_dSalVenta decimal(19,6) DEFAULT 0;
  DECLARE v_dEntRegular decimal(19,6) DEFAULT 0;
  DECLARE v_dSalAlbVenta decimal(19,6) DEFAULT 0;
  DECLARE v_dEntAlbEntrada decimal(19,6) DEFAULT 0;
  DECLARE v_TransaccionPropia varchar(1) DEFAULT 'N';
  DECLARE v_Lote varchar(50) DEFAULT '';
  DECLARE v_FechaCaducidad date DEFAULT NULL;
  DECLARE v_ConLotes varchar(1) DEFAULT 'N';
  DECLARE v_TipoLote varchar(1) DEFAULT NULL;
  DECLARE v_ResultadoLote varchar(20) DEFAULT NULL;
  DECLARE v_CodigoPrv varchar(20) DEFAULT NULL;
  DECLARE v_Descripcion varchar(100) DEFAULT NULL;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    IF v_TransaccionPropia = 'S' THEN
      ROLLBACK;
    END IF;
    RESIGNAL;
  END;
  SET v_Lote = TRIM(IFNULL(p_LOTE_MOV, ''));
  IF @@autocommit = 1 AND @@in_transaction = 0 THEN
    START TRANSACTION;
    SET v_TransaccionPropia = 'S';
  END IF;
  CALL PRC_FZA_STOCK_BLOQUEAR_CLAVE(
    p_CODIGO_ALMACEN_MOV,
    p_CODIGO_UNIDAD_MOV,
    p_USUARIO);
  
  
  IF p_TIPO_DOC_MOV = 'AC' THEN
    SELECT MAX(A.CODIGO_PRV_ALBC)
      INTO v_CodigoPrv
      FROM fza_albaranes_compra A
     WHERE A.SERIE_ALBC = p_SERIE_DOC_MOV
       AND A.NUMERO_ALBC = p_NRO_DOC_MOV;
  ELSEIF p_TIPO_DOC_MOV = 'FP' THEN
    SELECT MAX(F.CODIGO_PRV_FACC)
      INTO v_CodigoPrv
      FROM fza_facturas_compra F
     WHERE F.SERIE_FACC = p_SERIE_DOC_MOV
       AND F.NUMERO_FACC = p_NRO_DOC_MOV;
  ELSEIF p_TIPO_DOC_MOV = 'DC' THEN
    SELECT MAX(D.CODIGO_PRV_DEVC)
      INTO v_CodigoPrv
      FROM fza_devoluciones_compra D
     WHERE D.SERIE_DEVC = p_SERIE_DOC_MOV
       AND D.NUMERO_DEVC = p_NRO_DOC_MOV;
  END IF;
  SELECT LEFT(MAX(A.DESCRIPCION_ART), 100)
    INTO v_Descripcion
    FROM fza_articulos A
   WHERE A.CODIGO_ART_ART = p_CODARTICULO;
  IF v_Descripcion IS NULL THEN
    SELECT LEFT(MAX(A.DESCRIPCION_ART), 100)
      INTO v_Descripcion
      FROM fza_articulos_skus K
      JOIN fza_articulos A
        ON A.CODIGO_ART_ART = K.CODIGO_ART_SKU
     WHERE K.CODIGO_UNIDAD_SKU = p_CODIGO_UNIDAD_MOV;
  END IF;
  IF v_Lote <> '' THEN
    SET v_ConLotes = 'S';
    SELECT MAX(L.TIPO_LOT)
      INTO v_TipoLote
      FROM fza_articulos_lotes L
     WHERE L.CODIGO_UNIDAD_LOT = p_CODIGO_UNIDAD_MOV
       AND L.LOTE_LOT = v_Lote;
    IF v_TipoLote IS NULL THEN
      SELECT IF(MAX(A.TIPO_TRAZABILIDAD_ART) = 'SERIE', 'S', NULL)
        INTO v_TipoLote
        FROM fza_articulos_skus K
        JOIN fza_articulos A
          ON A.CODIGO_ART_ART = K.CODIGO_ART_SKU
       WHERE K.CODIGO_UNIDAD_SKU = p_CODIGO_UNIDAD_MOV;
    END IF;
    
    
    IF p_TIPO_MOVIMIENTO_MOV = 'E' AND IFNULL(p_CANTIDAD_MOV, 0) <> 0 THEN
      IF v_TipoLote = 'S' AND p_CANTIDAD_MOV <> 1 THEN
        SIGNAL SQLSTATE '45000'
          SET MESSAGE_TEXT = 'Una serie solo admite cantidad 1';
      END IF;
      CALL PRC_FZA_LOTES_ASEGURAR(
        p_CODIGO_UNIDAD_MOV, v_Lote, NULL, p_FECHA_CADUCIDAD_MOV,
        CURDATE(), v_CodigoPrv, LEFT(p_TIPO_DOC_MOV, 5), p_SERIE_DOC_MOV,
        p_NRO_DOC_MOV,
        IF(p_TIPO_DOC_MOV IN ('TR', 'AT', 'TA'), 'N', 'S'),
        LEFT(p_USUARIO, 50), v_ResultadoLote);
      IF v_ResultadoLote = 'SERIE_OTRO_ARTICULO' THEN
        SIGNAL SQLSTATE '45000'
          SET MESSAGE_TEXT = 'La serie ya existe en otro articulo';
      ELSEIF v_ResultadoLote = 'SERIE_EN_STOCK' THEN
        SIGNAL SQLSTATE '45000'
          SET MESSAGE_TEXT = 'La serie ya esta en stock';
      END IF;
    END IF;
    SELECT MAX(L.FECHA_CADUCIDAD_LOT)
      INTO v_FechaCaducidad
      FROM fza_articulos_lotes L
     WHERE L.CODIGO_UNIDAD_LOT = p_CODIGO_UNIDAD_MOV
       AND L.LOTE_LOT = v_Lote;
    SET v_FechaCaducidad = COALESCE(p_FECHA_CADUCIDAD_MOV, v_FechaCaducidad);
  ELSEIF EXISTS (
    SELECT 1
      FROM fza_articulos_stockactual S
     WHERE S.CODIGO_ALM_STK = p_CODIGO_ALMACEN_MOV
       AND S.CODIGO_UNIDAD_STK = p_CODIGO_UNIDAD_MOV
       AND S.LOTE_STK <> ''
  ) THEN
    SET v_ConLotes = 'S';
  END IF;
  SET v_PrecioFinal = p_PRECIO_MEDIO_MOV;
  CALL PRC_FZA_MOVIMIENTOS_VALORAR_ALTA(
    p_CODIGO_ALMACEN_MOV, p_CODIGO_UNIDAD_MOV, p_TIPO_DOC_MOV,
    p_TIPO_MOVIMIENTO_MOV, p_CANTIDAD_MOV, v_PrecioFinal,
    v_CosteFinal, v_StockFinal, v_ValorFinal, v_PMPFinal);
  IF p_TIPO_DOC_MOV IN ('AC', 'FP') AND p_TIPO_MOVIMIENTO_MOV = 'E' THEN
    SET v_dEntCompra = p_CANTIDAD_MOV;
  ELSEIF p_TIPO_DOC_MOV IN ('TR', 'AT', 'TA') THEN
    IF p_TIPO_MOVIMIENTO_MOV = 'E' THEN
      SET v_dEntTraspaso = p_CANTIDAD_MOV;
    ELSE
      SET v_dSalTraspaso = p_CANTIDAD_MOV;
    END IF;
  ELSEIF p_TIPO_DOC_MOV = 'DP' THEN
    IF p_TIPO_MOVIMIENTO_MOV = 'E' THEN
      SET v_dEntDeposito = p_CANTIDAD_MOV;
    ELSE
      SET v_dSalDeposito = p_CANTIDAD_MOV;
    END IF;
  ELSEIF p_TIPO_DOC_MOV IN ('VE', 'FC') AND
         p_TIPO_MOVIMIENTO_MOV = 'S' THEN
    SET v_dSalVenta = p_CANTIDAD_MOV;
  ELSEIF p_TIPO_DOC_MOV = 'IN' AND
         p_TIPO_MOVIMIENTO_MOV = 'E' THEN
    SET v_dEntRegular = p_CANTIDAD_MOV;
  ELSEIF p_TIPO_DOC_MOV = 'AV' AND
         p_TIPO_MOVIMIENTO_MOV = 'S' THEN
    SET v_dSalAlbVenta = p_CANTIDAD_MOV;
  ELSEIF p_TIPO_DOC_MOV = 'AE' AND
         p_TIPO_MOVIMIENTO_MOV = 'E' THEN
    SET v_dEntAlbEntrada = p_CANTIDAD_MOV;
  END IF;
  INSERT INTO fza_movimientos_almacen (
    NUMERO_MOV,
    TIPO_DOC_MOV,
    SERIE_DOC_MOV,
    NUMERO_DOC_MOV,
    LINEA_MOV,
    CODIGO_EMP_MOV,
    CODIGO_ALM_MOV,
    CODIGO_ALM_CONTRA_MOV,
    CODIGO_UNIDAD_MOV,
    DESCRIPCION_ARTICULO_MOV,
    TIPO_MOV,
    CANTIDAD_MOV,
    PRECIO_COSTE_UNITARIO_MOV,
    PRECIO_MEDIO_MOV,
    TOTAL_COSTE_MOV,
    VALOR_STOCK_MOV,
    FECHA_MOV,
    USUARIO_ALTA,
    USUARIO_MODIF,
    CODIGO_ALM_DOC_MOV,
    NUMERO_OPERACION_DOC_MOV,
    CODIGO_CAJA_DOC_MOV,
    CODIGO_CLI_MOV,
    CODIGO_PRV_MOV,
    CODIGO_ART_MOV,
    LOTE_MOV,
    FECHA_CADUCIDAD_MOV
  ) VALUES (
    p_NUMERO_MOV,
    p_TIPO_DOC_MOV,
    p_SERIE_DOC_MOV,
    p_NRO_DOC_MOV,
    p_LINEA_MOV,
    p_CODIGO_EMPRESA_MOV,
    p_CODIGO_ALMACEN_MOV,
    p_CODIGO_ALMACEN_CONTRA_MOV,
    p_CODIGO_UNIDAD_MOV,
    v_Descripcion,
    p_TIPO_MOVIMIENTO_MOV,
    p_CANTIDAD_MOV,
    v_PrecioFinal,
    v_PMPFinal,
    v_CosteFinal,
    v_ValorFinal,
    NOW(),
    p_USUARIO,
    p_USUARIO,
    p_ALMACEN_DOC,
    p_NUMOP_DOC,
    p_CODIGO_CAJA_DOC_MOV,
    p_CODCLIENTE,
    v_CodigoPrv,
    p_CODARTICULO,
    v_Lote,
    v_FechaCaducidad
  );
  IF v_ConLotes = 'N' THEN
    
    INSERT INTO fza_articulos_stockactual (
      CODIGO_ALM_STK,
      CODIGO_UNIDAD_STK,
      CANTIDAD_STK,
      VALOR_TOTAL_STK,
      PRECIO_MEDIO_STK,
      INSTANTE_MODIF,
      CANTIDAD_ENT_COMPRA_STK,
      CANTIDAD_ENT_TRASPASO_STK,
      CANTIDAD_SAL_TRASPASO_STK,
      CANTIDAD_ENT_DEPOSITO_STK,
      CANTIDAD_SAL_DEPOSITO_STK,
      CANTIDAD_SAL_VENTA_STK,
      CANTIDAD_ENT_REGULAR_STK,
      CANTIDAD_SAL_ALBVENTA_STK,
      CANTIDAD_ENT_ALBENTRADA_STK
    ) VALUES (
      p_CODIGO_ALMACEN_MOV,
      p_CODIGO_UNIDAD_MOV,
      v_StockFinal,
      v_ValorFinal,
      v_PMPFinal,
      NOW(),
      v_dEntCompra,
      v_dEntTraspaso,
      v_dSalTraspaso,
      v_dEntDeposito,
      v_dSalDeposito,
      v_dSalVenta,
      v_dEntRegular,
      v_dSalAlbVenta,
      v_dEntAlbEntrada
    )
    ON DUPLICATE KEY UPDATE
      CANTIDAD_STK = VALUES(CANTIDAD_STK),
      VALOR_TOTAL_STK = VALUES(VALOR_TOTAL_STK),
      PRECIO_MEDIO_STK = VALUES(PRECIO_MEDIO_STK),
      INSTANTE_MODIF = NOW(),
      CANTIDAD_ENT_COMPRA_STK = CANTIDAD_ENT_COMPRA_STK +
        VALUES(CANTIDAD_ENT_COMPRA_STK),
      CANTIDAD_ENT_TRASPASO_STK = CANTIDAD_ENT_TRASPASO_STK +
        VALUES(CANTIDAD_ENT_TRASPASO_STK),
      CANTIDAD_SAL_TRASPASO_STK = CANTIDAD_SAL_TRASPASO_STK +
        VALUES(CANTIDAD_SAL_TRASPASO_STK),
      CANTIDAD_ENT_DEPOSITO_STK = CANTIDAD_ENT_DEPOSITO_STK +
        VALUES(CANTIDAD_ENT_DEPOSITO_STK),
      CANTIDAD_SAL_DEPOSITO_STK = CANTIDAD_SAL_DEPOSITO_STK +
        VALUES(CANTIDAD_SAL_DEPOSITO_STK),
      CANTIDAD_SAL_VENTA_STK = CANTIDAD_SAL_VENTA_STK +
        VALUES(CANTIDAD_SAL_VENTA_STK),
      CANTIDAD_ENT_REGULAR_STK = CANTIDAD_ENT_REGULAR_STK +
        VALUES(CANTIDAD_ENT_REGULAR_STK),
      CANTIDAD_SAL_ALBVENTA_STK = CANTIDAD_SAL_ALBVENTA_STK +
        VALUES(CANTIDAD_SAL_ALBVENTA_STK),
      CANTIDAD_ENT_ALBENTRADA_STK = CANTIDAD_ENT_ALBENTRADA_STK +
        VALUES(CANTIDAD_ENT_ALBENTRADA_STK);
  ELSE
    
    
    INSERT INTO fza_articulos_stockactual (
      CODIGO_ALM_STK,
      CODIGO_UNIDAD_STK,
      LOTE_STK,
      FECHA_CADUCIDAD_STK,
      CANTIDAD_STK,
      VALOR_TOTAL_STK,
      PRECIO_MEDIO_STK,
      INSTANTE_MODIF,
      CANTIDAD_ENT_COMPRA_STK,
      CANTIDAD_ENT_TRASPASO_STK,
      CANTIDAD_SAL_TRASPASO_STK,
      CANTIDAD_ENT_DEPOSITO_STK,
      CANTIDAD_SAL_DEPOSITO_STK,
      CANTIDAD_SAL_VENTA_STK,
      CANTIDAD_ENT_REGULAR_STK,
      CANTIDAD_SAL_ALBVENTA_STK,
      CANTIDAD_ENT_ALBENTRADA_STK
    ) VALUES (
      p_CODIGO_ALMACEN_MOV,
      p_CODIGO_UNIDAD_MOV,
      v_Lote,
      v_FechaCaducidad,
      IF(p_TIPO_MOVIMIENTO_MOV = 'E', p_CANTIDAD_MOV, -p_CANTIDAD_MOV),
      0,
      v_PMPFinal,
      NOW(),
      v_dEntCompra,
      v_dEntTraspaso,
      v_dSalTraspaso,
      v_dEntDeposito,
      v_dSalDeposito,
      v_dSalVenta,
      v_dEntRegular,
      v_dSalAlbVenta,
      v_dEntAlbEntrada
    )
    ON DUPLICATE KEY UPDATE
      CANTIDAD_STK = IFNULL(CANTIDAD_STK, 0) + VALUES(CANTIDAD_STK),
      FECHA_CADUCIDAD_STK = COALESCE(VALUES(FECHA_CADUCIDAD_STK),
                                     FECHA_CADUCIDAD_STK),
      INSTANTE_MODIF = NOW(),
      CANTIDAD_ENT_COMPRA_STK = CANTIDAD_ENT_COMPRA_STK +
        VALUES(CANTIDAD_ENT_COMPRA_STK),
      CANTIDAD_ENT_TRASPASO_STK = CANTIDAD_ENT_TRASPASO_STK +
        VALUES(CANTIDAD_ENT_TRASPASO_STK),
      CANTIDAD_SAL_TRASPASO_STK = CANTIDAD_SAL_TRASPASO_STK +
        VALUES(CANTIDAD_SAL_TRASPASO_STK),
      CANTIDAD_ENT_DEPOSITO_STK = CANTIDAD_ENT_DEPOSITO_STK +
        VALUES(CANTIDAD_ENT_DEPOSITO_STK),
      CANTIDAD_SAL_DEPOSITO_STK = CANTIDAD_SAL_DEPOSITO_STK +
        VALUES(CANTIDAD_SAL_DEPOSITO_STK),
      CANTIDAD_SAL_VENTA_STK = CANTIDAD_SAL_VENTA_STK +
        VALUES(CANTIDAD_SAL_VENTA_STK),
      CANTIDAD_ENT_REGULAR_STK = CANTIDAD_ENT_REGULAR_STK +
        VALUES(CANTIDAD_ENT_REGULAR_STK),
      CANTIDAD_SAL_ALBVENTA_STK = CANTIDAD_SAL_ALBVENTA_STK +
        VALUES(CANTIDAD_SAL_ALBVENTA_STK),
      CANTIDAD_ENT_ALBENTRADA_STK = CANTIDAD_ENT_ALBENTRADA_STK +
        VALUES(CANTIDAD_ENT_ALBENTRADA_STK);
    CALL PRC_FZA_STOCK_LOTES_VALORAR(
      p_CODIGO_ALMACEN_MOV, p_CODIGO_UNIDAD_MOV,
      v_StockFinal, v_ValorFinal, v_PMPFinal);
  END IF;
  IF EXISTS (
    SELECT 1
      FROM fza_almacenes ALM
     WHERE ALM.CODIGO_ALM_ALM = p_CODIGO_ALMACEN_MOV
       AND ALM.ESWEB_ALM = 'S'
       AND ALM.ESACTIVO_ALM = 'S'
       AND ALM.ESFISICO_ALM = 'S'
       AND UPPER(TRIM(ALM.TIPO_USO_ALM)) = 'ESTANDAR'
  ) THEN
    CALL PRC_PRESTASHOP_ENCOLAR_CAMBIO_ALMACEN(
      p_CODARTICULO,
      p_CODIGO_UNIDAD_MOV,
      'N',
      'S',
      p_USUARIO,
      p_CODIGO_ALMACEN_MOV);
  END IF;
  IF v_TransaccionPropia = 'S' THEN
    COMMIT;
  END IF;
END
;;
