/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_spanish_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_FZA_MOVIMIENTOS_RECALCULO_ACTUALIZAR_STOCK_DIFERIDO`()
BEGIN
  DROP TEMPORARY TABLE IF EXISTS tmp_recalculo_final;
  CREATE TEMPORARY TABLE tmp_recalculo_final (
    almacen varchar(10) NOT NULL,
    sku varchar(50) NOT NULL,
    stock_final decimal(19,6) NOT NULL,
    pmp_final decimal(19,6) NOT NULL,
    valor_final decimal(19,6) NOT NULL,
    PRIMARY KEY (almacen, sku)
  ) ENGINE=InnoDB;
  INSERT INTO tmp_recalculo_final
    (almacen, sku, stock_final, pmp_final, valor_final)
  SELECT S.almacen,
         S.sku,
         IFNULL(O.stock_nuevo, S.stock_semilla),
         IFNULL(O.pmp_nuevo, S.pmp_semilla),
         IFNULL(O.valor_nuevo, S.valor_semilla)
    FROM tmp_recalculo_semillas S
    LEFT JOIN (
      SELECT X.almacen,
             X.sku,
             X.stock_nuevo,
             X.pmp_nuevo,
             X.valor_nuevo
        FROM tmp_movimientos_ordenados X
        JOIN (
          SELECT almacen,
                 sku,
                 MAX(rn) AS rn
            FROM tmp_movimientos_ordenados
           GROUP BY almacen, sku
        ) U ON U.almacen = X.almacen
           AND U.sku = X.sku
           AND U.rn = X.rn
    ) O ON O.almacen = S.almacen
       AND O.sku = S.sku;
  INSERT INTO fza_articulos_stockactual
    (CODIGO_ALM_STK,
     CODIGO_UNIDAD_STK,
     CANTIDAD_STK,
     VALOR_TOTAL_STK,
     PRECIO_MEDIO_STK,
     INSTANTE_MODIF)
  SELECT F.almacen,
         F.sku,
         F.stock_final,
         IF(F.stock_final > 0, F.valor_final, 0),
         F.pmp_final,
         NOW()
    FROM tmp_recalculo_final F
  ON DUPLICATE KEY UPDATE
    INSTANTE_MODIF = IF(
      (CANTIDAD_STK <=> VALUES(CANTIDAD_STK)) AND
      (VALOR_TOTAL_STK <=> VALUES(VALOR_TOTAL_STK)) AND
      (PRECIO_MEDIO_STK <=> VALUES(PRECIO_MEDIO_STK)),
      INSTANTE_MODIF, NOW()),
    CANTIDAD_STK = VALUES(CANTIDAD_STK),
    VALOR_TOTAL_STK = VALUES(VALOR_TOTAL_STK),
    PRECIO_MEDIO_STK = VALUES(PRECIO_MEDIO_STK);
  
  CALL PRC_FZA_STOCK_LOTES_REPARTIR();
  IF EXISTS (
    SELECT 1
      FROM INFORMATION_SCHEMA.ROUTINES
     WHERE ROUTINE_SCHEMA = DATABASE()
       AND ROUTINE_TYPE = 'PROCEDURE'
       AND ROUTINE_NAME = 'PRC_PRESTASHOP_ENCOLAR_STOCK_RECALCULO'
  ) THEN
    CALL PRC_PRESTASHOP_ENCOLAR_STOCK_RECALCULO('');
  END IF;
  DROP TEMPORARY TABLE IF EXISTS tmp_recalculo_final;
  DROP TEMPORARY TABLE IF EXISTS tmp_movimientos_ordenados;
  DROP TEMPORARY TABLE IF EXISTS tmp_recalculo_semillas;
END
;;
