  IN p_USUARIO varchar(50)
)
BEGIN
  CALL PRC_FZA_MOVIMIENTOS_RECALCULO_CIERRE_PREPARAR();
  CALL PRC_FZA_MOVIMIENTOS_RECALCULO_CIERRE_BLOQUEAR(p_USUARIO);
END
;;
