/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_spanish_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_FZA_MOVIMIENTOS_RECALCULO_CALCULAR_COLA`()
BEGIN
  SET @clave_previa := '';
  SET @stock := CAST(0 AS DECIMAL(19,6));
  SET @pmp := CAST(0 AS DECIMAL(28,12));
  SET @valor := CAST(0 AS DECIMAL(19,6));
  UPDATE tmp_movimientos_ordenados
     SET stock_nuevo = (@stock := IF(@clave_previa <> clave,
           stock_semilla, @stock)),
         valor_nuevo = (@valor := IF(@clave_previa <> clave,
           valor_semilla, @valor)),
         pmp_nuevo = (@pmp := IF(@stock > 0,
           CAST(@valor AS DECIMAL(28,12)) / @stock,
           IF(@clave_previa <> clave, pmp_semilla, @pmp))),
         cantidad = IF(es_cierre_inventario = 'S' AND tipo_mov = 'S',
           IFNULL(cantidad_cierre_lote, @stock), cantidad),
         coste_unitario = IF(tipo_mov = 'S' OR
           (tipo_mov = 'E' AND (tipo_doc IN ('VE', 'FC', 'AV', 'LT') OR
             (es_cierre_inventario = 'S' AND es_pmp_manual <> 'S'))),
           @pmp, coste_unitario),
         coste_nuevo = ROUND(cantidad * IF(tipo_mov = 'S' OR
           tipo_doc IN ('VE', 'FC', 'AV', 'LT') OR
           (es_cierre_inventario = 'S' AND es_pmp_manual <> 'S'),
           @pmp, coste_unitario), 6),
         valor_nuevo = (@valor := IF(tipo_mov = 'E',
           IF(@stock <= 0, GREATEST(@stock + cantidad, 0) * coste_unitario,
             @valor + coste_nuevo),
           IF(@stock - cantidad > 0, @valor - coste_nuevo, 0))),
         pmp_nuevo = (@pmp := IF(tipo_mov = 'E',
           IF(@stock <= 0 OR @stock + cantidad <= 0, coste_unitario,
             CAST(@valor AS DECIMAL(28,12)) / (@stock + cantidad)), @pmp)),
         stock_nuevo = (@stock := @stock +
           IF(tipo_mov = 'E', cantidad, -cantidad)),
         clave_previa = (@clave_previa := clave)
   ORDER BY rn;
  UPDATE fza_movimientos_almacen m
  JOIN tmp_movimientos_ordenados o ON o.numero_mov = m.NUMERO_MOV
     SET m.CANTIDAD_MOV = o.cantidad,
         m.PRECIO_COSTE_UNITARIO_MOV = o.coste_unitario,
         m.VALOR_STOCK_MOV = o.valor_nuevo,
         m.PRECIO_MEDIO_MOV = o.pmp_nuevo,
         m.TOTAL_COSTE_MOV = o.coste_nuevo,
         m.INSTANTE_MODIF = NOW()
   WHERE NOT (m.CANTIDAD_MOV <=> ROUND(o.cantidad, 6))
      OR NOT (m.PRECIO_COSTE_UNITARIO_MOV <=> ROUND(o.coste_unitario, 6))
      OR NOT (m.VALOR_STOCK_MOV <=> ROUND(o.valor_nuevo, 6))
      OR NOT (m.PRECIO_MEDIO_MOV <=> ROUND(o.pmp_nuevo, 6))
      OR NOT (m.TOTAL_COSTE_MOV <=> ROUND(o.coste_nuevo, 6));
  CALL PRC_FZA_MOVIMIENTOS_RECALCULO_INVENTARIOS();
END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
