/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_spanish_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_FZA_MOVIMIENTOS_RECALCULO_CIERRE_BLOQUEAR`(
  IN p_USUARIO varchar(50)
)
BEGIN
  DECLARE v_FIN int DEFAULT 0;
  DECLARE v_ALMACEN varchar(10);
  DECLARE v_SKU varchar(50);
  bloque_bloqueos: BEGIN
    DECLARE cur CURSOR FOR
      SELECT cierre.almacen, cierre.sku
        FROM tmp_movimientos_recalculo_cierre cierre
       WHERE IFNULL(cierre.almacen, '') <> ''
         AND IFNULL(cierre.sku, '') <> ''
       ORDER BY cierre.almacen, cierre.sku;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_FIN = 1;
    IF @@in_transaction = 0 THEN
      SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT =
          'El bloqueo del cierre requiere transaccion activa';
    END IF;
    OPEN cur;
    bucle: LOOP
      FETCH cur INTO v_ALMACEN, v_SKU;
      IF v_FIN = 1 THEN
        LEAVE bucle;
      END IF;
      CALL PRC_FZA_STOCK_BLOQUEAR_CLAVE(
        v_ALMACEN, v_SKU, p_USUARIO);
    END LOOP;
    CLOSE cur;
  END bloque_bloqueos;
END
;;
DELIMITER ;
