/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_spanish_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_FZA_MOVIMIENTOS_RECALCULO_CIERRE_CALCULAR`()
BEGIN
  DECLARE v_CAMBIOS int DEFAULT 1;
  DECLARE v_PASADAS int DEFAULT 0;
  DROP TEMPORARY TABLE IF EXISTS tmp_movimientos_recalculo_cierre;
  CREATE TEMPORARY TABLE tmp_movimientos_recalculo_cierre (
    empresa varchar(20) NOT NULL DEFAULT '',
    almacen varchar(10) NOT NULL,
    sku varchar(50) NOT NULL,
    instante_desde datetime NOT NULL,
    PRIMARY KEY (almacen, sku)
  ) ENGINE=InnoDB;
  DROP TEMPORARY TABLE IF EXISTS tmp_movimientos_recalculo_frontera;
  CREATE TEMPORARY TABLE tmp_movimientos_recalculo_frontera (
    empresa varchar(20) NOT NULL DEFAULT '',
    almacen varchar(10) NOT NULL,
    sku varchar(50) NOT NULL,
    instante_desde datetime NOT NULL,
    PRIMARY KEY (almacen, sku)
  ) ENGINE=InnoDB;
  DROP TEMPORARY TABLE IF EXISTS tmp_movimientos_recalculo_siguiente;
  CREATE TEMPORARY TABLE tmp_movimientos_recalculo_siguiente (
    empresa varchar(20) NOT NULL DEFAULT '',
    almacen varchar(10) NOT NULL,
    sku varchar(50) NOT NULL,
    instante_desde datetime NOT NULL,
    PRIMARY KEY (almacen, sku)
  ) ENGINE=InnoDB;
  INSERT INTO tmp_movimientos_recalculo_cierre
    (empresa, almacen, sku, instante_desde)
  SELECT empresa, almacen, sku, instante_desde
    FROM tmp_movimientos_recalculo_raices;
  INSERT INTO tmp_movimientos_recalculo_frontera
    (empresa, almacen, sku, instante_desde)
  SELECT empresa, almacen, sku, instante_desde
    FROM tmp_movimientos_recalculo_raices;
  SELECT COUNT(*) INTO v_CAMBIOS
    FROM tmp_movimientos_recalculo_frontera;
  WHILE v_CAMBIOS > 0 AND v_PASADAS < 100 DO
    DELETE FROM tmp_movimientos_recalculo_siguiente;
    INSERT INTO tmp_movimientos_recalculo_siguiente
      (empresa, almacen, sku, instante_desde)
    SELECT MIN(IFNULL(e.CODIGO_EMP_MOV, '')),
           e.CODIGO_ALM_MOV,
           e.CODIGO_UNIDAD_MOV,
           MIN(IFNULL(e.FECHA_MOV, '1000-01-01 00:00:00'))
      FROM tmp_movimientos_recalculo_frontera r
      JOIN fza_movimientos_almacen s
        ON s.CODIGO_ALM_MOV = r.almacen
       AND s.CODIGO_UNIDAD_MOV = r.sku
       AND s.ESACTIVO_MOV = 'S'
       AND s.TIPO_DOC_MOV IN ('TR', 'AT', 'TA')
       AND s.TIPO_MOV = 'S'
       AND IFNULL(s.FECHA_MOV, '1000-01-01 00:00:00') >=
           r.instante_desde
      JOIN fza_movimientos_almacen e
        ON e.TIPO_DOC_MOV = s.TIPO_DOC_MOV
       AND e.SERIE_DOC_MOV = s.SERIE_DOC_MOV
       AND e.NUMERO_DOC_MOV = s.NUMERO_DOC_MOV
       AND e.CODIGO_UNIDAD_MOV = s.CODIGO_UNIDAD_MOV
       AND e.CODIGO_ALM_MOV = s.CODIGO_ALM_CONTRA_MOV
       AND e.CODIGO_ALM_CONTRA_MOV = s.CODIGO_ALM_MOV
       AND e.ESACTIVO_MOV = 'S'
       AND e.TIPO_MOV = 'E'
       AND (e.LINEA_MOV = s.LINEA_MOV OR
            (IFNULL(e.NUMERO_OPERACION_DOC_MOV, '') <> '' AND
             e.NUMERO_OPERACION_DOC_MOV =
               s.NUMERO_OPERACION_DOC_MOV))
     GROUP BY e.CODIGO_ALM_MOV, e.CODIGO_UNIDAD_MOV;
    DELETE siguiente
      FROM tmp_movimientos_recalculo_siguiente siguiente
      JOIN tmp_movimientos_recalculo_cierre cierre
        ON cierre.almacen = siguiente.almacen
       AND cierre.sku = siguiente.sku
     WHERE siguiente.instante_desde >= cierre.instante_desde;
    SELECT COUNT(*) INTO v_CAMBIOS
      FROM tmp_movimientos_recalculo_siguiente;
    IF v_CAMBIOS > 0 THEN
      INSERT INTO tmp_movimientos_recalculo_cierre
        (empresa, almacen, sku, instante_desde)
      SELECT siguiente.empresa,
             siguiente.almacen,
             siguiente.sku,
             siguiente.instante_desde
        FROM tmp_movimientos_recalculo_siguiente siguiente
      ON DUPLICATE KEY UPDATE
        empresa = IF(
          tmp_movimientos_recalculo_cierre.empresa = '',
          VALUES(empresa),
          tmp_movimientos_recalculo_cierre.empresa),
        instante_desde = LEAST(
          tmp_movimientos_recalculo_cierre.instante_desde,
          VALUES(instante_desde));
      DELETE FROM tmp_movimientos_recalculo_frontera;
      INSERT INTO tmp_movimientos_recalculo_frontera
        (empresa, almacen, sku, instante_desde)
      SELECT empresa, almacen, sku, instante_desde
        FROM tmp_movimientos_recalculo_siguiente;
    END IF;
    SET v_PASADAS = v_PASADAS + 1;
  END WHILE;
  IF v_CAMBIOS > 0 THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT =
        'No converge el cierre preventivo de traspasos';
  END IF;
  DROP TEMPORARY TABLE IF EXISTS tmp_movimientos_recalculo_frontera;
  DROP TEMPORARY TABLE IF EXISTS tmp_movimientos_recalculo_siguiente;
END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_VALUE_ON_ZERO' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `PRC_FZA_MOVIMIENTOS_RECALCULO_CIERRE_PREPARAR` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_spanish_ci */ ;
