CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_FZA_MOVIMIENTOS_RECALCULO_CIERRE_VALIDAR`(
  OUT p_ESTABLE varchar(1)
)
BEGIN
  
  
  
  INSERT INTO tmp_movimientos_recalculo_raices
    (empresa, almacen, sku, instante_desde)
  SELECT empresa, almacen, sku, instante_desde
    FROM tmp_movimientos_recalculo
  ON DUPLICATE KEY UPDATE
    empresa = IF(
      tmp_movimientos_recalculo_raices.empresa = '',
      VALUES(empresa),
      tmp_movimientos_recalculo_raices.empresa),
    instante_desde = LEAST(
      tmp_movimientos_recalculo_raices.instante_desde,
      VALUES(instante_desde));
  DROP TEMPORARY TABLE IF EXISTS
    tmp_movimientos_recalculo_cierre_bloqueado;
  CREATE TEMPORARY TABLE tmp_movimientos_recalculo_cierre_bloqueado (
    empresa varchar(20) NOT NULL DEFAULT '',
    almacen varchar(10) NOT NULL,
    sku varchar(50) NOT NULL,
    instante_desde datetime NOT NULL,
    PRIMARY KEY (almacen, sku)
  ) ENGINE=InnoDB;
  INSERT INTO tmp_movimientos_recalculo_cierre_bloqueado
    (empresa, almacen, sku, instante_desde)
  SELECT empresa, almacen, sku, instante_desde
    FROM tmp_movimientos_recalculo_cierre;
  CALL PRC_FZA_MOVIMIENTOS_RECALCULO_CIERRE_CALCULAR();
  SELECT IF(EXISTS(
    SELECT 1
      FROM tmp_movimientos_recalculo_cierre validacion
      LEFT JOIN tmp_movimientos_recalculo_cierre_bloqueado bloqueado
        ON bloqueado.almacen = validacion.almacen
       AND bloqueado.sku = validacion.sku
     WHERE bloqueado.almacen IS NULL
        OR validacion.instante_desde < bloqueado.instante_desde),
    'N', 'S')
    INTO p_ESTABLE;
END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_VALUE_ON_ZERO' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `PRC_FZA_MOVIMIENTOS_RECALCULO_COMPLETAR` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_spanish_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_FZA_MOVIMIENTOS_RECALCULO_COMPLETAR`(
  IN p_TOKEN char(36),
  IN p_ALMACEN varchar(10),
  IN p_SKU varchar(50),
  IN p_RESUMEN varchar(1000),
  IN p_USUARIO varchar(50)
)
BEGIN
  UPDATE fza_movimientos_recalculos_pendientes
     SET ESTADO_MOVREC = 'PROCESADO',
         ESPROCESADO_MOVREC = 'S',
         INSTANTE_PROXIMO_INTENTO_MOVREC = NULL,
         INSTANTE_LIMITE_RECLAMACION_MOVREC = NULL,
         MENSAJE_ERROR_MOVREC = NULL,
         RESUMEN_CORRECCION_MOVREC = LEFT(COALESCE(
           NULLIF(TRIM(p_RESUMEN), ''), 'Sin resumen'), 1000),
         INSTANTE_PROCESADO_MOVREC = NOW(),
         INSTANTE_MODIF = NOW(),
         USUARIO_MODIF = LEFT(COALESCE(
           NULLIF(TRIM(p_USUARIO), ''), 'SISTEMA'), 50)
   WHERE TOKEN_RECLAMACION_MOVREC = p_TOKEN
     AND CODIGO_ALM_MOVREC = p_ALMACEN
     AND CODIGO_UNIDAD_MOVREC = p_SKU
     AND ESTADO_MOVREC = 'PROCESANDO'
     AND ESPROCESADO_MOVREC = 'N';
END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_VALUE_ON_ZERO' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `PRC_FZA_MOVIMIENTOS_RECALCULO_DOCUMENTOS` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_spanish_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_FZA_MOVIMIENTOS_RECALCULO_DOCUMENTOS`()
BEGIN
  UPDATE tmp_movimientos_ordenados O
    JOIN fza_movimientos_almacen M
      ON M.NUMERO_MOV = O.numero_mov
    JOIN fza_facturas_lineas L
      ON L.NUMERO_MOV_FACLIN = M.NUMERO_MOV
     AND L.SERIE_FAC_FACLIN = M.SERIE_DOC_MOV
     AND L.NUMERO_FAC_FACLIN = M.NUMERO_DOC_MOV
     SET L.PRECIO_ULT_COMPRA_FACLIN = M.PRECIO_COSTE_UNITARIO_MOV,
         L.INSTANTE_MODIF = NOW()
   WHERE O.tipo_doc = 'VE'
     AND NOT (L.PRECIO_ULT_COMPRA_FACLIN <=> M.PRECIO_COSTE_UNITARIO_MOV);

  DROP TEMPORARY TABLE IF EXISTS tmp_movrec_traspasos;
  CREATE TEMPORARY TABLE tmp_movrec_traspasos (
    empresa varchar(20) NOT NULL,
    almacen_doc varchar(10) NOT NULL,
    caja varchar(10) NOT NULL,
    operacion varchar(20) NOT NULL,
    tipo_doc varchar(5) NOT NULL,
    serie varchar(20) NOT NULL,
    numero varchar(20) NOT NULL,
    importe decimal(19,6) NOT NULL DEFAULT 0,
    PRIMARY KEY (empresa, almacen_doc, caja, operacion, tipo_doc, serie,
                 numero)
  ) ENGINE=InnoDB;
  INSERT IGNORE INTO tmp_movrec_traspasos
    (empresa, almacen_doc, caja, operacion, tipo_doc, serie, numero)
  SELECT M.CODIGO_EMP_MOV, M.CODIGO_ALM_DOC_MOV, M.CODIGO_CAJA_DOC_MOV,
         M.NUMERO_OPERACION_DOC_MOV, M.TIPO_DOC_MOV, M.SERIE_DOC_MOV,
         M.NUMERO_DOC_MOV
    FROM tmp_movimientos_ordenados O
    JOIN fza_movimientos_almacen M
      ON M.NUMERO_MOV = O.numero_mov
   WHERE O.tipo_doc IN ('TR', 'TA', 'AT')
     AND O.tipo_mov = 'S'
     AND IFNULL(M.CODIGO_ALM_DOC_MOV, '') <> ''
     AND IFNULL(M.CODIGO_CAJA_DOC_MOV, '') <> ''
     AND IFNULL(M.NUMERO_OPERACION_DOC_MOV, '') <> '';
  UPDATE tmp_movrec_traspasos T
     SET T.importe = (
       SELECT ROUND(IFNULL(SUM(S.TOTAL_COSTE_MOV), 0), 4)
         FROM fza_movimientos_almacen S
        WHERE S.SERIE_DOC_MOV = T.serie
          AND S.NUMERO_DOC_MOV = T.numero
          AND S.TIPO_DOC_MOV = T.tipo_doc
          AND S.TIPO_MOV = 'S'
          AND S.ESACTIVO_MOV = 'S'
          AND S.CODIGO_EMP_MOV = T.empresa
          AND S.CODIGO_ALM_DOC_MOV = T.almacen_doc
          AND S.CODIGO_CAJA_DOC_MOV = T.caja
          AND S.NUMERO_OPERACION_DOC_MOV = T.operacion);
  UPDATE tmp_movrec_traspasos T
    JOIN fza_caja_operaciones P
      ON P.CODIGO_EMP_OPCAJA = T.empresa
     AND P.CODIGO_ALM_OPCAJA = T.almacen_doc
     AND P.CODIGO_CAJA_OPCAJA = T.caja
     AND P.NUMERO_OPERACION_OPCAJA = T.operacion
     SET P.IMPORTE_TOTAL_OPCAJA = T.importe,
         P.INSTANTE_MODIF = NOW()
   WHERE P.TIPO_OPERACION_OPCAJA = T.tipo_doc
     AND P.ESTRASPASO_OPCAJA = 'S'
     AND (P.SERIE_FAC_OPCAJA IS NULL OR P.SERIE_FAC_OPCAJA = T.serie)
     AND (P.NUMERO_FAC_OPCAJA IS NULL OR P.NUMERO_FAC_OPCAJA = T.numero)
     AND NOT (P.IMPORTE_TOTAL_OPCAJA <=> T.importe);
  DROP TEMPORARY TABLE IF EXISTS tmp_movrec_traspasos;
END
;;
DELIMITER ;
