/*!50003 DROP PROCEDURE IF EXISTS `PRC_FZA_MOVIMIENTOS_RECALCULO_EJECUTAR` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_spanish_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_FZA_MOVIMIENTOS_RECALCULO_EJECUTAR`()
BEGIN
  DECLARE v_CAMBIOS int DEFAULT 1;
  DECLARE v_CIERRE_ESTABLE varchar(1) DEFAULT 'N';
  DECLARE v_INTENTOS_CIERRE int DEFAULT 0;
  DECLARE v_PASADAS int DEFAULT 0;
  DECLARE v_TRANSACCION_PROPIA varchar(1) DEFAULT 'N';
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    IF v_TRANSACCION_PROPIA = 'S' AND @@in_transaction <> 0 THEN
      ROLLBACK;
    END IF;
    RESIGNAL;
  END;
  IF @@autocommit = 1 AND @@in_transaction = 0 THEN
    SET v_TRANSACCION_PROPIA = 'S';
  END IF;
  cierre: WHILE v_CIERRE_ESTABLE <> 'S' AND
                v_INTENTOS_CIERRE < 3 DO
    CALL PRC_FZA_MOVIMIENTOS_RECALCULO_CIERRE_PREPARAR();
    IF v_TRANSACCION_PROPIA = 'S' THEN
      
      
      SET TRANSACTION ISOLATION LEVEL READ COMMITTED;
      START TRANSACTION;
    ELSEIF @@in_transaction = 0 THEN
      START TRANSACTION;
    END IF;
    CALL PRC_FZA_MOVIMIENTOS_RECALCULO_CIERRE_BLOQUEAR('RECALCULO');
    CALL PRC_FZA_MOVIMIENTOS_RECALCULO_CIERRE_VALIDAR(
      v_CIERRE_ESTABLE);
    IF v_CIERRE_ESTABLE <> 'S' THEN
      IF v_TRANSACCION_PROPIA = 'S' THEN
        ROLLBACK;
      ELSE
        SIGNAL SQLSTATE '45000'
          SET MESSAGE_TEXT =
            'El cierre de traspasos cambio antes del recalculo';
      END IF;
    END IF;
    SET v_INTENTOS_CIERRE = v_INTENTOS_CIERRE + 1;
  END WHILE cierre;
  IF v_CIERRE_ESTABLE <> 'S' THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT =
        'El cierre de traspasos no se estabilizo en tres intentos';
  END IF;
  CALL PRC_FZA_MOVIMIENTOS_RECALCULO_RAICES_RESTAURAR();
  WHILE EXISTS(SELECT 1 FROM tmp_movimientos_recalculo) AND
        v_CAMBIOS > 0 AND v_PASADAS < 100 DO
    CALL PRC_FZA_MOVIMIENTOS_RECALCULO_PASADA();
    CALL PRC_FZA_MOVIMIENTOS_RECALCULO_PROPAGAR(v_CAMBIOS);
    SET v_PASADAS = v_PASADAS + 1;
  END WHILE;
  IF v_PASADAS >= 100 AND
     EXISTS(SELECT 1 FROM tmp_movimientos_recalculo) THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT =
        'No converge la propagacion cronologica de traspasos';
  END IF;
  IF v_TRANSACCION_PROPIA = 'S' THEN
    COMMIT;
  END IF;
  DROP TEMPORARY TABLE IF EXISTS tmp_movimientos_recalculo;
  DROP TEMPORARY TABLE IF EXISTS tmp_movimientos_recalculo_raices;
  DROP TEMPORARY TABLE IF EXISTS tmp_movimientos_recalculo_cierre;
  DROP TEMPORARY TABLE IF EXISTS
    tmp_movimientos_recalculo_cierre_bloqueado;
END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_VALUE_ON_ZERO' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `PRC_FZA_MOVIMIENTOS_RECALCULO_EJECUTAR_DIFERIDO` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_spanish_ci */ ;
