CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_FZA_MOVIMIENTOS_RECALCULO_ENCOLAR`(
  IN p_NUMERO_MOV varchar(20),
  IN p_MOTIVO varchar(255),
  IN p_USUARIO varchar(50)
)
BEGIN
  IF NULLIF(TRIM(p_NUMERO_MOV), '') IS NULL THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'No se puede encolar sin numero de movimiento';
  END IF;
  INSERT INTO fza_movimientos_recalculos_pendientes (
    NUMERO_MOV_MOVREC,
    CODIGO_EMP_MOVREC,
    CODIGO_ALM_MOVREC,
    CODIGO_UNIDAD_MOVREC,
    INSTANTE_DESDE_MOVREC,
    MOTIVO_MOVREC,
    ESTADO_MOVREC,
    ESPROCESADO_MOVREC,
    VERSION_MOVREC,
    CONTADOR_INTENTOS_MOVREC,
    INSTANTE_ALTA,
    USUARIO_ALTA
  )
  SELECT M.NUMERO_MOV,
         IFNULL(M.CODIGO_EMP_MOV, ''),
         M.CODIGO_ALM_MOV,
         M.CODIGO_UNIDAD_MOV,
         IFNULL(M.FECHA_MOV, '1000-01-01 00:00:00'),
         LEFT(COALESCE(NULLIF(TRIM(p_MOTIVO), ''),
                       'SIN_ESPECIFICAR'), 255),
         'PENDIENTE',
         'N',
         1,
         0,
         NOW(),
         LEFT(COALESCE(NULLIF(TRIM(p_USUARIO), ''), 'SISTEMA'), 50)
    FROM fza_movimientos_almacen M
   WHERE M.NUMERO_MOV = p_NUMERO_MOV
     AND M.ESACTIVO_MOV = 'S'
  ON DUPLICATE KEY UPDATE
    INSTANTE_DESDE_MOVREC =
      LEAST(INSTANTE_DESDE_MOVREC, VALUES(INSTANTE_DESDE_MOVREC)),
    CODIGO_EMP_MOVREC = VALUES(CODIGO_EMP_MOVREC),
    CODIGO_ALM_MOVREC = VALUES(CODIGO_ALM_MOVREC),
    CODIGO_UNIDAD_MOVREC = VALUES(CODIGO_UNIDAD_MOVREC),
    MOTIVO_MOVREC = VALUES(MOTIVO_MOVREC),
    ESTADO_MOVREC = 'PENDIENTE',
    ESPROCESADO_MOVREC = 'N',
    VERSION_MOVREC = VERSION_MOVREC + 1,
    CONTADOR_INTENTOS_MOVREC = 0,
    INSTANTE_PROXIMO_INTENTO_MOVREC = NULL,
    TOKEN_RECLAMACION_MOVREC = NULL,
    INSTANTE_RECLAMACION_MOVREC = NULL,
    INSTANTE_LIMITE_RECLAMACION_MOVREC = NULL,
    MENSAJE_ERROR_MOVREC = NULL,
    RESUMEN_CORRECCION_MOVREC = NULL,
    INSTANTE_PROCESADO_MOVREC = NULL,
    INSTANTE_MODIF = NOW(),
    USUARIO_MODIF = VALUES(USUARIO_ALTA);
  IF ROW_COUNT() = 0 THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'El movimiento activo no existe';
  END IF;
END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
