CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_FZA_MOVIMIENTOS_RECALCULO_FALLAR`(
  IN p_TOKEN char(36),
  IN p_ALMACEN varchar(10),
  IN p_SKU varchar(50),
  IN p_MENSAJE varchar(1000),
  IN p_SEGUNDOS_REINTENTO int,
  IN p_USUARIO varchar(50)
)
BEGIN
  UPDATE fza_movimientos_recalculos_pendientes
     SET ESTADO_MOVREC = 'ERROR',
         ESPROCESADO_MOVREC = 'N',
         INSTANTE_PROXIMO_INTENTO_MOVREC = TIMESTAMPADD(
           SECOND,
           GREATEST(IFNULL(p_SEGUNDOS_REINTENTO, 0), 0),
           NOW()),
         INSTANTE_LIMITE_RECLAMACION_MOVREC = NULL,
         MENSAJE_ERROR_MOVREC = LEFT(COALESCE(
           NULLIF(TRIM(p_MENSAJE), ''), 'Error sin detalle'), 1000),
         RESUMEN_CORRECCION_MOVREC = NULL,
         INSTANTE_PROCESADO_MOVREC = NULL,
         INSTANTE_MODIF = NOW(),
         USUARIO_MODIF = LEFT(COALESCE(
           NULLIF(TRIM(p_USUARIO), ''), 'SISTEMA'), 50)
   WHERE TOKEN_RECLAMACION_MOVREC = p_TOKEN
     AND CODIGO_ALM_MOVREC = p_ALMACEN
     AND CODIGO_UNIDAD_MOVREC = p_SKU
     AND ESTADO_MOVREC = 'PROCESANDO'
     AND ESPROCESADO_MOVREC = 'N';
END
;;
