CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_FZA_MOVIMIENTOS_RECALCULO_INVENTARIOS`()
BEGIN
  DECLARE v_FIN varchar(1) DEFAULT 'N';
  DECLARE v_EMPRESA varchar(10);
  DECLARE v_ALMACEN varchar(10);
  DECLARE v_SERIE varchar(20);
  DECLARE v_NUMERO varchar(20);
  DECLARE v_LINEA varchar(8);
  DECLARE v_CANTIDAD decimal(19,6);
  DECLARE v_PMP decimal(19,6);
  DECLARE v_COSTE_ENTRADA decimal(19,6);
  
  
  
  DECLARE c_INVENTARIOS CURSOR FOR
    SELECT L.CODIGO_EMP_INVLIN,
           L.CODIGO_ALM_INVLIN,
           L.SERIE_INV_INVLIN,
           L.NUMERO_INV_INVLIN,
           L.LINEA_INVLIN,
           S.CANTIDAD_MOV,
           S.PRECIO_MEDIO_MOV,
           IFNULL(E.PRECIO_COSTE_UNITARIO_MOV, S.PRECIO_MEDIO_MOV)
      FROM tmp_movimientos_ordenados O
      STRAIGHT_JOIN fza_movimientos_almacen S ON S.NUMERO_MOV = O.numero_mov
      JOIN fza_inventarios I
        ON I.CODIGO_ALM_INV = S.CODIGO_ALM_MOV
       AND I.SERIE_INV = S.SERIE_DOC_MOV
       AND I.NUMERO_INV = S.NUMERO_DOC_MOV
      JOIN fza_inventarios_lineas L
        ON L.CODIGO_EMP_INVLIN = I.CODIGO_EMP_INV
       AND L.CODIGO_ALM_INVLIN = I.CODIGO_ALM_INV
       AND L.SERIE_INV_INVLIN = I.SERIE_INV
       AND L.NUMERO_INV_INVLIN = I.NUMERO_INV
       AND CAST(L.LINEA_INVLIN AS UNSIGNED) = CAST(S.LINEA_MOV AS UNSIGNED)
      LEFT JOIN fza_movimientos_almacen E
        ON E.TIPO_DOC_MOV = 'IN'
       AND E.TIPO_MOV = 'E'
       AND E.CODIGO_ALM_MOV = S.CODIGO_ALM_MOV
       AND E.CODIGO_UNIDAD_MOV = S.CODIGO_UNIDAD_MOV
       AND E.SERIE_DOC_MOV = S.SERIE_DOC_MOV
       AND E.NUMERO_DOC_MOV = S.NUMERO_DOC_MOV
       AND CAST(E.LINEA_MOV AS UNSIGNED) = CAST(S.LINEA_MOV AS UNSIGNED)
     WHERE O.es_cierre_inventario = 'S'
       AND S.TIPO_DOC_MOV = 'IN'
       AND S.TIPO_MOV = 'S'
       AND I.ESTADO_INV IN ('APLICADO', 'ABIERTO')
     ORDER BY L.CODIGO_EMP_INVLIN, L.CODIGO_ALM_INVLIN,
              L.SERIE_INV_INVLIN, L.NUMERO_INV_INVLIN, L.LINEA_INVLIN;
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_FIN = 'S';
  OPEN c_INVENTARIOS;
  FETCH c_INVENTARIOS INTO v_EMPRESA, v_ALMACEN, v_SERIE, v_NUMERO,
    v_LINEA, v_CANTIDAD, v_PMP, v_COSTE_ENTRADA;
  WHILE v_FIN = 'N' DO
    
    
    UPDATE fza_inventarios_lineas
       SET CANTIDAD_TEORICA_INVLIN = v_CANTIDAD,
           PRECIO_MEDIO_INVLIN = v_PMP,
           PRECIO_MEDIO_NUEVO_INVLIN = IF(
             ESPRECIO_MEDIO_CORREGIDO_INVLIN = 'S',
             PRECIO_MEDIO_NUEVO_INVLIN, v_COSTE_ENTRADA),
           CANTIDAD_DIFERENCIA_INVLIN = CANTIDAD_FISICA_INVLIN - v_CANTIDAD,
           TOTAL_COSTE_DIFERENCIA_INVLIN = ROUND(
             (CANTIDAD_FISICA_INVLIN * IF(
               ESPRECIO_MEDIO_CORREGIDO_INVLIN = 'S',
               PRECIO_MEDIO_NUEVO_INVLIN, v_COSTE_ENTRADA)) -
             (v_CANTIDAD * v_PMP), 2),
           INSTANTE_MODIF = NOW()
     WHERE CODIGO_EMP_INVLIN = v_EMPRESA
       AND CODIGO_ALM_INVLIN = v_ALMACEN
       AND SERIE_INV_INVLIN = v_SERIE
       AND NUMERO_INV_INVLIN = v_NUMERO
       AND LINEA_INVLIN = v_LINEA
       AND (NOT (CANTIDAD_TEORICA_INVLIN <=> v_CANTIDAD)
         OR NOT (PRECIO_MEDIO_INVLIN <=> v_PMP)
         OR NOT (PRECIO_MEDIO_NUEVO_INVLIN <=> IF(
           ESPRECIO_MEDIO_CORREGIDO_INVLIN = 'S',
           PRECIO_MEDIO_NUEVO_INVLIN, v_COSTE_ENTRADA))
         OR NOT (CANTIDAD_DIFERENCIA_INVLIN <=> ROUND(
           CANTIDAD_FISICA_INVLIN - v_CANTIDAD, 6))
         OR (NOT (TOTAL_COSTE_DIFERENCIA_INVLIN <=> ROUND(
           (CANTIDAD_FISICA_INVLIN * IF(
             ESPRECIO_MEDIO_CORREGIDO_INVLIN = 'S',
             PRECIO_MEDIO_NUEVO_INVLIN, v_COSTE_ENTRADA)) -
           (v_CANTIDAD * v_PMP), 2))
           AND NOT (TOTAL_COSTE_DIFERENCIA_INVLIN <=> ROUND(
           (CANTIDAD_FISICA_INVLIN * IF(
             ESPRECIO_MEDIO_CORREGIDO_INVLIN = 'S',
             PRECIO_MEDIO_NUEVO_INVLIN, v_COSTE_ENTRADA)) -
           (v_CANTIDAD * v_PMP), 6))));
    FETCH c_INVENTARIOS INTO v_EMPRESA, v_ALMACEN, v_SERIE, v_NUMERO,
      v_LINEA, v_CANTIDAD, v_PMP, v_COSTE_ENTRADA;
  END WHILE;
  CLOSE c_INVENTARIOS;
END
;;
DELIMITER ;
