/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_spanish_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_FZA_MOVIMIENTOS_RECALCULO_PROCESAR_GRUPO`(
  IN p_EMPRESA varchar(20),
  IN p_ALMACEN varchar(10),
  IN p_SKU varchar(50),
  IN p_INSTANTE_DESDE datetime,
  IN p_USUARIO varchar(50),
  OUT p_RESUMEN varchar(1000)
)
BEGIN
  DECLARE v_REVISADOS bigint DEFAULT 0;
  DECLARE v_CANTIDAD_ANTES decimal(19,6) DEFAULT 0;
  DECLARE v_PMP_ANTES decimal(19,6) DEFAULT 0;
  DECLARE v_VALOR_ANTES decimal(19,6) DEFAULT 0;
  DECLARE v_CANTIDAD_DESPUES decimal(19,6) DEFAULT 0;
  DECLARE v_PMP_DESPUES decimal(19,6) DEFAULT 0;
  DECLARE v_VALOR_DESPUES decimal(19,6) DEFAULT 0;
  IF @@in_transaction = 0 THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'PROCESAR_GRUPO requiere transaccion activa';
  END IF;
  CALL PRC_FZA_MOVIMIENTOS_RECALCULO_RAICES_RESTAURAR();
  
  SELECT IFNULL(SUM(S.CANTIDAD_STK), 0),
         IFNULL(MAX(S.PRECIO_MEDIO_STK), 0),
         IFNULL(SUM(S.VALOR_TOTAL_STK), 0)
    INTO v_CANTIDAD_ANTES, v_PMP_ANTES, v_VALOR_ANTES
    FROM fza_articulos_stockactual S
   WHERE S.CODIGO_ALM_STK = p_ALMACEN
     AND S.CODIGO_UNIDAD_STK = p_SKU;
  SELECT COUNT(*)
    INTO v_REVISADOS
    FROM fza_movimientos_almacen M
   WHERE M.CODIGO_ALM_MOV = p_ALMACEN
     AND M.CODIGO_UNIDAD_MOV = p_SKU
     AND M.ESACTIVO_MOV = 'S'
     AND IFNULL(M.FECHA_MOV, '1000-01-01 00:00:00') >=
         IFNULL(p_INSTANTE_DESDE, '1000-01-01 00:00:00');
  CALL PRC_FZA_MOVIMIENTOS_RECALCULO_EJECUTAR_DIFERIDO();
  SELECT IFNULL(SUM(S.CANTIDAD_STK), 0),
         IFNULL(MAX(S.PRECIO_MEDIO_STK), 0),
         IFNULL(SUM(S.VALOR_TOTAL_STK), 0)
    INTO v_CANTIDAD_DESPUES, v_PMP_DESPUES, v_VALOR_DESPUES
    FROM fza_articulos_stockactual S
   WHERE S.CODIGO_ALM_STK = p_ALMACEN
     AND S.CODIGO_UNIDAD_STK = p_SKU;
  SET p_RESUMEN = CONCAT(
    'Revisados: ', v_REVISADOS,
    '; desde: ', DATE_FORMAT(
      IFNULL(p_INSTANTE_DESDE, '1000-01-01 00:00:00'),
      '%Y-%m-%d %H:%i:%s'),
    '; cantidad: ', v_CANTIDAD_ANTES, ' -> ', v_CANTIDAD_DESPUES,
    '; PMP: ', v_PMP_ANTES, ' -> ', v_PMP_DESPUES,
    '; valor: ', v_VALOR_ANTES, ' -> ', v_VALOR_DESPUES);
END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_VALUE_ON_ZERO' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `PRC_FZA_MOVIMIENTOS_RECALCULO_PROCESAR_LOTE` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_spanish_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_FZA_MOVIMIENTOS_RECALCULO_PROCESAR_LOTE`(
  IN p_MAX_GRUPOS int,
  IN p_PAUSA_MILISEGUNDOS int,
  IN p_SEGUNDOS_LEASE int,
  IN p_SEGUNDOS_REINTENTO int,
  IN p_USUARIO varchar(50)
)
BEGIN
  DECLARE v_TOKEN char(36);
  DECLARE v_EMPRESA varchar(20);
  DECLARE v_ALMACEN varchar(10);
  DECLARE v_SKU varchar(50);
  DECLARE v_DESDE datetime;
  DECLARE v_FALLO varchar(1) DEFAULT 'N';
  DECLARE v_ERROR varchar(1000) DEFAULT '';
  DECLARE v_RESUMEN varchar(1000) DEFAULT '';
  DECLARE v_CIERRE_ESTABLE varchar(1) DEFAULT 'N';
  DECLARE v_CIERRE_PROCESADO varchar(1) DEFAULT 'N';
  DECLARE v_INTENTOS_CIERRE int DEFAULT 0;
  DECLARE v_COMPLETADOS int DEFAULT 0;
  DECLARE v_ERRORES int DEFAULT 0;
  DECLARE v_TOTAL int DEFAULT 0;
  DECLARE v_ESPERA int DEFAULT 0;
  IF @@in_transaction <> 0 THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'PROCESAR_LOTE requiere conexion sin transaccion';
  END IF;
  IF IFNULL(p_PAUSA_MILISEGUNDOS, -1) NOT BETWEEN 0 AND 60000 THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'PAUSA_MILISEGUNDOS debe estar entre 0 y 60000';
  END IF;
  IF IFNULL(p_MAX_GRUPOS, 0) NOT BETWEEN 1 AND 100 THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'MAX_GRUPOS debe estar entre 1 y 100';
  END IF;
  IF IFNULL(p_SEGUNDOS_REINTENTO, 0) NOT BETWEEN 1 AND 604800 THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'SEGUNDOS_REINTENTO debe estar entre 1 y 604800';
  END IF;
  lote: WHILE v_TOTAL < p_MAX_GRUPOS DO
    SET v_TOKEN = UUID();
    CALL PRC_FZA_MOVIMIENTOS_RECALCULO_RECLAMAR_INTERNO(
      1, p_SEGUNDOS_LEASE, v_TOKEN, p_USUARIO);
    IF EXISTS (
      SELECT 1
        FROM fza_movimientos_recalculos_pendientes Q
       WHERE Q.TOKEN_RECLAMACION_MOVREC = v_TOKEN
         AND Q.ESTADO_MOVREC = 'PROCESANDO'
    ) THEN
      SELECT MIN(Q.CODIGO_EMP_MOVREC),
             Q.CODIGO_ALM_MOVREC,
             Q.CODIGO_UNIDAD_MOVREC,
             MIN(Q.INSTANTE_DESDE_MOVREC)
        INTO v_EMPRESA, v_ALMACEN, v_SKU, v_DESDE
        FROM fza_movimientos_recalculos_pendientes Q
       WHERE Q.TOKEN_RECLAMACION_MOVREC = v_TOKEN
         AND Q.ESTADO_MOVREC = 'PROCESANDO'
       GROUP BY Q.CODIGO_ALM_MOVREC, Q.CODIGO_UNIDAD_MOVREC
       LIMIT 1;
      SET v_FALLO = 'N';
      SET v_ERROR = '';
      SET v_RESUMEN = '';
      SET v_CIERRE_PROCESADO = 'N';
      SET v_INTENTOS_CIERRE = 0;
      BEGIN
        DECLARE EXIT HANDLER FOR SQLEXCEPTION
        BEGIN
          GET DIAGNOSTICS CONDITION 1 v_ERROR = MESSAGE_TEXT;
          ROLLBACK;
          SET v_FALLO = 'S';
        END;
        cierre: WHILE v_CIERRE_PROCESADO = 'N' AND
                      v_INTENTOS_CIERRE < 3 DO
          CALL PRC_FZA_MOVIMIENTOS_RECALCULO_PREPARAR();
          CALL PRC_FZA_MOVIMIENTOS_RECALCULO_MARCAR(
            v_EMPRESA,
            v_ALMACEN,
            v_SKU,
            IFNULL(v_DESDE, '1000-01-01 00:00:00'));
          
          
          CALL PRC_FZA_MOVIMIENTOS_RECALCULO_CIERRE_PREPARAR();
          
          
          COMMIT;
          SET TRANSACTION ISOLATION LEVEL READ COMMITTED;
          START TRANSACTION;
          CALL PRC_FZA_MOVIMIENTOS_RECALCULO_CIERRE_BLOQUEAR(
            p_USUARIO);
          CALL PRC_FZA_MOVIMIENTOS_RECALCULO_CIERRE_VALIDAR(
            v_CIERRE_ESTABLE);
          IF v_CIERRE_ESTABLE = 'S' THEN
            CALL PRC_FZA_MOVIMIENTOS_RECALCULO_PROCESAR_GRUPO(
              v_EMPRESA,
              v_ALMACEN,
              v_SKU,
              v_DESDE,
              p_USUARIO,
              v_RESUMEN);
            CALL PRC_FZA_MOVIMIENTOS_RECALCULO_COMPLETAR(
              v_TOKEN, v_ALMACEN, v_SKU, v_RESUMEN, p_USUARIO);
            COMMIT;
            SET v_CIERRE_PROCESADO = 'S';
          ELSE
            ROLLBACK;
          END IF;
          SET v_INTENTOS_CIERRE = v_INTENTOS_CIERRE + 1;
        END WHILE cierre;
        IF v_CIERRE_PROCESADO = 'N' THEN
          SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT =
              'El cierre de traspasos no se estabilizo en tres intentos';
        END IF;
      END;
      IF v_FALLO = 'S' THEN
        START TRANSACTION;
        CALL PRC_FZA_MOVIMIENTOS_RECALCULO_FALLAR(
          v_TOKEN,
          v_ALMACEN,
          v_SKU,
          v_ERROR,
          p_SEGUNDOS_REINTENTO,
          p_USUARIO);
        COMMIT;
        SET v_ERRORES = v_ERRORES + 1;
      ELSE
        SET v_COMPLETADOS = v_COMPLETADOS + 1;
      END IF;
      SET v_TOTAL = v_TOTAL + 1;
      IF p_PAUSA_MILISEGUNDOS > 0 THEN
        SELECT SLEEP(p_PAUSA_MILISEGUNDOS / 1000)
          INTO v_ESPERA;
      END IF;
    ELSE
      
      
      COMMIT;
      LEAVE lote;
    END IF;
  END WHILE lote;
  SELECT v_TOKEN AS TOKEN_LOTE,
         v_COMPLETADOS AS GRUPOS_PROCESADOS,
         v_ERRORES AS GRUPOS_ERROR;
END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_VALUE_ON_ZERO' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `PRC_FZA_MOVIMIENTOS_RECALCULO_PROPAGAR` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_spanish_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_FZA_MOVIMIENTOS_RECALCULO_PROPAGAR`(
  OUT p_CAMBIOS int
)
BEGIN
  DECLARE v_FUERA_CIERRE int DEFAULT 0;
  DROP TEMPORARY TABLE IF EXISTS tmp_traspasos_propagar;
  CREATE TEMPORARY TABLE tmp_traspasos_propagar (
    numero_entrada varchar(20) NOT NULL,
    empresa varchar(20) NOT NULL,
    almacen varchar(10) NOT NULL,
    sku varchar(50) NOT NULL,
    instante_desde datetime NOT NULL,
    coste_salida decimal(19,6) NOT NULL,
    PRIMARY KEY (numero_entrada)
  ) ENGINE=InnoDB;
  INSERT INTO tmp_traspasos_propagar
    (numero_entrada, empresa, almacen, sku, instante_desde, coste_salida)
  SELECT e.NUMERO_MOV,
         IFNULL(e.CODIGO_EMP_MOV, ''),
         e.CODIGO_ALM_MOV,
         e.CODIGO_UNIDAD_MOV,
         IFNULL(e.FECHA_MOV, '1000-01-01 00:00:00'),
         SUM(s.TOTAL_COSTE_MOV) / NULLIF(SUM(s.CANTIDAD_MOV), 0)
    FROM tmp_movimientos_recalculo r
    JOIN fza_movimientos_almacen s
      ON s.CODIGO_ALM_MOV = r.almacen
     AND s.CODIGO_UNIDAD_MOV = r.sku
     AND s.ESACTIVO_MOV = 'S'
     AND s.TIPO_DOC_MOV IN ('TR', 'AT', 'TA')
     AND s.TIPO_MOV = 'S'
     AND IFNULL(s.FECHA_MOV, '1000-01-01 00:00:00') >= r.instante_desde
    JOIN fza_movimientos_almacen e
      ON e.TIPO_DOC_MOV = s.TIPO_DOC_MOV
     AND e.SERIE_DOC_MOV = s.SERIE_DOC_MOV
     AND e.NUMERO_DOC_MOV = s.NUMERO_DOC_MOV
     AND e.CODIGO_UNIDAD_MOV = s.CODIGO_UNIDAD_MOV
     AND e.CODIGO_ALM_MOV = s.CODIGO_ALM_CONTRA_MOV
     AND e.CODIGO_ALM_CONTRA_MOV = s.CODIGO_ALM_MOV
     AND e.ESACTIVO_MOV = 'S'
     AND e.TIPO_MOV = 'E'
     AND (e.LINEA_MOV = s.LINEA_MOV OR
          (IFNULL(e.NUMERO_OPERACION_DOC_MOV, '') <> '' AND
           e.NUMERO_OPERACION_DOC_MOV = s.NUMERO_OPERACION_DOC_MOV))
   GROUP BY e.NUMERO_MOV, e.CODIGO_EMP_MOV, e.CODIGO_ALM_MOV,
             e.CODIGO_UNIDAD_MOV, e.FECHA_MOV,
             e.PRECIO_COSTE_UNITARIO_MOV
  HAVING ABS(IFNULL(e.PRECIO_COSTE_UNITARIO_MOV, 0) -
         (SUM(s.TOTAL_COSTE_MOV) / NULLIF(SUM(s.CANTIDAD_MOV), 0))) >
         0.0000005;
  SELECT COUNT(*) INTO v_FUERA_CIERRE
    FROM tmp_traspasos_propagar p
    LEFT JOIN tmp_movimientos_recalculo_cierre_bloqueado cierre
      ON cierre.almacen = p.almacen
     AND cierre.sku = p.sku
   WHERE cierre.almacen IS NULL
      OR p.instante_desde < cierre.instante_desde;
  IF v_FUERA_CIERRE > 0 THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT =
        'El cierre de traspasos cambio durante el recalculo';
  END IF;
  SELECT COUNT(*) INTO p_CAMBIOS FROM tmp_traspasos_propagar;
  UPDATE fza_movimientos_almacen e
  JOIN tmp_traspasos_propagar p ON p.numero_entrada = e.NUMERO_MOV
     SET e.PRECIO_COSTE_UNITARIO_MOV = p.coste_salida,
         e.INSTANTE_MODIF = NOW();
  DELETE FROM tmp_movimientos_recalculo;
  INSERT INTO tmp_movimientos_recalculo
    (empresa, almacen, sku, instante_desde)
  SELECT MIN(empresa), almacen, sku, MIN(instante_desde)
    FROM tmp_traspasos_propagar
   GROUP BY almacen, sku;
  DROP TEMPORARY TABLE IF EXISTS tmp_traspasos_propagar;
END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_VALUE_ON_ZERO' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `PRC_FZA_MOVIMIENTOS_RECALCULO_RAICES_RESTAURAR` */;
