CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_FZA_MOVIMIENTOS_RECALCULO_RAICES_RESTAURAR`()
BEGIN
  DELETE FROM tmp_movimientos_recalculo;
  INSERT INTO tmp_movimientos_recalculo
    (empresa, almacen, sku, instante_desde)
  SELECT empresa, almacen, sku, instante_desde
    FROM tmp_movimientos_recalculo_raices;
END
;;
