/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_spanish_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_FZA_MOVIMIENTOS_RECALCULO_RECLAMAR`(
  IN p_MAX_GRUPOS int,
  IN p_SEGUNDOS_LEASE int,
  IN p_TOKEN char(36),
  IN p_USUARIO varchar(50)
)
BEGIN
  CALL PRC_FZA_MOVIMIENTOS_RECALCULO_RECLAMAR_INTERNO(
    p_MAX_GRUPOS, p_SEGUNDOS_LEASE, p_TOKEN, p_USUARIO);
  SELECT MIN(Q.CODIGO_EMP_MOVREC) AS CODIGO_EMPRESA,
         Q.CODIGO_ALM_MOVREC AS CODIGO_ALMACEN,
         Q.CODIGO_UNIDAD_MOVREC AS CODIGO_UNIDAD,
         MIN(Q.INSTANTE_DESDE_MOVREC) AS INSTANTE_DESDE,
         COUNT(*) AS CANTIDAD_PENDIENTES
    FROM fza_movimientos_recalculos_pendientes Q
   WHERE Q.TOKEN_RECLAMACION_MOVREC = p_TOKEN
     AND Q.ESTADO_MOVREC = 'PROCESANDO'
   GROUP BY Q.CODIGO_ALM_MOVREC, Q.CODIGO_UNIDAD_MOVREC
   ORDER BY MIN(Q.INSTANTE_DESDE_MOVREC),
            Q.CODIGO_ALM_MOVREC,
            Q.CODIGO_UNIDAD_MOVREC;
END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_VALUE_ON_ZERO' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `PRC_FZA_MOVIMIENTOS_RECALCULO_RECLAMAR_INTERNO` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_spanish_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_FZA_MOVIMIENTOS_RECALCULO_RECLAMAR_INTERNO`(
  IN p_MAX_GRUPOS int,
  IN p_SEGUNDOS_LEASE int,
  IN p_TOKEN char(36),
  IN p_USUARIO varchar(50)
)
BEGIN
  DECLARE v_TRANSACCION_PROPIA varchar(1) DEFAULT 'N';
  DECLARE v_TABLA_TEMPORAL_PROPIA varchar(1) DEFAULT 'N';
  DECLARE v_TOKEN_EXISTENTE int DEFAULT 0;
  DECLARE v_CERROJO varchar(64);
  DECLARE v_ADQUIRIDO int DEFAULT 0;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    IF v_TRANSACCION_PROPIA = 'S' THEN
      ROLLBACK;
    END IF;
    IF v_TABLA_TEMPORAL_PROPIA = 'S' THEN
      DROP TEMPORARY TABLE IF EXISTS tmp_movrec_grupos;
    END IF;
    IF v_ADQUIRIDO = 1 THEN
      DO RELEASE_LOCK(v_CERROJO);
    END IF;
    RESIGNAL;
  END;
  IF IFNULL(p_MAX_GRUPOS, 0) NOT BETWEEN 1 AND 100 THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'MAX_GRUPOS debe estar entre 1 y 100';
  END IF;
  IF IFNULL(p_SEGUNDOS_LEASE, 0) NOT BETWEEN 30 AND 86400 THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'SEGUNDOS_LEASE debe estar entre 30 y 86400';
  END IF;
  IF NULLIF(TRIM(p_TOKEN), '') IS NULL THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'El token de reclamacion es obligatorio';
  END IF;
  IF @@in_transaction <> 0 THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'RECLAMAR requiere una conexion sin transaccion';
  END IF;
  
  SET v_CERROJO = CONCAT('fza_movrec_', MD5(DATABASE()));
  SET v_ADQUIRIDO = GET_LOCK(v_CERROJO, 30);
  IF COALESCE(v_ADQUIRIDO, 0) <> 1 THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'No se pudo bloquear la reclamacion de stock';
  END IF;
  SET v_TABLA_TEMPORAL_PROPIA = 'S';
  DROP TEMPORARY TABLE IF EXISTS tmp_movrec_grupos;
  CREATE TEMPORARY TABLE tmp_movrec_grupos (
    almacen varchar(10) NOT NULL,
    sku varchar(50) NOT NULL,
    instante_desde datetime NOT NULL,
    PRIMARY KEY (almacen, sku)
  ) ENGINE=InnoDB;
  
  
  SET TRANSACTION ISOLATION LEVEL READ COMMITTED;
  START TRANSACTION;
  SET v_TRANSACCION_PROPIA = 'S';
  
  BEGIN
    DECLARE v_FIN int DEFAULT 0;
    DECLARE v_NUMERO varchar(20);
    DECLARE c_CADUCADOS CURSOR FOR
      SELECT NUMERO_MOV_MOVREC
        FROM fza_movimientos_recalculos_pendientes
       WHERE ESTADO_MOVREC = 'PROCESANDO'
         AND ESPROCESADO_MOVREC = 'N'
         AND (INSTANTE_LIMITE_RECLAMACION_MOVREC IS NULL OR
              INSTANTE_LIMITE_RECLAMACION_MOVREC <= NOW())
       ORDER BY NUMERO_MOV_MOVREC;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_FIN = 1;
    OPEN c_CADUCADOS;
    FETCH c_CADUCADOS INTO v_NUMERO;
    WHILE v_FIN = 0 DO
      UPDATE fza_movimientos_recalculos_pendientes
         SET ESTADO_MOVREC = 'ERROR',
             ESPROCESADO_MOVREC = 'N',
             INSTANTE_PROXIMO_INTENTO_MOVREC = NOW(),
             TOKEN_RECLAMACION_MOVREC = NULL,
             INSTANTE_LIMITE_RECLAMACION_MOVREC = NULL,
             MENSAJE_ERROR_MOVREC = 'Lease agotado; se permite reintento',
             RESUMEN_CORRECCION_MOVREC = NULL,
             INSTANTE_MODIF = NOW(),
             USUARIO_MODIF = LEFT(COALESCE(
               NULLIF(TRIM(p_USUARIO), ''), 'SISTEMA'), 50)
       WHERE NUMERO_MOV_MOVREC = v_NUMERO
         AND ESTADO_MOVREC = 'PROCESANDO'
         AND ESPROCESADO_MOVREC = 'N'
         AND (INSTANTE_LIMITE_RECLAMACION_MOVREC IS NULL OR
              INSTANTE_LIMITE_RECLAMACION_MOVREC <= NOW());
      FETCH c_CADUCADOS INTO v_NUMERO;
    END WHILE;
    CLOSE c_CADUCADOS;
  END;
  SELECT COUNT(*)
    INTO v_TOKEN_EXISTENTE
    FROM fza_movimientos_recalculos_pendientes Q
   WHERE Q.TOKEN_RECLAMACION_MOVREC = p_TOKEN;
  IF v_TOKEN_EXISTENTE = 0 THEN
    CALL PRC_FZA_MOVREC_RECLAMAR_GRUPOS(
      p_MAX_GRUPOS, p_SEGUNDOS_LEASE, p_TOKEN, p_USUARIO);
  END IF;
  COMMIT;
  SET v_TRANSACCION_PROPIA = 'N';
  DROP TEMPORARY TABLE IF EXISTS tmp_movrec_grupos;
  SET v_TABLA_TEMPORAL_PROPIA = 'N';
  DO RELEASE_LOCK(v_CERROJO);
END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_VALUE_ON_ZERO' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `PRC_FZA_MOVIMIENTOS_VALORAR_ALTA` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_spanish_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_FZA_MOVIMIENTOS_VALORAR_ALTA`(
  IN p_ALMACEN varchar(10), IN p_SKU varchar(50),
  IN p_DOCUMENTO varchar(20), IN p_TIPO varchar(1),
  IN p_CANTIDAD decimal(19,6), INOUT p_COSTE decimal(19,6),
  OUT p_TOTAL decimal(19,6), OUT p_STOCK decimal(19,6),
  OUT p_VALOR decimal(19,6), OUT p_PMP decimal(19,6))
BEGIN
  DECLARE v_STOCK decimal(19,6) DEFAULT 0;
  DECLARE v_VALOR decimal(19,6) DEFAULT 0;
  DECLARE v_PMP decimal(28,12) DEFAULT 0;
  DECLARE v_HAY_STOCK int DEFAULT 0;
  SELECT COUNT(*), IFNULL(SUM(CANTIDAD_STK), 0),
         IFNULL(SUM(VALOR_TOTAL_STK), 0),
         IFNULL(MAX(PRECIO_MEDIO_STK), 0)
    INTO v_HAY_STOCK, v_STOCK, v_VALOR, v_PMP
    FROM fza_articulos_stockactual
   WHERE CODIGO_ALM_STK = p_ALMACEN AND CODIGO_UNIDAD_STK = p_SKU
     FOR UPDATE;
  IF v_STOCK > 0 THEN
    SET v_PMP = v_VALOR / v_STOCK;
  ELSE
    SET v_PMP = COALESCE((
      SELECT PRECIO_MEDIO_MOV FROM fza_movimientos_almacen
       WHERE CODIGO_ALM_MOV = p_ALMACEN AND CODIGO_UNIDAD_MOV = p_SKU
         AND ESACTIVO_MOV = 'S'
       ORDER BY FECHA_MOV DESC, INSTANTE_ALTA DESC, NUMERO_MOV DESC
       LIMIT 1 FOR UPDATE), IF(v_HAY_STOCK > 0, v_PMP, p_COSTE), 0);
  END IF;
  SET p_STOCK = v_STOCK + IF(p_TIPO = 'E', p_CANTIDAD, -p_CANTIDAD);
  
  IF p_TIPO = 'S' OR p_DOCUMENTO IN ('VE', 'FC', 'AV', 'LT') THEN
    SET p_COSTE = v_PMP;
    SET p_TOTAL = ROUND(p_CANTIDAD * v_PMP, 6);
  ELSE
    SET p_TOTAL = ROUND(p_CANTIDAD * p_COSTE, 6);
  END IF;
  IF p_TIPO = 'E' THEN
    IF v_STOCK <= 0 THEN
      SET v_PMP = p_COSTE;
      SET p_VALOR = IF(p_STOCK > 0, p_STOCK * p_COSTE, 0);
    ELSE
      SET p_VALOR = v_VALOR + p_TOTAL;
      SET v_PMP = IF(p_STOCK > 0, p_VALOR / p_STOCK, p_COSTE);
    END IF;
  ELSE
    SET p_VALOR = IF(p_STOCK > 0, v_VALOR - p_TOTAL, 0);
  END IF;
  SET p_PMP = v_PMP;
END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_VALUE_ON_ZERO' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `PRC_FZA_MOVREC_RECLAMAR_GRUPOS` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_spanish_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_FZA_MOVREC_RECLAMAR_GRUPOS`(
  IN p_MAX_GRUPOS int, IN p_SEGUNDOS_LEASE int,
  IN p_TOKEN char(36), IN p_USUARIO varchar(50))
BEGIN
  DECLARE v_FIN int DEFAULT 0;
  DECLARE v_NUMERO varchar(20);
  DECLARE c_FILAS CURSOR FOR
    SELECT Q.NUMERO_MOV_MOVREC
      FROM tmp_movrec_grupos G
      JOIN fza_movimientos_recalculos_pendientes Q
        ON Q.CODIGO_ALM_MOVREC = G.almacen
       AND Q.CODIGO_UNIDAD_MOVREC = G.sku
     WHERE Q.ESPROCESADO_MOVREC = 'N'
       AND Q.ESTADO_MOVREC IN ('PENDIENTE', 'ERROR')
       AND (Q.INSTANTE_PROXIMO_INTENTO_MOVREC IS NULL OR
            Q.INSTANTE_PROXIMO_INTENTO_MOVREC <= NOW())
     ORDER BY Q.NUMERO_MOV_MOVREC;
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_FIN = 1;
  INSERT INTO tmp_movrec_grupos (almacen, sku, instante_desde)
  SELECT Q.CODIGO_ALM_MOVREC,
         Q.CODIGO_UNIDAD_MOVREC,
         MIN(Q.INSTANTE_DESDE_MOVREC)
    FROM fza_movimientos_recalculos_pendientes Q
   WHERE Q.ESPROCESADO_MOVREC = 'N'
     AND Q.ESTADO_MOVREC IN ('PENDIENTE', 'ERROR')
     AND (Q.INSTANTE_PROXIMO_INTENTO_MOVREC IS NULL OR
          Q.INSTANTE_PROXIMO_INTENTO_MOVREC <= NOW())
     AND NOT EXISTS (
       SELECT 1
         FROM fza_movimientos_recalculos_pendientes B
        WHERE B.CODIGO_ALM_MOVREC = Q.CODIGO_ALM_MOVREC
          AND B.CODIGO_UNIDAD_MOVREC = Q.CODIGO_UNIDAD_MOVREC
          AND B.ESTADO_MOVREC = 'PROCESANDO'
          AND B.ESPROCESADO_MOVREC = 'N'
          AND B.INSTANTE_LIMITE_RECLAMACION_MOVREC > NOW())
     AND NOT EXISTS (
       SELECT 1
         FROM fza_movimientos_recalculos_pendientes E
        WHERE E.CODIGO_ALM_MOVREC = Q.CODIGO_ALM_MOVREC
          AND E.CODIGO_UNIDAD_MOVREC = Q.CODIGO_UNIDAD_MOVREC
          AND E.ESPROCESADO_MOVREC = 'N'
          AND E.INSTANTE_PROXIMO_INTENTO_MOVREC > NOW())
   GROUP BY Q.CODIGO_ALM_MOVREC, Q.CODIGO_UNIDAD_MOVREC
   ORDER BY MIN(Q.INSTANTE_DESDE_MOVREC),
            Q.CODIGO_ALM_MOVREC,
            Q.CODIGO_UNIDAD_MOVREC
   LIMIT p_MAX_GRUPOS;
  
  OPEN c_FILAS;
  FETCH c_FILAS INTO v_NUMERO;
  WHILE v_FIN = 0 DO
    UPDATE fza_movimientos_recalculos_pendientes Q
     SET Q.ESTADO_MOVREC = 'PROCESANDO',
         Q.ESPROCESADO_MOVREC = 'N',
         Q.CONTADOR_INTENTOS_MOVREC = Q.CONTADOR_INTENTOS_MOVREC + 1,
         Q.TOKEN_RECLAMACION_MOVREC = p_TOKEN,
         Q.INSTANTE_RECLAMACION_MOVREC = NOW(),
         Q.INSTANTE_LIMITE_RECLAMACION_MOVREC =
           DATE_ADD(NOW(), INTERVAL p_SEGUNDOS_LEASE SECOND),
         Q.MENSAJE_ERROR_MOVREC = NULL,
         Q.INSTANTE_MODIF = NOW(),
         Q.USUARIO_MODIF = LEFT(COALESCE(
           NULLIF(TRIM(p_USUARIO), ''), 'SISTEMA'), 50)
   WHERE Q.NUMERO_MOV_MOVREC = v_NUMERO
     AND EXISTS (SELECT 1 FROM tmp_movrec_grupos G
                  WHERE G.almacen = Q.CODIGO_ALM_MOVREC
                    AND G.sku = Q.CODIGO_UNIDAD_MOVREC)
     AND Q.ESPROCESADO_MOVREC = 'N'
     AND Q.ESTADO_MOVREC IN ('PENDIENTE', 'ERROR')
     AND (Q.INSTANTE_PROXIMO_INTENTO_MOVREC IS NULL OR
          Q.INSTANTE_PROXIMO_INTENTO_MOVREC <= NOW());
    FETCH c_FILAS INTO v_NUMERO;
  END WHILE;
  CLOSE c_FILAS;
END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `PRC_FZA_REPARACION_NUMERAR` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_spanish_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_FZA_REPARACION_NUMERAR`(
 IN P_ID bigint, IN P_USUARIO varchar(100))
BEGIN
 DECLARE V_ALMACEN varchar(10);
 DECLARE V_EMPRESA varchar(10);
 DECLARE V_NUMERO bigint;
 DECLARE V_MAXIMO bigint;
 IF @@in_transaction = 0 THEN
  SIGNAL SQLSTATE '45000'
   SET MESSAGE_TEXT='La numeración requiere la transacción del alta.';
 END IF;
 SELECT G.CODIGO_ALM_GAR, G.NUMERO_ORDEN_GAR
 INTO V_ALMACEN, V_NUMERO
 FROM fza_garantias_reclamaciones G
 WHERE G.ID_GAR=P_ID FOR UPDATE;
 IF COALESCE(V_ALMACEN, '')='' THEN
  SIGNAL SQLSTATE '45000'
   SET MESSAGE_TEXT='La orden necesita su almacén de origen.';
 END IF;
 SELECT A.CODIGO_EMP_ALM INTO V_EMPRESA
 FROM fza_almacenes A WHERE A.CODIGO_ALM_ALM=V_ALMACEN FOR UPDATE;
 IF COALESCE(V_EMPRESA, '')='' THEN
  SIGNAL SQLSTATE '45000'
   SET MESSAGE_TEXT='El almacén de la orden no pertenece a una empresa.';
 END IF;
 IF V_NUMERO IS NULL THEN
  SELECT COALESCE(MAX(COALESCE(G.NUMERO_ORDEN_GAR, G.ID_GAR)), 0)
  INTO V_MAXIMO FROM fza_garantias_reclamaciones G
  WHERE G.CODIGO_ALM_GAR=V_ALMACEN AND G.ID_GAR<>P_ID;
  INSERT INTO fza_contadores (
   TIPO_DOC_CON, EMPRESA_CON, SERIE_CON, CON, NUM_DIGITOS_CON,
   ESACTIVO_CON, DEFAULT_CON, INSTANTE_ALTA, USUARIO_ALTA, USUARIO_MODIF)
  VALUES ('OT', V_EMPRESA, V_ALMACEN, V_MAXIMO+1, 6,
   'S', 'N', NOW(), P_USUARIO, P_USUARIO)
  ON DUPLICATE KEY UPDATE CON=GREATEST(CON+1, VALUES(CON)),
   INSTANTE_MODIF=NOW(), USUARIO_MODIF=P_USUARIO;
  SELECT C.CON INTO V_NUMERO FROM fza_contadores C
  WHERE C.TIPO_DOC_CON='OT' AND C.EMPRESA_CON=V_EMPRESA
   AND C.SERIE_CON=V_ALMACEN FOR UPDATE;
  UPDATE fza_garantias_reclamaciones
  SET NUMERO_ORDEN_GAR=V_NUMERO WHERE ID_GAR=P_ID;
 END IF;
END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `PRC_FZA_REPOSICION_CABECERA` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_spanish_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_FZA_REPOSICION_CABECERA`(
  IN p_TIPO varchar(5), IN p_SERIE varchar(20), IN p_NUMERO varchar(20),
  IN p_TEMPORADA int, IN p_USUARIO varchar(50),
  OUT p_LOTE varchar(50), OUT p_EMPRESA varchar(10),
  OUT p_PROVEEDOR varchar(20), OUT p_TEMPORADA_LOTE int)
BEGIN
  DECLARE v_EsNueva varchar(1) DEFAULT 'N';
  SET p_LOTE = NULL;
  IF p_TIPO = 'AC' THEN
    SELECT A.LOTE_REPOSICION_ALBC, A.CODIGO_EMP_ALBC,
           A.CODIGO_PRV_ALBC, A.ID_PV_TEMPORADA_REPOSICION_ALBC,
           A.ESREPOSICION_AUTO_ALBC
      INTO p_LOTE, p_EMPRESA, p_PROVEEDOR, p_TEMPORADA_LOTE, v_EsNueva
      FROM fza_albaranes_compra A
     WHERE A.SERIE_ALBC = p_SERIE AND A.NUMERO_ALBC = p_NUMERO
     FOR UPDATE;
  ELSEIF p_TIPO = 'FP' THEN
    SELECT F.LOTE_REPOSICION_FACC, F.CODIGO_EMP_FACC,
           F.CODIGO_PRV_FACC, F.ID_PV_TEMPORADA_REPOSICION_FACC,
           IF(F.ESMUEVE_STOCK_FACC = 'S', F.ESREPOSICION_AUTO_FACC, 'N')
      INTO p_LOTE, p_EMPRESA, p_PROVEEDOR, p_TEMPORADA_LOTE, v_EsNueva
      FROM fza_facturas_compra F
     WHERE F.SERIE_FACC = p_SERIE AND F.NUMERO_FACC = p_NUMERO
     FOR UPDATE;
  END IF;
  IF v_EsNueva = 'S' AND EXISTS (SELECT 1 FROM fza_empresas E
      WHERE E.CODIGO_EMP_EMP = p_EMPRESA
        AND E.ESLOTES_REPOSICION_EMP = 'S') THEN
    IF COALESCE(p_PROVEEDOR, '') IN ('', '0') THEN
      SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Seleccione el proveedor de la reposicion';
    END IF;
    IF NULLIF(p_LOTE, '') IS NULL THEN
      IF p_TEMPORADA IS NULL THEN
        SIGNAL SQLSTATE '45000'
          SET MESSAGE_TEXT = 'Configure la temporada actual de reposicion';
      END IF;
      SET p_LOTE = CONCAT('R-', REPLACE(UUID(), '-', ''));
      SET p_TEMPORADA_LOTE = p_TEMPORADA;
      IF p_TIPO = 'AC' THEN
        UPDATE fza_albaranes_compra
           SET LOTE_REPOSICION_ALBC = p_LOTE,
               ID_PV_TEMPORADA_REPOSICION_ALBC = p_TEMPORADA,
               INSTANTE_MODIF = NOW(), USUARIO_MODIF = p_USUARIO
         WHERE SERIE_ALBC = p_SERIE AND NUMERO_ALBC = p_NUMERO;
      ELSEIF p_TIPO = 'FP' THEN
        UPDATE fza_facturas_compra
           SET LOTE_REPOSICION_FACC = p_LOTE,
               ID_PV_TEMPORADA_REPOSICION_FACC = p_TEMPORADA,
               INSTANTE_MODIF = NOW(), USUARIO_MODIF = p_USUARIO
         WHERE SERIE_FACC = p_SERIE AND NUMERO_FACC = p_NUMERO;
      END IF;
    END IF;
  ELSE
    SET p_LOTE = NULL;
  END IF;
END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `PRC_FZA_REPOSICION_PREPARAR` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_spanish_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_FZA_REPOSICION_PREPARAR`(
  IN p_TIPO varchar(5), IN p_SERIE varchar(20), IN p_NUMERO varchar(20),
  IN p_SKU varchar(50), IN p_TEMPORADA varchar(100),
  IN p_USUARIO varchar(50), OUT p_LOTE varchar(50))
BEGIN
  DECLARE v_Empresa varchar(10);
  DECLARE v_Proveedor varchar(20);
  DECLARE v_Temporada int;
  DECLARE v_TemporadaLote int;
  DECLARE v_Resultado varchar(30);
  SET p_LOTE = NULL;
  IF EXISTS (SELECT 1 FROM fza_articulos_skus K
      JOIN fza_articulos A ON A.CODIGO_ART_ART = K.CODIGO_ART_SKU
      WHERE K.CODIGO_UNIDAD_SKU = p_SKU
        AND COALESCE(A.TIPO_TRAZABILIDAD_ART, 'NINGUNA') = 'NINGUNA'
        AND A.TIPO_ART = 'ESTANDAR') THEN
    SELECT P.ID_PV_ARTPROP INTO v_Temporada
      FROM fza_propiedades_valores P
     WHERE P.ID_PROP_PV = 'TEMPORADA' AND P.ESACTIVO_PV = 'S'
       AND (P.PV = p_TEMPORADA OR
            CAST(P.ID_PV_ARTPROP AS CHAR) = p_TEMPORADA)
     ORDER BY P.PV = p_TEMPORADA DESC, P.ID_PV_ARTPROP LIMIT 1;
    CALL PRC_FZA_REPOSICION_CABECERA(p_TIPO, p_SERIE, p_NUMERO,
      v_Temporada, p_USUARIO, p_LOTE, v_Empresa, v_Proveedor,
      v_TemporadaLote);
    IF NULLIF(p_LOTE, '') IS NOT NULL THEN
      CALL PRC_FZA_LOTES_ASEGURAR(p_SKU, p_LOTE, 'L', NULL,
        CURDATE(), v_Proveedor, p_TIPO, p_SERIE, p_NUMERO,
        'N', p_USUARIO, v_Resultado);
      UPDATE fza_articulos_lotes
         SET ESREPOSICION_LOT = 'S', CODIGO_EMP_LOT = v_Empresa,
             ID_PV_TEMPORADA_LOT = v_TemporadaLote
       WHERE CODIGO_UNIDAD_LOT = p_SKU AND LOTE_LOT = p_LOTE;
    END IF;
  END IF;
END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `PRC_FZA_STOCK_ACUMULADOS_APLICAR` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_spanish_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_FZA_STOCK_ACUMULADOS_APLICAR`(IN p_SIGNO int)
BEGIN
  
  UPDATE fza_articulos_stockactual s
   INNER JOIN (
     SELECT m.CODIGO_ALM_MOV AS alm,
            m.CODIGO_UNIDAD_MOV AS uni,
            IFNULL(m.LOTE_MOV, '') AS lote,
            SUM(IF(m.TIPO_DOC_MOV IN ('AC', 'FP') AND m.TIPO_MOV = 'E',
                m.CANTIDAD_MOV, 0)) AS ent_compra,
            SUM(IF(m.TIPO_DOC_MOV IN ('TR', 'AT', 'TA') AND
                m.TIPO_MOV = 'E', m.CANTIDAD_MOV, 0)) AS ent_traspaso,
            SUM(IF(m.TIPO_DOC_MOV IN ('TR', 'AT', 'TA') AND
                m.TIPO_MOV = 'S', m.CANTIDAD_MOV, 0)) AS sal_traspaso,
            SUM(IF(m.TIPO_DOC_MOV = 'DP' AND m.TIPO_MOV = 'E',
                m.CANTIDAD_MOV, 0)) AS ent_deposito,
            SUM(IF(m.TIPO_DOC_MOV = 'DP' AND m.TIPO_MOV = 'S',
                m.CANTIDAD_MOV, 0)) AS sal_deposito,
            SUM(IF(m.TIPO_DOC_MOV IN ('VE', 'FC') AND m.TIPO_MOV = 'S',
                m.CANTIDAD_MOV, 0)) AS sal_venta,
            SUM(IF(m.TIPO_DOC_MOV = 'IN' AND m.TIPO_MOV = 'E',
                m.CANTIDAD_MOV, 0)) AS ent_regular,
            SUM(IF(m.TIPO_DOC_MOV = 'AV' AND m.TIPO_MOV = 'S',
                m.CANTIDAD_MOV, 0)) AS sal_albventa,
            SUM(IF(m.TIPO_DOC_MOV = 'AE' AND m.TIPO_MOV = 'E',
                m.CANTIDAD_MOV, 0)) AS ent_albentrada
       FROM tmp_stock_acumulados_mov t
       JOIN fza_movimientos_almacen m
         ON m.NUMERO_MOV = t.numero_mov
      WHERE m.ESACTIVO_MOV = 'S'
      GROUP BY m.CODIGO_ALM_MOV, m.CODIGO_UNIDAD_MOV, IFNULL(m.LOTE_MOV, '')
   ) d ON d.alm = s.CODIGO_ALM_STK
      AND d.uni = s.CODIGO_UNIDAD_STK
      AND d.lote = IFNULL(s.LOTE_STK, '')
  SET
    s.CANTIDAD_ENT_COMPRA_STK = GREATEST(
      s.CANTIDAD_ENT_COMPRA_STK + p_SIGNO * d.ent_compra, 0),
    s.CANTIDAD_ENT_TRASPASO_STK = GREATEST(
      s.CANTIDAD_ENT_TRASPASO_STK + p_SIGNO * d.ent_traspaso, 0),
    s.CANTIDAD_SAL_TRASPASO_STK = GREATEST(
      s.CANTIDAD_SAL_TRASPASO_STK + p_SIGNO * d.sal_traspaso, 0),
    s.CANTIDAD_ENT_DEPOSITO_STK = GREATEST(
      s.CANTIDAD_ENT_DEPOSITO_STK + p_SIGNO * d.ent_deposito, 0),
    s.CANTIDAD_SAL_DEPOSITO_STK = GREATEST(
      s.CANTIDAD_SAL_DEPOSITO_STK + p_SIGNO * d.sal_deposito, 0),
    s.CANTIDAD_SAL_VENTA_STK = GREATEST(
      s.CANTIDAD_SAL_VENTA_STK + p_SIGNO * d.sal_venta, 0),
    s.CANTIDAD_ENT_REGULAR_STK = GREATEST(
      s.CANTIDAD_ENT_REGULAR_STK + p_SIGNO * d.ent_regular, 0),
    s.CANTIDAD_SAL_ALBVENTA_STK = GREATEST(
      s.CANTIDAD_SAL_ALBVENTA_STK + p_SIGNO * d.sal_albventa, 0),
    s.CANTIDAD_ENT_ALBENTRADA_STK = GREATEST(
      s.CANTIDAD_ENT_ALBENTRADA_STK + p_SIGNO * d.ent_albentrada, 0),
    s.INSTANTE_MODIF = NOW();
END
;;
DELIMITER ;
