CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_FZA_STOCK_ACUMULADOS_PREPARAR`()
BEGIN
  DROP TEMPORARY TABLE IF EXISTS tmp_stock_acumulados_mov;
  CREATE TEMPORARY TABLE tmp_stock_acumulados_mov (
    numero_mov varchar(20) NOT NULL,
    PRIMARY KEY (numero_mov)
  ) ENGINE=InnoDB;
END
;;
