/*!50003 DROP PROCEDURE IF EXISTS `PRC_FZA_STOCK_LOTES_REPARTIR` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_spanish_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_FZA_STOCK_LOTES_REPARTIR`()
BEGIN
  
  
  
  
  DECLARE v_FIN int DEFAULT 0;
  DECLARE v_ALMACEN varchar(10);
  DECLARE v_SKU varchar(50);
  DECLARE v_STOCK decimal(19,6);
  DECLARE v_PMP decimal(19,6);
  DECLARE v_VALOR decimal(19,6);
  DECLARE v_CON_LOTES varchar(1);
  DECLARE cur_SKUS CURSOR FOR
    SELECT F.almacen, F.sku, F.stock_final, F.pmp_final, F.valor_final
      FROM tmp_recalculo_final F
     ORDER BY F.almacen, F.sku;
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_FIN = 1;
  OPEN cur_SKUS;
  bucle_SKUS: LOOP
    FETCH cur_SKUS INTO v_ALMACEN, v_SKU, v_STOCK, v_PMP, v_VALOR;
    IF v_FIN = 1 THEN
      LEAVE bucle_SKUS;
    END IF;
    CALL PRC_FZA_STOCK_LOTES_REPARTIR_SKU(
      v_ALMACEN, v_SKU, v_STOCK, v_CON_LOTES);
    IF v_CON_LOTES = 'S' THEN
      CALL PRC_FZA_STOCK_LOTES_VALORAR(
        v_ALMACEN, v_SKU, v_STOCK, v_VALOR, v_PMP);
    END IF;
  END LOOP;
  CLOSE cur_SKUS;
END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_VALUE_ON_ZERO' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `PRC_FZA_STOCK_LOTES_REPARTIR_SKU` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_spanish_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_FZA_STOCK_LOTES_REPARTIR_SKU`(
  IN p_ALMACEN varchar(10),
  IN p_SKU varchar(50),
  IN p_STOCK decimal(38,6),
  OUT p_CON_LOTES varchar(1)
)
cuerpo: BEGIN
  
  
  
  
  
  
  DECLARE v_LOTES decimal(38,6) DEFAULT 0;
  SET p_CON_LOTES = 'N';
  IF NOT EXISTS (
       SELECT 1
         FROM fza_articulos_stockactual S
        WHERE S.CODIGO_ALM_STK = p_ALMACEN
          AND S.CODIGO_UNIDAD_STK = p_SKU
          AND S.LOTE_STK <> '')
     AND NOT EXISTS (
       SELECT 1
         FROM fza_articulos_skus K
         JOIN fza_articulos A
           ON A.CODIGO_ART_ART = K.CODIGO_ART_SKU
        WHERE K.CODIGO_UNIDAD_SKU = p_SKU
          AND IFNULL(A.TIPO_TRAZABILIDAD_ART, 'NINGUNA') <> 'NINGUNA') THEN
    LEAVE cuerpo;
  END IF;
  INSERT INTO fza_articulos_stockactual (
    CODIGO_ALM_STK,
    CODIGO_UNIDAD_STK,
    LOTE_STK,
    FECHA_CADUCIDAD_STK,
    CANTIDAD_STK,
    VALOR_TOTAL_STK,
    PRECIO_MEDIO_STK,
    INSTANTE_MODIF
  )
  SELECT M.CODIGO_ALM_MOV,
         M.CODIGO_UNIDAD_MOV,
         M.LOTE_MOV,
         MAX(L.FECHA_CADUCIDAD_LOT),
         SUM(IF(M.TIPO_MOV = 'E', M.CANTIDAD_MOV, -M.CANTIDAD_MOV)),
         0,
         0,
         NOW()
    FROM fza_movimientos_almacen M
    LEFT JOIN fza_articulos_lotes L
      ON L.CODIGO_UNIDAD_LOT = M.CODIGO_UNIDAD_MOV
     AND L.LOTE_LOT = M.LOTE_MOV
   WHERE M.CODIGO_ALM_MOV = p_ALMACEN
     AND M.CODIGO_UNIDAD_MOV = p_SKU
     AND M.ESACTIVO_MOV = 'S'
     AND IFNULL(M.LOTE_MOV, '') <> ''
   GROUP BY M.CODIGO_ALM_MOV, M.CODIGO_UNIDAD_MOV, M.LOTE_MOV
  ON DUPLICATE KEY UPDATE
    CANTIDAD_STK = VALUES(CANTIDAD_STK),
    FECHA_CADUCIDAD_STK = COALESCE(VALUES(FECHA_CADUCIDAD_STK),
                                   FECHA_CADUCIDAD_STK);
  UPDATE fza_articulos_stockactual S
     SET S.CANTIDAD_STK = 0
   WHERE S.CODIGO_ALM_STK = p_ALMACEN
     AND S.CODIGO_UNIDAD_STK = p_SKU
     AND S.LOTE_STK <> ''
     AND IFNULL(S.CANTIDAD_STK, 0) <> 0
     AND NOT EXISTS (
       SELECT 1
         FROM fza_movimientos_almacen M
        WHERE M.CODIGO_ALM_MOV = p_ALMACEN
          AND M.CODIGO_UNIDAD_MOV = p_SKU
          AND M.ESACTIVO_MOV = 'S'
          AND M.LOTE_MOV = S.LOTE_STK);
  SELECT IFNULL(SUM(S.CANTIDAD_STK), 0)
    INTO v_LOTES
    FROM fza_articulos_stockactual S
   WHERE S.CODIGO_ALM_STK = p_ALMACEN
     AND S.CODIGO_UNIDAD_STK = p_SKU
     AND S.LOTE_STK <> '';
  IF v_LOTES = 0 AND NOT EXISTS (
       SELECT 1
         FROM fza_articulos_stockactual S
        WHERE S.CODIGO_ALM_STK = p_ALMACEN
          AND S.CODIGO_UNIDAD_STK = p_SKU
          AND S.LOTE_STK <> '') THEN
    
    LEAVE cuerpo;
  END IF;
  SET p_CON_LOTES = 'S';
  IF IFNULL(p_STOCK, 0) - v_LOTES <> 0 OR EXISTS (
       SELECT 1
         FROM fza_articulos_stockactual S
        WHERE S.CODIGO_ALM_STK = p_ALMACEN
          AND S.CODIGO_UNIDAD_STK = p_SKU
          AND S.LOTE_STK = '') THEN
    INSERT INTO fza_articulos_stockactual (
      CODIGO_ALM_STK,
      CODIGO_UNIDAD_STK,
      LOTE_STK,
      CANTIDAD_STK,
      VALOR_TOTAL_STK,
      PRECIO_MEDIO_STK,
      INSTANTE_MODIF
    ) VALUES (
      p_ALMACEN,
      p_SKU,
      '',
      IFNULL(p_STOCK, 0) - v_LOTES,
      0,
      0,
      NOW()
    )
    ON DUPLICATE KEY UPDATE
      CANTIDAD_STK = VALUES(CANTIDAD_STK);
  END IF;
  
  DELETE FROM fza_articulos_stockactual
   WHERE CODIGO_ALM_STK = p_ALMACEN
     AND CODIGO_UNIDAD_STK = p_SKU
     AND LOTE_STK = ''
     AND IFNULL(CANTIDAD_STK, 0) = 0
     AND IFNULL(CANTIDAD_PTE_RECIBIR_STK, 0) = 0
     AND IFNULL(CANTIDAD_PTE_SERVIR_STK, 0) = 0
     AND CANTIDAD_ENT_COMPRA_STK = 0
     AND CANTIDAD_ENT_TRASPASO_STK = 0
     AND CANTIDAD_SAL_TRASPASO_STK = 0
     AND CANTIDAD_ENT_DEPOSITO_STK = 0
     AND CANTIDAD_SAL_DEPOSITO_STK = 0
     AND CANTIDAD_SAL_VENTA_STK = 0
     AND CANTIDAD_ENT_REGULAR_STK = 0
     AND CANTIDAD_SAL_ALBVENTA_STK = 0
     AND CANTIDAD_ENT_ALBENTRADA_STK = 0;
END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_VALUE_ON_ZERO' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `PRC_FZA_STOCK_LOTES_VALORAR` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_spanish_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_FZA_STOCK_LOTES_VALORAR`(
  IN p_ALMACEN varchar(10),
  IN p_SKU varchar(50),
  IN p_STOCK decimal(19,6),
  IN p_VALOR decimal(19,6),
  IN p_PMP decimal(19,6)
)
BEGIN
  
  
  
  
  DECLARE v_POSITIVOS decimal(38,6) DEFAULT 0;
  DECLARE v_REPARTIDO decimal(38,6) DEFAULT 0;
  DECLARE v_LOTE_MAYOR varchar(50) DEFAULT NULL;
  DECLARE v_VALOR decimal(19,6) DEFAULT 0;
  SET v_VALOR = IF(IFNULL(p_STOCK, 0) > 0, IFNULL(p_VALOR, 0), 0);
  SELECT IFNULL(SUM(GREATEST(IFNULL(S.CANTIDAD_STK, 0), 0)), 0)
    INTO v_POSITIVOS
    FROM fza_articulos_stockactual S
   WHERE S.CODIGO_ALM_STK = p_ALMACEN
     AND S.CODIGO_UNIDAD_STK = p_SKU;
  UPDATE fza_articulos_stockactual S
     SET S.PRECIO_MEDIO_STK = p_PMP,
         S.VALOR_TOTAL_STK = IF(v_VALOR <> 0 AND v_POSITIVOS > 0 AND
                                IFNULL(S.CANTIDAD_STK, 0) > 0,
                                ROUND(v_VALOR * S.CANTIDAD_STK /
                                      v_POSITIVOS, 6), 0)
   WHERE S.CODIGO_ALM_STK = p_ALMACEN
     AND S.CODIGO_UNIDAD_STK = p_SKU;
  IF v_VALOR <> 0 AND v_POSITIVOS > 0 THEN
    SELECT IFNULL(SUM(S.VALOR_TOTAL_STK), 0)
      INTO v_REPARTIDO
      FROM fza_articulos_stockactual S
     WHERE S.CODIGO_ALM_STK = p_ALMACEN
       AND S.CODIGO_UNIDAD_STK = p_SKU;
    IF v_REPARTIDO <> v_VALOR THEN
      SELECT S.LOTE_STK
        INTO v_LOTE_MAYOR
        FROM fza_articulos_stockactual S
       WHERE S.CODIGO_ALM_STK = p_ALMACEN
         AND S.CODIGO_UNIDAD_STK = p_SKU
       ORDER BY S.CANTIDAD_STK DESC, S.LOTE_STK
       LIMIT 1;
      UPDATE fza_articulos_stockactual S
         SET S.VALOR_TOTAL_STK = S.VALOR_TOTAL_STK +
                                 (v_VALOR - v_REPARTIDO)
       WHERE S.CODIGO_ALM_STK = p_ALMACEN
         AND S.CODIGO_UNIDAD_STK = p_SKU
         AND S.LOTE_STK = v_LOTE_MAYOR;
    END IF;
  END IF;
END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_VALUE_ON_ZERO' */ ;
