/*!50003 DROP PROCEDURE IF EXISTS `PRC_GETPERFILFORMULARIO` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_spanish_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_GETPERFILFORMULARIO`(IN `p_usuario` VARCHAR(200),
    IN `p_grupo` VARCHAR(200),
    IN `p_formulario` VARCHAR(100))
BEGIN
    
    WITH perfiles_con_prioridad AS (
        SELECT 
            USUARIO_GRUPO_USUPER,
            KEY_USUPER,
            SUBKEY_USUPER,
            VALUE_USUPER,
            VALUE_TEXT_USUPER,
            TYPE_BLOB_USUPER,
            VALUE_BLOB_USUPER,
            CASE USUARIO_GRUPO_USUPER
                WHEN p_usuario THEN 1
                WHEN p_grupo   THEN 2
                WHEN 'Todos'   THEN 3
            END AS prioridad,
            ROW_NUMBER() OVER (
                PARTITION BY SUBKEY_USUPER 
                ORDER BY CASE USUARIO_GRUPO_USUPER
                    WHEN p_usuario THEN 1
                    WHEN p_grupo   THEN 2
                    WHEN 'Todos'   THEN 3
                END
            ) AS rn
        FROM fza_usuarios_perfiles
        WHERE KEY_USUPER = p_formulario 
          AND USUARIO_GRUPO_USUPER IN (p_usuario, p_grupo, 'Todos')
    )
    SELECT 
        USUARIO_GRUPO_USUPER,
        KEY_USUPER,
        SUBKEY_USUPER,
        VALUE_USUPER,
        VALUE_TEXT_USUPER,
        TYPE_BLOB_USUPER,
        VALUE_BLOB_USUPER
    FROM perfiles_con_prioridad
    WHERE rn = 1
    ORDER BY SUBKEY_USUPER;
END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `PRC_GET_BALANCE_ALMACEN_SIN_TALLAS` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_spanish_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_GET_BALANCE_ALMACEN_SIN_TALLAS`(
  IN p_MODO varchar(1),
  IN p_DESDE date,
  IN p_HASTA date,
  IN p_ALMACENES text,
  IN p_FAMILIAS text,
  IN p_PROVEEDORES text,
  IN p_TEMPORADAS text,
  IN p_ARTICULOS text,
  IN p_COD_TARIFA varchar(20),
  IN p_DESGLOSADO varchar(1),
  IN p_BANDAS text,
  IN p_NIVEL1 varchar(3),
  IN p_NIVEL2 varchar(3),
  IN p_NIVEL3 varchar(3),
  IN p_NIVEL_FAM int(11)
)
BEGIN
    DECLARE v_alms      TEXT;
    DECLARE v_tarifa    VARCHAR(20);
    DECLARE v_desde     DATE;
    DECLARE v_hasta     DATE;
    DECLARE v_por_alm   BOOLEAN DEFAULT FALSE;
    
    DECLARE v_por_prv    BOOLEAN DEFAULT FALSE;


    DECLARE v_desglosado BOOLEAN DEFAULT FALSE;
    DECLARE v_nivel_fam INT;

    SET p_MODO       = IFNULL(NULLIF(p_MODO, ''), 'A');
    SET p_DESGLOSADO  = IFNULL(NULLIF(p_DESGLOSADO, ''), 'N');
    SET v_desglosado  = (p_MODO = 'F' AND p_DESGLOSADO = 'S');
    SET p_FAMILIAS    = IFNULL(p_FAMILIAS, '');
    SET p_PROVEEDORES = IFNULL(p_PROVEEDORES, '');
    SET p_TEMPORADAS  = IFNULL(p_TEMPORADAS, '');
    SET p_ARTICULOS   = IFNULL(p_ARTICULOS, '');
    SET p_BANDAS      = IFNULL(p_BANDAS, '');



    SET p_NIVEL1      = UPPER(IFNULL(p_NIVEL1, ''));
    SET p_NIVEL2      = UPPER(IFNULL(p_NIVEL2, ''));
    SET p_NIVEL3      = UPPER(IFNULL(p_NIVEL3, ''));
    SET v_por_alm     = (p_NIVEL1 = 'ALM' OR p_NIVEL2 = 'ALM' OR p_NIVEL3 = 'ALM');
    SET v_por_prv     = (p_NIVEL1 = 'PRV' OR p_NIVEL2 = 'PRV' OR p_NIVEL3 = 'PRV');
    SET v_nivel_fam   = IF(IFNULL(p_NIVEL_FAM, 0) < 1, 9999, p_NIVEL_FAM);
    SET v_tarifa      = IFNULL(NULLIF(p_COD_TARIFA, ''), 'PVP');
    SET v_desde      = IFNULL(p_DESDE, '1900-01-01');
    SET v_hasta      = IFNULL(p_HASTA, CURRENT_DATE);


    IF p_MODO = 'A' THEN
        SET v_desde = '1000-01-01';
        SET v_hasta = '9999-12-31';
    END IF;




    DROP TEMPORARY TABLE IF EXISTS `tmp_bst_alm`;
    CREATE TEMPORARY TABLE `tmp_bst_alm` (
        `CODIGO_ALM` VARCHAR(20) NOT NULL PRIMARY KEY
    );
    INSERT IGNORE INTO `tmp_bst_alm` (`CODIGO_ALM`)
    SELECT `CODIGO_ALM_ALM` FROM `fza_almacenes`
     WHERE IF(IFNULL(p_ALMACENES, '') = '',
              `ESACTIVO_ALM` = 'S',
              FIND_IN_SET(`CODIGO_ALM_ALM`, p_ALMACENES));






    DROP TEMPORARY TABLE IF EXISTS `tmp_bst_fam`;
    CREATE TEMPORARY TABLE `tmp_bst_fam` (
        `CODIGO_FAM` VARCHAR(20) NOT NULL PRIMARY KEY
    );
    INSERT IGNORE INTO `tmp_bst_fam` (`CODIGO_FAM`)
    WITH RECURSIVE `fam_tree` AS (
        SELECT `CODIGO_FAM_FAM`
          FROM `fza_articulos_familias`
         WHERE FIND_IN_SET(`CODIGO_FAM_FAM`, p_FAMILIAS)
        UNION ALL
        SELECT f.`CODIGO_FAM_FAM`
          FROM `fza_articulos_familias` f
          JOIN `fam_tree` t ON f.`CODIGO_PADRE_FAM` = t.`CODIGO_FAM_FAM`
    )
    SELECT DISTINCT `CODIGO_FAM_FAM` FROM `fam_tree`;


    DROP TEMPORARY TABLE IF EXISTS `tmp_bst_fam_grp`;
    CREATE TEMPORARY TABLE `tmp_bst_fam_grp` (
        `CODIGO_FAM` VARCHAR(20)  NOT NULL PRIMARY KEY,
        `COD_GRP`    VARCHAR(20)  NOT NULL,
        `DESC_GRP`   VARCHAR(200) NULL
    );
    INSERT IGNORE INTO `tmp_bst_fam_grp` (`CODIGO_FAM`, `COD_GRP`, `DESC_GRP`)
    WITH RECURSIVE `fam_path` AS (
        SELECT `CODIGO_FAM_FAM` AS `COD`,
               CAST(`CODIGO_FAM_FAM` AS CHAR(1000)) AS `RUTA`
          FROM `fza_articulos_familias`
         WHERE `CODIGO_PADRE_FAM` IS NULL OR `CODIGO_PADRE_FAM` = ''
        UNION ALL
        SELECT f.`CODIGO_FAM_FAM`,
               CONCAT(pa.`RUTA`, '>', f.`CODIGO_FAM_FAM`)
          FROM `fza_articulos_familias` f
          JOIN `fam_path` pa ON f.`CODIGO_PADRE_FAM` = pa.`COD`
    )
    SELECT pa.`COD`,
           SUBSTRING_INDEX(SUBSTRING_INDEX(pa.`RUTA`, '>', v_nivel_fam), '>', -1),
           NULL
      FROM `fam_path` pa;
    UPDATE `tmp_bst_fam_grp` g
      JOIN `fza_articulos_familias` f ON f.`CODIGO_FAM_FAM` = g.`COD_GRP`
       SET g.`DESC_GRP` = COALESCE(f.`DESCRIPCION_FAM`, f.`NOMBRE_FAM_FAM`,
                                   g.`COD_GRP`);



    DROP TEMPORARY TABLE IF EXISTS `tmp_bst_arts`;
    CREATE TEMPORARY TABLE `tmp_bst_arts` (
        `CODIGO_ART` VARCHAR(20) NOT NULL PRIMARY KEY
    );
    INSERT IGNORE INTO `tmp_bst_arts` (`CODIGO_ART`)
    SELECT a.`CODIGO_ART_ART`
      FROM `fza_articulos` a
     WHERE (p_ARTICULOS = ''
            OR FIND_IN_SET(a.`CODIGO_ART_ART`, p_ARTICULOS))
       AND (p_FAMILIAS = ''
            OR a.`CODIGO_FAM_ART` IN (SELECT `CODIGO_FAM` FROM `tmp_bst_fam`))
       AND (p_PROVEEDORES = ''
            OR EXISTS (SELECT 1 FROM `fza_articulos_proveedores` ap
                        WHERE ap.`CODIGO_ART_AP` = a.`CODIGO_ART_ART`
                          AND FIND_IN_SET(ap.`CODIGO_PRV_AP`, p_PROVEEDORES)) OR EXISTS (SELECT 1 FROM fza_articulos_lotes LFA JOIN fza_articulos_skus SFA ON SFA.CODIGO_UNIDAD_SKU = LFA.CODIGO_UNIDAD_LOT WHERE SFA.CODIGO_ART_SKU = a.CODIGO_ART_ART AND FIND_IN_SET(LFA.CODIGO_PRV_LOT, p_PROVEEDORES) > 0))
       AND (p_TEMPORADAS = ''
            OR EXISTS (SELECT 1 FROM `fza_articulos_propiedades` tp
                        LEFT JOIN `fza_propiedades_valores` tpv
                          ON tpv.`ID_PV_ARTPROP` = tp.`ID_PV_ARTPROP`
                        WHERE tp.`CODIGO_ART_ART` = a.`CODIGO_ART_ART`
                          AND tp.`CODIGO_PROP_ARTPROP` = 'TEMPORADA'
                          AND FIND_IN_SET(
                                COALESCE(tpv.`PV`, tp.`VALOR_LIBRE_ARTPROP`),
                                p_TEMPORADAS)));






    DROP TEMPORARY TABLE IF EXISTS `tmp_bst_sku`;
    CREATE TEMPORARY TABLE `tmp_bst_sku` (
        `CODIGO_UNIDAD` VARCHAR(50)  NOT NULL PRIMARY KEY,
        `CODIGO_ART`    VARCHAR(20)  NOT NULL,
        `COLOR`         VARCHAR(100) NOT NULL DEFAULT '',
        `COLOR_HEX`     VARCHAR(7)   NULL,
        `ORDEN_COLOR`   INT          NOT NULL DEFAULT 0,
        KEY `IDX_BST_SKU_ART` (`CODIGO_ART`)
    );
    INSERT IGNORE INTO `tmp_bst_sku`
    SELECT sku.`CODIGO_UNIDAD_SKU`, sku.`CODIGO_ART_SKU`,
           COALESCE(co.`AV`, ''), COALESCE(atb.`HEX_ATB`, ''),
           COALESCE(co.`ORDEN_AV`, 0)
      FROM `fza_articulos_skus` sku
      JOIN `fza_articulos` a
        ON a.`CODIGO_ART_ART` = sku.`CODIGO_ART_SKU`
       AND a.`CODIGO_ART_ART` IN (SELECT `CODIGO_ART` FROM `tmp_bst_arts`)





      LEFT JOIN `fza_atributos_sku` sac
        ON sac.`CODIGO_UNIDAD_SKU_SA` = sku.`CODIGO_UNIDAD_SKU`
       AND sac.`ID_AV_SA` IN (SELECT `ID_AV` FROM `fza_atributos_valores`
                               WHERE `ID_VA_AV` = (SELECT EJ452.ID_ATB_VA FROM VI_VARIACIONES_EJES EJ452 WHERE EJ452.ID_VAR_VA = (SELECT SK452.CODIGO_VAR_SKU FROM fza_articulos_skus SK452 WHERE SK452.CODIGO_UNIDAD_SKU = sac.CODIGO_UNIDAD_SKU_SA) AND EJ452.EJE_VA = 'F'))
      LEFT JOIN `fza_atributos_valores` co
        ON co.`ID_AV` = sac.`ID_AV_SA` AND co.`ID_VA_AV` = (SELECT EJ452.ID_ATB_VA FROM VI_VARIACIONES_EJES EJ452 WHERE EJ452.ID_VAR_VA = (SELECT SK452.CODIGO_VAR_SKU FROM fza_articulos_skus SK452 WHERE SK452.CODIGO_UNIDAD_SKU = sac.CODIGO_UNIDAD_SKU_SA) AND EJ452.EJE_VA = 'F')
      LEFT JOIN `fza_atributos_basicos` atb ON atb.`ID_ATB` = co.`ID_ATB_AV`;









    DROP TEMPORARY TABLE IF EXISTS `tmp_bst_base`;
    CREATE TEMPORARY TABLE `tmp_bst_base` (
        `CODIGO_ART`     VARCHAR(20)  NOT NULL,
        `CODIGO_ALM`     VARCHAR(50)  NOT NULL DEFAULT '',
        `COLOR`          VARCHAR(100) NOT NULL DEFAULT '',
        `COLOR_HEX`      VARCHAR(7)   NULL,
        `ORDEN_COLOR`    INT          NOT NULL DEFAULT 0,
        `EXI_INI`        DECIMAL(19,6) NOT NULL DEFAULT 0,
        `EXI_FIN`        DECIMAL(19,6) NOT NULL DEFAULT 0,

        `ENT_COMPRA`     DECIMAL(19,6) NOT NULL DEFAULT 0,
        `ENT_ALBENTRADA` DECIMAL(19,6) NOT NULL DEFAULT 0,
        `ENT_TRASPASO`   DECIMAL(19,6) NOT NULL DEFAULT 0,
        `ENT_DEPOSITO`   DECIMAL(19,6) NOT NULL DEFAULT 0,
        `ENT_REGULAR`    DECIMAL(19,6) NOT NULL DEFAULT 0,
        `ENT_DEVPRV`     DECIMAL(19,6) NOT NULL DEFAULT 0,
        `ENT_OTROS`      DECIMAL(19,6) NOT NULL DEFAULT 0,

        `SAL_ALBVENTA`   DECIMAL(19,6) NOT NULL DEFAULT 0,
        `SAL_VENTA`      DECIMAL(19,6) NOT NULL DEFAULT 0,

        `VEN_FAC`        DECIMAL(19,6) NOT NULL DEFAULT 0,


        `NUM_MOVS`       INT           NOT NULL DEFAULT 0,
        PRIMARY KEY (`CODIGO_ART`, `CODIGO_ALM`, `COLOR`)
    );
    INSERT INTO `tmp_bst_base`
        (`CODIGO_ART`, `CODIGO_ALM`, `COLOR`, `COLOR_HEX`, `ORDEN_COLOR`,
         `EXI_INI`, `EXI_FIN`,
         `ENT_COMPRA`, `ENT_ALBENTRADA`, `ENT_TRASPASO`, `ENT_DEPOSITO`,
         `ENT_REGULAR`, `ENT_DEVPRV`, `ENT_OTROS`,
         `SAL_ALBVENTA`, `SAL_VENTA`, `NUM_MOVS`)
    SELECT s.`CODIGO_ART`, COALESCE(mv.`ALM`, ''),
           s.`COLOR`, MIN(s.`COLOR_HEX`),
           MIN(s.`ORDEN_COLOR`),



           SUM(COALESCE(mv.`STOCK_NOW`, 0) - COALESCE(mv.`DELTA_DESDE`, 0)),


           SUM(COALESCE(mv.`STOCK_NOW`, 0) - COALESCE(mv.`DELTA_HASTA`, 0)),
           SUM(COALESCE(mv.`ENT_COMPRA`, 0)), SUM(COALESCE(mv.`ENT_ALBENTRADA`, 0)),
           SUM(COALESCE(mv.`ENT_TRASPASO`, 0)), SUM(COALESCE(mv.`ENT_DEPOSITO`, 0)),
           SUM(COALESCE(mv.`ENT_REGULAR`, 0)), SUM(COALESCE(mv.`ENT_DEVPRV`, 0)),
           SUM(COALESCE(mv.`ENT_OTROS`, 0)),
           SUM(COALESCE(mv.`SAL_ALBVENTA`, 0)), SUM(COALESCE(mv.`SAL_VENTA`, 0)),
           SUM(COALESCE(mv.`NUM_MOVS`, 0))
      FROM `tmp_bst_sku` s
      LEFT JOIN (



            SELECT u.`CODIGO_UNIDAD`, u.`ALM`,
                   SUM(u.`STOCK_NOW`)                       AS `STOCK_NOW`,
                   SUM(IF(u.`EN_PERIODO` AND u.`TIPO` IN ('AC', 'AB', 'FP'),
                          u.`NETO`, 0))                     AS `ENT_COMPRA`,
                   SUM(IF(u.`EN_PERIODO` AND u.`TIPO` = 'AE',
                          u.`NETO`, 0))                     AS `ENT_ALBENTRADA`,
                   SUM(IF(u.`EN_PERIODO` AND u.`TIPO` IN ('TR', 'AT', 'TA'),
                          u.`NETO`, 0))                     AS `ENT_TRASPASO`,
                   SUM(IF(u.`EN_PERIODO` AND u.`TIPO` = 'DP',
                          u.`NETO`, 0))                     AS `ENT_DEPOSITO`,
                   SUM(IF(u.`EN_PERIODO` AND u.`TIPO` = 'IN',
                          u.`NETO`, 0))                     AS `ENT_REGULAR`,
                   SUM(IF(u.`EN_PERIODO` AND u.`TIPO` = 'DC',
                          u.`NETO`, 0))                     AS `ENT_DEVPRV`,
                   SUM(IF(u.`EN_PERIODO` AND u.`TIPO` NOT IN
                          ('AC', 'AB', 'FP', 'AE', 'TR', 'AT', 'TA', 'DP', 'IN',
                           'DC', 'AV', 'VE', 'FC'),
                          u.`NETO`, 0))                     AS `ENT_OTROS`,
                   SUM(IF(u.`EN_PERIODO` AND u.`TIPO` = 'AV',
                          -u.`NETO`, 0))                    AS `SAL_ALBVENTA`,
                   SUM(IF(u.`EN_PERIODO` AND u.`TIPO` IN ('VE', 'FC'),
                          -u.`NETO`, 0))                    AS `SAL_VENTA`,
                   SUM(IF(u.`FECHA` >= v_desde, u.`NETO`, 0)) AS `DELTA_DESDE`,
                   SUM(IF(u.`FECHA` > v_hasta, u.`NETO`, 0))  AS `DELTA_HASTA`,
                   SUM(u.`EN_PERIODO`)                      AS `NUM_MOVS`
              FROM (
                    SELECT st2.`CODIGO_UNIDAD_STK` AS `CODIGO_UNIDAD`,
                           CONCAT(IF(v_por_alm, st2.`CODIGO_ALM_STK`, ''), IF(v_por_prv, CONCAT(CHAR(31 USING utf8mb4), COALESCE((SELECT NULLIF(NULLIF(TRIM(LG.CODIGO_PRV_LOT), ''), '0') FROM fza_articulos_lotes LG WHERE LG.CODIGO_UNIDAD_LOT = st2.CODIGO_UNIDAD_STK AND LG.LOTE_LOT = st2.LOTE_STK LIMIT 1), IF(p_PROVEEDORES = '', (SELECT MAX(AG.CODIGO_PRV_AP) FROM fza_articulos_proveedores AG WHERE AG.CODIGO_ART_AP = (SELECT SG.CODIGO_ART_SKU FROM fza_articulos_skus SG WHERE SG.CODIGO_UNIDAD_SKU = st2.CODIGO_UNIDAD_STK) AND AG.ESPROVEEDORPRINCIPAL_AP = 'S'), (SELECT AG.CODIGO_PRV_AP FROM fza_articulos_proveedores AG WHERE AG.CODIGO_ART_AP = (SELECT SG.CODIGO_ART_SKU FROM fza_articulos_skus SG WHERE SG.CODIGO_UNIDAD_SKU = st2.CODIGO_UNIDAD_STK) AND FIND_IN_SET(AG.CODIGO_PRV_AP, p_PROVEEDORES) > 0 ORDER BY AG.ESPROVEEDORPRINCIPAL_AP = 'S' DESC, AG.CODIGO_PRV_AP LIMIT 1)), '')), '')) AS `ALM`,
                           st2.`CANTIDAD_STK` AS `STOCK_NOW`,
                           '' AS `TIPO`, NULL AS `FECHA`,
                           FALSE AS `EN_PERIODO`, 0 AS `NETO`
                      FROM `fza_articulos_stockactual` st2
                     WHERE
       (p_PROVEEDORES = '' OR EXISTS (
         SELECT 1 FROM fza_articulos_lotes LP
          WHERE LP.CODIGO_UNIDAD_LOT = st2.CODIGO_UNIDAD_STK
            AND LP.LOTE_LOT = st2.LOTE_STK
            AND COALESCE(TRIM(LP.CODIGO_PRV_LOT), '') NOT IN ('', '0')
            AND FIND_IN_SET(LP.CODIGO_PRV_LOT, p_PROVEEDORES) > 0)
        OR (NOT EXISTS (
         SELECT 1 FROM fza_articulos_lotes LP
          WHERE LP.CODIGO_UNIDAD_LOT = st2.CODIGO_UNIDAD_STK
            AND LP.LOTE_LOT = st2.LOTE_STK
            AND COALESCE(TRIM(LP.CODIGO_PRV_LOT), '') NOT IN ('', '0')) AND EXISTS (
         SELECT 1 FROM fza_articulos_proveedores APF
          WHERE APF.CODIGO_ART_AP = (SELECT SF.CODIGO_ART_SKU FROM fza_articulos_skus SF WHERE SF.CODIGO_UNIDAD_SKU = st2.CODIGO_UNIDAD_STK)
            AND FIND_IN_SET(APF.CODIGO_PRV_AP, p_PROVEEDORES) > 0))) AND st2.`CODIGO_ALM_STK` IN (SELECT `CODIGO_ALM` FROM `tmp_bst_alm`)


                       AND st2.`CODIGO_UNIDAD_STK` IN
                           (SELECT `CODIGO_UNIDAD` FROM `tmp_bst_sku`)
                    UNION ALL
                    SELECT m.`CODIGO_UNIDAD_MOV`,
                           CONCAT(IF(v_por_alm, m.`CODIGO_ALM_MOV`, ''), IF(v_por_prv, CONCAT(CHAR(31 USING utf8mb4), COALESCE((SELECT NULLIF(NULLIF(TRIM(LG.CODIGO_PRV_LOT), ''), '0') FROM fza_articulos_lotes LG WHERE LG.CODIGO_UNIDAD_LOT = m.CODIGO_UNIDAD_MOV AND LG.LOTE_LOT = m.LOTE_MOV LIMIT 1), IF(p_PROVEEDORES = '', (SELECT MAX(AG.CODIGO_PRV_AP) FROM fza_articulos_proveedores AG WHERE AG.CODIGO_ART_AP = m.CODIGO_ART_MOV AND AG.ESPROVEEDORPRINCIPAL_AP = 'S'), (SELECT AG.CODIGO_PRV_AP FROM fza_articulos_proveedores AG WHERE AG.CODIGO_ART_AP = m.CODIGO_ART_MOV AND FIND_IN_SET(AG.CODIGO_PRV_AP, p_PROVEEDORES) > 0 ORDER BY AG.ESPROVEEDORPRINCIPAL_AP = 'S' DESC, AG.CODIGO_PRV_AP LIMIT 1)), '')), '')),
                           0,
                           CASE

                             WHEN UPPER(IFNULL(m.TIPO_DOC_MOV, ''))
                                  IN ('TR', 'AT', 'TA') AND EXISTS (
                               SELECT 1 FROM fza_almacenes DA
                                WHERE DA.CODIGO_ALM_ALM IN
                                  (m.CODIGO_ALM_MOV, m.CODIGO_ALM_CONTRA_MOV)
                                  AND UPPER(TRIM(DA.TIPO_USO_ALM)) IN
                                    ('DEPOSITO', 'DEPÓSITO')) THEN 'DP'
                             ELSE UPPER(IFNULL(m.TIPO_DOC_MOV, ''))
                           END,
                           DATE(m.`FECHA_MOV`),
                           DATE(m.`FECHA_MOV`) BETWEEN v_desde AND v_hasta,

                           IF(m.`TIPO_MOV` = 'E', m.`CANTIDAD_MOV`,
                              -m.`CANTIDAD_MOV`)
                      FROM `fza_movimientos_almacen` m
                     WHERE
       (p_PROVEEDORES = '' OR EXISTS (
         SELECT 1 FROM fza_articulos_lotes LP
          WHERE LP.CODIGO_UNIDAD_LOT = m.CODIGO_UNIDAD_MOV
            AND LP.LOTE_LOT = m.LOTE_MOV
            AND COALESCE(TRIM(LP.CODIGO_PRV_LOT), '') NOT IN ('', '0')
            AND FIND_IN_SET(LP.CODIGO_PRV_LOT, p_PROVEEDORES) > 0)
        OR (NOT EXISTS (
         SELECT 1 FROM fza_articulos_lotes LP
          WHERE LP.CODIGO_UNIDAD_LOT = m.CODIGO_UNIDAD_MOV
            AND LP.LOTE_LOT = m.LOTE_MOV
            AND COALESCE(TRIM(LP.CODIGO_PRV_LOT), '') NOT IN ('', '0')) AND EXISTS (
         SELECT 1 FROM fza_articulos_proveedores APF
          WHERE APF.CODIGO_ART_AP = m.CODIGO_ART_MOV
            AND FIND_IN_SET(APF.CODIGO_PRV_AP, p_PROVEEDORES) > 0))) AND m.`ESACTIVO_MOV` = 'S'
                       AND m.`CODIGO_ALM_MOV` IN (SELECT `CODIGO_ALM` FROM `tmp_bst_alm`)


                       AND m.`CODIGO_UNIDAD_MOV` IN
                           (SELECT `CODIGO_UNIDAD` FROM `tmp_bst_sku`)

                       AND m.`FECHA_MOV` >= v_desde
                   ) u
             GROUP BY u.`CODIGO_UNIDAD`, u.`ALM`
           ) mv ON mv.`CODIGO_UNIDAD` = s.`CODIGO_UNIDAD`
     GROUP BY s.`CODIGO_ART`, COALESCE(mv.`ALM`, ''), s.`COLOR`;












    DROP TEMPORARY TABLE IF EXISTS tmp_bst_alm_factura;
    CREATE TEMPORARY TABLE tmp_bst_alm_factura AS
    SELECT FL.SERIE_FAC_FACLIN AS SERIE_FAC,
           FL.NUMERO_FAC_FACLIN AS NUMERO_FAC,
           FL.LINEA_FACLIN AS LINEA_FAC,
           MIN(COALESCE(NULLIF(OL.CODIGO_ALM_FACLIN, ''),
                        NULLIF(OFAC.CODIGO_ALM_FAC, ''))) AS CODIGO_ALM
      FROM fza_facturas F
      JOIN fza_facturas_lineas FL
        ON FL.SERIE_FAC_FACLIN = F.SERIE_FAC
       AND FL.NUMERO_FAC_FACLIN = F.NUMERO_FAC
      JOIN fza_facturas_relaciones R
        ON R.SERIE_FAC_FACREL = F.SERIE_FAC
       AND R.NUMERO_FAC_FACREL = F.NUMERO_FAC
       AND R.TIPO_RELACION_FACREL = 'SUSTITUYE'
      JOIN fza_facturas OFAC
        ON OFAC.SERIE_FAC = R.SERIE_FAC_ORIGEN_FACREL
       AND OFAC.NUMERO_FAC = R.NUMERO_FAC_ORIGEN_FACREL
       AND OFAC.CODIGO_EMP_FAC = F.CODIGO_EMP_FAC
      LEFT JOIN fza_facturas_lineas OL
        ON OL.SERIE_FAC_FACLIN = OFAC.SERIE_FAC
       AND OL.NUMERO_FAC_FACLIN = OFAC.NUMERO_FAC
       AND OL.CODIGO_UNIDAD_FACLIN = FL.CODIGO_UNIDAD_FACLIN
     WHERE F.FECHA_FAC >= v_desde AND DATE(F.FECHA_FAC) <= v_hasta
       AND NULLIF(FL.CODIGO_ALM_FACLIN, '') IS NULL
       AND NULLIF(F.CODIGO_ALM_FAC, '') IS NULL
     GROUP BY FL.SERIE_FAC_FACLIN, FL.NUMERO_FAC_FACLIN, FL.LINEA_FACLIN;
    ALTER TABLE tmp_bst_alm_factura
      ADD PRIMARY KEY (SERIE_FAC, NUMERO_FAC, LINEA_FAC);
    DROP TEMPORARY TABLE IF EXISTS `tmp_bst_ven`;
    CREATE TEMPORARY TABLE `tmp_bst_ven` (
        `CODIGO_ART` VARCHAR(20)   NOT NULL,
        `CODIGO_ALM` VARCHAR(50)   NOT NULL DEFAULT '',
        `COLOR`      VARCHAR(100)  NOT NULL DEFAULT '',
        `VEN_QTY`    DECIMAL(19,6) NOT NULL DEFAULT 0,
        PRIMARY KEY (`CODIGO_ART`, `CODIGO_ALM`, `COLOR`)
    );
    INSERT INTO `tmp_bst_ven`
    SELECT s.`CODIGO_ART`,
           CONCAT(IF(v_por_alm, COALESCE(NULLIF(fl.CODIGO_ALM_FACLIN, ''), NULLIF(f.CODIGO_ALM_FAC, ''), AFS.CODIGO_ALM), ''), IF(v_por_prv, CONCAT(CHAR(31 USING utf8mb4), COALESCE((SELECT NULLIF(NULLIF(TRIM(LG.CODIGO_PRV_LOT), ''), '0') FROM fza_articulos_lotes LG WHERE LG.CODIGO_UNIDAD_LOT = fl.CODIGO_UNIDAD_FACLIN AND LG.LOTE_LOT = fl.LOTE_FACLIN LIMIT 1), IF(p_PROVEEDORES = '', (SELECT MAX(AG.CODIGO_PRV_AP) FROM fza_articulos_proveedores AG WHERE AG.CODIGO_ART_AP = fl.CODIGO_ART_FACLIN AND AG.ESPROVEEDORPRINCIPAL_AP = 'S'), (SELECT AG.CODIGO_PRV_AP FROM fza_articulos_proveedores AG WHERE AG.CODIGO_ART_AP = fl.CODIGO_ART_FACLIN AND FIND_IN_SET(AG.CODIGO_PRV_AP, p_PROVEEDORES) > 0 ORDER BY AG.ESPROVEEDORPRINCIPAL_AP = 'S' DESC, AG.CODIGO_PRV_AP LIMIT 1)), '')), '')),
           s.`COLOR`,
           SUM(fl.`CANTIDAD_FACLIN`)
      FROM `fza_facturas_lineas` fl
      JOIN `fza_facturas` f
        ON f.`NUMERO_FAC` = fl.`NUMERO_FAC_FACLIN`
       AND f.`SERIE_FAC` = fl.`SERIE_FAC_FACLIN`
      LEFT JOIN tmp_bst_alm_factura AFS
        ON AFS.SERIE_FAC = fl.SERIE_FAC_FACLIN
       AND AFS.NUMERO_FAC = fl.NUMERO_FAC_FACLIN
       AND AFS.LINEA_FAC = fl.LINEA_FACLIN
      JOIN `tmp_bst_sku` s
        ON s.`CODIGO_UNIDAD` = fl.`CODIGO_UNIDAD_FACLIN`
     WHERE
       (p_PROVEEDORES = '' OR EXISTS (
         SELECT 1 FROM fza_articulos_lotes LP
          WHERE LP.CODIGO_UNIDAD_LOT = fl.CODIGO_UNIDAD_FACLIN
            AND LP.LOTE_LOT = fl.LOTE_FACLIN
            AND COALESCE(TRIM(LP.CODIGO_PRV_LOT), '') NOT IN ('', '0')
            AND FIND_IN_SET(LP.CODIGO_PRV_LOT, p_PROVEEDORES) > 0)
        OR (NOT EXISTS (
         SELECT 1 FROM fza_articulos_lotes LP
          WHERE LP.CODIGO_UNIDAD_LOT = fl.CODIGO_UNIDAD_FACLIN
            AND LP.LOTE_LOT = fl.LOTE_FACLIN
            AND COALESCE(TRIM(LP.CODIGO_PRV_LOT), '') NOT IN ('', '0')) AND EXISTS (
         SELECT 1 FROM fza_articulos_proveedores APF
          WHERE APF.CODIGO_ART_AP = fl.CODIGO_ART_FACLIN
            AND FIND_IN_SET(APF.CODIGO_PRV_AP, p_PROVEEDORES) > 0))) AND COALESCE(NULLIF(fl.CODIGO_ALM_FACLIN, ''), NULLIF(f.CODIGO_ALM_FAC, ''), AFS.CODIGO_ALM) IN (SELECT `CODIGO_ALM` FROM `tmp_bst_alm`)
       AND DATE(f.`FECHA_FAC`) BETWEEN v_desde AND v_hasta
       
       AND NOT EXISTS (
         SELECT 1 FROM fza_facturas_traspasos_vendidos TVI
          WHERE TVI.SERIE_FAC_FACTV = f.SERIE_FAC
            AND TVI.NUMERO_FAC_FACTV = f.NUMERO_FAC)
       AND NOT EXISTS (
         SELECT 1 FROM fza_facturas_operaciones_caja TAI
         JOIN fza_caja_operaciones OTA
           ON OTA.ID_OPCAJA = TAI.ID_OPCAJA_FACOP
          AND OTA.TIPO_OPERACION_OPCAJA = 'TA'
          WHERE TAI.SERIE_FAC_FACOP = f.SERIE_FAC
            AND TAI.NUMERO_FAC_FACOP = f.NUMERO_FAC)

         AND COALESCE(f.FASE_FAC, '') NOT IN
           ('BORRADOR', 'ERROR_BORRADOR', 'CANCELADA',
            'SIN_VERIF_ANULADA', 'VERIFACTU_ANULADA',
            'NOVERIFACTU_ANULADA')
         AND NOT EXISTS (
           SELECT 1 FROM fza_verifactu_cola VA
            WHERE VA.SERIE_FAC_VFCOLA = f.SERIE_FAC
              AND VA.NUMERO_FAC_VFCOLA = f.NUMERO_FAC
              AND VA.TIPO_OPERACION_VFCOLA = 'ANULACION')
         AND NOT EXISTS (
           SELECT 1 FROM fza_facturas_relaciones FR
           JOIN fza_facturas FS
             ON FS.SERIE_FAC = FR.SERIE_FAC_FACREL
            AND FS.NUMERO_FAC = FR.NUMERO_FAC_FACREL
            AND FS.CODIGO_EMP_FAC = f.CODIGO_EMP_FAC
            WHERE FR.SERIE_FAC_ORIGEN_FACREL = f.SERIE_FAC
              AND FR.NUMERO_FAC_ORIGEN_FACREL = f.NUMERO_FAC
              AND FR.TIPO_RELACION_FACREL = 'RECTIFICA'
              AND f.FASE_FAC = 'RECTIFICADA'
              AND FS.TIPO_RECTIFICATIVA_FAC = 'S')
         AND NOT EXISTS (
           SELECT 1 FROM fza_facturas_relaciones FT
           JOIN fza_facturas FN
             ON FN.SERIE_FAC = FT.SERIE_FAC_FACREL
            AND FN.NUMERO_FAC = FT.NUMERO_FAC_FACREL
            AND FN.CODIGO_EMP_FAC = f.CODIGO_EMP_FAC
            WHERE FT.SERIE_FAC_ORIGEN_FACREL = f.SERIE_FAC
              AND FT.NUMERO_FAC_ORIGEN_FACREL = f.NUMERO_FAC
              AND FT.TIPO_RELACION_FACREL = 'SUSTITUYE'
              AND COALESCE(FN.FASE_FAC, '') NOT IN
                ('BORRADOR', 'ERROR_BORRADOR', 'CANCELADA',
                 'SIN_VERIF_ANULADA', 'VERIFACTU_ANULADA',
                 'NOVERIFACTU_ANULADA'))
     GROUP BY s.`CODIGO_ART`,
              CONCAT(IF(v_por_alm, COALESCE(NULLIF(fl.CODIGO_ALM_FACLIN, ''), NULLIF(f.CODIGO_ALM_FAC, ''), AFS.CODIGO_ALM), ''), IF(v_por_prv, CONCAT(CHAR(31 USING utf8mb4), COALESCE((SELECT NULLIF(NULLIF(TRIM(LG.CODIGO_PRV_LOT), ''), '0') FROM fza_articulos_lotes LG WHERE LG.CODIGO_UNIDAD_LOT = fl.CODIGO_UNIDAD_FACLIN AND LG.LOTE_LOT = fl.LOTE_FACLIN LIMIT 1), IF(p_PROVEEDORES = '', (SELECT MAX(AG.CODIGO_PRV_AP) FROM fza_articulos_proveedores AG WHERE AG.CODIGO_ART_AP = fl.CODIGO_ART_FACLIN AND AG.ESPROVEEDORPRINCIPAL_AP = 'S'), (SELECT AG.CODIGO_PRV_AP FROM fza_articulos_proveedores AG WHERE AG.CODIGO_ART_AP = fl.CODIGO_ART_FACLIN AND FIND_IN_SET(AG.CODIGO_PRV_AP, p_PROVEEDORES) > 0 ORDER BY AG.ESPROVEEDORPRINCIPAL_AP = 'S' DESC, AG.CODIGO_PRV_AP LIMIT 1)), '')), '')),
              s.`COLOR`;
    UPDATE `tmp_bst_base` b
      JOIN `tmp_bst_ven` v
        ON v.`CODIGO_ART` = b.`CODIGO_ART`
       AND v.`CODIGO_ALM` = b.`CODIGO_ALM`
       AND v.`COLOR` = b.`COLOR`
       SET b.`VEN_FAC` = v.`VEN_QTY`;






    DELETE FROM `tmp_bst_base`
     WHERE `EXI_INI` = 0 AND `EXI_FIN` = 0
       AND `ENT_COMPRA` = 0 AND `ENT_ALBENTRADA` = 0 AND `ENT_TRASPASO` = 0
       AND `ENT_DEPOSITO` = 0 AND `ENT_REGULAR` = 0 AND `ENT_DEVPRV` = 0
       AND `ENT_OTROS` = 0 AND `SAL_ALBVENTA` = 0 AND `SAL_VENTA` = 0
       AND `VEN_FAC` = 0 AND `NUM_MOVS` = 0;




    DROP TEMPORARY TABLE IF EXISTS `tmp_bst_marcas`;
    CREATE TEMPORARY TABLE `tmp_bst_marcas` (
        `CODIGO_ART` VARCHAR(20)  NOT NULL,
        `CODIGO_ALM` VARCHAR(50)  NOT NULL DEFAULT '',
        `COLOR`      VARCHAR(100) NOT NULL DEFAULT '',
        `CON_SINMOV` TINYINT      NOT NULL DEFAULT 0,
        `CON_DEVPRV` TINYINT      NOT NULL DEFAULT 0,
        `CON_OTROS`  TINYINT      NOT NULL DEFAULT 0,
        `CON_AVIFAC` TINYINT      NOT NULL DEFAULT 0,
        PRIMARY KEY (`CODIGO_ART`, `CODIGO_ALM`, `COLOR`)
    );
    INSERT INTO `tmp_bst_marcas`
    SELECT `CODIGO_ART`, `CODIGO_ALM`, `COLOR`,
           SUM(ABS(`EXI_INI`)) <> 0,
           SUM(ABS(`ENT_DEVPRV`)) <> 0,
           SUM(ABS(`ENT_OTROS`)) <> 0,
           SUM(ABS(`VEN_FAC` - `SAL_VENTA` - `SAL_ALBVENTA`)) <> 0
      FROM `tmp_bst_base`
     GROUP BY `CODIGO_ART`, `CODIGO_ALM`, `COLOR`;







    DROP TEMPORARY TABLE IF EXISTS `tmp_bst_medidas`;
    CREATE TEMPORARY TABLE `tmp_bst_medidas` (
        `CODIGO_ART`     VARCHAR(20)  NOT NULL,
        `CODIGO_ALM`     VARCHAR(50)  NOT NULL DEFAULT '',
        `COLOR`          VARCHAR(100) NULL,
        `COLOR_HEX`      VARCHAR(7)   NULL,
        `ORDEN_COLOR`    INT          NOT NULL DEFAULT 0,
        `BANDA`          VARCHAR(20)  NOT NULL,
        `ORDEN_BANDA`    INT          NOT NULL,
        `ETIQUETA_BANDA` VARCHAR(40)  NOT NULL,
        `ES_COSTE`       TINYINT      NOT NULL DEFAULT 0,
        `CANTIDAD`       DECIMAL(19,6) NOT NULL DEFAULT 0,
        KEY `IDX_BST_MED` (`CODIGO_ART`, `CODIGO_ALM`, `COLOR`, `ORDEN_BANDA`)
    );


    IF p_MODO = 'F' THEN
        INSERT INTO `tmp_bst_medidas`
        SELECT `CODIGO_ART`, `CODIGO_ALM`, `COLOR`, `COLOR_HEX`, `ORDEN_COLOR`,
               'EXIINI', 10, 'Existencias iniciales', 1, `EXI_INI`
          FROM `tmp_bst_base`;
    ELSE



        INSERT INTO `tmp_bst_medidas`
        SELECT b.`CODIGO_ART`, b.`CODIGO_ALM`, b.`COLOR`, b.`COLOR_HEX`,
               b.`ORDEN_COLOR`,
               'SINMOV', 15, 'Stock sin movim.', 1, b.`EXI_INI`
          FROM `tmp_bst_base` b
          JOIN `tmp_bst_marcas` x
            ON x.`CODIGO_ART` = b.`CODIGO_ART`
           AND x.`CODIGO_ALM` = b.`CODIGO_ALM`
           AND x.`COLOR` = b.`COLOR`
         WHERE x.`CON_SINMOV` = 1;
    END IF;



    IF (p_MODO = 'F' AND p_DESGLOSADO = 'N') OR p_MODO = 'A' THEN
        INSERT INTO `tmp_bst_medidas`
        SELECT `CODIGO_ART`, `CODIGO_ALM`, `COLOR`, `COLOR_HEX`, `ORDEN_COLOR`,
               'ENT', 20, 'Entradas', 1,
               `ENT_COMPRA` + `ENT_ALBENTRADA` + `ENT_TRASPASO`
                 + `ENT_DEPOSITO` + `ENT_REGULAR` + `ENT_DEVPRV` + `ENT_OTROS`
          FROM `tmp_bst_base`;
        INSERT INTO `tmp_bst_medidas`
        SELECT `CODIGO_ART`, `CODIGO_ALM`, `COLOR`, `COLOR_HEX`, `ORDEN_COLOR`,
               'VEN', 50, 'Ventas', 0, `SAL_VENTA` + `SAL_ALBVENTA`
          FROM `tmp_bst_base`;
    END IF;


    IF p_MODO = 'F' AND p_DESGLOSADO = 'S' THEN
        INSERT INTO `tmp_bst_medidas`
        SELECT `CODIGO_ART`, `CODIGO_ALM`, `COLOR`, `COLOR_HEX`, `ORDEN_COLOR`,
               'ENTCMP', 21, 'Ent. compra', 1, `ENT_COMPRA`
          FROM `tmp_bst_base`;
        INSERT INTO `tmp_bst_medidas`
        SELECT `CODIGO_ART`, `CODIGO_ALM`, `COLOR`, `COLOR_HEX`, `ORDEN_COLOR`,
               'ENTALB', 22, 'Alb. entrada', 1, `ENT_ALBENTRADA`
          FROM `tmp_bst_base`;
        INSERT INTO `tmp_bst_medidas`
        SELECT `CODIGO_ART`, `CODIGO_ALM`, `COLOR`, `COLOR_HEX`, `ORDEN_COLOR`,
               'ENTTRA', 23, 'Traspasos (neto)', 1, `ENT_TRASPASO`
          FROM `tmp_bst_base`;
        INSERT INTO `tmp_bst_medidas`
        SELECT `CODIGO_ART`, `CODIGO_ALM`, `COLOR`, `COLOR_HEX`, `ORDEN_COLOR`,
               'ENTDEP', 24, 'Depósitos (neto)', 1, `ENT_DEPOSITO`
          FROM `tmp_bst_base`;
        INSERT INTO `tmp_bst_medidas`
        SELECT `CODIGO_ART`, `CODIGO_ALM`, `COLOR`, `COLOR_HEX`, `ORDEN_COLOR`,
               'ENTREG', 25, 'Regulariz.', 1, `ENT_REGULAR`
          FROM `tmp_bst_base`;
        INSERT INTO `tmp_bst_medidas`
        SELECT b.`CODIGO_ART`, b.`CODIGO_ALM`, b.`COLOR`, b.`COLOR_HEX`,
               b.`ORDEN_COLOR`,
               'ENTDEV', 26, 'Dev. proveedor', 1, b.`ENT_DEVPRV`
          FROM `tmp_bst_base` b
          JOIN `tmp_bst_marcas` x
            ON x.`CODIGO_ART` = b.`CODIGO_ART`
           AND x.`CODIGO_ALM` = b.`CODIGO_ALM`
           AND x.`COLOR` = b.`COLOR`
         WHERE x.`CON_DEVPRV` = 1;
        INSERT INTO `tmp_bst_medidas`
        SELECT b.`CODIGO_ART`, b.`CODIGO_ALM`, b.`COLOR`, b.`COLOR_HEX`,
               b.`ORDEN_COLOR`,
               'ENTOTR', 27, 'Otros movim.', 1, b.`ENT_OTROS`
          FROM `tmp_bst_base` b
          JOIN `tmp_bst_marcas` x
            ON x.`CODIGO_ART` = b.`CODIGO_ART`
           AND x.`CODIGO_ALM` = b.`CODIGO_ALM`
           AND x.`COLOR` = b.`COLOR`
         WHERE x.`CON_OTROS` = 1;
        INSERT INTO `tmp_bst_medidas`
        SELECT `CODIGO_ART`, `CODIGO_ALM`, `COLOR`, `COLOR_HEX`, `ORDEN_COLOR`,
               'SALALB', 43, 'Alb. venta', 0, `SAL_ALBVENTA`
          FROM `tmp_bst_base`;
        INSERT INTO `tmp_bst_medidas`
        SELECT `CODIGO_ART`, `CODIGO_ALM`, `COLOR`, `COLOR_HEX`, `ORDEN_COLOR`,
               'VEN', 50, 'Ventas', 0, `SAL_VENTA`
          FROM `tmp_bst_base`;
    END IF;

    INSERT INTO `tmp_bst_medidas`
    SELECT `CODIGO_ART`, `CODIGO_ALM`, `COLOR`, `COLOR_HEX`, `ORDEN_COLOR`,
           'EXIFIN', 90, 'Existencias finales', 1, `EXI_FIN`
      FROM `tmp_bst_base`;


    INSERT INTO `tmp_bst_medidas`
    SELECT b.`CODIGO_ART`, b.`CODIGO_ALM`, b.`COLOR`, b.`COLOR_HEX`,
           b.`ORDEN_COLOR`,
           'AVIFAC', 95, 'Aviso fact.-vend.', 0,
           b.`VEN_FAC` - b.`SAL_VENTA` - b.`SAL_ALBVENTA`
      FROM `tmp_bst_base` b
      JOIN `tmp_bst_marcas` x
        ON x.`CODIGO_ART` = b.`CODIGO_ART`
       AND x.`CODIGO_ALM` = b.`CODIGO_ALM`
       AND x.`COLOR` = b.`COLOR`
     WHERE x.`CON_AVIFAC` = 1;


    IF p_BANDAS <> '' THEN
        DELETE FROM `tmp_bst_medidas`
         WHERE NOT FIND_IN_SET(`BANDA`, p_BANDAS)
           AND `BANDA` NOT IN ('AVIFAC', 'SINMOV');
    END IF;








    DROP TEMPORARY TABLE IF EXISTS `tmp_bst_pvp`;





    CREATE TEMPORARY TABLE `tmp_bst_pvp` AS
    SELECT s.`CODIGO_ART`, s.`COLOR`,
           COALESCE(
               MAX(IF(IFNULL(t.`CODIGO_UNIDAD_ARTTAR`, '') = '',
                      t.`PRECIO_FINAL_ARTTAR`, NULL)),
               MAX(t.`PRECIO_FINAL_ARTTAR`)) AS `PVP`
      FROM `tmp_bst_sku` s
      JOIN `fza_articulos_tarifas` t
        ON t.`CODIGO_ART_ARTTAR` = s.`CODIGO_ART`
       AND t.`CODIGO_TAR_ARTTAR` = v_tarifa
       AND t.`ESACTIVO_ARTTAR` = 'S'
       AND (t.`FECHA_DESDE_ARTTAR` IS NULL
            OR t.`FECHA_DESDE_ARTTAR` <= CURRENT_DATE)
       AND (t.`FECHA_HASTA_ARTTAR` IS NULL
            OR t.`FECHA_HASTA_ARTTAR` >= CURRENT_DATE)
       AND (IFNULL(t.`CODIGO_UNIDAD_ARTTAR`, '') = ''
            OR t.`CODIGO_UNIDAD_ARTTAR` = s.`CODIGO_UNIDAD`
            OR (LOCATE('/*/', t.`CODIGO_UNIDAD_ARTTAR`) = 0
                AND LEFT(s.`CODIGO_UNIDAD`,
                         CHAR_LENGTH(t.`CODIGO_UNIDAD_ARTTAR`) + 1)
                    = CONCAT(t.`CODIGO_UNIDAD_ARTTAR`, '/'))
            OR (LOCATE('/*/', t.`CODIGO_UNIDAD_ARTTAR`) > 0
                AND LEFT(s.`CODIGO_UNIDAD`,
                         LOCATE('/*/', t.`CODIGO_UNIDAD_ARTTAR`))
                    = LEFT(t.`CODIGO_UNIDAD_ARTTAR`,
                           LOCATE('/*/', t.`CODIGO_UNIDAD_ARTTAR`))
                AND RIGHT(s.`CODIGO_UNIDAD`,
                          CHAR_LENGTH(t.`CODIGO_UNIDAD_ARTTAR`)
                          - LOCATE('/*/', t.`CODIGO_UNIDAD_ARTTAR`) - 1)
                    = SUBSTRING(t.`CODIGO_UNIDAD_ARTTAR`,
                                LOCATE('/*/', t.`CODIGO_UNIDAD_ARTTAR`)
                                + 2)))
     GROUP BY s.`CODIGO_ART`, s.`COLOR`;
    ALTER TABLE `tmp_bst_pvp`
        ADD PRIMARY KEY (`CODIGO_ART`, `COLOR`);

    DROP TEMPORARY TABLE IF EXISTS `tmp_bst_cst`;
    CREATE TEMPORARY TABLE `tmp_bst_cst` AS
    SELECT sk.`CODIGO_ART`, sk.`COLOR`,
           IF(v_por_alm, st.`CODIGO_ALM_STK`, '') AS `CODIGO_ALM`,
           IF(SUM(st.`CANTIDAD_STK`) <> 0,
              SUM(st.`VALOR_TOTAL_STK`) / SUM(st.`CANTIDAD_STK`), 0) AS `COSTE`
      FROM `fza_articulos_stockactual` st
      JOIN `tmp_bst_sku` sk
        ON sk.`CODIGO_UNIDAD` = st.`CODIGO_UNIDAD_STK`
     WHERE
       (p_PROVEEDORES = '' OR EXISTS (
         SELECT 1 FROM fza_articulos_lotes LP
          WHERE LP.CODIGO_UNIDAD_LOT = st.CODIGO_UNIDAD_STK
            AND LP.LOTE_LOT = st.LOTE_STK
            AND COALESCE(TRIM(LP.CODIGO_PRV_LOT), '') NOT IN ('', '0')
            AND FIND_IN_SET(LP.CODIGO_PRV_LOT, p_PROVEEDORES) > 0)
        OR (NOT EXISTS (
         SELECT 1 FROM fza_articulos_lotes LP
          WHERE LP.CODIGO_UNIDAD_LOT = st.CODIGO_UNIDAD_STK
            AND LP.LOTE_LOT = st.LOTE_STK
            AND COALESCE(TRIM(LP.CODIGO_PRV_LOT), '') NOT IN ('', '0')) AND EXISTS (
         SELECT 1 FROM fza_articulos_proveedores APF
          WHERE APF.CODIGO_ART_AP = (SELECT SF.CODIGO_ART_SKU FROM fza_articulos_skus SF WHERE SF.CODIGO_UNIDAD_SKU = st.CODIGO_UNIDAD_STK)
            AND FIND_IN_SET(APF.CODIGO_PRV_AP, p_PROVEEDORES) > 0))) AND st.`CODIGO_ALM_STK` IN (SELECT `CODIGO_ALM` FROM `tmp_bst_alm`)

       AND st.`CODIGO_UNIDAD_STK` IN
           (SELECT `CODIGO_UNIDAD` FROM `tmp_bst_sku`)
     GROUP BY sk.`CODIGO_ART`, sk.`COLOR`,
              IF(v_por_alm, st.`CODIGO_ALM_STK`, '');
    ALTER TABLE `tmp_bst_cst` ADD PRIMARY KEY
      (`CODIGO_ART`, `CODIGO_ALM`, `COLOR`);

    DROP TEMPORARY TABLE IF EXISTS `tmp_bst_prov`;
    CREATE TEMPORARY TABLE `tmp_bst_prov` AS
    SELECT ap.`CODIGO_ART_AP` AS `CODIGO_ART`,
           MAX(ap.`REF_PROVEEDOR_AP`)   AS `REF_PROVEEDOR_AP`,
           MAX(ap.`PRECIO_ULT_COMPRA_AP`) AS `COSTE_PRV`,
           MAX(ap.`CODIGO_PRV_AP`)      AS `CODIGO_PRV`,
           MAX(pr.`RAZON_SOCIAL_PRV`)   AS `RAZON`
      FROM `fza_articulos_proveedores` ap
      LEFT JOIN `fza_proveedores` pr
        ON pr.`CODIGO_PRV_PRV` = ap.`CODIGO_PRV_AP`
     WHERE ap.`ESPROVEEDORPRINCIPAL_AP` = 'S'

       AND ap.`CODIGO_ART_AP` IN
           (SELECT `CODIGO_ART` FROM `tmp_bst_arts`)
     GROUP BY ap.`CODIGO_ART_AP`;
    ALTER TABLE `tmp_bst_prov` ADD PRIMARY KEY (`CODIGO_ART`);

    DROP TEMPORARY TABLE IF EXISTS `tmp_bst_tmp`;
    CREATE TEMPORARY TABLE `tmp_bst_tmp` AS
    SELECT s.`CODIGO_ART` AS `CODIGO_ART`, s.`COLOR` AS `COLOR`,
           MAX(COALESCE(e.`VALOR_PV`,
                        e.`VALOR_LIBRE_ARTPROP`)) AS `TEMPORADA`
      FROM `tmp_bst_sku` s
      JOIN `vi_articulos_propiedades_efectivas` e
        ON e.`CODIGO_UNIDAD_SKU` = s.`CODIGO_UNIDAD`
       AND e.`CODIGO_PROP_ARTPROP` = 'TEMPORADA'
     GROUP BY s.`CODIGO_ART`, s.`COLOR`;
    ALTER TABLE `tmp_bst_tmp` ADD PRIMARY KEY (`CODIGO_ART`, `COLOR`);






    DROP TEMPORARY TABLE IF EXISTS `tmp_bst_fal`;
    CREATE TEMPORARY TABLE `tmp_bst_fal` AS
    SELECT DISTINCT al.`SERIE_FAC_ALBLIN` AS `SERIE_FAC`,
           al.`NUMERO_FAC_ALBLIN` AS `NUMERO_FAC`,
           al.`LINEA_FAC_ALBLIN` AS `LINEA_FAC`
      FROM `fza_albaranes_lineas` al
     WHERE
       (p_PROVEEDORES = '' OR EXISTS (
         SELECT 1 FROM fza_articulos_lotes LP
          WHERE LP.CODIGO_UNIDAD_LOT = al.CODIGO_UNIDAD_ALBLIN
            AND LP.LOTE_LOT = al.LOTE_ALBLIN
            AND COALESCE(TRIM(LP.CODIGO_PRV_LOT), '') NOT IN ('', '0')
            AND FIND_IN_SET(LP.CODIGO_PRV_LOT, p_PROVEEDORES) > 0)
        OR (NOT EXISTS (
         SELECT 1 FROM fza_articulos_lotes LP
          WHERE LP.CODIGO_UNIDAD_LOT = al.CODIGO_UNIDAD_ALBLIN
            AND LP.LOTE_LOT = al.LOTE_ALBLIN
            AND COALESCE(TRIM(LP.CODIGO_PRV_LOT), '') NOT IN ('', '0')) AND EXISTS (
         SELECT 1 FROM fza_articulos_proveedores APF
          WHERE APF.CODIGO_ART_AP = al.CODIGO_ART_ALBLIN
            AND FIND_IN_SET(APF.CODIGO_PRV_AP, p_PROVEEDORES) > 0))) AND COALESCE(al.`SERIE_FAC_ALBLIN`, '') <> ''
       AND COALESCE(al.`NUMERO_FAC_ALBLIN`, '') <> ''
       AND COALESCE(al.`LINEA_FAC_ALBLIN`, '') <> '';
    ALTER TABLE `tmp_bst_fal`
        ADD PRIMARY KEY (`SERIE_FAC`, `NUMERO_FAC`, `LINEA_FAC`);

    DROP TEMPORARY TABLE IF EXISTS `tmp_bst_vt`;
    CREATE TEMPORARY TABLE `tmp_bst_vt` AS



    SELECT s.`CODIGO_ART`,
           CONCAT(IF(v_por_alm, COALESCE(NULLIF(fl.CODIGO_ALM_FACLIN, ''), NULLIF(f.CODIGO_ALM_FAC, ''), AFS.CODIGO_ALM), ''), IF(v_por_prv, CONCAT(CHAR(31 USING utf8mb4), COALESCE((SELECT NULLIF(NULLIF(TRIM(LG.CODIGO_PRV_LOT), ''), '0') FROM fza_articulos_lotes LG WHERE LG.CODIGO_UNIDAD_LOT = fl.CODIGO_UNIDAD_FACLIN AND LG.LOTE_LOT = fl.LOTE_FACLIN LIMIT 1), IF(p_PROVEEDORES = '', (SELECT MAX(AG.CODIGO_PRV_AP) FROM fza_articulos_proveedores AG WHERE AG.CODIGO_ART_AP = fl.CODIGO_ART_FACLIN AND AG.ESPROVEEDORPRINCIPAL_AP = 'S'), (SELECT AG.CODIGO_PRV_AP FROM fza_articulos_proveedores AG WHERE AG.CODIGO_ART_AP = fl.CODIGO_ART_FACLIN AND FIND_IN_SET(AG.CODIGO_PRV_AP, p_PROVEEDORES) > 0 ORDER BY AG.ESPROVEEDORPRINCIPAL_AP = 'S' DESC, AG.CODIGO_PRV_AP LIMIT 1)), '')), '')) AS `CODIGO_ALM`,
           s.`COLOR`,
           SUM(fl.`CANTIDAD_FACLIN`) AS `VEN_QTY`,





           SUM(COALESCE(fl.`TOTAL_FAC_SIVA_FACLIN`,
                    CASE WHEN fl.`ESIMP_INCL_TARIFA_FACLIN` = 'S'
                         THEN fl.`TOTAL_FACLIN` /
                         (1 + COALESCE(fl.`PORCENTAJE_IVA_FACLIN`, 0) / 100)
                         ELSE fl.`TOTAL_FACLIN` END)) AS `VEN_IMPORTE`,

           SUM(IF(fa.`LINEA_FAC` IS NULL, 0,
                  fl.`CANTIDAD_FACLIN`)) AS `VEN_QTY_ALB`,
           SUM(IF(fa.`LINEA_FAC` IS NULL, 0,
                  COALESCE(fl.`TOTAL_FAC_SIVA_FACLIN`,
                           CASE WHEN fl.`ESIMP_INCL_TARIFA_FACLIN` = 'S'
                                THEN fl.`TOTAL_FACLIN` /
                                (1 + COALESCE(fl.`PORCENTAJE_IVA_FACLIN`, 0) / 100)
                                ELSE fl.`TOTAL_FACLIN` END))) AS `VEN_IMPORTE_ALB`
      FROM `fza_facturas_lineas` fl
      JOIN `fza_facturas` f
        ON f.`NUMERO_FAC` = fl.`NUMERO_FAC_FACLIN`
       AND f.`SERIE_FAC` = fl.`SERIE_FAC_FACLIN`
      LEFT JOIN tmp_bst_alm_factura AFS
        ON AFS.SERIE_FAC = fl.SERIE_FAC_FACLIN
       AND AFS.NUMERO_FAC = fl.NUMERO_FAC_FACLIN
       AND AFS.LINEA_FAC = fl.LINEA_FACLIN
      LEFT JOIN `tmp_bst_fal` fa
        ON fa.`SERIE_FAC` = fl.`SERIE_FAC_FACLIN`
       AND fa.`NUMERO_FAC` = fl.`NUMERO_FAC_FACLIN`
       AND fa.`LINEA_FAC` = fl.`LINEA_FACLIN`
      JOIN `tmp_bst_sku` s
        ON s.`CODIGO_UNIDAD` = fl.`CODIGO_UNIDAD_FACLIN`
     WHERE
       (p_PROVEEDORES = '' OR EXISTS (
         SELECT 1 FROM fza_articulos_lotes LP
          WHERE LP.CODIGO_UNIDAD_LOT = fl.CODIGO_UNIDAD_FACLIN
            AND LP.LOTE_LOT = fl.LOTE_FACLIN
            AND COALESCE(TRIM(LP.CODIGO_PRV_LOT), '') NOT IN ('', '0')
            AND FIND_IN_SET(LP.CODIGO_PRV_LOT, p_PROVEEDORES) > 0)
        OR (NOT EXISTS (
         SELECT 1 FROM fza_articulos_lotes LP
          WHERE LP.CODIGO_UNIDAD_LOT = fl.CODIGO_UNIDAD_FACLIN
            AND LP.LOTE_LOT = fl.LOTE_FACLIN
            AND COALESCE(TRIM(LP.CODIGO_PRV_LOT), '') NOT IN ('', '0')) AND EXISTS (
         SELECT 1 FROM fza_articulos_proveedores APF
          WHERE APF.CODIGO_ART_AP = fl.CODIGO_ART_FACLIN
            AND FIND_IN_SET(APF.CODIGO_PRV_AP, p_PROVEEDORES) > 0))) AND COALESCE(NULLIF(fl.CODIGO_ALM_FACLIN, ''), NULLIF(f.CODIGO_ALM_FAC, ''), AFS.CODIGO_ALM) IN (SELECT `CODIGO_ALM` FROM `tmp_bst_alm`)
       AND DATE(f.`FECHA_FAC`) BETWEEN v_desde AND v_hasta

         AND COALESCE(f.FASE_FAC, '') NOT IN
           ('BORRADOR', 'ERROR_BORRADOR', 'CANCELADA',
            'SIN_VERIF_ANULADA', 'VERIFACTU_ANULADA',
            'NOVERIFACTU_ANULADA')
         AND NOT EXISTS (
           SELECT 1 FROM fza_verifactu_cola VA
            WHERE VA.SERIE_FAC_VFCOLA = f.SERIE_FAC
              AND VA.NUMERO_FAC_VFCOLA = f.NUMERO_FAC
              AND VA.TIPO_OPERACION_VFCOLA = 'ANULACION')
         AND NOT EXISTS (
           SELECT 1 FROM fza_facturas_relaciones FR
           JOIN fza_facturas FS
             ON FS.SERIE_FAC = FR.SERIE_FAC_FACREL
            AND FS.NUMERO_FAC = FR.NUMERO_FAC_FACREL
            AND FS.CODIGO_EMP_FAC = f.CODIGO_EMP_FAC
            WHERE FR.SERIE_FAC_ORIGEN_FACREL = f.SERIE_FAC
              AND FR.NUMERO_FAC_ORIGEN_FACREL = f.NUMERO_FAC
              AND FR.TIPO_RELACION_FACREL = 'RECTIFICA'
              AND f.FASE_FAC = 'RECTIFICADA'
              AND FS.TIPO_RECTIFICATIVA_FAC = 'S')
         AND NOT EXISTS (
           SELECT 1 FROM fza_facturas_relaciones FT
           JOIN fza_facturas FN
             ON FN.SERIE_FAC = FT.SERIE_FAC_FACREL
            AND FN.NUMERO_FAC = FT.NUMERO_FAC_FACREL
            AND FN.CODIGO_EMP_FAC = f.CODIGO_EMP_FAC
            WHERE FT.SERIE_FAC_ORIGEN_FACREL = f.SERIE_FAC
              AND FT.NUMERO_FAC_ORIGEN_FACREL = f.NUMERO_FAC
              AND FT.TIPO_RELACION_FACREL = 'SUSTITUYE'
              AND COALESCE(FN.FASE_FAC, '') NOT IN
                ('BORRADOR', 'ERROR_BORRADOR', 'CANCELADA',
                 'SIN_VERIF_ANULADA', 'VERIFACTU_ANULADA',
                 'NOVERIFACTU_ANULADA'))
     GROUP BY s.`CODIGO_ART`,
              CONCAT(IF(v_por_alm, COALESCE(NULLIF(fl.CODIGO_ALM_FACLIN, ''), NULLIF(f.CODIGO_ALM_FAC, ''), AFS.CODIGO_ALM), ''), IF(v_por_prv, CONCAT(CHAR(31 USING utf8mb4), COALESCE((SELECT NULLIF(NULLIF(TRIM(LG.CODIGO_PRV_LOT), ''), '0') FROM fza_articulos_lotes LG WHERE LG.CODIGO_UNIDAD_LOT = fl.CODIGO_UNIDAD_FACLIN AND LG.LOTE_LOT = fl.LOTE_FACLIN LIMIT 1), IF(p_PROVEEDORES = '', (SELECT MAX(AG.CODIGO_PRV_AP) FROM fza_articulos_proveedores AG WHERE AG.CODIGO_ART_AP = fl.CODIGO_ART_FACLIN AND AG.ESPROVEEDORPRINCIPAL_AP = 'S'), (SELECT AG.CODIGO_PRV_AP FROM fza_articulos_proveedores AG WHERE AG.CODIGO_ART_AP = fl.CODIGO_ART_FACLIN AND FIND_IN_SET(AG.CODIGO_PRV_AP, p_PROVEEDORES) > 0 ORDER BY AG.ESPROVEEDORPRINCIPAL_AP = 'S' DESC, AG.CODIGO_PRV_AP LIMIT 1)), '')), '')), s.`COLOR`;
    ALTER TABLE `tmp_bst_vt` ADD PRIMARY KEY (`CODIGO_ART`, `CODIGO_ALM`, `COLOR`);









    DROP TEMPORARY TABLE IF EXISTS `tmp_bst_nc`;
    CREATE TEMPORARY TABLE `tmp_bst_nc` (
        `CODIGO_ART`   VARCHAR(20)  NOT NULL,
        `COLOR`        VARCHAR(100) NOT NULL DEFAULT '',
        `NOMBRE_COLOR` VARCHAR(100) NULL,
        PRIMARY KEY (`CODIGO_ART`, `COLOR`)
    );
    INSERT INTO `tmp_bst_nc` (`CODIGO_ART`, `COLOR`, `NOMBRE_COLOR`)
    SELECT s.`CODIGO_ART`, s.`COLOR`,
           MIN(NULLIF(TRIM(atb.`NOMBRE_ATB`), ''))
      FROM `tmp_bst_sku` s
      JOIN `fza_atributos_sku` sac
        ON sac.`CODIGO_UNIDAD_SKU_SA` = s.`CODIGO_UNIDAD`
      JOIN `fza_atributos_valores` co
        ON co.`ID_AV` = sac.`ID_AV_SA` AND co.`ID_VA_AV` = (SELECT EJ452.ID_ATB_VA FROM VI_VARIACIONES_EJES EJ452 WHERE EJ452.ID_VAR_VA = (SELECT SK452.CODIGO_VAR_SKU FROM fza_articulos_skus SK452 WHERE SK452.CODIGO_UNIDAD_SKU = sac.CODIGO_UNIDAD_SKU_SA) AND EJ452.EJE_VA = 'F')
      LEFT JOIN `fza_articulos_atributos_basicos` aab
        ON aab.`CODIGO_ART_AAB` = s.`CODIGO_ART`
       AND aab.`ID_AV_AAB` = co.`ID_AV`
      LEFT JOIN `fza_articulos_conjuntos_asign` aca
        ON aca.`CODIGO_ART_ACA` = s.`CODIGO_ART`
       AND aca.`ID_VA_ACA` = (SELECT EJ452.ID_ATB_VA FROM VI_VARIACIONES_EJES EJ452 WHERE EJ452.ID_VAR_VA = (SELECT AR452.TIPO_VARIACION_ART FROM fza_articulos AR452 WHERE AR452.CODIGO_ART_ART = s.CODIGO_ART) AND EJ452.EJE_VA = 'F')
      LEFT JOIN `fza_atributos_conjuntos_det` acd
        ON acd.`ID_AC_ACD` = aca.`ID_AC_ACA`
       AND acd.`ID_AV_ACD` = co.`ID_AV`
      LEFT JOIN `fza_atributos_basicos` atb
        ON atb.`ID_ATB` = CASE
             WHEN aab.`CODIGO_ART_AAB` IS NOT NULL THEN aab.`ID_ATB_AAB`
             WHEN acd.`ID_ATB_ACD` IS NOT NULL THEN acd.`ID_ATB_ACD`
             ELSE co.`ID_ATB_AV`
           END
     WHERE s.`COLOR` = co.`AV`
     GROUP BY s.`CODIGO_ART`, s.`COLOR`;





    SELECT
        COALESCE(fam.`ORDEN_FAM`, 999999)             AS `ORDEN_FAM`,
        art.`CODIGO_FAM_ART`                          AS `CODIGO_FAM`,
        COALESCE(fam.`DESCRIPCION_FAM`,
                 fam.`NOMBRE_FAM_FAM`, art.`CODIGO_FAM_ART`) AS `DESCRIPCION_FAM`,
        p.`CODIGO_ART`                                AS `CODIGO_ART_ART`,
        art.`DESCRIPCION_ART`                         AS `DESCRIPCION_ART`,
        SUBSTRING_INDEX(p.`CODIGO_ALM`, CHAR(31 USING utf8mb4), 1) AS `CODIGO_ALM`,
        COALESCE(alm.`NOMBRE_ALM_ALM`, '')            AS `NOMBRE_ALM`,
        prov.`REF_PROVEEDOR_AP`                       AS `REF_PRV`,
        ROUND(COALESCE(NULLIF(cst.`COSTE`, 0), prov.`COSTE_PRV`, 0), 2) AS `COSTE_ART`,
        ROUND(COALESCE(pvp.`PVP`, 0), 2)              AS `PVP_ART`,
        p.`ORDEN_COLOR`, p.`COLOR`, p.`COLOR_HEX`,
        COALESCE(nc.`NOMBRE_COLOR`, p.`COLOR`)        AS `NOMBRE_COLOR`,
        p.`ORDEN_BANDA`, p.`BANDA`, p.`ETIQUETA_BANDA`, p.`ES_COSTE`,
        p.`CANTIDAD`,




        ROUND(CASE
                WHEN p.`BANDA` = 'SALALB' THEN
                  IF(COALESCE(vt.`VEN_QTY_ALB`, 0) <> 0,
                     COALESCE(vt.`VEN_IMPORTE_ALB`, 0) / vt.`VEN_QTY_ALB`, 0)
                WHEN p.`BANDA` = 'VEN' AND v_desglosado THEN
                  IF((COALESCE(vt.`VEN_QTY`, 0) - COALESCE(vt.`VEN_QTY_ALB`, 0)) <> 0,
                     (COALESCE(vt.`VEN_IMPORTE`, 0)
                     - COALESCE(vt.`VEN_IMPORTE_ALB`, 0))
                     / (COALESCE(vt.`VEN_QTY`, 0) - COALESCE(vt.`VEN_QTY_ALB`, 0)), 0)
                WHEN p.`BANDA` = 'VEN' THEN
                  IF(COALESCE(vt.`VEN_QTY`, 0) <> 0,
                     COALESCE(vt.`VEN_IMPORTE`, 0) / vt.`VEN_QTY`, 0)
                WHEN p.`BANDA` = 'AVIFAC' THEN 0
                WHEN p.`ES_COSTE` = 1 THEN
                  COALESCE(NULLIF(cst.`COSTE`, 0), prov.`COSTE_PRV`, 0)
                ELSE COALESCE(pvp.`PVP`, 0)
              END, 2)                                 AS `PRECIO`,



        ROUND(CASE
                WHEN p.`BANDA` = 'SALALB' THEN
                  COALESCE(vt.`VEN_IMPORTE_ALB`, 0)
                WHEN p.`BANDA` = 'VEN' AND v_desglosado THEN
                  (COALESCE(vt.`VEN_IMPORTE`, 0)
                     - COALESCE(vt.`VEN_IMPORTE_ALB`, 0))
                WHEN p.`BANDA` = 'VEN' THEN COALESCE(vt.`VEN_IMPORTE`, 0)
                WHEN p.`BANDA` = 'AVIFAC' THEN 0
                ELSE p.`CANTIDAD` * IF(p.`ES_COSTE` = 1,
                       COALESCE(NULLIF(cst.`COSTE`, 0), prov.`COSTE_PRV`, 0),
                       COALESCE(pvp.`PVP`, 0))
              END, 2)                                 AS `IMPORTE`,




        ROUND(CASE
                WHEN p.`BANDA` = 'SALALB' THEN
                  COALESCE(vt.`VEN_IMPORTE_ALB`, 0)
                WHEN p.`BANDA` = 'VEN' AND v_desglosado THEN
                  (COALESCE(vt.`VEN_IMPORTE`, 0)
                     - COALESCE(vt.`VEN_IMPORTE_ALB`, 0))
                WHEN p.`BANDA` = 'VEN' THEN COALESCE(vt.`VEN_IMPORTE`, 0)
                ELSE 0
              END, 2)
                                                      AS `VENTAS`,



        IF(p.`BANDA` = 'EXIFIN', p.`CANTIDAD`, 0)     AS `EXIFIN_CANT`,
        ROUND(IF(p.`BANDA` = 'EXIFIN',
                 p.`CANTIDAD` * COALESCE(NULLIF(cst.`COSTE`, 0),
                                         prov.`COSTE_PRV`, 0),
                 0), 2)                               AS `EXIFIN_IMP`,
        CASE p_NIVEL1
            WHEN 'PRV' THEN IF(v_por_prv, SUBSTRING_INDEX(p.`CODIGO_ALM`, CHAR(31 USING utf8mb4), -1), COALESCE(prov.`CODIGO_PRV`, ''))
            WHEN 'FAM' THEN COALESCE(fg.`COD_GRP`, art.`CODIGO_FAM_ART`)
            WHEN 'TMP' THEN COALESCE(tmp.`TEMPORADA`, '')
            WHEN 'ALM' THEN SUBSTRING_INDEX(p.`CODIGO_ALM`, CHAR(31 USING utf8mb4), 1)
            ELSE ''
        END                                           AS `GRUPO1_COD`,
        CASE p_NIVEL1
            WHEN 'PRV' THEN CONCAT('Proveedor: ',
                 COALESCE(NULLIF(gprv.`RAZON_SOCIAL_PRV`, ''),
                          NULLIF(SUBSTRING_INDEX(p.`CODIGO_ALM`, CHAR(31 USING utf8mb4), -1), ''),
                          '(sin proveedor)'))
            WHEN 'FAM' THEN CONCAT('Familia: ',
                 COALESCE(fg.`DESC_GRP`, fg.`COD_GRP`,
                          art.`CODIGO_FAM_ART`))
            WHEN 'TMP' THEN CONCAT('Temporada: ',
                 COALESCE(NULLIF(tmp.`TEMPORADA`, ''), '(sin temporada)'))
            WHEN 'ALM' THEN CONCAT('Almacén: ',
                 COALESCE(NULLIF(alm.`NOMBRE_ALM_ALM`, ''), SUBSTRING_INDEX(p.`CODIGO_ALM`, CHAR(31 USING utf8mb4), 1),
                          '(sin almacén)'))
            ELSE ''
        END                                           AS `GRUPO1_ETIQ`,
        CASE p_NIVEL2
            WHEN 'PRV' THEN IF(v_por_prv, SUBSTRING_INDEX(p.`CODIGO_ALM`, CHAR(31 USING utf8mb4), -1), COALESCE(prov.`CODIGO_PRV`, ''))
            WHEN 'FAM' THEN COALESCE(fg.`COD_GRP`, art.`CODIGO_FAM_ART`)
            WHEN 'TMP' THEN COALESCE(tmp.`TEMPORADA`, '')
            WHEN 'ALM' THEN SUBSTRING_INDEX(p.`CODIGO_ALM`, CHAR(31 USING utf8mb4), 1)
            ELSE ''
        END                                           AS `GRUPO2_COD`,
        CASE p_NIVEL2
            WHEN 'PRV' THEN CONCAT('Proveedor: ',
                 COALESCE(NULLIF(gprv.`RAZON_SOCIAL_PRV`, ''),
                          NULLIF(SUBSTRING_INDEX(p.`CODIGO_ALM`, CHAR(31 USING utf8mb4), -1), ''),
                          '(sin proveedor)'))
            WHEN 'FAM' THEN CONCAT('Familia: ',
                 COALESCE(fg.`DESC_GRP`, fg.`COD_GRP`,
                          art.`CODIGO_FAM_ART`))
            WHEN 'TMP' THEN CONCAT('Temporada: ',
                 COALESCE(NULLIF(tmp.`TEMPORADA`, ''), '(sin temporada)'))
            WHEN 'ALM' THEN CONCAT('Almacén: ',
                 COALESCE(NULLIF(alm.`NOMBRE_ALM_ALM`, ''), SUBSTRING_INDEX(p.`CODIGO_ALM`, CHAR(31 USING utf8mb4), 1),
                          '(sin almacén)'))
            ELSE ''
        END                                           AS `GRUPO2_ETIQ`,
        CASE p_NIVEL3
            WHEN 'PRV' THEN IF(v_por_prv, SUBSTRING_INDEX(p.`CODIGO_ALM`, CHAR(31 USING utf8mb4), -1), COALESCE(prov.`CODIGO_PRV`, ''))
            WHEN 'FAM' THEN COALESCE(fg.`COD_GRP`, art.`CODIGO_FAM_ART`)
            WHEN 'TMP' THEN COALESCE(tmp.`TEMPORADA`, '')
            WHEN 'ALM' THEN SUBSTRING_INDEX(p.`CODIGO_ALM`, CHAR(31 USING utf8mb4), 1)
            ELSE ''
        END                                           AS `GRUPO3_COD`,
        CASE p_NIVEL3
            WHEN 'PRV' THEN CONCAT('Proveedor: ',
                 COALESCE(NULLIF(gprv.`RAZON_SOCIAL_PRV`, ''),
                          NULLIF(SUBSTRING_INDEX(p.`CODIGO_ALM`, CHAR(31 USING utf8mb4), -1), ''),
                          '(sin proveedor)'))
            WHEN 'FAM' THEN CONCAT('Familia: ',
                 COALESCE(fg.`DESC_GRP`, fg.`COD_GRP`,
                          art.`CODIGO_FAM_ART`))
            WHEN 'TMP' THEN CONCAT('Temporada: ',
                 COALESCE(NULLIF(tmp.`TEMPORADA`, ''), '(sin temporada)'))
            WHEN 'ALM' THEN CONCAT('Almacén: ',
                 COALESCE(NULLIF(alm.`NOMBRE_ALM_ALM`, ''), SUBSTRING_INDEX(p.`CODIGO_ALM`, CHAR(31 USING utf8mb4), 1),
                          '(sin almacén)'))
            ELSE ''
        END                                           AS `GRUPO3_ETIQ`
      FROM (
            SELECT m.`CODIGO_ART`, m.`CODIGO_ALM`, m.`COLOR`,
                   MIN(m.`COLOR_HEX`) AS `COLOR_HEX`,
                   MIN(m.`ORDEN_COLOR`) AS `ORDEN_COLOR`,
                   m.`BANDA`, m.`ORDEN_BANDA`, m.`ETIQUETA_BANDA`, m.`ES_COSTE`,
                   SUM(m.`CANTIDAD`) AS `CANTIDAD`
              FROM `tmp_bst_medidas` m
             GROUP BY m.`CODIGO_ART`, m.`CODIGO_ALM`, m.`COLOR`, m.`BANDA`,
                      m.`ORDEN_BANDA`, m.`ETIQUETA_BANDA`, m.`ES_COSTE`
           ) p
      JOIN `fza_articulos` art ON art.`CODIGO_ART_ART` = p.`CODIGO_ART`
      LEFT JOIN `fza_articulos_familias` fam
        ON fam.`CODIGO_FAM_FAM` = art.`CODIGO_FAM_ART`
      LEFT JOIN `tmp_bst_fam_grp` fg ON fg.`CODIGO_FAM` = art.`CODIGO_FAM_ART`
      LEFT JOIN `fza_almacenes` alm ON alm.`CODIGO_ALM_ALM` = SUBSTRING_INDEX(p.`CODIGO_ALM`, CHAR(31 USING utf8mb4), 1)
      
      LEFT JOIN `fza_proveedores` gprv
        ON v_por_prv AND gprv.`CODIGO_PRV_PRV` = SUBSTRING_INDEX(p.`CODIGO_ALM`, CHAR(31 USING utf8mb4), -1)
      LEFT JOIN `tmp_bst_pvp` pvp ON pvp.`CODIGO_ART` = p.`CODIGO_ART`
                           AND pvp.`COLOR` = p.`COLOR`
      LEFT JOIN `tmp_bst_cst` cst ON cst.`CODIGO_ART` = p.`CODIGO_ART`
       
       AND cst.`COLOR` = p.`COLOR`
       AND cst.`CODIGO_ALM` =
         SUBSTRING_INDEX(p.`CODIGO_ALM`, CHAR(31 USING utf8mb4), 1)
      LEFT JOIN `tmp_bst_prov` prov ON prov.`CODIGO_ART` = p.`CODIGO_ART`




      LEFT JOIN `tmp_bst_tmp` tmp ON tmp.`CODIGO_ART` = p.`CODIGO_ART`
                AND tmp.`COLOR` = p.`COLOR`
      LEFT JOIN `tmp_bst_vt` vt ON vt.`CODIGO_ART` = p.`CODIGO_ART`
               AND vt.`CODIGO_ALM` = p.`CODIGO_ALM`
               AND vt.`COLOR` = p.`COLOR`
      LEFT JOIN `tmp_bst_nc` nc ON nc.`CODIGO_ART` = p.`CODIGO_ART`
               AND nc.`COLOR` = p.`COLOR`
     ORDER BY `GRUPO1_COD`, `GRUPO2_COD`, `GRUPO3_COD`,
              COALESCE(fam.`ORDEN_FAM`, 999999), art.`CODIGO_FAM_ART`,
              p.`CODIGO_ART`, p.`ORDEN_COLOR`, p.`COLOR`, p.`ORDEN_BANDA`;


    DROP TEMPORARY TABLE IF EXISTS `tmp_bst_pvp`;
    DROP TEMPORARY TABLE IF EXISTS `tmp_bst_cst`;
    DROP TEMPORARY TABLE IF EXISTS `tmp_bst_prov`;
    DROP TEMPORARY TABLE IF EXISTS `tmp_bst_tmp`;
    DROP TEMPORARY TABLE IF EXISTS `tmp_bst_vt`;
    DROP TEMPORARY TABLE IF EXISTS `tmp_bst_fal`;
    DROP TEMPORARY TABLE IF EXISTS `tmp_bst_medidas`;
    DROP TEMPORARY TABLE IF EXISTS `tmp_bst_marcas`;
    DROP TEMPORARY TABLE IF EXISTS `tmp_bst_ven`;
    DROP TEMPORARY TABLE IF EXISTS `tmp_bst_base`;
    DROP TEMPORARY TABLE IF EXISTS `tmp_bst_nc`;
    DROP TEMPORARY TABLE IF EXISTS `tmp_bst_sku`;
    DROP TEMPORARY TABLE IF EXISTS `tmp_bst_arts`;
    DROP TEMPORARY TABLE IF EXISTS `tmp_bst_fam_grp`;
    DROP TEMPORARY TABLE IF EXISTS `tmp_bst_fam`;
    DROP TEMPORARY TABLE IF EXISTS `tmp_bst_alm`;
    DROP TEMPORARY TABLE IF EXISTS tmp_bst_alm_factura;
END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `PRC_GET_BALANCE_ALMACEN_TALLAS` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_spanish_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_GET_BALANCE_ALMACEN_TALLAS`(
  IN p_MODO varchar(1),
  IN p_DESDE date,
  IN p_HASTA date,
  IN p_ALMACENES text,
  IN p_FAMILIAS text,
  IN p_PROVEEDORES text,
  IN p_TEMPORADAS text,
  IN p_ARTICULOS text,
  IN p_COD_TARIFA varchar(20),
  IN p_DESGLOSADO varchar(1),
  IN p_BANDAS text,
  IN p_NIVEL1 varchar(3),
  IN p_NIVEL2 varchar(3),
  IN p_NIVEL3 varchar(3),
  IN p_NIVEL_FAM int(11)
)
BEGIN
    DECLARE v_alms      TEXT;
    DECLARE v_tarifa    VARCHAR(20);
    DECLARE v_desde     DATE;
    DECLARE v_hasta     DATE;
    DECLARE v_por_alm   BOOLEAN DEFAULT FALSE;
    
    DECLARE v_por_prv    BOOLEAN DEFAULT FALSE;


    DECLARE v_desglosado BOOLEAN DEFAULT FALSE;
    DECLARE v_nivel_fam INT;

    SET p_MODO       = IFNULL(NULLIF(p_MODO, ''), 'A');
    SET p_DESGLOSADO  = IFNULL(NULLIF(p_DESGLOSADO, ''), 'N');
    SET v_desglosado  = (p_MODO = 'F' AND p_DESGLOSADO = 'S');
    SET p_FAMILIAS    = IFNULL(p_FAMILIAS, '');
    SET p_PROVEEDORES = IFNULL(p_PROVEEDORES, '');
    SET p_TEMPORADAS  = IFNULL(p_TEMPORADAS, '');
    SET p_ARTICULOS   = IFNULL(p_ARTICULOS, '');
    SET p_BANDAS      = IFNULL(p_BANDAS, '');



    SET p_NIVEL1      = UPPER(IFNULL(p_NIVEL1, ''));
    SET p_NIVEL2      = UPPER(IFNULL(p_NIVEL2, ''));
    SET p_NIVEL3      = UPPER(IFNULL(p_NIVEL3, ''));


    SET v_por_alm     = (p_NIVEL1 = 'ALM' OR p_NIVEL2 = 'ALM' OR p_NIVEL3 = 'ALM');
    SET v_por_prv     = (p_NIVEL1 = 'PRV' OR p_NIVEL2 = 'PRV' OR p_NIVEL3 = 'PRV');


    SET v_nivel_fam   = IF(IFNULL(p_NIVEL_FAM, 0) < 1, 9999, p_NIVEL_FAM);
    SET v_tarifa      = IFNULL(NULLIF(p_COD_TARIFA, ''), 'PVP');
    SET v_desde      = IFNULL(p_DESDE, '1900-01-01');
    SET v_hasta      = IFNULL(p_HASTA, CURRENT_DATE);


    IF p_MODO = 'A' THEN
        SET v_desde = '1000-01-01';
        SET v_hasta = '9999-12-31';
    END IF;





    DROP TEMPORARY TABLE IF EXISTS `tmp_bat_alm`;
    CREATE TEMPORARY TABLE `tmp_bat_alm` (
        `CODIGO_ALM` VARCHAR(20) NOT NULL PRIMARY KEY
    );
    INSERT IGNORE INTO `tmp_bat_alm` (`CODIGO_ALM`)
    SELECT `CODIGO_ALM_ALM` FROM `fza_almacenes`
     WHERE IF(IFNULL(p_ALMACENES, '') = '',
              `ESACTIVO_ALM` = 'S',
              FIND_IN_SET(`CODIGO_ALM_ALM`, p_ALMACENES));








    DROP TEMPORARY TABLE IF EXISTS `tmp_bat_fam`;
    CREATE TEMPORARY TABLE `tmp_bat_fam` (
        `CODIGO_FAM` VARCHAR(20) NOT NULL PRIMARY KEY
    );
    INSERT IGNORE INTO `tmp_bat_fam` (`CODIGO_FAM`)
    WITH RECURSIVE `fam_tree` AS (
        SELECT `CODIGO_FAM_FAM`
          FROM `fza_articulos_familias`
         WHERE FIND_IN_SET(`CODIGO_FAM_FAM`, p_FAMILIAS)
        UNION ALL
        SELECT f.`CODIGO_FAM_FAM`
          FROM `fza_articulos_familias` f
          JOIN `fam_tree` t ON f.`CODIGO_PADRE_FAM` = t.`CODIGO_FAM_FAM`
    )
    SELECT DISTINCT `CODIGO_FAM_FAM` FROM `fam_tree`;





    DROP TEMPORARY TABLE IF EXISTS `tmp_bat_fam_grp`;
    CREATE TEMPORARY TABLE `tmp_bat_fam_grp` (
        `CODIGO_FAM` VARCHAR(20)  NOT NULL PRIMARY KEY,
        `COD_GRP`    VARCHAR(20)  NOT NULL,
        `DESC_GRP`   VARCHAR(200) NULL
    );
    INSERT IGNORE INTO `tmp_bat_fam_grp` (`CODIGO_FAM`, `COD_GRP`, `DESC_GRP`)
    WITH RECURSIVE `fam_path` AS (
        SELECT `CODIGO_FAM_FAM` AS `COD`,
               CAST(`CODIGO_FAM_FAM` AS CHAR(1000)) AS `RUTA`
          FROM `fza_articulos_familias`
         WHERE `CODIGO_PADRE_FAM` IS NULL OR `CODIGO_PADRE_FAM` = ''
        UNION ALL
        SELECT f.`CODIGO_FAM_FAM`,
               CONCAT(pa.`RUTA`, '>', f.`CODIGO_FAM_FAM`)
          FROM `fza_articulos_familias` f
          JOIN `fam_path` pa ON f.`CODIGO_PADRE_FAM` = pa.`COD`
    )
    SELECT pa.`COD`,
           SUBSTRING_INDEX(SUBSTRING_INDEX(pa.`RUTA`, '>', v_nivel_fam), '>', -1),
           NULL
      FROM `fam_path` pa;

    UPDATE `tmp_bat_fam_grp` g
      JOIN `fza_articulos_familias` f ON f.`CODIGO_FAM_FAM` = g.`COD_GRP`
       SET g.`DESC_GRP` = COALESCE(f.`DESCRIPCION_FAM`, f.`NOMBRE_FAM_FAM`,
                                   g.`COD_GRP`);

    DROP TEMPORARY TABLE IF EXISTS `tmp_bat_arts`;
    CREATE TEMPORARY TABLE `tmp_bat_arts` (
        `CODIGO_ART` VARCHAR(20) NOT NULL PRIMARY KEY
    );
    INSERT IGNORE INTO `tmp_bat_arts` (`CODIGO_ART`)
    SELECT a.`CODIGO_ART_ART`
      FROM `fza_articulos` a
     WHERE a.`ESACTIVO_ART` = 'S'
       AND (p_ARTICULOS = ''
            OR FIND_IN_SET(a.`CODIGO_ART_ART`, p_ARTICULOS))
       AND (p_FAMILIAS = ''
            OR a.`CODIGO_FAM_ART` IN (SELECT `CODIGO_FAM` FROM `tmp_bat_fam`))
       AND (p_PROVEEDORES = ''
            OR EXISTS (SELECT 1 FROM `fza_articulos_proveedores` ap
                        WHERE ap.`CODIGO_ART_AP` = a.`CODIGO_ART_ART`
                          AND FIND_IN_SET(ap.`CODIGO_PRV_AP`, p_PROVEEDORES)) OR EXISTS (SELECT 1 FROM fza_articulos_lotes LFA JOIN fza_articulos_skus SFA ON SFA.CODIGO_UNIDAD_SKU = LFA.CODIGO_UNIDAD_LOT WHERE SFA.CODIGO_ART_SKU = a.CODIGO_ART_ART AND FIND_IN_SET(LFA.CODIGO_PRV_LOT, p_PROVEEDORES) > 0))
       AND (p_TEMPORADAS = ''
            OR EXISTS (SELECT 1 FROM `fza_articulos_propiedades` tp
                        LEFT JOIN `fza_propiedades_valores` tpv
                          ON tpv.`ID_PV_ARTPROP` = tp.`ID_PV_ARTPROP`
                        WHERE tp.`CODIGO_ART_ART` = a.`CODIGO_ART_ART`
                          AND tp.`CODIGO_PROP_ARTPROP` = 'TEMPORADA'
                          AND FIND_IN_SET(
                                COALESCE(tpv.`PV`, tp.`VALOR_LIBRE_ARTPROP`),
                                p_TEMPORADAS)));







    DROP TEMPORARY TABLE IF EXISTS `tmp_bat_pos`;
    CREATE TEMPORARY TABLE `tmp_bat_pos` (
        `CODIGO_ART` VARCHAR(20)  NOT NULL,
        `ID_AV`      INT          NOT NULL,
        `ETIQ`       VARCHAR(100) NULL,
        `POSICION`   INT          NOT NULL,
        PRIMARY KEY (`CODIGO_ART`, `ID_AV`)
    );

    INSERT IGNORE INTO `tmp_bat_pos` (`CODIGO_ART`, `ID_AV`, `ETIQ`, `POSICION`)
    SELECT asg.`CODIGO_ART`, acd.`ID_AV_ACD`, av.`AV`,
           ROW_NUMBER() OVER (PARTITION BY asg.`CODIGO_ART`
                              ORDER BY acd.`ORDEN_ACD`, acd.`ID_AV_ACD`)
      FROM (SELECT a.`CODIGO_ART_ART` AS `CODIGO_ART`,
                   MIN(asa.`ID_AC_ACA`) AS `ID_AC`
              FROM `fza_articulos` a
              JOIN `fza_articulos_conjuntos_asign` asa
                ON asa.`CODIGO_ART_ACA` = a.`CODIGO_ART_ART`
               AND asa.`ID_VA_ACA` = (SELECT EJ452.ID_ATB_VA FROM VI_VARIACIONES_EJES EJ452 WHERE EJ452.ID_VAR_VA = a.TIPO_VARIACION_ART AND EJ452.EJE_VA = 'P')
             WHERE a.`ESACTIVO_ART` = 'S'
               AND a.`CODIGO_ART_ART` IN (SELECT `CODIGO_ART` FROM `tmp_bat_arts`)
             GROUP BY a.`CODIGO_ART_ART`) asg
      JOIN `fza_atributos_conjuntos_det` acd ON acd.`ID_AC_ACD` = asg.`ID_AC`
      JOIN `fza_atributos_valores` av ON av.`ID_AV` = acd.`ID_AV_ACD`;


    DROP TEMPORARY TABLE IF EXISTS `tmp_bat_pos_arts`;
    CREATE TEMPORARY TABLE `tmp_bat_pos_arts` (
        `CODIGO_ART` VARCHAR(20) NOT NULL PRIMARY KEY
    );
    INSERT IGNORE INTO `tmp_bat_pos_arts`
    SELECT DISTINCT `CODIGO_ART` FROM `tmp_bat_pos`;

    INSERT IGNORE INTO `tmp_bat_pos` (`CODIGO_ART`, `ID_AV`, `ETIQ`, `POSICION`)
    SELECT x.`CODIGO_ART`, x.`ID_AV`, x.`AV`,
           ROW_NUMBER() OVER (PARTITION BY x.`CODIGO_ART`
                              ORDER BY x.`ORDEN_AV`, x.`AV`)
      FROM (SELECT DISTINCT a.`CODIGO_ART_ART` AS `CODIGO_ART`,
                   av.`ID_AV`, av.`AV`, COALESCE(av.`ORDEN_AV`, 0) AS `ORDEN_AV`
              FROM `fza_articulos` a
              JOIN `fza_articulos_skus` sku
                ON sku.`CODIGO_ART_SKU` = a.`CODIGO_ART_ART`
              JOIN `fza_atributos_sku` sa
                ON sa.`CODIGO_UNIDAD_SKU_SA` = sku.`CODIGO_UNIDAD_SKU`
              JOIN `fza_atributos_valores` av
                ON av.`ID_AV` = sa.`ID_AV_SA` AND av.`ID_VA_AV` = (SELECT EJ452.ID_ATB_VA FROM VI_VARIACIONES_EJES EJ452 WHERE EJ452.ID_VAR_VA = sku.CODIGO_VAR_SKU AND EJ452.EJE_VA = 'P')
             WHERE a.`ESACTIVO_ART` = 'S'
               AND a.`CODIGO_ART_ART` IN (SELECT `CODIGO_ART` FROM `tmp_bat_arts`)
               AND a.`CODIGO_ART_ART` NOT IN
                   (SELECT `CODIGO_ART` FROM `tmp_bat_pos_arts`)) x;

    
    INSERT IGNORE INTO `tmp_bat_pos`
      (`CODIGO_ART`, `ID_AV`, `ETIQ`, `POSICION`)
    SELECT A.CODIGO_ART_ART, 0, '-', COALESCE(MAX(P.POSICION), 0) + 1
      FROM fza_articulos A
      LEFT JOIN tmp_bat_pos P ON P.CODIGO_ART = A.CODIGO_ART_ART
     WHERE A.CODIGO_ART_ART IN (SELECT CODIGO_ART FROM tmp_bat_arts)
       AND EXISTS (SELECT 1 FROM fza_articulos_skus S
         WHERE S.CODIGO_ART_SKU = A.CODIGO_ART_ART
           AND NOT EXISTS (SELECT 1 FROM fza_atributos_sku SA
             JOIN fza_atributos_valores AV ON AV.ID_AV = SA.ID_AV_SA
             JOIN VI_VARIACIONES_EJES E ON E.ID_ATB_VA = AV.ID_VA_AV
               AND E.ID_VAR_VA = S.CODIGO_VAR_SKU AND E.EJE_VA = 'P'
             WHERE SA.CODIGO_UNIDAD_SKU_SA = S.CODIGO_UNIDAD_SKU))
     GROUP BY A.CODIGO_ART_ART;

    DROP TEMPORARY TABLE IF EXISTS `tmp_bat_etiq`;
    CREATE TEMPORARY TABLE `tmp_bat_etiq` AS
    SELECT `CODIGO_ART`, (`POSICION` - 1) DIV 14 + 1 AS `BLOQUE_TALLAS`,
           MAX(CASE WHEN MOD(`POSICION` - 1, 14) + 1 =  1 THEN `ETIQ` END) AS `ETIQ_T01`,
           MAX(CASE WHEN MOD(`POSICION` - 1, 14) + 1 =  2 THEN `ETIQ` END) AS `ETIQ_T02`,
           MAX(CASE WHEN MOD(`POSICION` - 1, 14) + 1 =  3 THEN `ETIQ` END) AS `ETIQ_T03`,
           MAX(CASE WHEN MOD(`POSICION` - 1, 14) + 1 =  4 THEN `ETIQ` END) AS `ETIQ_T04`,
           MAX(CASE WHEN MOD(`POSICION` - 1, 14) + 1 =  5 THEN `ETIQ` END) AS `ETIQ_T05`,
           MAX(CASE WHEN MOD(`POSICION` - 1, 14) + 1 =  6 THEN `ETIQ` END) AS `ETIQ_T06`,
           MAX(CASE WHEN MOD(`POSICION` - 1, 14) + 1 =  7 THEN `ETIQ` END) AS `ETIQ_T07`,
           MAX(CASE WHEN MOD(`POSICION` - 1, 14) + 1 =  8 THEN `ETIQ` END) AS `ETIQ_T08`,
           MAX(CASE WHEN MOD(`POSICION` - 1, 14) + 1 =  9 THEN `ETIQ` END) AS `ETIQ_T09`,
           MAX(CASE WHEN MOD(`POSICION` - 1, 14) + 1 = 10 THEN `ETIQ` END) AS `ETIQ_T10`,
           MAX(CASE WHEN MOD(`POSICION` - 1, 14) + 1 = 11 THEN `ETIQ` END) AS `ETIQ_T11`,
           MAX(CASE WHEN MOD(`POSICION` - 1, 14) + 1 = 12 THEN `ETIQ` END) AS `ETIQ_T12`,
           MAX(CASE WHEN MOD(`POSICION` - 1, 14) + 1 = 13 THEN `ETIQ` END) AS `ETIQ_T13`,
           MAX(CASE WHEN MOD(`POSICION` - 1, 14) + 1 = 14 THEN `ETIQ` END) AS `ETIQ_T14`
      FROM `tmp_bat_pos`
     GROUP BY `CODIGO_ART`, (`POSICION` - 1) DIV 14 + 1;
    ALTER TABLE `tmp_bat_etiq` ADD PRIMARY KEY (`CODIGO_ART`, `BLOQUE_TALLAS`);




    DROP TEMPORARY TABLE IF EXISTS `tmp_bat_sku`;
    CREATE TEMPORARY TABLE `tmp_bat_sku` (
        `CODIGO_UNIDAD` VARCHAR(50)  NOT NULL PRIMARY KEY,
        `CODIGO_ART`    VARCHAR(20)  NOT NULL,
        `CLAVE_FILA`         VARCHAR(600) NOT NULL DEFAULT '',
        `COLOR_HEX`     VARCHAR(7)   NULL,
        `ORDEN_COLOR`   INT          NOT NULL DEFAULT 0,
        `POSICION`      INT          NOT NULL,
        KEY `IDX_BAT_SKU_ART` (`CODIGO_ART`)
    );
    INSERT IGNORE INTO `tmp_bat_sku`
    SELECT sku.`CODIGO_UNIDAD_SKU`, sku.`CODIGO_ART_SKU`,
           JSON_ARRAY(COALESCE(co.`AV`, ''), COALESCE(pe.`ID_AV`, 0),
                      COALESCE(pe.`AV`, ''), COALESCE(pe.`ORDEN_AV`, 0)),
           COALESCE(atb.`HEX_ATB`, ''),
           COALESCE(co.`ORDEN_AV`, 0), p.`POSICION`
      FROM `fza_articulos_skus` sku
      JOIN `fza_articulos` a
        ON a.`CODIGO_ART_ART` = sku.`CODIGO_ART_SKU`
       AND a.`ESACTIVO_ART` = 'S'
      LEFT JOIN `fza_atributos_sku` sat
        ON sat.`CODIGO_UNIDAD_SKU_SA` = sku.`CODIGO_UNIDAD_SKU`
       AND sat.ID_AV_SA IN (SELECT AV.ID_AV FROM fza_atributos_valores AV
         JOIN VI_VARIACIONES_EJES E ON E.ID_ATB_VA = AV.ID_VA_AV
           AND E.ID_VAR_VA = sku.CODIGO_VAR_SKU AND E.EJE_VA = 'P')
      LEFT JOIN `fza_atributos_valores` ta
        ON ta.`ID_AV` = sat.`ID_AV_SA` AND ta.`ID_VA_AV` = (SELECT EJ452.ID_ATB_VA FROM VI_VARIACIONES_EJES EJ452 WHERE EJ452.ID_VAR_VA = sku.CODIGO_VAR_SKU AND EJ452.EJE_VA = 'P')
      JOIN `tmp_bat_pos` p
        ON p.`CODIGO_ART` = sku.`CODIGO_ART_SKU` AND p.`ID_AV` = COALESCE(ta.`ID_AV`, 0)





      LEFT JOIN `fza_atributos_sku` sac
        ON sac.`CODIGO_UNIDAD_SKU_SA` = sku.`CODIGO_UNIDAD_SKU`
       AND sac.`ID_AV_SA` IN (SELECT `ID_AV` FROM `fza_atributos_valores`
                               WHERE `ID_VA_AV` = (SELECT EJ452.ID_ATB_VA FROM VI_VARIACIONES_EJES EJ452 WHERE EJ452.ID_VAR_VA = (SELECT SK452.CODIGO_VAR_SKU FROM fza_articulos_skus SK452 WHERE SK452.CODIGO_UNIDAD_SKU = sac.CODIGO_UNIDAD_SKU_SA) AND EJ452.EJE_VA = 'F'))
      LEFT JOIN `fza_atributos_valores` co
        ON co.`ID_AV` = sac.`ID_AV_SA` AND co.`ID_VA_AV` = (SELECT EJ452.ID_ATB_VA FROM VI_VARIACIONES_EJES EJ452 WHERE EJ452.ID_VAR_VA = (SELECT SK452.CODIGO_VAR_SKU FROM fza_articulos_skus SK452 WHERE SK452.CODIGO_UNIDAD_SKU = sac.CODIGO_UNIDAD_SKU_SA) AND EJ452.EJE_VA = 'F')

      LEFT JOIN `VI_VARIACIONES_EJES` es
        ON es.`ID_VAR_VA` = sku.`CODIGO_VAR_SKU` AND es.`EJE_VA` = 'S'
      LEFT JOIN `fza_atributos_sku` sap
        ON sap.`CODIGO_UNIDAD_SKU_SA` = sku.`CODIGO_UNIDAD_SKU`
       AND sap.`ID_AV_SA` IN
           (SELECT `ID_AV` FROM `fza_atributos_valores`
             WHERE `ID_VA_AV` = es.`ID_ATB_VA`)
      LEFT JOIN `fza_atributos_valores` pe ON pe.`ID_AV` = sap.`ID_AV_SA`
      LEFT JOIN `fza_atributos_basicos` atb ON atb.`ID_ATB` = co.`ID_ATB_AV`;








    DROP TEMPORARY TABLE IF EXISTS `tmp_bat_base`;
    CREATE TEMPORARY TABLE `tmp_bat_base` (
        `CODIGO_ART`     VARCHAR(20)  NOT NULL,
        `CODIGO_ALM`     VARCHAR(50)  NOT NULL DEFAULT '',
        `CLAVE_FILA`          VARCHAR(600) NOT NULL DEFAULT '',
        `COLOR_HEX`      VARCHAR(7)   NULL,
        `ORDEN_COLOR`    INT          NOT NULL DEFAULT 0,
        `POSICION`       INT          NOT NULL,
        `EXI_INI`        DECIMAL(19,6) NOT NULL DEFAULT 0,
        `EXI_FIN`        DECIMAL(19,6) NOT NULL DEFAULT 0,

        `ENT_COMPRA`     DECIMAL(19,6) NOT NULL DEFAULT 0,
        `ENT_ALBENTRADA` DECIMAL(19,6) NOT NULL DEFAULT 0,
        `ENT_TRASPASO`   DECIMAL(19,6) NOT NULL DEFAULT 0,
        `ENT_DEPOSITO`   DECIMAL(19,6) NOT NULL DEFAULT 0,
        `ENT_REGULAR`    DECIMAL(19,6) NOT NULL DEFAULT 0,
        `ENT_DEVPRV`     DECIMAL(19,6) NOT NULL DEFAULT 0,
        `ENT_OTROS`      DECIMAL(19,6) NOT NULL DEFAULT 0,

        `SAL_ALBVENTA`   DECIMAL(19,6) NOT NULL DEFAULT 0,
        `SAL_VENTA`      DECIMAL(19,6) NOT NULL DEFAULT 0,

        `VEN_FAC`        DECIMAL(19,6) NOT NULL DEFAULT 0,
        `SAL_VENTA_DEP`  DECIMAL(19,6) NOT NULL DEFAULT 0,


        `NUM_MOVS`       INT           NOT NULL DEFAULT 0,
        PRIMARY KEY (`CODIGO_ART`, `CODIGO_ALM`, `POSICION`, `CLAVE_FILA`)
    );
    INSERT INTO `tmp_bat_base`
        (`CODIGO_ART`, `CODIGO_ALM`, `CLAVE_FILA`, `COLOR_HEX`, `ORDEN_COLOR`,
         `POSICION`, `EXI_INI`, `EXI_FIN`,
         `ENT_COMPRA`, `ENT_ALBENTRADA`, `ENT_TRASPASO`, `ENT_DEPOSITO`,
         `ENT_REGULAR`, `ENT_DEVPRV`, `ENT_OTROS`,
         `SAL_ALBVENTA`, `SAL_VENTA`, `NUM_MOVS`)
    SELECT s.`CODIGO_ART`, COALESCE(mv.`ALM`, ''),
           s.`CLAVE_FILA`, MIN(s.`COLOR_HEX`),
           MIN(s.`ORDEN_COLOR`), s.`POSICION`,



           SUM(COALESCE(mv.`STOCK_NOW`, 0) - COALESCE(mv.`DELTA_DESDE`, 0)),


           SUM(COALESCE(mv.`STOCK_NOW`, 0) - COALESCE(mv.`DELTA_HASTA`, 0)),
           SUM(COALESCE(mv.`ENT_COMPRA`, 0)), SUM(COALESCE(mv.`ENT_ALBENTRADA`, 0)),
           SUM(COALESCE(mv.`ENT_TRASPASO`, 0)), SUM(COALESCE(mv.`ENT_DEPOSITO`, 0)),
           SUM(COALESCE(mv.`ENT_REGULAR`, 0)), SUM(COALESCE(mv.`ENT_DEVPRV`, 0)),
           SUM(COALESCE(mv.`ENT_OTROS`, 0)),
           SUM(COALESCE(mv.`SAL_ALBVENTA`, 0)), SUM(COALESCE(mv.`SAL_VENTA`, 0)),
           SUM(COALESCE(mv.`NUM_MOVS`, 0))
      FROM `tmp_bat_sku` s
      LEFT JOIN (



            SELECT u.`CODIGO_UNIDAD`, u.`ALM`,
                   SUM(u.`STOCK_NOW`)                       AS `STOCK_NOW`,
                   SUM(IF(u.`EN_PERIODO` AND u.`TIPO` IN ('AC', 'AB', 'FP'),
                          u.`NETO`, 0))                     AS `ENT_COMPRA`,
                   SUM(IF(u.`EN_PERIODO` AND u.`TIPO` = 'AE',
                          u.`NETO`, 0))                     AS `ENT_ALBENTRADA`,
                   SUM(IF(u.`EN_PERIODO` AND u.`TIPO` IN ('TR', 'AT', 'TA'),
                          u.`NETO`, 0))                     AS `ENT_TRASPASO`,
                   SUM(IF(u.`EN_PERIODO` AND u.`TIPO` = 'DP',
                          u.`NETO`, 0))                     AS `ENT_DEPOSITO`,
                   SUM(IF(u.`EN_PERIODO` AND u.`TIPO` = 'IN',
                          u.`NETO`, 0))                     AS `ENT_REGULAR`,
                   SUM(IF(u.`EN_PERIODO` AND u.`TIPO` = 'DC',
                          u.`NETO`, 0))                     AS `ENT_DEVPRV`,
                   SUM(IF(u.`EN_PERIODO` AND u.`TIPO` NOT IN
                          ('AC', 'AB', 'FP', 'AE', 'TR', 'AT', 'TA', 'DP', 'IN',
                           'DC', 'AV', 'VE', 'FC'),
                          u.`NETO`, 0))                     AS `ENT_OTROS`,
                   SUM(IF(u.`EN_PERIODO` AND u.`TIPO` = 'AV',
                          -u.`NETO`, 0))                    AS `SAL_ALBVENTA`,
                   SUM(IF(u.`EN_PERIODO` AND u.`TIPO` IN ('VE', 'FC'),
                          -u.`NETO`, 0))                    AS `SAL_VENTA`,
                   SUM(IF(u.`FECHA` >= v_desde, u.`NETO`, 0)) AS `DELTA_DESDE`,
                   SUM(IF(u.`FECHA` > v_hasta, u.`NETO`, 0))  AS `DELTA_HASTA`,
                   SUM(u.`EN_PERIODO`)                      AS `NUM_MOVS`
              FROM (
                    SELECT st2.`CODIGO_UNIDAD_STK` AS `CODIGO_UNIDAD`,
                           CONCAT(IF(v_por_alm, st2.`CODIGO_ALM_STK`, ''), IF(v_por_prv, CONCAT(CHAR(31 USING utf8mb4), COALESCE((SELECT NULLIF(NULLIF(TRIM(LG.CODIGO_PRV_LOT), ''), '0') FROM fza_articulos_lotes LG WHERE LG.CODIGO_UNIDAD_LOT = st2.CODIGO_UNIDAD_STK AND LG.LOTE_LOT = st2.LOTE_STK LIMIT 1), IF(p_PROVEEDORES = '', (SELECT MAX(AG.CODIGO_PRV_AP) FROM fza_articulos_proveedores AG WHERE AG.CODIGO_ART_AP = (SELECT SG.CODIGO_ART_SKU FROM fza_articulos_skus SG WHERE SG.CODIGO_UNIDAD_SKU = st2.CODIGO_UNIDAD_STK) AND AG.ESPROVEEDORPRINCIPAL_AP = 'S'), (SELECT AG.CODIGO_PRV_AP FROM fza_articulos_proveedores AG WHERE AG.CODIGO_ART_AP = (SELECT SG.CODIGO_ART_SKU FROM fza_articulos_skus SG WHERE SG.CODIGO_UNIDAD_SKU = st2.CODIGO_UNIDAD_STK) AND FIND_IN_SET(AG.CODIGO_PRV_AP, p_PROVEEDORES) > 0 ORDER BY AG.ESPROVEEDORPRINCIPAL_AP = 'S' DESC, AG.CODIGO_PRV_AP LIMIT 1)), '')), '')) AS `ALM`,
                           st2.`CANTIDAD_STK` AS `STOCK_NOW`,
                           '' AS `TIPO`, NULL AS `FECHA`,
                           FALSE AS `EN_PERIODO`, 0 AS `NETO`
                      FROM `fza_articulos_stockactual` st2
                     WHERE
       (p_PROVEEDORES = '' OR EXISTS (
         SELECT 1 FROM fza_articulos_lotes LP
          WHERE LP.CODIGO_UNIDAD_LOT = st2.CODIGO_UNIDAD_STK
            AND LP.LOTE_LOT = st2.LOTE_STK
            AND COALESCE(TRIM(LP.CODIGO_PRV_LOT), '') NOT IN ('', '0')
            AND FIND_IN_SET(LP.CODIGO_PRV_LOT, p_PROVEEDORES) > 0)
        OR (NOT EXISTS (
         SELECT 1 FROM fza_articulos_lotes LP
          WHERE LP.CODIGO_UNIDAD_LOT = st2.CODIGO_UNIDAD_STK
            AND LP.LOTE_LOT = st2.LOTE_STK
            AND COALESCE(TRIM(LP.CODIGO_PRV_LOT), '') NOT IN ('', '0')) AND EXISTS (
         SELECT 1 FROM fza_articulos_proveedores APF
          WHERE APF.CODIGO_ART_AP = (SELECT SF.CODIGO_ART_SKU FROM fza_articulos_skus SF WHERE SF.CODIGO_UNIDAD_SKU = st2.CODIGO_UNIDAD_STK)
            AND FIND_IN_SET(APF.CODIGO_PRV_AP, p_PROVEEDORES) > 0))) AND st2.`CODIGO_ALM_STK` IN (SELECT `CODIGO_ALM` FROM `tmp_bat_alm`)


                       AND st2.`CODIGO_UNIDAD_STK` IN
                           (SELECT `CODIGO_UNIDAD` FROM `tmp_bat_sku`)
                    UNION ALL
                    SELECT m.`CODIGO_UNIDAD_MOV`,
                           CONCAT(IF(v_por_alm, m.`CODIGO_ALM_MOV`, ''), IF(v_por_prv, CONCAT(CHAR(31 USING utf8mb4), COALESCE((SELECT NULLIF(NULLIF(TRIM(LG.CODIGO_PRV_LOT), ''), '0') FROM fza_articulos_lotes LG WHERE LG.CODIGO_UNIDAD_LOT = m.CODIGO_UNIDAD_MOV AND LG.LOTE_LOT = m.LOTE_MOV LIMIT 1), IF(p_PROVEEDORES = '', (SELECT MAX(AG.CODIGO_PRV_AP) FROM fza_articulos_proveedores AG WHERE AG.CODIGO_ART_AP = m.CODIGO_ART_MOV AND AG.ESPROVEEDORPRINCIPAL_AP = 'S'), (SELECT AG.CODIGO_PRV_AP FROM fza_articulos_proveedores AG WHERE AG.CODIGO_ART_AP = m.CODIGO_ART_MOV AND FIND_IN_SET(AG.CODIGO_PRV_AP, p_PROVEEDORES) > 0 ORDER BY AG.ESPROVEEDORPRINCIPAL_AP = 'S' DESC, AG.CODIGO_PRV_AP LIMIT 1)), '')), '')),
                           0,
                           UPPER(IFNULL(m.`TIPO_DOC_MOV`, '')),
                           DATE(m.`FECHA_MOV`),
                           DATE(m.`FECHA_MOV`) BETWEEN v_desde AND v_hasta,

                           IF(m.`TIPO_MOV` = 'E', m.`CANTIDAD_MOV`,
                              -m.`CANTIDAD_MOV`)
                      FROM `fza_movimientos_almacen` m
                     WHERE
       (p_PROVEEDORES = '' OR EXISTS (
         SELECT 1 FROM fza_articulos_lotes LP
          WHERE LP.CODIGO_UNIDAD_LOT = m.CODIGO_UNIDAD_MOV
            AND LP.LOTE_LOT = m.LOTE_MOV
            AND COALESCE(TRIM(LP.CODIGO_PRV_LOT), '') NOT IN ('', '0')
            AND FIND_IN_SET(LP.CODIGO_PRV_LOT, p_PROVEEDORES) > 0)
        OR (NOT EXISTS (
         SELECT 1 FROM fza_articulos_lotes LP
          WHERE LP.CODIGO_UNIDAD_LOT = m.CODIGO_UNIDAD_MOV
            AND LP.LOTE_LOT = m.LOTE_MOV
            AND COALESCE(TRIM(LP.CODIGO_PRV_LOT), '') NOT IN ('', '0')) AND EXISTS (
         SELECT 1 FROM fza_articulos_proveedores APF
          WHERE APF.CODIGO_ART_AP = m.CODIGO_ART_MOV
            AND FIND_IN_SET(APF.CODIGO_PRV_AP, p_PROVEEDORES) > 0))) AND m.`ESACTIVO_MOV` = 'S'
                       AND m.`CODIGO_ALM_MOV` IN (SELECT `CODIGO_ALM` FROM `tmp_bat_alm`)


                       AND m.`CODIGO_UNIDAD_MOV` IN
                           (SELECT `CODIGO_UNIDAD` FROM `tmp_bat_sku`)

                       AND m.`FECHA_MOV` >= v_desde
                   ) u
             GROUP BY u.`CODIGO_UNIDAD`, u.`ALM`
           ) mv ON mv.`CODIGO_UNIDAD` = s.`CODIGO_UNIDAD`
     GROUP BY s.`CODIGO_ART`, COALESCE(mv.`ALM`, ''),
              s.`POSICION`, s.`CLAVE_FILA`;









    DROP TEMPORARY TABLE IF EXISTS `tmp_bat_ven`;
    CREATE TEMPORARY TABLE `tmp_bat_ven` (
        `CODIGO_ART` VARCHAR(20)   NOT NULL,
        `CODIGO_ALM` VARCHAR(50)   NOT NULL DEFAULT '',
        `CLAVE_FILA`      VARCHAR(600)  NOT NULL DEFAULT '',
        `POSICION`   INT           NOT NULL,
        `VEN_QTY`    DECIMAL(19,6) NOT NULL DEFAULT 0,
        PRIMARY KEY (`CODIGO_ART`, `CODIGO_ALM`, `CLAVE_FILA`, `POSICION`)
    );
    INSERT INTO `tmp_bat_ven`
    SELECT s.`CODIGO_ART`,
           CONCAT(IF(v_por_alm, fl.`CODIGO_ALM_FACLIN`, ''), IF(v_por_prv, CONCAT(CHAR(31 USING utf8mb4), COALESCE((SELECT NULLIF(NULLIF(TRIM(LG.CODIGO_PRV_LOT), ''), '0') FROM fza_articulos_lotes LG WHERE LG.CODIGO_UNIDAD_LOT = fl.CODIGO_UNIDAD_FACLIN AND LG.LOTE_LOT = fl.LOTE_FACLIN LIMIT 1), IF(p_PROVEEDORES = '', (SELECT MAX(AG.CODIGO_PRV_AP) FROM fza_articulos_proveedores AG WHERE AG.CODIGO_ART_AP = fl.CODIGO_ART_FACLIN AND AG.ESPROVEEDORPRINCIPAL_AP = 'S'), (SELECT AG.CODIGO_PRV_AP FROM fza_articulos_proveedores AG WHERE AG.CODIGO_ART_AP = fl.CODIGO_ART_FACLIN AND FIND_IN_SET(AG.CODIGO_PRV_AP, p_PROVEEDORES) > 0 ORDER BY AG.ESPROVEEDORPRINCIPAL_AP = 'S' DESC, AG.CODIGO_PRV_AP LIMIT 1)), '')), '')),
           s.`CLAVE_FILA`, s.`POSICION`,
           SUM(fl.`CANTIDAD_FACLIN`)
      FROM `fza_facturas_lineas` fl
      JOIN `fza_facturas` f
        ON f.`NUMERO_FAC` = fl.`NUMERO_FAC_FACLIN`
       AND f.`SERIE_FAC` = fl.`SERIE_FAC_FACLIN`
      JOIN `tmp_bat_sku` s
        ON s.`CODIGO_UNIDAD` = fl.`CODIGO_UNIDAD_FACLIN`
     WHERE
       (p_PROVEEDORES = '' OR EXISTS (
         SELECT 1 FROM fza_articulos_lotes LP
          WHERE LP.CODIGO_UNIDAD_LOT = fl.CODIGO_UNIDAD_FACLIN
            AND LP.LOTE_LOT = fl.LOTE_FACLIN
            AND COALESCE(TRIM(LP.CODIGO_PRV_LOT), '') NOT IN ('', '0')
            AND FIND_IN_SET(LP.CODIGO_PRV_LOT, p_PROVEEDORES) > 0)
        OR (NOT EXISTS (
         SELECT 1 FROM fza_articulos_lotes LP
          WHERE LP.CODIGO_UNIDAD_LOT = fl.CODIGO_UNIDAD_FACLIN
            AND LP.LOTE_LOT = fl.LOTE_FACLIN
            AND COALESCE(TRIM(LP.CODIGO_PRV_LOT), '') NOT IN ('', '0')) AND EXISTS (
         SELECT 1 FROM fza_articulos_proveedores APF
          WHERE APF.CODIGO_ART_AP = fl.CODIGO_ART_FACLIN
            AND FIND_IN_SET(APF.CODIGO_PRV_AP, p_PROVEEDORES) > 0))) AND fl.`CODIGO_ALM_FACLIN` IN (SELECT `CODIGO_ALM` FROM `tmp_bat_alm`)
       AND DATE(f.`FECHA_FAC`) BETWEEN v_desde AND v_hasta
       
       AND NOT EXISTS (
         SELECT 1 FROM fza_facturas_traspasos_vendidos TVI
          WHERE TVI.SERIE_FAC_FACTV = f.SERIE_FAC
            AND TVI.NUMERO_FAC_FACTV = f.NUMERO_FAC)
       AND NOT EXISTS (
         SELECT 1 FROM fza_facturas_operaciones_caja TAI
         JOIN fza_caja_operaciones OTA
           ON OTA.ID_OPCAJA = TAI.ID_OPCAJA_FACOP
          AND OTA.TIPO_OPERACION_OPCAJA = 'TA'
          WHERE TAI.SERIE_FAC_FACOP = f.SERIE_FAC
            AND TAI.NUMERO_FAC_FACOP = f.NUMERO_FAC)

       AND f.`ESCONSOLIDADA_FAC` = 'S'
       AND NOT EXISTS (
           SELECT 1 FROM `fza_empresas` d
            WHERE d.`CODIGO_CLI_TRASPASOS_EMP` = f.`CODIGO_CLI_FAC`
              AND d.`CODIGO_EMP_EMP` <> f.`CODIGO_EMP_FAC`)
     GROUP BY s.`CODIGO_ART`,
              CONCAT(IF(v_por_alm, fl.`CODIGO_ALM_FACLIN`, ''), IF(v_por_prv, CONCAT(CHAR(31 USING utf8mb4), COALESCE((SELECT NULLIF(NULLIF(TRIM(LG.CODIGO_PRV_LOT), ''), '0') FROM fza_articulos_lotes LG WHERE LG.CODIGO_UNIDAD_LOT = fl.CODIGO_UNIDAD_FACLIN AND LG.LOTE_LOT = fl.LOTE_FACLIN LIMIT 1), IF(p_PROVEEDORES = '', (SELECT MAX(AG.CODIGO_PRV_AP) FROM fza_articulos_proveedores AG WHERE AG.CODIGO_ART_AP = fl.CODIGO_ART_FACLIN AND AG.ESPROVEEDORPRINCIPAL_AP = 'S'), (SELECT AG.CODIGO_PRV_AP FROM fza_articulos_proveedores AG WHERE AG.CODIGO_ART_AP = fl.CODIGO_ART_FACLIN AND FIND_IN_SET(AG.CODIGO_PRV_AP, p_PROVEEDORES) > 0 ORDER BY AG.ESPROVEEDORPRINCIPAL_AP = 'S' DESC, AG.CODIGO_PRV_AP LIMIT 1)), '')), '')),
              s.`CLAVE_FILA`, s.`POSICION`;
    UPDATE `tmp_bat_base` b
      JOIN `tmp_bat_ven` v
        ON v.`CODIGO_ART` = b.`CODIGO_ART`
       AND v.`CODIGO_ALM` = b.`CODIGO_ALM`
       AND v.`CLAVE_FILA` = b.`CLAVE_FILA`
       AND v.`POSICION` = b.`POSICION`
       SET b.`VEN_FAC` = v.`VEN_QTY`;


    DROP TEMPORARY TABLE IF EXISTS `tmp_bat_vdep`;
    CREATE TEMPORARY TABLE `tmp_bat_vdep` (
        `CODIGO_ART` VARCHAR(20)   NOT NULL,
        `CODIGO_ALM` VARCHAR(50)   NOT NULL DEFAULT '',
        `CLAVE_FILA` VARCHAR(600)  NOT NULL DEFAULT '',
        `POSICION`   INT           NOT NULL,
        `VEN_DEP`    DECIMAL(19,6) NOT NULL DEFAULT 0,
        PRIMARY KEY (`CODIGO_ART`, `CODIGO_ALM`, `CLAVE_FILA`, `POSICION`)
    );
    INSERT INTO `tmp_bat_vdep`
    SELECT s.`CODIGO_ART`,
           CONCAT(IF(v_por_alm, pa.`CODIGO_ALM_ALM`, ''), IF(v_por_prv, CONCAT(CHAR(31 USING utf8mb4), COALESCE((SELECT NULLIF(NULLIF(TRIM(LG.CODIGO_PRV_LOT), ''), '0') FROM fza_articulos_lotes LG WHERE LG.CODIGO_UNIDAD_LOT = m.CODIGO_UNIDAD_MOV AND LG.LOTE_LOT = m.LOTE_MOV LIMIT 1), IF(p_PROVEEDORES = '', (SELECT MAX(AG.CODIGO_PRV_AP) FROM fza_articulos_proveedores AG WHERE AG.CODIGO_ART_AP = m.CODIGO_ART_MOV AND AG.ESPROVEEDORPRINCIPAL_AP = 'S'), (SELECT AG.CODIGO_PRV_AP FROM fza_articulos_proveedores AG WHERE AG.CODIGO_ART_AP = m.CODIGO_ART_MOV AND FIND_IN_SET(AG.CODIGO_PRV_AP, p_PROVEEDORES) > 0 ORDER BY AG.ESPROVEEDORPRINCIPAL_AP = 'S' DESC, AG.CODIGO_PRV_AP LIMIT 1)), '')), '')),
           s.`CLAVE_FILA`, s.`POSICION`,
           SUM(IF(m.`TIPO_MOV` = 'E', -m.`CANTIDAD_MOV`, m.`CANTIDAD_MOV`))
      FROM `fza_almacenes` da
      JOIN `fza_almacenes` pa
        ON pa.`CODIGO_ALM_ALM` = da.`CODIGO_PADRE_ALM`
      JOIN `fza_movimientos_almacen` m
        ON m.`CODIGO_ALM_MOV` = da.`CODIGO_ALM_ALM`
      JOIN `tmp_bat_sku` s
        ON s.`CODIGO_UNIDAD` = m.`CODIGO_UNIDAD_MOV`
      LEFT JOIN `tmp_bat_alm` sel
        ON sel.`CODIGO_ALM` = da.`CODIGO_ALM_ALM`
     WHERE
       (p_PROVEEDORES = '' OR EXISTS (
         SELECT 1 FROM fza_articulos_lotes LP
          WHERE LP.CODIGO_UNIDAD_LOT = m.CODIGO_UNIDAD_MOV
            AND LP.LOTE_LOT = m.LOTE_MOV
            AND COALESCE(TRIM(LP.CODIGO_PRV_LOT), '') NOT IN ('', '0')
            AND FIND_IN_SET(LP.CODIGO_PRV_LOT, p_PROVEEDORES) > 0)
        OR (NOT EXISTS (
         SELECT 1 FROM fza_articulos_lotes LP
          WHERE LP.CODIGO_UNIDAD_LOT = m.CODIGO_UNIDAD_MOV
            AND LP.LOTE_LOT = m.LOTE_MOV
            AND COALESCE(TRIM(LP.CODIGO_PRV_LOT), '') NOT IN ('', '0')) AND EXISTS (
         SELECT 1 FROM fza_articulos_proveedores APF
          WHERE APF.CODIGO_ART_AP = m.CODIGO_ART_MOV
            AND FIND_IN_SET(APF.CODIGO_PRV_AP, p_PROVEEDORES) > 0))) AND UPPER(TRIM(da.`TIPO_USO_ALM`)) IN ('DEPOSITO', 'DEPÓSITO')
       AND IF(IFNULL(p_ALMACENES, '') = '',
              pa.`ESACTIVO_ALM` = 'S',
              FIND_IN_SET(pa.`CODIGO_ALM_ALM`, p_ALMACENES))

       AND (v_por_alm OR sel.`CODIGO_ALM` IS NULL)
       AND m.`ESACTIVO_MOV` = 'S'
       AND UPPER(IFNULL(m.`TIPO_DOC_MOV`, '')) IN ('VE', 'FC')
       AND m.`FECHA_MOV` >= v_desde
       AND DATE(m.`FECHA_MOV`) BETWEEN v_desde AND v_hasta
     GROUP BY s.`CODIGO_ART`, CONCAT(IF(v_por_alm, pa.`CODIGO_ALM_ALM`, ''), IF(v_por_prv, CONCAT(CHAR(31 USING utf8mb4), COALESCE((SELECT NULLIF(NULLIF(TRIM(LG.CODIGO_PRV_LOT), ''), '0') FROM fza_articulos_lotes LG WHERE LG.CODIGO_UNIDAD_LOT = m.CODIGO_UNIDAD_MOV AND LG.LOTE_LOT = m.LOTE_MOV LIMIT 1), IF(p_PROVEEDORES = '', (SELECT MAX(AG.CODIGO_PRV_AP) FROM fza_articulos_proveedores AG WHERE AG.CODIGO_ART_AP = m.CODIGO_ART_MOV AND AG.ESPROVEEDORPRINCIPAL_AP = 'S'), (SELECT AG.CODIGO_PRV_AP FROM fza_articulos_proveedores AG WHERE AG.CODIGO_ART_AP = m.CODIGO_ART_MOV AND FIND_IN_SET(AG.CODIGO_PRV_AP, p_PROVEEDORES) > 0 ORDER BY AG.ESPROVEEDORPRINCIPAL_AP = 'S' DESC, AG.CODIGO_PRV_AP LIMIT 1)), '')), '')),
              s.`CLAVE_FILA`, s.`POSICION`;
    UPDATE `tmp_bat_base` b
      JOIN `tmp_bat_vdep` d
        ON d.`CODIGO_ART` = b.`CODIGO_ART`
       AND d.`CODIGO_ALM` = b.`CODIGO_ALM`
       AND d.`CLAVE_FILA` = b.`CLAVE_FILA`
       AND d.`POSICION` = b.`POSICION`
       SET b.`SAL_VENTA_DEP` = d.`VEN_DEP`;
    UPDATE `tmp_bat_base` b
      JOIN `fza_almacenes` da
        ON da.`CODIGO_ALM_ALM` = SUBSTRING_INDEX(b.`CODIGO_ALM`, CHAR(31 USING utf8mb4), 1)
       SET b.`SAL_VENTA_DEP` = b.`SAL_VENTA_DEP` - b.`SAL_VENTA`
     WHERE UPPER(TRIM(da.`TIPO_USO_ALM`)) IN ('DEPOSITO', 'DEPÓSITO')
       AND IFNULL(da.`CODIGO_PADRE_ALM`, '') <> '';





    DELETE FROM `tmp_bat_base`
     WHERE `EXI_INI` = 0 AND `EXI_FIN` = 0
       AND `ENT_COMPRA` = 0 AND `ENT_ALBENTRADA` = 0 AND `ENT_TRASPASO` = 0
       AND `ENT_DEPOSITO` = 0 AND `ENT_REGULAR` = 0 AND `ENT_DEVPRV` = 0
       AND `ENT_OTROS` = 0 AND `SAL_ALBVENTA` = 0 AND `SAL_VENTA` = 0
       AND `VEN_FAC` = 0 AND `NUM_MOVS` = 0;



    DROP TEMPORARY TABLE IF EXISTS `tmp_bat_marcas`;
    CREATE TEMPORARY TABLE `tmp_bat_marcas` (
        `CODIGO_ART` VARCHAR(20)  NOT NULL,
        `CODIGO_ALM` VARCHAR(50)  NOT NULL DEFAULT '',
        `CLAVE_FILA`      VARCHAR(600) NOT NULL DEFAULT '',
        `CON_SINMOV` TINYINT      NOT NULL DEFAULT 0,
        `CON_DEVPRV` TINYINT      NOT NULL DEFAULT 0,
        `CON_OTROS`  TINYINT      NOT NULL DEFAULT 0,
        `CON_AVIFAC` TINYINT      NOT NULL DEFAULT 0,
        PRIMARY KEY (`CODIGO_ART`, `CODIGO_ALM`, `CLAVE_FILA`)
    );
    INSERT INTO `tmp_bat_marcas`
    SELECT `CODIGO_ART`, `CODIGO_ALM`, `CLAVE_FILA`,
           SUM(ABS(`EXI_INI`)) <> 0,
           SUM(ABS(`ENT_DEVPRV`)) <> 0,
           SUM(ABS(`ENT_OTROS`)) <> 0,
           SUM(ABS(`VEN_FAC` - `SAL_VENTA` - `SAL_ALBVENTA`
                   - `SAL_VENTA_DEP`)) <> 0
      FROM `tmp_bat_base`
     GROUP BY `CODIGO_ART`, `CODIGO_ALM`, `CLAVE_FILA`;






    DROP TEMPORARY TABLE IF EXISTS `tmp_bat_medidas`;
    CREATE TEMPORARY TABLE `tmp_bat_medidas` (
        `CODIGO_ART`     VARCHAR(20)  NOT NULL,
        `CODIGO_ALM`     VARCHAR(50)  NOT NULL DEFAULT '',
        `CLAVE_FILA`          VARCHAR(600) NULL,
        `COLOR_HEX`      VARCHAR(7)   NULL,
        `ORDEN_COLOR`    INT          NOT NULL DEFAULT 0,
        `POSICION`       INT          NOT NULL,
        `BANDA`          VARCHAR(20)  NOT NULL,
        `ORDEN_BANDA`    INT          NOT NULL,
        `ETIQUETA_BANDA` VARCHAR(40)  NOT NULL,
        `ES_COSTE`       TINYINT      NOT NULL DEFAULT 0,
        `CANTIDAD`       DECIMAL(19,6) NOT NULL DEFAULT 0,
        KEY `IDX_BAT_MED` (`CODIGO_ART`, `CODIGO_ALM`, `CLAVE_FILA`, `ORDEN_BANDA`)
    );

    IF p_MODO = 'F' THEN
        INSERT INTO `tmp_bat_medidas`
        SELECT `CODIGO_ART`, `CODIGO_ALM`, `CLAVE_FILA`, `COLOR_HEX`, `ORDEN_COLOR`,
               `POSICION`,
               'EXIINI', 10, 'Existencias iniciales', 1, `EXI_INI`
          FROM `tmp_bat_base`;
    ELSE



        INSERT INTO `tmp_bat_medidas`
        SELECT b.`CODIGO_ART`, b.`CODIGO_ALM`, b.`CLAVE_FILA`, b.`COLOR_HEX`,
               b.`ORDEN_COLOR`, b.`POSICION`,
               'SINMOV', 15, 'Stock sin movim.', 1, b.`EXI_INI`
          FROM `tmp_bat_base` b
          JOIN `tmp_bat_marcas` x
            ON x.`CODIGO_ART` = b.`CODIGO_ART`
           AND x.`CODIGO_ALM` = b.`CODIGO_ALM`
           AND x.`CLAVE_FILA` = b.`CLAVE_FILA`
         WHERE x.`CON_SINMOV` = 1;
    END IF;



    IF (p_MODO = 'F' AND p_DESGLOSADO = 'N') OR p_MODO = 'A' THEN
        INSERT INTO `tmp_bat_medidas`
        SELECT `CODIGO_ART`, `CODIGO_ALM`, `CLAVE_FILA`, `COLOR_HEX`, `ORDEN_COLOR`,
               `POSICION`,
               'ENT', 20, 'Entradas', 1,
               `ENT_COMPRA` + `ENT_ALBENTRADA` + `ENT_TRASPASO`
                 + `ENT_DEPOSITO` + `ENT_REGULAR` + `ENT_DEVPRV` + `ENT_OTROS`
          FROM `tmp_bat_base`;
        INSERT INTO `tmp_bat_medidas`
        SELECT `CODIGO_ART`, `CODIGO_ALM`, `CLAVE_FILA`, `COLOR_HEX`, `ORDEN_COLOR`,
               `POSICION`,
               'VEN', 50, 'Ventas', 0, `SAL_VENTA` + `SAL_ALBVENTA`
          FROM `tmp_bat_base`;
    END IF;


    IF p_MODO = 'F' AND p_DESGLOSADO = 'S' THEN
        INSERT INTO `tmp_bat_medidas`
        SELECT `CODIGO_ART`, `CODIGO_ALM`, `CLAVE_FILA`, `COLOR_HEX`, `ORDEN_COLOR`,
               `POSICION`,
               'ENTCMP', 21, 'Ent. compra', 1, `ENT_COMPRA`
          FROM `tmp_bat_base`;
        INSERT INTO `tmp_bat_medidas`
        SELECT `CODIGO_ART`, `CODIGO_ALM`, `CLAVE_FILA`, `COLOR_HEX`, `ORDEN_COLOR`,
               `POSICION`,
               'ENTALB', 22, 'Alb. entrada', 1, `ENT_ALBENTRADA`
          FROM `tmp_bat_base`;
        INSERT INTO `tmp_bat_medidas`
        SELECT `CODIGO_ART`, `CODIGO_ALM`, `CLAVE_FILA`, `COLOR_HEX`, `ORDEN_COLOR`,
               `POSICION`,
               'ENTTRA', 23, 'Traspasos (neto)', 1, `ENT_TRASPASO`
          FROM `tmp_bat_base`;
        INSERT INTO `tmp_bat_medidas`
        SELECT `CODIGO_ART`, `CODIGO_ALM`, `CLAVE_FILA`, `COLOR_HEX`, `ORDEN_COLOR`,
               `POSICION`,
               'ENTDEP', 24, 'Depósitos (neto)', 1, `ENT_DEPOSITO`
          FROM `tmp_bat_base`;
        INSERT INTO `tmp_bat_medidas`
        SELECT `CODIGO_ART`, `CODIGO_ALM`, `CLAVE_FILA`, `COLOR_HEX`, `ORDEN_COLOR`,
               `POSICION`,
               'ENTREG', 25, 'Regulariz.', 1, `ENT_REGULAR`
          FROM `tmp_bat_base`;
        INSERT INTO `tmp_bat_medidas`
        SELECT b.`CODIGO_ART`, b.`CODIGO_ALM`, b.`CLAVE_FILA`, b.`COLOR_HEX`,
               b.`ORDEN_COLOR`, b.`POSICION`,
               'ENTDEV', 26, 'Dev. proveedor', 1, b.`ENT_DEVPRV`
          FROM `tmp_bat_base` b
          JOIN `tmp_bat_marcas` x
            ON x.`CODIGO_ART` = b.`CODIGO_ART`
           AND x.`CODIGO_ALM` = b.`CODIGO_ALM`
           AND x.`CLAVE_FILA` = b.`CLAVE_FILA`
         WHERE x.`CON_DEVPRV` = 1;
        INSERT INTO `tmp_bat_medidas`
        SELECT b.`CODIGO_ART`, b.`CODIGO_ALM`, b.`CLAVE_FILA`, b.`COLOR_HEX`,
               b.`ORDEN_COLOR`, b.`POSICION`,
               'ENTOTR', 27, 'Otros movim.', 1, b.`ENT_OTROS`
          FROM `tmp_bat_base` b
          JOIN `tmp_bat_marcas` x
            ON x.`CODIGO_ART` = b.`CODIGO_ART`
           AND x.`CODIGO_ALM` = b.`CODIGO_ALM`
           AND x.`CLAVE_FILA` = b.`CLAVE_FILA`
         WHERE x.`CON_OTROS` = 1;
        INSERT INTO `tmp_bat_medidas`
        SELECT `CODIGO_ART`, `CODIGO_ALM`, `CLAVE_FILA`, `COLOR_HEX`, `ORDEN_COLOR`,
               `POSICION`,
               'SALALB', 43, 'Alb. venta', 0, `SAL_ALBVENTA`
          FROM `tmp_bat_base`;
        INSERT INTO `tmp_bat_medidas`
        SELECT `CODIGO_ART`, `CODIGO_ALM`, `CLAVE_FILA`, `COLOR_HEX`, `ORDEN_COLOR`,
               `POSICION`,
               'VEN', 50, 'Ventas', 0, `SAL_VENTA`
          FROM `tmp_bat_base`;
    END IF;

    INSERT INTO `tmp_bat_medidas`
    SELECT `CODIGO_ART`, `CODIGO_ALM`, `CLAVE_FILA`, `COLOR_HEX`, `ORDEN_COLOR`,
           `POSICION`,
           'EXIFIN', 90, 'Existencias finales', 1, `EXI_FIN`
      FROM `tmp_bat_base`;


    INSERT INTO `tmp_bat_medidas`
    SELECT b.`CODIGO_ART`, b.`CODIGO_ALM`, b.`CLAVE_FILA`, b.`COLOR_HEX`,
           b.`ORDEN_COLOR`, b.`POSICION`,
           'AVIFAC', 95, 'Dif. fact./ventas', 0,
           b.`VEN_FAC` - b.`SAL_VENTA` - b.`SAL_ALBVENTA`
             - b.`SAL_VENTA_DEP`
      FROM `tmp_bat_base` b
      JOIN `tmp_bat_marcas` x
        ON x.`CODIGO_ART` = b.`CODIGO_ART`
       AND x.`CODIGO_ALM` = b.`CODIGO_ALM`
       AND x.`CLAVE_FILA` = b.`CLAVE_FILA`
     WHERE x.`CON_AVIFAC` = 1;



    IF p_BANDAS <> '' THEN
        DELETE FROM `tmp_bat_medidas`
         WHERE NOT FIND_IN_SET(`BANDA`, p_BANDAS)
           AND `BANDA` NOT IN ('AVIFAC', 'SINMOV');
    END IF;







    DROP TEMPORARY TABLE IF EXISTS `tmp_bat_pvp`;





    CREATE TEMPORARY TABLE `tmp_bat_pvp` AS
    SELECT s.`CODIGO_ART`, s.`CLAVE_FILA`,
           COALESCE(
               MAX(IF(IFNULL(t.`CODIGO_UNIDAD_ARTTAR`, '') = '',
                      t.`PRECIO_FINAL_ARTTAR`, NULL)),
               MAX(t.`PRECIO_FINAL_ARTTAR`)) AS `PVP`
      FROM `tmp_bat_sku` s
      JOIN `fza_articulos_tarifas` t
        ON t.`CODIGO_ART_ARTTAR` = s.`CODIGO_ART`
       AND t.`CODIGO_TAR_ARTTAR` = v_tarifa
       AND t.`ESACTIVO_ARTTAR` = 'S'
       AND (t.`FECHA_DESDE_ARTTAR` IS NULL
            OR t.`FECHA_DESDE_ARTTAR` <= CURRENT_DATE)
       AND (t.`FECHA_HASTA_ARTTAR` IS NULL
            OR t.`FECHA_HASTA_ARTTAR` >= CURRENT_DATE)
       AND (IFNULL(t.`CODIGO_UNIDAD_ARTTAR`, '') = ''
            OR t.`CODIGO_UNIDAD_ARTTAR` = s.`CODIGO_UNIDAD`
            OR (LOCATE('/*/', t.`CODIGO_UNIDAD_ARTTAR`) = 0
                AND LEFT(s.`CODIGO_UNIDAD`,
                         CHAR_LENGTH(t.`CODIGO_UNIDAD_ARTTAR`) + 1)
                    = CONCAT(t.`CODIGO_UNIDAD_ARTTAR`, '/'))
            OR (LOCATE('/*/', t.`CODIGO_UNIDAD_ARTTAR`) > 0
                AND LEFT(s.`CODIGO_UNIDAD`,
                         LOCATE('/*/', t.`CODIGO_UNIDAD_ARTTAR`))
                    = LEFT(t.`CODIGO_UNIDAD_ARTTAR`,
                           LOCATE('/*/', t.`CODIGO_UNIDAD_ARTTAR`))
                AND RIGHT(s.`CODIGO_UNIDAD`,
                          CHAR_LENGTH(t.`CODIGO_UNIDAD_ARTTAR`)
                          - LOCATE('/*/', t.`CODIGO_UNIDAD_ARTTAR`) - 1)
                    = SUBSTRING(t.`CODIGO_UNIDAD_ARTTAR`,
                                LOCATE('/*/', t.`CODIGO_UNIDAD_ARTTAR`)
                                + 2)))
     GROUP BY s.`CODIGO_ART`, s.`CLAVE_FILA`;
    ALTER TABLE `tmp_bat_pvp`
        ADD PRIMARY KEY (`CODIGO_ART`, `CLAVE_FILA`);
    DROP TEMPORARY TABLE IF EXISTS `tmp_bat_prov`;
    CREATE TEMPORARY TABLE `tmp_bat_prov` AS
    SELECT ap.`CODIGO_ART_AP` AS `CODIGO_ART`,
           MAX(ap.`REF_PROVEEDOR_AP`)   AS `REF_PROVEEDOR_AP`,
           MAX(ap.`PRECIO_ULT_COMPRA_AP`) AS `COSTE_PRV`,
           MAX(ap.`CODIGO_PRV_AP`)      AS `CODIGO_PRV`,
           MAX(pr.`RAZON_SOCIAL_PRV`)   AS `RAZON`
      FROM `fza_articulos_proveedores` ap
      LEFT JOIN `fza_proveedores` pr
        ON pr.`CODIGO_PRV_PRV` = ap.`CODIGO_PRV_AP`
     WHERE ap.`ESPROVEEDORPRINCIPAL_AP` = 'S'

       AND ap.`CODIGO_ART_AP` IN
           (SELECT `CODIGO_ART` FROM `tmp_bat_arts`)
     GROUP BY ap.`CODIGO_ART_AP`;
    ALTER TABLE `tmp_bat_prov` ADD PRIMARY KEY (`CODIGO_ART`);
    DROP TEMPORARY TABLE IF EXISTS `tmp_bat_tmp`;
    CREATE TEMPORARY TABLE `tmp_bat_tmp` AS
    SELECT s.`CODIGO_ART` AS `CODIGO_ART`, s.`CLAVE_FILA` AS `CLAVE_FILA`,
           MAX(COALESCE(e.`VALOR_PV`,
                        e.`VALOR_LIBRE_ARTPROP`)) AS `TEMPORADA`
      FROM `tmp_bat_sku` s
      JOIN `vi_articulos_propiedades_efectivas` e
        ON e.`CODIGO_UNIDAD_SKU` = s.`CODIGO_UNIDAD`
       AND e.`CODIGO_PROP_ARTPROP` = 'TEMPORADA'
     GROUP BY s.`CODIGO_ART`, s.`CLAVE_FILA`;
    ALTER TABLE `tmp_bat_tmp` ADD PRIMARY KEY (`CODIGO_ART`, `CLAVE_FILA`);





    DROP TEMPORARY TABLE IF EXISTS `tmp_bat_fal`;
    CREATE TEMPORARY TABLE `tmp_bat_fal` AS
    SELECT DISTINCT al.`SERIE_FAC_ALBLIN` AS `SERIE_FAC`,
           al.`NUMERO_FAC_ALBLIN` AS `NUMERO_FAC`,
           al.`LINEA_FAC_ALBLIN` AS `LINEA_FAC`
      FROM `fza_albaranes_lineas` al
     WHERE
       (p_PROVEEDORES = '' OR EXISTS (
         SELECT 1 FROM fza_articulos_lotes LP
          WHERE LP.CODIGO_UNIDAD_LOT = al.CODIGO_UNIDAD_ALBLIN
            AND LP.LOTE_LOT = al.LOTE_ALBLIN
            AND COALESCE(TRIM(LP.CODIGO_PRV_LOT), '') NOT IN ('', '0')
            AND FIND_IN_SET(LP.CODIGO_PRV_LOT, p_PROVEEDORES) > 0)
        OR (NOT EXISTS (
         SELECT 1 FROM fza_articulos_lotes LP
          WHERE LP.CODIGO_UNIDAD_LOT = al.CODIGO_UNIDAD_ALBLIN
            AND LP.LOTE_LOT = al.LOTE_ALBLIN
            AND COALESCE(TRIM(LP.CODIGO_PRV_LOT), '') NOT IN ('', '0')) AND EXISTS (
         SELECT 1 FROM fza_articulos_proveedores APF
          WHERE APF.CODIGO_ART_AP = al.CODIGO_ART_ALBLIN
            AND FIND_IN_SET(APF.CODIGO_PRV_AP, p_PROVEEDORES) > 0))) AND COALESCE(al.`SERIE_FAC_ALBLIN`, '') <> ''
       AND COALESCE(al.`NUMERO_FAC_ALBLIN`, '') <> ''
       AND COALESCE(al.`LINEA_FAC_ALBLIN`, '') <> '';
    ALTER TABLE `tmp_bat_fal`
        ADD PRIMARY KEY (`SERIE_FAC`, `NUMERO_FAC`, `LINEA_FAC`);
    DROP TEMPORARY TABLE IF EXISTS `tmp_bat_vt`;
    CREATE TEMPORARY TABLE `tmp_bat_vt` AS





    SELECT s.`CODIGO_ART`,
           (s.`POSICION` - 1) DIV 14 + 1 AS `BLOQUE_TALLAS`,
           CONCAT(IF(v_por_alm, fl.`CODIGO_ALM_FACLIN`, ''), IF(v_por_prv, CONCAT(CHAR(31 USING utf8mb4), COALESCE((SELECT NULLIF(NULLIF(TRIM(LG.CODIGO_PRV_LOT), ''), '0') FROM fza_articulos_lotes LG WHERE LG.CODIGO_UNIDAD_LOT = fl.CODIGO_UNIDAD_FACLIN AND LG.LOTE_LOT = fl.LOTE_FACLIN LIMIT 1), IF(p_PROVEEDORES = '', (SELECT MAX(AG.CODIGO_PRV_AP) FROM fza_articulos_proveedores AG WHERE AG.CODIGO_ART_AP = fl.CODIGO_ART_FACLIN AND AG.ESPROVEEDORPRINCIPAL_AP = 'S'), (SELECT AG.CODIGO_PRV_AP FROM fza_articulos_proveedores AG WHERE AG.CODIGO_ART_AP = fl.CODIGO_ART_FACLIN AND FIND_IN_SET(AG.CODIGO_PRV_AP, p_PROVEEDORES) > 0 ORDER BY AG.ESPROVEEDORPRINCIPAL_AP = 'S' DESC, AG.CODIGO_PRV_AP LIMIT 1)), '')), '')) AS `CODIGO_ALM`,
           s.`CLAVE_FILA`,
           SUM(fl.`CANTIDAD_FACLIN`) AS `VEN_QTY`,





           SUM(COALESCE(fl.`TOTAL_FAC_SIVA_FACLIN`,
                    CASE WHEN fl.`ESIMP_INCL_TARIFA_FACLIN` = 'S'
                         THEN fl.`TOTAL_FACLIN` /
                         (1 + COALESCE(fl.`PORCENTAJE_IVA_FACLIN`, 0) / 100)
                         ELSE fl.`TOTAL_FACLIN` END)) AS `VEN_IMPORTE`,

           SUM(IF(fa.`LINEA_FAC` IS NULL, 0,
                  fl.`CANTIDAD_FACLIN`)) AS `VEN_QTY_ALB`,
           SUM(IF(fa.`LINEA_FAC` IS NULL, 0,
                  COALESCE(fl.`TOTAL_FAC_SIVA_FACLIN`,
                           CASE WHEN fl.`ESIMP_INCL_TARIFA_FACLIN` = 'S'
                                THEN fl.`TOTAL_FACLIN` /
                                (1 + COALESCE(fl.`PORCENTAJE_IVA_FACLIN`, 0) / 100)
                                ELSE fl.`TOTAL_FACLIN` END))) AS `VEN_IMPORTE_ALB`
      FROM `fza_facturas_lineas` fl
      JOIN `fza_facturas` f
        ON f.`NUMERO_FAC` = fl.`NUMERO_FAC_FACLIN`
       AND f.`SERIE_FAC` = fl.`SERIE_FAC_FACLIN`
      LEFT JOIN `tmp_bat_fal` fa
        ON fa.`SERIE_FAC` = fl.`SERIE_FAC_FACLIN`
       AND fa.`NUMERO_FAC` = fl.`NUMERO_FAC_FACLIN`
       AND fa.`LINEA_FAC` = fl.`LINEA_FACLIN`
      JOIN `tmp_bat_sku` s
        ON s.`CODIGO_UNIDAD` = fl.`CODIGO_UNIDAD_FACLIN`
     WHERE
       (p_PROVEEDORES = '' OR EXISTS (
         SELECT 1 FROM fza_articulos_lotes LP
          WHERE LP.CODIGO_UNIDAD_LOT = fl.CODIGO_UNIDAD_FACLIN
            AND LP.LOTE_LOT = fl.LOTE_FACLIN
            AND COALESCE(TRIM(LP.CODIGO_PRV_LOT), '') NOT IN ('', '0')
            AND FIND_IN_SET(LP.CODIGO_PRV_LOT, p_PROVEEDORES) > 0)
        OR (NOT EXISTS (
         SELECT 1 FROM fza_articulos_lotes LP
          WHERE LP.CODIGO_UNIDAD_LOT = fl.CODIGO_UNIDAD_FACLIN
            AND LP.LOTE_LOT = fl.LOTE_FACLIN
            AND COALESCE(TRIM(LP.CODIGO_PRV_LOT), '') NOT IN ('', '0')) AND EXISTS (
         SELECT 1 FROM fza_articulos_proveedores APF
          WHERE APF.CODIGO_ART_AP = fl.CODIGO_ART_FACLIN
            AND FIND_IN_SET(APF.CODIGO_PRV_AP, p_PROVEEDORES) > 0))) AND fl.`CODIGO_ALM_FACLIN` IN (SELECT `CODIGO_ALM` FROM `tmp_bat_alm`)
       AND DATE(f.`FECHA_FAC`) BETWEEN v_desde AND v_hasta

       AND f.`ESCONSOLIDADA_FAC` = 'S'
       AND NOT EXISTS (
           SELECT 1 FROM `fza_empresas` d
            WHERE d.`CODIGO_CLI_TRASPASOS_EMP` = f.`CODIGO_CLI_FAC`
              AND d.`CODIGO_EMP_EMP` <> f.`CODIGO_EMP_FAC`)
     GROUP BY s.`CODIGO_ART`,
              CONCAT(IF(v_por_alm, fl.`CODIGO_ALM_FACLIN`, ''), IF(v_por_prv, CONCAT(CHAR(31 USING utf8mb4), COALESCE((SELECT NULLIF(NULLIF(TRIM(LG.CODIGO_PRV_LOT), ''), '0') FROM fza_articulos_lotes LG WHERE LG.CODIGO_UNIDAD_LOT = fl.CODIGO_UNIDAD_FACLIN AND LG.LOTE_LOT = fl.LOTE_FACLIN LIMIT 1), IF(p_PROVEEDORES = '', (SELECT MAX(AG.CODIGO_PRV_AP) FROM fza_articulos_proveedores AG WHERE AG.CODIGO_ART_AP = fl.CODIGO_ART_FACLIN AND AG.ESPROVEEDORPRINCIPAL_AP = 'S'), (SELECT AG.CODIGO_PRV_AP FROM fza_articulos_proveedores AG WHERE AG.CODIGO_ART_AP = fl.CODIGO_ART_FACLIN AND FIND_IN_SET(AG.CODIGO_PRV_AP, p_PROVEEDORES) > 0 ORDER BY AG.ESPROVEEDORPRINCIPAL_AP = 'S' DESC, AG.CODIGO_PRV_AP LIMIT 1)), '')), '')), s.`CLAVE_FILA`,
              (s.`POSICION` - 1) DIV 14 + 1;
    ALTER TABLE `tmp_bat_vt` ADD PRIMARY KEY (`CODIGO_ART`, `CODIGO_ALM`, `CLAVE_FILA`, `BLOQUE_TALLAS`);








    DROP TEMPORARY TABLE IF EXISTS `tmp_bat_nc`;
    CREATE TEMPORARY TABLE `tmp_bat_nc` (
        `CODIGO_ART`   VARCHAR(20)  NOT NULL,
        `CLAVE_FILA`        VARCHAR(600) NOT NULL DEFAULT '',
        `NOMBRE_COLOR` VARCHAR(100) NULL,
        PRIMARY KEY (`CODIGO_ART`, `CLAVE_FILA`)
    );
    INSERT INTO `tmp_bat_nc` (`CODIGO_ART`, `CLAVE_FILA`, `NOMBRE_COLOR`)
    SELECT s.`CODIGO_ART`, s.`CLAVE_FILA`,
           MIN(NULLIF(TRIM(atb.`NOMBRE_ATB`), ''))
      FROM `tmp_bat_sku` s
      JOIN `fza_atributos_sku` sac
        ON sac.`CODIGO_UNIDAD_SKU_SA` = s.`CODIGO_UNIDAD`
      JOIN `fza_atributos_valores` co
        ON co.`ID_AV` = sac.`ID_AV_SA` AND co.`ID_VA_AV` = (SELECT EJ452.ID_ATB_VA FROM VI_VARIACIONES_EJES EJ452 WHERE EJ452.ID_VAR_VA = (SELECT SK452.CODIGO_VAR_SKU FROM fza_articulos_skus SK452 WHERE SK452.CODIGO_UNIDAD_SKU = sac.CODIGO_UNIDAD_SKU_SA) AND EJ452.EJE_VA = 'F')
      LEFT JOIN `fza_articulos_atributos_basicos` aab
        ON aab.`CODIGO_ART_AAB` = s.`CODIGO_ART`
       AND aab.`ID_AV_AAB` = co.`ID_AV`
      LEFT JOIN `fza_articulos_conjuntos_asign` aca
        ON aca.`CODIGO_ART_ACA` = s.`CODIGO_ART`
       AND aca.`ID_VA_ACA` = (SELECT EJ452.ID_ATB_VA FROM VI_VARIACIONES_EJES EJ452 WHERE EJ452.ID_VAR_VA = (SELECT AR452.TIPO_VARIACION_ART FROM fza_articulos AR452 WHERE AR452.CODIGO_ART_ART = s.CODIGO_ART) AND EJ452.EJE_VA = 'F')
      LEFT JOIN `fza_atributos_conjuntos_det` acd
        ON acd.`ID_AC_ACD` = aca.`ID_AC_ACA`
       AND acd.`ID_AV_ACD` = co.`ID_AV`
      LEFT JOIN `fza_atributos_basicos` atb
        ON atb.`ID_ATB` = CASE
             WHEN aab.`CODIGO_ART_AAB` IS NOT NULL THEN aab.`ID_ATB_AAB`
             WHEN acd.`ID_ATB_ACD` IS NOT NULL THEN acd.`ID_ATB_ACD`
             ELSE co.`ID_ATB_AV`
           END
     WHERE JSON_UNQUOTE(JSON_EXTRACT(s.`CLAVE_FILA`, '$[0]')) = co.`AV`
     GROUP BY s.`CODIGO_ART`, s.`CLAVE_FILA`;






    CALL PRC_BALANCE_VALORAR_TALLAS(v_por_alm);
    SELECT
        COALESCE(fam.`ORDEN_FAM`, 999999)             AS `ORDEN_FAM`,
        art.`CODIGO_FAM_ART`                          AS `CODIGO_FAM`,
        COALESCE(fam.`DESCRIPCION_FAM`,
                 fam.`NOMBRE_FAM_FAM`, art.`CODIGO_FAM_ART`) AS `DESCRIPCION_FAM`,
        p.`CODIGO_ART`                                AS `CODIGO_ART_ART`,
        art.`DESCRIPCION_ART`                         AS `DESCRIPCION_ART`,
        SUBSTRING_INDEX(p.`CODIGO_ALM`, CHAR(31 USING utf8mb4), 1) AS `CODIGO_ALM`,
        COALESCE(alm.`NOMBRE_ALM_ALM`, '')            AS `NOMBRE_ALM`,
        prov.`REF_PROVEEDOR_AP`                       AS `REF_PRV`,
        ROUND(IFNULL(p.`IMPORTE_COSTE` / NULLIF(p.`CANTIDAD`, 0), 0), 2)
                                                       AS `COSTE_ART`,
        ROUND(COALESCE(pvp.`PVP`, 0), 2)              AS `PVP_ART`,
        p.`ORDEN_COLOR`, p.`COLOR_HEX`,
        CONCAT_WS(' / ',
          NULLIF(JSON_UNQUOTE(JSON_EXTRACT(p.`CLAVE_FILA`, '$[0]')), ''),
          NULLIF(JSON_UNQUOTE(JSON_EXTRACT(p.`CLAVE_FILA`, '$[2]')), ''))
                                                       AS `COLOR`,
        CONCAT_WS(' / ',
          NULLIF(COALESCE(nc.`NOMBRE_COLOR`,
            JSON_UNQUOTE(JSON_EXTRACT(p.`CLAVE_FILA`, '$[0]'))), ''),
          NULLIF(JSON_UNQUOTE(JSON_EXTRACT(p.`CLAVE_FILA`, '$[2]')), ''))
                                                       AS `NOMBRE_COLOR`,
        p.`BLOQUE_TALLAS`,
        JSON_ARRAY(p.`CODIGO_ART`, p.`CODIGO_ALM`, p.`BLOQUE_TALLAS`)
                                                       AS `CLAVE_BLOQUE`,
        p.`ORDEN_BANDA`, p.`BANDA`, p.`ETIQUETA_BANDA`, p.`ES_COSTE`,
        et.`ETIQ_T01`, et.`ETIQ_T02`, et.`ETIQ_T03`, et.`ETIQ_T04`,
        et.`ETIQ_T05`, et.`ETIQ_T06`, et.`ETIQ_T07`, et.`ETIQ_T08`,
        et.`ETIQ_T09`, et.`ETIQ_T10`, et.`ETIQ_T11`, et.`ETIQ_T12`,
        et.`ETIQ_T13`, et.`ETIQ_T14`,
        p.`T01`, p.`T02`, p.`T03`, p.`T04`, p.`T05`, p.`T06`, p.`T07`,
        p.`T08`, p.`T09`, p.`T10`, p.`T11`, p.`T12`, p.`T13`, p.`T14`,
        p.`CANTIDAD`,




        ROUND(CASE
                WHEN p.`BANDA` = 'SALALB' THEN
                  IF(COALESCE(vt.`VEN_QTY_ALB`, 0) <> 0,
                     COALESCE(vt.`VEN_IMPORTE_ALB`, 0) / vt.`VEN_QTY_ALB`, 0)
                WHEN p.`BANDA` = 'VEN' AND v_desglosado THEN
                  IF((COALESCE(vt.`VEN_QTY`, 0) - COALESCE(vt.`VEN_QTY_ALB`, 0)) <> 0,
                     (COALESCE(vt.`VEN_IMPORTE`, 0)
                     - COALESCE(vt.`VEN_IMPORTE_ALB`, 0))
                     / (COALESCE(vt.`VEN_QTY`, 0) - COALESCE(vt.`VEN_QTY_ALB`, 0)), 0)
                WHEN p.`BANDA` = 'VEN' THEN
                  IF(COALESCE(vt.`VEN_QTY`, 0) <> 0,
                     COALESCE(vt.`VEN_IMPORTE`, 0) / vt.`VEN_QTY`, 0)
                WHEN p.`BANDA` = 'AVIFAC' THEN 0
                WHEN p.`ES_COSTE` = 1 THEN
                  IFNULL(p.`IMPORTE_COSTE` / NULLIF(p.`CANTIDAD`, 0), 0)
                ELSE COALESCE(pvp.`PVP`, 0)
              END, 2)                                 AS `PRECIO`,



        ROUND(CASE
                WHEN p.`BANDA` = 'SALALB' THEN
                  COALESCE(vt.`VEN_IMPORTE_ALB`, 0)
                WHEN p.`BANDA` = 'VEN' AND v_desglosado THEN
                  (COALESCE(vt.`VEN_IMPORTE`, 0)
                     - COALESCE(vt.`VEN_IMPORTE_ALB`, 0))
                WHEN p.`BANDA` = 'VEN' THEN COALESCE(vt.`VEN_IMPORTE`, 0)
                WHEN p.`BANDA` = 'AVIFAC' THEN 0
                WHEN p.`ES_COSTE` = 1 THEN p.`IMPORTE_COSTE`
                ELSE p.`CANTIDAD` * COALESCE(pvp.`PVP`, 0)
              END, 2)                                 AS `IMPORTE`,




        ROUND(CASE
                WHEN p.`BANDA` = 'SALALB' THEN
                  COALESCE(vt.`VEN_IMPORTE_ALB`, 0)
                WHEN p.`BANDA` = 'VEN' AND v_desglosado THEN
                  (COALESCE(vt.`VEN_IMPORTE`, 0)
                     - COALESCE(vt.`VEN_IMPORTE_ALB`, 0))
                WHEN p.`BANDA` = 'VEN' THEN COALESCE(vt.`VEN_IMPORTE`, 0)
                ELSE 0
              END, 2)
                                                      AS `VENTAS`,



        IF(p.`BANDA` = 'EXIFIN', p.`CANTIDAD`, 0)     AS `EXIFIN_CANT`,
        ROUND(IF(p.`BANDA` = 'EXIFIN',
                 p.`IMPORTE_COSTE`,
                 0), 2)                               AS `EXIFIN_IMP`,




        CASE p_NIVEL1
            WHEN 'PRV' THEN IF(v_por_prv, SUBSTRING_INDEX(p.`CODIGO_ALM`, CHAR(31 USING utf8mb4), -1), COALESCE(prov.`CODIGO_PRV`, ''))
            WHEN 'FAM' THEN COALESCE(fg.`COD_GRP`, art.`CODIGO_FAM_ART`)
            WHEN 'TMP' THEN COALESCE(tmp.`TEMPORADA`, '')
            WHEN 'ALM' THEN SUBSTRING_INDEX(p.`CODIGO_ALM`, CHAR(31 USING utf8mb4), 1)
            ELSE ''
        END                                           AS `GRUPO1_COD`,
        CASE p_NIVEL1
            WHEN 'PRV' THEN CONCAT('Proveedor: ',
                 COALESCE(NULLIF(gprv.`RAZON_SOCIAL_PRV`, ''),
                          NULLIF(SUBSTRING_INDEX(p.`CODIGO_ALM`, CHAR(31 USING utf8mb4), -1), ''),
                          '(sin proveedor)'))
            WHEN 'FAM' THEN CONCAT('Familia: ',
                 COALESCE(fg.`DESC_GRP`, fg.`COD_GRP`,
                          art.`CODIGO_FAM_ART`))
            WHEN 'TMP' THEN CONCAT('Temporada: ',
                 COALESCE(NULLIF(tmp.`TEMPORADA`, ''), '(sin temporada)'))
            WHEN 'ALM' THEN CONCAT('Almacén: ',
                 COALESCE(NULLIF(alm.`NOMBRE_ALM_ALM`, ''), SUBSTRING_INDEX(p.`CODIGO_ALM`, CHAR(31 USING utf8mb4), 1),
                          '(sin almacén)'))
            ELSE ''
        END                                           AS `GRUPO1_ETIQ`,
        CASE p_NIVEL2
            WHEN 'PRV' THEN IF(v_por_prv, SUBSTRING_INDEX(p.`CODIGO_ALM`, CHAR(31 USING utf8mb4), -1), COALESCE(prov.`CODIGO_PRV`, ''))
            WHEN 'FAM' THEN COALESCE(fg.`COD_GRP`, art.`CODIGO_FAM_ART`)
            WHEN 'TMP' THEN COALESCE(tmp.`TEMPORADA`, '')
            WHEN 'ALM' THEN SUBSTRING_INDEX(p.`CODIGO_ALM`, CHAR(31 USING utf8mb4), 1)
            ELSE ''
        END                                           AS `GRUPO2_COD`,
        CASE p_NIVEL2
            WHEN 'PRV' THEN CONCAT('Proveedor: ',
                 COALESCE(NULLIF(gprv.`RAZON_SOCIAL_PRV`, ''),
                          NULLIF(SUBSTRING_INDEX(p.`CODIGO_ALM`, CHAR(31 USING utf8mb4), -1), ''),
                          '(sin proveedor)'))
            WHEN 'FAM' THEN CONCAT('Familia: ',
                 COALESCE(fg.`DESC_GRP`, fg.`COD_GRP`,
                          art.`CODIGO_FAM_ART`))
            WHEN 'TMP' THEN CONCAT('Temporada: ',
                 COALESCE(NULLIF(tmp.`TEMPORADA`, ''), '(sin temporada)'))
            WHEN 'ALM' THEN CONCAT('Almacén: ',
                 COALESCE(NULLIF(alm.`NOMBRE_ALM_ALM`, ''), SUBSTRING_INDEX(p.`CODIGO_ALM`, CHAR(31 USING utf8mb4), 1),
                          '(sin almacén)'))
            ELSE ''
        END                                           AS `GRUPO2_ETIQ`,
        CASE p_NIVEL3
            WHEN 'PRV' THEN IF(v_por_prv, SUBSTRING_INDEX(p.`CODIGO_ALM`, CHAR(31 USING utf8mb4), -1), COALESCE(prov.`CODIGO_PRV`, ''))
            WHEN 'FAM' THEN COALESCE(fg.`COD_GRP`, art.`CODIGO_FAM_ART`)
            WHEN 'TMP' THEN COALESCE(tmp.`TEMPORADA`, '')
            WHEN 'ALM' THEN SUBSTRING_INDEX(p.`CODIGO_ALM`, CHAR(31 USING utf8mb4), 1)
            ELSE ''
        END                                           AS `GRUPO3_COD`,
        CASE p_NIVEL3
            WHEN 'PRV' THEN CONCAT('Proveedor: ',
                 COALESCE(NULLIF(gprv.`RAZON_SOCIAL_PRV`, ''),
                          NULLIF(SUBSTRING_INDEX(p.`CODIGO_ALM`, CHAR(31 USING utf8mb4), -1), ''),
                          '(sin proveedor)'))
            WHEN 'FAM' THEN CONCAT('Familia: ',
                 COALESCE(fg.`DESC_GRP`, fg.`COD_GRP`,
                          art.`CODIGO_FAM_ART`))
            WHEN 'TMP' THEN CONCAT('Temporada: ',
                 COALESCE(NULLIF(tmp.`TEMPORADA`, ''), '(sin temporada)'))
            WHEN 'ALM' THEN CONCAT('Almacén: ',
                 COALESCE(NULLIF(alm.`NOMBRE_ALM_ALM`, ''), SUBSTRING_INDEX(p.`CODIGO_ALM`, CHAR(31 USING utf8mb4), 1),
                          '(sin almacén)'))
            ELSE ''
        END                                           AS `GRUPO3_ETIQ`
      FROM (
            SELECT m.`CODIGO_ART`, m.`CODIGO_ALM`, m.`CLAVE_FILA`,
                   (m.`POSICION` - 1) DIV 14 + 1 AS `BLOQUE_TALLAS`,
                   MIN(m.`COLOR_HEX`) AS `COLOR_HEX`,
                   MIN(m.`ORDEN_COLOR`) AS `ORDEN_COLOR`,
                   m.`BANDA`, m.`ORDEN_BANDA`, m.`ETIQUETA_BANDA`, m.`ES_COSTE`,
                   SUM(IF(MOD(m.`POSICION` - 1, 14) + 1 =  1, m.`CANTIDAD`, 0)) AS `T01`,
                   SUM(IF(MOD(m.`POSICION` - 1, 14) + 1 =  2, m.`CANTIDAD`, 0)) AS `T02`,
                   SUM(IF(MOD(m.`POSICION` - 1, 14) + 1 =  3, m.`CANTIDAD`, 0)) AS `T03`,
                   SUM(IF(MOD(m.`POSICION` - 1, 14) + 1 =  4, m.`CANTIDAD`, 0)) AS `T04`,
                   SUM(IF(MOD(m.`POSICION` - 1, 14) + 1 =  5, m.`CANTIDAD`, 0)) AS `T05`,
                   SUM(IF(MOD(m.`POSICION` - 1, 14) + 1 =  6, m.`CANTIDAD`, 0)) AS `T06`,
                   SUM(IF(MOD(m.`POSICION` - 1, 14) + 1 =  7, m.`CANTIDAD`, 0)) AS `T07`,
                   SUM(IF(MOD(m.`POSICION` - 1, 14) + 1 =  8, m.`CANTIDAD`, 0)) AS `T08`,
                   SUM(IF(MOD(m.`POSICION` - 1, 14) + 1 =  9, m.`CANTIDAD`, 0)) AS `T09`,
                   SUM(IF(MOD(m.`POSICION` - 1, 14) + 1 = 10, m.`CANTIDAD`, 0)) AS `T10`,
                   SUM(IF(MOD(m.`POSICION` - 1, 14) + 1 = 11, m.`CANTIDAD`, 0)) AS `T11`,
                   SUM(IF(MOD(m.`POSICION` - 1, 14) + 1 = 12, m.`CANTIDAD`, 0)) AS `T12`,
                   SUM(IF(MOD(m.`POSICION` - 1, 14) + 1 = 13, m.`CANTIDAD`, 0)) AS `T13`,
                   SUM(IF(MOD(m.`POSICION` - 1, 14) + 1 = 14, m.`CANTIDAD`, 0)) AS `T14`,
                   SUM(m.`CANTIDAD`) AS `CANTIDAD`,
                   SUM(m.`IMPORTE_COSTE`) AS `IMPORTE_COSTE`
              FROM `tmp_bat_medidas` m
             GROUP BY m.`CODIGO_ART`, m.`CODIGO_ALM`, m.`CLAVE_FILA`, m.`BANDA`,
                      m.`ORDEN_BANDA`, m.`ETIQUETA_BANDA`, m.`ES_COSTE`,
                      (m.`POSICION` - 1) DIV 14 + 1
           ) p
      JOIN `fza_articulos` art ON art.`CODIGO_ART_ART` = p.`CODIGO_ART`
      LEFT JOIN `fza_articulos_familias` fam
        ON fam.`CODIGO_FAM_FAM` = art.`CODIGO_FAM_ART`
      LEFT JOIN `tmp_bat_fam_grp` fg ON fg.`CODIGO_FAM` = art.`CODIGO_FAM_ART`
      LEFT JOIN `fza_almacenes` alm ON alm.`CODIGO_ALM_ALM` = SUBSTRING_INDEX(p.`CODIGO_ALM`, CHAR(31 USING utf8mb4), 1)
      
      LEFT JOIN `fza_proveedores` gprv
        ON v_por_prv AND gprv.`CODIGO_PRV_PRV` = SUBSTRING_INDEX(p.`CODIGO_ALM`, CHAR(31 USING utf8mb4), -1)
      LEFT JOIN `tmp_bat_etiq` et ON et.`CODIGO_ART` = p.`CODIGO_ART`
               AND et.`BLOQUE_TALLAS` = p.`BLOQUE_TALLAS`
      LEFT JOIN `tmp_bat_pvp` pvp ON pvp.`CODIGO_ART` = p.`CODIGO_ART`
                           AND pvp.`CLAVE_FILA` = p.`CLAVE_FILA`
      LEFT JOIN `tmp_bat_prov` prov ON prov.`CODIGO_ART` = p.`CODIGO_ART`




      LEFT JOIN `tmp_bat_tmp` tmp ON tmp.`CODIGO_ART` = p.`CODIGO_ART`
                AND tmp.`CLAVE_FILA` = p.`CLAVE_FILA`
      LEFT JOIN `tmp_bat_vt` vt ON vt.`CODIGO_ART` = p.`CODIGO_ART`
               AND vt.`CODIGO_ALM` = p.`CODIGO_ALM`
               AND vt.`CLAVE_FILA` = p.`CLAVE_FILA`
               AND vt.`BLOQUE_TALLAS` = p.`BLOQUE_TALLAS`
      LEFT JOIN `tmp_bat_nc` nc ON nc.`CODIGO_ART` = p.`CODIGO_ART`
               AND nc.`CLAVE_FILA` = p.`CLAVE_FILA`
     ORDER BY `GRUPO1_COD`, `GRUPO2_COD`, `GRUPO3_COD`,
              COALESCE(fam.`ORDEN_FAM`, 999999), art.`CODIGO_FAM_ART`,
              p.`CODIGO_ART`, p.`CODIGO_ALM`, p.`BLOQUE_TALLAS`, p.`ORDEN_COLOR`,
              JSON_UNQUOTE(JSON_EXTRACT(p.`CLAVE_FILA`, '$[0]')),
              CAST(JSON_EXTRACT(p.`CLAVE_FILA`, '$[3]') AS SIGNED),
              JSON_UNQUOTE(JSON_EXTRACT(p.`CLAVE_FILA`, '$[2]')),
              p.`ORDEN_BANDA`;

    DROP TEMPORARY TABLE IF EXISTS `tmp_bat_pvp`;
    DROP TEMPORARY TABLE IF EXISTS `tmp_bat_cst`;
    DROP TEMPORARY TABLE IF EXISTS `tmp_bat_prov`;
    DROP TEMPORARY TABLE IF EXISTS `tmp_bat_tmp`;
    DROP TEMPORARY TABLE IF EXISTS `tmp_bat_vt`;
    DROP TEMPORARY TABLE IF EXISTS `tmp_bat_fal`;
    DROP TEMPORARY TABLE IF EXISTS `tmp_bat_medidas`;
    DROP TEMPORARY TABLE IF EXISTS `tmp_bat_marcas`;
    DROP TEMPORARY TABLE IF EXISTS `tmp_bat_ven`;
    DROP TEMPORARY TABLE IF EXISTS `tmp_bat_base`;
    DROP TEMPORARY TABLE IF EXISTS `tmp_bat_vdep`;
    DROP TEMPORARY TABLE IF EXISTS `tmp_bat_nc`;
    DROP TEMPORARY TABLE IF EXISTS `tmp_bat_sku`;
    DROP TEMPORARY TABLE IF EXISTS `tmp_bat_etiq`;
    DROP TEMPORARY TABLE IF EXISTS `tmp_bat_pos_arts`;
    DROP TEMPORARY TABLE IF EXISTS `tmp_bat_pos`;
    DROP TEMPORARY TABLE IF EXISTS `tmp_bat_arts`;
    DROP TEMPORARY TABLE IF EXISTS `tmp_bat_fam_grp`;
    DROP TEMPORARY TABLE IF EXISTS `tmp_bat_fam`;
    DROP TEMPORARY TABLE IF EXISTS `tmp_bat_alm`;
END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_VALUE_ON_ZERO' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `PRC_GET_CAJA_STOCK_PIVOTADO` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_spanish_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_GET_CAJA_STOCK_PIVOTADO`(IN p_input VARCHAR(50))
BEGIN
    DECLARE v_codigo_articulo VARCHAR(20);
    DECLARE v_es_sku BOOLEAN DEFAULT FALSE;
    DECLARE v_id_atributo_pivot VARCHAR(20);
    DECLARE v_id_atributo_grupo VARCHAR(20);
    DECLARE v_valor_grupo_filtro VARCHAR(50) DEFAULT NULL;
    DECLARE v_columnas_dinamicas TEXT;
    DECLARE v_num_tallas INT DEFAULT 0;
    DECLARE v_columnas_con_stock TEXT;
    SELECT COALESCE(
        (SELECT CODIGO_ART_ART
           FROM fza_articulos
          WHERE CODIGO_ART_ART = p_input
          LIMIT 1),
        (SELECT CODIGO_ART_SKU
           FROM fza_articulos_skus
          WHERE CODIGO_UNIDAD_SKU = p_input
          LIMIT 1)
    ) INTO v_codigo_articulo;
    IF v_codigo_articulo IS NOT NULL AND v_codigo_articulo <> p_input THEN
        SET v_es_sku = TRUE;
    END IF;
    IF v_codigo_articulo IS NOT NULL THEN
        SELECT vat.ID_ATB_VA
          INTO v_id_atributo_pivot
          FROM fza_articulos art
          JOIN VI_VARIACIONES_EJES vat
            ON vat.ID_VAR_VA = art.TIPO_VARIACION_ART
          JOIN fza_variaciones_atributos V
            ON V.ID_VAR_VA = vat.ID_VAR_VA
           AND V.ID_ATB_VA = vat.ID_ATB_VA
         WHERE art.CODIGO_ART_ART = v_codigo_articulo
         AND vat.EJE_VA = 'P'
         LIMIT 1;
        SELECT vat.ID_ATB_VA
          INTO v_id_atributo_grupo
          FROM fza_articulos art
          JOIN VI_VARIACIONES_EJES vat
            ON vat.ID_VAR_VA = art.TIPO_VARIACION_ART
          JOIN fza_variaciones_atributos V
            ON V.ID_VAR_VA = vat.ID_VAR_VA
           AND V.ID_ATB_VA = vat.ID_ATB_VA
         WHERE art.CODIGO_ART_ART = v_codigo_articulo
           AND vat.EJE_VA = 'F'
         LIMIT 1;
    END IF;
    IF v_id_atributo_pivot IS NOT NULL THEN
        IF v_es_sku = TRUE AND v_id_atributo_grupo IS NOT NULL THEN
            SET v_valor_grupo_filtro = (
                SELECT av.AV
                  FROM fza_atributos_sku ask
                  JOIN fza_atributos_valores av
                    ON ask.ID_AV_SA = av.ID_AV
                 WHERE ask.CODIGO_UNIDAD_SKU_SA = p_input
                   AND av.ID_VA_AV = v_id_atributo_grupo
                 LIMIT 1
            );
        END IF;
        SELECT COUNT(*), GROUP_CONCAT(DISTINCT
            CONCAT(
                'SUM(CASE WHEN av_p.AV = ''',
                REPLACE(t.AV, '''', ''''''),
                ''' THEN stk.CANTIDAD_STK ELSE 0 END) AS `',
                REPLACE(t.AV, '`', '``'), '`'
            )
            ORDER BY t.BLOQUE, t.ORDEN_TALLA, t.ID_AV
        ), GROUP_CONCAT(DISTINCT
            CASE WHEN t.CON_STOCK = 1 THEN
                CONCAT(
                    'SUM(CASE WHEN av_p.AV = ''',
                    REPLACE(t.AV, '''', ''''''),
                    ''' THEN stk.CANTIDAD_STK ELSE 0 END) AS `',
                    REPLACE(t.AV, '`', '``'), '`'
                )
            END
            ORDER BY t.BLOQUE, t.ORDEN_TALLA, t.ID_AV
        ) INTO v_num_tallas, v_columnas_dinamicas,
               v_columnas_con_stock
        FROM (
            SELECT AV.AV, MIN(AV.ID_AV) AS ID_AV,
                   MAX(CASE WHEN EXISTS (
                       SELECT 1 FROM fza_articulos_skus SKE
                       JOIN fza_atributos_sku SAE
                         ON SAE.CODIGO_UNIDAD_SKU_SA =
                            SKE.CODIGO_UNIDAD_SKU
                       JOIN fza_articulos_stockactual STE
                         ON STE.CODIGO_UNIDAD_STK =
                            SKE.CODIGO_UNIDAD_SKU
                       WHERE SKE.CODIGO_ART_SKU = v_codigo_articulo
                         AND SAE.ID_AV_SA = AV.ID_AV
                         AND STE.CANTIDAD_STK <> 0)
                        THEN 1 ELSE 0 END) AS CON_STOCK,
                   CASE WHEN COUNT(ACD.ID_AV_ACD) > 0
                        THEN 0 ELSE 1 END AS BLOQUE,
                   COALESCE(MIN(AAB.ORDEN_AAB), MIN(ACD.ORDEN_ACD),
                            MIN(AV.ORDEN_AV)) AS ORDEN_TALLA
              FROM fza_atributos_valores AV
              LEFT JOIN fza_articulos_atributos_basicos AAB
                ON AAB.CODIGO_ART_AAB = v_codigo_articulo
               AND AAB.ID_AV_AAB = AV.ID_AV
              LEFT JOIN fza_articulos_conjuntos_asign ACA
                ON ACA.CODIGO_ART_ACA = v_codigo_articulo
               AND ACA.ID_VA_ACA = AV.ID_VA_AV
              LEFT JOIN fza_atributos_conjuntos_det ACD
                ON ACD.ID_AC_ACD = ACA.ID_AC_ACA
               AND ACD.ID_AV_ACD = AV.ID_AV
             WHERE AV.ID_VA_AV = v_id_atributo_pivot
               AND (ACD.ID_AV_ACD IS NOT NULL OR EXISTS (
                   SELECT 1 FROM fza_articulos_skus SK
                   JOIN fza_atributos_sku SA
                     ON SA.CODIGO_UNIDAD_SKU_SA = SK.CODIGO_UNIDAD_SKU
                   WHERE SK.CODIGO_ART_SKU = v_codigo_articulo
                     AND SA.ID_AV_SA = AV.ID_AV))
             GROUP BY AV.AV
        ) t;
        
        
        
        IF v_num_tallas > 21 THEN
            SET v_columnas_dinamicas = v_columnas_con_stock;
        END IF;
        IF v_columnas_dinamicas IS NOT NULL THEN
            SET @sql = CONCAT(
                'SELECT
                    CONCAT(''', v_codigo_articulo, ''',
                        CASE
                            WHEN av_g.AV IS NOT NULL THEN CONCAT(''/'', av_g.AV)
                            ELSE ''''
                        END
                    ) AS Codigo,
                    alm.NOMBRE_ALM_ALM AS Almacen, ',
                    v_columnas_dinamicas, ',
                    SUM(stk.CANTIDAD_STK) AS Total
                 FROM fza_articulos_stockactual stk
                 JOIN fza_almacenes alm
                   ON stk.CODIGO_ALM_STK = alm.CODIGO_ALM_ALM
                 JOIN fza_articulos_skus sk
                   ON stk.CODIGO_UNIDAD_STK = sk.CODIGO_UNIDAD_SKU
                 JOIN fza_atributos_sku ask_p
                   ON sk.CODIGO_UNIDAD_SKU = ask_p.CODIGO_UNIDAD_SKU_SA
                 JOIN fza_atributos_valores av_p
                   ON ask_p.ID_AV_SA = av_p.ID_AV
                  AND av_p.ID_VA_AV = ''', v_id_atributo_pivot, '''
                 LEFT JOIN fza_atributos_sku ask_g
                   ON sk.CODIGO_UNIDAD_SKU = ask_g.CODIGO_UNIDAD_SKU_SA
                 LEFT JOIN fza_atributos_valores av_g
                   ON ask_g.ID_AV_SA = av_g.ID_AV
                  AND av_g.ID_VA_AV = ''',
                    IFNULL(v_id_atributo_grupo, 'xxx'), '''
                 WHERE sk.CODIGO_ART_SKU = ''', v_codigo_articulo, ''' ',
                 CASE WHEN v_valor_grupo_filtro IS NOT NULL THEN
                    CONCAT(' AND av_g.AV = ''',
                           REPLACE(v_valor_grupo_filtro, '''', ''''''), ''' ')
                 ELSE '' END, '
                 GROUP BY av_g.AV, alm.NOMBRE_ALM_ALM
                 ORDER BY alm.NOMBRE_ALM_ALM, av_g.AV'
            );
            PREPARE stmt FROM @sql;
            EXECUTE stmt;
            DEALLOCATE PREPARE stmt;
        END IF;
    END IF;
    IF v_columnas_dinamicas IS NULL THEN
        SELECT stk.CODIGO_UNIDAD_STK AS Codigo,
               alm.NOMBRE_ALM_ALM AS Almacen,
               SUM(stk.CANTIDAD_STK) AS Stock_Total
          FROM fza_articulos_stockactual stk
          JOIN fza_almacenes alm
            ON stk.CODIGO_ALM_STK = alm.CODIGO_ALM_ALM
         WHERE stk.CODIGO_UNIDAD_STK = p_input
         GROUP BY stk.CODIGO_UNIDAD_STK, alm.NOMBRE_ALM_ALM
         ORDER BY alm.NOMBRE_ALM_ALM;
    END IF;
END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_VALUE_ON_ZERO' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `PRC_GET_CAJA_STOCK_PIVOTADO_WITHZ` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_spanish_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_GET_CAJA_STOCK_PIVOTADO_WITHZ`(IN p_input VARCHAR(50))
BEGIN
    DECLARE v_codigo_articulo VARCHAR(20);
    DECLARE v_es_sku BOOLEAN DEFAULT FALSE;
    DECLARE v_id_atributo_pivot VARCHAR(20);
    DECLARE v_nombre_atributo_pivot VARCHAR(50);
    DECLARE v_columnas_dinamicas TEXT;
    DECLARE v_num_tallas INT DEFAULT 0;
    DECLARE v_columnas_con_stock TEXT;
    DECLARE v_id_atributo_fila VARCHAR(20) DEFAULT NULL;
    DECLARE v_nombre_atributo_fila VARCHAR(50) DEFAULT NULL;
    DECLARE v_select_fila TEXT DEFAULT '';
    DECLARE v_join_fila TEXT DEFAULT '';
    DECLARE v_groupby_fila TEXT DEFAULT '';
    DECLARE v_src_select_fila TEXT DEFAULT '';
    DECLARE v_filtros_fijos TEXT DEFAULT '';
    DECLARE v_sql_query TEXT;
    SELECT COALESCE(
        (SELECT CODIGO_ART_ART
           FROM fza_articulos
          WHERE CODIGO_ART_ART = p_input
          LIMIT 1),
        (SELECT CODIGO_ART_SKU
           FROM fza_articulos_skus
          WHERE CODIGO_UNIDAD_SKU = p_input
          LIMIT 1)
    ) INTO v_codigo_articulo;
    IF v_codigo_articulo IS NOT NULL AND v_codigo_articulo <> p_input THEN
        SET v_es_sku = TRUE;
    END IF;
    IF v_codigo_articulo IS NOT NULL THEN
        SELECT vat.ID_ATB_VA, V.NOMBRE_VA
          INTO v_id_atributo_pivot, v_nombre_atributo_pivot
          FROM fza_articulos art
          JOIN VI_VARIACIONES_EJES vat
            ON vat.ID_VAR_VA = art.TIPO_VARIACION_ART
          JOIN fza_variaciones_atributos V
            ON V.ID_VAR_VA = vat.ID_VAR_VA
           AND V.ID_ATB_VA = vat.ID_ATB_VA
         WHERE art.CODIGO_ART_ART = v_codigo_articulo
         AND vat.EJE_VA = 'P'
         LIMIT 1;
    END IF;
    IF v_codigo_articulo IS NOT NULL AND v_es_sku = FALSE THEN
        SELECT vat.ID_ATB_VA, V.NOMBRE_VA
          INTO v_id_atributo_fila, v_nombre_atributo_fila
          FROM fza_articulos art
          JOIN VI_VARIACIONES_EJES vat
            ON vat.ID_VAR_VA = art.TIPO_VARIACION_ART
          JOIN fza_variaciones_atributos V
            ON V.ID_VAR_VA = vat.ID_VAR_VA
           AND V.ID_ATB_VA = vat.ID_ATB_VA
         WHERE art.CODIGO_ART_ART = v_codigo_articulo
           AND vat.EJE_VA = 'F'
         LIMIT 1;
    END IF;
    IF v_id_atributo_pivot IS NOT NULL THEN
        IF v_id_atributo_fila IS NOT NULL THEN
            SET v_select_fila = CONCAT(
                ', COALESCE(src.VALOR_FILA, ''-'') AS `',
                v_nombre_atributo_fila, '`');
            SET v_src_select_fila = ', av_fila.AV AS VALOR_FILA';
            SET v_join_fila = CONCAT(
                ' LEFT JOIN fza_atributos_sku ask_fila',
                ' ON sk.CODIGO_UNIDAD_SKU = ask_fila.CODIGO_UNIDAD_SKU_SA',
                ' LEFT JOIN fza_atributos_valores av_fila',
                ' ON ask_fila.ID_AV_SA = av_fila.ID_AV',
                ' AND av_fila.ID_VA_AV = ''', v_id_atributo_fila, ''' ');
            SET v_groupby_fila = ', src.VALOR_FILA';
        END IF;
        SELECT COUNT(*), GROUP_CONCAT(DISTINCT
            CONCAT(
                'SUM(CASE WHEN src.AV = ''', REPLACE(t.AV, '''', ''''''),
                ''' THEN src.CANTIDAD_STK ELSE 0 END) AS `',
                REPLACE(t.AV, '`', '``'), '`'
            )
            ORDER BY t.BLOQUE, t.ORDEN_TALLA, t.ID_AV
        ), GROUP_CONCAT(DISTINCT
            CASE WHEN t.CON_STOCK = 1 THEN
                CONCAT(
                    'SUM(CASE WHEN src.AV = ''', REPLACE(t.AV, '''', ''''''),
                    ''' THEN src.CANTIDAD_STK ELSE 0 END) AS `',
                    REPLACE(t.AV, '`', '``'), '`'
                )
            END
            ORDER BY t.BLOQUE, t.ORDEN_TALLA, t.ID_AV
        ) INTO v_num_tallas, v_columnas_dinamicas,
               v_columnas_con_stock
        FROM (
            SELECT AV.AV, MIN(AV.ID_AV) AS ID_AV,
                   MAX(CASE WHEN EXISTS (
                       SELECT 1 FROM fza_articulos_skus SKE
                       JOIN fza_atributos_sku SAE
                         ON SAE.CODIGO_UNIDAD_SKU_SA =
                            SKE.CODIGO_UNIDAD_SKU
                       JOIN fza_articulos_stockactual STE
                         ON STE.CODIGO_UNIDAD_STK =
                            SKE.CODIGO_UNIDAD_SKU
                       WHERE SKE.CODIGO_ART_SKU = v_codigo_articulo
                         AND SAE.ID_AV_SA = AV.ID_AV
                         AND STE.CANTIDAD_STK <> 0)
                        THEN 1 ELSE 0 END) AS CON_STOCK,
                   CASE WHEN COUNT(ACD.ID_AV_ACD) > 0
                        THEN 0 ELSE 1 END AS BLOQUE,
                   COALESCE(MIN(AAB.ORDEN_AAB), MIN(ACD.ORDEN_ACD),
                            MIN(AV.ORDEN_AV)) AS ORDEN_TALLA
              FROM fza_atributos_valores AV
              LEFT JOIN fza_articulos_atributos_basicos AAB
                ON AAB.CODIGO_ART_AAB = v_codigo_articulo
               AND AAB.ID_AV_AAB = AV.ID_AV
              LEFT JOIN fza_articulos_conjuntos_asign ACA
                ON ACA.CODIGO_ART_ACA = v_codigo_articulo
               AND ACA.ID_VA_ACA = AV.ID_VA_AV
              LEFT JOIN fza_atributos_conjuntos_det ACD
                ON ACD.ID_AC_ACD = ACA.ID_AC_ACA
               AND ACD.ID_AV_ACD = AV.ID_AV
             WHERE AV.ID_VA_AV = v_id_atributo_pivot
               AND (ACD.ID_AV_ACD IS NOT NULL OR EXISTS (
                   SELECT 1 FROM fza_articulos_skus SK
                   JOIN fza_atributos_sku SA
                     ON SA.CODIGO_UNIDAD_SKU_SA = SK.CODIGO_UNIDAD_SKU
                   WHERE SK.CODIGO_ART_SKU = v_codigo_articulo
                     AND SA.ID_AV_SA = AV.ID_AV))
             GROUP BY AV.AV
        ) t;
        
        
        
        IF v_num_tallas > 21 THEN
            SET v_columnas_dinamicas = v_columnas_con_stock;
        END IF;
        IF v_es_sku = TRUE THEN
            SELECT GROUP_CONCAT(
                CONCAT(
                    ' AND EXISTS (SELECT 1 FROM fza_atributos_sku f_ask ',
                    ' JOIN fza_atributos_valores f_av',
                    ' ON f_ask.ID_AV_SA = f_av.ID_AV ',
                    ' WHERE f_ask.CODIGO_UNIDAD_SKU_SA = sk.CODIGO_UNIDAD_SKU ',
                    ' AND f_av.ID_VA_AV = ''', av.ID_VA_AV, ''' ',
                    ' AND f_av.AV = ''', av.AV, ''') '
                ) SEPARATOR ' '
            ) INTO v_filtros_fijos
              FROM fza_atributos_sku ask
              JOIN fza_atributos_valores av
                ON ask.ID_AV_SA = av.ID_AV
             WHERE ask.CODIGO_UNIDAD_SKU_SA = p_input
               AND av.ID_VA_AV <> v_id_atributo_pivot;
        END IF;
        IF v_filtros_fijos IS NULL THEN
            SET v_filtros_fijos = '';
        END IF;
        IF v_columnas_dinamicas IS NOT NULL THEN
            SET @sql = CONCAT(
                'SELECT
                    alm.NOMBRE_ALM_ALM AS Almacen',
                    v_select_fila, ', ',
                    v_columnas_dinamicas, ',
                    COALESCE(SUM(src.CANTIDAD_STK), 0) AS Total,
                    COALESCE(SUM(src.PTE_TRASPASAR), 0) AS `Pte. traspasar`,
                    COALESCE(SUM(src.PTE_RECIBIR), 0)
                      AS `Pte. recibir trasp.`,
                    COALESCE(SUM(src.CANTIDAD_STK), 0) -
                      COALESCE(SUM(src.PTE_TRASPASAR), 0) AS Disponible,
                    alm.CODIGO_ALM_ALM AS CODIGO_ALM_STOCK
                 FROM fza_almacenes alm
                 LEFT JOIN (
                    SELECT stk.CODIGO_ALM_STK, av.AV, stk.CANTIDAD_STK,
                           0 AS PTE_TRASPASAR, 0 AS PTE_RECIBIR',
                    v_src_select_fila, '
                    FROM fza_articulos_stockactual stk
                    JOIN fza_articulos_skus sk
                      ON stk.CODIGO_UNIDAD_STK = sk.CODIGO_UNIDAD_SKU
                    JOIN fza_atributos_sku ask
                      ON sk.CODIGO_UNIDAD_SKU = ask.CODIGO_UNIDAD_SKU_SA
                    JOIN fza_atributos_valores av
                      ON ask.ID_AV_SA = av.ID_AV',
                    v_join_fila, '
                    WHERE sk.CODIGO_ART_SKU = ''', v_codigo_articulo, '''
                      AND av.ID_VA_AV = ''', v_id_atributo_pivot, ''' ',
                      v_filtros_fijos, '
                    UNION ALL
                    SELECT pt.CODIGO_ALM_ALM, av.AV, 0,
                           pt.CANTIDAD_PTE_TRASPASAR,
                           pt.CANTIDAD_PTE_RECTRASPASAR',
                    v_src_select_fila, '
                    FROM vi_articulos_pdte_traspaso pt
                    JOIN fza_articulos_skus sk
                      ON pt.CODIGO_UNIDAD_SKU = sk.CODIGO_UNIDAD_SKU
                    JOIN fza_atributos_sku ask
                      ON sk.CODIGO_UNIDAD_SKU = ask.CODIGO_UNIDAD_SKU_SA
                    JOIN fza_atributos_valores av
                      ON ask.ID_AV_SA = av.ID_AV',
                    v_join_fila, '
                    WHERE sk.CODIGO_ART_SKU = ''', v_codigo_articulo, '''
                      AND av.ID_VA_AV = ''', v_id_atributo_pivot, ''' ',
                      v_filtros_fijos, '
                 ) src ON alm.CODIGO_ALM_ALM = src.CODIGO_ALM_STK
                 WHERE alm.ESACTIVO_ALM = ''S''
                 GROUP BY alm.NOMBRE_ALM_ALM, alm.CODIGO_ALM_ALM',
                 v_groupby_fila, '
                 ORDER BY alm.NOMBRE_ALM_ALM', v_groupby_fila
            );
            PREPARE stmt FROM @sql;
            EXECUTE stmt;
            DEALLOCATE PREPARE stmt;
        END IF;
    END IF;
    IF v_id_atributo_pivot IS NULL OR v_columnas_dinamicas IS NULL THEN
        SELECT alm.NOMBRE_ALM_ALM AS Almacen,
               COALESCE(SUM(stk.CANTIDAD_STK), 0) AS `Stock Total`,
               (SELECT COALESCE(SUM(pt.CANTIDAD_PTE_TRASPASAR), 0)
                  FROM vi_articulos_pdte_traspaso pt
                 WHERE pt.CODIGO_ALM_ALM = alm.CODIGO_ALM_ALM
                   AND pt.CODIGO_UNIDAD_SKU = p_input) AS `Pte. traspasar`,
               (SELECT COALESCE(SUM(pt.CANTIDAD_PTE_RECTRASPASAR), 0)
                  FROM vi_articulos_pdte_traspaso pt
                 WHERE pt.CODIGO_ALM_ALM = alm.CODIGO_ALM_ALM
                   AND pt.CODIGO_UNIDAD_SKU = p_input)
                 AS `Pte. recibir trasp.`,
               COALESCE(SUM(stk.CANTIDAD_STK), 0) -
               (SELECT COALESCE(SUM(pt.CANTIDAD_PTE_TRASPASAR), 0)
                  FROM vi_articulos_pdte_traspaso pt
                 WHERE pt.CODIGO_ALM_ALM = alm.CODIGO_ALM_ALM
                   AND pt.CODIGO_UNIDAD_SKU = p_input) AS Disponible,
               alm.CODIGO_ALM_ALM AS CODIGO_ALM_STOCK
          FROM fza_almacenes alm
          LEFT JOIN fza_articulos_stockactual stk
            ON alm.CODIGO_ALM_ALM = stk.CODIGO_ALM_STK
           AND stk.CODIGO_UNIDAD_STK = p_input
         WHERE alm.ESACTIVO_ALM = 'S'
         GROUP BY alm.NOMBRE_ALM_ALM, alm.CODIGO_ALM_ALM
         ORDER BY alm.NOMBRE_ALM_ALM;
    END IF;
END
;;
DELIMITER ;
