CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_GET_CREAR_VALOR`(IN `p_id_va` VARCHAR(20),       
    IN `p_valor` VARCHAR(100),      
    IN `p_usuario` VARCHAR(100),    
    OUT `p_id_resultado` INT)
BEGIN
    
    SELECT `ID_AV` INTO p_id_resultado
    FROM `fza_atributos_valores`
    WHERE `ID_VA_AV` = p_id_va 
      AND UPPER(`AV`) = UPPER(p_valor) 
    LIMIT 1;

    
    IF p_id_resultado IS NULL THEN
        INSERT INTO `fza_atributos_valores` (
            `ID_VA_AV`, 
            `AV`, 
            `USUARIO_ALTA`, 
            `USUARIO_MODIF`, 
            `INSTANTE_ALTA`
        ) VALUES (
            p_id_va, 
            p_valor, 
            p_usuario, 
            p_usuario, 
            NOW()
        );
        
        
        SET p_id_resultado = LAST_INSERT_ID();
    END IF;

    
END
;;
DELIMITER ;
