/*!50003 DROP PROCEDURE IF EXISTS `PRC_GET_MOV_VENTAS_ART` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_spanish_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_GET_MOV_VENTAS_ART`(
  IN p_DESDE date,
  IN p_HASTA date,
  IN p_INICIO_COMPRAS date,
  IN p_ALMACENES text,
  IN p_FAMILIAS text,
  IN p_PROVEEDORES text,
  IN p_TEMPORADAS text,
  IN p_ARTICULOS text,
  IN p_NIVEL1 varchar(3),
  IN p_NIVEL2 varchar(3),
  IN p_NIVEL3 varchar(3),
  IN p_NIVEL_FAM int(11),
  IN p_SOLO_VENTAS varchar(1),
  IN p_CON_IMPUESTOS varchar(1),
  IN p_ORDEN varchar(2),
  IN p_ORDEN_DESC varchar(1),
  IN p_ENTRADAS_GLOBALES varchar(1),
  IN p_TARIFA varchar(20),
  IN p_EMPRESA varchar(20)
)
BEGIN

    DECLARE v_desde      DATE;
    DECLARE v_hasta      DATE;
    DECLARE v_ini_cmp    DATE;
    DECLARE v_por_alm    BOOLEAN DEFAULT FALSE;
    
    DECLARE v_por_prv    BOOLEAN DEFAULT FALSE;
    DECLARE v_por_col    BOOLEAN DEFAULT FALSE;
    DECLARE v_por_tal    BOOLEAN DEFAULT FALSE;
    DECLARE v_por_copa   BOOLEAN DEFAULT FALSE;
    DECLARE v_filtra_cmp BOOLEAN DEFAULT FALSE;
    DECLARE v_ent_global BOOLEAN DEFAULT TRUE;
    DECLARE v_nivel_fam  INT;
    DECLARE v_tarifa     VARCHAR(20);
    DECLARE v_imp_incl   VARCHAR(1);
    DECLARE v_grupo_iva  VARCHAR(20);
    DECLARE v_iva_n      DECIMAL(9,4);
    DECLARE v_iva_r      DECIMAL(9,4);
    DECLARE v_iva_s      DECIMAL(9,4);
    DECLARE v_iva_e      DECIMAL(9,4);

    SET p_FAMILIAS    = IFNULL(p_FAMILIAS, '');
    SET p_PROVEEDORES = IFNULL(p_PROVEEDORES, '');
    SET p_TEMPORADAS  = IFNULL(p_TEMPORADAS, '');
    SET p_ARTICULOS   = IFNULL(p_ARTICULOS, '');
    SET p_SOLO_VENTAS = IFNULL(NULLIF(p_SOLO_VENTAS, ''), 'N');
    SET p_CON_IMPUESTOS = IF(
        UPPER(IFNULL(NULLIF(p_CON_IMPUESTOS, ''), 'S')) = 'N', 'N', 'S');
    SET p_ORDEN       = UPPER(IFNULL(p_ORDEN, ''));
    SET p_ORDEN_DESC  = IF(
        UPPER(IFNULL(NULLIF(p_ORDEN_DESC, ''), 'S')) = 'N', 'N', 'S');
    SET p_ENTRADAS_GLOBALES = IF(
        UPPER(IFNULL(NULLIF(p_ENTRADAS_GLOBALES, ''), 'S')) = 'N',
        'N', 'S');
    SET p_NIVEL1      = UPPER(IFNULL(p_NIVEL1, ''));
    SET p_NIVEL2      = UPPER(IFNULL(p_NIVEL2, ''));
    SET p_NIVEL3      = UPPER(IFNULL(p_NIVEL3, ''));
    SET v_por_alm     = (p_NIVEL1 = 'ALM' OR p_NIVEL2 = 'ALM'
                         OR p_NIVEL3 = 'ALM');
    SET v_por_prv     = (p_NIVEL1 = 'PRV' OR p_NIVEL2 = 'PRV' OR p_NIVEL3 = 'PRV');

    SET v_ent_global  = (p_ENTRADAS_GLOBALES = 'S' AND NOT v_por_alm);
    SET v_por_col     = (p_NIVEL1 = 'COL' OR p_NIVEL2 = 'COL'
                         OR p_NIVEL3 = 'COL');
    SET v_por_tal     = (p_NIVEL1 = 'TAL' OR p_NIVEL2 = 'TAL'
                         OR p_NIVEL3 = 'TAL');


    SET v_por_copa = (v_por_tal OR p_NIVEL1 = 'COP'
                       OR p_NIVEL2 = 'COP' OR p_NIVEL3 = 'COP');
    IF p_NIVEL1 = 'COP' OR p_NIVEL2 = 'COP' OR p_NIVEL3 = 'COP' THEN
        SET v_por_col = TRUE;
        SET v_por_tal = TRUE;
    END IF;
    SET v_nivel_fam   = IF(IFNULL(p_NIVEL_FAM, 0) < 1, 9999, p_NIVEL_FAM);
    SET v_desde       = IFNULL(p_DESDE, '1900-01-01');
    SET v_hasta       = IFNULL(p_HASTA, CURRENT_DATE);
    SET v_ini_cmp     = p_INICIO_COMPRAS;
    SET v_filtra_cmp  = (v_ini_cmp IS NOT NULL);
    IF p_ORDEN NOT IN ('AD', 'UE', 'IE', 'UV', 'IV', 'IC', 'IB',
                       'PB', 'VC', 'VE', 'M1', 'M2', 'VD', 'PV') THEN
        SET p_ORDEN = '';
    END IF;


    DROP TEMPORARY TABLE IF EXISTS `tmp_mva_salida`;

    DROP TEMPORARY TABLE IF EXISTS `tmp_mva_alm`;
    CREATE TEMPORARY TABLE `tmp_mva_alm` (
        `CODIGO_ALM` VARCHAR(20) NOT NULL PRIMARY KEY
    );
    INSERT IGNORE INTO `tmp_mva_alm` (`CODIGO_ALM`)
    SELECT `CODIGO_ALM_ALM`
      FROM `fza_almacenes`
     WHERE IF(IFNULL(p_ALMACENES, '') = '',
              `ESACTIVO_ALM` = 'S',
              FIND_IN_SET(`CODIGO_ALM_ALM`, p_ALMACENES));

    DROP TEMPORARY TABLE IF EXISTS `tmp_mva_fam`;
    CREATE TEMPORARY TABLE `tmp_mva_fam` (
        `CODIGO_FAM` VARCHAR(20) NOT NULL PRIMARY KEY
    );
    INSERT IGNORE INTO `tmp_mva_fam` (`CODIGO_FAM`)
    WITH RECURSIVE `fam_tree` AS (
        SELECT `CODIGO_FAM_FAM`
          FROM `fza_articulos_familias`
         WHERE FIND_IN_SET(`CODIGO_FAM_FAM`, p_FAMILIAS)
        UNION ALL
        SELECT f.`CODIGO_FAM_FAM`
          FROM `fza_articulos_familias` f
          JOIN `fam_tree` t ON f.`CODIGO_PADRE_FAM` = t.`CODIGO_FAM_FAM`
    )
    SELECT DISTINCT `CODIGO_FAM_FAM`
      FROM `fam_tree`;

    DROP TEMPORARY TABLE IF EXISTS `tmp_mva_fam_grp`;
    CREATE TEMPORARY TABLE `tmp_mva_fam_grp` (
        `CODIGO_FAM` VARCHAR(20)  NOT NULL PRIMARY KEY,
        `COD_GRP`    VARCHAR(20)  NOT NULL,
        `DESC_GRP`   VARCHAR(200) NULL
    );
    INSERT IGNORE INTO `tmp_mva_fam_grp`
        (`CODIGO_FAM`, `COD_GRP`, `DESC_GRP`)
    WITH RECURSIVE `fam_path` AS (
        SELECT `CODIGO_FAM_FAM` AS `COD`,
               CAST(`CODIGO_FAM_FAM` AS CHAR(1000)) AS `RUTA`
          FROM `fza_articulos_familias`
         WHERE `CODIGO_PADRE_FAM` IS NULL OR `CODIGO_PADRE_FAM` = ''
        UNION ALL
        SELECT f.`CODIGO_FAM_FAM`,
               CONCAT(pa.`RUTA`, '>', f.`CODIGO_FAM_FAM`)
          FROM `fza_articulos_familias` f
          JOIN `fam_path` pa ON f.`CODIGO_PADRE_FAM` = pa.`COD`
    )
    SELECT pa.`COD`,
           SUBSTRING_INDEX(SUBSTRING_INDEX(pa.`RUTA`, '>', v_nivel_fam),
                           '>', -1),
           NULL
      FROM `fam_path` pa;
    UPDATE `tmp_mva_fam_grp` g
      JOIN `fza_articulos_familias` f
        ON f.`CODIGO_FAM_FAM` = g.`COD_GRP`
       SET g.`DESC_GRP` = COALESCE(f.`DESCRIPCION_FAM`,
                                   f.`NOMBRE_FAM_FAM`, g.`COD_GRP`);




    DROP TEMPORARY TABLE IF EXISTS `tmp_mva_arts0`;
    CREATE TEMPORARY TABLE `tmp_mva_arts0` (
        `CODIGO_ART` VARCHAR(20) NOT NULL PRIMARY KEY
    );
    INSERT IGNORE INTO `tmp_mva_arts0` (`CODIGO_ART`)
    SELECT a.`CODIGO_ART_ART`
      FROM `fza_articulos` a
     WHERE a.`ESACTIVO_ART` = 'S'
       AND (p_ARTICULOS = ''
            OR FIND_IN_SET(a.`CODIGO_ART_ART`, p_ARTICULOS))
       AND (p_FAMILIAS = ''
            OR a.`CODIGO_FAM_ART` IN
               (SELECT `CODIGO_FAM` FROM `tmp_mva_fam`))
       AND (p_PROVEEDORES = ''
            OR EXISTS (
                SELECT 1
                  FROM `fza_articulos_proveedores` ap
                 WHERE ap.`CODIGO_ART_AP` = a.`CODIGO_ART_ART`
                   AND FIND_IN_SET(ap.`CODIGO_PRV_AP`, p_PROVEEDORES)
            ) OR EXISTS (SELECT 1 FROM fza_articulos_lotes LFA JOIN fza_articulos_skus SFA ON SFA.CODIGO_UNIDAD_SKU = LFA.CODIGO_UNIDAD_LOT WHERE SFA.CODIGO_ART_SKU = a.CODIGO_ART_ART AND FIND_IN_SET(LFA.CODIGO_PRV_LOT, p_PROVEEDORES) > 0))
       AND (p_TEMPORADAS = ''
            OR v_por_col
            OR EXISTS (
                SELECT 1
                  FROM `fza_articulos_propiedades` ta
                  LEFT JOIN `fza_propiedades_valores` tav
                    ON tav.`ID_PV_ARTPROP` = ta.`ID_PV_ARTPROP`
                 WHERE ta.`CODIGO_ART_ART` = a.`CODIGO_ART_ART`
                   AND ta.`CODIGO_PROP_ARTPROP` = 'TEMPORADA'
                   AND FIND_IN_SET(
                       COALESCE(tav.`PV`, ta.`VALOR_LIBRE_ARTPROP`),
                       p_TEMPORADAS)
            ));


    DROP TEMPORARY TABLE IF EXISTS `tmp_mva_skus`;
    CREATE TEMPORARY TABLE `tmp_mva_skus` (
        `CODIGO_UNIDAD` VARCHAR(50) NOT NULL PRIMARY KEY,
        `CODIGO_ART`    VARCHAR(20) NOT NULL,
        KEY `IDX_MVA_SKUS_ART` (`CODIGO_ART`)
    );
    INSERT INTO `tmp_mva_skus` (`CODIGO_UNIDAD`, `CODIGO_ART`)
    SELECT sku.`CODIGO_UNIDAD_SKU`, sku.`CODIGO_ART_SKU`
      FROM `fza_articulos_skus` sku
      JOIN `tmp_mva_arts0` a0
        ON a0.`CODIGO_ART` = sku.`CODIGO_ART_SKU`;




    DROP TEMPORARY TABLE IF EXISTS `tmp_mva_sku_color_elegido`;
    CREATE TEMPORARY TABLE `tmp_mva_sku_color_elegido` (
        `CODIGO_UNIDAD` VARCHAR(50)  NOT NULL PRIMARY KEY,
        `ID_AV`         INT          NOT NULL,
        `CLAVE_COLOR`   VARCHAR(100) NOT NULL,
        KEY `IDX_MVA_COLOR_ELEGIDO_CLAVE` (`CLAVE_COLOR`)
    );



    DROP TEMPORARY TABLE IF EXISTS `tmp_mva_color_global`;
    CREATE TEMPORARY TABLE `tmp_mva_color_global` (
        `CLAVE_COLOR` VARCHAR(100) NOT NULL PRIMARY KEY,
        `ID_COLOR`    INT          NOT NULL,
        `COLOR`       VARCHAR(100) NOT NULL,
        `ORDEN_COLOR` INT          NOT NULL DEFAULT 0,
        UNIQUE KEY `UK_MVA_COLOR_GLOBAL_ID` (`ID_COLOR`)
    );
    IF v_por_col THEN
        INSERT INTO `tmp_mva_sku_color_elegido`
            (`CODIGO_UNIDAD`, `ID_AV`, `CLAVE_COLOR`)
        SELECT elegido.`CODIGO_UNIDAD`, elegido.`ID_AV`,
               elegido.`CLAVE_COLOR`
          FROM (
                SELECT sac.`CODIGO_UNIDAD_SKU_SA` AS `CODIGO_UNIDAD`,
                       co.`ID_AV`, UPPER(TRIM(co.`AV`)) AS `CLAVE_COLOR`,
                       ROW_NUMBER() OVER (
                           PARTITION BY sac.`CODIGO_UNIDAD_SKU_SA`
                           ORDER BY COALESCE(co.`ORDEN_AV`, 0), co.`ID_AV`
                       ) AS `POSICION`
                  FROM `fza_atributos_sku` sac
                  JOIN `tmp_mva_skus` sku
                    ON sku.`CODIGO_UNIDAD` = sac.`CODIGO_UNIDAD_SKU_SA`
                  JOIN `fza_atributos_valores` co
                    ON co.`ID_AV` = sac.`ID_AV_SA`
                   AND co.`ID_VA_AV` = (SELECT EJ452.ID_ATB_VA FROM VI_VARIACIONES_EJES EJ452 WHERE EJ452.ID_VAR_VA = (SELECT SK452.CODIGO_VAR_SKU FROM fza_articulos_skus SK452 WHERE SK452.CODIGO_UNIDAD_SKU = sac.CODIGO_UNIDAD_SKU_SA) AND EJ452.EJE_VA = 'F')
                 WHERE NULLIF(TRIM(co.`AV`), '') IS NOT NULL
               ) elegido
         WHERE elegido.`POSICION` = 1;
        INSERT INTO `tmp_mva_color_global`
            (`CLAVE_COLOR`, `ID_COLOR`, `COLOR`, `ORDEN_COLOR`)
        SELECT UPPER(TRIM(co.`AV`)), MIN(co.`ID_AV`), MIN(TRIM(co.`AV`)),
               MIN(COALESCE(co.`ORDEN_AV`, 0))
          FROM `fza_atributos_valores` co
          JOIN (
                SELECT DISTINCT e.`CLAVE_COLOR`
                  FROM `tmp_mva_sku_color_elegido` e
               ) usados
            ON usados.`CLAVE_COLOR` = UPPER(TRIM(co.`AV`))
         WHERE EXISTS (SELECT 1 FROM tmp_mva_sku_color_elegido E452 WHERE E452.ID_AV = co.ID_AV)
           AND NULLIF(TRIM(co.`AV`), '') IS NOT NULL
         GROUP BY UPPER(TRIM(co.`AV`));
    END IF;


    DROP TEMPORARY TABLE IF EXISTS `tmp_mva_sku_talla_elegida`;
    CREATE TEMPORARY TABLE `tmp_mva_sku_talla_elegida` (
        `CODIGO_UNIDAD` VARCHAR(50)  NOT NULL PRIMARY KEY,
        `ID_AV`         INT          NOT NULL,
        `CLAVE_TALLA`   VARCHAR(100) NOT NULL,
        KEY `IDX_MVA_TALLA_ELEGIDA_CLAVE` (`CLAVE_TALLA`)
    );
    DROP TEMPORARY TABLE IF EXISTS `tmp_mva_talla_global`;
    CREATE TEMPORARY TABLE `tmp_mva_talla_global` (
        `CLAVE_TALLA` VARCHAR(100) NOT NULL PRIMARY KEY,
        `ID_TALLA`    INT          NOT NULL,
        `TALLA`       VARCHAR(100) NOT NULL,
        `ORDEN_TALLA` INT          NOT NULL DEFAULT 0,
        UNIQUE KEY `UK_MVA_TALLA_GLOBAL_ID` (`ID_TALLA`)
    );
    IF v_por_tal THEN
        INSERT INTO `tmp_mva_sku_talla_elegida`
            (`CODIGO_UNIDAD`, `ID_AV`, `CLAVE_TALLA`)
        SELECT elegida.`CODIGO_UNIDAD`, elegida.`ID_AV`,
               elegida.`CLAVE_TALLA`
          FROM (
                SELECT sat.`CODIGO_UNIDAD_SKU_SA` AS `CODIGO_UNIDAD`,
                       ta.`ID_AV`, UPPER(TRIM(ta.`AV`)) AS `CLAVE_TALLA`,
                       ROW_NUMBER() OVER (
                           PARTITION BY sat.`CODIGO_UNIDAD_SKU_SA`
                           ORDER BY COALESCE(ta.`ORDEN_AV`, 0), ta.`ID_AV`
                       ) AS `POSICION`
                  FROM `fza_atributos_sku` sat
                  JOIN `tmp_mva_skus` sku
                    ON sku.`CODIGO_UNIDAD` = sat.`CODIGO_UNIDAD_SKU_SA`
                  JOIN `fza_atributos_valores` ta
                    ON ta.`ID_AV` = sat.`ID_AV_SA`
                   AND ta.`ID_VA_AV` = (SELECT EJ452.ID_ATB_VA FROM VI_VARIACIONES_EJES EJ452 WHERE EJ452.ID_VAR_VA = (SELECT SK452.CODIGO_VAR_SKU FROM fza_articulos_skus SK452 WHERE SK452.CODIGO_UNIDAD_SKU = sat.CODIGO_UNIDAD_SKU_SA) AND EJ452.EJE_VA = 'P')
                 WHERE NULLIF(TRIM(ta.`AV`), '') IS NOT NULL
               ) elegida
         WHERE elegida.`POSICION` = 1;
        INSERT INTO `tmp_mva_talla_global`
            (`CLAVE_TALLA`, `ID_TALLA`, `TALLA`, `ORDEN_TALLA`)
        SELECT UPPER(TRIM(ta.`AV`)), MIN(ta.`ID_AV`), MIN(TRIM(ta.`AV`)),
               MIN(COALESCE(ta.`ORDEN_AV`, 0))
          FROM `fza_atributos_valores` ta
          JOIN (
                SELECT DISTINCT e.`CLAVE_TALLA`
                  FROM `tmp_mva_sku_talla_elegida` e
               ) usadas
            ON usadas.`CLAVE_TALLA` = UPPER(TRIM(ta.`AV`))
         WHERE EXISTS (SELECT 1 FROM tmp_mva_sku_talla_elegida E452 WHERE E452.ID_AV = ta.ID_AV)
           AND NULLIF(TRIM(ta.`AV`), '') IS NOT NULL
         GROUP BY UPPER(TRIM(ta.`AV`));
    END IF;


    DROP TEMPORARY TABLE IF EXISTS `tmp_mva_sku_color`;
    CREATE TEMPORARY TABLE `tmp_mva_sku_color` (
        `CODIGO_UNIDAD` VARCHAR(50)  NOT NULL PRIMARY KEY,
        `CODIGO_ART`    VARCHAR(20)  NOT NULL,
        `ID_COLOR`      INT          NOT NULL DEFAULT 0,
        `ID_COPA`       INT          NOT NULL DEFAULT 0,
        `CLAVE_COLOR`   VARCHAR(100) NOT NULL DEFAULT '',
        `COLOR`         VARCHAR(100) NOT NULL DEFAULT '',
        `COLOR_ETIQUETA` VARCHAR(255) NOT NULL DEFAULT '',
        `ORDEN_COLOR`   INT          NOT NULL DEFAULT 0,
        `ID_TALLA`      INT          NOT NULL DEFAULT 0,
        `CLAVE_TALLA`   VARCHAR(100) NOT NULL DEFAULT '',
        `TALLA`         VARCHAR(100) NOT NULL DEFAULT '',
        `TALLA_ETIQUETA` VARCHAR(255) NOT NULL DEFAULT '',
        `ORDEN_TALLA`   INT          NOT NULL DEFAULT 0,
        KEY `IDX_MVA_SKU_COLOR_ART`
            (`CODIGO_ART`, `ID_COLOR`, `ID_COPA`, `ID_TALLA`),
        KEY `IDX_MVA_SKU_COLOR_CLAVE` (`CODIGO_ART`, `CLAVE_COLOR`)
    );
    INSERT INTO `tmp_mva_sku_color`
        (`CODIGO_UNIDAD`, `CODIGO_ART`, `ID_COLOR`, `ID_COPA`, `CLAVE_COLOR`,
         `COLOR`, `COLOR_ETIQUETA`, `ORDEN_COLOR`, `ID_TALLA`,
         `CLAVE_TALLA`, `TALLA`, `TALLA_ETIQUETA`, `ORDEN_TALLA`)
    SELECT sku.`CODIGO_UNIDAD`, sku.`CODIGO_ART`,
           IF(v_por_col, COALESCE(cg.`ID_COLOR`, 0), 0),
           IF(v_por_copa, COALESCE(copa.`ID_AV`, 0), 0),
           IF(v_por_col, COALESCE(cg.`CLAVE_COLOR`, ''), ''),
           IF(v_por_col, COALESCE(cg.`COLOR`, ''), ''),
           IF(v_por_col,
              COALESCE(NULLIF(aab.`DESCRIPCION_AAB`, ''),
                       NULLIF(col_raw.`DESCRIPCION_AV`, ''), cg.`COLOR`, ''),
              ''),
           IF(v_por_col, COALESCE(cg.`ORDEN_COLOR`, 0), 0),
           IF(v_por_tal, COALESCE(tg.`ID_TALLA`, 0), 0),
           IF(v_por_tal, COALESCE(tg.`CLAVE_TALLA`, ''), ''),
           IF(v_por_tal, COALESCE(tg.`TALLA`, ''), ''),
           IF(v_por_tal,
              COALESCE(NULLIF(aab_tal.`DESCRIPCION_AAB`, ''),
                       NULLIF(tal_raw.`DESCRIPCION_AV`, ''), tg.`TALLA`, ''),
              ''),
           IF(v_por_tal, COALESCE(tg.`ORDEN_TALLA`, 0), 0)
      FROM `tmp_mva_skus` sku
      LEFT JOIN `fza_articulos_skus` sk_copa
        ON sk_copa.`CODIGO_UNIDAD_SKU` = sku.`CODIGO_UNIDAD`
      LEFT JOIN `VI_VARIACIONES_EJES` eje_copa
        ON eje_copa.`ID_VAR_VA` = sk_copa.`CODIGO_VAR_SKU`
       AND eje_copa.`EJE_VA` = 'S'
      LEFT JOIN `fza_atributos_valores` copa
        ON copa.`ID_AV` = (
            SELECT MIN(av.`ID_AV`)
              FROM `fza_atributos_sku` sa
              JOIN `fza_atributos_valores` av ON av.`ID_AV` = sa.`ID_AV_SA`
             WHERE sa.`CODIGO_UNIDAD_SKU_SA` = sku.`CODIGO_UNIDAD`
               AND av.`ID_VA_AV` = eje_copa.`ID_ATB_VA`)
      LEFT JOIN `tmp_mva_sku_color_elegido` elegido
        ON elegido.`CODIGO_UNIDAD` = sku.`CODIGO_UNIDAD`
      LEFT JOIN `tmp_mva_color_global` cg
        ON cg.`CLAVE_COLOR` = elegido.`CLAVE_COLOR`
      LEFT JOIN `fza_atributos_valores` col_raw
        ON col_raw.`ID_AV` = elegido.`ID_AV`
      LEFT JOIN `fza_articulos_atributos_basicos` aab
        ON aab.`CODIGO_ART_AAB` = sku.`CODIGO_ART`
       AND aab.`ID_AV_AAB` = elegido.`ID_AV`
      LEFT JOIN `tmp_mva_sku_talla_elegida` talla_elegida
        ON talla_elegida.`CODIGO_UNIDAD` = sku.`CODIGO_UNIDAD`
      LEFT JOIN `tmp_mva_talla_global` tg
        ON tg.`CLAVE_TALLA` = talla_elegida.`CLAVE_TALLA`
      LEFT JOIN `fza_atributos_valores` tal_raw
        ON tal_raw.`ID_AV` = talla_elegida.`ID_AV`
      LEFT JOIN `fza_articulos_atributos_basicos` aab_tal
        ON aab_tal.`CODIGO_ART_AAB` = sku.`CODIGO_ART`
       AND aab_tal.`ID_AV_AAB` = talla_elegida.`ID_AV`;

    DROP TEMPORARY TABLE IF EXISTS `tmp_mva_color`;
    CREATE TEMPORARY TABLE `tmp_mva_color` (
        `CODIGO_ART`    VARCHAR(20)  NOT NULL,
        `ID_COLOR`      INT          NOT NULL DEFAULT 0,
        `ID_COPA`       INT          NOT NULL DEFAULT 0,
        `CLAVE_COLOR`   VARCHAR(100) NOT NULL DEFAULT '',
        `COLOR`         VARCHAR(100) NOT NULL DEFAULT '',
        `COLOR_ETIQUETA` VARCHAR(255) NOT NULL DEFAULT '',
        `ORDEN_COLOR`   INT          NOT NULL DEFAULT 0,
        PRIMARY KEY (`CODIGO_ART`, `ID_COLOR`, `ID_COPA`)
    );
    INSERT INTO `tmp_mva_color`
        (`CODIGO_ART`, `ID_COLOR`, `ID_COPA`, `CLAVE_COLOR`, `COLOR`,
         `COLOR_ETIQUETA`, `ORDEN_COLOR`)
    SELECT s.`CODIGO_ART`, s.`ID_COLOR`, s.`ID_COPA`, MIN(s.`CLAVE_COLOR`), MIN(s.`COLOR`),
           IF(v_por_col,
              COALESCE(NULLIF(MIN(s.`COLOR_ETIQUETA`), ''), '(sin color)'), ''),
           MIN(s.`ORDEN_COLOR`)
      FROM `tmp_mva_sku_color` s
     GROUP BY s.`CODIGO_ART`, s.`ID_COLOR`, s.`ID_COPA`;

    DROP TEMPORARY TABLE IF EXISTS `tmp_mva_talla`;
    CREATE TEMPORARY TABLE `tmp_mva_talla` (
        `CODIGO_ART`     VARCHAR(20)  NOT NULL,
        `ID_TALLA`       INT          NOT NULL DEFAULT 0,
        `CLAVE_TALLA`    VARCHAR(100) NOT NULL DEFAULT '',
        `TALLA`          VARCHAR(100) NOT NULL DEFAULT '',
        `TALLA_ETIQUETA` VARCHAR(255) NOT NULL DEFAULT '',
        `ORDEN_TALLA`    INT          NOT NULL DEFAULT 0,
        PRIMARY KEY (`CODIGO_ART`, `ID_TALLA`)
    );
    INSERT INTO `tmp_mva_talla`
        (`CODIGO_ART`, `ID_TALLA`, `CLAVE_TALLA`, `TALLA`,
         `TALLA_ETIQUETA`, `ORDEN_TALLA`)
    SELECT s.`CODIGO_ART`, s.`ID_TALLA`, MIN(s.`CLAVE_TALLA`),
           MIN(s.`TALLA`),
           IF(v_por_tal,
              COALESCE(NULLIF(MIN(s.`TALLA_ETIQUETA`), ''), '(sin talla)'),
              ''),
           MIN(s.`ORDEN_TALLA`)
      FROM `tmp_mva_sku_color` s
     GROUP BY s.`CODIGO_ART`, s.`ID_TALLA`;




    DROP TEMPORARY TABLE IF EXISTS `tmp_mva_temporada`;
    CREATE TEMPORARY TABLE `tmp_mva_temporada` (
        `CODIGO_ART` VARCHAR(20)  NOT NULL,
        `ID_COLOR`   INT          NOT NULL DEFAULT 0,
        `ID_COPA`       INT          NOT NULL DEFAULT 0,
        `TEMPORADA`  VARCHAR(255) NOT NULL DEFAULT '',
        PRIMARY KEY (`CODIGO_ART`, `ID_COLOR`, `ID_COPA`)
    );
    IF v_por_col OR v_por_copa THEN
        INSERT INTO `tmp_mva_temporada`
            (`CODIGO_ART`, `ID_COLOR`, `ID_COPA`, `TEMPORADA`)
        SELECT unidad.`CODIGO_ART`, unidad.`ID_COLOR`, unidad.`ID_COPA`,
               COALESCE(
                   MAX(NULLIF(COALESCE(tpcv.`PV`,
                                       tpc.`VALOR_LIBRE_ARTPROP`), '')),
                   MAX(NULLIF(COALESCE(tpav.`PV`,
                                       tpa.`VALOR_LIBRE_ARTPROP`), '')),
                   '')
          FROM (
                SELECT DISTINCT s.`CODIGO_ART`, s.`ID_COLOR`, s.`ID_COPA`,
                       CASE
                           WHEN s.`CLAVE_COLOR` <> '' THEN
                               SUBSTRING_INDEX(s.`CODIGO_UNIDAD`, '/', 2)
                           ELSE NULL
                       END AS `CODIGO_UNIDAD_COLOR`
                  FROM `tmp_mva_sku_color` s
               ) unidad
          LEFT JOIN `fza_articulos_propiedades` tpc
            ON tpc.`CODIGO_ART_ART` = unidad.`CODIGO_ART`
           AND tpc.`CODIGO_PROP_ARTPROP` = 'TEMPORADA'
           AND tpc.`CODIGO_UNIDAD_ARTPROP` = unidad.`CODIGO_UNIDAD_COLOR`
          LEFT JOIN `fza_propiedades_valores` tpcv
            ON tpcv.`ID_PV_ARTPROP` = tpc.`ID_PV_ARTPROP`
          LEFT JOIN `fza_articulos_propiedades` tpa
            ON tpa.`CODIGO_ART_ART` = unidad.`CODIGO_ART`
           AND tpa.`CODIGO_PROP_ARTPROP` = 'TEMPORADA'
           AND tpa.`CODIGO_UNIDAD_ARTPROP` = ''
          LEFT JOIN `fza_propiedades_valores` tpav
            ON tpav.`ID_PV_ARTPROP` = tpa.`ID_PV_ARTPROP`
         GROUP BY unidad.`CODIGO_ART`, unidad.`ID_COLOR`, unidad.`ID_COPA`;
    ELSE
        INSERT INTO `tmp_mva_temporada`
            (`CODIGO_ART`, `ID_COLOR`, `ID_COPA`, `TEMPORADA`)
        SELECT tp.`CODIGO_ART_ART`, 0, 0,
               MAX(COALESCE(tpv.`PV`, tp.`VALOR_LIBRE_ARTPROP`, ''))
          FROM `fza_articulos_propiedades` tp
          LEFT JOIN `fza_propiedades_valores` tpv
            ON tpv.`ID_PV_ARTPROP` = tp.`ID_PV_ARTPROP`
         WHERE tp.`CODIGO_PROP_ARTPROP` = 'TEMPORADA'
           AND tp.`CODIGO_UNIDAD_ARTPROP` = ''
           AND tp.`CODIGO_ART_ART` IN
               (SELECT `CODIGO_ART` FROM `tmp_mva_arts0`)
         GROUP BY tp.`CODIGO_ART_ART`;
    END IF;




    DROP TEMPORARY TABLE IF EXISTS `tmp_mva_ent`;
    CREATE TEMPORARY TABLE `tmp_mva_ent` (
        `CODIGO_ART` VARCHAR(20)   NOT NULL,
        `ID_COLOR`   INT           NOT NULL DEFAULT 0,
        `ID_COPA`       INT          NOT NULL DEFAULT 0,
        `ID_TALLA`   INT           NOT NULL DEFAULT 0,
        `CODIGO_ALM` VARCHAR(50)   NOT NULL DEFAULT '',
        `UNI_ENT`    DECIMAL(19,6) NOT NULL DEFAULT 0,
        `IMP_ENT`    DECIMAL(19,6) NOT NULL DEFAULT 0,
        PRIMARY KEY (`CODIGO_ART`, `ID_COLOR`, `ID_COPA`, `ID_TALLA`, `CODIGO_ALM`)
    );
    INSERT INTO `tmp_mva_ent`
        (`CODIGO_ART`, `ID_COLOR`, `ID_COPA`, `ID_TALLA`, `CODIGO_ALM`,
         `UNI_ENT`, `IMP_ENT`)
    SELECT sc.`CODIGO_ART`, sc.`ID_COLOR`, sc.`ID_COPA`, sc.`ID_TALLA`,
           CONCAT(IF(v_por_alm, m.`CODIGO_ALM_MOV`, ''), IF(v_por_prv, CONCAT(CHAR(31 USING utf8mb4), COALESCE((SELECT NULLIF(NULLIF(TRIM(LG.CODIGO_PRV_LOT), ''), '0') FROM fza_articulos_lotes LG WHERE LG.CODIGO_UNIDAD_LOT = m.CODIGO_UNIDAD_MOV AND LG.LOTE_LOT = m.LOTE_MOV LIMIT 1), IF(p_PROVEEDORES = '', (SELECT MAX(AG.CODIGO_PRV_AP) FROM fza_articulos_proveedores AG WHERE AG.CODIGO_ART_AP = m.CODIGO_ART_MOV AND AG.ESPROVEEDORPRINCIPAL_AP = 'S'), (SELECT AG.CODIGO_PRV_AP FROM fza_articulos_proveedores AG WHERE AG.CODIGO_ART_AP = m.CODIGO_ART_MOV AND FIND_IN_SET(AG.CODIGO_PRV_AP, p_PROVEEDORES) > 0 ORDER BY AG.ESPROVEEDORPRINCIPAL_AP = 'S' DESC, AG.CODIGO_PRV_AP LIMIT 1)), '')), '')),
           SUM(CASE WHEN m.`TIPO_MOV` = 'S'
                    THEN -m.`CANTIDAD_MOV` ELSE m.`CANTIDAD_MOV` END),
           SUM(CASE WHEN m.`TIPO_MOV` = 'S'
                    THEN -m.`TOTAL_COSTE_MOV` ELSE m.`TOTAL_COSTE_MOV` END)
      FROM `fza_movimientos_almacen` m
      JOIN `tmp_mva_sku_color` sc
        ON sc.`CODIGO_UNIDAD` = m.`CODIGO_UNIDAD_MOV`
     WHERE
       (p_PROVEEDORES = '' OR EXISTS (
         SELECT 1 FROM fza_articulos_lotes LP
          WHERE LP.CODIGO_UNIDAD_LOT = m.CODIGO_UNIDAD_MOV
            AND LP.LOTE_LOT = m.LOTE_MOV
            AND COALESCE(TRIM(LP.CODIGO_PRV_LOT), '') NOT IN ('', '0')
            AND FIND_IN_SET(LP.CODIGO_PRV_LOT, p_PROVEEDORES) > 0)
        OR (NOT EXISTS (
         SELECT 1 FROM fza_articulos_lotes LP
          WHERE LP.CODIGO_UNIDAD_LOT = m.CODIGO_UNIDAD_MOV
            AND LP.LOTE_LOT = m.LOTE_MOV
            AND COALESCE(TRIM(LP.CODIGO_PRV_LOT), '') NOT IN ('', '0')) AND EXISTS (
         SELECT 1 FROM fza_articulos_proveedores APF
          WHERE APF.CODIGO_ART_AP = m.CODIGO_ART_MOV
            AND FIND_IN_SET(APF.CODIGO_PRV_AP, p_PROVEEDORES) > 0))) AND m.`ESACTIVO_MOV` = 'S'
       AND (NOT v_filtra_cmp OR m.`FECHA_MOV` >= v_ini_cmp)
       AND ((m.`TIPO_MOV` = 'E' AND
              (m.`TIPO_DOC_MOV` IN ('AC', 'AE') OR
               (NOT v_ent_global AND
                m.`TIPO_DOC_MOV` IN ('TR', 'AT', 'TA')))) OR
            (m.`TIPO_MOV` = 'S' AND m.`TIPO_DOC_MOV` = 'DC') OR
            m.`TIPO_DOC_MOV` = 'FP')
       AND (v_ent_global
            OR m.`CODIGO_ALM_MOV` IN
               (SELECT `CODIGO_ALM` FROM `tmp_mva_alm`))
     GROUP BY sc.`CODIGO_ART`, sc.`ID_COLOR`, sc.`ID_COPA`, sc.`ID_TALLA`,
              CONCAT(IF(v_por_alm, m.`CODIGO_ALM_MOV`, ''), IF(v_por_prv, CONCAT(CHAR(31 USING utf8mb4), COALESCE((SELECT NULLIF(NULLIF(TRIM(LG.CODIGO_PRV_LOT), ''), '0') FROM fza_articulos_lotes LG WHERE LG.CODIGO_UNIDAD_LOT = m.CODIGO_UNIDAD_MOV AND LG.LOTE_LOT = m.LOTE_MOV LIMIT 1), IF(p_PROVEEDORES = '', (SELECT MAX(AG.CODIGO_PRV_AP) FROM fza_articulos_proveedores AG WHERE AG.CODIGO_ART_AP = m.CODIGO_ART_MOV AND AG.ESPROVEEDORPRINCIPAL_AP = 'S'), (SELECT AG.CODIGO_PRV_AP FROM fza_articulos_proveedores AG WHERE AG.CODIGO_ART_AP = m.CODIGO_ART_MOV AND FIND_IN_SET(AG.CODIGO_PRV_AP, p_PROVEEDORES) > 0 ORDER BY AG.ESPROVEEDORPRINCIPAL_AP = 'S' DESC, AG.CODIGO_PRV_AP LIMIT 1)), '')), ''));

    IF v_ent_global THEN
        DELETE e FROM `tmp_mva_ent` e
         WHERE NOT EXISTS (
               SELECT 1
                 FROM `fza_movimientos_almacen` m
                 JOIN `tmp_mva_sku_color` sc
                   ON sc.`CODIGO_UNIDAD` = m.`CODIGO_UNIDAD_MOV`
                 JOIN `tmp_mva_alm` al
                   ON al.`CODIGO_ALM` = m.`CODIGO_ALM_MOV`
                WHERE
       (p_PROVEEDORES = '' OR EXISTS (
         SELECT 1 FROM fza_articulos_lotes LP
          WHERE LP.CODIGO_UNIDAD_LOT = m.CODIGO_UNIDAD_MOV
            AND LP.LOTE_LOT = m.LOTE_MOV
            AND COALESCE(TRIM(LP.CODIGO_PRV_LOT), '') NOT IN ('', '0')
            AND FIND_IN_SET(LP.CODIGO_PRV_LOT, p_PROVEEDORES) > 0)
        OR (NOT EXISTS (
         SELECT 1 FROM fza_articulos_lotes LP
          WHERE LP.CODIGO_UNIDAD_LOT = m.CODIGO_UNIDAD_MOV
            AND LP.LOTE_LOT = m.LOTE_MOV
            AND COALESCE(TRIM(LP.CODIGO_PRV_LOT), '') NOT IN ('', '0')) AND EXISTS (
         SELECT 1 FROM fza_articulos_proveedores APF
          WHERE APF.CODIGO_ART_AP = m.CODIGO_ART_MOV
            AND FIND_IN_SET(APF.CODIGO_PRV_AP, p_PROVEEDORES) > 0))) AND m.`ESACTIVO_MOV` = 'S'
                  AND (NOT v_filtra_cmp OR m.`FECHA_MOV` >= v_ini_cmp)
                  AND m.`FECHA_MOV` < DATE_ADD(v_hasta, INTERVAL 1 DAY)
                  AND sc.`CODIGO_ART` = e.`CODIGO_ART`
                  AND sc.`ID_COLOR` = e.`ID_COLOR`
                  AND sc.`ID_COPA` = e.`ID_COPA`
                  AND sc.`ID_TALLA` = e.`ID_TALLA`);
    END IF;






    DROP TEMPORARY TABLE IF EXISTS `tmp_mva_fac`;
    CREATE TEMPORARY TABLE `tmp_mva_fac` (
        `SERIE_FAC`  VARCHAR(20) NOT NULL,
        `NUMERO_FAC` VARCHAR(20) NOT NULL,
        `CODIGO_ALM` VARCHAR(20) NULL,


        `ESRECARGO`  VARCHAR(1)  NOT NULL DEFAULT 'N',
        PRIMARY KEY (`SERIE_FAC`, `NUMERO_FAC`)
    );
    INSERT INTO `tmp_mva_fac`
        (`SERIE_FAC`, `NUMERO_FAC`, `CODIGO_ALM`, `ESRECARGO`)
    SELECT f.`SERIE_FAC`, f.`NUMERO_FAC`, f.`CODIGO_ALM_FAC`,
           IF(emp.`ESIVA_RECARGO_COMPRAS_EMP` = 'S', 'S', 'N')
      FROM `fza_facturas` f
      LEFT JOIN `fza_empresas` emp
        ON emp.`CODIGO_EMP_EMP` = f.`CODIGO_EMP_FAC`
     WHERE f.`FECHA_FAC` >= v_desde
       AND f.`FECHA_FAC` < DATE_ADD(v_hasta, INTERVAL 1 DAY)

         AND NOT EXISTS (
           SELECT 1 FROM fza_facturas_relaciones FT
           JOIN fza_facturas FN
             ON FN.SERIE_FAC = FT.SERIE_FAC_FACREL
            AND FN.NUMERO_FAC = FT.NUMERO_FAC_FACREL
            AND FN.CODIGO_EMP_FAC = f.CODIGO_EMP_FAC
            WHERE FT.SERIE_FAC_ORIGEN_FACREL = f.SERIE_FAC
              AND FT.NUMERO_FAC_ORIGEN_FACREL = f.NUMERO_FAC
              AND FT.TIPO_RELACION_FACREL = 'SUSTITUYE'
              AND COALESCE(FN.FASE_FAC, '') NOT IN
                ('BORRADOR', 'ERROR_BORRADOR', 'CANCELADA',
                 'SIN_VERIF_ANULADA', 'VERIFACTU_ANULADA',
                 'NOVERIFACTU_ANULADA'))
         AND COALESCE(f.`FASE_FAC`, '') NOT IN (
           'BORRADOR', 'ERROR_BORRADOR', 'CANCELADA',
           'SIN_VERIF_ANULADA',
           'VERIFACTU_ANULADA',
           'NOVERIFACTU_ANULADA'
       )
       AND NOT EXISTS (
           SELECT 1
             FROM `fza_verifactu_cola` va
            WHERE va.`SERIE_FAC_VFCOLA` = f.`SERIE_FAC`
              AND va.`NUMERO_FAC_VFCOLA` = f.`NUMERO_FAC`
              AND va.`TIPO_OPERACION_VFCOLA` = 'ANULACION'
       )

       AND NOT EXISTS (
           SELECT 1
             FROM `fza_facturas` fo
             JOIN `fza_facturas_relaciones` fr
               ON fr.`SERIE_FAC_ORIGEN_FACREL` = fo.`SERIE_FAC`
              AND fr.`NUMERO_FAC_ORIGEN_FACREL` = fo.`NUMERO_FAC`
             JOIN `fza_facturas` fs
               ON fs.`CODIGO_EMP_FAC` = fo.`CODIGO_EMP_FAC`
              AND fs.`SERIE_FAC` = fr.`SERIE_FAC_FACREL`
              AND fs.`NUMERO_FAC` = fr.`NUMERO_FAC_FACREL`
            WHERE fo.`CODIGO_EMP_FAC` = f.`CODIGO_EMP_FAC`
              AND fo.`SERIE_FAC` = f.`SERIE_FAC`
              AND fo.`NUMERO_FAC` = f.`NUMERO_FAC`
              AND fo.`TIPO_FAC` = 'SIMPLIFICADA'
              AND fo.`FASE_FAC` = 'RECTIFICADA'
              AND fr.`TIPO_RELACION_FACREL` = 'RECTIFICA'
              AND fs.`TIPO_RECTIFICATIVA_FAC` = 'S'
       )





       AND NOT (
           EXISTS (
               SELECT 1
                 FROM `fza_empresas` d
                WHERE d.`CODIGO_CLI_TRASPASOS_EMP` = f.`CODIGO_CLI_FAC`
                  AND d.`CODIGO_EMP_EMP` <> f.`CODIGO_EMP_FAC`
           )
           AND NOT EXISTS (
               SELECT 1
                 FROM `fza_facturas_traspasos_vendidos` tv
                WHERE tv.`SERIE_FAC_FACTV` = f.`SERIE_FAC`
                  AND tv.`NUMERO_FAC_FACTV` = f.`NUMERO_FAC`
           )
       );



    DROP TEMPORARY TABLE IF EXISTS tmp_mva_alm_factura;
    CREATE TEMPORARY TABLE tmp_mva_alm_factura AS
    SELECT FL.SERIE_FAC_FACLIN AS SERIE_FAC,
           FL.NUMERO_FAC_FACLIN AS NUMERO_FAC,
           FL.LINEA_FACLIN AS LINEA_FAC,
           MIN(COALESCE(NULLIF(OL.CODIGO_ALM_FACLIN, ''),
                        NULLIF(OFAC.CODIGO_ALM_FAC, ''))) AS CODIGO_ALM
      FROM fza_facturas F
      JOIN fza_facturas_lineas FL
        ON FL.SERIE_FAC_FACLIN = F.SERIE_FAC
       AND FL.NUMERO_FAC_FACLIN = F.NUMERO_FAC
      JOIN fza_facturas_relaciones R
        ON R.SERIE_FAC_FACREL = F.SERIE_FAC
       AND R.NUMERO_FAC_FACREL = F.NUMERO_FAC
       AND R.TIPO_RELACION_FACREL = 'SUSTITUYE'
      JOIN fza_facturas OFAC
        ON OFAC.SERIE_FAC = R.SERIE_FAC_ORIGEN_FACREL
       AND OFAC.NUMERO_FAC = R.NUMERO_FAC_ORIGEN_FACREL
       AND OFAC.CODIGO_EMP_FAC = F.CODIGO_EMP_FAC
      LEFT JOIN fza_facturas_lineas OL
        ON OL.SERIE_FAC_FACLIN = OFAC.SERIE_FAC
       AND OL.NUMERO_FAC_FACLIN = OFAC.NUMERO_FAC
       AND OL.CODIGO_UNIDAD_FACLIN = FL.CODIGO_UNIDAD_FACLIN
     WHERE F.FECHA_FAC >= v_desde AND DATE(F.FECHA_FAC) <= v_hasta
       AND NULLIF(FL.CODIGO_ALM_FACLIN, '') IS NULL
       AND NULLIF(F.CODIGO_ALM_FAC, '') IS NULL
     GROUP BY FL.SERIE_FAC_FACLIN, FL.NUMERO_FAC_FACLIN, FL.LINEA_FACLIN;
    ALTER TABLE tmp_mva_alm_factura
      ADD PRIMARY KEY (SERIE_FAC, NUMERO_FAC, LINEA_FAC);
    DROP TEMPORARY TABLE IF EXISTS `tmp_mva_ven`;
    CREATE TEMPORARY TABLE `tmp_mva_ven` (
        `CODIGO_ART` VARCHAR(20)   NOT NULL,
        `ID_COLOR`   INT           NOT NULL DEFAULT 0,
        `ID_COPA`       INT          NOT NULL DEFAULT 0,
        `ID_TALLA`   INT           NOT NULL DEFAULT 0,
        `CODIGO_ALM` VARCHAR(50)   NOT NULL DEFAULT '',
        `UDS_VEN`    DECIMAL(19,6) NOT NULL DEFAULT 0,
        `IMP_VEN`    DECIMAL(19,6) NOT NULL DEFAULT 0,


        `IMP_VEN_REG` DECIMAL(19,6) NOT NULL DEFAULT 0,
        `PRECIO_SALIDA_MIN` DECIMAL(19,6) NULL,
        `PRECIO_SALIDA_MAX` DECIMAL(19,6) NULL,
        `PRECIO_FINAL_MIN` DECIMAL(19,6) NULL,
        `PRECIO_FINAL_MAX` DECIMAL(19,6) NULL,
        PRIMARY KEY (`CODIGO_ART`, `ID_COLOR`, `ID_COPA`, `ID_TALLA`, `CODIGO_ALM`)
    );
    INSERT INTO `tmp_mva_ven`
        (`CODIGO_ART`, `ID_COLOR`, `ID_COPA`, `ID_TALLA`, `CODIGO_ALM`,
         `UDS_VEN`, `IMP_VEN`, `IMP_VEN_REG`,
         `PRECIO_SALIDA_MIN`, `PRECIO_SALIDA_MAX`,
         `PRECIO_FINAL_MIN`, `PRECIO_FINAL_MAX`)
    SELECT sc.`CODIGO_ART`, sc.`ID_COLOR`, sc.`ID_COPA`, sc.`ID_TALLA`,
           CONCAT(IF(v_por_alm, COALESCE(NULLIF(fl.CODIGO_ALM_FACLIN, ''), NULLIF(f.CODIGO_ALM, ''), AFS.CODIGO_ALM), ''), IF(v_por_prv, CONCAT(CHAR(31 USING utf8mb4), COALESCE((SELECT NULLIF(NULLIF(TRIM(LG.CODIGO_PRV_LOT), ''), '0') FROM fza_articulos_lotes LG WHERE LG.CODIGO_UNIDAD_LOT = fl.CODIGO_UNIDAD_FACLIN AND LG.LOTE_LOT = fl.LOTE_FACLIN LIMIT 1), IF(p_PROVEEDORES = '', (SELECT MAX(AG.CODIGO_PRV_AP) FROM fza_articulos_proveedores AG WHERE AG.CODIGO_ART_AP = fl.CODIGO_ART_FACLIN AND AG.ESPROVEEDORPRINCIPAL_AP = 'S'), (SELECT AG.CODIGO_PRV_AP FROM fza_articulos_proveedores AG WHERE AG.CODIGO_ART_AP = fl.CODIGO_ART_FACLIN AND FIND_IN_SET(AG.CODIGO_PRV_AP, p_PROVEEDORES) > 0 ORDER BY AG.ESPROVEEDORPRINCIPAL_AP = 'S' DESC, AG.CODIGO_PRV_AP LIMIT 1)), '')), '')),
           SUM(fl.`CANTIDAD_FACLIN`),
           SUM(CASE p_CON_IMPUESTOS
                   WHEN 'N' THEN COALESCE(
                       fl.`TOTAL_FAC_SIVA_FACLIN`,
                       fl.`TOTAL_FACLIN` / NULLIF(
                         1 + COALESCE(fl.`PORCENTAJE_IVA_FACLIN`, 0)
                           / 100, 0),
                       0)
                   ELSE COALESCE(
                       fl.`TOTAL_FACLIN`, fl.`TOTAL_FAC_SIVA_FACLIN`, 0)
               END),
           SUM(CASE f.`ESRECARGO`
                   WHEN 'S' THEN COALESCE(
                       fl.`TOTAL_FACLIN`, fl.`TOTAL_FAC_SIVA_FACLIN`, 0)
                   ELSE COALESCE(
                       fl.`TOTAL_FAC_SIVA_FACLIN`,
                       fl.`TOTAL_FACLIN` / NULLIF(
                         1 + COALESCE(fl.`PORCENTAJE_IVA_FACLIN`, 0)
                           / 100, 0),
                       0)
               END),
           MIN(ROUND(COALESCE(NULLIF(fl.`PRECIO_SALIDA_FACLIN`, 0) *
                   IF(fl.`ESIMP_INCL_TARIFA_FACLIN` = 'S', 1,
                      1 + COALESCE(fl.`PORCENTAJE_IVA_FACLIN`, 0) / 100),
                   fl.`PRECIO_VENTA_CIVA_ARTICULO_FACLIN` /
                     NULLIF(1 - COALESCE(fl.`PORCENTAJE_DTO_FACLIN`, 0)
                       / 100, 0),
                   fl.`PRECIO_VENTA_CIVA_ARTICULO_FACLIN`, 0), 2)),
           MAX(ROUND(COALESCE(NULLIF(fl.`PRECIO_SALIDA_FACLIN`, 0) *
                   IF(fl.`ESIMP_INCL_TARIFA_FACLIN` = 'S', 1,
                      1 + COALESCE(fl.`PORCENTAJE_IVA_FACLIN`, 0) / 100),
                   fl.`PRECIO_VENTA_CIVA_ARTICULO_FACLIN` /
                     NULLIF(1 - COALESCE(fl.`PORCENTAJE_DTO_FACLIN`, 0)
                       / 100, 0),
                   fl.`PRECIO_VENTA_CIVA_ARTICULO_FACLIN`, 0), 2)),
           MIN(ROUND(COALESCE(fl.`PRECIO_VENTA_CIVA_ARTICULO_FACLIN`,
                   fl.`PRECIO_VENTA_SIVA_ARTICULO_FACLIN` *
                     (1 + COALESCE(fl.`PORCENTAJE_IVA_FACLIN`, 0) / 100),
                   fl.`TOTAL_FACLIN` / NULLIF(fl.`CANTIDAD_FACLIN`, 0), 0), 2)),
           MAX(ROUND(COALESCE(fl.`PRECIO_VENTA_CIVA_ARTICULO_FACLIN`,
                   fl.`PRECIO_VENTA_SIVA_ARTICULO_FACLIN` *
                     (1 + COALESCE(fl.`PORCENTAJE_IVA_FACLIN`, 0) / 100),
                   fl.`TOTAL_FACLIN` / NULLIF(fl.`CANTIDAD_FACLIN`, 0), 0), 2))
      FROM `tmp_mva_fac` f
      JOIN `fza_facturas_lineas` fl
        ON fl.`NUMERO_FAC_FACLIN` = f.`NUMERO_FAC`
       AND fl.`SERIE_FAC_FACLIN` = f.`SERIE_FAC`
      LEFT JOIN tmp_mva_alm_factura AFS
        ON AFS.SERIE_FAC = fl.SERIE_FAC_FACLIN
       AND AFS.NUMERO_FAC = fl.NUMERO_FAC_FACLIN
       AND AFS.LINEA_FAC = fl.LINEA_FACLIN
      JOIN `tmp_mva_sku_color` sc
        ON sc.`CODIGO_UNIDAD` = fl.`CODIGO_UNIDAD_FACLIN`
     WHERE
       (p_PROVEEDORES = '' OR EXISTS (
         SELECT 1 FROM fza_articulos_lotes LP
          WHERE LP.CODIGO_UNIDAD_LOT = fl.CODIGO_UNIDAD_FACLIN
            AND LP.LOTE_LOT = fl.LOTE_FACLIN
            AND COALESCE(TRIM(LP.CODIGO_PRV_LOT), '') NOT IN ('', '0')
            AND FIND_IN_SET(LP.CODIGO_PRV_LOT, p_PROVEEDORES) > 0)
        OR (NOT EXISTS (
         SELECT 1 FROM fza_articulos_lotes LP
          WHERE LP.CODIGO_UNIDAD_LOT = fl.CODIGO_UNIDAD_FACLIN
            AND LP.LOTE_LOT = fl.LOTE_FACLIN
            AND COALESCE(TRIM(LP.CODIGO_PRV_LOT), '') NOT IN ('', '0')) AND EXISTS (
         SELECT 1 FROM fza_articulos_proveedores APF
          WHERE APF.CODIGO_ART_AP = fl.CODIGO_ART_FACLIN
            AND FIND_IN_SET(APF.CODIGO_PRV_AP, p_PROVEEDORES) > 0))) AND COALESCE(NULLIF(fl.CODIGO_ALM_FACLIN, ''), NULLIF(f.CODIGO_ALM, ''), AFS.CODIGO_ALM)
           IN (SELECT `CODIGO_ALM` FROM `tmp_mva_alm`)
     GROUP BY sc.`CODIGO_ART`, sc.`ID_COLOR`, sc.`ID_COPA`, sc.`ID_TALLA`,
              CONCAT(IF(v_por_alm, COALESCE(NULLIF(fl.CODIGO_ALM_FACLIN, ''), NULLIF(f.CODIGO_ALM, ''), AFS.CODIGO_ALM), ''), IF(v_por_prv, CONCAT(CHAR(31 USING utf8mb4), COALESCE((SELECT NULLIF(NULLIF(TRIM(LG.CODIGO_PRV_LOT), ''), '0') FROM fza_articulos_lotes LG WHERE LG.CODIGO_UNIDAD_LOT = fl.CODIGO_UNIDAD_FACLIN AND LG.LOTE_LOT = fl.LOTE_FACLIN LIMIT 1), IF(p_PROVEEDORES = '', (SELECT MAX(AG.CODIGO_PRV_AP) FROM fza_articulos_proveedores AG WHERE AG.CODIGO_ART_AP = fl.CODIGO_ART_FACLIN AND AG.ESPROVEEDORPRINCIPAL_AP = 'S'), (SELECT AG.CODIGO_PRV_AP FROM fza_articulos_proveedores AG WHERE AG.CODIGO_ART_AP = fl.CODIGO_ART_FACLIN AND FIND_IN_SET(AG.CODIGO_PRV_AP, p_PROVEEDORES) > 0 ORDER BY AG.ESPROVEEDORPRINCIPAL_AP = 'S' DESC, AG.CODIGO_PRV_AP LIMIT 1)), '')), ''));


    DROP TEMPORARY TABLE IF EXISTS `tmp_mva_coste_ven`;
    CREATE TEMPORARY TABLE `tmp_mva_coste_ven` (
        `CODIGO_ART` VARCHAR(20)   NOT NULL,
        `ID_COLOR`   INT           NOT NULL DEFAULT 0,
        `ID_COPA`       INT          NOT NULL DEFAULT 0,
        `ID_TALLA`   INT           NOT NULL DEFAULT 0,
        `CODIGO_ALM` VARCHAR(50)   NOT NULL DEFAULT '',
        `COSTE_VEN`  DECIMAL(19,6) NOT NULL DEFAULT 0,
        PRIMARY KEY (`CODIGO_ART`, `ID_COLOR`, `ID_COPA`, `ID_TALLA`, `CODIGO_ALM`)
    );





    INSERT INTO `tmp_mva_coste_ven`
        (`CODIGO_ART`, `ID_COLOR`, `ID_COPA`, `ID_TALLA`, `CODIGO_ALM`, `COSTE_VEN`)
    SELECT c.`CODIGO_ART`, c.`ID_COLOR`, c.`ID_COPA`, c.`ID_TALLA`,
           CONCAT(IF(v_por_alm, c.`CODIGO_ALM`, ''), IF(v_por_prv, CONCAT(CHAR(31 USING utf8mb4), c.`PRV`), '')),
           SUM(c.`COSTE`)
      FROM (
        SELECT sc.`CODIGO_ART`, sc.`ID_COLOR`, sc.`ID_COPA`, sc.`ID_TALLA`,
               COALESCE(NULLIF(fl.CODIGO_ALM_FACLIN, ''),
                       NULLIF(f.CODIGO_ALM, ''), m.CODIGO_ALM_MOV) AS `CODIGO_ALM`,
               IF(v_por_prv, COALESCE((SELECT NULLIF(NULLIF(TRIM(LG.CODIGO_PRV_LOT), ''), '0') FROM fza_articulos_lotes LG WHERE LG.CODIGO_UNIDAD_LOT = m.CODIGO_UNIDAD_MOV AND LG.LOTE_LOT = m.LOTE_MOV LIMIT 1), IF(p_PROVEEDORES = '', (SELECT MAX(AG.CODIGO_PRV_AP) FROM fza_articulos_proveedores AG WHERE AG.CODIGO_ART_AP = m.CODIGO_ART_MOV AND AG.ESPROVEEDORPRINCIPAL_AP = 'S'), (SELECT AG.CODIGO_PRV_AP FROM fza_articulos_proveedores AG WHERE AG.CODIGO_ART_AP = m.CODIGO_ART_MOV AND FIND_IN_SET(AG.CODIGO_PRV_AP, p_PROVEEDORES) > 0 ORDER BY AG.ESPROVEEDORPRINCIPAL_AP = 'S' DESC, AG.CODIGO_PRV_AP LIMIT 1)), ''), '') AS `PRV`,
               IF(m.`TIPO_MOV` = 'E', -1, 1) * m.`TOTAL_COSTE_MOV`
                 AS `COSTE`
          FROM `tmp_mva_fac` f




          STRAIGHT_JOIN `fza_movimientos_almacen` m
            ON m.`SERIE_DOC_MOV` = f.`SERIE_FAC`
           AND m.`NUMERO_DOC_MOV` = f.`NUMERO_FAC`
           AND m.`TIPO_DOC_MOV` IN ('VE', 'FC')

          LEFT JOIN `fza_facturas_lineas` fl
            ON fl.`NUMERO_FAC_FACLIN` = f.`NUMERO_FAC`
           AND fl.`SERIE_FAC_FACLIN` = f.`SERIE_FAC`
           AND fl.`LINEA_FACLIN` = m.`LINEA_MOV`
          JOIN `tmp_mva_sku_color` sc
            ON sc.`CODIGO_UNIDAD` = m.`CODIGO_UNIDAD_MOV`
         WHERE
       (p_PROVEEDORES = '' OR EXISTS (
         SELECT 1 FROM fza_articulos_lotes LP
          WHERE LP.CODIGO_UNIDAD_LOT = m.CODIGO_UNIDAD_MOV
            AND LP.LOTE_LOT = m.LOTE_MOV
            AND COALESCE(TRIM(LP.CODIGO_PRV_LOT), '') NOT IN ('', '0')
            AND FIND_IN_SET(LP.CODIGO_PRV_LOT, p_PROVEEDORES) > 0)
        OR (NOT EXISTS (
         SELECT 1 FROM fza_articulos_lotes LP
          WHERE LP.CODIGO_UNIDAD_LOT = m.CODIGO_UNIDAD_MOV
            AND LP.LOTE_LOT = m.LOTE_MOV
            AND COALESCE(TRIM(LP.CODIGO_PRV_LOT), '') NOT IN ('', '0')) AND EXISTS (
         SELECT 1 FROM fza_articulos_proveedores APF
          WHERE APF.CODIGO_ART_AP = m.CODIGO_ART_MOV
            AND FIND_IN_SET(APF.CODIGO_PRV_AP, p_PROVEEDORES) > 0))) AND m.`ESACTIVO_MOV` = 'S'
           AND m.`TIPO_MOV` IN ('S', 'E')

        UNION ALL

        SELECT sc.CODIGO_ART, sc.ID_COLOR, sc.ID_COPA, sc.ID_TALLA,
               m.CODIGO_ALM_MOV,
               IF(v_por_prv, COALESCE((SELECT NULLIF(NULLIF(TRIM(LG.CODIGO_PRV_LOT), ''), '0') FROM fza_articulos_lotes LG WHERE LG.CODIGO_UNIDAD_LOT = m.CODIGO_UNIDAD_MOV AND LG.LOTE_LOT = m.LOTE_MOV LIMIT 1), IF(p_PROVEEDORES = '', (SELECT MAX(AG.CODIGO_PRV_AP) FROM fza_articulos_proveedores AG WHERE AG.CODIGO_ART_AP = m.CODIGO_ART_MOV AND AG.ESPROVEEDORPRINCIPAL_AP = 'S'), (SELECT AG.CODIGO_PRV_AP FROM fza_articulos_proveedores AG WHERE AG.CODIGO_ART_AP = m.CODIGO_ART_MOV AND FIND_IN_SET(AG.CODIGO_PRV_AP, p_PROVEEDORES) > 0 ORDER BY AG.ESPROVEEDORPRINCIPAL_AP = 'S' DESC, AG.CODIGO_PRV_AP LIMIT 1)), ''), ''),
               IF(m.TIPO_MOV = 'E', -1, 1) * m.TOTAL_COSTE_MOV AS COSTE
          FROM tmp_mva_fac f
          JOIN fza_facturas FCAB
            ON FCAB.SERIE_FAC = f.SERIE_FAC
           AND FCAB.NUMERO_FAC = f.NUMERO_FAC
          JOIN fza_facturas_relaciones R
            ON R.SERIE_FAC_FACREL = f.SERIE_FAC
           AND R.NUMERO_FAC_FACREL = f.NUMERO_FAC
           AND R.TIPO_RELACION_FACREL = 'SUSTITUYE'
          JOIN fza_facturas OFAC
            ON OFAC.SERIE_FAC = R.SERIE_FAC_ORIGEN_FACREL
           AND OFAC.NUMERO_FAC = R.NUMERO_FAC_ORIGEN_FACREL
           AND OFAC.CODIGO_EMP_FAC = FCAB.CODIGO_EMP_FAC
          JOIN fza_movimientos_almacen m
            ON m.SERIE_DOC_MOV = OFAC.SERIE_FAC
           AND m.NUMERO_DOC_MOV = OFAC.NUMERO_FAC
           AND m.CODIGO_EMP_MOV = OFAC.CODIGO_EMP_FAC
           AND m.TIPO_DOC_MOV IN ('VE', 'FC')
           AND m.ESACTIVO_MOV = 'S'
          JOIN tmp_mva_sku_color sc
            ON sc.CODIGO_UNIDAD = m.CODIGO_UNIDAD_MOV
         WHERE
       (p_PROVEEDORES = '' OR EXISTS (
         SELECT 1 FROM fza_articulos_lotes LP
          WHERE LP.CODIGO_UNIDAD_LOT = m.CODIGO_UNIDAD_MOV
            AND LP.LOTE_LOT = m.LOTE_MOV
            AND COALESCE(TRIM(LP.CODIGO_PRV_LOT), '') NOT IN ('', '0')
            AND FIND_IN_SET(LP.CODIGO_PRV_LOT, p_PROVEEDORES) > 0)
        OR (NOT EXISTS (
         SELECT 1 FROM fza_articulos_lotes LP
          WHERE LP.CODIGO_UNIDAD_LOT = m.CODIGO_UNIDAD_MOV
            AND LP.LOTE_LOT = m.LOTE_MOV
            AND COALESCE(TRIM(LP.CODIGO_PRV_LOT), '') NOT IN ('', '0')) AND EXISTS (
         SELECT 1 FROM fza_articulos_proveedores APF
          WHERE APF.CODIGO_ART_AP = m.CODIGO_ART_MOV
            AND FIND_IN_SET(APF.CODIGO_PRV_AP, p_PROVEEDORES) > 0))) AND EXISTS (SELECT 1 FROM fza_facturas_lineas LF
           WHERE LF.SERIE_FAC_FACLIN = f.SERIE_FAC
             AND LF.NUMERO_FAC_FACLIN = f.NUMERO_FAC
             AND LF.CODIGO_UNIDAD_FACLIN = m.CODIGO_UNIDAD_MOV)
           AND NOT EXISTS (SELECT 1 FROM fza_movimientos_almacen MD
             WHERE MD.SERIE_DOC_MOV = f.SERIE_FAC
               AND MD.NUMERO_DOC_MOV = f.NUMERO_FAC
               AND MD.CODIGO_EMP_MOV = FCAB.CODIGO_EMP_FAC
               AND MD.CODIGO_UNIDAD_MOV = m.CODIGO_UNIDAD_MOV
               AND MD.ESACTIVO_MOV = 'S'
               AND MD.TIPO_DOC_MOV IN ('VE', 'FC'))
      ) c
     WHERE c.`CODIGO_ALM` IN (SELECT `CODIGO_ALM` FROM `tmp_mva_alm`)
     GROUP BY c.`CODIGO_ART`, c.`ID_COLOR`, c.`ID_COPA`, c.`ID_TALLA`,
              CONCAT(IF(v_por_alm, c.`CODIGO_ALM`, ''), IF(v_por_prv, CONCAT(CHAR(31 USING utf8mb4), c.`PRV`), ''));



    INSERT INTO `tmp_mva_coste_ven`
        (`CODIGO_ART`, `ID_COLOR`, `ID_COPA`, `ID_TALLA`, `CODIGO_ALM`, `COSTE_VEN`)
    SELECT c.`CODIGO_ART`, c.`ID_COLOR`, c.`ID_COPA`, c.`ID_TALLA`,
           CONCAT(IF(v_por_alm, c.`CODIGO_ALM`, ''), IF(v_por_prv, CONCAT(CHAR(31 USING utf8mb4), c.`PRV`), '')),
           SUM(c.`COSTE`)
      FROM (
        SELECT sc.`CODIGO_ART`, sc.`ID_COLOR`, sc.`ID_COPA`, sc.`ID_TALLA`,
               m.`CODIGO_ALM_MOV` AS `CODIGO_ALM`,
               IF(v_por_prv, COALESCE((SELECT NULLIF(NULLIF(TRIM(LG.CODIGO_PRV_LOT), ''), '0') FROM fza_articulos_lotes LG WHERE LG.CODIGO_UNIDAD_LOT = m.CODIGO_UNIDAD_MOV AND LG.LOTE_LOT = m.LOTE_MOV LIMIT 1), IF(p_PROVEEDORES = '', (SELECT MAX(AG.CODIGO_PRV_AP) FROM fza_articulos_proveedores AG WHERE AG.CODIGO_ART_AP = m.CODIGO_ART_MOV AND AG.ESPROVEEDORPRINCIPAL_AP = 'S'), (SELECT AG.CODIGO_PRV_AP FROM fza_articulos_proveedores AG WHERE AG.CODIGO_ART_AP = m.CODIGO_ART_MOV AND FIND_IN_SET(AG.CODIGO_PRV_AP, p_PROVEEDORES) > 0 ORDER BY AG.ESPROVEEDORPRINCIPAL_AP = 'S' DESC, AG.CODIGO_PRV_AP LIMIT 1)), ''), '') AS `PRV`,
               IF(m.`TIPO_MOV` = 'E', -1, 1) * m.`TOTAL_COSTE_MOV`
                 AS `COSTE`
          FROM `tmp_mva_fac` f
          STRAIGHT_JOIN `fza_albaranes` a
            ON a.`SERIE_FAC_ALB` = f.`SERIE_FAC`
           AND a.`NUMERO_FAC_ALB` = f.`NUMERO_FAC`
          STRAIGHT_JOIN `fza_movimientos_almacen` m
            ON m.`SERIE_DOC_MOV` = a.`SERIE_ALB`
           AND m.`NUMERO_DOC_MOV` = a.`NUMERO_ALB`
           AND m.`TIPO_DOC_MOV` = 'AV'
          JOIN `tmp_mva_sku_color` sc
            ON sc.`CODIGO_UNIDAD` = m.`CODIGO_UNIDAD_MOV`
         WHERE
       (p_PROVEEDORES = '' OR EXISTS (
         SELECT 1 FROM fza_articulos_lotes LP
          WHERE LP.CODIGO_UNIDAD_LOT = m.CODIGO_UNIDAD_MOV
            AND LP.LOTE_LOT = m.LOTE_MOV
            AND COALESCE(TRIM(LP.CODIGO_PRV_LOT), '') NOT IN ('', '0')
            AND FIND_IN_SET(LP.CODIGO_PRV_LOT, p_PROVEEDORES) > 0)
        OR (NOT EXISTS (
         SELECT 1 FROM fza_articulos_lotes LP
          WHERE LP.CODIGO_UNIDAD_LOT = m.CODIGO_UNIDAD_MOV
            AND LP.LOTE_LOT = m.LOTE_MOV
            AND COALESCE(TRIM(LP.CODIGO_PRV_LOT), '') NOT IN ('', '0')) AND EXISTS (
         SELECT 1 FROM fza_articulos_proveedores APF
          WHERE APF.CODIGO_ART_AP = m.CODIGO_ART_MOV
            AND FIND_IN_SET(APF.CODIGO_PRV_AP, p_PROVEEDORES) > 0))) AND m.`ESACTIVO_MOV` = 'S'
           AND m.`TIPO_MOV` IN ('S', 'E')
      ) c
     WHERE c.`CODIGO_ALM` IN (SELECT `CODIGO_ALM` FROM `tmp_mva_alm`)
     GROUP BY c.`CODIGO_ART`, c.`ID_COLOR`, c.`ID_COPA`, c.`ID_TALLA`,
              CONCAT(IF(v_por_alm, c.`CODIGO_ALM`, ''), IF(v_por_prv, CONCAT(CHAR(31 USING utf8mb4), c.`PRV`), ''))
    ON DUPLICATE KEY UPDATE
        `COSTE_VEN` = `COSTE_VEN` + VALUES(`COSTE_VEN`);






    INSERT INTO `tmp_mva_coste_ven`
        (`CODIGO_ART`, `ID_COLOR`, `ID_COPA`, `ID_TALLA`, `CODIGO_ALM`, `COSTE_VEN`)
    SELECT c.`CODIGO_ART`, c.`ID_COLOR`, c.`ID_COPA`, c.`ID_TALLA`,
           CONCAT(IF(v_por_alm, c.`CODIGO_ALM`, ''), IF(v_por_prv, CONCAT(CHAR(31 USING utf8mb4), c.`PRV`), '')),
           SUM(c.`COSTE`)
      FROM (
        SELECT sc.`CODIGO_ART`, sc.`ID_COLOR`, sc.`ID_COPA`, sc.`ID_TALLA`,
               tv.`CODIGO_ALM_ORIGEN_FACTV` AS `CODIGO_ALM`,
               IF(v_por_prv, COALESCE((SELECT NULLIF(NULLIF(TRIM(LG.CODIGO_PRV_LOT), ''), '0') FROM fza_articulos_lotes LG WHERE LG.CODIGO_UNIDAD_LOT = m.CODIGO_UNIDAD_MOV AND LG.LOTE_LOT = m.LOTE_MOV LIMIT 1), IF(p_PROVEEDORES = '', (SELECT MAX(AG.CODIGO_PRV_AP) FROM fza_articulos_proveedores AG WHERE AG.CODIGO_ART_AP = m.CODIGO_ART_MOV AND AG.ESPROVEEDORPRINCIPAL_AP = 'S'), (SELECT AG.CODIGO_PRV_AP FROM fza_articulos_proveedores AG WHERE AG.CODIGO_ART_AP = m.CODIGO_ART_MOV AND FIND_IN_SET(AG.CODIGO_PRV_AP, p_PROVEEDORES) > 0 ORDER BY AG.ESPROVEEDORPRINCIPAL_AP = 'S' DESC, AG.CODIGO_PRV_AP LIMIT 1)), ''), '') AS `PRV`,
               tv.`CANTIDAD_FACTV`
                 * COALESCE(m.`PRECIO_COSTE_UNITARIO_MOV`, 0) AS `COSTE`
          FROM `tmp_mva_fac` f
          STRAIGHT_JOIN `fza_facturas_traspasos_vendidos` tv
            ON tv.`SERIE_FAC_FACTV` = f.`SERIE_FAC`
           AND tv.`NUMERO_FAC_FACTV` = f.`NUMERO_FAC`
          STRAIGHT_JOIN `fza_movimientos_almacen` m
            ON m.`NUMERO_MOV` = tv.`NUMERO_MOV_TA_FACTV`
          JOIN `tmp_mva_sku_color` sc
            ON sc.`CODIGO_UNIDAD` = tv.`CODIGO_UNIDAD_FACTV`

       WHERE (p_PROVEEDORES = '' OR EXISTS (
         SELECT 1 FROM fza_articulos_lotes LP
          WHERE LP.CODIGO_UNIDAD_LOT = m.CODIGO_UNIDAD_MOV
            AND LP.LOTE_LOT = m.LOTE_MOV
            AND COALESCE(TRIM(LP.CODIGO_PRV_LOT), '') NOT IN ('', '0')
            AND FIND_IN_SET(LP.CODIGO_PRV_LOT, p_PROVEEDORES) > 0)
        OR (NOT EXISTS (
         SELECT 1 FROM fza_articulos_lotes LP
          WHERE LP.CODIGO_UNIDAD_LOT = m.CODIGO_UNIDAD_MOV
            AND LP.LOTE_LOT = m.LOTE_MOV
            AND COALESCE(TRIM(LP.CODIGO_PRV_LOT), '') NOT IN ('', '0')) AND EXISTS (
         SELECT 1 FROM fza_articulos_proveedores APF
          WHERE APF.CODIGO_ART_AP = m.CODIGO_ART_MOV
            AND FIND_IN_SET(APF.CODIGO_PRV_AP, p_PROVEEDORES) > 0)))
) c
     WHERE c.`CODIGO_ALM` IN (SELECT `CODIGO_ALM` FROM `tmp_mva_alm`)
     GROUP BY c.`CODIGO_ART`, c.`ID_COLOR`, c.`ID_COPA`, c.`ID_TALLA`,
              CONCAT(IF(v_por_alm, c.`CODIGO_ALM`, ''), IF(v_por_prv, CONCAT(CHAR(31 USING utf8mb4), c.`PRV`), ''))
    ON DUPLICATE KEY UPDATE
        `COSTE_VEN` = `COSTE_VEN` + VALUES(`COSTE_VEN`);


    SET v_tarifa = IFNULL(NULLIF(TRIM(p_TARIFA), ''), 'PVP');
    SET v_imp_incl = COALESCE(
        (SELECT IF(t.`ESIMP_INCL_TAR` = 'S', 'S', 'N')
           FROM `fza_tarifas` t
          WHERE t.`CODIGO_TAR_ARTTAR` = v_tarifa
          LIMIT 1), 'S');
    SET v_grupo_iva = COALESCE(
        (SELECT emp.`GRUPO_ZONA_IVA_EMP`
           FROM `fza_empresas` emp
          WHERE emp.`CODIGO_EMP_EMP` = p_EMPRESA
          LIMIT 1),
        (SELECT g.`IVA_IVAGRP`
           FROM `fza_ivas_grupos` g
          WHERE g.`ESDEFAULT_IVA_IVAGRP` = 'S'
          LIMIT 1));
    DROP TEMPORARY TABLE IF EXISTS `tmp_mva_iva`;
    CREATE TEMPORARY TABLE `tmp_mva_iva` AS
    SELECT COALESCE(i.`PORCENTAJE_NORMAL_IVA`, 0)        AS `N`,
           COALESCE(i.`PORCENTAJE_REDUCIDO_IVA`, 0)      AS `R`,
           COALESCE(i.`PORCENTAJE_SUPERREDUCIDO_IVA`, 0) AS `S`,
           COALESCE(i.`PORCENTAJE_EXENTO_IVA`, 0)        AS `E`
      FROM `fza_ivas` i
     WHERE i.`IVA_IVAGRP` = v_grupo_iva
       AND (i.`FECHA_DESDE_IVA` IS NULL
            OR i.`FECHA_DESDE_IVA` <= CURRENT_DATE)
       AND (i.`FECHA_HASTA_IVA` IS NULL
            OR i.`FECHA_HASTA_IVA` >= CURRENT_DATE)
     ORDER BY i.`FECHA_DESDE_IVA` DESC
     LIMIT 1;
    SET v_iva_n = COALESCE((SELECT `N` FROM `tmp_mva_iva`), 0);
    SET v_iva_r = COALESCE((SELECT `R` FROM `tmp_mva_iva`), 0);
    SET v_iva_s = COALESCE((SELECT `S` FROM `tmp_mva_iva`), 0);
    SET v_iva_e = COALESCE((SELECT `E` FROM `tmp_mva_iva`), 0);



    DROP TEMPORARY TABLE IF EXISTS `tmp_mva_tarifa`;
    CREATE TEMPORARY TABLE `tmp_mva_tarifa` (
        `CODIGO_UNIDAD`  VARCHAR(50)   NOT NULL PRIMARY KEY,
        `ESPROPIO`       VARCHAR(1)    NOT NULL DEFAULT 'N',
        `PRECIO_SALIDA`  DECIMAL(19,6) NULL,
        `PRECIO_FINAL`   DECIMAL(19,6) NULL
    );
    INSERT INTO `tmp_mva_tarifa`
        (`CODIGO_UNIDAD`, `ESPROPIO`, `PRECIO_SALIDA`, `PRECIO_FINAL`)
    WITH `vigentes` AS (
        SELECT t.`CODIGO_ART_ARTTAR` AS `CODIGO_ART`,
               IFNULL(t.`CODIGO_UNIDAD_ARTTAR`, '') AS `CODIGO_UNIDAD`,
               t.`PRECIO_SALIDA_ARTTAR` AS `PRECIO_SALIDA`,
               t.`PRECIO_FINAL_ARTTAR` AS `PRECIO_FINAL`,
               ROW_NUMBER() OVER (
                   PARTITION BY t.`CODIGO_ART_ARTTAR`,
                                IFNULL(t.`CODIGO_UNIDAD_ARTTAR`, '')
                   ORDER BY t.`FECHA_DESDE_ARTTAR` DESC,
                            t.`CODIGO_UNICO_ARTTAR` DESC
               ) AS `POSICION`
          FROM `fza_articulos_tarifas` t
          JOIN `tmp_mva_arts0` a0
            ON a0.`CODIGO_ART` = t.`CODIGO_ART_ARTTAR`
         WHERE t.`CODIGO_TAR_ARTTAR` = v_tarifa
           AND t.`ESACTIVO_ARTTAR` = 'S'
           AND (t.`FECHA_DESDE_ARTTAR` IS NULL
                OR t.`FECHA_DESDE_ARTTAR` <= CURRENT_DATE)
           AND (t.`FECHA_HASTA_ARTTAR` IS NULL
                OR t.`FECHA_HASTA_ARTTAR` >= CURRENT_DATE)
    )




    , `candidatas` AS (
        SELECT sku.`CODIGO_UNIDAD`,
               v.`CODIGO_UNIDAD` AS `UNIDAD_TARIFA`,
               v.`PRECIO_SALIDA`, v.`PRECIO_FINAL`,
               ROW_NUMBER() OVER (
                   PARTITION BY sku.`CODIGO_UNIDAD`
                   ORDER BY CASE
                       WHEN v.`CODIGO_UNIDAD` = sku.`CODIGO_UNIDAD`
                           THEN 0
                       WHEN LOCATE('/*/', v.`CODIGO_UNIDAD`) > 0 THEN 1
                       WHEN v.`CODIGO_UNIDAD` <> '' THEN 2
                       ELSE 3 END,
                       CHAR_LENGTH(v.`CODIGO_UNIDAD`) DESC
               ) AS `ORDEN`
          FROM `tmp_mva_skus` sku
          JOIN `vigentes` v
            ON v.`CODIGO_ART` = sku.`CODIGO_ART`
           AND v.`POSICION` = 1
           AND (v.`CODIGO_UNIDAD` = ''
                OR v.`CODIGO_UNIDAD` = sku.`CODIGO_UNIDAD`
                OR (LOCATE('/*/', v.`CODIGO_UNIDAD`) = 0
                    AND LEFT(sku.`CODIGO_UNIDAD`,
                             CHAR_LENGTH(v.`CODIGO_UNIDAD`) + 1)
                        = CONCAT(v.`CODIGO_UNIDAD`, '/'))
                OR (LOCATE('/*/', v.`CODIGO_UNIDAD`) > 0
                    AND LEFT(sku.`CODIGO_UNIDAD`,
                             LOCATE('/*/', v.`CODIGO_UNIDAD`))
                        = LEFT(v.`CODIGO_UNIDAD`,
                               LOCATE('/*/', v.`CODIGO_UNIDAD`))
                    AND RIGHT(sku.`CODIGO_UNIDAD`,
                              CHAR_LENGTH(v.`CODIGO_UNIDAD`)
                              - LOCATE('/*/', v.`CODIGO_UNIDAD`) - 1)
                        = SUBSTRING(v.`CODIGO_UNIDAD`,
                                    LOCATE('/*/', v.`CODIGO_UNIDAD`)
                                    + 2)))
    )
    SELECT c.`CODIGO_UNIDAD`,
           IF(c.`UNIDAD_TARIFA` = '', 'N', 'S'),
           c.`PRECIO_SALIDA`, c.`PRECIO_FINAL`
      FROM `candidatas` c
     WHERE c.`ORDEN` = 1;


    DROP TEMPORARY TABLE IF EXISTS `tmp_mva_pvp`;
    CREATE TEMPORARY TABLE `tmp_mva_pvp` (
        `CODIGO_ART`    VARCHAR(20)   NOT NULL,
        `ID_COLOR`      INT           NOT NULL DEFAULT 0,
        `ID_COPA`       INT          NOT NULL DEFAULT 0,
        `ID_TALLA`      INT           NOT NULL DEFAULT 0,
        `PRECIO_SALIDA` DECIMAL(19,6) NULL,
        `PRECIO_FINAL`  DECIMAL(19,6) NULL,
        PRIMARY KEY (`CODIGO_ART`, `ID_COLOR`, `ID_COPA`, `ID_TALLA`)
    );
    INSERT INTO `tmp_mva_pvp`
        (`CODIGO_ART`, `ID_COLOR`, `ID_COPA`, `ID_TALLA`, `PRECIO_SALIDA`,
         `PRECIO_FINAL`)
    SELECT p.`CODIGO_ART`, p.`ID_COLOR`, p.`ID_COPA`, p.`ID_TALLA`,
           p.`PRECIO_SALIDA` * p.`FACTOR_IVA`,
           p.`PRECIO_FINAL` * p.`FACTOR_IVA`
      FROM (
            SELECT sc.`CODIGO_ART`, sc.`ID_COLOR`, sc.`ID_COPA`, sc.`ID_TALLA`,
                   IF(MIN(tf.`PRECIO_SALIDA`) = MAX(tf.`PRECIO_SALIDA`),
                      MAX(tf.`PRECIO_SALIDA`), NULL) AS `PRECIO_SALIDA`,
                   IF(MIN(tf.`PRECIO_FINAL`) = MAX(tf.`PRECIO_FINAL`),
                      MAX(tf.`PRECIO_FINAL`), NULL) AS `PRECIO_FINAL`,
                   IF(v_imp_incl = 'S', 1,
                      1 + CASE COALESCE(NULLIF(MAX(a.`TIPO_IVA_ART`), ''), 'N')
                              WHEN 'R' THEN v_iva_r
                              WHEN 'S' THEN v_iva_s
                              WHEN 'E' THEN v_iva_e
                              ELSE v_iva_n
                          END / 100) AS `FACTOR_IVA`
              FROM `tmp_mva_tarifa` tf
              JOIN `tmp_mva_sku_color` sc
                ON sc.`CODIGO_UNIDAD` = tf.`CODIGO_UNIDAD`
              JOIN `fza_articulos` a
                ON a.`CODIGO_ART_ART` = sc.`CODIGO_ART`
             GROUP BY sc.`CODIGO_ART`, sc.`ID_COLOR`, sc.`ID_COPA`, sc.`ID_TALLA`
           ) p;


    DROP TEMPORARY TABLE IF EXISTS `tmp_mva_arts`;
    CREATE TEMPORARY TABLE `tmp_mva_arts` (
        `CODIGO_ART` VARCHAR(20) NOT NULL PRIMARY KEY
    );
    INSERT IGNORE INTO `tmp_mva_arts` (`CODIGO_ART`)
    SELECT a0.`CODIGO_ART`
      FROM `tmp_mva_arts0` a0;


    DROP TEMPORARY TABLE IF EXISTS `tmp_mva_coste`;
    CREATE TEMPORARY TABLE `tmp_mva_coste` (
        `CODIGO_ART` VARCHAR(20)   NOT NULL,
        `ID_COLOR`   INT           NOT NULL DEFAULT 0,
        `ID_COPA`       INT          NOT NULL DEFAULT 0,
        `ID_TALLA`   INT           NOT NULL DEFAULT 0,
        `COSTE`      DECIMAL(19,6) NOT NULL DEFAULT 0,
        PRIMARY KEY (`CODIGO_ART`, `ID_COLOR`, `ID_COPA`, `ID_TALLA`)
    );
    INSERT INTO `tmp_mva_coste`
        (`CODIGO_ART`, `ID_COLOR`, `ID_COPA`, `ID_TALLA`, `COSTE`)
    SELECT sc.`CODIGO_ART`, sc.`ID_COLOR`, sc.`ID_COPA`, sc.`ID_TALLA`,
           IF(SUM(st.`CANTIDAD_STK`) <> 0,
              SUM(st.`VALOR_TOTAL_STK`) / SUM(st.`CANTIDAD_STK`), 0)
      FROM `fza_articulos_stockactual` st
      JOIN `tmp_mva_sku_color` sc
        ON sc.`CODIGO_UNIDAD` = st.`CODIGO_UNIDAD_STK`
     WHERE
       (p_PROVEEDORES = '' OR EXISTS (
         SELECT 1 FROM fza_articulos_lotes LP
          WHERE LP.CODIGO_UNIDAD_LOT = st.CODIGO_UNIDAD_STK
            AND LP.LOTE_LOT = st.LOTE_STK
            AND COALESCE(TRIM(LP.CODIGO_PRV_LOT), '') NOT IN ('', '0')
            AND FIND_IN_SET(LP.CODIGO_PRV_LOT, p_PROVEEDORES) > 0)
        OR (NOT EXISTS (
         SELECT 1 FROM fza_articulos_lotes LP
          WHERE LP.CODIGO_UNIDAD_LOT = st.CODIGO_UNIDAD_STK
            AND LP.LOTE_LOT = st.LOTE_STK
            AND COALESCE(TRIM(LP.CODIGO_PRV_LOT), '') NOT IN ('', '0')) AND EXISTS (
         SELECT 1 FROM fza_articulos_proveedores APF
          WHERE APF.CODIGO_ART_AP = (SELECT SF.CODIGO_ART_SKU FROM fza_articulos_skus SF WHERE SF.CODIGO_UNIDAD_SKU = st.CODIGO_UNIDAD_STK)
            AND FIND_IN_SET(APF.CODIGO_PRV_AP, p_PROVEEDORES) > 0))) AND st.`CODIGO_ALM_STK` IN
           (SELECT `CODIGO_ALM` FROM `tmp_mva_alm`)
     GROUP BY sc.`CODIGO_ART`, sc.`ID_COLOR`, sc.`ID_COPA`, sc.`ID_TALLA`;


    DROP TEMPORARY TABLE IF EXISTS `tmp_mva_base`;
    CREATE TEMPORARY TABLE `tmp_mva_base` (
        `CODIGO_ART` VARCHAR(20) NOT NULL,
        `ID_COLOR`   INT         NOT NULL DEFAULT 0,
        `ID_COPA`       INT          NOT NULL DEFAULT 0,
        `ID_TALLA`   INT         NOT NULL DEFAULT 0,
        `CODIGO_ALM` VARCHAR(50) NOT NULL DEFAULT '',
        PRIMARY KEY (`CODIGO_ART`, `ID_COLOR`, `ID_COPA`, `ID_TALLA`, `CODIGO_ALM`)
    );
    INSERT IGNORE INTO `tmp_mva_base`
        (`CODIGO_ART`, `ID_COLOR`, `ID_COPA`, `ID_TALLA`, `CODIGO_ALM`)
    SELECT e.`CODIGO_ART`, e.`ID_COLOR`, e.`ID_COPA`, e.`ID_TALLA`, e.`CODIGO_ALM`
      FROM `tmp_mva_ent` e
     WHERE e.`CODIGO_ART` IN
           (SELECT `CODIGO_ART` FROM `tmp_mva_arts`);
    INSERT IGNORE INTO `tmp_mva_base`
        (`CODIGO_ART`, `ID_COLOR`, `ID_COPA`, `ID_TALLA`, `CODIGO_ALM`)
    SELECT v.`CODIGO_ART`, v.`ID_COLOR`, v.`ID_COPA`, v.`ID_TALLA`, v.`CODIGO_ALM`
      FROM `tmp_mva_ven` v
     WHERE v.`CODIGO_ART` IN
           (SELECT `CODIGO_ART` FROM `tmp_mva_arts`);


    DROP TEMPORARY TABLE IF EXISTS `tmp_mva_tot_g3`;
    DROP TEMPORARY TABLE IF EXISTS `tmp_mva_tot_g2`;
    DROP TEMPORARY TABLE IF EXISTS `tmp_mva_tot_g1`;
    DROP TEMPORARY TABLE IF EXISTS `tmp_mva_tot_global`;
    DROP TEMPORARY TABLE IF EXISTS `tmp_mva_resultado`;
    CREATE TEMPORARY TABLE `tmp_mva_resultado` AS
    SELECT
        COALESCE(fam.`ORDEN_FAM`, 999999)             AS `ORDEN_FAM`,
        art.`CODIGO_FAM_ART`                          AS `CODIGO_FAM`,
        COALESCE(fam.`DESCRIPCION_FAM`,
                 fam.`NOMBRE_FAM_FAM`, art.`CODIGO_FAM_ART`)
                                                       AS `DESCRIPCION_FAM`,
        b.`CODIGO_ART`                                AS `CODIGO_ART_ART`,
        art.`DESCRIPCION_ART`                         AS `DESCRIPCION_ART`,
        prov.`REF_PROVEEDOR_AP`                       AS `REF_PRV`,
        ROUND(COALESCE(NULLIF(cst.`COSTE`, 0),
                       prov.`COSTE_PRV`, 0), 2)        AS `COSTE_ART`,


        ROUND(CASE WHEN v.`CODIGO_ART` IS NOT NULL THEN
          IF(v.`PRECIO_FINAL_MIN` = v.`PRECIO_FINAL_MAX`,
             v.`PRECIO_FINAL_MAX`, 0)
          ELSE COALESCE(pv.`PRECIO_FINAL`, 0) END, 2) AS `PVP_ART`,
        ROUND(CASE WHEN v.`CODIGO_ART` IS NOT NULL THEN
          IF(v.`PRECIO_SALIDA_MIN` = v.`PRECIO_SALIDA_MAX`,
             v.`PRECIO_SALIDA_MAX`, 0)
          ELSE COALESCE(pv.`PRECIO_SALIDA`, 0) END, 2)
                                                       AS `PRECIO_SALIDA_ART`,
        SUBSTRING_INDEX(b.`CODIGO_ALM`, CHAR(31 USING utf8mb4), 1) AS `CODIGO_ALM`,
        COALESCE(alm.`NOMBRE_ALM_ALM`, '')            AS `NOMBRE_ALM`,
        COALESCE(e.`UNI_ENT`, 0)            AS `UNI_ENT_TOT`,
        COALESCE(e.`IMP_ENT`, 0)            AS `IMP_ENT_TOT`,
        COALESCE(v.`UDS_VEN`, 0)            AS `UDS_VENTA`,
        COALESCE(v.`IMP_VEN`, 0)            AS `IMP_VENTA`,
        COALESCE(v.`IMP_VEN_REG`, 0)        AS `IMP_VENTA_REGIMEN`,
        COALESCE(cv.`COSTE_VEN`,
              COALESCE(v.`UDS_VEN`, 0)
              * COALESCE(NULLIF(cst.`COSTE`, 0),
                         prov.`COSTE_PRV`, 0))     AS `IMP_COSTE`,
        COALESCE(v.`IMP_VEN_REG`, 0)
              - COALESCE(cv.`COSTE_VEN`,
                COALESCE(v.`UDS_VEN`, 0)
                * COALESCE(NULLIF(cst.`COSTE`, 0),
                           prov.`COSTE_PRV`, 0))   AS `BENEFICIO`,
        COALESCE(v.`IMP_VEN_REG`, 0)
              - COALESCE(e.`IMP_ENT`, 0)          AS `VENTA_ENT`,
        ROUND(IF(COALESCE(v.`IMP_VEN_REG`, 0) <> 0,
                 (COALESCE(v.`IMP_VEN_REG`, 0)
                  - COALESCE(cv.`COSTE_VEN`,
                    COALESCE(v.`UDS_VEN`, 0)
                    * COALESCE(NULLIF(cst.`COSTE`, 0),
                               prov.`COSTE_PRV`, 0)))
                 / COALESCE(v.`IMP_VEN_REG`, 0)
                 * 100, 0), 2)                        AS `PCT_BNFCO`,
        ROUND(IF(COALESCE(e.`IMP_ENT`, 0) <> 0,
                 COALESCE(v.`IMP_VEN_REG`, 0)
                 / COALESCE(e.`IMP_ENT`, 0) * 100, 0), 2)
                                                       AS `VENT_ENT`,
        ROUND(IF(COALESCE(cv.`COSTE_VEN`,
                 COALESCE(v.`UDS_VEN`, 0)
                 * COALESCE(NULLIF(cst.`COSTE`, 0),
                            prov.`COSTE_PRV`, 0)) <> 0,
                 (COALESCE(v.`IMP_VEN_REG`, 0)
                  - COALESCE(cv.`COSTE_VEN`,
                    COALESCE(v.`UDS_VEN`, 0)
                    * COALESCE(NULLIF(cst.`COSTE`, 0),
                               prov.`COSTE_PRV`, 0)))
                 / COALESCE(cv.`COSTE_VEN`,
                    COALESCE(v.`UDS_VEN`, 0)
                    * COALESCE(NULLIF(cst.`COSTE`, 0),
                               prov.`COSTE_PRV`, 0))
                 * 100, 0), 2)
                                                       AS `MARGEN1`,
        ROUND(IF(COALESCE(e.`IMP_ENT`, 0) <> 0,
                 (COALESCE(v.`IMP_VEN_REG`, 0) - COALESCE(e.`IMP_ENT`, 0))
                 / COALESCE(e.`IMP_ENT`, 0) * 100, 0), 2)
                                                       AS `MARGEN2`,
        ROUND(IF(COALESCE(e.`UNI_ENT`, 0) <> 0,
                 COALESCE(v.`UDS_VEN`, 0) / COALESCE(e.`UNI_ENT`, 0)
                 * 100, 0), 2)                        AS `PCT_VDTO`,

        CAST(0 AS DECIMAL(19,2))                       AS `PCT_VLAST`,



        CASE p_NIVEL1
            WHEN 'ART' THEN b.`CODIGO_ART`
            WHEN 'PRV' THEN IF(v_por_prv, SUBSTRING_INDEX(b.`CODIGO_ALM`, CHAR(31 USING utf8mb4), -1), COALESCE(prov.`CODIGO_PRV`, ''))
            WHEN 'FAM' THEN COALESCE(
                 fg.`COD_GRP`, art.`CODIGO_FAM_ART`, '')
            WHEN 'TMP' THEN COALESCE(tmp.`TEMPORADA`, '')
            WHEN 'ALM' THEN SUBSTRING_INDEX(b.`CODIGO_ALM`, CHAR(31 USING utf8mb4), 1)
            WHEN 'COL' THEN CONCAT(
                 LPAD(COALESCE(col.`ORDEN_COLOR`, 0), 10, '0'), ':',
                 COALESCE(col.`CLAVE_COLOR`, ''))
            WHEN 'COP' THEN CONCAT(
                 LPAD(COALESCE(copa.`ORDEN_AV`, 0), 10, '0'), ':',
                 UPPER(TRIM(COALESCE(copa.`AV`, ''))))
            WHEN 'TAL' THEN CONCAT(
                 LPAD(COALESCE(tal.`ORDEN_TALLA`, 0), 10, '0'), ':',
                 COALESCE(tal.`CLAVE_TALLA`, ''))
            ELSE ''
        END                                           AS `GRUPO1_COD`,
        CASE p_NIVEL1
            WHEN 'ART' THEN CONCAT(
                 'Artículo: ', b.`CODIGO_ART`, ' - ',
                 COALESCE(NULLIF(art.`DESCRIPCION_ART`, ''),
                          '(sin descripción)'))
            WHEN 'PRV' THEN CONCAT('Proveedor: ',
                 COALESCE(NULLIF(gprv.`RAZON_SOCIAL_PRV`, ''),
                          NULLIF(SUBSTRING_INDEX(b.`CODIGO_ALM`, CHAR(31 USING utf8mb4), -1), ''),
                          '(sin proveedor)'))
            WHEN 'FAM' THEN CONCAT('Familia: ',
                 COALESCE(fg.`DESC_GRP`, fg.`COD_GRP`,
                          art.`CODIGO_FAM_ART`))
            WHEN 'TMP' THEN CONCAT('Temporada: ',
                 COALESCE(NULLIF(tmp.`TEMPORADA`, ''), '(sin temporada)'))
            WHEN 'ALM' THEN CONCAT('Almacén: ',
                 COALESCE(NULLIF(alm.`NOMBRE_ALM_ALM`, ''), SUBSTRING_INDEX(b.`CODIGO_ALM`, CHAR(31 USING utf8mb4), 1),
                          '(sin almacén)'))
            WHEN 'COL' THEN CONCAT('Color: ',
                 COALESCE(NULLIF(col.`COLOR`, ''), '(sin color)'))
            WHEN 'COP' THEN CONCAT('Copa: ',
                 COALESCE(NULLIF(copa.`AV`, ''), '(sin copa)'))
            WHEN 'TAL' THEN CONCAT('Talla: ',
                 COALESCE(NULLIF(tal.`TALLA`, ''), '(sin talla)'))
            ELSE ''
        END                                           AS `GRUPO1_ETIQ`,
        CASE p_NIVEL2
            WHEN 'ART' THEN b.`CODIGO_ART`
            WHEN 'PRV' THEN IF(v_por_prv, SUBSTRING_INDEX(b.`CODIGO_ALM`, CHAR(31 USING utf8mb4), -1), COALESCE(prov.`CODIGO_PRV`, ''))
            WHEN 'FAM' THEN COALESCE(
                 fg.`COD_GRP`, art.`CODIGO_FAM_ART`, '')
            WHEN 'TMP' THEN COALESCE(tmp.`TEMPORADA`, '')
            WHEN 'ALM' THEN SUBSTRING_INDEX(b.`CODIGO_ALM`, CHAR(31 USING utf8mb4), 1)
            WHEN 'COL' THEN CONCAT(
                 LPAD(COALESCE(col.`ORDEN_COLOR`, 0), 10, '0'), ':',
                 COALESCE(col.`CLAVE_COLOR`, ''))
            WHEN 'COP' THEN CONCAT(
                 LPAD(COALESCE(copa.`ORDEN_AV`, 0), 10, '0'), ':',
                 UPPER(TRIM(COALESCE(copa.`AV`, ''))))
            WHEN 'TAL' THEN CONCAT(
                 LPAD(COALESCE(tal.`ORDEN_TALLA`, 0), 10, '0'), ':',
                 COALESCE(tal.`CLAVE_TALLA`, ''))
            ELSE ''
        END                                           AS `GRUPO2_COD`,
        CASE p_NIVEL2
            WHEN 'ART' THEN CONCAT(
                 'Artículo: ', b.`CODIGO_ART`, ' - ',
                 COALESCE(NULLIF(art.`DESCRIPCION_ART`, ''),
                          '(sin descripción)'))
            WHEN 'PRV' THEN CONCAT('Proveedor: ',
                 COALESCE(NULLIF(gprv.`RAZON_SOCIAL_PRV`, ''),
                          NULLIF(SUBSTRING_INDEX(b.`CODIGO_ALM`, CHAR(31 USING utf8mb4), -1), ''),
                          '(sin proveedor)'))
            WHEN 'FAM' THEN CONCAT('Familia: ',
                 COALESCE(fg.`DESC_GRP`, fg.`COD_GRP`,
                          art.`CODIGO_FAM_ART`))
            WHEN 'TMP' THEN CONCAT('Temporada: ',
                 COALESCE(NULLIF(tmp.`TEMPORADA`, ''), '(sin temporada)'))
            WHEN 'ALM' THEN CONCAT('Almacén: ',
                 COALESCE(NULLIF(alm.`NOMBRE_ALM_ALM`, ''), SUBSTRING_INDEX(b.`CODIGO_ALM`, CHAR(31 USING utf8mb4), 1),
                          '(sin almacén)'))
            WHEN 'COL' THEN CONCAT('Color: ',
                 COALESCE(NULLIF(col.`COLOR`, ''), '(sin color)'))
            WHEN 'COP' THEN CONCAT('Copa: ',
                 COALESCE(NULLIF(copa.`AV`, ''), '(sin copa)'))
            WHEN 'TAL' THEN CONCAT('Talla: ',
                 COALESCE(NULLIF(tal.`TALLA`, ''), '(sin talla)'))
            ELSE ''
        END                                           AS `GRUPO2_ETIQ`,
        CASE p_NIVEL3
            WHEN 'ART' THEN b.`CODIGO_ART`
            WHEN 'PRV' THEN IF(v_por_prv, SUBSTRING_INDEX(b.`CODIGO_ALM`, CHAR(31 USING utf8mb4), -1), COALESCE(prov.`CODIGO_PRV`, ''))
            WHEN 'FAM' THEN COALESCE(
                 fg.`COD_GRP`, art.`CODIGO_FAM_ART`, '')
            WHEN 'TMP' THEN COALESCE(tmp.`TEMPORADA`, '')
            WHEN 'ALM' THEN SUBSTRING_INDEX(b.`CODIGO_ALM`, CHAR(31 USING utf8mb4), 1)
            WHEN 'COL' THEN CONCAT(
                 LPAD(COALESCE(col.`ORDEN_COLOR`, 0), 10, '0'), ':',
                 COALESCE(col.`CLAVE_COLOR`, ''))
            WHEN 'COP' THEN CONCAT(
                 LPAD(COALESCE(copa.`ORDEN_AV`, 0), 10, '0'), ':',
                 UPPER(TRIM(COALESCE(copa.`AV`, ''))))
            WHEN 'TAL' THEN CONCAT(
                 LPAD(COALESCE(tal.`ORDEN_TALLA`, 0), 10, '0'), ':',
                 COALESCE(tal.`CLAVE_TALLA`, ''))
            ELSE ''
        END                                           AS `GRUPO3_COD`,
        CASE p_NIVEL3
            WHEN 'ART' THEN CONCAT(
                 'Artículo: ', b.`CODIGO_ART`, ' - ',
                 COALESCE(NULLIF(art.`DESCRIPCION_ART`, ''),
                          '(sin descripción)'))
            WHEN 'PRV' THEN CONCAT('Proveedor: ',
                 COALESCE(NULLIF(gprv.`RAZON_SOCIAL_PRV`, ''),
                          NULLIF(SUBSTRING_INDEX(b.`CODIGO_ALM`, CHAR(31 USING utf8mb4), -1), ''),
                          '(sin proveedor)'))
            WHEN 'FAM' THEN CONCAT('Familia: ',
                 COALESCE(fg.`DESC_GRP`, fg.`COD_GRP`,
                          art.`CODIGO_FAM_ART`))
            WHEN 'TMP' THEN CONCAT('Temporada: ',
                 COALESCE(NULLIF(tmp.`TEMPORADA`, ''), '(sin temporada)'))
            WHEN 'ALM' THEN CONCAT('Almacén: ',
                 COALESCE(NULLIF(alm.`NOMBRE_ALM_ALM`, ''), SUBSTRING_INDEX(b.`CODIGO_ALM`, CHAR(31 USING utf8mb4), 1),
                          '(sin almacén)'))
            WHEN 'COL' THEN CONCAT('Color: ',
                 COALESCE(NULLIF(col.`COLOR`, ''), '(sin color)'))
            WHEN 'COP' THEN CONCAT('Copa: ',
                 COALESCE(NULLIF(copa.`AV`, ''), '(sin copa)'))
            WHEN 'TAL' THEN CONCAT('Talla: ',
                 COALESCE(NULLIF(tal.`TALLA`, ''), '(sin talla)'))
            ELSE ''
        END                                           AS `GRUPO3_ETIQ`,


        b.`ID_COLOR`                                  AS `ID_COLOR`,
        COALESCE(col.`COLOR`, '')                     AS `COLOR`,
        COALESCE(col.`COLOR_ETIQUETA`, '')            AS `COLOR_ETIQUETA`,
        COALESCE(col.`ORDEN_COLOR`, 0)                AS `ORDEN_COLOR`,
        b.`ID_TALLA`                                  AS `ID_TALLA`,
        COALESCE(tal.`TALLA`, '')                     AS `TALLA`,
        COALESCE(tal.`TALLA_ETIQUETA`, '')            AS `TALLA_ETIQUETA`,
        COALESCE(tal.`ORDEN_TALLA`, 0)                AS `ORDEN_TALLA`,
        b.`ID_COPA`, COALESCE(copa.`AV`, '') AS `COPA`,
        COALESCE(copa.`ORDEN_AV`, 0) AS `ORDEN_COPA`
      FROM `tmp_mva_base` b
      JOIN `fza_articulos` art
        ON art.`CODIGO_ART_ART` = b.`CODIGO_ART`
      LEFT JOIN `tmp_mva_ent` e
        ON e.`CODIGO_ART` = b.`CODIGO_ART`
       AND e.`ID_COLOR` = b.`ID_COLOR`
       AND e.`ID_COPA` = b.`ID_COPA`
       AND e.`ID_TALLA` = b.`ID_TALLA`
       AND e.`CODIGO_ALM` = b.`CODIGO_ALM`
      LEFT JOIN `tmp_mva_ven` v
        ON v.`CODIGO_ART` = b.`CODIGO_ART`
       AND v.`ID_COLOR` = b.`ID_COLOR`
       AND v.`ID_COPA` = b.`ID_COPA`
       AND v.`ID_TALLA` = b.`ID_TALLA`
       AND v.`CODIGO_ALM` = b.`CODIGO_ALM`
      LEFT JOIN `tmp_mva_coste_ven` cv
        ON cv.`CODIGO_ART` = b.`CODIGO_ART`
       AND cv.`ID_COLOR` = b.`ID_COLOR`
       AND cv.`ID_COPA` = b.`ID_COPA`
       AND cv.`ID_TALLA` = b.`ID_TALLA`
       AND cv.`CODIGO_ALM` = b.`CODIGO_ALM`
      LEFT JOIN `tmp_mva_coste` cst
        ON cst.`CODIGO_ART` = b.`CODIGO_ART`
       AND cst.`ID_COLOR` = b.`ID_COLOR`
       AND cst.`ID_COPA` = b.`ID_COPA`
       AND cst.`ID_TALLA` = b.`ID_TALLA`
      LEFT JOIN `tmp_mva_pvp` pv
        ON pv.`CODIGO_ART` = b.`CODIGO_ART`
       AND pv.`ID_COLOR` = b.`ID_COLOR`
       AND pv.`ID_COPA` = b.`ID_COPA`
       AND pv.`ID_TALLA` = b.`ID_TALLA`
      LEFT JOIN `tmp_mva_color` col
        ON col.`CODIGO_ART` = b.`CODIGO_ART`
       AND col.`ID_COLOR` = b.`ID_COLOR`
       AND col.`ID_COPA` = b.`ID_COPA`
      LEFT JOIN `fza_atributos_valores` copa
        ON copa.`ID_AV` = b.`ID_COPA`
      LEFT JOIN `tmp_mva_talla` tal
        ON tal.`CODIGO_ART` = b.`CODIGO_ART`
       AND tal.`ID_TALLA` = b.`ID_TALLA`
      LEFT JOIN `tmp_mva_temporada` tmp
        ON tmp.`CODIGO_ART` = b.`CODIGO_ART`
       AND tmp.`ID_COLOR` = b.`ID_COLOR`
       AND tmp.`ID_COPA` = b.`ID_COPA`
      LEFT JOIN `fza_articulos_familias` fam
        ON fam.`CODIGO_FAM_FAM` = art.`CODIGO_FAM_ART`
      LEFT JOIN `tmp_mva_fam_grp` fg
        ON fg.`CODIGO_FAM` = art.`CODIGO_FAM_ART`
      LEFT JOIN `fza_almacenes` alm
        ON alm.`CODIGO_ALM_ALM` = SUBSTRING_INDEX(b.`CODIGO_ALM`, CHAR(31 USING utf8mb4), 1)
      
      LEFT JOIN `fza_proveedores` gprv
        ON v_por_prv AND gprv.`CODIGO_PRV_PRV` = SUBSTRING_INDEX(b.`CODIGO_ALM`, CHAR(31 USING utf8mb4), -1)
      LEFT JOIN (
            SELECT ap.`CODIGO_ART_AP` AS `CODIGO_ART`,
                   MAX(ap.`REF_PROVEEDOR_AP`)     AS `REF_PROVEEDOR_AP`,
                   MAX(ap.`PRECIO_ULT_COMPRA_AP`) AS `COSTE_PRV`,
                   MAX(ap.`CODIGO_PRV_AP`)        AS `CODIGO_PRV`,
                   MAX(pr.`RAZON_SOCIAL_PRV`)     AS `RAZON`
              FROM `fza_articulos_proveedores` ap
              LEFT JOIN `fza_proveedores` pr
                ON pr.`CODIGO_PRV_PRV` = ap.`CODIGO_PRV_AP`
             WHERE ap.`ESPROVEEDORPRINCIPAL_AP` = 'S'
               AND ap.`CODIGO_ART_AP` IN
                   (SELECT `CODIGO_ART` FROM `tmp_mva_arts0`)
             GROUP BY ap.`CODIGO_ART_AP`
           ) prov ON prov.`CODIGO_ART` = b.`CODIGO_ART`
     WHERE (p_SOLO_VENTAS <> 'S' OR COALESCE(v.`UDS_VEN`, 0) <> 0)



        AND (p_TEMPORADAS = '' OR NOT v_por_col
             OR FIND_IN_SET(COALESCE(tmp.`TEMPORADA`, ''), p_TEMPORADAS));


    ALTER TABLE `tmp_mva_resultado`
      ADD INDEX `IX_MVA_RESULTADO_G1` (`GRUPO1_COD`(100)),
      ADD INDEX `IX_MVA_RESULTADO_G2`
          (`GRUPO1_COD`(100), `GRUPO2_COD`(100)),
      ADD INDEX `IX_MVA_RESULTADO_G3`
          (`GRUPO1_COD`(100), `GRUPO2_COD`(100),
           `GRUPO3_COD`(100));



    CREATE TEMPORARY TABLE `tmp_mva_tot_global` AS
    SELECT ROUND(COALESCE(SUM(r.`UDS_VENTA`), 0), 2) AS `UDS_VENTA`
      FROM `tmp_mva_resultado` r;
    CREATE TEMPORARY TABLE `tmp_mva_tot_g1` AS
    SELECT r.`GRUPO1_COD`,
           MIN(COALESCE(r.`GRUPO1_ETIQ`, '')) AS `ETIQUETA_ORDEN`,
           ROUND(COALESCE(SUM(r.`UDS_VENTA`), 0), 2) AS `UDS_VENTA`,
           CASE p_ORDEN
               WHEN 'UE' THEN SUM(r.`UNI_ENT_TOT`)
               WHEN 'IE' THEN SUM(r.`IMP_ENT_TOT`)
               WHEN 'UV' THEN SUM(r.`UDS_VENTA`)
               WHEN 'IV' THEN SUM(r.`IMP_VENTA`)
               WHEN 'IC' THEN SUM(r.`IMP_COSTE`)
               WHEN 'IB' THEN SUM(r.`BENEFICIO`)
               WHEN 'PB' THEN IF(SUM(r.`IMP_VENTA_REGIMEN`) <> 0,
                    SUM(r.`BENEFICIO`) / SUM(r.`IMP_VENTA_REGIMEN`) * 100,
                    0)
               WHEN 'VC' THEN SUM(r.`VENTA_ENT`)
               WHEN 'VE' THEN IF(SUM(r.`IMP_ENT_TOT`) <> 0,
                    SUM(r.`IMP_VENTA_REGIMEN`) / SUM(r.`IMP_ENT_TOT`)
                    * 100, 0)
               WHEN 'M1' THEN IF(SUM(r.`IMP_COSTE`) <> 0,
                    SUM(r.`BENEFICIO`) / SUM(r.`IMP_COSTE`) * 100, 0)
               WHEN 'M2' THEN IF(SUM(r.`IMP_ENT_TOT`) <> 0,
                    SUM(r.`VENTA_ENT`) / SUM(r.`IMP_ENT_TOT`) * 100, 0)
               WHEN 'VD' THEN IF(SUM(r.`UNI_ENT_TOT`) <> 0,
                    SUM(r.`UDS_VENTA`) / SUM(r.`UNI_ENT_TOT`) * 100, 0)
               WHEN 'PV' THEN IF(gt.`UDS_VENTA` <> 0,
                    SUM(r.`UDS_VENTA`) / gt.`UDS_VENTA` * 100, 0)
               ELSE 0
           END AS `VALOR_ORDEN`
      FROM `tmp_mva_resultado` r
      CROSS JOIN `tmp_mva_tot_global` gt
     GROUP BY r.`GRUPO1_COD`, gt.`UDS_VENTA`;
    ALTER TABLE `tmp_mva_tot_g1`
      ADD INDEX `IX_MVA_TOT_G1` (`GRUPO1_COD`(100));
    CREATE TEMPORARY TABLE `tmp_mva_tot_g2` AS
    SELECT r.`GRUPO1_COD`,
           r.`GRUPO2_COD`,
           MIN(COALESCE(r.`GRUPO2_ETIQ`, '')) AS `ETIQUETA_ORDEN`,
           ROUND(COALESCE(SUM(r.`UDS_VENTA`), 0), 2) AS `UDS_VENTA`,
           CASE p_ORDEN
               WHEN 'UE' THEN SUM(r.`UNI_ENT_TOT`)
               WHEN 'IE' THEN SUM(r.`IMP_ENT_TOT`)
               WHEN 'UV' THEN SUM(r.`UDS_VENTA`)
               WHEN 'IV' THEN SUM(r.`IMP_VENTA`)
               WHEN 'IC' THEN SUM(r.`IMP_COSTE`)
               WHEN 'IB' THEN SUM(r.`BENEFICIO`)
               WHEN 'PB' THEN IF(SUM(r.`IMP_VENTA_REGIMEN`) <> 0,
                    SUM(r.`BENEFICIO`) / SUM(r.`IMP_VENTA_REGIMEN`) * 100,
                    0)
               WHEN 'VC' THEN SUM(r.`VENTA_ENT`)
               WHEN 'VE' THEN IF(SUM(r.`IMP_ENT_TOT`) <> 0,
                    SUM(r.`IMP_VENTA_REGIMEN`) / SUM(r.`IMP_ENT_TOT`)
                    * 100, 0)
               WHEN 'M1' THEN IF(SUM(r.`IMP_COSTE`) <> 0,
                    SUM(r.`BENEFICIO`) / SUM(r.`IMP_COSTE`) * 100, 0)
               WHEN 'M2' THEN IF(SUM(r.`IMP_ENT_TOT`) <> 0,
                    SUM(r.`VENTA_ENT`) / SUM(r.`IMP_ENT_TOT`) * 100, 0)
               WHEN 'VD' THEN IF(SUM(r.`UNI_ENT_TOT`) <> 0,
                    SUM(r.`UDS_VENTA`) / SUM(r.`UNI_ENT_TOT`) * 100, 0)
               WHEN 'PV' THEN IF(g1.`UDS_VENTA` <> 0,
                    SUM(r.`UDS_VENTA`) / g1.`UDS_VENTA` * 100, 0)
               ELSE 0
           END AS `VALOR_ORDEN`
      FROM `tmp_mva_resultado` r
      JOIN `tmp_mva_tot_g1` g1
        ON g1.`GRUPO1_COD` = r.`GRUPO1_COD`
     GROUP BY r.`GRUPO1_COD`, r.`GRUPO2_COD`, g1.`UDS_VENTA`;
    ALTER TABLE `tmp_mva_tot_g2`
      ADD INDEX `IX_MVA_TOT_G2`
          (`GRUPO1_COD`(100), `GRUPO2_COD`(100));
    CREATE TEMPORARY TABLE `tmp_mva_tot_g3` AS
    SELECT r.`GRUPO1_COD`,
           r.`GRUPO2_COD`,
           r.`GRUPO3_COD`,
           MIN(COALESCE(r.`GRUPO3_ETIQ`, '')) AS `ETIQUETA_ORDEN`,
           ROUND(COALESCE(SUM(r.`UDS_VENTA`), 0), 2) AS `UDS_VENTA`,
           CASE p_ORDEN
               WHEN 'UE' THEN SUM(r.`UNI_ENT_TOT`)
               WHEN 'IE' THEN SUM(r.`IMP_ENT_TOT`)
               WHEN 'UV' THEN SUM(r.`UDS_VENTA`)
               WHEN 'IV' THEN SUM(r.`IMP_VENTA`)
               WHEN 'IC' THEN SUM(r.`IMP_COSTE`)
               WHEN 'IB' THEN SUM(r.`BENEFICIO`)
               WHEN 'PB' THEN IF(SUM(r.`IMP_VENTA_REGIMEN`) <> 0,
                    SUM(r.`BENEFICIO`) / SUM(r.`IMP_VENTA_REGIMEN`) * 100,
                    0)
               WHEN 'VC' THEN SUM(r.`VENTA_ENT`)
               WHEN 'VE' THEN IF(SUM(r.`IMP_ENT_TOT`) <> 0,
                    SUM(r.`IMP_VENTA_REGIMEN`) / SUM(r.`IMP_ENT_TOT`)
                    * 100, 0)
               WHEN 'M1' THEN IF(SUM(r.`IMP_COSTE`) <> 0,
                    SUM(r.`BENEFICIO`) / SUM(r.`IMP_COSTE`) * 100, 0)
               WHEN 'M2' THEN IF(SUM(r.`IMP_ENT_TOT`) <> 0,
                    SUM(r.`VENTA_ENT`) / SUM(r.`IMP_ENT_TOT`) * 100, 0)
               WHEN 'VD' THEN IF(SUM(r.`UNI_ENT_TOT`) <> 0,
                    SUM(r.`UDS_VENTA`) / SUM(r.`UNI_ENT_TOT`) * 100, 0)
               WHEN 'PV' THEN IF(g2.`UDS_VENTA` <> 0,
                    SUM(r.`UDS_VENTA`) / g2.`UDS_VENTA` * 100, 0)
               ELSE 0
           END AS `VALOR_ORDEN`
      FROM `tmp_mva_resultado` r
      JOIN `tmp_mva_tot_g2` g2
        ON g2.`GRUPO1_COD` = r.`GRUPO1_COD`
       AND g2.`GRUPO2_COD` = r.`GRUPO2_COD`
      GROUP BY r.`GRUPO1_COD`, r.`GRUPO2_COD`, r.`GRUPO3_COD`,
               g2.`UDS_VENTA`;
    ALTER TABLE `tmp_mva_tot_g3`
      ADD INDEX `IX_MVA_TOT_G3`
          (`GRUPO1_COD`(100), `GRUPO2_COD`(100),
           `GRUPO3_COD`(100));



    CREATE TEMPORARY TABLE `tmp_mva_salida` AS
    SELECT r.`ORDEN_FAM`,
           r.`CODIGO_FAM`,
           r.`DESCRIPCION_FAM`,
           r.`CODIGO_ART_ART`,
           r.`DESCRIPCION_ART`,
           r.`REF_PRV`,
           r.`COSTE_ART`,
           r.`PVP_ART`,
           r.`CODIGO_ALM`,
           r.`NOMBRE_ALM`,
           r.`UNI_ENT_TOT`,
           r.`IMP_ENT_TOT`,
           r.`UDS_VENTA`,
           r.`IMP_VENTA`,
           r.`IMP_COSTE`,
           r.`BENEFICIO`,
           r.`VENTA_ENT`,
           r.`PCT_BNFCO`,
           r.`VENT_ENT`,
           r.`MARGEN1`,
           r.`MARGEN2`,
           r.`PCT_VDTO`,
           ROUND(COALESCE(
               r.`UDS_VENTA` / NULLIF(
                   CASE
                       WHEN p_NIVEL3 <> '' THEN g3.`UDS_VENTA`
                       WHEN p_NIVEL2 <> '' THEN g2.`UDS_VENTA`
                       WHEN p_NIVEL1 <> '' THEN g1.`UDS_VENTA`
                       ELSE gt.`UDS_VENTA`
                   END, 0) * 100, 0), 2)               AS `PCT_VLAST`,
           r.`GRUPO1_COD`,
           r.`GRUPO1_ETIQ`,
           r.`GRUPO2_COD`,
           r.`GRUPO2_ETIQ`,
           r.`GRUPO3_COD`,
           r.`GRUPO3_ETIQ`,
           r.`ID_COLOR`,
           r.`COLOR`,
           r.`COLOR_ETIQUETA`,
           r.`ORDEN_COLOR`,
           gt.`UDS_VENTA`                              AS `UDS_VENTA_GLOBAL`,
           g1.`UDS_VENTA`                              AS `UDS_VENTA_G1`,
           g2.`UDS_VENTA`                              AS `UDS_VENTA_G2`,
           g3.`UDS_VENTA`                              AS `UDS_VENTA_G3`,
           r.`ID_TALLA`,
           r.`TALLA`,
           r.`TALLA_ETIQUETA`,
           r.`ORDEN_TALLA`,
           r.`IMP_VENTA_REGIMEN`,
           r.`PRECIO_SALIDA_ART`,
           g1.`ETIQUETA_ORDEN`                         AS `ORDEN_G1_ETIQUETA`,
           g1.`VALOR_ORDEN`                            AS `ORDEN_G1_VALOR`,
           g2.`ETIQUETA_ORDEN`                         AS `ORDEN_G2_ETIQUETA`,
           g2.`VALOR_ORDEN`                            AS `ORDEN_G2_VALOR`,
           g3.`ETIQUETA_ORDEN`                         AS `ORDEN_G3_ETIQUETA`,
           g3.`VALOR_ORDEN`                            AS `ORDEN_G3_VALOR`,
           r.`ID_COPA`, r.`COPA`, r.`ORDEN_COPA`
      FROM `tmp_mva_resultado` r
      CROSS JOIN `tmp_mva_tot_global` gt
      JOIN `tmp_mva_tot_g1` g1
        ON g1.`GRUPO1_COD` = r.`GRUPO1_COD`
      JOIN `tmp_mva_tot_g2` g2
        ON g2.`GRUPO1_COD` = r.`GRUPO1_COD`
       AND g2.`GRUPO2_COD` = r.`GRUPO2_COD`
      JOIN `tmp_mva_tot_g3` g3
        ON g3.`GRUPO1_COD` = r.`GRUPO1_COD`
       AND g3.`GRUPO2_COD` = r.`GRUPO2_COD`
       AND g3.`GRUPO3_COD` = r.`GRUPO3_COD`;




    SELECT r.`ORDEN_FAM`,
           r.`CODIGO_FAM`,
           r.`DESCRIPCION_FAM`,
           r.`CODIGO_ART_ART`,
           r.`DESCRIPCION_ART`,
           r.`REF_PRV`,
           r.`COSTE_ART`,
           r.`PVP_ART`,
           r.`CODIGO_ALM`,
           r.`NOMBRE_ALM`,
           r.`UNI_ENT_TOT`,
           r.`IMP_ENT_TOT`,
           r.`UDS_VENTA`,
           r.`IMP_VENTA`,
           r.`IMP_COSTE`,
           r.`BENEFICIO`,
           r.`VENTA_ENT`,
           r.`PCT_BNFCO`,
           r.`VENT_ENT`,
           r.`MARGEN1`,
           r.`MARGEN2`,
           r.`PCT_VDTO`,
           r.`PCT_VLAST`,
           r.`GRUPO1_COD`,
           r.`GRUPO1_ETIQ`,
           r.`GRUPO2_COD`,
           r.`GRUPO2_ETIQ`,
           r.`GRUPO3_COD`,
           r.`GRUPO3_ETIQ`,
           r.`ID_COLOR`,
           r.`COLOR`,
           r.`COLOR_ETIQUETA`,
           r.`ORDEN_COLOR`,
           r.`UDS_VENTA_GLOBAL`,
           r.`UDS_VENTA_G1`,
           r.`UDS_VENTA_G2`,
           r.`UDS_VENTA_G3`,
           r.`ID_TALLA`,
           r.`TALLA`,
           r.`TALLA_ETIQUETA`,
           r.`ORDEN_TALLA`,
           r.`IMP_VENTA_REGIMEN`,
           r.`PRECIO_SALIDA_ART`,
           r.`ID_COPA`, r.`COPA`, r.`ORDEN_COPA`
      FROM `tmp_mva_salida` r
     ORDER BY
           CASE WHEN p_ORDEN = 'AD' AND p_ORDEN_DESC = 'S'
                 THEN r.`ORDEN_G1_ETIQUETA` END DESC,
           CASE WHEN p_ORDEN = 'AD' AND p_ORDEN_DESC = 'N'
                 THEN r.`ORDEN_G1_ETIQUETA` END ASC,
           CASE WHEN p_ORDEN = 'AD' AND p_ORDEN_DESC = 'S'
                THEN r.`GRUPO1_COD` END DESC,
           CASE WHEN p_ORDEN = 'AD' AND p_ORDEN_DESC = 'N'
                THEN r.`GRUPO1_COD` END ASC,
           CASE WHEN p_ORDEN NOT IN ('', 'AD') AND p_ORDEN_DESC = 'S'
                 THEN r.`ORDEN_G1_VALOR` END DESC,
           CASE WHEN p_ORDEN NOT IN ('', 'AD') AND p_ORDEN_DESC = 'N'
                 THEN r.`ORDEN_G1_VALOR` END ASC,
           r.`GRUPO1_COD`,
           CASE WHEN p_ORDEN = 'AD' AND p_ORDEN_DESC = 'S'
                 THEN r.`ORDEN_G2_ETIQUETA` END DESC,
           CASE WHEN p_ORDEN = 'AD' AND p_ORDEN_DESC = 'N'
                 THEN r.`ORDEN_G2_ETIQUETA` END ASC,
           CASE WHEN p_ORDEN = 'AD' AND p_ORDEN_DESC = 'S'
                THEN r.`GRUPO2_COD` END DESC,
           CASE WHEN p_ORDEN = 'AD' AND p_ORDEN_DESC = 'N'
                THEN r.`GRUPO2_COD` END ASC,
           CASE WHEN p_ORDEN NOT IN ('', 'AD') AND p_ORDEN_DESC = 'S'
                 THEN r.`ORDEN_G2_VALOR` END DESC,
           CASE WHEN p_ORDEN NOT IN ('', 'AD') AND p_ORDEN_DESC = 'N'
                 THEN r.`ORDEN_G2_VALOR` END ASC,
           r.`GRUPO2_COD`,
           CASE WHEN p_ORDEN = 'AD' AND p_ORDEN_DESC = 'S'
                 THEN r.`ORDEN_G3_ETIQUETA` END DESC,
           CASE WHEN p_ORDEN = 'AD' AND p_ORDEN_DESC = 'N'
                 THEN r.`ORDEN_G3_ETIQUETA` END ASC,
           CASE WHEN p_ORDEN = 'AD' AND p_ORDEN_DESC = 'S'
                THEN r.`GRUPO3_COD` END DESC,
           CASE WHEN p_ORDEN = 'AD' AND p_ORDEN_DESC = 'N'
                THEN r.`GRUPO3_COD` END ASC,
           CASE WHEN p_ORDEN NOT IN ('', 'AD') AND p_ORDEN_DESC = 'S'
                 THEN r.`ORDEN_G3_VALOR` END DESC,
           CASE WHEN p_ORDEN NOT IN ('', 'AD') AND p_ORDEN_DESC = 'N'
                 THEN r.`ORDEN_G3_VALOR` END ASC,
           r.`GRUPO3_COD`,
           CASE WHEN p_ORDEN = 'AD' AND p_ORDEN_DESC = 'S' THEN
                COALESCE(NULLIF(r.`DESCRIPCION_ART`, ''),
                         r.`CODIGO_ART_ART`) END DESC,
           CASE WHEN p_ORDEN = 'AD' AND p_ORDEN_DESC = 'N' THEN
                COALESCE(NULLIF(r.`DESCRIPCION_ART`, ''),
                         r.`CODIGO_ART_ART`) END ASC,
           CASE WHEN p_ORDEN = 'AD' AND p_ORDEN_DESC = 'S'
                THEN r.`CODIGO_ART_ART` END DESC,
           CASE WHEN p_ORDEN = 'AD' AND p_ORDEN_DESC = 'N'
                THEN r.`CODIGO_ART_ART` END ASC,
           CASE WHEN p_ORDEN NOT IN ('', 'AD')
                     AND p_ORDEN_DESC = 'S' THEN
                CASE p_ORDEN
                    WHEN 'UE' THEN r.`UNI_ENT_TOT`
                    WHEN 'IE' THEN r.`IMP_ENT_TOT`
                    WHEN 'UV' THEN r.`UDS_VENTA`
                    WHEN 'IV' THEN r.`IMP_VENTA`
                    WHEN 'IC' THEN r.`IMP_COSTE`
                    WHEN 'IB' THEN r.`BENEFICIO`
                    WHEN 'PB' THEN r.`PCT_BNFCO`
                    WHEN 'VC' THEN r.`VENTA_ENT`
                    WHEN 'VE' THEN r.`VENT_ENT`
                    WHEN 'M1' THEN r.`MARGEN1`
                    WHEN 'M2' THEN r.`MARGEN2`
                    WHEN 'VD' THEN r.`PCT_VDTO`
                    WHEN 'PV' THEN r.`PCT_VLAST`
                END
           END DESC,
           CASE WHEN p_ORDEN NOT IN ('', 'AD')
                     AND p_ORDEN_DESC = 'N' THEN
                CASE p_ORDEN
                    WHEN 'UE' THEN r.`UNI_ENT_TOT`
                    WHEN 'IE' THEN r.`IMP_ENT_TOT`
                    WHEN 'UV' THEN r.`UDS_VENTA`
                    WHEN 'IV' THEN r.`IMP_VENTA`
                    WHEN 'IC' THEN r.`IMP_COSTE`
                    WHEN 'IB' THEN r.`BENEFICIO`
                    WHEN 'PB' THEN r.`PCT_BNFCO`
                    WHEN 'VC' THEN r.`VENTA_ENT`
                    WHEN 'VE' THEN r.`VENT_ENT`
                    WHEN 'M1' THEN r.`MARGEN1`
                    WHEN 'M2' THEN r.`MARGEN2`
                    WHEN 'VD' THEN r.`PCT_VDTO`
                    WHEN 'PV' THEN r.`PCT_VLAST`
                END
           END ASC,
           r.`ORDEN_FAM`, r.`CODIGO_FAM`, r.`CODIGO_ART_ART`,
           r.`ORDEN_COLOR`, r.`COLOR`, r.`ORDEN_COPA`, r.`COPA`,
           r.`ORDEN_TALLA`, r.`TALLA`,
           r.`CODIGO_ALM`;
    DROP TEMPORARY TABLE IF EXISTS tmp_mva_alm_factura;
END
;;
DELIMITER ;
