CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_PED_CREAR_ALBARAN_INICIO_OPCIONES`(
  IN p_NUMERO_PED varchar(20), IN p_SERIE_PED varchar(20),
  IN p_SERIE_NUEVA varchar(12), IN p_NUMERO_MANUAL varchar(20),
  IN p_FECHA date, IN p_ALMACEN varchar(10), IN p_FORMA_PAGO varchar(20),
  IN p_USUARIO varchar(100),
  OUT p_NUMERO_ALB varchar(20), OUT p_SERIE_ALB varchar(20))
BEGIN
  DECLARE v_EMPRESA varchar(10);
  DECLARE v_SERIE varchar(20);
  DECLARE v_NUMERO varchar(20);
  DECLARE v_NUMERO_TMP varchar(20);
  DECLARE v_SERIE_TMP varchar(20);
  DECLARE v_DIGITOS int;
  DECLARE v_FECHA date;
  SELECT CODIGO_EMP_PED,
         COALESCE(NULLIF(TRIM(p_SERIE_NUEVA), ''), SERIE_PED)
    INTO v_EMPRESA, v_SERIE
    FROM fza_pedidos
   WHERE NUMERO_PED = p_NUMERO_PED AND SERIE_PED = p_SERIE_PED;
  IF v_SERIE IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'El pedido no existe';
  END IF;
  SET v_FECHA = COALESCE(p_FECHA, CURRENT_DATE());
  IF COALESCE(TRIM(p_NUMERO_MANUAL), '') = '' THEN
    CALL PRC_PRE_RESERVAR_NUMERO('AV', v_EMPRESA, v_SERIE, p_USUARIO,
      v_NUMERO);
  ELSE
    SET v_NUMERO = TRIM(p_NUMERO_MANUAL);
    SELECT MAX(NUM_DIGITOS_CON) INTO v_DIGITOS FROM fza_contadores
     WHERE TIPO_DOC_CON = 'AV' AND EMPRESA_CON IN (v_EMPRESA, '-')
       AND SERIE_CON = v_SERIE;
    IF v_NUMERO REGEXP '^[0-9]+$' AND
       COALESCE(v_DIGITOS, 6) > LENGTH(v_NUMERO) THEN
      SET v_NUMERO = LPAD(v_NUMERO, COALESCE(v_DIGITOS, 6), '0');
    END IF;
  END IF;
  IF EXISTS (SELECT 1 FROM fza_albaranes
              WHERE SERIE_ALB = v_SERIE AND NUMERO_ALB = v_NUMERO) THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'El número indicado ya existe en la serie';
  END IF;
  CALL PRC_PED_CREAR_ALBARAN_INICIO(p_NUMERO_PED, p_SERIE_PED, p_USUARIO,
    v_NUMERO_TMP, v_SERIE_TMP);
  UPDATE fza_albaranes
     SET SERIE_ALB = v_SERIE,
         NUMERO_ALB = v_NUMERO,
         FECHA_ALB = v_FECHA,
         INSTANTE_MOVIMIENTO_ALB = IF(v_FECHA = CURRENT_DATE(), NOW(),
                                      CAST(v_FECHA AS datetime)),
         CODIGO_ALM_ALB = COALESCE(NULLIF(TRIM(p_ALMACEN), ''),
                                   CODIGO_ALM_ALB),
         FORMA_PAGO_ALB = COALESCE(NULLIF(TRIM(p_FORMA_PAGO), ''),
                                   FORMA_PAGO_ALB)
   WHERE SERIE_ALB = v_SERIE_TMP AND NUMERO_ALB = v_NUMERO_TMP;
  SET p_NUMERO_ALB = v_NUMERO;
  SET p_SERIE_ALB = v_SERIE;
END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
