CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_PREPARAR_RECIBOS_EFECTOS_COMPRA`(
    IN `p_SERIE`   VARCHAR(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_spanish_ci,
    IN `p_NUMERO`  VARCHAR(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_spanish_ci,
    IN `p_EFECTOS` TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_spanish_ci
)
BEGIN
    DECLARE v_plazo   INT;
    DECLARE v_importe DECIMAL(18,6);
    DECLARE v_letra   VARCHAR(150);

    SET p_EFECTOS = REPLACE(IFNULL(p_EFECTOS, ''), ' ', '');

    DROP TEMPORARY TABLE IF EXISTS `tmp_recibos_efectos_compra`;
    CREATE TEMPORARY TABLE `tmp_recibos_efectos_compra` (
        `SERIE_FAC_REC`                   VARCHAR(20)   NOT NULL,
        `NUMERO_FAC_REC`                  VARCHAR(20)   NOT NULL,
        `NUMERO_PLAZO_REC`                INT           NOT NULL,
        `ESTADO_RECIBO_REC`               VARCHAR(20)   NULL,
        `EUROS_RECIBO_REC`                DECIMAL(18,6) NULL,
        `FECHA_EXPEDICION_RECIBO_REC`     DATE          NULL,
        `FECHA_VENCIMIENTO_RECIBO_REC`    DATE          NULL,
        `IBAN_CLI_REC`                    VARCHAR(34)   NULL,
        `LOCALIDAD_EXPEDICION_RECIBO_REC` VARCHAR(200)  NULL,
        `CODIGO_CLI_REC`                  VARCHAR(20)   NULL,
        `RAZON_SOCIAL_CLI_REC`            VARCHAR(200)  NULL,
        `DIRECCION1_CLIENTE_RECIBO_REC`   VARCHAR(200)  NULL,
        `POBLACION_CLI_REC`               VARCHAR(200)  NULL,
        `PROVINCIA_CLI_REC`               VARCHAR(200)  NULL,
        `CODIGO_POSTAL_CLI_REC`           VARCHAR(15)   NULL,
        `IMPORTE_LETRA_RECIBO_REC`        VARCHAR(150)  NULL,
        PRIMARY KEY (`NUMERO_PLAZO_REC`)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;

    INSERT INTO `tmp_recibos_efectos_compra`
        (`SERIE_FAC_REC`, `NUMERO_FAC_REC`, `NUMERO_PLAZO_REC`,
         `ESTADO_RECIBO_REC`, `EUROS_RECIBO_REC`,
         `FECHA_EXPEDICION_RECIBO_REC`, `FECHA_VENCIMIENTO_RECIBO_REC`,
         `IBAN_CLI_REC`, `LOCALIDAD_EXPEDICION_RECIBO_REC`,
         `CODIGO_CLI_REC`, `RAZON_SOCIAL_CLI_REC`,
         `DIRECCION1_CLIENTE_RECIBO_REC`, `POBLACION_CLI_REC`,
         `PROVINCIA_CLI_REC`, `CODIGO_POSTAL_CLI_REC`)
    SELECT e.`SERIE_FACC_EFEC`, e.`NUMERO_FACC_EFEC`, e.`NUMERO_EFEC`,
           e.`ESTADO_EFEC`, ROUND(e.`IMPORTE_PAGADO_EFEC`, 2),
           e.`FECHA_PAGO_EFEC`,
           e.`FECHA_VENCIMIENTO_EFEC`,
           COALESCE(NULLIF(TRIM(e.`IBAN_EFEC`), ''), cli.`IBAN_PRV`),
           f.`POBLACION_EMPRESA_FACC`,
           COALESCE(NULLIF(e.`CODIGO_PRV_EFEC`, ''), f.`CODIGO_PRV_FACC`),
           COALESCE(NULLIF(f.`RAZON_SOCIAL_PRV_FACC`, ''),
                    e.`RAZON_SOCIAL_PRV_EFEC`),
           f.`DIRECCION1_PRV_FACC`, f.`POBLACION_PRV_FACC`,
           f.`PROVINCIA_PRV_FACC`, f.`CODIGO_POSTAL_PRV_FACC`
      FROM `fza_efectos_compra` e
      LEFT JOIN `fza_facturas_compra` f
        ON f.`SERIE_FACC` = e.`SERIE_FACC_EFEC`
       AND f.`NUMERO_FACC` = e.`NUMERO_FACC_EFEC`
      LEFT JOIN `fza_proveedores` cli
        ON cli.`CODIGO_PRV_PRV` =
           COALESCE(NULLIF(e.`CODIGO_PRV_EFEC`, ''), f.`CODIGO_PRV_FACC`)
     WHERE e.`SERIE_FACC_EFEC` = p_SERIE
       AND e.`NUMERO_FACC_EFEC` = p_NUMERO
       AND e.`ESTADO_EFEC` IN ('PAGADO', 'PARCIAL')
       AND e.`IMPORTE_PAGADO_EFEC` > 0
       AND (p_EFECTOS = '' OR FIND_IN_SET(e.`NUMERO_EFEC`, p_EFECTOS));

    
    SET v_plazo = (SELECT MIN(`NUMERO_PLAZO_REC`)
                     FROM `tmp_recibos_efectos_compra`);
    WHILE v_plazo IS NOT NULL DO
        SET v_importe = (SELECT `EUROS_RECIBO_REC`
                           FROM `tmp_recibos_efectos_compra`
                          WHERE `NUMERO_PLAZO_REC` = v_plazo);
        SET v_letra = NULL;
        CALL PRC_GET_NUMEROS_A_LETRAS(IFNULL(v_importe, 0), v_letra);
        UPDATE `tmp_recibos_efectos_compra`
           SET `IMPORTE_LETRA_RECIBO_REC` = v_letra
         WHERE `NUMERO_PLAZO_REC` = v_plazo;
        SET v_plazo = (SELECT MIN(`NUMERO_PLAZO_REC`)
                         FROM `tmp_recibos_efectos_compra`
                        WHERE `NUMERO_PLAZO_REC` > v_plazo);
    END WHILE;
END
;;
DELIMITER ;
