CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_PREPARAR_RECIBOS_EFECTOS_VENTA`(
    IN `p_SERIE`   VARCHAR(20),
    IN `p_NUMERO`  VARCHAR(20),
    IN `p_EFECTOS` TEXT
)
BEGIN
    DECLARE v_plazo   INT;
    DECLARE v_importe DECIMAL(18,6);
    DECLARE v_letra   VARCHAR(150);

    SET p_EFECTOS = REPLACE(IFNULL(p_EFECTOS, ''), ' ', '');

    DROP TEMPORARY TABLE IF EXISTS `tmp_recibos_efectos_venta`;
    CREATE TEMPORARY TABLE `tmp_recibos_efectos_venta` (
        `SERIE_FAC_REC`                   VARCHAR(20)   NOT NULL,
        `NUMERO_FAC_REC`                  VARCHAR(20)   NOT NULL,
        `NUMERO_PLAZO_REC`                INT           NOT NULL,
        `ESTADO_RECIBO_REC`               VARCHAR(20)   NULL,
        `EUROS_RECIBO_REC`                DECIMAL(18,6) NULL,
        `FECHA_EXPEDICION_RECIBO_REC`     DATE          NULL,
        `FECHA_VENCIMIENTO_RECIBO_REC`    DATE          NULL,
        `IBAN_CLI_REC`                    VARCHAR(34)   NULL,
        `LOCALIDAD_EXPEDICION_RECIBO_REC` VARCHAR(200)  NULL,
        `CODIGO_CLI_REC`                  VARCHAR(20)   NULL,
        `RAZON_SOCIAL_CLI_REC`            VARCHAR(200)  NULL,
        `DIRECCION1_CLIENTE_RECIBO_REC`   VARCHAR(200)  NULL,
        `POBLACION_CLI_REC`               VARCHAR(200)  NULL,
        `PROVINCIA_CLI_REC`               VARCHAR(200)  NULL,
        `CODIGO_POSTAL_CLI_REC`           VARCHAR(15)   NULL,
        `IMPORTE_LETRA_RECIBO_REC`        VARCHAR(150)  NULL,
        PRIMARY KEY (`NUMERO_PLAZO_REC`)
    );

    INSERT INTO `tmp_recibos_efectos_venta`
        (`SERIE_FAC_REC`, `NUMERO_FAC_REC`, `NUMERO_PLAZO_REC`,
         `ESTADO_RECIBO_REC`, `EUROS_RECIBO_REC`,
         `FECHA_EXPEDICION_RECIBO_REC`, `FECHA_VENCIMIENTO_RECIBO_REC`,
         `IBAN_CLI_REC`, `LOCALIDAD_EXPEDICION_RECIBO_REC`,
         `CODIGO_CLI_REC`, `RAZON_SOCIAL_CLI_REC`,
         `DIRECCION1_CLIENTE_RECIBO_REC`, `POBLACION_CLI_REC`,
         `PROVINCIA_CLI_REC`, `CODIGO_POSTAL_CLI_REC`)
    SELECT e.`SERIE_FAC_EFV`, e.`NUMERO_FAC_EFV`, e.`NUMERO_EFV`,
           e.`ESTADO_EFV`, ROUND(e.`IMPORTE_EFV`, 2),
           COALESCE(e.`FECHA_EMISION_EFV`, DATE(f.`FECHA_FAC`)),
           e.`FECHA_VENCIMIENTO_EFV`,
           COALESCE(NULLIF(TRIM(e.`IBAN_EFV`), ''), cli.`IBAN_CLI`),
           f.`POBLACION_EMPRESA_FAC`,
           COALESCE(NULLIF(e.`CODIGO_CLI_EFV`, ''), f.`CODIGO_CLI_FAC`),
           COALESCE(NULLIF(f.`RAZON_SOCIAL_CLIENTE_FAC`, ''),
                    e.`RAZON_SOCIAL_CLI_EFV`),
           f.`DIRECCION1_CLIENTE_FAC`, f.`POBLACION_CLIENTE_FAC`,
           f.`PROVINCIA_CLIENTE_FAC`, f.`CODIGO_POSTAL_CLIENTE_FAC`
      FROM `fza_efectos_venta` e
      LEFT JOIN `fza_facturas` f
        ON f.`SERIE_FAC` = e.`SERIE_FAC_EFV`
       AND f.`NUMERO_FAC` = e.`NUMERO_FAC_EFV`
      LEFT JOIN `fza_clientes` cli
        ON cli.`CODIGO_CLI_CLI` =
           COALESCE(NULLIF(e.`CODIGO_CLI_EFV`, ''), f.`CODIGO_CLI_FAC`)
     WHERE e.`SERIE_FAC_EFV` = p_SERIE
       AND e.`NUMERO_FAC_EFV` = p_NUMERO
       AND (p_EFECTOS = '' OR FIND_IN_SET(e.`NUMERO_EFV`, p_EFECTOS));

    
    SET v_plazo = (SELECT MIN(`NUMERO_PLAZO_REC`)
                     FROM `tmp_recibos_efectos_venta`);
    WHILE v_plazo IS NOT NULL DO
        SET v_importe = (SELECT `EUROS_RECIBO_REC`
                           FROM `tmp_recibos_efectos_venta`
                          WHERE `NUMERO_PLAZO_REC` = v_plazo);
        SET v_letra = NULL;
        CALL PRC_GET_NUMEROS_A_LETRAS(IFNULL(v_importe, 0), v_letra);
        UPDATE `tmp_recibos_efectos_venta`
           SET `IMPORTE_LETRA_RECIBO_REC` = v_letra
         WHERE `NUMERO_PLAZO_REC` = v_plazo;
        SET v_plazo = (SELECT MIN(`NUMERO_PLAZO_REC`)
                         FROM `tmp_recibos_efectos_venta`
                        WHERE `NUMERO_PLAZO_REC` > v_plazo);
    END WHILE;
END
;;
DELIMITER ;
