CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_PRE_CONVERTIR`(
  IN p_SERIE varchar(20), IN p_NUMERO varchar(20),
  IN p_TIPO varchar(2), IN p_SERIE_DESTINO varchar(12),
  IN p_USUARIO varchar(100), OUT p_NUMERO_DESTINO varchar(20)
)
BEGIN
  DECLARE v_EMPRESA varchar(10);
  DECLARE v_ESTADO varchar(20);
  DECLARE v_TIPO varchar(2);
  DECLARE v_SERIE varchar(20);
  DECLARE v_NUMERO varchar(20);
  SELECT CODIGO_EMP_PRE, ESTADO_PRE, TIPO_DESTINO_PRE,
    SERIE_DESTINO_PRE, NUMERO_DESTINO_PRE
    INTO v_EMPRESA, v_ESTADO, v_TIPO, v_SERIE, v_NUMERO
    FROM fza_presupuestos
   WHERE SERIE_PRE = p_SERIE AND NUMERO_PRE = p_NUMERO FOR UPDATE;
  IF v_EMPRESA IS NULL OR p_TIPO NOT IN ('PE', 'AV', 'FC') THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Presupuesto o destino no válido';
  END IF;
  IF COALESCE(v_NUMERO, '') <> '' THEN
    IF v_TIPO <> p_TIPO OR v_SERIE <> p_SERIE_DESTINO THEN
      SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'El presupuesto ya tiene otro documento de destino';
    END IF;
    IF (p_TIPO = 'PE' AND NOT EXISTS (SELECT 1 FROM fza_pedidos
        WHERE SERIE_PED = v_SERIE AND NUMERO_PED = v_NUMERO)) OR
       (p_TIPO = 'AV' AND NOT EXISTS (SELECT 1 FROM fza_albaranes
        WHERE SERIE_ALB = v_SERIE AND NUMERO_ALB = v_NUMERO)) OR
       (p_TIPO = 'FC' AND NOT EXISTS (SELECT 1 FROM fza_facturas
        WHERE SERIE_FAC = v_SERIE AND NUMERO_FAC = v_NUMERO)) THEN
      SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'El documento de destino ya no existe';
    END IF;
    SET p_NUMERO_DESTINO = v_NUMERO;
  ELSE
    IF v_ESTADO <> 'ABIERTO' THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'El presupuesto no está abierto';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM fza_presupuestos_lineas
      WHERE SERIE_PRE_PRELIN = p_SERIE AND NUMERO_PRE_PRELIN = p_NUMERO) THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'El presupuesto no tiene líneas';
    END IF;
    IF EXISTS (SELECT 1 FROM fza_presupuestos_celdas
      WHERE SERIE_PRE_PRECEL = p_SERIE AND NUMERO_PRE_PRECEL = p_NUMERO
        AND CANTIDAD_PRECEL <> 0) THEN
      SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Cambie a modo SKU antes de convertir el presupuesto';
    END IF;
    CALL PRC_PRE_RESERVAR_NUMERO(p_TIPO, v_EMPRESA, p_SERIE_DESTINO,
      p_USUARIO, p_NUMERO_DESTINO);
    CASE p_TIPO
      WHEN 'PE' THEN
        CALL PRC_PRE_COPIAR_PED_CABECERA(p_SERIE, p_NUMERO,
          p_SERIE_DESTINO, p_NUMERO_DESTINO, p_USUARIO);
        CALL PRC_PRE_COPIAR_PED_LINEAS(p_SERIE, p_NUMERO,
          p_SERIE_DESTINO, p_NUMERO_DESTINO, p_USUARIO);
      WHEN 'AV' THEN
        CALL PRC_PRE_COPIAR_ALB_CABECERA(p_SERIE, p_NUMERO,
          p_SERIE_DESTINO, p_NUMERO_DESTINO, p_USUARIO);
        CALL PRC_PRE_COPIAR_ALB_LINEAS(p_SERIE, p_NUMERO,
          p_SERIE_DESTINO, p_NUMERO_DESTINO, p_USUARIO);
      WHEN 'FC' THEN
        CALL PRC_PRE_COPIAR_FAC_CABECERA(p_SERIE, p_NUMERO,
          p_SERIE_DESTINO, p_NUMERO_DESTINO, p_USUARIO);
        CALL PRC_PRE_COPIAR_FAC_LINEAS(p_SERIE, p_NUMERO,
          p_SERIE_DESTINO, p_NUMERO_DESTINO, p_USUARIO);
    END CASE;
    UPDATE fza_presupuestos SET ESTADO_PRE = 'CONVERTIDO',
      TIPO_DESTINO_PRE = p_TIPO, SERIE_DESTINO_PRE = p_SERIE_DESTINO,
      NUMERO_DESTINO_PRE = p_NUMERO_DESTINO,
      USUARIO_MODIF = p_USUARIO, INSTANTE_MODIF = NOW()
    WHERE SERIE_PRE = p_SERIE AND NUMERO_PRE = p_NUMERO;
  END IF;
END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_VALUE_ON_ZERO' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `PRC_PRE_CONVERTIR_DOCUMENTO` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_spanish_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_PRE_CONVERTIR_DOCUMENTO`(
  IN p_SERIE varchar(20), IN p_NUMERO varchar(20),
  IN p_TIPO varchar(2), IN p_SERIE_DESTINO varchar(12),
  IN p_NUMERO_MANUAL varchar(20), IN p_FECHA date,
  IN p_ALMACEN varchar(10), IN p_ESMUEVE_STOCK varchar(1),
  IN p_FORMA_PAGO varchar(20),
  IN p_USUARIO varchar(100), OUT p_NUMERO_DESTINO varchar(20)
)
BEGIN
  DECLARE v_CONVERTIDO varchar(20);
  DECLARE v_FORMA_PAGO varchar(20);
  SET v_FORMA_PAGO = NULLIF(TRIM(COALESCE(p_FORMA_PAGO, '')), '');
  SELECT NUMERO_DESTINO_PRE INTO v_CONVERTIDO
    FROM fza_presupuestos
   WHERE SERIE_PRE = p_SERIE AND NUMERO_PRE = p_NUMERO;
  IF v_FORMA_PAGO IS NOT NULL AND
     COALESCE(v_CONVERTIDO, '') = '' AND
     NOT EXISTS (SELECT 1 FROM fza_formas_pago
                  WHERE CODIGO_FP_FP = v_FORMA_PAGO) THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'La forma de pago no existe';
  END IF;
  CALL PRC_PRE_CONVERTIR_OPCIONES(p_SERIE, p_NUMERO, p_TIPO,
    p_SERIE_DESTINO, p_NUMERO_MANUAL, p_FECHA, p_ALMACEN,
    p_ESMUEVE_STOCK, p_USUARIO, p_NUMERO_DESTINO);
  IF v_FORMA_PAGO IS NOT NULL AND COALESCE(v_CONVERTIDO, '') = '' THEN
    CASE p_TIPO
      WHEN 'PE' THEN
        UPDATE fza_pedidos SET FORMA_PAGO_PED = v_FORMA_PAGO
         WHERE SERIE_PED = p_SERIE_DESTINO
           AND NUMERO_PED = p_NUMERO_DESTINO;
      WHEN 'AV' THEN
        UPDATE fza_albaranes SET FORMA_PAGO_ALB = v_FORMA_PAGO
         WHERE SERIE_ALB = p_SERIE_DESTINO
           AND NUMERO_ALB = p_NUMERO_DESTINO;
      ELSE
        UPDATE fza_facturas SET FORMA_PAGO_FAC = v_FORMA_PAGO
         WHERE SERIE_FAC = p_SERIE_DESTINO
           AND NUMERO_FAC = p_NUMERO_DESTINO;
    END CASE;
  END IF;
END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_VALUE_ON_ZERO' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `PRC_PRE_CONVERTIR_OPCIONES` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_spanish_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_PRE_CONVERTIR_OPCIONES`(
  IN p_SERIE varchar(20), IN p_NUMERO varchar(20),
  IN p_TIPO varchar(2), IN p_SERIE_DESTINO varchar(12),
  IN p_NUMERO_MANUAL varchar(20), IN p_FECHA date,
  IN p_ALMACEN varchar(10), IN p_ESMUEVE_STOCK varchar(1),
  IN p_USUARIO varchar(100), OUT p_NUMERO_DESTINO varchar(20)
)
BEGIN
  DECLARE v_EMPRESA varchar(10);
  DECLARE v_ESTADO varchar(20);
  DECLARE v_TIPO varchar(2);
  DECLARE v_SERIE varchar(20);
  DECLARE v_NUMERO varchar(20);
  DECLARE v_DIGITOS int;
  DECLARE v_ALMACEN varchar(10);
  DECLARE v_MUEVE varchar(1);
  DECLARE v_INSTANTE datetime;
  SELECT CODIGO_EMP_PRE, ESTADO_PRE, TIPO_DESTINO_PRE,
    SERIE_DESTINO_PRE, NUMERO_DESTINO_PRE
    INTO v_EMPRESA, v_ESTADO, v_TIPO, v_SERIE, v_NUMERO
    FROM fza_presupuestos
   WHERE SERIE_PRE = p_SERIE AND NUMERO_PRE = p_NUMERO FOR UPDATE;
  IF v_EMPRESA IS NULL OR p_TIPO NOT IN ('PE', 'AV', 'FC') THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Presupuesto o destino no válido';
  END IF;
  IF COALESCE(v_NUMERO, '') <> '' THEN
    CALL PRC_PRE_CONVERTIR(p_SERIE, p_NUMERO, p_TIPO, v_SERIE,
      p_USUARIO, p_NUMERO_DESTINO);
  ELSE
    IF v_ESTADO <> 'ABIERTO' THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'El presupuesto no está abierto';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM fza_presupuestos_lineas
      WHERE SERIE_PRE_PRELIN = p_SERIE AND NUMERO_PRE_PRELIN = p_NUMERO) THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'El presupuesto no tiene líneas';
    END IF;
    IF EXISTS (SELECT 1 FROM fza_presupuestos_celdas
      WHERE SERIE_PRE_PRECEL = p_SERIE AND NUMERO_PRE_PRECEL = p_NUMERO
        AND CANTIDAD_PRECEL <> 0) THEN
      SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Cambie a modo SKU antes de convertir el presupuesto';
    END IF;
    IF COALESCE(p_SERIE_DESTINO, '') = '' THEN
      SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Indique la serie del documento de destino';
    END IF;
    IF p_FECHA IS NULL THEN
      SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Indique la fecha del documento de destino';
    END IF;
    SET v_ALMACEN = NULLIF(TRIM(COALESCE(p_ALMACEN, '')), '');
    SET v_MUEVE = IF(p_TIPO = 'FC' AND p_ESMUEVE_STOCK = 'N', 'N', 'S');
    IF v_ALMACEN IS NULL AND v_MUEVE = 'S' THEN
      SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Indique el almacén del documento de destino';
    END IF;
    IF v_ALMACEN IS NOT NULL AND NOT EXISTS (SELECT 1 FROM fza_almacenes
      WHERE CODIGO_ALM_ALM = v_ALMACEN AND CODIGO_EMP_ALM = v_EMPRESA
        AND ESACTIVO_ALM = 'S') THEN
      SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'El almacén no es un almacén activo de la empresa';
    END IF;

    IF COALESCE(TRIM(p_NUMERO_MANUAL), '') = '' THEN
      CALL PRC_PRE_RESERVAR_NUMERO(p_TIPO, v_EMPRESA, p_SERIE_DESTINO,
        p_USUARIO, p_NUMERO_DESTINO);
    ELSE
      SET p_NUMERO_DESTINO = TRIM(p_NUMERO_MANUAL);
      SELECT MAX(NUM_DIGITOS_CON) INTO v_DIGITOS FROM fza_contadores
       WHERE TIPO_DOC_CON = p_TIPO AND EMPRESA_CON = v_EMPRESA
         AND SERIE_CON = p_SERIE_DESTINO;
      IF p_NUMERO_DESTINO REGEXP '^[0-9]+$' AND
         COALESCE(v_DIGITOS, 0) > LENGTH(p_NUMERO_DESTINO) THEN
        SET p_NUMERO_DESTINO = LPAD(p_NUMERO_DESTINO, v_DIGITOS, '0');
      END IF;
      IF (p_TIPO = 'PE' AND EXISTS (SELECT 1 FROM fza_pedidos
          WHERE SERIE_PED = p_SERIE_DESTINO
            AND NUMERO_PED = p_NUMERO_DESTINO)) OR
         (p_TIPO = 'AV' AND EXISTS (SELECT 1 FROM fza_albaranes
          WHERE SERIE_ALB = p_SERIE_DESTINO
            AND NUMERO_ALB = p_NUMERO_DESTINO)) OR
         (p_TIPO = 'FC' AND EXISTS (SELECT 1 FROM fza_facturas
          WHERE SERIE_FAC = p_SERIE_DESTINO
            AND NUMERO_FAC = p_NUMERO_DESTINO)) THEN
        SIGNAL SQLSTATE '45000'
          SET MESSAGE_TEXT = 'El número indicado ya existe en la serie de destino';
      END IF;
    END IF;

    CASE p_TIPO
      WHEN 'PE' THEN
        CALL PRC_PRE_COPIAR_PED_CABECERA(p_SERIE, p_NUMERO,
          p_SERIE_DESTINO, p_NUMERO_DESTINO, p_USUARIO);
        CALL PRC_PRE_COPIAR_PED_LINEAS(p_SERIE, p_NUMERO,
          p_SERIE_DESTINO, p_NUMERO_DESTINO, p_USUARIO);
        UPDATE fza_pedidos SET FECHA_PED = p_FECHA,
          CODIGO_ALM_PED = v_ALMACEN
         WHERE SERIE_PED = p_SERIE_DESTINO
           AND NUMERO_PED = p_NUMERO_DESTINO;
        UPDATE fza_pedidos_lineas SET CODIGO_ALMACEN_PEDLIN = v_ALMACEN
         WHERE SERIE_PED_PEDLIN = p_SERIE_DESTINO
           AND NUMERO_PED_PEDLIN = p_NUMERO_DESTINO;
      WHEN 'AV' THEN
        CALL PRC_PRE_COPIAR_ALB_CABECERA(p_SERIE, p_NUMERO,
          p_SERIE_DESTINO, p_NUMERO_DESTINO, p_USUARIO);
        CALL PRC_PRE_COPIAR_ALB_LINEAS(p_SERIE, p_NUMERO,
          p_SERIE_DESTINO, p_NUMERO_DESTINO, p_USUARIO);
        SET v_INSTANTE = IF(p_FECHA = CURRENT_DATE(), NOW(),
          CAST(p_FECHA AS datetime));
        UPDATE fza_albaranes SET FECHA_ALB = p_FECHA,
          INSTANTE_MOVIMIENTO_ALB = v_INSTANTE,
          CODIGO_ALM_ALB = v_ALMACEN
         WHERE SERIE_ALB = p_SERIE_DESTINO
           AND NUMERO_ALB = p_NUMERO_DESTINO;
        UPDATE fza_albaranes_lineas SET CODIGO_ALMACEN_ALBLIN = v_ALMACEN
         WHERE SERIE_ALB_ALBLIN = p_SERIE_DESTINO
           AND NUMERO_ALB_ALBLIN = p_NUMERO_DESTINO;
      WHEN 'FC' THEN
        CALL PRC_PRE_COPIAR_FAC_CABECERA(p_SERIE, p_NUMERO,
          p_SERIE_DESTINO, p_NUMERO_DESTINO, p_USUARIO);
        CALL PRC_PRE_COPIAR_FAC_LINEAS(p_SERIE, p_NUMERO,
          p_SERIE_DESTINO, p_NUMERO_DESTINO, p_USUARIO);
        UPDATE fza_facturas SET FECHA_FAC = p_FECHA,
          CODIGO_ALM_FAC = v_ALMACEN,
          ESMUEVE_STOCK_FAC = v_MUEVE
         WHERE SERIE_FAC = p_SERIE_DESTINO
           AND NUMERO_FAC = p_NUMERO_DESTINO;
        UPDATE fza_facturas_lineas SET CODIGO_ALM_FACLIN = v_ALMACEN
         WHERE SERIE_FAC_FACLIN = p_SERIE_DESTINO
           AND NUMERO_FAC_FACLIN = p_NUMERO_DESTINO;
    END CASE;
    UPDATE fza_presupuestos SET ESTADO_PRE = 'CONVERTIDO',
      TIPO_DESTINO_PRE = p_TIPO, SERIE_DESTINO_PRE = p_SERIE_DESTINO,
      NUMERO_DESTINO_PRE = p_NUMERO_DESTINO,
      USUARIO_MODIF = p_USUARIO, INSTANTE_MODIF = NOW()
    WHERE SERIE_PRE = p_SERIE AND NUMERO_PRE = p_NUMERO;
  END IF;
END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_VALUE_ON_ZERO' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `PRC_PRE_COPIAR_ALB_CABECERA` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_spanish_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_PRE_COPIAR_ALB_CABECERA`(
  IN p_SERIE varchar(20), IN p_NUMERO varchar(20),
  IN p_SERIE_DESTINO varchar(12), IN p_NUMERO_DESTINO varchar(20),
  IN p_USUARIO varchar(100)
)
BEGIN
  CALL PRC_PRE_PREPARAR_RECARGO(p_SERIE, p_NUMERO);
  CALL PRC_PRE_TOTALES_RECARGO(p_SERIE, p_NUMERO);
  INSERT INTO fza_albaranes (
    NUMERO_ALB, SERIE_ALB,
    FECHA_ALB, INSTANTE_MOVIMIENTO_ALB,
    ESCONSOLIDADO_ALB, ESTADO_ALB,
    CODIGO_EMP_ALB, CODIGO_ALM_ALB,
    RAZON_SOCIAL_EMPRESA_ALB, NIF_EMPRESA_ALB,
    MOVIL_EMPRESA_ALB, EMAIL_EMPRESA_ALB,
    DIRECCION1_EMPRESA_ALB, DIRECCION2_EMPRESA_ALB,
    POBLACION_EMPRESA_ALB, PROVINCIA_EMPRESA_ALB,
    CODIGO_PAI_EMPRESA_ALB, NOMBRE_PAI_EMPRESA_ALB,
    CODIGO_POSTAL_EMPRESA_ALB, GRUPO_ZONA_IVA_EMPRESA_ALB,
    ESRETENCIONES_EMPRESA_ALB, ESRETENCIONES_CLIENTE_ALB,
    ESREGIMENESPECIALAGRICOLA_EMPRESA_ALB,
    ESREGIMENESPECIALAGRICOLA_CLIENTE_ALB,
    CODIGO_CLI_ALB, RAZON_SOCIAL_CLIENTE_ALB,
    NIF_CLIENTE_ALB, MOVIL_CLIENTE_ALB,
    EMAIL_CLIENTE_ALB, DIRECCION1_CLIENTE_ALB,
    DIRECCION2_CLIENTE_ALB, POBLACION_CLIENTE_ALB,
    PROVINCIA_CLIENTE_ALB, CODIGO_POSTAL_CLIENTE_ALB,
    CODIGO_PAI_CLIENTE_ALB, NOMBRE_PAI_CLIENTE_ALB,
    NOMBRE_CLI_ENVIO_ALB, MOVIL_CLIENTE_ENVIO_ALB,
    DIRECCION1_CLIENTE_ENVIO_ALB, DIRECCION2_CLIENTE_ENVIO_ALB,
    POBLACION_CLIENTE_ENVIO_ALB, PROVINCIA_CLIENTE_ENVIO_ALB,
    CODIGO_POSTAL_CLIENTE_ENVIO_ALB, CODIGO_PAI_CLIENTE_ENVIO_ALB,
    NOMBRE_PAI_CLIENTE_ENVIO_ALB, TRANSPORTISTA_ALB,
    CODIGO_IVA_ALB, ESIVA_RECARGO_CLIENTE_ALB,
    ESIVA_EXENTO_CLIENTE_ALB, ESINTRACOMUNITARIO_CLIENTE_ALB,
    TARIFA_ARTICULO_CLIENTE_ALB, ESIMP_INCL_TARIFA_CLIENTE_ALB,
    ESAPLICA_RE_ZONA_IVA_ALB,
    PORCENTAJE_REN_ALB,
    TOTAL_REN_ALB,
    PORCENTAJE_RER_ALB,
    TOTAL_RER_ALB,
    PORCENTAJE_RES_ALB,
    TOTAL_RES_ALB,
    PORCENTAJE_REE_ALB,
    TOTAL_REE_ALB,
    TOTAL_BASEI_IVAN_ALB,
    TOTAL_BASEI_IVAR_ALB,
    TOTAL_BASEI_IVAS_ALB,
    TOTAL_BASEI_IVAE_ALB,
    PORCENTAJE_IVAN_ALB, TOTAL_IVAN_ALB,
    PORCENTAJE_IVAR_ALB, TOTAL_IVAR_ALB,
    PORCENTAJE_IVAS_ALB, TOTAL_IVAS_ALB,
    PORCENTAJE_IVAE_ALB, TOTAL_IVAE_ALB,
    TOTAL_BASES_ALB, TOTAL_IMPUESTOS_ALB,
    PORCENTAJE_RETENCION_ALB, TOTAL_RETENCION_ALB,
    TOTAL_LIQUIDO_ALB, FORMA_PAGO_ALB,
    CONTADOR_LINEAS_ALB, COMENTARIOS_ALB,
    OBSERVACIONES_ALB, INSTANTE_MODIF,
    INSTANTE_ALTA, USUARIO_ALTA,
    USUARIO_MODIF)
  SELECT
    p_NUMERO_DESTINO, p_SERIE_DESTINO,
    CURRENT_DATE(), NOW(),
    P.ESCONSOLIDADO_PRE, 'ABIERTO',
    P.CODIGO_EMP_PRE, P.CODIGO_ALM_PRE,
    P.RAZON_SOCIAL_EMPRESA_PRE, P.NIF_EMPRESA_PRE,
    P.MOVIL_EMPRESA_PRE, P.EMAIL_EMPRESA_PRE,
    P.DIRECCION1_EMPRESA_PRE, P.DIRECCION2_EMPRESA_PRE,
    P.POBLACION_EMPRESA_PRE, P.PROVINCIA_EMPRESA_PRE,
    P.CODIGO_PAI_EMPRESA_PRE, P.NOMBRE_PAI_EMPRESA_PRE,
    P.CODIGO_POSTAL_EMPRESA_PRE, P.GRUPO_ZONA_IVA_EMPRESA_PRE,
    COALESCE(P.ESRETENCIONES_EMPRESA_PRE, 'N'),
    COALESCE(P.ESRETENCIONES_CLIENTE_PRE, 'N'),
    COALESCE(P.ESREGIMENESPECIALAGRICOLA_EMPRESA_PRE, 'N'),
    COALESCE(P.ESREGIMENESPECIALAGRICOLA_CLIENTE_PRE, 'N'),
    P.CODIGO_CLI_PRE, P.RAZON_SOCIAL_CLIENTE_PRE,
    P.NIF_CLIENTE_PRE, P.MOVIL_CLIENTE_PRE,
    P.EMAIL_CLIENTE_PRE, P.DIRECCION1_CLIENTE_PRE,
    P.DIRECCION2_CLIENTE_PRE, P.POBLACION_CLIENTE_PRE,
    P.PROVINCIA_CLIENTE_PRE, P.CODIGO_POSTAL_CLIENTE_PRE,
    P.CODIGO_PAI_CLIENTE_PRE, P.NOMBRE_PAI_CLIENTE_PRE,
    P.NOMBRE_CLI_ENVIO_PRE, P.MOVIL_CLIENTE_ENVIO_PRE,
    P.DIRECCION1_CLIENTE_ENVIO_PRE, P.DIRECCION2_CLIENTE_ENVIO_PRE,
    P.POBLACION_CLIENTE_ENVIO_PRE, P.PROVINCIA_CLIENTE_ENVIO_PRE,
    P.CODIGO_POSTAL_CLIENTE_ENVIO_PRE, P.CODIGO_PAI_CLIENTE_ENVIO_PRE,
    P.NOMBRE_PAI_CLIENTE_ENVIO_PRE, P.TRANSPORTISTA_PRE,
    P.CODIGO_IVA_PRE, P.ESIVA_RECARGO_CLIENTE_PRE,
    P.ESIVA_EXENTO_CLIENTE_PRE, P.ESINTRACOMUNITARIO_CLIENTE_PRE,
    P.TARIFA_ARTICULO_CLIENTE_PRE, P.ESIMP_INCL_TARIFA_CLIENTE_PRE,
    P.ESAPLICA_RE_ZONA_IVA_PRE,
    P.PORCENTAJE_REN_PRE,
    P.TOTAL_REN_PRE,
    P.PORCENTAJE_RER_PRE,
    P.TOTAL_RER_PRE,
    P.PORCENTAJE_RES_PRE,
    P.TOTAL_RES_PRE,
    P.PORCENTAJE_REE_PRE,
    P.TOTAL_REE_PRE,
    P.TOTAL_BASEI_IVAN_PRE,
    P.TOTAL_BASEI_IVAR_PRE,
    P.TOTAL_BASEI_IVAS_PRE,
    P.TOTAL_BASEI_IVAE_PRE,
    P.PORCENTAJE_IVAN_PRE, P.TOTAL_IVAN_PRE,
    P.PORCENTAJE_IVAR_PRE, P.TOTAL_IVAR_PRE,
    P.PORCENTAJE_IVAS_PRE, P.TOTAL_IVAS_PRE,
    P.PORCENTAJE_IVAE_PRE, P.TOTAL_IVAE_PRE,
    P.TOTAL_BASES_PRE, P.TOTAL_IMPUESTOS_PRE,
    P.PORCENTAJE_RETENCION_PRE, P.TOTAL_RETENCION_PRE,
    P.TOTAL_LIQUIDO_PRE, P.FORMA_PAGO_PRE,
    P.CONTADOR_LINEAS_PRE, P.COMENTARIOS_PRE,
    P.OBSERVACIONES_PRE, NOW(),
    NOW(), p_USUARIO,
    p_USUARIO
  FROM fza_presupuestos P
  WHERE P.SERIE_PRE = p_SERIE AND P.NUMERO_PRE = p_NUMERO;
END
;;
DELIMITER ;
