CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_PRE_COPIAR_ALB_LINEAS`(
  IN p_SERIE varchar(20), IN p_NUMERO varchar(20),
  IN p_SERIE_DESTINO varchar(12), IN p_NUMERO_DESTINO varchar(20),
  IN p_USUARIO varchar(100)
)
BEGIN
  INSERT INTO fza_albaranes_lineas (
    NUMERO_ALB_ALBLIN, SERIE_ALB_ALBLIN,
    LINEA_ALBLIN, CODIGO_ART_ALBLIN,
    CODIGO_FAM_ALBLIN, NOMBRE_FAM_ALBLIN,
    DESCRIPCION_ARTICULO_ALBLIN, TIPO_CANTIDAD_ARTICULO_ALBLIN,
    CANTIDAD_ALBLIN, CODIGO_TAR_ALBLIN,
    ESIMP_INCL_TARIFA_ALBLIN, TIPO_IVA_ARTICULO_ALBLIN,
    PORCENTAJE_IVA_ALBLIN, PRECIO_VENTA_SIVA_ARTICULO_ALBLIN,
    PRECIO_VENTA_CIVA_ARTICULO_ALBLIN, TOTAL_ALBLIN,
    CODIGO_ALMACEN_ALBLIN, INSTANTE_MODIF,
    INSTANTE_ALTA, USUARIO_ALTA,
    USUARIO_MODIF, CODIGO_UNIDAD_ALBLIN,
    LOTE_ALBLIN, FECHA_CADUCIDAD_ALBLIN,
    DESCRIPCION_VARIACION_ALBLIN, ATTR1_VALOR_ALBLIN,
    ATTR1_NOMBRE_ALBLIN, ATTR2_VALOR_ALBLIN,
    ATTR2_NOMBRE_ALBLIN, ATTR3_VALOR_ALBLIN,
    ATTR3_NOMBRE_ALBLIN, ATTR4_VALOR_ALBLIN,
    ATTR4_NOMBRE_ALBLIN, ATTR5_VALOR_ALBLIN,
    ATTR5_NOMBRE_ALBLIN, NUM_ATRIBUTOS_ALBLIN,
    ID_AC_PIVOT_ALBLIN,
    PRECIO_SALIDA_ALBLIN,
    PORCENTAJE_DTO_ALBLIN, PRECIO_DTO_ALBLIN)
  SELECT
    p_NUMERO_DESTINO, p_SERIE_DESTINO,
    P.LINEA_PRELIN, P.CODIGO_ART_PRELIN,
    P.CODIGO_FAM_PRELIN, P.NOMBRE_FAM_PRELIN,
    P.DESCRIPCION_ARTICULO_PRELIN, P.TIPO_CANTIDAD_ARTICULO_PRELIN,
    P.CANTIDAD_PRELIN, P.CODIGO_TAR_PRELIN,
    P.ESIMP_INCL_TARIFA_PRELIN, P.TIPO_IVA_ARTICULO_PRELIN,
    P.PORCENTAJE_IVA_PRELIN, P.PRECIO_VENTA_SIVA_ARTICULO_PRELIN,
    P.PRECIO_VENTA_CIVA_ARTICULO_PRELIN, P.TOTAL_PRELIN,
    P.CODIGO_ALMACEN_PRELIN, NOW(),
    NOW(), p_USUARIO,
    p_USUARIO, P.CODIGO_UNIDAD_PRELIN,
    P.LOTE_PRELIN, P.FECHA_CADUCIDAD_PRELIN,
    P.DESCRIPCION_VARIACION_PRELIN, P.ATTR1_VALOR_PRELIN,
    P.ATTR1_NOMBRE_PRELIN, P.ATTR2_VALOR_PRELIN,
    P.ATTR2_NOMBRE_PRELIN, P.ATTR3_VALOR_PRELIN,
    P.ATTR3_NOMBRE_PRELIN, P.ATTR4_VALOR_PRELIN,
    P.ATTR4_NOMBRE_PRELIN, P.ATTR5_VALOR_PRELIN,
    P.ATTR5_NOMBRE_PRELIN, P.NUM_ATRIBUTOS_PRELIN,
    P.ID_AC_PIVOT_PRELIN,
    COALESCE(P.PRECIO_SALIDA_PRELIN,
      CASE WHEN P.ESIMP_INCL_TARIFA_PRELIN = 'S'
        THEN P.PRECIO_VENTA_CIVA_ARTICULO_PRELIN
        ELSE P.PRECIO_VENTA_SIVA_ARTICULO_PRELIN END),
    COALESCE(P.PORCENTAJE_DTO_PRELIN, 0),
    COALESCE(P.PRECIO_DTO_PRELIN, 0)
  FROM fza_presupuestos_lineas P
  WHERE P.SERIE_PRE_PRELIN = p_SERIE AND P.NUMERO_PRE_PRELIN = p_NUMERO;
END
;;
DELIMITER ;
