CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_PRE_COPIAR_FAC_CABECERA`(
  IN p_SERIE varchar(20), IN p_NUMERO varchar(20),
  IN p_SERIE_DESTINO varchar(12), IN p_NUMERO_DESTINO varchar(20),
  IN p_USUARIO varchar(100)
)
BEGIN
  CALL PRC_PRE_PREPARAR_RECARGO(p_SERIE, p_NUMERO);
  CALL PRC_PRE_TOTALES_RECARGO(p_SERIE, p_NUMERO);
  INSERT INTO fza_facturas (
    NUMERO_FAC, SERIE_FAC,
    FECHA_FAC, TIPO_FAC,
    ESMUEVE_STOCK_FAC, FASE_FAC,
    CODIGO_EMP_FAC, RAZON_SOCIAL_EMPRESA_FAC,
    NIF_EMPRESA_FAC, MOVIL_EMPRESA_FAC,
    EMAIL_EMPRESA_FAC, DIRECCION1_EMPRESA_FAC,
    DIRECCION2_EMPRESA_FAC, POBLACION_EMPRESA_FAC,
    PROVINCIA_EMPRESA_FAC, CODIGO_PAI_EMPRESA_FAC,
    NOMBRE_PAI_EMPRESA_FAC, CODIGO_POSTAL_EMPRESA_FAC,
    GRUPO_ZONA_IVA_EMPRESA_FAC, CODIGO_CLI_FAC,
    RAZON_SOCIAL_CLIENTE_FAC, NIF_CLIENTE_FAC,
    MOVIL_CLIENTE_FAC, EMAIL_CLIENTE_FAC,
    DIRECCION1_CLIENTE_FAC, DIRECCION2_CLIENTE_FAC,
    POBLACION_CLIENTE_FAC, PROVINCIA_CLIENTE_FAC,
    CODIGO_POSTAL_CLIENTE_FAC, CODIGO_PAI_CLIENTE_FAC,
    NOMBRE_PAI_CLIENTE_FAC, CODIGO_IVA_FAC,
    ESIVA_RECARGO_CLIENTE_FAC, ESIVA_EXENTO_CLIENTE_FAC,
    TARIFA_ARTICULO_CLIENTE_FAC, ESIMP_INCL_TARIFA_CLIENTE_FAC,
    ESINTRACOMUNITARIO_CLIENTE_FAC, ESAPLICA_RE_ZONA_IVA_FAC,
    PORCENTAJE_REN_FAC,
    TOTAL_REN_FAC,
    PORCENTAJE_RER_FAC,
    TOTAL_RER_FAC,
    PORCENTAJE_RES_FAC,
    TOTAL_RES_FAC,
    PORCENTAJE_REE_FAC,
    TOTAL_REE_FAC,
    PORCENTAJE_IVAN_FAC,
    TOTAL_IVAN_FAC, PORCENTAJE_IVAR_FAC,
    TOTAL_IVAR_FAC, PORCENTAJE_IVAS_FAC,
    TOTAL_IVAS_FAC, PORCENTAJE_IVAE_FAC,
    TOTAL_IVAE_FAC, TOTAL_BASES_FAC,
    TOTAL_IMPUESTOS_FAC, FORMA_PAGO_FAC,
    ESRETENCIONES_EMPRESA_FAC, ESRETENCIONES_CLIENTE_FAC,
    ESREGIMENESPECIALAGRICOLA_EMPRESA_FAC,
    ESREGIMENESPECIALAGRICOLA_CLIENTE_FAC,
    PORCENTAJE_RETENCION_FAC, TOTAL_RETENCION_FAC,
    TOTAL_LIQUIDO_FAC, COMENTARIOS_FAC,
    CONTADOR_LINEAS_FAC, INSTANTE_MODIF,
    INSTANTE_ALTA, USUARIO_ALTA,
    USUARIO_MODIF, CODIGO_ALM_FAC,
    TOTAL_BASEI_IVAN_FAC,
    TOTAL_BASEI_IVAR_FAC,
    TOTAL_BASEI_IVAS_FAC,
    TOTAL_BASEI_IVAE_FAC)
  SELECT
    p_NUMERO_DESTINO, p_SERIE_DESTINO,
    CURRENT_DATE(), 'NORMAL',
    'S', 'BORRADOR',
    P.CODIGO_EMP_PRE, P.RAZON_SOCIAL_EMPRESA_PRE,
    P.NIF_EMPRESA_PRE, P.MOVIL_EMPRESA_PRE,
    P.EMAIL_EMPRESA_PRE, P.DIRECCION1_EMPRESA_PRE,
    P.DIRECCION2_EMPRESA_PRE, P.POBLACION_EMPRESA_PRE,
    P.PROVINCIA_EMPRESA_PRE, P.CODIGO_PAI_EMPRESA_PRE,
    P.NOMBRE_PAI_EMPRESA_PRE, P.CODIGO_POSTAL_EMPRESA_PRE,
    P.GRUPO_ZONA_IVA_EMPRESA_PRE, P.CODIGO_CLI_PRE,
    P.RAZON_SOCIAL_CLIENTE_PRE, P.NIF_CLIENTE_PRE,
    P.MOVIL_CLIENTE_PRE, P.EMAIL_CLIENTE_PRE,
    P.DIRECCION1_CLIENTE_PRE, P.DIRECCION2_CLIENTE_PRE,
    P.POBLACION_CLIENTE_PRE, P.PROVINCIA_CLIENTE_PRE,
    P.CODIGO_POSTAL_CLIENTE_PRE, P.CODIGO_PAI_CLIENTE_PRE,
    P.NOMBRE_PAI_CLIENTE_PRE, P.CODIGO_IVA_PRE,
    P.ESIVA_RECARGO_CLIENTE_PRE, P.ESIVA_EXENTO_CLIENTE_PRE,
    P.TARIFA_ARTICULO_CLIENTE_PRE, P.ESIMP_INCL_TARIFA_CLIENTE_PRE,
    P.ESINTRACOMUNITARIO_CLIENTE_PRE, P.ESAPLICA_RE_ZONA_IVA_PRE,
    P.PORCENTAJE_REN_PRE,
    P.TOTAL_REN_PRE,
    P.PORCENTAJE_RER_PRE,
    P.TOTAL_RER_PRE,
    P.PORCENTAJE_RES_PRE,
    P.TOTAL_RES_PRE,
    P.PORCENTAJE_REE_PRE,
    P.TOTAL_REE_PRE,
    P.PORCENTAJE_IVAN_PRE,
    P.TOTAL_IVAN_PRE, P.PORCENTAJE_IVAR_PRE,
    P.TOTAL_IVAR_PRE, P.PORCENTAJE_IVAS_PRE,
    P.TOTAL_IVAS_PRE, P.PORCENTAJE_IVAE_PRE,
    P.TOTAL_IVAE_PRE, P.TOTAL_BASES_PRE,
    P.TOTAL_IMPUESTOS_PRE, P.FORMA_PAGO_PRE,
    COALESCE(P.ESRETENCIONES_EMPRESA_PRE, 'N'),
    COALESCE(P.ESRETENCIONES_CLIENTE_PRE, 'N'),
    COALESCE(P.ESREGIMENESPECIALAGRICOLA_EMPRESA_PRE, 'N'),
    COALESCE(P.ESREGIMENESPECIALAGRICOLA_CLIENTE_PRE, 'N'),
    P.PORCENTAJE_RETENCION_PRE, P.TOTAL_RETENCION_PRE,
    P.TOTAL_LIQUIDO_PRE, P.COMENTARIOS_PRE,
    P.CONTADOR_LINEAS_PRE, NOW(),
    NOW(), p_USUARIO,
    p_USUARIO, P.CODIGO_ALM_PRE,
    (SELECT COALESCE(SUM(L.TOTAL_PRELIN), 0)
      FROM fza_presupuestos_lineas L
      WHERE L.SERIE_PRE_PRELIN = p_SERIE
        AND L.NUMERO_PRE_PRELIN = p_NUMERO
        AND COALESCE(NULLIF(L.TIPO_IVA_ARTICULO_PRELIN, ''), 'N') = 'N'),
    (SELECT COALESCE(SUM(L.TOTAL_PRELIN), 0)
      FROM fza_presupuestos_lineas L
      WHERE L.SERIE_PRE_PRELIN = p_SERIE
        AND L.NUMERO_PRE_PRELIN = p_NUMERO
        AND COALESCE(NULLIF(L.TIPO_IVA_ARTICULO_PRELIN, ''), 'N') = 'R'),
    (SELECT COALESCE(SUM(L.TOTAL_PRELIN), 0)
      FROM fza_presupuestos_lineas L
      WHERE L.SERIE_PRE_PRELIN = p_SERIE
        AND L.NUMERO_PRE_PRELIN = p_NUMERO
        AND COALESCE(NULLIF(L.TIPO_IVA_ARTICULO_PRELIN, ''), 'N') = 'S'),
    (SELECT COALESCE(SUM(L.TOTAL_PRELIN), 0)
      FROM fza_presupuestos_lineas L
      WHERE L.SERIE_PRE_PRELIN = p_SERIE
        AND L.NUMERO_PRE_PRELIN = p_NUMERO
        AND COALESCE(NULLIF(L.TIPO_IVA_ARTICULO_PRELIN, ''), 'N') = 'E')
  FROM fza_presupuestos P
  WHERE P.SERIE_PRE = p_SERIE AND P.NUMERO_PRE = p_NUMERO;
END
;;
