CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_PRE_COPIAR_FAC_LINEAS`(
  IN p_SERIE varchar(20), IN p_NUMERO varchar(20),
  IN p_SERIE_DESTINO varchar(12), IN p_NUMERO_DESTINO varchar(20),
  IN p_USUARIO varchar(100)
)
BEGIN
  INSERT INTO fza_facturas_lineas (
    NUMERO_FAC_FACLIN, SERIE_FAC_FACLIN,
    LINEA_FACLIN, CODIGO_ART_FACLIN,
    CODIGO_UNIDAD_FACLIN, LOTE_FACLIN,
    FECHA_CADUCIDAD_FACLIN, CODIGO_FAM_FACLIN,
    NOMBRE_FAM_FACLIN, TIPO_CANTIDAD_ARTICULO_FACLIN,
    CANTIDAD_FACLIN, DESCRIPCION_ARTICULO_FACLIN,
    DESCRIPCION_VARIACION_FACLIN, CODIGO_TAR_FACLIN,
    ESIMP_INCL_TARIFA_FACLIN, PRECIO_VENTA_SIVA_ARTICULO_FACLIN,
    TIPO_IVA_ARTICULO_FACLIN, PORCENTAJE_IVA_FACLIN,
    PRECIO_VENTA_CIVA_ARTICULO_FACLIN, TOTAL_FACLIN, TOTAL_FAC_SIVA_FACLIN, CODIGO_ALM_FACLIN,
    INSTANTE_MODIF, INSTANTE_ALTA,
    USUARIO_ALTA, USUARIO_MODIF,
    ATTR1_VALOR_FACLIN, ATTR1_NOMBRE_FACLIN,
    ATTR2_VALOR_FACLIN, ATTR2_NOMBRE_FACLIN,
    ATTR3_VALOR_FACLIN, ATTR3_NOMBRE_FACLIN,
    ATTR4_VALOR_FACLIN, ATTR4_NOMBRE_FACLIN,
    ATTR5_VALOR_FACLIN, ATTR5_NOMBRE_FACLIN,
    NUM_ATRIBUTOS_FACLIN,
    CODIGO_EMP_FACLIN,
    PRECIO_SALIDA_FACLIN,
    PORCENTAJE_DTO_FACLIN, PRECIO_DTO_FACLIN,
    TIPO_ARTICULO_FACLIN)
  SELECT
    p_NUMERO_DESTINO, p_SERIE_DESTINO,
    P.LINEA_PRELIN, P.CODIGO_ART_PRELIN,
    P.CODIGO_UNIDAD_PRELIN, P.LOTE_PRELIN,
    P.FECHA_CADUCIDAD_PRELIN, P.CODIGO_FAM_PRELIN,
    P.NOMBRE_FAM_PRELIN, P.TIPO_CANTIDAD_ARTICULO_PRELIN,
    P.CANTIDAD_PRELIN, P.DESCRIPCION_ARTICULO_PRELIN,
    P.DESCRIPCION_VARIACION_PRELIN, P.CODIGO_TAR_PRELIN,
    P.ESIMP_INCL_TARIFA_PRELIN, P.PRECIO_VENTA_SIVA_ARTICULO_PRELIN,
    P.TIPO_IVA_ARTICULO_PRELIN, P.PORCENTAJE_IVA_PRELIN,
    P.PRECIO_VENTA_CIVA_ARTICULO_PRELIN, ROUND(P.CANTIDAD_PRELIN * P.PRECIO_VENTA_CIVA_ARTICULO_PRELIN, 2),
    P.TOTAL_PRELIN, P.CODIGO_ALMACEN_PRELIN,
    NOW(), NOW(),
    p_USUARIO, p_USUARIO,
    P.ATTR1_VALOR_PRELIN, P.ATTR1_NOMBRE_PRELIN,
    P.ATTR2_VALOR_PRELIN, P.ATTR2_NOMBRE_PRELIN,
    P.ATTR3_VALOR_PRELIN, P.ATTR3_NOMBRE_PRELIN,
    P.ATTR4_VALOR_PRELIN, P.ATTR4_NOMBRE_PRELIN,
    P.ATTR5_VALOR_PRELIN, P.ATTR5_NOMBRE_PRELIN,
    P.NUM_ATRIBUTOS_PRELIN,
    (SELECT H.CODIGO_EMP_PRE FROM fza_presupuestos H
      WHERE H.SERIE_PRE = p_SERIE AND H.NUMERO_PRE = p_NUMERO),
    COALESCE(P.PRECIO_SALIDA_PRELIN,
      CASE WHEN P.ESIMP_INCL_TARIFA_PRELIN = 'S'
        THEN P.PRECIO_VENTA_CIVA_ARTICULO_PRELIN
        ELSE P.PRECIO_VENTA_SIVA_ARTICULO_PRELIN END),
    COALESCE(P.PORCENTAJE_DTO_PRELIN, 0),
    COALESCE(P.PRECIO_DTO_PRELIN, 0),
    COALESCE((SELECT A.TIPO_ART FROM fza_articulos A
      WHERE A.CODIGO_ART_ART = P.CODIGO_ART_PRELIN), 'ESTANDAR')
  FROM fza_presupuestos_lineas P
  WHERE P.SERIE_PRE_PRELIN = p_SERIE AND P.NUMERO_PRE_PRELIN = p_NUMERO;
END
;;
DELIMITER ;
