CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_PRE_COPIAR_PED_CABECERA`(
  IN p_SERIE varchar(20), IN p_NUMERO varchar(20),
  IN p_SERIE_DESTINO varchar(12), IN p_NUMERO_DESTINO varchar(20),
  IN p_USUARIO varchar(100)
)
BEGIN
  CALL PRC_PRE_PREPARAR_RECARGO(p_SERIE, p_NUMERO);
  CALL PRC_PRE_TOTALES_RECARGO(p_SERIE, p_NUMERO);
  INSERT INTO fza_pedidos (
    NUMERO_PED, SERIE_PED,
    FECHA_PED, ESCONSOLIDADO_PED,
    ESTADO_PED, CODIGO_EMP_PED,
    CODIGO_ALM_PED, RAZON_SOCIAL_EMPRESA_PED,
    NIF_EMPRESA_PED, MOVIL_EMPRESA_PED,
    EMAIL_EMPRESA_PED, DIRECCION1_EMPRESA_PED,
    DIRECCION2_EMPRESA_PED, POBLACION_EMPRESA_PED,
    PROVINCIA_EMPRESA_PED, CODIGO_PAI_EMPRESA_PED,
    NOMBRE_PAI_EMPRESA_PED, CODIGO_POSTAL_EMPRESA_PED,
    GRUPO_ZONA_IVA_EMPRESA_PED, CODIGO_CLI_PED,
    NIF_CLIENTE_PED, EMAIL_CLIENTE_PED,
    NOMBRE_CLI_ENVIO_PED, MOVIL_CLIENTE_ENVIO_PED,
    DIRECCION1_CLIENTE_ENVIO_PED, DIRECCION2_CLIENTE_ENVIO_PED,
    POBLACION_CLIENTE_ENVIO_PED, PROVINCIA_CLIENTE_ENVIO_PED,
    CODIGO_POSTAL_CLIENTE_ENVIO_PED, CODIGO_PAI_CLIENTE_ENVIO_PED,
    NOMBRE_PAI_CLIENTE_ENVIO_PED, ESIVA_RECARGO_CLIENTE_PED,
    ESIVA_EXENTO_CLIENTE_PED, TARIFA_ARTICULO_CLIENTE_PED,
    ESIMP_INCL_TARIFA_CLIENTE_PED, ESINTRACOMUNITARIO_CLIENTE_PED,
    CODIGO_IVA_PED, ESAPLICA_RE_ZONA_IVA_PED,
    PORCENTAJE_REN_PED,
    TOTAL_REN_PED,
    PORCENTAJE_RER_PED,
    TOTAL_RER_PED,
    PORCENTAJE_RES_PED,
    TOTAL_RES_PED,
    PORCENTAJE_REE_PED,
    TOTAL_REE_PED,
    PORCENTAJE_IVAN_PED,
    TOTAL_IVAN_PED, PORCENTAJE_IVAR_PED,
    TOTAL_IVAR_PED, PORCENTAJE_IVAS_PED,
    TOTAL_IVAS_PED, PORCENTAJE_IVAE_PED,
    TOTAL_IVAE_PED, TOTAL_BASES_PED,
    TOTAL_IMPUESTOS_PED, FORMA_PAGO_PED,
    ESRETENCIONES_EMPRESA_PED, ESRETENCIONES_CLIENTE_PED,
    ESREGIMENESPECIALAGRICOLA_EMPRESA_PED,
    ESREGIMENESPECIALAGRICOLA_CLIENTE_PED,
    PORCENTAJE_RETENCION_PED, TOTAL_RETENCION_PED,
    TOTAL_LIQUIDO_PED, COMENTARIOS_PED,
    OBSERVACIONES_PED, CONTADOR_LINEAS_PED,
    INSTANTE_MODIF, INSTANTE_ALTA,
    USUARIO_ALTA, USUARIO_MODIF,
    RAZON_SOCIAL_CLIENTE_FISCAL_PED,
    MOVIL_CLIENTE_FISCAL_PED,
    EMAIL_CLIENTE_FISCAL_PED,
    DIRECCION1_CLIENTE_FISCAL_PED,
    DIRECCION2_CLIENTE_FISCAL_PED,
    POBLACION_CLIENTE_FISCAL_PED,
    PROVINCIA_CLIENTE_FISCAL_PED,
    CODIGO_POSTAL_CLIENTE_FISCAL_PED,
    CODIGO_PAI_CLIENTE_FISCAL_PED,
    NOMBRE_PAI_CLIENTE_FISCAL_PED,
    TOTAL_BASEI_IVAN_PED,
    TOTAL_BASEI_IVAR_PED,
    TOTAL_BASEI_IVAS_PED,
    TOTAL_BASEI_IVAE_PED)
  SELECT
    p_NUMERO_DESTINO, p_SERIE_DESTINO,
    CURRENT_DATE(), P.ESCONSOLIDADO_PRE,
    'PENDIENTE', P.CODIGO_EMP_PRE,
    P.CODIGO_ALM_PRE, P.RAZON_SOCIAL_EMPRESA_PRE,
    P.NIF_EMPRESA_PRE, P.MOVIL_EMPRESA_PRE,
    P.EMAIL_EMPRESA_PRE, P.DIRECCION1_EMPRESA_PRE,
    P.DIRECCION2_EMPRESA_PRE, P.POBLACION_EMPRESA_PRE,
    P.PROVINCIA_EMPRESA_PRE, P.CODIGO_PAI_EMPRESA_PRE,
    P.NOMBRE_PAI_EMPRESA_PRE, P.CODIGO_POSTAL_EMPRESA_PRE,
    P.GRUPO_ZONA_IVA_EMPRESA_PRE, P.CODIGO_CLI_PRE,
    P.NIF_CLIENTE_PRE, P.EMAIL_CLIENTE_PRE,
    P.NOMBRE_CLI_ENVIO_PRE, P.MOVIL_CLIENTE_ENVIO_PRE,
    P.DIRECCION1_CLIENTE_ENVIO_PRE, P.DIRECCION2_CLIENTE_ENVIO_PRE,
    P.POBLACION_CLIENTE_ENVIO_PRE, P.PROVINCIA_CLIENTE_ENVIO_PRE,
    P.CODIGO_POSTAL_CLIENTE_ENVIO_PRE, P.CODIGO_PAI_CLIENTE_ENVIO_PRE,
    P.NOMBRE_PAI_CLIENTE_ENVIO_PRE, P.ESIVA_RECARGO_CLIENTE_PRE,
    P.ESIVA_EXENTO_CLIENTE_PRE, P.TARIFA_ARTICULO_CLIENTE_PRE,
    P.ESIMP_INCL_TARIFA_CLIENTE_PRE, P.ESINTRACOMUNITARIO_CLIENTE_PRE,
    P.CODIGO_IVA_PRE, P.ESAPLICA_RE_ZONA_IVA_PRE,
    P.PORCENTAJE_REN_PRE,
    P.TOTAL_REN_PRE,
    P.PORCENTAJE_RER_PRE,
    P.TOTAL_RER_PRE,
    P.PORCENTAJE_RES_PRE,
    P.TOTAL_RES_PRE,
    P.PORCENTAJE_REE_PRE,
    P.TOTAL_REE_PRE,
    P.PORCENTAJE_IVAN_PRE,
    P.TOTAL_IVAN_PRE, P.PORCENTAJE_IVAR_PRE,
    P.TOTAL_IVAR_PRE, P.PORCENTAJE_IVAS_PRE,
    P.TOTAL_IVAS_PRE, P.PORCENTAJE_IVAE_PRE,
    P.TOTAL_IVAE_PRE, P.TOTAL_BASES_PRE,
    P.TOTAL_IMPUESTOS_PRE, P.FORMA_PAGO_PRE,
    COALESCE(P.ESRETENCIONES_EMPRESA_PRE, 'N'),
    COALESCE(P.ESRETENCIONES_CLIENTE_PRE, 'N'),
    COALESCE(P.ESREGIMENESPECIALAGRICOLA_EMPRESA_PRE, 'N'),
    COALESCE(P.ESREGIMENESPECIALAGRICOLA_CLIENTE_PRE, 'N'),
    P.PORCENTAJE_RETENCION_PRE, P.TOTAL_RETENCION_PRE,
    P.TOTAL_LIQUIDO_PRE, P.COMENTARIOS_PRE,
    P.OBSERVACIONES_PRE, P.CONTADOR_LINEAS_PRE,
    NOW(), NOW(),
    p_USUARIO, p_USUARIO,
    P.RAZON_SOCIAL_CLIENTE_PRE,
    P.MOVIL_CLIENTE_PRE,
    P.EMAIL_CLIENTE_PRE,
    P.DIRECCION1_CLIENTE_PRE,
    P.DIRECCION2_CLIENTE_PRE,
    P.POBLACION_CLIENTE_PRE,
    P.PROVINCIA_CLIENTE_PRE,
    P.CODIGO_POSTAL_CLIENTE_PRE,
    P.CODIGO_PAI_CLIENTE_PRE,
    P.NOMBRE_PAI_CLIENTE_PRE,
    (SELECT COALESCE(SUM(L.TOTAL_PRELIN), 0)
      FROM fza_presupuestos_lineas L
      WHERE L.SERIE_PRE_PRELIN = p_SERIE
        AND L.NUMERO_PRE_PRELIN = p_NUMERO
        AND COALESCE(NULLIF(L.TIPO_IVA_ARTICULO_PRELIN, ''), 'N') = 'N'),
    (SELECT COALESCE(SUM(L.TOTAL_PRELIN), 0)
      FROM fza_presupuestos_lineas L
      WHERE L.SERIE_PRE_PRELIN = p_SERIE
        AND L.NUMERO_PRE_PRELIN = p_NUMERO
        AND COALESCE(NULLIF(L.TIPO_IVA_ARTICULO_PRELIN, ''), 'N') = 'R'),
    (SELECT COALESCE(SUM(L.TOTAL_PRELIN), 0)
      FROM fza_presupuestos_lineas L
      WHERE L.SERIE_PRE_PRELIN = p_SERIE
        AND L.NUMERO_PRE_PRELIN = p_NUMERO
        AND COALESCE(NULLIF(L.TIPO_IVA_ARTICULO_PRELIN, ''), 'N') = 'S'),
    (SELECT COALESCE(SUM(L.TOTAL_PRELIN), 0)
      FROM fza_presupuestos_lineas L
      WHERE L.SERIE_PRE_PRELIN = p_SERIE
        AND L.NUMERO_PRE_PRELIN = p_NUMERO
        AND COALESCE(NULLIF(L.TIPO_IVA_ARTICULO_PRELIN, ''), 'N') = 'E')
  FROM fza_presupuestos P
  WHERE P.SERIE_PRE = p_SERIE AND P.NUMERO_PRE = p_NUMERO;
END
;;
