CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_PRE_COPIAR_PED_LINEAS`(
  IN p_SERIE varchar(20), IN p_NUMERO varchar(20),
  IN p_SERIE_DESTINO varchar(12), IN p_NUMERO_DESTINO varchar(20),
  IN p_USUARIO varchar(100)
)
BEGIN
  INSERT INTO fza_pedidos_lineas (
    NUMERO_PED_PEDLIN, SERIE_PED_PEDLIN,
    LINEA_PEDLIN, CODIGO_ART_PEDLIN,
    CODIGO_FAM_PEDLIN, NOMBRE_FAM_PEDLIN,
    TIPO_CANTIDAD_ARTICULO_PEDLIN, ESIMP_INCL_TARIFA_PEDLIN,
    TIPO_IVA_ARTICULO_PEDLIN, DESCRIPCION_ARTICULO_PEDLIN,
    CODIGO_TAR_PEDLIN, CANTIDAD_PEDLIN,
    CANTIDAD_PENDIENTE_PEDLIN, CODIGO_ALMACEN_PEDLIN,
    PRECIO_VENTA_SIVA_ARTICULO_PEDLIN, PORCENTAJE_IVA_PEDLIN,
    PRECIO_VENTA_CIVA_ARTICULO_PEDLIN, TOTAL_PEDLIN,
    INSTANTE_MODIF, INSTANTE_ALTA,
    USUARIO_ALTA, USUARIO_MODIF,
    CODIGO_UNIDAD_PEDLIN, ATTR1_VALOR_PEDLIN,
    ATTR1_NOMBRE_PEDLIN, ATTR2_VALOR_PEDLIN,
    ATTR2_NOMBRE_PEDLIN, ATTR3_VALOR_PEDLIN,
    ATTR3_NOMBRE_PEDLIN, ATTR4_VALOR_PEDLIN,
    ATTR4_NOMBRE_PEDLIN, ATTR5_VALOR_PEDLIN,
    ATTR5_NOMBRE_PEDLIN, NUM_ATRIBUTOS_PEDLIN,
    ID_AC_PIVOT_PEDLIN,
    PRECIO_SALIDA_PEDLIN,
    PORCENTAJE_DTO_PEDLIN, PRECIO_DTO_PEDLIN)
  SELECT
    p_NUMERO_DESTINO, p_SERIE_DESTINO,
    P.LINEA_PRELIN, P.CODIGO_ART_PRELIN,
    P.CODIGO_FAM_PRELIN, P.NOMBRE_FAM_PRELIN,
    P.TIPO_CANTIDAD_ARTICULO_PRELIN, P.ESIMP_INCL_TARIFA_PRELIN,
    P.TIPO_IVA_ARTICULO_PRELIN, P.DESCRIPCION_ARTICULO_PRELIN,
    P.CODIGO_TAR_PRELIN, P.CANTIDAD_PRELIN,
    P.CANTIDAD_PRELIN, P.CODIGO_ALMACEN_PRELIN,
    P.PRECIO_VENTA_SIVA_ARTICULO_PRELIN, P.PORCENTAJE_IVA_PRELIN,
    P.PRECIO_VENTA_CIVA_ARTICULO_PRELIN, P.TOTAL_PRELIN,
    NOW(), NOW(),
    p_USUARIO, p_USUARIO,
    COALESCE(P.CODIGO_UNIDAD_PRELIN, ''), P.ATTR1_VALOR_PRELIN,
    P.ATTR1_NOMBRE_PRELIN, P.ATTR2_VALOR_PRELIN,
    P.ATTR2_NOMBRE_PRELIN, P.ATTR3_VALOR_PRELIN,
    P.ATTR3_NOMBRE_PRELIN, P.ATTR4_VALOR_PRELIN,
    P.ATTR4_NOMBRE_PRELIN, P.ATTR5_VALOR_PRELIN,
    P.ATTR5_NOMBRE_PRELIN, P.NUM_ATRIBUTOS_PRELIN,
    P.ID_AC_PIVOT_PRELIN,
    COALESCE(P.PRECIO_SALIDA_PRELIN,
      CASE WHEN P.ESIMP_INCL_TARIFA_PRELIN = 'S'
        THEN P.PRECIO_VENTA_CIVA_ARTICULO_PRELIN
        ELSE P.PRECIO_VENTA_SIVA_ARTICULO_PRELIN END),
    COALESCE(P.PORCENTAJE_DTO_PRELIN, 0),
    COALESCE(P.PRECIO_DTO_PRELIN, 0)
  FROM fza_presupuestos_lineas P
  WHERE P.SERIE_PRE_PRELIN = p_SERIE AND P.NUMERO_PRE_PRELIN = p_NUMERO;
END
;;
