DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_PRE_PREPARAR_RECARGO`(
  IN p_SERIE varchar(20), IN p_NUMERO varchar(20))
BEGIN
  UPDATE fza_presupuestos D
  LEFT JOIN fza_ivas I ON I.CODIGO_IVA = D.CODIGO_IVA_PRE
  LEFT JOIN fza_ivas_grupos G ON G.IVA_IVAGRP = I.IVA_IVAGRP
     SET D.ESAPLICA_RE_ZONA_IVA_PRE = COALESCE(
      D.ESAPLICA_RE_ZONA_IVA_PRE, G.ESAPLICA_RE_IVA_IVAGRP, 'S'),
         D.PORCENTAJE_REN_PRE = COALESCE(
      D.PORCENTAJE_REN_PRE, I.PORCENTAJE_NORMAL_RE_IVA, 0),
         D.PORCENTAJE_RER_PRE = COALESCE(
      D.PORCENTAJE_RER_PRE, I.PORCENTAJE_REDUCIDO_RE_IVA, 0),
         D.PORCENTAJE_RES_PRE = COALESCE(
      D.PORCENTAJE_RES_PRE, I.PORCENTAJE_SUPERREDUCIDO_RE_IVA, 0),
         D.PORCENTAJE_REE_PRE = COALESCE(
      D.PORCENTAJE_REE_PRE, I.PORCENTAJE_EXENTO_RE_IVA, 0)
   WHERE D.SERIE_PRE = p_SERIE AND D.NUMERO_PRE = p_NUMERO;
END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
