/*!50003 DROP PROCEDURE IF EXISTS `PRC_PRE_RESERVAR_NUMERO` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_spanish_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_PRE_RESERVAR_NUMERO`(
  IN p_TIPO varchar(2), IN p_EMPRESA varchar(10),
  IN p_SERIE varchar(12), IN p_USUARIO varchar(100),
  OUT p_NUMERO varchar(20)
)
BEGIN
  DECLARE v_SIGUIENTE bigint;
  DECLARE v_DIGITOS int;
  DECLARE v_SUELO bigint DEFAULT 0;
  IF p_TIPO NOT IN ('PE', 'AV', 'FC', 'PV') OR
     COALESCE(p_SERIE, '') = '' OR COALESCE(p_EMPRESA, '') = '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Serie o empresa no válida';
  END IF;
  INSERT INTO fza_contadores
    (TIPO_DOC_CON, EMPRESA_CON, SERIE_CON, CON, NUM_DIGITOS_CON,
     INSTANTE_ALTA, USUARIO_ALTA, USUARIO_MODIF)
  VALUES (p_TIPO, p_EMPRESA, p_SERIE, 1, 6,
    NOW(), p_USUARIO, p_USUARIO)
  ON DUPLICATE KEY UPDATE CON = CON;
  SELECT GREATEST(CON, 1), NUM_DIGITOS_CON
    INTO v_SIGUIENTE, v_DIGITOS FROM fza_contadores
   WHERE TIPO_DOC_CON = p_TIPO AND EMPRESA_CON = p_EMPRESA
     AND SERIE_CON = p_SERIE AND ESACTIVO_CON = 'S' FOR UPDATE;
  IF v_SIGUIENTE IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Contador desactivado';
  END IF;
  CASE p_TIPO
    WHEN 'PE' THEN SELECT COALESCE(MAX(CAST(NUMERO_PED AS UNSIGNED)), 0)
      INTO v_SUELO FROM fza_pedidos WHERE SERIE_PED = p_SERIE;
    WHEN 'AV' THEN SELECT COALESCE(MAX(CAST(NUMERO_ALB AS UNSIGNED)), 0)
      INTO v_SUELO FROM fza_albaranes WHERE SERIE_ALB = p_SERIE;
    WHEN 'FC' THEN SELECT COALESCE(MAX(CAST(NUMERO_FAC AS UNSIGNED)), 0)
      INTO v_SUELO FROM fza_facturas WHERE SERIE_FAC = p_SERIE;
    WHEN 'PV' THEN SELECT COALESCE(MAX(CAST(NUMERO_PRE AS UNSIGNED)), 0)
      INTO v_SUELO FROM fza_presupuestos WHERE SERIE_PRE = p_SERIE;
  END CASE;
  SET v_SIGUIENTE = GREATEST(v_SIGUIENTE, v_SUELO + 1);
  SET p_NUMERO = CAST(v_SIGUIENTE AS CHAR);
  IF v_DIGITOS > LENGTH(p_NUMERO) THEN
    SET p_NUMERO = LPAD(p_NUMERO, v_DIGITOS, '0');
  END IF;
  UPDATE fza_contadores SET CON = v_SIGUIENTE + 1,
    INSTANTE_MODIF = NOW(), USUARIO_MODIF = p_USUARIO
   WHERE TIPO_DOC_CON = p_TIPO AND EMPRESA_CON = p_EMPRESA
     AND SERIE_CON = p_SERIE;
END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
