/*!50003 DROP PROCEDURE IF EXISTS `PRC_PRE_TOTALES_RECARGO` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_spanish_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_PRE_TOTALES_RECARGO`(
  IN p_SERIE varchar(20), IN p_NUMERO varchar(20))
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM INFORMATION_SCHEMA.COLUMNS
    WHERE TABLE_SCHEMA = DATABASE()
      AND TABLE_NAME = 'fza_presupuestos_lineas'
      AND COLUMN_NAME = 'TOTAL_PRELIN') THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'Falta TOTAL_PRELIN para calcular el presupuesto';
  END IF;
  UPDATE fza_presupuestos D
  CROSS JOIN (
    SELECT
      COALESCE(SUM(IF(X.TIPO = 'N', X.BASE, 0)), 0) AS BASE_N,
      ROUND(SUM(IF(X.TIPO = 'N', X.CUOTA, 0)), 2) AS IVA_N,
      COALESCE(SUM(IF(X.TIPO = 'R', X.BASE, 0)), 0) AS BASE_R,
      ROUND(SUM(IF(X.TIPO = 'R', X.CUOTA, 0)), 2) AS IVA_R,
      COALESCE(SUM(IF(X.TIPO = 'S', X.BASE, 0)), 0) AS BASE_S,
      ROUND(SUM(IF(X.TIPO = 'S', X.CUOTA, 0)), 2) AS IVA_S,
      COALESCE(SUM(IF(X.TIPO = 'E', X.BASE, 0)), 0) AS BASE_E,
      ROUND(SUM(IF(X.TIPO = 'E', X.CUOTA, 0)), 2) AS IVA_E
    FROM (
      SELECT ROUND(COALESCE(L.TOTAL_PRELIN, 0), 2) AS BASE,
        CASE WHEN COALESCE(D.ESIVA_EXENTO_CLIENTE_PRE, 'N') = 'S'
          OR COALESCE(D.ESINTRACOMUNITARIO_CLIENTE_PRE, 'N') = 'S'
          THEN 'E'
          WHEN UPPER(TRIM(L.TIPO_IVA_ARTICULO_PRELIN)) IN ('R', 'S', 'E')
          THEN UPPER(TRIM(L.TIPO_IVA_ARTICULO_PRELIN))
          ELSE 'N' END AS TIPO,
        CASE WHEN COALESCE(D.ESIVA_EXENTO_CLIENTE_PRE, 'N') = 'S'
          OR COALESCE(D.ESINTRACOMUNITARIO_CLIENTE_PRE, 'N') = 'S'
          THEN 0
          ELSE ROUND(COALESCE(L.TOTAL_PRELIN, 0), 2) *
            COALESCE(L.PORCENTAJE_IVA_PRELIN, 0) / 100 END AS CUOTA
      FROM fza_presupuestos_lineas L
      JOIN fza_presupuestos D
        ON D.SERIE_PRE = L.SERIE_PRE_PRELIN
        AND D.NUMERO_PRE = L.NUMERO_PRE_PRELIN
      WHERE D.SERIE_PRE = p_SERIE AND D.NUMERO_PRE = p_NUMERO
    ) X
  ) B
  SET
    D.TOTAL_BASEI_IVAN_PRE = B.BASE_N,
    D.TOTAL_IVAN_PRE = COALESCE(B.IVA_N, 0),
    D.TOTAL_REN_PRE = IF(D.ESIVA_RECARGO_CLIENTE_PRE = 'S'
      AND COALESCE(D.ESAPLICA_RE_ZONA_IVA_PRE, 'S') <> 'N'
      AND COALESCE(D.ESIVA_EXENTO_CLIENTE_PRE, 'N') <> 'S'
      AND COALESCE(D.ESINTRACOMUNITARIO_CLIENTE_PRE, 'N') <> 'S',
      ROUND(B.BASE_N * COALESCE(D.PORCENTAJE_REN_PRE, 0) / 100, 2), 0),
    D.TOTAL_BASEI_IVAR_PRE = B.BASE_R,
    D.TOTAL_IVAR_PRE = COALESCE(B.IVA_R, 0),
    D.TOTAL_RER_PRE = IF(D.ESIVA_RECARGO_CLIENTE_PRE = 'S'
      AND COALESCE(D.ESAPLICA_RE_ZONA_IVA_PRE, 'S') <> 'N'
      AND COALESCE(D.ESIVA_EXENTO_CLIENTE_PRE, 'N') <> 'S'
      AND COALESCE(D.ESINTRACOMUNITARIO_CLIENTE_PRE, 'N') <> 'S',
      ROUND(B.BASE_R * COALESCE(D.PORCENTAJE_RER_PRE, 0) / 100, 2), 0),
    D.TOTAL_BASEI_IVAS_PRE = B.BASE_S,
    D.TOTAL_IVAS_PRE = COALESCE(B.IVA_S, 0),
    D.TOTAL_RES_PRE = IF(D.ESIVA_RECARGO_CLIENTE_PRE = 'S'
      AND COALESCE(D.ESAPLICA_RE_ZONA_IVA_PRE, 'S') <> 'N'
      AND COALESCE(D.ESIVA_EXENTO_CLIENTE_PRE, 'N') <> 'S'
      AND COALESCE(D.ESINTRACOMUNITARIO_CLIENTE_PRE, 'N') <> 'S',
      ROUND(B.BASE_S * COALESCE(D.PORCENTAJE_RES_PRE, 0) / 100, 2), 0),
    D.TOTAL_BASEI_IVAE_PRE = B.BASE_E,
    D.TOTAL_IVAE_PRE = COALESCE(B.IVA_E, 0),
    D.TOTAL_REE_PRE = IF(D.ESIVA_RECARGO_CLIENTE_PRE = 'S'
      AND COALESCE(D.ESAPLICA_RE_ZONA_IVA_PRE, 'S') <> 'N'
      AND COALESCE(D.ESIVA_EXENTO_CLIENTE_PRE, 'N') <> 'S'
      AND COALESCE(D.ESINTRACOMUNITARIO_CLIENTE_PRE, 'N') <> 'S',
      ROUND(B.BASE_E * COALESCE(D.PORCENTAJE_REE_PRE, 0) / 100, 2), 0)
  WHERE D.SERIE_PRE = p_SERIE AND D.NUMERO_PRE = p_NUMERO;
  UPDATE fza_presupuestos
  SET TOTAL_BASES_PRE = COALESCE(TOTAL_BASEI_IVAN_PRE, 0) +
      COALESCE(TOTAL_BASEI_IVAR_PRE, 0) +
      COALESCE(TOTAL_BASEI_IVAS_PRE, 0) + COALESCE(TOTAL_BASEI_IVAE_PRE, 0),
    TOTAL_IMPUESTOS_PRE = COALESCE(TOTAL_IVAN_PRE, 0) +
      COALESCE(TOTAL_IVAR_PRE, 0) + COALESCE(TOTAL_IVAS_PRE, 0) +
      COALESCE(TOTAL_IVAE_PRE, 0) + COALESCE(TOTAL_REN_PRE, 0) +
      COALESCE(TOTAL_RER_PRE, 0) + COALESCE(TOTAL_RES_PRE, 0) +
      COALESCE(TOTAL_REE_PRE, 0)
  WHERE SERIE_PRE = p_SERIE AND NUMERO_PRE = p_NUMERO;
  UPDATE fza_presupuestos
  SET TOTAL_RETENCION_PRE = IF(
    COALESCE(ESRETENCIONES_CLIENTE_PRE, 'N') = 'S'
    AND COALESCE(ESRETENCIONES_EMPRESA_PRE, 'N') = 'S'
    AND TRIM(COALESCE(NIF_CLIENTE_PRE, '')) <> ''
    AND TRIM(COALESCE(RAZON_SOCIAL_CLIENTE_PRE, '')) <> ''
    AND TRIM(COALESCE(DIRECCION1_CLIENTE_PRE, '')) <> '',
    ROUND(TOTAL_BASES_PRE *
      COALESCE(PORCENTAJE_RETENCION_PRE, 0) / 100, 2), 0)
  WHERE SERIE_PRE = p_SERIE AND NUMERO_PRE = p_NUMERO;
  UPDATE fza_presupuestos
  SET TOTAL_LIQUIDO_PRE = TOTAL_BASES_PRE + TOTAL_IMPUESTOS_PRE -
    TOTAL_RETENCION_PRE
  WHERE SERIE_PRE = p_SERIE AND NUMERO_PRE = p_NUMERO;
END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_VALUE_ON_ZERO' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `PRC_RECALCULAR_STOCK` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_spanish_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_RECALCULAR_STOCK`()
BEGIN
  DECLARE v_TRANSACCION_PROPIA varchar(1) DEFAULT 'N';
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  bloque_error: BEGIN
    IF v_TRANSACCION_PROPIA = 'S' THEN
      ROLLBACK;
    ELSE
      RESIGNAL;
    END IF;
    SELECT 'ERROR: No se pudo recalcular el stock' AS MENSAJE;
  END bloque_error;
  IF @@in_transaction = 0 THEN
    SET v_TRANSACCION_PROPIA = 'S';
    START TRANSACTION;
  END IF;
  DELETE FROM fza_articulos_stockactual;
  
  INSERT INTO fza_articulos_stockactual (
    CODIGO_ALM_STK,
    CODIGO_UNIDAD_STK,
    LOTE_STK,
    FECHA_CADUCIDAD_STK,
    CANTIDAD_STK,
    INSTANTE_MODIF
  )
  SELECT M.CODIGO_ALM_MOV,
         M.CODIGO_UNIDAD_MOV,
         IFNULL(M.LOTE_MOV, ''),
         MAX(L.FECHA_CADUCIDAD_LOT),
         SUM(IF(M.TIPO_MOV = 'E', M.CANTIDAD_MOV, -M.CANTIDAD_MOV)),
         NOW()
    FROM fza_movimientos_almacen M
    LEFT JOIN fza_articulos_lotes L
      ON L.CODIGO_UNIDAD_LOT = M.CODIGO_UNIDAD_MOV
     AND L.LOTE_LOT = M.LOTE_MOV
     AND IFNULL(M.LOTE_MOV, '') <> ''
   WHERE M.ESACTIVO_MOV = 'S'
   GROUP BY M.CODIGO_ALM_MOV, M.CODIGO_UNIDAD_MOV, IFNULL(M.LOTE_MOV, '');
  CALL PRC_PRESTASHOP_ENCOLAR_TODOS_WEB(
    'N', 'S', '');
  IF v_TRANSACCION_PROPIA = 'S' THEN
    COMMIT;
  END IF;
  SELECT 'Stock recalculado correctamente.' AS MENSAJE;
END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_VALUE_ON_ZERO' */ ;
