/*!50003 DROP PROCEDURE IF EXISTS `PRC_REMV_ANYADIR_EFECTO` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_spanish_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_REMV_ANYADIR_EFECTO`(
    IN p_SERIE_REM varchar(20),
    IN p_NUMERO_REM varchar(20),
    IN p_SERIE_FAC varchar(20),
    IN p_NUMERO_FAC varchar(20),
    IN p_NUM_EFV int,
    IN p_USUARIO varchar(100),
    OUT p_RESULTADO int)
BEGIN
  DECLARE v_PROPIA varchar(1) DEFAULT 'N';
  DECLARE v_EMP varchar(8);
  DECLARE v_IBAN varchar(34);
  DECLARE v_ESTADO varchar(20);
  DECLARE v_TIPO varchar(20);
  DECLARE v_ACTIVO varchar(1);
  DECLARE v_REMESABLE varchar(1);
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    IF v_PROPIA = 'S' THEN ROLLBACK; END IF;
    SET p_RESULTADO = -1;
    RESIGNAL;
  END;
  SET p_RESULTADO = 0;
  IF @@in_transaction = 0 THEN
    SET v_PROPIA = 'S';
    START TRANSACTION;
  END IF;
  SELECT CODIGO_EMP_REMV, IBAN_REMV, ESTADO_REMV
    INTO v_EMP, v_IBAN, v_ESTADO
    FROM fza_remesas_venta
   WHERE SERIE_REMV = p_SERIE_REM AND NUMERO_REMV = p_NUMERO_REM
   FOR UPDATE;
  
  SELECT CODIGO_TEFE_EFV INTO v_TIPO FROM fza_efectos_venta
   WHERE SERIE_FAC_EFV = p_SERIE_FAC AND NUMERO_FAC_EFV = p_NUMERO_FAC
     AND NUMERO_EFV = p_NUM_EFV FOR UPDATE;
  SELECT ESACTIVO_TEFE, ESREMESABLE_TEFE INTO v_ACTIVO, v_REMESABLE
    FROM fza_tipos_efecto WHERE CODIGO_TEFE = v_TIPO FOR UPDATE;
  IF v_ESTADO IN ('ABIERTA', 'CERRADA') AND v_ACTIVO = 'S'
     AND v_REMESABLE = 'S' THEN
    UPDATE fza_efectos_venta
       SET SERIE_REMV_EFV = p_SERIE_REM, NUMERO_REMV_EFV = p_NUMERO_REM,
           ESTADO_EFV = 'REMESADO',
           IBAN_EMP_EFV = COALESCE(NULLIF(v_IBAN, ''), IBAN_EMP_EFV),
           INSTANTE_MODIF = NOW(), USUARIO_MODIF = p_USUARIO
     WHERE SERIE_FAC_EFV = p_SERIE_FAC AND NUMERO_FAC_EFV = p_NUMERO_FAC
       AND NUMERO_EFV = p_NUM_EFV AND CODIGO_EMP_EFV = v_EMP
       AND NULLIF(TRIM(SERIE_REMV_EFV), '') IS NULL
       AND NULLIF(TRIM(NUMERO_REMV_EFV), '') IS NULL
       AND ESTADO_EFV IN ('PENDIENTE', 'PARCIAL')
       AND COALESCE(ESCONCILIADO_EFV, 'N') <> 'S'
       AND COALESCE(IMPORTE_PENDIENTE_EFV, 0) > 0;
    SET p_RESULTADO = ROW_COUNT();
    IF p_RESULTADO = 1 THEN
      CALL PRC_REMV_RECALCULAR(p_SERIE_REM, p_NUMERO_REM);
    END IF;
  END IF;
  IF v_PROPIA = 'S' THEN COMMIT; END IF;
END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_VALUE_ON_ZERO' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `PRC_REMV_CREAR` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_spanish_ci */ ;
