/*!50001 VIEW `vi_articulos_skus_etiquetas` AS with sku_atrib as (select `sa`.`CODIGO_UNIDAD_SKU_SA` AS `CODIGO_UNIDAD_SKU`,max(case when `av`.`ID_VA_AV` = (select `ej452`.`ID_ATB_VA` from `vi_variaciones_ejes` `ej452` where `ej452`.`ID_VAR_VA` = (select `sk452`.`CODIGO_VAR_SKU` from `fza_articulos_skus` `sk452` where `sk452`.`CODIGO_UNIDAD_SKU` = `sa`.`CODIGO_UNIDAD_SKU_SA`) and `ej452`.`EJE_VA` = 'F') then `av`.`AV` end) AS `ATR_CO`,max(case when `av`.`ID_VA_AV` = (select `ej452`.`ID_ATB_VA` from `vi_variaciones_ejes` `ej452` where `ej452`.`ID_VAR_VA` = (select `sk452`.`CODIGO_VAR_SKU` from `fza_articulos_skus` `sk452` where `sk452`.`CODIGO_UNIDAD_SKU` = `sa`.`CODIGO_UNIDAD_SKU_SA`) and `ej452`.`EJE_VA` = 'P') then `av`.`AV` end) AS `ATR_TAL`,max(case when `av`.`ID_VA_AV` = (select `ej`.`ID_ATB_VA` from (`vi_variaciones_ejes` `ej` join `fza_articulos_skus` `sk` on(`sk`.`CODIGO_VAR_SKU` = `ej`.`ID_VAR_VA`)) where `sk`.`CODIGO_UNIDAD_SKU` = `sa`.`CODIGO_UNIDAD_SKU_SA` and `ej`.`EJE_VA` = 'S') then `av`.`AV` end) AS `ATR_PESTANA`,group_concat(concat(coalesce(`va`.`NOMBRE_VA`,`av`.`ID_VA_AV`),': ',`av`.`AV`) order by coalesce(`va`.`ORDEN_VA`,99) ASC,`av`.`ID_VA_AV` ASC separator ' / ') AS `ATRIBUTOS_TXT`,group_concat(`av`.`AV` order by coalesce(`va`.`ORDEN_VA`,99) ASC,`av`.`ID_VA_AV` ASC separator ' / ') AS `DESCRIPCION_SKU` from ((`fza_atributos_sku` `sa` join `fza_atributos_valores` `av` on(`av`.`ID_AV` = `sa`.`ID_AV_SA`)) left join `fza_variaciones_atributos` `va` on(`va`.`ID_ATB_VA` = `av`.`ID_VA_AV` and `va`.`ID_VAR_VA` = (select `sk452`.`CODIGO_VAR_SKU` from `fza_articulos_skus` `sk452` where `sk452`.`CODIGO_UNIDAD_SKU` = `sa`.`CODIGO_UNIDAD_SKU_SA`))) group by `sa`.`CODIGO_UNIDAD_SKU_SA`), art_prop as (select `ap`.`CODIGO_ART_ART` AS `CODIGO_ART_ART`,max(case when `ap`.`CODIGO_PROP_ARTPROP` = 'MARCA' then coalesce(`pv`.`PV`,`ap`.`VALOR_LIBRE_ARTPROP`) end) AS `PROP_MARCA`,max(case when `ap`.`CODIGO_PROP_ARTPROP` = 'MATERIAL' then coalesce(`pv`.`PV`,`ap`.`VALOR_LIBRE_ARTPROP`) end) AS `PROP_MATERIAL`,max(case when `ap`.`CODIGO_PROP_ARTPROP` = 'GENERO' then coalesce(`pv`.`PV`,`ap`.`VALOR_LIBRE_ARTPROP`) end) AS `PROP_GENERO`,max(case when `ap`.`CODIGO_PROP_ARTPROP` = 'ESTILO' then coalesce(`pv`.`PV`,`ap`.`VALOR_LIBRE_ARTPROP`) end) AS `PROP_ESTILO`,max(case when `ap`.`CODIGO_PROP_ARTPROP` = 'ORIGEN' then coalesce(`pv`.`PV`,`ap`.`VALOR_LIBRE_ARTPROP`) end) AS `PROP_ORIGEN`,max(case when `ap`.`CODIGO_PROP_ARTPROP` = 'COMPOSICION' then coalesce(`pv`.`PV`,`ap`.`VALOR_LIBRE_ARTPROP`) end) AS `PROP_COMPOSICION`,group_concat(concat(coalesce(`p`.`NOMBRE_PROP_PROP`,`ap`.`CODIGO_PROP_ARTPROP`),': ',coalesce(`pv`.`PV`,`ap`.`VALOR_LIBRE_ARTPROP`,'')) order by `ap`.`CODIGO_PROP_ARTPROP` ASC separator ' | ') AS `PROPIEDADES_TXT` from ((`fza_articulos_propiedades` `ap` left join `fza_propiedades` `p` on(`p`.`CODIGO_PROP_ARTPROP` = `ap`.`CODIGO_PROP_ARTPROP`)) left join `fza_propiedades_valores` `pv` on(`pv`.`ID_PV_ARTPROP` = `ap`.`ID_PV_ARTPROP`)) group by `ap`.`CODIGO_ART_ART`), sku_temp as (select `sku`.`CODIGO_UNIDAD_SKU` AS `CODIGO_UNIDAD_SKU`,coalesce(`tpv`.`PV`,`tps`.`VALOR_LIBRE_ARTPROP`,`tpc`.`VALOR_LIBRE_ARTPROP`,`tpa`.`VALOR_LIBRE_ARTPROP`) AS `PROP_TEMPORADA`,`tpv`.`DESCRIPCION_PV` AS `DESCRIPCION_TEMPORADA`,`tpv`.`DESCRIPCION_PV` AS `COD_TEMPORADA` from ((((`fza_articulos_skus` `sku` left join `fza_articulos_propiedades` `tps` on(`tps`.`CODIGO_ART_ART` = `sku`.`CODIGO_ART_SKU` and `tps`.`CODIGO_PROP_ARTPROP` = 'TEMPORADA' and `tps`.`CODIGO_UNIDAD_ARTPROP` = `sku`.`CODIGO_UNIDAD_SKU`)) left join `fza_articulos_propiedades` `tpc` on(`tpc`.`CODIGO_ART_ART` = `sku`.`CODIGO_ART_SKU` and `tpc`.`CODIGO_PROP_ARTPROP` = 'TEMPORADA' and `tpc`.`CODIGO_UNIDAD_ARTPROP` = case when char_length(`sku`.`CODIGO_UNIDAD_SKU`) - char_length(replace(`sku`.`CODIGO_UNIDAD_SKU`,'/','')) >= 2 then substring_index(`sku`.`CODIGO_UNIDAD_SKU`,'/',2) else NULL end)) left join `fza_articulos_propiedades` `tpa` on(`tpa`.`CODIGO_ART_ART` = `sku`.`CODIGO_ART_SKU` and `tpa`.`CODIGO_PROP_ARTPROP` = 'TEMPORADA' and `tpa`.`CODIGO_UNIDAD_ARTPROP` = '')) left join `fza_propiedades_valores` `tpv` on(`tpv`.`ID_PV_ARTPROP` = coalesce(`tps`.`ID_PV_ARTPROP`,`tpc`.`ID_PV_ARTPROP`,`tpa`.`ID_PV_ARTPROP`)))), cb_prin as (select `fza_codigos_barras`.`CODIGO_UNIDAD_CB` AS `CODIGO_UNIDAD_CB`,max(`fza_codigos_barras`.`CODIGO_BARRAS_CB`) AS `CODIGO_BARRAS_CB` from `fza_codigos_barras` where `fza_codigos_barras`.`ESPRINCIPAL_CB` = 'S' group by `fza_codigos_barras`.`CODIGO_UNIDAD_CB`), sku_medida as (select `m`.`CODIGO_UNIDAD_SKU` AS `CODIGO_UNIDAD_SKU`,`m`.`VALOR_BASICO` AS `VALOR_BASICO`,`m`.`UNIDAD_BASICA` AS `UNIDAD_BASICA`,`m`.`UNIDAD_PRECIO` AS `UNIDAD_PRECIO`,`m`.`FACTOR_PRECIO_UNIDAD` AS `FACTOR_PRECIO_UNIDAD` from (select `b`.`CODIGO_UNIDAD_SKU` AS `CODIGO_UNIDAD_SKU`,`b`.`VALOR_NUM_ATB` AS `VALOR_BASICO`,`u`.`CODIGO_UNIMED` AS `UNIDAD_BASICA`,(select min(`ub`.`CODIGO_UNIMED`) from `fza_unidades_medida` `ub` where `ub`.`MAGNITUD_UNIMED` = `u`.`MAGNITUD_UNIMED` and `ub`.`ESBASE_UNIMED` = 'S') AS `UNIDAD_PRECIO`,1 / (`b`.`VALOR_NUM_ATB` * `u`.`FACTOR_BASE_UNIMED`) AS `FACTOR_PRECIO_UNIDAD`,row_number() over ( partition by `b`.`CODIGO_UNIDAD_SKU` order by coalesce(`b`.`ORDEN_ATRIBUTO`,99),`b`.`ID_VA_AV`) AS `ORDEN_MEDIDA` from (`vi_atributos_sku_basico` `b` join `fza_unidades_medida` `u` on(`u`.`CODIGO_UNIMED` = case when lcase(trim(`b`.`UNIDAD_ATB`)) in ('gr','grs','gramo','gramos') then 'g' when lcase(trim(`b`.`UNIDAD_ATB`)) in ('kgs','kilo','kilos') then 'kg' when lcase(trim(`b`.`UNIDAD_ATB`)) in ('lt','lts','litro','litros') then 'l' else trim(`b`.`UNIDAD_ATB`) end collate utf8mb4_spanish_ci and `u`.`MAGNITUD_UNIMED` in ('MASA','VOLUMEN'))) where `b`.`VALOR_NUM_ATB` > 0 and `u`.`FACTOR_BASE_UNIMED` > 0) `m` where `m`.`ORDEN_MEDIDA` = 1)select `sku`.`CODIGO_UNIDAD_SKU` AS `CODIGO_UNIDAD_SKU`,`sku`.`CODIGO_ART_SKU` AS `CODIGO_ART_ART`,`sku`.`CODIGO_VAR_SKU` AS `CODIGO_VAR_SKU`,`sku`.`ESACTIVO_SKU` AS `ESACTIVO_SKU`,`art`.`ESACTIVO_ART` AS `ESACTIVO_ART`,`art`.`DESCRIPCION_ART` AS `DESCRIPCION_ART`,`art`.`TIPO_ART` AS `TIPO_ART`,`art`.`TIPO_IVA_ART` AS `TIPO_IVA_ART`,`art`.`CODIGO_FAM_ART` AS `CODIGO_FAM_ART`,`fam`.`NOMBRE_FAM_FAM` AS `NOMBRE_FAM_FAM`,`fam`.`DESCRIPCION_FAM` AS `DESCRIPCION_FAM`,`sa`.`ATR_CO` AS `ATR_CO`,`sa`.`ATR_TAL` AS `ATR_TAL`,(select max(`b`.`VALOR_NUM_ATB`) from `vi_atributos_sku_basico` `b` where `b`.`CODIGO_UNIDAD_SKU` = `sku`.`CODIGO_UNIDAD_SKU` and `b`.`ID_VA_AV` = 'TAL' and lcase(trim(`b`.`UNIDAD_ATB`)) = 'cm' and `b`.`VALOR_NUM_ATB` > 0) AS `VALOR_TALLA_CM`,`sa`.`ATRIBUTOS_TXT` AS `ATRIBUTOS_TXT`,`sa`.`DESCRIPCION_SKU` AS `DESCRIPCION_SKU`,`apr`.`PROP_MARCA` AS `PROP_MARCA`,`apr`.`PROP_MATERIAL` AS `PROP_MATERIAL`,`st`.`PROP_TEMPORADA` AS `PROP_TEMPORADA`,`st`.`DESCRIPCION_TEMPORADA` AS `DESCRIPCION_TEMPORADA`,`st`.`COD_TEMPORADA` AS `COD_TEMPORADA`,`apr`.`PROP_GENERO` AS `PROP_GENERO`,`apr`.`PROP_ESTILO` AS `PROP_ESTILO`,`apr`.`PROP_ORIGEN` AS `PROP_ORIGEN`,`apr`.`PROP_COMPOSICION` AS `PROP_COMPOSICION`,`apr`.`PROPIEDADES_TXT` AS `PROPIEDADES_TXT`,`ap`.`CODIGO_PRV_AP` AS `CODIGO_PRV_PRV`,`prv`.`RAZON_SOCIAL_PRV` AS `RAZON_SOCIAL_PRV`,`prv`.`NOMBRE_PRV` AS `NOMBRE_PRV`,`ap`.`REF_PROVEEDOR_AP` AS `REF_PROVEEDOR`,`cb`.`CODIGO_BARRAS_CB` AS `CODIGO_BARRAS_CB`,`sa`.`ATR_PESTANA` AS `ATR_PESTANA`,`med`.`VALOR_BASICO` AS `VALOR_BASICO`,`med`.`UNIDAD_BASICA` AS `UNIDAD_BASICA`,`med`.`UNIDAD_PRECIO` AS `UNIDAD_PRECIO`,`med`.`FACTOR_PRECIO_UNIDAD` AS `FACTOR_PRECIO_UNIDAD` from (((((((((`fza_articulos_skus` `sku` join `fza_articulos` `art` on(`art`.`CODIGO_ART_ART` = `sku`.`CODIGO_ART_SKU`)) left join `fza_articulos_familias` `fam` on(`fam`.`CODIGO_FAM_FAM` = `art`.`CODIGO_FAM_ART`)) left join `sku_atrib` `sa` on(`sa`.`CODIGO_UNIDAD_SKU` = `sku`.`CODIGO_UNIDAD_SKU`)) left join `art_prop` `apr` on(`apr`.`CODIGO_ART_ART` = `sku`.`CODIGO_ART_SKU`)) left join `sku_temp` `st` on(`st`.`CODIGO_UNIDAD_SKU` = `sku`.`CODIGO_UNIDAD_SKU`)) left join `fza_articulos_proveedores` `ap` on(`ap`.`CODIGO_ART_AP` = `sku`.`CODIGO_ART_SKU` and `ap`.`ESPROVEEDORPRINCIPAL_AP` = 'S')) left join `fza_proveedores` `prv` on(`prv`.`CODIGO_PRV_PRV` = `ap`.`CODIGO_PRV_AP`)) left join `cb_prin` `cb` on(`cb`.`CODIGO_UNIDAD_CB` = `sku`.`CODIGO_UNIDAD_SKU`)) left join `sku_medida` `med` on(`med`.`CODIGO_UNIDAD_SKU` = `sku`.`CODIGO_UNIDAD_SKU`)) */;
