/*!50001 VIEW `vi_caja_busqueda_unificada` AS select `a`.`CODIGO_ART_ART` AS `INPUT_BUSQUEDA`,_utf8mb4'CODIGO' collate utf8mb4_spanish_ci AS `TIPO_COINCIDENCIA`,`a`.`CODIGO_ART_ART` AS `CODIGO_PADRE`,cast(NULL as char charset utf8mb4) collate utf8mb4_spanish_ci AS `CODIGO_SKU`,`a`.`DESCRIPCION_ART` AS `DESCRIPCION_ART`,`a`.`TIPO_ART` AS `TIPO_ART`,cast(NULL as char(50) charset utf8mb4) collate utf8mb4_spanish_ci AS `LOTE_BUSQUEDA`,cast(NULL as date) AS `FECHA_CADUCIDAD_BUSQUEDA` from `fza_articulos` `a` where `a`.`ESACTIVO_ART` = 'S' union all select `sku`.`CODIGO_UNIDAD_SKU` AS `INPUT_BUSQUEDA`,_utf8mb4'SKU' collate utf8mb4_spanish_ci AS `TIPO_COINCIDENCIA`,`a`.`CODIGO_ART_ART` AS `CODIGO_PADRE`,`sku`.`CODIGO_UNIDAD_SKU` AS `CODIGO_SKU`,`a`.`DESCRIPCION_ART` AS `DESCRIPCION_ART`,`a`.`TIPO_ART` AS `TIPO_ART`,NULL AS `LOTE_BUSQUEDA`,NULL AS `FECHA_CADUCIDAD_BUSQUEDA` from (`fza_articulos_skus` `sku` join `fza_articulos` `a` on(`sku`.`CODIGO_ART_SKU` = `a`.`CODIGO_ART_ART`)) where `sku`.`ESACTIVO_SKU` = 'S' union all select `cb`.`CODIGO_BARRAS_CB` AS `INPUT_BUSQUEDA`,_utf8mb4'EAN' collate utf8mb4_spanish_ci AS `TIPO_COINCIDENCIA`,`a`.`CODIGO_ART_ART` AS `CODIGO_PADRE`,`sku`.`CODIGO_UNIDAD_SKU` AS `CODIGO_SKU`,`a`.`DESCRIPCION_ART` AS `DESCRIPCION_ART`,`a`.`TIPO_ART` AS `TIPO_ART`,NULL AS `LOTE_BUSQUEDA`,NULL AS `FECHA_CADUCIDAD_BUSQUEDA` from ((`fza_codigos_barras` `cb` join `fza_articulos_skus` `sku` on(`cb`.`CODIGO_UNIDAD_CB` = `sku`.`CODIGO_UNIDAD_SKU`)) join `fza_articulos` `a` on(`sku`.`CODIGO_ART_SKU` = `a`.`CODIGO_ART_ART`)) where `cb`.`LOTE_CB` is null union all select `ap`.`REF_PROVEEDOR_AP` AS `INPUT_BUSQUEDA`,_utf8mb4'MODELO_PROV' collate utf8mb4_spanish_ci AS `TIPO_COINCIDENCIA`,`a`.`CODIGO_ART_ART` AS `CODIGO_PADRE`,NULL AS `CODIGO_SKU`,`a`.`DESCRIPCION_ART` AS `DESCRIPCION_ART`,`a`.`TIPO_ART` AS `TIPO_ART`,NULL AS `LOTE_BUSQUEDA`,NULL AS `FECHA_CADUCIDAD_BUSQUEDA` from (`fza_articulos_proveedores` `ap` join `fza_articulos` `a` on(`ap`.`CODIGO_ART_AP` = `a`.`CODIGO_ART_ART`)) where `a`.`ESACTIVO_ART` = 'S' and `ap`.`REF_PROVEEDOR_AP` is not null and `ap`.`REF_PROVEEDOR_AP` <> '' union all select `cb`.`CODIGO_BARRAS_CB` AS `INPUT_BUSQUEDA`,case when `a`.`TIPO_TRAZABILIDAD_ART` = 'SERIE' then _utf8mb4'SERIE' collate utf8mb4_spanish_ci else _utf8mb4'LOTE' collate utf8mb4_spanish_ci end AS `TIPO_COINCIDENCIA`,`a`.`CODIGO_ART_ART` AS `CODIGO_PADRE`,`sku`.`CODIGO_UNIDAD_SKU` AS `CODIGO_SKU`,`a`.`DESCRIPCION_ART` AS `DESCRIPCION_ART`,`a`.`TIPO_ART` AS `TIPO_ART`,`cb`.`LOTE_CB` AS `LOTE_BUSQUEDA`,`lot`.`FECHA_CADUCIDAD_LOT` AS `FECHA_CADUCIDAD_BUSQUEDA` from (((`fza_codigos_barras` `cb` join `fza_articulos_skus` `sku` on(`cb`.`CODIGO_UNIDAD_CB` = `sku`.`CODIGO_UNIDAD_SKU`)) join `fza_articulos` `a` on(`sku`.`CODIGO_ART_SKU` = `a`.`CODIGO_ART_ART`)) left join `fza_articulos_lotes` `lot` on(`lot`.`CODIGO_UNIDAD_LOT` = `cb`.`CODIGO_UNIDAD_CB` and `lot`.`LOTE_LOT` = `cb`.`LOTE_CB`)) where `cb`.`LOTE_CB` is not null union all select `lot`.`LOTE_LOT` AS `INPUT_BUSQUEDA`,_utf8mb4'SERIE' collate utf8mb4_spanish_ci AS `TIPO_COINCIDENCIA`,`a`.`CODIGO_ART_ART` AS `CODIGO_PADRE`,`sku`.`CODIGO_UNIDAD_SKU` AS `CODIGO_SKU`,`a`.`DESCRIPCION_ART` AS `DESCRIPCION_ART`,`a`.`TIPO_ART` AS `TIPO_ART`,`lot`.`LOTE_LOT` AS `LOTE_BUSQUEDA`,NULL AS `FECHA_CADUCIDAD_BUSQUEDA` from ((`fza_articulos_lotes` `lot` join `fza_articulos_skus` `sku` on(`lot`.`CODIGO_UNIDAD_LOT` = `sku`.`CODIGO_UNIDAD_SKU`)) join `fza_articulos` `a` on(`sku`.`CODIGO_ART_SKU` = `a`.`CODIGO_ART_ART`)) where `lot`.`TIPO_LOT` = 'S' and `lot`.`ESACTIVO_LOT` = 'S' and !exists(select 1 from `fza_codigos_barras` `cbs` where `cbs`.`CODIGO_BARRAS_CB` = `lot`.`LOTE_LOT` limit 1) */;
