N_DEP` AS `FECHA_CREACION_DEP`,`d`.`FECHA_ENTREGA_DEP` AS `FECHA_ENTREGA_DEP`,`d`.`EMPRESA_CANCEL_DEP` AS `EMPRESA_CANCEL_DEP`,`d`.`ALMACEN_CANCEL_DEP` AS `ALMACEN_CANCEL_DEP`,`d`.`CAJA_CANCEL_DEP` AS `CAJA_CANCEL_DEP`,`d`.`NUMERO_OPERACION_CANCEL_DEP` AS `NUMERO_OPERACION_CANCEL_DEP` from `fza_depositos_cliente` `d` where `d`.`NUMERO_OPERACION_CANCEL_DEP` is not null and `d`.`NUMERO_OPERACION_CANCEL_DEP` <> '' union all select case `o`.`TIPO_OPERACION_OPCAJA` when 'DE' then 'COBRO_INICIAL' when 'CB' then 'COBRO_PARCIAL' end AS `ROL_EN_OPERACION`,`d`.`ID_DEPOSITO_DEP` AS `ID_DEPOSITO_DEP`,`o`.`CODIGO_EMP_OPCAJA` AS `CODIGO_EMPRESA_OP`,`o`.`CODIGO_ALM_OPCAJA` AS `CODIGO_ALMACEN_OP`,`o`.`CODIGO_CAJA_OPCAJA` AS `CODIGO_CAJA_OP`,`o`.`NUMERO_OPERACION_OPCAJA` AS `NUMERO_OPERACION_OP`,`d`.`CODIGO_CLI_DEP` AS `CODIGO_CLI_DEP`,`d`.`CODIGO_ART_DEP` AS `CODIGO_ART_DEP`,`d`.`CODIGO_UNIDAD_DEP` AS `CODIGO_UNIDAD_DEP`,`d`.`CODIGO_ALM_DEP` AS `CODIGO_ALM_DEP`,`d`.`CANTIDAD_PENDIENTE_DEP` AS `CANTIDAD_PENDIENTE_DEP`,`d`.`PRECIO_VENTA_DEP` AS `PRECIO_VENTA_DEP`,`d`.`PORCENTAJE_IVA_DEP` AS `PORCENTAJE_IVA_DEP`,`d`.`IMPORTE_ANTICIPO_DEP` AS `IMPORTE_ANTICIPO_DEP`,`d`.`PRECIO_VENTA_DEP` - `d`.`IMPORTE_ANTICIPO_DEP` AS `IMPORTE_PENDIENTE_DEP`,`d`.`ESTADO_DEP` AS `ESTADO_DEP`,`d`.`FECHA_CREACION_DEP` AS `FECHA_CREACION_DEP`,`d`.`FECHA_ENTREGA_DEP` AS `FECHA_ENTREGA_DEP`,`d`.`EMPRESA_CANCEL_DEP` AS `EMPRESA_CANCEL_DEP`,`d`.`ALMACEN_CANCEL_DEP` AS `ALMACEN_CANCEL_DEP`,`d`.`CAJA_CANCEL_DEP` AS `CAJA_CANCEL_DEP`,`d`.`NUMERO_OPERACION_CANCEL_DEP` AS `NUMERO_OPERACION_CANCEL_DEP` from (`fza_caja_operaciones` `o` join `fza_depositos_cliente` `d` on(`d`.`ID_DEPOSITO_DEP` = `o`.`ID_DEPOSITO_OPCAJA`)) where `o`.`TIPO_OPERACION_OPCAJA` in ('CB','DE') and `o`.`ID_DEPOSITO_OPCAJA` is not null */;
