/*!50001 VIEW `vi_caja_pagos` AS select `p`.`CODIGO_EMP_PAGO` AS `CODIGO_EMP_PAGO`,`p`.`CODIGO_ALM_PAGO` AS `CODIGO_ALM_PAGO`,`p`.`CODIGO_CAJA_PAGO` AS `CODIGO_CAJA_PAGO`,`p`.`SERIE_OPERACION_PAGO` AS `SERIE_OPERACION_PAGO`,`p`.`NUMERO_OPERACION_PAGO` AS `NUMERO_OPERACION_PAGO`,`p`.`NUMERO_LINEA_PAGO` AS `NUMERO_LINEA_PAGO`,`p`.`CODIGO_FP_CFP` AS `CODIGO_FP_CFP`,`p`.`CODIGO_DIVISA_PAGO` AS `CODIGO_DIVISA_PAGO`,`p`.`RED_BLOCKCHAIN_PAGO` AS `RED_BLOCKCHAIN_PAGO`,`p`.`FACTOR_CAMBIO_PAGO` AS `FACTOR_CAMBIO_PAGO`,`p`.`IMPORTE_DIVISA_PAGO` AS `IMPORTE_DIVISA_PAGO`,`p`.`IMPORTE_ENTREGADO_PAGO` AS `IMPORTE_ENTREGADO_PAGO`,`p`.`IMPORTE_CAMBIO_PAGO` AS `IMPORTE_CAMBIO_PAGO`,`p`.`REFERENCIA_FACPAG` AS `REFERENCIA_FACPAG`,`p`.`OBSERVACIONES_PAGO` AS `OBSERVACIONES_PAGO`,`p`.`INSTANTE_MODIF` AS `INSTANTE_MODIF`,`p`.`INSTANTE_ALTA` AS `INSTANTE_ALTA`,`p`.`USUARIO_ALTA` AS `USUARIO_ALTA`,coalesce(`o`.`FECHA_OP`,`p`.`INSTANTE_ALTA`) AS `FECHA_PAGO`,`o`.`NUM_FAC` AS `NUMERO_FAC_PAGO`,`o`.`SERIE_FAC` AS `SERIE_FAC_PAGO`,`fp`.`DESCRIPCION_FORMA_PAGO_CFP` AS `DESCRIPCION_FP_PAGO`,`o`.`TIPO_OPERACION` AS `TIPO_OPERACION_PAGO`,`o`.`EMPLEADO` AS `EMPLEADO_PAGO`,`o`.`CODIGO_CLI` AS `CODIGO_CLI_PAGO`,`o`.`IMPORTE_TOTAL` AS `IMPORTE_OPERACION_PAGO`,`o`.`ARQUEO` AS `ARQUEO_PAGO`,`o`.`SERIE_ORIGEN` AS `SERIE_ORIGEN_PAGO`,`o`.`NUMERO_ORIGEN` AS `NUMERO_ORIGEN_PAGO`,`o`.`MOTIVO_DEV` AS `MOTIVO_DEVOLUCION_PAGO`,`f`.`TIPO_FAC` AS `TIPO_FAC_PAGO`,`f`.`FASE_FAC` AS `FASE_FAC_PAGO`,`f`.`ESCONSOLIDADA_FAC` AS `ESCONSOLIDADA_FAC_PAGO`,`f`.`TOTAL_LIQUIDO_FAC` AS `TOTAL_FAC_PAGO`,`f`.`CODIGO_CLI_FAC` AS `CODIGO_CLI_FAC_PAGO`,`f`.`RAZON_SOCIAL_CLIENTE_FAC` AS `CLIENTE_FAC_PAGO` from (((`fza_caja_pagos` `p` left join (select `fza_caja_operaciones`.`CODIGO_EMP_OPCAJA` AS `CODIGO_EMP_OPCAJA`,`fza_caja_operaciones`.`CODIGO_ALM_OPCAJA` AS `CODIGO_ALM_OPCAJA`,`fza_caja_operaciones`.`CODIGO_CAJA_OPCAJA` AS `CODIGO_CAJA_OPCAJA`,`fza_caja_operaciones`.`NUMERO_OPERACION_OPCAJA` AS `NUMERO_OPERACION_OPCAJA`,min(`fza_caja_operaciones`.`FECHA_OPERACION_OPCAJA`) AS `FECHA_OP`,max(`fza_caja_operaciones`.`NUMERO_FAC_OPCAJA`) AS `NUM_FAC`,max(`fza_caja_operaciones`.`SERIE_FAC_OPCAJA`) AS `SERIE_FAC`,max(`fza_caja_operaciones`.`TIPO_OPERACION_OPCAJA`) AS `TIPO_OPERACION`,max(`fza_caja_operaciones`.`CODIGO_EMPLEADO_OPCAJA`) AS `EMPLEADO`,max(`fza_caja_operaciones`.`CODIGO_CLI_OPCAJA`) AS `CODIGO_CLI`,max(`fza_caja_operaciones`.`IMPORTE_TOTAL_OPCAJA`) AS `IMPORTE_TOTAL`,max(`fza_caja_operaciones`.`CODIGO_ARQUEO_OPCAJA`) AS `ARQUEO`,max(`fza_caja_operaciones`.`SERIE_REF_ORIGEN_OPCAJA`) AS `SERIE_ORIGEN`,max(`fza_caja_operaciones`.`NUMERO_REF_ORIGEN_OPCAJA`) AS `NUMERO_ORIGEN`,max(`fza_caja_operaciones`.`MOTIVO_DEVOLUCION_OPCAJA`) AS `MOTIVO_DEV` from `fza_caja_operaciones` group by `fza_caja_operaciones`.`CODIGO_EMP_OPCAJA`,`fza_caja_operaciones`.`CODIGO_ALM_OPCAJA`,`fza_caja_operaciones`.`CODIGO_CAJA_OPCAJA`,`fza_caja_operaciones`.`NUMERO_OPERACION_OPCAJA`) `o` on(`o`.`CODIGO_EMP_OPCAJA` = `p`.`CODIGO_EMP_PAGO` and `o`.`CODIGO_ALM_OPCAJA` = `p`.`CODIGO_ALM_PAGO` and `o`.`CODIGO_CAJA_OPCAJA` = `p`.`CODIGO_CAJA_PAGO` and `o`.`NUMERO_OPERACION_OPCAJA` = `p`.`NUMERO_OPERACION_PAGO`)) left join `fza_caja_formas_pago` `fp` on(`fp`.`CODIGO_FP_CFP` = `p`.`CODIGO_FP_CFP`)) left join `fza_facturas` `f` on(`f`.`NUMERO_FAC` = `o`.`NUM_FAC` and `f`.`SERIE_FAC` = `o`.`SERIE_FAC`)) */;
