/*!50001 VIEW `vi_caja_tarifa_sku_articulos` AS select `skus`.`CODIGO_UNIDAD_SKU` AS `CODIGO_UNIDAD_ARTTAR`,`skus`.`CODIGO_ART_SKU` AS `CODIGO_ART_ART`,`tarifas`.`CODIGO_TAR_ARTTAR` AS `CODIGO_TAR_ARTTAR`,`tarifas`.`NOMBRE_TAR_TAR` AS `NOMBRE_TAR_TAR`,coalesce(`tarifa_sku`.`PRECIO_FINAL_ARTTAR`,`tarifa_padre`.`PRECIO_FINAL_ARTTAR`) AS `PRECIO_FINAL_ARTTAR`,coalesce(`tarifa_sku`.`PRECIO_SALIDA_ARTTAR`,`tarifa_padre`.`PRECIO_SALIDA_ARTTAR`) AS `PRECIO_SALIDA_ARTTAR`,coalesce(`tarifa_sku`.`PORCENTAJE_DTO_ARTTAR`,`tarifa_padre`.`PORCENTAJE_DTO_ARTTAR`) AS `PORCENTAJE_DTO_ARTTAR`,coalesce(`tarifa_sku`.`PRECIO_DTO_ARTTAR`,`tarifa_padre`.`PRECIO_DTO_ARTTAR`) AS `PRECIO_DTO_ARTTAR`,case when `tarifa_sku`.`PRECIO_FINAL_ARTTAR` is not null then 'ESPECIFICO_SKU' else 'HEREDADO_PADRE' end AS `ORIGEN_PRECIO`,concat(`articulos`.`DESCRIPCION_ART`,' (',`skus`.`CODIGO_UNIDAD_SKU`,')') AS `DESCRIPCION_COMPLETA`,`tarifas`.`ESIMP_INCL_TAR` AS `ESIMP_INCL_TAR`,`articulos`.`TIPO_CANTIDAD_ART` AS `TIPO_CANTIDAD_ART`,`articulos`.`CODIGO_FAM_ART` AS `CODIGO_FAM_ART` from (((((`fza_articulos_skus` `skus` join `fza_articulos` `articulos` on(`skus`.`CODIGO_ART_SKU` = `articulos`.`CODIGO_ART_ART`)) join (select distinct `fza_articulos_tarifas`.`CODIGO_ART_ARTTAR` AS `CODIGO_ART_ARTTAR`,`fza_articulos_tarifas`.`CODIGO_TAR_ARTTAR` AS `CODIGO_TAR_ARTTAR` from `fza_articulos_tarifas`) `t_existentes` on(`t_existentes`.`CODIGO_ART_ARTTAR` = `articulos`.`CODIGO_ART_ART`)) join `fza_tarifas` `tarifas` on(`tarifas`.`CODIGO_TAR_ARTTAR` = `t_existentes`.`CODIGO_TAR_ARTTAR`)) left join `fza_articulos_tarifas` `tarifa_sku` on(`skus`.`CODIGO_UNIDAD_SKU` = `tarifa_sku`.`CODIGO_UNIDAD_ARTTAR` and `tarifas`.`CODIGO_TAR_ARTTAR` = `tarifa_sku`.`CODIGO_TAR_ARTTAR`)) left join `fza_articulos_tarifas` `tarifa_padre` on(`articulos`.`CODIGO_ART_ART` = `tarifa_padre`.`CODIGO_ART_ARTTAR` and `tarifas`.`CODIGO_TAR_ARTTAR` = `tarifa_padre`.`CODIGO_TAR_ARTTAR` and (`tarifa_padre`.`CODIGO_UNIDAD_ARTTAR` is null or `tarifa_padre`.`CODIGO_UNIDAD_ARTTAR` = ''))) where `skus`.`ESACTIVO_SKU` = 'S' and (`tarifa_sku`.`PRECIO_FINAL_ARTTAR` is not null or `tarifa_padre`.`PRECIO_FINAL_ARTTAR` is not null) order by `skus`.`CODIGO_ART_SKU`,`skus`.`CODIGO_UNIDAD_SKU`,`tarifas`.`ORDEN_TAR` */;
