` `ep458` where `ep458`.`ID_VAR_VA` = `sk458`.`CODIGO_VAR_SKU` and `ep458`.`EJE_VA` = 'P' limit 1) and !exists(select 1 from `vi_variaciones_ejes` `ej458` where `ej458`.`ID_VAR_VA` = `sk458`.`CODIGO_VAR_SKU` and `ej458`.`EJE_VA` = 'F' limit 1) limit 1) then '' else substring_index(substring_index(`l`.`CODIGO_UNIDAD_DEVCLIN`,'/',2),'/',-1) end),'') AS `COLOR_TEXTO`,coalesce(min(`sc`.`CODIGO_ATB_COLOR`),'') AS `CODIGO_ATB_COLOR`,avg(`l`.`PRECIO_COMPRA_SIVA_ARTICULO_DEVCLIN`) AS `PRECIO_COMPRA`,0 AS `PRECIO_VENTA`,`l`.`ID_AC_PIVOT_DEVCLIN` AS `ID_AC_PIVOT`,`ac`.`NOMBRE_AC` AS `NOMBRE_AC`,coalesce(`ac`.`NOMBRE_CORTO_AC`,ucase(left(`ac`.`NOMBRE_AC`,8))) AS `NOMBRE_CORTO_AC`,`l`.`CODIGO_ALMACEN_DEVCLIN` AS `CODIGO_ALM_DEVCLIN`,min(`alm`.`CODIGO_EMP_ALM`) AS `CODIGO_EMP_ALM_DEVCLIN`,min(`alm`.`NOMBRE_ALM_ALM`) AS `NOMBRE_ALM_DEVCLIN`,min(`alm`.`DIRECCION_ALM`) AS `DIRECCION_ALM_DEVCLIN`,min(`alm`.`CODIGO_POSTAL_ALM`) AS `CODIGO_POSTAL_ALM_DEVCLIN`,min(`alm`.`POBLACION_ALM`) AS `POBLACION_ALM_DEVCLIN`,min(`alm`.`PROVINCIA_ALM`) AS `PROVINCIA_ALM_DEVCLIN`,min(`alm`.`TELEFONO_ALM`) AS `TELEFONO_ALM_DEVCLIN`,min(`alm`.`EMAIL_ALM`) AS `EMAIL_ALM_DEVCLIN`,sum(`l`.`CANTIDAD_DEVCLIN`) AS `TOTAL_UNIDADES`,sum(`l`.`TOTAL_DEVCLIN`) AS `TOTAL_LINEA`,coalesce(sum(case when `p`.`POSICION` = 1 then `l`.`CANTIDAD_DEVCLIN` end),0) AS `T01`,coalesce(sum(case when `p`.`POSICION` = 2 then `l`.`CANTIDAD_DEVCLIN` end),0) AS `T02`,coalesce(sum(case when `p`.`POSICION` = 3 then `l`.`CANTIDAD_DEVCLIN` end),0) AS `T03`,coalesce(sum(case when `p`.`POSICION` = 4 then `l`.`CANTIDAD_DEVCLIN` end),0) AS `T04`,coalesce(sum(case when `p`.`POSICION` = 5 then `l`.`CANTIDAD_DEVCLIN` end),0) AS `T05`,coalesce(sum(case when `p`.`POSICION` = 6 then `l`.`CANTIDAD_DEVCLIN` end),0) AS `T06`,coalesce(sum(case when `p`.`POSICION` = 7 then `l`.`CANTIDAD_DEVCLIN` end),0) AS `T07`,coalesce(sum(case when `p`.`POSICION` = 8 then `l`.`CANTIDAD_DEVCLIN` end),0) AS `T08`,coalesce(sum(case when `p`.`POSICION` = 9 then `l`.`C