/*!50001 VIEW `vi_facturas_compra_lin_print` AS with POS_ACD as (select `fza_atributos_conjuntos_det`.`ID_AC_ACD` AS `ID_AC`,`fza_atributos_conjuntos_det`.`ID_AV_ACD` AS `ID_AV`,row_number() over ( partition by `fza_atributos_conjuntos_det`.`ID_AC_ACD` order by `fza_atributos_conjuntos_det`.`ORDEN_ACD`,`fza_atributos_conjuntos_det`.`ID_AV_ACD`) AS `POSICION` from `fza_atributos_conjuntos_det`), SKU_TALLA as (select `sa`.`CODIGO_UNIDAD_SKU_SA` AS `CODIGO_UNIDAD`,`sa`.`ID_AV_SA` AS `ID_AV_TALLA` from (`fza_atributos_sku` `sa` join `fza_atributos_valores` `av` on(`av`.`ID_AV` = `sa`.`ID_AV_SA` and `av`.`ID_VA_AV` = (select `ej452`.`ID_ATB_VA` from `vi_variaciones_ejes` `ej452` where `ej452`.`ID_VAR_VA` = (select `sk452`.`CODIGO_VAR_SKU` from `fza_articulos_skus` `sk452` where `sk452`.`CODIGO_UNIDAD_SKU` = `sa`.`CODIGO_UNIDAD_SKU_SA`) and `ej452`.`EJE_VA` = 'P')))), SKU_COLOR as (select `sa`.`CODIGO_UNIDAD_SKU_SA` AS `CODIGO_UNIDAD`,`atb`.`CODIGO_ATB` AS `CODIGO_ATB_COLOR`,coalesce(`atb`.`NOMBRE_ATB`,nullif(`av`.`AV`,'')) AS `NOMBRE_COLOR` from ((`fza_atributos_sku` `sa` join `fza_atributos_valores` `av` on(`av`.`ID_AV` = `sa`.`ID_AV_SA` and `av`.`ID_VA_AV` = (select `ej452`.`ID_ATB_VA` from `vi_variaciones_ejes` `ej452` where `ej452`.`ID_VAR_VA` = (select `sk452`.`CODIGO_VAR_SKU` from `fza_articulos_skus` `sk452` where `sk452`.`CODIGO_UNIDAD_SKU` = `sa`.`CODIGO_UNIDAD_SKU_SA`) and `ej452`.`EJE_VA` = 'F'))) left join `fza_atributos_basicos` `atb` on(`atb`.`ID_ATB` = `av`.`ID_ATB_AV`)))select `l`.`SERIE_FACC_FACCLIN` AS `SERIE_FACC`,`l`.`NUMERO_FACC_FACCLIN` AS `NUMERO_FACC`,min(`l`.`LINEA_FACCLIN`) AS `LINEA_FACC`,`l`.`CODIGO_ART_FACCLIN` AS `CODIGO_ART`,coalesce(min(`l`.`REF_PRV_FACCLIN`),'') AS `REF_PRV`,concat(coalesce(min(`l`.`DESCRIPCION_ARTICULO_FACCLIN`),''),case when coalesce(`l`.`LOTE_FACCLIN`,'') <> '' then concat(char(10),'Lote: ',`l`.`LOTE_FACCLIN`) else '' end,case when `l`.`FECHA_CADUCIDAD_FACCLIN` is not null then concat(' Cad.: ',date_format(`l`.`FECHA_CADUCIDAD_FACCLIN`,'%d/%m/%Y')) else '' end) AS `DESCRIPCION`,`l`.`TIPO_CANTIDAD_ARTICULO_FACCLIN` AS `TIPO_CANTIDAD`,min(`l`.`DESCRIPCION_ARTICULO_FACCLIN`) AS `DESCRIPCION_BASE`,`l`.`LOTE_FACCLIN` AS `LOTE`,`l`.`FECHA_CADUCIDAD_FACCLIN` AS `FECHA_CADUCIDAD`,coalesce(min(`sc`.`NOMBRE_COLOR`),min(case when exists(select 1 from `fza_articulos_skus` `sk458` where `sk458`.`CODIGO_UNIDAD_SKU` = `l`.`CODIGO_UNIDAD_FACCLIN` and exists(select 1 from `vi_variaciones_ejes` `ep458` where `ep458`.`ID_VAR_VA` = `sk458`.`CODIGO_VAR_SKU` and `ep458`.`EJE_VA` = 'P' limit 1) and !exists(select 1 from `vi_variaciones_ejes` `ej458` where `ej458`.`ID_VAR_VA` = `sk458`.`CODIGO_VAR_SKU` and `ej458`.`EJE_VA` = 'F' limit 1) limit 1) then '' else substring_index(substring_index(`l`.`CODIGO_UNIDAD_FACCLIN`,'/',2),'/',-1) end),'') AS `COLOR_TEXTO`,coalesce(min(`sc`.`CODIGO_ATB_COLOR`),'') AS `CODIGO_ATB_COLOR`,avg(`l`.`PRECIO_COMPRA_SIVA_ARTICULO_FACCLIN`) AS `PRECIO_COMPRA`,0 AS `PRECIO_VENTA`,`l`.`ID_AC_PIVOT_FACCLIN` AS `ID_AC_PIVOT`,`ac`.`NOMBRE_AC` AS `NOMBRE_AC`,coalesce(`ac`.`NOMBRE_CORTO_AC`,ucase(left(`ac`.`NOMBRE_AC`,8))) AS `NOMBRE_CORTO_AC`,`l`.`CODIGO_ALMACEN_FACCLIN` AS `CODIGO_ALM_FACCLIN`,min(`alm`.`CODIGO_EMP_ALM`) AS `CODIGO_EMP_ALM_FACCLIN`,min(`alm`.`NOMBRE_ALM_ALM`) AS `NOMBRE_ALM_FACCLIN`,min(`alm`.`DIRECCION_ALM`) AS `DIRECCION_ALM_FACCLIN`,min(`alm`.`CODIGO_POSTAL_ALM`) AS `CODIGO_POSTAL_ALM_FACCLIN`,min(`alm`.`POBLACION_ALM`) AS `POBLACION_ALM_FACCLIN`,min(`alm`.`PROVINCIA_ALM`) AS `PROVINCIA_ALM_FACCLIN`,min(`alm`.`TELEFONO_ALM`) AS `TELEFONO_ALM_FACCLIN`,min(`alm`.`EMAIL_ALM`) AS `EMAIL_ALM_FACCLIN`,sum(`l`.`CANTIDAD_FACCLIN`) AS `TOTAL_UNIDADES`,sum(`l`.`TOTAL_FACCLIN`) AS `TOTAL_LINEA`,coalesce(sum(case when `p`.`POSICION` = 1 then `l`.`CANTIDAD_FACCLIN` end),0) AS `T01`,coalesce(sum(case when `p`.`POSICION` = 2 then `l`.`CANTIDAD_FACCLIN` end),0) AS `T02`,coalesce(sum(case when `p`.`POSICION` = 3 then `l`.`CANTIDAD_FACCLIN` end),0) AS `T03`,coalesce(sum(case when `p`.`POSICION` = 4 then `l`.`CANTIDAD_FACCLIN` end),0) AS `T04`,coalesce(sum(case when `p`.`POSICION` = 5 then `l`.`CANTIDAD_FACCLIN` end),0) AS `T05`,coalesce(sum(case when `p`.`POSICION` = 6 then `l`.`CANTIDAD_FACCLIN` end),0) AS `T06`,coalesce(sum(case when `p`.`POSICION` = 7 then `l`.`CANTIDAD_FACCLIN` end),0) AS `T07`,coalesce(sum(case when `p`.`POSICION` = 8 then `l`.`CANTIDAD_FACCLIN` end),0) AS `T08`,coalesce(sum(case when `p`.`POSICION` = 9 then `l`.`CANTIDAD_FACCLIN` end),0) AS `T09`,coalesce(sum(case when `p`.`POSICION` = 10 then `l`.`CANTIDAD_FACCLIN` end),0) AS `T10`,coalesce(sum(case when `p`.`POSICION` = 11 then `l`.`CANTIDAD_FACCLIN` end),0) AS `T11`,coalesce(sum(case when `p`.`POSICION` = 12 then `l`.`CANTIDAD_FACCLIN` end),0) AS `T12`,coalesce(sum(case when `p`.`POSICION` = 13 then `l`.`CANTIDAD_FACCLIN` end),0) AS `T13`,coalesce(sum(case when `p`.`POSICION` = 14 then `l`.`CANTIDAD_FACCLIN` end),0) AS `T14`,coalesce(sum(case when `p`.`POSICION` = 15 then `l`.`CANTIDAD_FACCLIN` end),0) AS `T15`,coalesce(sum(case when `p`.`POSICION` = 16 then `l`.`CANTIDAD_FACCLIN` end),0) AS `T16`,coalesce(sum(case when `p`.`POSICION` = 17 then `l`.`CANTIDAD_FACCLIN` end),0) AS `T17`,coalesce(sum(case when `p`.`POSICION` = 18 then `l`.`CANTIDAD_FACCLIN` end),0) AS `T18`,coalesce(sum(case when `p`.`POSICION` = 19 then `l`.`CANTIDAD_FACCLIN` end),0) AS `T19`,coalesce(sum(case when `p`.`POSICION` = 20 then `l`.`CANTIDAD_FACCLIN` end),0) AS `T20`,coalesce(sum(case when `p`.`POSICION` = 21 then `l`.`CANTIDAD_FACCLIN` end),0) AS `T21` from (((((`fza_facturas_compra_lineas` `l` left join `fza_atributos_conjuntos` `ac` on(`ac`.`ID_AC` = `l`.`ID_AC_PIVOT_FACCLIN`)) left join `sku_talla` `st` on(`st`.`CODIGO_UNIDAD` = `l`.`CODIGO_UNIDAD_FACCLIN`)) left join `pos_acd` `p` on(`p`.`ID_AC` = `l`.`ID_AC_PIVOT_FACCLIN` and `p`.`ID_AV` = `st`.`ID_AV_TALLA`)) left join `sku_color` `sc` on(`sc`.`CODIGO_UNIDAD` = `l`.`CODIGO_UNIDAD_FACCLIN`)) left join `fza_almacenes` `alm` on(`alm`.`CODIGO_ALM_ALM` = `l`.`CODIGO_ALMACEN_FACCLIN`)) group by `l`.`SERIE_FACC_FACCLIN`,`l`.`NUMERO_FACC_FACCLIN`,`l`.`CODIGO_ART_FACCLIN`,`l`.`ID_AC_PIVOT_FACCLIN`,`ac`.`NOMBRE_AC`,`ac`.`NOMBRE_CORTO_AC`,`sc`.`CODIGO_ATB_COLOR`,`sc`.`NOMBRE_COLOR`,case when exists(select 1 from `fza_articulos_skus` `sk458` where `sk458`.`CODIGO_UNIDAD_SKU` = `l`.`CODIGO_UNIDAD_FACCLIN` and exists(select 1 from `vi_variaciones_ejes` `ep458` where `ep458`.`ID_VAR_VA` = `sk458`.`CODIGO_VAR_SKU` and `ep458`.`EJE_VA` = 'P' limit 1) and !exists(select 1 from `vi_variaciones_ejes` `ej458` where `ej458`.`ID_VAR_VA` = `sk458`.`CODIGO_VAR_SKU` and `ej458`.`EJE_VA` = 'F' limit 1) limit 1) then '' else substring_index(substring_index(`l`.`CODIGO_UNIDAD_FACCLIN`,'/',2),'/',-1) end,`l`.`CODIGO_ALMACEN_FACCLIN`,`l`.`TIPO_CANTIDAD_ARTICULO_FACCLIN`,`l`.`LOTE_FACCLIN`,`l`.`FECHA_CADUCIDAD_FACCLIN` */;
