/*!50001 VIEW `vi_ses_preview_skus` AS select `l`.`SERIE_SES_SESLIN` AS `SERIE`,`l`.`NUMERO_SES_SESLIN` AS `NUMERO`,`l`.`LINEA_SESLIN` AS `LINEA`,`l`.`CODIGO_ART_TENTATIVO_SESLIN` AS `CODIGO_ART`,`l`.`DESCRIPCION_SESLIN` AS `DESCRIPCION`,`c`.`ID_FILA_SES_SESCEL` AS `ID_FILA`,`c`.`ID_AV_PIVOT_SESCEL` AS `ID_AV_PIVOT`,`avp`.`AV` AS `VALOR_PIVOT`,if(`c`.`CODIGO_ALM_SESCEL` = '',`s`.`CODIGO_ALM_SES`,`c`.`CODIGO_ALM_SESCEL`) AS `CODIGO_ALM`,`c`.`CANTIDAD_SESCEL` AS `CANTIDAD`,`l`.`PRECIO_COMPRA_SESLIN` AS `PRECIO_COMPRA`,`l`.`PRECIO_VENTA_SESLIN` AS `PRECIO_VENTA` from (((`fza_compras_sesiones_lineas` `l` join `fza_compras_sesiones` `s` on(`s`.`SERIE_SES` = `l`.`SERIE_SES_SESLIN` and `s`.`NUMERO_SES` = `l`.`NUMERO_SES_SESLIN`)) join `fza_compras_sesiones_celdas` `c` on(`c`.`SERIE_SES_SESCEL` = `l`.`SERIE_SES_SESLIN` and `c`.`NUMERO_SES_SESCEL` = `l`.`NUMERO_SES_SESLIN` and `c`.`LINEA_SES_SESCEL` = `l`.`LINEA_SESLIN`)) join `fza_atributos_valores` `avp` on(`avp`.`ID_AV` = `c`.`ID_AV_PIVOT_SESCEL`)) where `c`.`CANTIDAD_SESCEL` > 0 */;
