/*!50001 VIEW `vi_traspasos_pendientes` AS select 'SOLICITUD' AS `TIPO_PENDIENTE`,concat(`s`.`SERIE_TRSOL`,'/',`s`.`NUMERO_TRSOL`) AS `DOCUMENTO_PENDIENTE`,`s`.`CODIGO_ALM_ORIGEN_TRSOL` AS `CODIGO_ALM_ORIGEN`,`s`.`CODIGO_ALM_DESTINO_TRSOL` AS `CODIGO_ALM_DESTINO`,`l`.`CODIGO_UNIDAD_TRSOLLIN` AS `CODIGO_UNIDAD_SKU`,`l`.`CANTIDAD_PEDIDA_TRSOLLIN` - `l`.`CANTIDAD_SERVIDA_TRSOLLIN` AS `CANTIDAD_PENDIENTE` from (`fza_traspasos_solicitudes` `s` join `fza_traspasos_solicitudes_lineas` `l` on(`l`.`NUMERO_TRSOL_TRSOLLIN` = `s`.`NUMERO_TRSOL` and `l`.`SERIE_TRSOL_TRSOLLIN` = `s`.`SERIE_TRSOL`)) where `s`.`TIPO_TRSOL` = 'MANUAL' and `s`.`ESTADO_TRSOL` = 'PENDIENTE' and coalesce(`l`.`ESATENDIDA_TRSOLLIN`,'N') <> 'S' and `l`.`CANTIDAD_PEDIDA_TRSOLLIN` > `l`.`CANTIDAD_SERVIDA_TRSOLLIN` union all select 'PROPUESTA' AS `PROPUESTA`,cast(`p`.`ID_TRPRO` as char(20) charset utf8mb4) collate utf8mb4_spanish_ci AS `Name_exp_2`,`p`.`CODIGO_ALM_ORIGEN_TRPRO` AS `CODIGO_ALM_ORIGEN_TRPRO`,`p`.`CODIGO_ALM_DESTINO_TRPRO` AS `CODIGO_ALM_DESTINO_TRPRO`,`pl`.`CODIGO_UNIDAD_TRPROLIN` AS `CODIGO_UNIDAD_TRPROLIN`,`pl`.`CANTIDAD_TRPROLIN` AS `CANTIDAD_TRPROLIN` from (`fza_traspasos_propuestas` `p` join `fza_traspasos_propuestas_lineas` `pl` on(`pl`.`ID_TRPRO_TRPROLIN` = `p`.`ID_TRPRO`)) where `p`.`ESTADO_TRPRO` = 'PENDIENTE' and `pl`.`CANTIDAD_TRPROLIN` > 0 union all select 'TRANSITO' AS `TRANSITO`,concat(`t`.`SERIE_CARGA_TRTRA`,'/',`t`.`NUMERO_CARGA_TRTRA`) AS `CONCAT(T.``SERIE_CARGA_TRTRA``, '/', T.``NUMERO_CARGA_TRTRA``)`,`t`.`CODIGO_ALM_TRANSITO_TRTRA` AS `CODIGO_ALM_TRANSITO_TRTRA`,`t`.`CODIGO_ALM_DESTINO_TRTRA` AS `CODIGO_ALM_DESTINO_TRTRA`,`m`.`CODIGO_UNIDAD_MOV` AS `CODIGO_UNIDAD_MOV`,sum(`m`.`CANTIDAD_MOV`) AS `SUM(M.``CANTIDAD_MOV``)` from (`fza_traspasos_transito` `t` join `fza_movimientos_almacen` `m` on(`m`.`TIPO_DOC_MOV` = `t`.`TIPO_DOC_CARGA_TRTRA` and `m`.`SERIE_DOC_MOV` = `t`.`SERIE_CARGA_TRTRA` and `m`.`NUMERO_DOC_MOV` = `t`.`NUMERO_CARGA_TRTRA` and `m`.`CODIGO_ALM_MOV` = `t`.`CODIGO_ALM_TRANSITO_TRTRA` and `m`.`TIPO_MOV` = 'E')) where `t`.`ESTADO_TRTRA` = 'PENDIENTE' group by `t`.`ID_TRTRA`,`t`.`SERIE_CARGA_TRTRA`,`t`.`NUMERO_CARGA_TRTRA`,`t`.`CODIGO_ALM_TRANSITO_TRTRA`,`t`.`CODIGO_ALM_DESTINO_TRTRA`,`m`.`CODIGO_UNIDAD_MOV` */;
