/*!50001 VIEW `vi_variaciones_ejes` AS select `va`.`ID_VAR_VA` AS `ID_VAR_VA`,`va`.`ID_ATB_VA` AS `ID_ATB_VA`,case when !exists(select 1 from `fza_variaciones_atributos` `u` where `u`.`ID_VAR_VA` = `va`.`ID_VAR_VA` and (coalesce(`u`.`ORDEN_VA`,0) > coalesce(`va`.`ORDEN_VA`,0) or coalesce(`u`.`ORDEN_VA`,0) = coalesce(`va`.`ORDEN_VA`,0) and `u`.`ID_ATB_VA` > `va`.`ID_ATB_VA`) limit 1) then 'P' when !exists(select 1 from `fza_variaciones_atributos` `u` where `u`.`ID_VAR_VA` = `va`.`ID_VAR_VA` and (coalesce(`u`.`ORDEN_VA`,0) < coalesce(`va`.`ORDEN_VA`,0) or coalesce(`u`.`ORDEN_VA`,0) = coalesce(`va`.`ORDEN_VA`,0) and `u`.`ID_ATB_VA` < `va`.`ID_ATB_VA`) limit 1) then 'F' when `va`.`EJE_VA` = 'S' and !exists(select 1 from `fza_variaciones_atributos` `s` where `s`.`ID_VAR_VA` = `va`.`ID_VAR_VA` and `s`.`EJE_VA` = 'S' and (coalesce(`s`.`ORDEN_VA`,0) < coalesce(`va`.`ORDEN_VA`,0) or coalesce(`s`.`ORDEN_VA`,0) = coalesce(`va`.`ORDEN_VA`,0) and `s`.`ID_ATB_VA` < `va`.`ID_ATB_VA`) and exists(select 1 from `fza_variaciones_atributos` `a` where `a`.`ID_VAR_VA` = `s`.`ID_VAR_VA` and (coalesce(`a`.`ORDEN_VA`,0) < coalesce(`s`.`ORDEN_VA`,0) or coalesce(`a`.`ORDEN_VA`,0) = coalesce(`s`.`ORDEN_VA`,0) and `a`.`ID_ATB_VA` < `s`.`ID_ATB_VA`) limit 1) limit 1) then 'S' else '' end collate utf8mb4_spanish_ci AS `EJE_VA` from `fza_variaciones_atributos` `va` */;
